import { loadBluprint, rootOf } from "@/lib/server/bluprints";
import { reviewRange } from "@/lib/server/review";
import { bluprintReview, reviewBluprint } from "@/lib/server/vault";
import { notJson } from "@/lib/server/route";

/**
 * The bluprint after a branch or pull request (lib/server/vault.ts `bluprintReview`):
 * `GET ?bluprint=&commit=` says whether it exists or is being made (only read, so
 * a commit is enough), `POST` with `{bluprint, review, claude}` starts making it.
 * As app/api/diff/route.ts, what is checked out is only ever the commit the
 * review spec itself resolves to.
 */
function resolved(bluprint: string | null, spec: string | null) {
  let open: ReturnType<typeof loadBluprint> = null;
  try {
    open = loadBluprint(bluprint ?? undefined);
  } catch {}
  if (!open || !spec) return { error: "No such bluprint or review." };
  const r = reviewRange(rootOf(open.file.RUN), spec);
  return "error" in r ? r : { id: open.name, commit: r.to };
}

export async function GET(request: Request) {
  const q = new URL(request.url).searchParams;
  let open: ReturnType<typeof loadBluprint> = null;
  try {
    open = loadBluprint(q.get("bluprint") ?? undefined);
  } catch {}
  return Response.json(open ? reviewBluprint(open.name, q.get("commit") ?? "") : { status: "none" });
}

export async function POST(request: Request) {
  const refused = notJson(request);
  if (refused) return refused;
  const body = (await request.json().catch(() => ({}))) as { bluprint?: string; review?: string; claude?: string };
  const r = resolved(body.bluprint ?? null, body.review ?? null);
  if ("error" in r) return Response.json({ status: "failed", error: r.error });
  return Response.json(bluprintReview(r.id, r.commit, body.claude));
}

app/app/api/source/route.ts:
import { readSlice, writeSlice, Refused } from "@/lib/server/repo";
import { demoSource, loadBluprint, rootOf } from "@/lib/server/bluprints";
import { sliceOf } from "@/lib/bluprint/source";
import { notJson } from "@/lib/server/route";

/** The checkout behind the bluprint the reader has open (`?bluprint=`); null with no project yet. */
const rootFor = (bluprint: string | null | undefined) => {
  const open = loadBluprint(bluprint ?? undefined);
  return open ? rootOf(open.file.RUN) : null;
};

/**
 * The only door to the real repository.
 *
 * GET reads a slice; POST writes one back. Both take caller-supplied paths, so
 * both go through the same containment check in `lib/server/repo.ts` — that check is
 * the whole security model and neither handler is allowed its own version of
 * it.
 *
 * Refusals are 400 with a plain message. A refused path never gets a different
 * status or a different body from a path that exists and is out of bounds:
 * probing for what is on the filesystem should learn nothing.
 */

function bad(message: string) {
  return Response.json({ refused: message }, { status: 400 });
}

export async function GET(request: Request) {
  const q = new URL(request.url).searchParams;
  const file = q.get("file");
  const start = Number(q.get("start"));
  const end = Number(q.get("end"));
  if (!file || !Number.isInteger(start) || !Number.isInteger(end)) {
    return bad("bad request");
  }

  const fixture = q.get("fixture") ?? undefined;
  // A landing demo reads the code its bluprint was made from, committed beside it (D63).
  const demo = demoSource(q.get("bluprint") ?? undefined);
  if (demo) {
    const text = demo[file];
    return text === undefined ? bad("unreadable") : Response.json(sliceOf(text, { file, start, end, fixture }));
  }
  const root = rootFor(q.get("bluprint"));
  if (!root) return bad("unreadable");
  try {
    // `fixture` is the text the bluprint claims is at these lines. Passing it is
    // what lets the answer say "this has drifted" instead of quietly showing
    // fresh code under a stale explanation.
    return Response.json(await readSlice({ file, start, end }, fixture, root));
  } catch (e) {
    return bad(e instanceof Refused ? e.message : "unreadable");
  }
}

export async function POST(request: Request) {
  // JSON only: a cross-site form can send text/plain with no preflight.
  const refused = notJson(request);
  if (refused) return refused;
  const body = await request.json().catch(() => null);
  const { file, start, end, code, expected, bluprint } = body ?? {};
  if (
    typeof file !== "string" ||
    !Number.isInteger(start) ||
    !Number.isInteger(end) ||
    typeof code !== "string" ||
    typeof expected !== "string"
  ) {
    return bad("bad request");
  }

  const root = rootFor(typeof bluprint === "string" ? bluprint : null);
  if (!root) return bad("unreadable");
  const result = await writeSlice({ file, start, end, code, expected }, root);
  return Response.json(result, { status: result.ok ? 200 : 409 });
}

