import { listBluprints, loadDemo, loadBluprint, remoteOf, rootOf } from "@/lib/server/bluprints";
import { ClaudeWeb } from "@/components/agent/claude-web";
import { STATIC_BLUPRINT } from "@/lib/bluprint/source";
