"use client";

import { invoke } from "@tauri-apps/api/core";
import { useEffect, useState } from "react";
import { useSettings } from "@/lib/client/settings";
import { cn } from "@/lib/client/utils";
import { findClaude } from "@/lib/client/claude";

/**
 * The coding agents a workspace tab can start, and how each is drawn.
 *
 * Claude goes through the app's launcher, `bluprint-claude`, so it can take bluprint
 * context (src-tauri/src/claude.rs); the others start as the user's own CLI,
 * typed into the shell. Logos come from Simple Icons (CC0) where it has one;
 * an agent without one gets the terminal glyph. Adding an agent is one entry.
 */

export interface Agent {
  id: string;
  /** What the menu and the strip call it. */
  label: string;
  /** What is typed into the shell to start it. */
  command: string;
}

export const CLAUDE: Agent = { id: "claude", label: "Claude Code", command: "bluprint-claude" };

/** Every other agent, shown when installed. */
const AGENTS: Agent[] = [
  { id: "codex", label: "Codex", command: "codex" },
  { id: "opencode", label: "OpenCode", command: "opencode" },
  { id: "pi", label: "Pi", command: "pi" },
];

export const agentById = (id: string | undefined) => (id === CLAUDE.id ? CLAUDE : AGENTS.find((a) => a.id === id));

/* ── icons ────────────────────────────────────────────────────── */

/** Simple Icons paths, on a 24 grid. */
export const LOGOS: Record<string, { d: string; color?: string }> = {
  claude: {
    color: "#D97757",
    d: "m4.7144 15.9555 4.7174-2.6471.079-.2307-.079-.1275h-.2307l-.7893-.0486-2.6956-.0729-2.3375-.0971-2.2646-.1214-.5707-.1215-.5343-.7042.0546-.3522.4797-.3218.686.0608 1.5179.1032 2.2767.1578 1.6514.0972 2.4468.255h.3886l.0546-.1579-.1336-.0971-.1032-.0972L6.973 9.8356l-2.55-1.6879-1.3356-.9714-.7225-.4918-.3643-.4614-.1578-1.0078.6557-.7225.8803.0607.2246.0607.8925.686 1.9064 1.4754 2.4893 1.8336.3643.3035.1457-.1032.0182-.0728-.164-.2733-1.3539-2.4467-1.445-2.4893-.6435-1.032-.17-.6194c-.0607-.255-.1032-.4674-.1032-.7285L6.287.1335 6.6997 0l.9957.1336.419.3642.6192 1.4147 1.0018 2.2282 1.5543 3.0296.4553.8985.2429.8318.091.255h.1579v-.1457l.1275-1.706.2368-2.0947.2307-2.6957.0789-.7589.3764-.9107.7468-.4918.5828.2793.4797.686-.0668.4433-.2853 1.8517-.5586 2.9021-.3643 1.9429h.2125l.2429-.2429.9835-1.3053 1.6514-2.0643.7286-.8196.85-.9046.5464-.4311h1.0321l.759 1.1293-.34 1.1657-1.0625 1.3478-.8804 1.1414-1.2628 1.7-.7893 1.36.0729.1093.1882-.0183 2.8535-.607 1.5421-.2794 1.8396-.3157.8318.3886.091.3946-.3278.8075-1.967.4857-2.3072.4614-3.4364.8136-.0425.0304.0486.0607 1.5482.1457.6618.0364h1.621l3.0175.2247.7892.522.4736.6376-.079.4857-1.2142.6193-1.6393-.3886-3.825-.9107-1.3113-.3279h-.1822v.1093l1.0929 1.0686 2.0035 1.8092 2.5075 2.3314.1275.5768-.3218.4554-.34-.0486-2.2039-1.6575-.85-.7468-1.9246-1.621h-.1275v.17l.4432.6496 2.3436 3.5214.1214 1.0807-.17.3521-.6071.2125-.6679-.1214-1.3721-1.9246L14.38 17.959l-1.1414-1.9428-.1397.079-.674 7.2552-.3156.3703-.7286.2793-.6071-.4614-.3218-.7468.3218-1.4753.3886-1.9246.3157-1.53.2853-1.9004.17-.6314-.0121-.0425-.1397.0182-1.4328 1.9672-2.1796 2.9446-1.7243 1.8456-.4128.164-.7164-.3704.0667-.6618.4008-.5889 2.386-3.0357 1.4389-1.882.929-1.0868-.0062-.1579h-.0546l-6.3385 4.1164-1.1293.1457-.4857-.4554.0608-.7467.2307-.2429 1.9064-1.3114Z",
  },
  opencode: { d: "M22 24H2V0h20zM17 4.8H7v14.4h10z" },
  // Pi's mark from pi.dev, scaled from its 800 grid.
  pi: { d: "M4.959 4.959H15.521V12H12V8.48H4.959ZM4.959 8.48H8.48V12H12V15.521H8.48V19.042H4.959ZM15.521 12H19.042V19.042H15.521Z" },
};

/** The terminal glyph, as on the title bar's button, for a shell or an agent with no logo. */
export function TerminalIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.4"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      className={cn("size-3 shrink-0", className)}
    >
      <rect x="1.5" y="2.5" width="13" height="11" rx="2" />
      <path d="M4.5 6.5 6.5 8l-2 1.5M8.5 10h3" />
    </svg>
  );
}

export function AgentIcon({ id, className }: { id: string | undefined; className?: string }) {
  const logo = id ? LOGOS[id] : undefined;
  if (!logo) return <TerminalIcon className={className} />;
  return (
    <svg
      viewBox="0 0 24 24"
      fill={logo.color ?? "currentColor"}
      aria-hidden
      className={cn("size-3 shrink-0", className)}
    >
      <path d={logo.d} />
    </svg>
  );
}

/* ── what is installed ────────────────────────────────────────── */

/** Which of AGENTS the user's shell can run, asked once per session of the app. */
let installed: Promise<string[]> | null = null;

export function useInstalled(): Agent[] {
  const [names, setNames] = useState<string[]>([]);
  useEffect(() => {
    installed ??= invoke<string[]>("pty_which", { names: AGENTS.map((a) => a.command) }).catch(() => []);
    let live = true;
    void installed.then((n) => live && setNames(n));
    return () => {
      live = false;
    };
  }, []);
  return AGENTS.filter((a) => names.includes(a.command));
}

/** Whether Claude Code was found, where Settings says or wherever it is installed; unknown while looking. */
function useClaudeFound(): boolean | undefined {
  const [found, setFound] = useState<boolean>();
  useEffect(() => {
    let live = true;
    void findClaude().then((f) => live && setFound(!!f));
    return () => {
      live = false;
    };
  }, []);
  return found;
}

/**
 * The agents this machine has — Claude unless it was looked for and missed —
 * and the one Settings names as the default, while it is installed; else
 * Claude, as it always was.
 */
export function useAgents(): { agents: Agent[]; main: Agent; others: Agent[] } {
  const others = useInstalled();
  const claudeFound = useClaudeFound();
  const preferred = useSettings().agent;
  const agents = [...(claudeFound === false ? [] : [CLAUDE]), ...others];
  return { agents, others, main: agents.find((a) => a.id === preferred) ?? CLAUDE };
}

app/components/agent/file-tab.tsx:
"use client";

import { invoke } from "@tauri-apps/api/core";
import { useEffect, useState } from "react";
import { CodeEditor } from "@/components/ui/editor";
import { MarkdownEditor } from "@/components/ui/markdown-editor";
import { keys } from "@/components/ui/button";
import { langOf } from "@/lib/client/highlight";
import { cn } from "@/lib/client/utils";
import { useMac } from "@/lib/client/platform";

/**
 * A file a terminal named (components/agent/shell.tsx), open in the main view as an
 * editor tab: a breadcrumb over the path, the code pane's editor with its
 * gutter, and a status line. Any file on disk, read and written through the
 * desktop app (src-tauri/src/files.rs) rather than the bluprint's `/api/source`,
 * since agents name files outside the project and Claude's pasted images.
 */

const MARKDOWN = /\.(md|mdx|markdown)$/i;
const IMAGE = /\.(png|jpe?g|gif|webp|bmp|ico|svg)$/i;
/** Past this the editor's one-div-per-line drawing gets slow; such a file is named, not drawn. */
const TOO_BIG = 2_000_000;

type Read =
  | { kind: "text"; text: string }
  | { kind: "image"; url: string; bytes: number }
  | { kind: "other"; why: string };

const LANG: Record<string, string> = { c: "Code", python: "Python", sql: "SQL", markup: "Markup", plain: "Plain text" };

export function FileTab({ path, line, visible, inset }: { path: string; line?: number; visible: boolean; inset?: string }) {
  const [read, setRead] = useState<Read | null>(null);
  const [draft, setDraft] = useState<string | null>(null);
  const [saved, setSaved] = useState<"saved" | string | null>(null);
  const [size, setSize] = useState<{ w: number; h: number } | null>(null);
  const [source, setSource] = useState(false);
  const md = MARKDOWN.test(path);
  const mac = useMac();

  const load = () =>
    invoke<ArrayBuffer>("file_read", { path }).then((buf): Read => {
      if (IMAGE.test(path)) {
        const type = path.toLowerCase().endsWith(".svg") ? "image/svg+xml" : "";
        return { kind: "image", url: URL.createObjectURL(new Blob([buf], type ? { type } : {})), bytes: buf.byteLength };
      }
      if (buf.byteLength > TOO_BIG) return { kind: "other", why: `Too large to open here (${(buf.byteLength / 1e6).toFixed(1)} MB).` };
      try {
        return { kind: "text", text: new TextDecoder("utf-8", { fatal: true }).decode(buf) };
      } catch {
        return { kind: "other", why: "A binary file: nothing here to read as text." };
      }
    });

  useEffect(() => {
    let gone = false;
    let url: string | undefined;
    load()
      .catch((e): Read => ({ kind: "other", why: `Could not read it: ${String(e)}` }))
      .then((r) => {
        if (r.kind === "image") url = r.url;
        if (gone) return;
        setRead(r);
        setDraft(null);
      });
    return () => {
      gone = true;
      if (url) URL.revokeObjectURL(url);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [path]);

  const text = read?.kind === "text" ? read.text : "";
  const dirty = draft !== null && draft !== text;

  async function save() {
    if (!dirty || read?.kind !== "text") return;
    try {
      await invoke("file_write", { path, text: draft, expected: text });
      setRead({ kind: "text", text: draft! });
      setDraft(null);
      setSaved("saved");
    } catch (e) {
      setSaved(String(e) === "stale" ? "it changed on disk since it was opened. Reopen it to get the current text." : String(e));
    }
  }

  const home = path.match(/^\/Users\/[^/]+|^\/home\/[^/]+/)?.[0];
  const crumbs = (home ? `~${path.slice(home.length)}` : path).split("/").filter(Boolean);
  const name = crumbs.at(-1) ?? path;

  return (
    <div data-chrome className={cn("absolute inset-0 flex flex-col bg-code", !visible && "hidden")} style={{ paddingRight: inset }}>
      <div className="flex h-7 shrink-0 items-center gap-1 overflow-x-auto border-b border-border-gray px-4 font-mono text-[11.5px] text-faint" title={path}>
        {crumbs.map((c, i) => (
          <span key={i} className="flex shrink-0 items-center gap-1">
            {i > 0 ? <span aria-hidden>›</span> : null}
            <span className={cn(i === crumbs.length - 1 && "text-ink")}>{c}</span>
          </span>
        ))}
        {dirty ? <span aria-label="Unsaved changes" className="ml-1.5 size-2 shrink-0 rounded-full bg-ink" /> : null}
      </div>

      <div className="relative min-h-0 flex-1">
        {read === null ? <p className="p-4 text-[12.5px] text-faint">Reading…</p> : null}
        {read?.kind === "other" ? <p className="p-4 text-[12.5px] text-muted-slate">{read.why}</p> : null}
        {read?.kind === "image" ? (
          <div className="absolute inset-0 flex items-center justify-center overflow-auto p-6">
            {/* eslint-disable-next-line @next/next/no-img-element -- a local blob, not a page asset */}
            <img
              src={read.url}
              alt={name}
              onLoad={(e) => setSize({ w: e.currentTarget.naturalWidth, h: e.currentTarget.naturalHeight })}
              className="max-h-full max-w-full object-contain shadow-[0_0_0_1px_var(--color-border-gray)]"
            />
          </div>
        ) : null}
        {read?.kind === "text" && md && !source ? (
          <MarkdownEditor
            key={path}
            file={path}
            value={draft ?? text}
            onChange={(next) => (setDraft(next), setSaved(null))}
            onSave={() => void save()}
            lit={line}
            className="absolute inset-0"
          />
        ) : read?.kind === "text" ? (
          <CodeEditor
            key={path}
            file={path}
            start={1}
            value={draft ?? text}
            onChange={(next) => (setDraft(next), setSaved(null))}
            onSave={() => void save()}
            lit={line}
            className="absolute inset-0"
          />
        ) : null}
      </div>

      <div className="flex h-6 shrink-0 items-center gap-4 border-t border-border-gray px-4 font-mono text-[11px] text-faint">
        {read?.kind === "text" ? (
          <>
            {line ? <span>Ln {line}</span> : null}
            <span className="tnum">{(draft ?? text).split("\n").length.toLocaleString()} lines</span>
            {md ? (
              <button type="button" onClick={() => setSource((v) => !v)} className="cursor-pointer hover:text-ink" title="Switch between the drawn page and its Markdown">
                {source ? "Markdown source · show page" : "Live preview · show source"}
              </button>
            ) : (
              <span>{LANG[langOf(path)]}</span>
            )}
            <span>UTF-8</span>
            <span className="ml-auto">
              {saved && saved !== "saved" ? (
                <span className="text-clay-ink">Not saved: {saved}</span>
              ) : dirty ? (
                `${keys(mac, "S")} to save`
              ) : saved === "saved" ? (
                "Saved"
              ) : null}
            </span>
          </>
        ) : read?.kind === "image" ? (
          <>
            {size ? <span className="tnum">{size.w} × {size.h}</span> : null}
            <span className="tnum">{(read.bytes / 1024).toFixed(0)} KB</span>
          </>
        ) : null}
      </div>
    </div>
  );
}

