/**
 * A plan Claude wrote in plan mode, as a short design doc in a tab of its own
 * (components/agent/workspace.tsx), so it is read rather than scrolled past in the
 * terminal: a title and two sentences, then a few short sections, pictures
 * among them only where the plan needs one, and its Steps ticked off as
 * Claude builds it. A diagram is drawn the way the bluprint draws a diff (components/review/diff.tsx) —
 * a plan is a diff that has not happened yet — so what it adds is green, what
 * it changes amber and what it removes red, against the parts it leaves alone.
 *
 * It is accepted from here. Claude Code still asks in its terminal, and the
 * buttons at the foot are that question's own answers, read off the screen
 * and pressed there (lib/agent/plan.ts): answering in either place is the same.
 */

export interface Plan {
  text: string;
  file: string | null;
  /** 1 for the first plan in this tab, counting up as Claude revises it. */
  version: number;
  /** Waiting on the user, accepted, or sent back with what to change. */
  state: "open" | "approved" | "revising";
  /** When it was approved (ms), so what was built after it can be told from what came before. */
  approvedAt?: number;
  /** What the user asked to change, while Claude revises. */
  asked?: string;
  /** What the user asked for that this revision answers. */
  after?: string;
  /** Its steps as Claude marks them while it builds the plan (src-tauri/src/claude.rs, bluprint-plan-step). */
  steps?: StepMark[];
}

export interface StepMark {
  n: number;
  state: "doing" | "done" | "skipped";
  note: string | null;
}



/** The question's answers while Claude Code is asking it; polled, since it is drawn by another program. */
function useChoices(read: () => string[], on: boolean) {
  const [choices, setChoices] = useState<Choice[] | null>(null);
  const reader = useRef(read);
  useEffect(() => {
    reader.current = read;
  });
  useEffect(() => {
    if (!on) return;
    const tick = () => {
      const next = planChoices(reader.current());
      setChoices((was) => (JSON.stringify(was) === JSON.stringify(next) ? was : next));
    };
    const first = setTimeout(tick, 0);
    const timer = setInterval(tick, 400);
    return () => {
      clearTimeout(first);
      clearInterval(timer);
    };
  }, [on]);
  return on ? choices : null;
}

export function PlanView({
  plan,
  visible,
  status,
  pty,
  read,
  onAnswered,
  onShowClaude,
  inset,
}: {
  plan: Plan;
  visible: boolean;
  /** What the Claude that wrote it is doing. */
  status?: Status;
  /** That Claude's terminal; gone once its tab is closed. */
  pty?: number;
  /** Its screen, line by line (components/agent/shell.tsx). */
  read: () => string[];
  onAnswered: (next: Pick<Plan, "state" | "asked">) => void;
  onShowClaude?: () => void;
  /** Room kept on the right for the workspace window floating over the main view. */
  inset?: string;
}) {
  const doc = useMemo(() => parsePlan(plan.text), [plan.text]);
  // Not read while the tab is out of sight: it is the terminal's whole screen, every 400ms.
  const choices = useChoices(read, visible && plan.state !== "approved" && pty !== undefined);
  const [words, setWords] = useState("");
  const top = useRef<HTMLDivElement>(null);

  // A revised plan is read from its top.
  useEffect(() => {
    top.current?.scrollTo({ top: 0 });
  }, [plan.version]);

  const answer = async (c: Choice) => {
    if (pty === undefined) return;
    // Asked again at the moment of pressing: a key must never land in a
    // prompt that has moved on to something else.
    if (!planChoices(read())?.some((x) => x.n === c.n && x.input === c.input)) return;
    const said = words.replace(/\s*\n\s*/g, " ").trim();
    if (c.input && !said) return;
    await invoke("pty_write", { id: pty, data: String(c.n) });
    if (c.input) {
      // Its number opens the field; the words go in once it has.
      await sleep(250);
      await invoke("pty_write", { id: pty, data: said });
      await sleep(150);
      await invoke("pty_write", { id: pty, data: "\r" });
      setWords("");
    }
    onAnswered(c.input ? { state: "revising", asked: said } : { state: "approved" });
  };

  const { added, changed, removed } = doc.files;
  const yes = choices?.filter((c) => !c.input) ?? [];
  const change = choices?.find((c) => c.input);

  return (
    <div ref={top} className={cn("absolute inset-0 flex flex-col overflow-y-auto bg-paper", !visible && "hidden")} style={{ paddingRight: inset }}>
      <article className="mx-auto w-full max-w-[920px] flex-1 px-10 pb-16 pt-9">
        <header className="mb-9">
          <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
            <Eyebrow className="text-accent">{plan.version > 1 ? `Plan · revision ${plan.version}` : "Plan"}</Eyebrow>
            <span className="flex flex-wrap items-center gap-x-3 font-mono text-[11px] text-faint">
              {doc.steps ? (
                <span className="tnum">
                  {plan.steps?.length ? `${plan.steps.filter((s) => s.state === "done").length} of ${doc.steps} steps done` : `${doc.steps} steps`}
                </span>
              ) : null}
              {added + changed + removed ? (
                <span className="tnum">
                  {added + changed + removed} {added + changed + removed === 1 ? "file" : "files"}
                  {(["added", "changed", "removed"] as const).map((v) =>
                    doc.files[v] ? (
                      <span key={v} className="ml-1.5 font-semibold" style={{ color: TINT[v].ink }}>
                        {TINT[v].mark}
                        {doc.files[v]}
                      </span>
                    ) : null,
                  )}
                </span>
              ) : null}
              <span className="tnum">{doc.minutes} min read</span>
            </span>
            {plan.after ? (
              <span className="min-w-0 truncate text-[12px] text-muted-slate" title={plan.after}>
                for “{plan.after}”
              </span>
            ) : null}
          </div>
          <h1 className="mt-2.5 font-display text-[clamp(32px,3.2vw,46px)] font-normal leading-[1.02] tracking-[-0.018em] text-ink">{doc.title}</h1>
          {doc.lede ? <p className="mt-2.5 max-w-[720px] text-[17px] leading-relaxed text-on-surface-variant">{doc.lede}</p> : null}
        </header>
        {/* One hairline between sections, as between a level's blocks. */}
        <div className="flex flex-col [&>*+*]:mt-9 [&>*+*]:border-t [&>*+*]:border-border-gray [&>*+*]:pt-8">
          {doc.intro ? <Body text={doc.intro} /> : null}
          {doc.sections.map((s, i) => {
            const risky = /risk|watch|careful|caveat/i.test(s.title);
            return (
              <section key={i}>
                <Eyebrow className={cn("mb-3.5 block", risky && "text-clay-ink")}>{s.title}</Eyebrow>
                <Body text={s.body} marks={/step/i.test(s.title) && plan.steps?.length ? plan.steps : undefined} />
              </section>
            );
          })}
        </div>
        <OnTheBluprint text={plan.text} since={plan.state === "approved" ? plan.approvedAt : undefined} done={status === "done"} />
        {plan.file ? (
          <p className="mt-10 font-mono text-[11px] text-faint" title={plan.file}>
            {plan.file.replace(/^\/(Users|home)\/[^/]+/, "~")}
          </p>
        ) : null}
      </article>

      {/* The question, at the foot of the doc it is about. */}
      <footer className="sticky bottom-0 border-t border-border-gray bg-paper/95 backdrop-blur-sm">
        <div className="mx-auto flex w-full max-w-[920px] flex-col gap-2.5 px-10 py-3.5">
          {plan.state === "approved" ? (
            <Line dot="bg-[var(--color-diff-add-ink)]" text={
                status === "working"
                  ? "Accepted. Claude is building it."
                  : status === "waiting"
                    ? "Accepted. Claude needs you in its tab."
                    : "Accepted, and Claude has finished."
              } action={onShowClaude} />
          ) : choices ? (
            <>
              <div className="flex flex-wrap items-center gap-2">
                <span className="mr-auto flex items-center gap-2 text-[13px] font-medium text-ink">
                  <span className="size-2 rounded-full bg-clay-ink" />
                  Build this plan?
                </span>
                {yes
                  .slice(1)
                  .reverse()
                  .map((c) => (
                    <Button key={c.n} onClick={() => void answer(c)}>
                      {c.label}
                    </Button>
                  ))}
                {yes[0] ? (
                  <Button variant="primary" onClick={() => void answer(yes[0])}>
                    {yes[0].label}
                  </Button>
                ) : null}
              </div>
              {change ? (
                <form
                  className="flex items-end gap-2"
                  onSubmit={(e) => {
                    e.preventDefault();
                    void answer(change);
                  }}
                >
                  <textarea
                    rows={1}
                    value={words}
                    onChange={(e) => {
                      setWords(e.target.value);
                      // Grows with what is typed, as Claude Code's prompt does, up to a scroll.
                      e.target.style.height = "auto";
                      e.target.style.height = `${e.target.scrollHeight + 2}px`;
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
                        e.preventDefault();
                        e.currentTarget.form?.requestSubmit();
                      }
                    }}
                    placeholder={`${change.label}…`}
                    className="max-h-40 min-h-8 min-w-0 flex-1 resize-none border border-border-gray bg-card px-3 py-[7px] text-[13px] leading-[16px] text-ink placeholder:text-faint focus:border-border-strong focus:outline-none"
                  />
                  <Button type="submit" disabled={!words.trim()}>
                    Send
                  </Button>
                </form>
              ) : null}
            </>
          ) : plan.state === "revising" || status === "working" ? (
            <Line dot="bg-amber-ink" text={plan.asked ? `Asked: “${plan.asked}”. Claude is revising the plan.` : "Claude is revising the plan."} action={onShowClaude} />
          ) : (
            <Line dot="bg-border-strong" text={pty === undefined ? "Claude's tab is closed." : "Not accepted yet. Claude's tab has the conversation."} action={onShowClaude} />
          )}
        </div>
      </footer>
    </div>
  );
}

/** Every diagram box the plan tied to a bluprint section (its `section`, an id path), with what the plan does to it. */
function plannedSections(text: string): { label: string; section: string; change?: string }[] {
  return pieces(text).flatMap((p) => {
    if (p.kind !== "figure" || p.lang !== "diagram") return [];
    try {
      const v = JSON.parse(p.body) as { boxes?: Loose[] };
      return (v.boxes ?? []).filter((b) => str(b.section)).map((b) => ({ label: str(b.label) ?? str(b.id) ?? "", section: str(b.section)!, change: str(b.change) }));
    } catch {
      return [];
    }
  });
}

/**
 * A plan with no diagram tied to the bluprint still names its files: each one the
 * bluprint already explains lands on the section that explains it most closely.
 */
function filedSections(text: string, bluprint: BuiltBluprint): { label: string; section: string; change?: string }[] {
  const cited = citations(bluprint.L0);
  const root = bluprint.RUN.root?.replace(/\/$/, "");
  const seen = new Set<string>();
  return pieces(text).flatMap((p) => {
    if (p.kind !== "figure" || p.lang !== "files") return [];
    return fileLines(p.body).flatMap((f) => {
      const path = (root && f.path.startsWith(`${root}/`) ? f.path.slice(root.length + 1) : f.path).replace(/^\.?\//, "");
      const by = (cited.get(path) ?? []).slice().sort((a, b) => b.path.length - a.path.length)[0];
      const section = by?.path.join("/");
      if (!section || seen.has(section)) return [];
      seen.add(section);
      return [{ label: path.slice(path.lastIndexOf("/") + 1), section, change: f.verdict === "removed" ? "gone" : "changed" }];
    });
  });
}

/**
 * Where the plan lands on the bluprint, each part a way to its level; and once
 * the plan is built, what the bluprint's updates actually redid beside what the
 * plan said it would touch, so a plan that quietly grew, or missed a part,
 * is visible without reading the diff.
 */
function OnTheBluprint({ text, since, done }: { text: string; since?: number; done: boolean }) {
  const bluprint = useMaybeBluprint();
  const planned = useMemo(() => {
    const drawn = plannedSections(text);
    return drawn.length || !bluprint ? drawn : filedSections(text, bluprint);
  }, [text, bluprint]);
  const [touched, setTouched] = useState<{ id: string; title: string }[] | null>(null);
  useEffect(() => {
    if (!bluprint || !done || since === undefined) return;
    let live = true;
    fetch(`/api/diff?bluprint=${encodeURIComponent(bluprint.name)}&turns=1`)
      .then((r) => r.json())
      .then((j: { turns?: { at: string; sections?: { id: string; title: string }[] }[] }) => {
        if (!live) return;
        const after = (j.turns ?? []).filter((t) => Date.parse(t.at) >= since);
        setTouched(after.length ? [...new Map(after.flatMap((t) => t.sections ?? []).map((s) => [s.id, s])).values()] : null);
      })
      .catch(() => {});
    return () => {
      live = false;
    };
  }, [bluprint, done, since]);
  if (!bluprint || !planned.length) return null;
  const pathOf = (section: string) => (bluprint.nodeAt(section.split("/")) ? section.split("/") : findSection(bluprint, section));
  const trail = (path: string[]) => path.map((_, i) => bluprint.nodeAt(path.slice(0, i + 1))?.title ?? path[i]).join(" › ");
  const resolved = planned.map((p) => ({ ...p, path: pathOf(p.section) }));
  // A planned section counts as touched when it, or a section inside it, was redone.
  const hit = (path: string[]) => touched?.some((t) => path.includes(t.id) || bluprint.nodeAt(path)?.children?.some(function inside(c): boolean { return c.id === t.id || (c.children ?? []).some(inside); }));
  const changing = resolved.filter((p) => p.path && p.change);
  const unplanned = touched?.filter((t) => !resolved.some((p) => p.path?.includes(t.id))) ?? [];
  return (
    <section className="mt-9 border-t border-border-gray pt-8">
      <Eyebrow className="mb-3.5 block">On the bluprint</Eyebrow>
      <ul className="flex flex-col gap-1 text-[13px]">
        {resolved.map((p) => (
          <li key={p.label + p.section} className="flex items-baseline gap-2">
            <span className="w-[140px] shrink-0 truncate text-ink">{p.label}</span>
            {p.path ? (
              <button type="button" onClick={() => goTo(p.path!)} className="min-w-0 cursor-pointer truncate text-accent hover:underline">
                {trail(p.path)}
              </button>
            ) : (
              <span className="text-faint">no section {p.section}</span>
            )}
            {touched && p.path && p.change ? (
              <span className={cn("ml-auto shrink-0 text-[12px]", hit(p.path) ? "text-accent" : "text-amber-ink")}>{hit(p.path) ? "touched" : "planned, not touched"}</span>
            ) : null}
          </li>
        ))}
      </ul>
      {touched && unplanned.length ? (
        <p className="mt-3 text-[12.5px] text-amber-ink">
          Also changed, not in the plan:{" "}
          {unplanned.map((t, i) => (
            <span key={t.id}>
              {i ? ", " : ""}
              {t.title}
            </span>
          ))}
        </p>
      ) : null}
      {touched && changing.length && changing.every((p) => hit(p.path!)) && !unplanned.length ? <p className="mt-3 text-[12.5px] text-accent">Built as planned: every part it named changed, and nothing else.</p> : null}
    </section>
  );
}

function Line({ dot, text, action }: { dot: string; text: string; action?: () => void }) {
  return (
    <div className="flex items-center gap-2 text-[13px] text-on-surface-variant">
      <span className={cn("size-2 shrink-0 rounded-full", dot)} />
      <span className="mr-auto min-w-0">{text}</span>
      {action ? (
        <Button variant="ghost" onClick={action}>
          Show Claude
        </Button>
      ) : null}
    </div>
  );
}

/** A section's words and pictures, in order; the Steps with Claude's marks on them once it builds the plan. */
function Body({ text, marks }: { text: string; marks?: StepMark[] }) {
  return (
    <div className="flex flex-col gap-6">
      {pieces(text).map((p, i) =>
        p.kind === "figure" ? (
          <Figure key={i} lang={p.lang} body={p.body} />
        ) : (
          <div key={i} className="doc-prose plan-prose max-w-[760px]">
            <Markdown remarkPlugins={[remarkGfm]} components={marks ? marked(p.text, marks) : undefined}>
              {p.text}
            </Markdown>
          </div>
        ),
      )}
    </div>
  );
}

/** Each numbered step with its mark, found by the number its own line starts with. */
function marked(text: string, marks: StepMark[]): Components {
  const lines = text.split("\n");
  return {
    li({ node, children }) {
      const n = Number(lines[(node?.position?.start.line ?? 0) - 1]?.match(/^(\d+)[.)]\s/)?.[1]);
      const m = marks.find((s) => s.n === n);
      return (
        <li data-state={m?.state}>
          {children}
          {m?.state === "doing" ? <span className="ml-2 inline-block font-mono text-[10.5px] uppercase tracking-[0.08em] text-amber-ink">in progress</span> : null}
          {m?.state === "skipped" ? <span className="ml-2 inline-block text-[13px] text-faint">skipped{m.note ? ` — ${m.note}` : ""}</span> : null}
        </li>
      );
    },
  };
}

/** A fence drawn as the bluprint draws its blocks; one that does not parse is shown as written. */
function Figure({ lang, body }: { lang: string; body: string }) {
  if (lang === "files") {
    const lines = fileLines(body);
    if (lines.length) return <Files lines={lines} />;
  } else {
    const drawn = figureOf(lang, body);
    if (drawn) return drawn;
  }
  return (
    <div className="doc-prose">
      <pre>{body}</pre>
    </div>
  );
}

type Loose = Record<string, unknown>;
const isObj = (v: unknown): v is Loose => typeof v === "object" && v !== null && !Array.isArray(v);
const str = (v: unknown) => (typeof v === "string" ? v : typeof v === "number" ? String(v) : undefined);
const objs = (v: unknown) => (Array.isArray(v) ? v.filter(isObj) : []);

const CHANGE: Record<string, Exclude<Verdict, "untouched">> = {
  new: "added",
  added: "added",
  add: "added",
  changed: "changed",
  change: "changed",
  edit: "changed",
  edited: "changed",
  gone: "removed",
  removed: "removed",
  deleted: "removed",
};
const LEGEND = { added: "green is new", changed: "amber changes", removed: "red goes" } as const;

function figureOf(lang: string, body: string): React.ReactNode {
  let v: unknown;
  try {
    v = JSON.parse(body);
  } catch {
    return null;
  }
  if (!isObj(v)) return null;
  if (lang === "diagram") {
    const raw = objs(v.boxes).filter((b) => str(b.id));
    if (!raw.length) return null;
    // Placed in a row when the plan left out where: still a picture. A grid
    // counted from 1 would leave an empty first column and row, drawn as room.
    const at = (n: unknown, i: number) => (typeof n === "number" ? n : i);
    const col0 = Math.min(...raw.map((b, i) => at(b.col, i)));
    const row0 = Math.min(...raw.map((b) => at(b.row, 0)));
    const boxes: (DiagramBox & { verdict: Verdict })[] = raw.map((b, i) => ({
      id: str(b.id)!,
      label: str(b.label) ?? str(b.id)!,
      sub: str(b.sub),
      col: at(b.col, i) - col0,
      row: at(b.row, 0) - row0,
      verdict: CHANGE[str(b.change)?.toLowerCase() ?? ""] ?? "untouched",
    }));
    const of = new Map(boxes.map((b) => [b.id, b.verdict]));
    const arrows: (DiagramArrow & { verdict: Verdict })[] = objs(v.arrows)
      .filter((a) => of.has(str(a.from) ?? "") && of.has(str(a.to) ?? ""))
      .map((a) => {
        const ends = [of.get(str(a.from)!), of.get(str(a.to)!)];
        // A line to something new is new, and one to something going goes with it.
        const verdict =
          CHANGE[str(a.change)?.toLowerCase() ?? ""] ?? (ends.includes("added") ? "added" : ends.includes("removed") ? "removed" : "untouched");
        return { from: str(a.from)!, to: str(a.to)!, label: str(a.label), verdict };
      });
    const block: Extract<Anatomy, { kind: "diagram" }> = { kind: "diagram", caption: str(v.caption) ?? "", boxes, arrows };
    const shown = (["added", "changed", "removed"] as const).filter((k) => boxes.some((b) => b.verdict === k) || arrows.some((a) => a.verdict === k));
    // Nothing marked as changing: drawn plainly, not as a picture of nothing happening.
    if (!shown.length) return <ExplainedBlock block={block} />;
    return (
      <DiagramDiff
        block={block}
        boxes={boxes.map((b): PartDiff => ({ key: b.id, verdict: b.verdict }))}
        arrows={arrows.map((a): PartDiff => ({ key: `${a.from}→${a.to}`, verdict: a.verdict }))}
        legend={shown.map((k) => LEGEND[k]).join(" · ")}
      />
    );
  }
  if (lang === "screen") {
    // A heading or a line of text is as often written with `text` as with
    // `label`, and a first heading is often the screen's title again.
    const title = str(v.title) ?? "";
    const items = objs(v.items)
      .filter((it) => str(it.label) ?? str(it.text))
      .filter((it, i) => !(i === 0 && it.type === "heading" && (str(it.label) ?? str(it.text)) === title))
      .map((it) => ({
        type: (["heading", "text", "field", "choice", "button", "list", "image"].includes(str(it.type) ?? "") ? str(it.type) : "text") as Extract<Explained, { kind: "screen" }>["items"][number]["type"],
        label: (str(it.label) ?? str(it.text))!,
        note: str(it.note),
      }));
    if (!items.length) return null;
    return (
      <ExplainedBlock
        block={{ kind: "screen", title: str(v.title) ?? "", caption: str(v.caption), device: v.device === "phone" ? "phone" : "web", route: str(v.route), items }}
      />
    );
  }
  if (lang === "sequence") {
    const actors = Array.isArray(v.actors) ? v.actors.map(str).filter((a): a is string => Boolean(a)) : [];
    const rows = objs(v.rows)
      .filter((r) => actors.includes(str(r.from) ?? "") && actors.includes(str(r.to) ?? ""))
      .map((r) => ({ from: str(r.from)!, to: str(r.to)!, label: str(r.label) ?? "", note: str(r.note), state: "derived" as const }));
    if (actors.length < 2 || !rows.length) return null;
    return <ExplainedBlock block={{ kind: "sequence", caption: str(v.caption), actors, rows }} />;
  }
  if (lang === "table") {
    const columns = Array.isArray(v.columns) ? v.columns.map((c) => str(c) ?? "") : [];
    const rows = Array.isArray(v.rows) ? v.rows.filter(Array.isArray).map((r: unknown[]) => r.map((c) => str(c) ?? "")) : [];
    if (!columns.length) return null;
    return <ExplainedBlock block={{ kind: "table", caption: str(v.caption), columns, rows, state: "derived" }} />;
  }
  return null;
}

/** The files a plan touches, marked as the bluprint marks a diff. */
function Files({ lines }: { lines: FileLine[] }) {
  return (
    <ul className="max-w-[860px] overflow-hidden border border-border-gray bg-card">
      {lines.map((f, i) => {
        const t = TINT[f.verdict];
        return (
          <li key={i} className="flex items-baseline gap-3 border-b border-border-gray px-4 py-2.5 last:border-b-0">
            <span aria-label={WORD[f.verdict]} className="w-3 shrink-0 text-center font-mono text-[14px] font-bold" style={{ color: t.ink }}>
              {t.mark}
            </span>
            {/* A long path keeps its end, the file's own name, and leaves the reason room. */}
            <span title={f.path} className={cn("max-w-[55%] shrink-0 font-mono text-[12.5px] break-all text-ink", f.verdict === "removed" && "line-through")}>
              {f.path.length > 60 ? `…${f.path.slice(-59)}` : f.path}
            </span>
            {f.why ? <span className="min-w-0 flex-1 text-[13.5px] leading-snug text-on-surface-variant">{f.why}</span> : null}
          </li>
        );
      })}
    </ul>
  );
}

app/components/agent/shell.tsx:
"use client";

import "@xterm/xterm/css/xterm.css";
import type { ITheme } from "@xterm/xterm";
import { Channel, invoke, isTauri } from "@tauri-apps/api/core";
import { getCurrentWebview } from "@tauri-apps/api/webview";
import { readText, writeText } from "@tauri-apps/plugin-clipboard-manager";
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { onFocusClaude } from "@/lib/agent/context";
import { screens } from "@/lib/agent/dictate";
import { outline } from "@/lib/bluprint/build";
import { readSettings } from "@/lib/client/settings";
import { themeOf, type Theme } from "@/lib/client/theme";
import { cn } from "@/lib/client/utils";
import { isMac } from "@/lib/client/platform";
import { findClaude } from "@/lib/client/claude";

/**
 * One tab's program: the user's shell, or their Claude Code, on a real pty in
 * the open bluprint's checkout (src-tauri/src/pty.rs), drawn by xterm. The
 * workspace window (components/agent/workspace.tsx) holds a row of these. A Shell
 * lives as long as its tab: hiding the window or switching tabs only takes it
 * out of sight, so scrollback and a running process survive.
 */

/**
 * The palettes, one per theme. A terminal is chrome ([data-chrome],
 * app/globals.css): its background is the window's own
 * `surface-container-low`, so the terminal sits in it as a tool rather than
 * another card. Classic's chrome is the sheet, so its terminal is white with
 * the sheet's cobalt ink.
 */
const PLAIN: Record<"light" | "dark", ITheme> = {
  light: {
    background: "#f4f4f5",
    foreground: "#1c1c1f",
    cursor: "#111113",
    cursorAccent: "#f4f4f5",
    selectionBackground: "#d4d4d8",
    black: "#1c1c1f",
    red: "#b42318",
    green: "#2a7333",
    yellow: "#8a5a0b",
    blue: "#1d4ed8",
    magenta: "#7e3fb8",
    cyan: "#0e7490",
    white: "#71717a",
    brightBlack: "#52525b",
    brightRed: "#d03a2c",
    brightGreen: "#3a8a44",
    brightYellow: "#a36d10",
    brightBlue: "#2f62e8",
    brightMagenta: "#9455cf",
    brightCyan: "#1489a8",
    brightWhite: "#3f3f46",
  },
  dark: {
    background: "#17171a",
    foreground: "#ececee",
    cursor: "#fafafa",
    cursorAccent: "#17171a",
    selectionBackground: "#3a3a40",
    black: "#0f0f11",
    red: "#f08a8f",
    green: "#8fd19a",
    yellow: "#e0b45e",
    blue: "#93b4ff",
    magenta: "#c9a7f5",
    cyan: "#7dd3d8",
    white: "#d4d4d8",
    brightBlack: "#7a7a83",
    brightRed: "#f5a3a7",
    brightGreen: "#a9e0b2",
    brightYellow: "#ecc77f",
    brightBlue: "#b0c8ff",
    brightMagenta: "#dcc2fa",
    brightCyan: "#9fe1e5",
    brightWhite: "#ffffff",
  },
};

const PALETTES: Record<Theme, ITheme> = {
  ...PLAIN,
  classic: {
    ...PLAIN.light,
    background: "#ffffff",
    foreground: "#1e2f9e",
    cursor: "#2438c8",
    cursorAccent: "#ffffff",
    selectionBackground: "#d5daf5",
    black: "#1e2f9e",
    blue: "#2438c8",
    white: "#7d8adb",
    brightBlack: "#4a5bd2",
    brightBlue: "#4a5bd2",
    brightWhite: "#3445c6",
  },
};

const palette = () => PALETTES[themeOf(document.documentElement.dataset.theme)];

/* ── keys ─────────────────────────────────────────────────────── */

/**
 * What a terminal app does with a key before the program sees it, as GNOME
 * Terminal and VS Code do, and on a Mac as Terminal.app and Ghostty do.
 * Ctrl+←/→ and Home/End are left alone: xterm sends their standard
 * sequences, which shells and Claude Code read themselves.
 */
type Action = { send: string } | { copy: true } | { paste: true } | { zoom: number | null };

/** `claude`: Claude Code is in front, so Ctrl+Enter is its "send now". */
function actionFor(e: KeyboardEvent, selected: boolean, claude: boolean): Action | null {
  const mac = isMac();
  const ctrl = e.ctrlKey && !e.altKey && !e.metaKey;
  // xterm sends nothing for Cmd+arrows and a plain DEL for Cmd+Backspace;
  // a Mac terminal sends the line's start, end and delete-to-start. Option+
  // arrows jump a word, as Esc b / Esc f, which zsh and bash read too.
  if (mac && e.metaKey && !e.ctrlKey && !e.altKey && !e.shiftKey) {
    if (e.key === "ArrowLeft") return { send: "\x01" };
    if (e.key === "ArrowRight") return { send: "\x05" };
    if (e.key === "Backspace") return { send: "\x15" };
  }
  if (mac && e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey) {
    if (e.key === "ArrowLeft") return { send: "\x1bb" };
    if (e.key === "ArrowRight") return { send: "\x1bf" };
    if (e.key === "Delete") return { send: "\x1bd" };
  }
  // A Mac zooms on Cmd, leaving Ctrl+- to the program: Claude Code's undo.
  if (mac ? e.metaKey && !e.ctrlKey && !e.altKey : ctrl && !e.shiftKey) {
    if (e.code === "Equal" || e.code === "NumpadAdd") return { zoom: 1 };
    if (e.code === "Minus" || e.code === "NumpadSubtract") return { zoom: -1 };
    if (e.code === "Digit0" || e.code === "Numpad0") return { zoom: null };
  }
  if (ctrl && !e.shiftKey) {
    // Delete a word: Ctrl+W back (shells, readline, Claude Code), Alt+D on.
    // Off a Mac, Ctrl+W itself closes the tab (components/agent/workspace.tsx), so
    // this is the way to send it.
    if (e.key === "Backspace") return { send: "\x17" };
    if (e.key === "Delete") return { send: "\x1bd" };
    // With text selected, Ctrl+C copies it rather than interrupting — off a
    // Mac, where Cmd+C copies and Ctrl+C always interrupts.
    if (e.code === "KeyC" && selected && !mac) return { copy: true };
    // xterm sends nothing for Ctrl+-; a Mac terminal sends ^_.
    if (e.code === "Minus" && mac) return { send: "\x1f" };
    // xterm sends a plain Return. Claude Code reads Ctrl+Enter, as CSI u,
    // as sending now; a shell would print it, so only Claude gets it.
    if (e.key === "Enter" && claude) return { send: "\x1b[13;5u" };
  }
  if (ctrl && e.shiftKey) {
    if (e.code === "KeyC") return { copy: true };
    if (e.code === "KeyV") return { paste: true };
  }
  // A new line without sending: Claude Code reads Alt+Enter as one, and a
  // shell keeps editing a multi-line command.
  if (e.key === "Enter" && e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey) return { send: "\x1b\r" };
  return null;
}

/** A dropped path as the shell reads it: backslashed as Terminal.app does, quoted on Windows. */
const quote = (path: string) =>
  /Windows/.test(navigator.userAgent)
    ? /\s/.test(path)
      ? `"${path}"`
      : path
    : path.replace(/[^\w\-.,/:@+%=\u0080-\uffff]/g, "\\$&");

/** One font size for every tab, kept per machine like the window's width. */
const FONT_KEY = "bluprint.terminal.fontSize";
const FONT = { min: 9, base: 13, max: 24 };
const ZOOMED = "bluprint:terminal-zoom";

function storedFont() {
  try {
    const n = Number(localStorage.getItem(FONT_KEY));
    if (n >= FONT.min && n <= FONT.max) return n;
  } catch {
    /* storage blocked: the default is fine */
  }
  return FONT.base;
}

function zoom(by: number | null) {
  const next = by === null ? FONT.base : Math.max(FONT.min, Math.min(FONT.max, storedFont() + by));
  try {
    localStorage.setItem(FONT_KEY, String(next));
  } catch {
    /* applies until reload */
  }
  window.dispatchEvent(new CustomEvent(ZOOMED, { detail: next }));
}

/**
 * One tab's terminal: the user's shell on a pty, an xterm drawing it. Lives as
 * long as its tab. With Claude Code found (as Settings says, or wherever it is
 * installed), the shell can run it through the app's launcher, and with
 * `startClaude` it runs it first (src-tauri/src/claude.rs); quitting Claude
 * leaves the shell.
 */
/** What Claude Code shows in place of a plan (src-tauri/src/claude.rs, HIDE). */
const OPEN_PLAN = "▸ Open plan";
/** `[Image #4]`, or a path with an extension and an optional `:line`, as agents print them. */
const FILE_REF = /\[Image #\d+\]|((?:~\/|\.{0,2}\/)?(?:[\w.@+-]+\/)*[\w@+-][\w.@+-]*\.[A-Za-z0-9]{1,10})(?::(\d+))?(?::\d+)?/g;

export function Shell({
  startClaude = false,
  resume,
  run,
  cwd,
  visible,
  claude = false,
  onTitle,
  onSpawn,
  onClaude,
  onOutput,
  onInput,
  onScreen,
  onOpenPlan,
  session,
  onOpenFile,
  onExit,
}: {
  startClaude?: boolean;
  /** The conversation the started Claude picks up again, in a tab reopened after a restart. */
  resume?: string;
  /** A command to type into the shell once it starts, as if the user had: another agent's CLI. */
  run?: string;
  /** Where it starts. A tab keeps the one it was opened with. */
  cwd?: string;
  visible: boolean;
  /** Claude Code is in front in it now, not the shell or another program. */
  claude?: boolean;
  onTitle?: (title: string) => void;
  onSpawn?: (pty: number) => void;
  /** Whether Claude Code was found, so this tab can run it. */
  onClaude?: (found: boolean) => void;
  /** What the program prints, as text: how the dev server's tab hears its address. */
  onOutput?: (text: string) => void;
  /** The user typed into it: what the program prints next is the echo, not its own work. */
  onInput?: () => void;
  /** How to read what is on screen now, line by line: how a plan's tab finds Claude Code's question.
   * With `all`, the whole scrollback: how an agent reads the dev server's logs. */
  onScreen?: (read: (all?: boolean) => string[]) => void;
  /** The plan's line Claude Code shows in place of the plan (src-tauri/src/claude.rs, HIDE) was clicked. */
  onOpenPlan?: () => void;
  /** Claude Code's conversation in it, whose pasted images `[Image #N]` names. */
  session?: string;
  /** A file it printed was clicked: its absolute path, and the line it named. */
  onOpenFile?: (path: string, line?: number) => void;
  onExit: () => void;
}) {
  const el = useRef<HTMLDivElement>(null);
  const pane = useRef<HTMLDivElement>(null);
  /** Files dragged from outside are over this terminal. */
  const [dropping, setDropping] = useState(false);
  /** Re-fit and focus, set once the terminal exists. */
  const show = useRef<(() => void) | null>(null);
  const [error, setError] = useState<string | null>(null);
  // Latest callbacks, so the effect below runs once per shell, not per render.
  const handlers = useRef({ claude, onTitle, onSpawn, onClaude, onOutput, onInput, onScreen, onOpenPlan, session, onOpenFile, onExit });
  useEffect(() => {
    handlers.current = { claude, onTitle, onSpawn, onClaude, onOutput, onInput, onScreen, onOpenPlan, session, onOpenFile, onExit };
  });
  // The bluprint's sections, for `bluprint-list`. Through a ref for the same
  // reason: a bluprint that updates must not restart the shell.
  const bluprint = useBluprint();
  const sections = useRef(bluprint);
  useEffect(() => {
    sections.current = bluprint;
  });

  useEffect(() => {
    if (!isTauri()) {
      // queueMicrotask, so the effect body itself sets no state.
      queueMicrotask(() => setError("The terminal needs the desktop app: run `npm run app:dev`."));
      return;
    }
    let gone = false;
    let id: number | null = null;
    let cleanup = () => {};

    (async () => {
      // Every tab can run Claude, so it is looked for every time; without it
      // the tab is still a shell.
      const { claudePath, model, voice, research } = readSettings();
      const found = await findClaude(claudePath);
      if (gone) return;
      handlers.current.onClaude?.(!!found);
      const launch = found ? { path: found.path, model: model || null, voice, research } : null;
      // xterm measures one glyph to size every cell, so it needs the face's
      // name (not a var()) and the face itself loaded: measured against the
      // fallback, the real font lands in cells of the wrong width once it
      // arrives. A web font is only fetched when something asks for it.
      const family = getComputedStyle(document.documentElement).getPropertyValue("--font-mono").trim();
      const [{ Terminal }, { FitAddon }, { WebglAddon }] = await Promise.all([
        import("@xterm/xterm"),
        import("@xterm/addon-fit"),
        import("@xterm/addon-webgl"),
        document.fonts.load(`${storedFont()}px ${family}`),
        document.fonts.load(`bold ${storedFont()}px ${family}`),
      ]);
      if (gone || !el.current) return;
      const term = new Terminal({
        theme: palette(),
        fontFamily: `${family}, ui-monospace, monospace`,
        // A whole pixel size: a fractional one gives fractional cells, which
        // drift out of line across a row.
        fontSize: storedFont(),
        lineHeight: 1.2,
        cursorBlink: true,
        scrollback: 5000,
        // Claude Code can take the mouse for itself; Option-drag still selects.
        macOptionClickForcesSelection: true,
        allowProposedApi: true,
        // A link a program prints (OSC 8), as Claude Code does: a file opens in
        // an editor tab, a web address in the browser. xterm's own handler
        // asks with confirm(), which the app's webview has no dialog for.
        linkHandler: {
          allowNonHttpProtocols: true,
          activate: (_, uri) => {
            if (uri.startsWith("file:")) {
              const path = decodeURIComponent(new URL(uri).pathname).replace(/^\/([A-Za-z]:)/, "$1");
              handlers.current.onOpenFile?.(path);
            } else {
              void invoke("preview_external", { url: uri }).catch(() => {});
            }
          },
        },
      });
      const fit = new FitAddon();
      term.loadAddon(fit);
      term.open(el.current);
      // The GPU renderer, as VS Code uses: glyphs from a texture atlas on an
      // exact grid. If WebGL is missing or the context is lost, xterm falls
      // back to its DOM renderer by itself once the addon is disposed.
      try {
        const gl = new WebglAddon();
        gl.onContextLoss(() => gl.dispose());
        term.loadAddon(gl);
      } catch {
        /* no WebGL: the DOM renderer stays */
      }
      // macOS shows the right-click menu on Ctrl+Return; in a terminal the key belongs to the program.
      let ctrlEnter = 0;
      term.attachCustomKeyEventHandler((e) => {
        if (e.type === "keydown" && e.key === "Enter" && e.ctrlKey) ctrlEnter = e.timeStamp;
        // An IME's keys (arrows and Enter among them) are its own until the text is committed.
        if (e.isComposing || e.keyCode === 229) return true;
        // Taken by the app first (the palette's keys, components/chrome/palette.tsx): not the program's too.
        if (e.defaultPrevented) return false;
        // Ctrl+` (Cmd+` too) and Ctrl+W off a Mac belong to the workspace window, never the program in a tab.
        if (e.ctrlKey && !e.altKey && !e.shiftKey && e.code === "KeyW" && !isMac()) return false;
        if ((e.ctrlKey || e.metaKey) && e.code === "Backquote") return false;
        const action = actionFor(e, term.hasSelection(), handlers.current.claude);
        if (!action) return true;
        e.preventDefault();
        if (e.type !== "keydown") return false;
        if ("send" in action) {
          if (id !== null) void invoke("pty_write", { id, data: action.send });
        } else if ("copy" in action) {
          void writeText(term.getSelection());
          term.clearSelection();
        } else if ("paste" in action) {
          // paste() wraps it for programs that asked for bracketed paste.
          void readText().then((t) => t && term.paste(t), () => {});
        } else {
          zoom(action.zoom);
        }
        return false;
      });

      /** Fit to the box — skipped while hidden, when it has no size to fit. The
       * program is told only of a real change: each one makes Claude Code redraw. */
      let told = "";
      const refit = () => {
        if (!el.current?.offsetWidth) return;
        fit.fit();
        if (id === null || told === `${term.cols}x${term.rows}`) return;
        told = `${term.cols}x${term.rows}`;
        void invoke("pty_resize", { id, cols: term.cols, rows: term.rows });
      };
      refit();

      const out = new Channel<ArrayBuffer | { exit: number }>();
      // Streaming, so a character split across two reads still decodes.
      const text = new TextDecoder();
      out.onmessage = (m) => {
        if (gone) return;
        if (m instanceof ArrayBuffer) {
          term.write(new Uint8Array(m));
          handlers.current.onOutput?.(text.decode(m, { stream: true }));
        } else handlers.current.onExit();
      };
      try {
        const spawned = await invoke<{ id: number; shell: string }>("pty_spawn", {
          cols: term.cols,
          rows: term.rows,
          onData: out,
          launch,
          startClaude: startClaude && !!launch,
          resume: resume ?? null,
          cwd: cwd ?? null,
          outline: outline(sections.current),
        });
        id = spawned.id;
        // Unmounted while the shell was starting: end it rather than leak it.
        if (gone) {
          void invoke("pty_kill", { id });
          term.dispose();
          return;
        }
        // Typed ahead: the terminal holds it until the shell is ready to read.
        if (run) void invoke("pty_write", { id, data: `${run}\r` });
        handlers.current.onTitle?.(spawned.shell);
        handlers.current.onSpawn?.(spawned.id);
        const read = (all?: boolean) => {
          const b = term.buffer.active;
          const from = all ? 0 : b.baseY;
          return Array.from({ length: all ? b.length : term.rows }, (_, i) => b.getLine(from + i)?.translateToString(true) ?? "");
        };
        handlers.current.onScreen?.(read);
        screens.set(spawned.id, () => read());
      } catch (e) {
        term.dispose();
        setError(`Could not start a shell: ${String(e)}`);
        return;
      }

      // Claude Code shows a plan as its title and this line; the plan itself
      // is read in its tab, which the line opens again even once closed.
      const planLinks = term.registerLinkProvider({
        provideLinks(y, done) {
          const line = term.buffer.active.getLine(y - 1)?.translateToString(true) ?? "";
          const at = line.indexOf(OPEN_PLAN);
          if (at < 0 || !handlers.current.onOpenPlan) return done(undefined);
          done([
            {
              text: OPEN_PLAN,
              range: { start: { x: at + 1, y }, end: { x: at + OPEN_PLAN.length, y } },
              decorations: { pointerCursor: true, underline: true },
              activate: () => handlers.current.onOpenPlan?.(),
            },
          ]);
        },
      });
      // A file an agent names, or an image pasted into Claude Code, opens in
      // an editor tab. Only what is a file on disk is underlined.
      const fileLinks = term.registerLinkProvider({
        provideLinks(y, done) {
          const line = term.buffer.active.getLine(y - 1)?.translateToString(true) ?? "";
          const found = [...line.matchAll(FILE_REF)].filter((m) => m.index === 0 || !/[\w/:.~-]/.test(line[m.index - 1]));
          if (!found.length || !handlers.current.onOpenFile) return done(undefined);
          const { session } = handlers.current;
          void Promise.all(
            found.map(async (m) => {
              const ref = m[1] ?? m[0];
              const path = await invoke<string | null>("file_resolve", { text: ref, cwd: cwd ?? "", session: session ?? null }).catch(() => null);
              if (!path) return null;
              const at = Number(m[2]) || undefined;
              return {
                text: m[0],
                range: { start: { x: m.index + 1, y }, end: { x: m.index + m[0].length, y } },
                decorations: { pointerCursor: true, underline: true },
                activate: () => handlers.current.onOpenFile?.(path, at),
              };
            }),
          ).then((links) => done(links.filter((l) => l !== null)));
        },
      });
      const input = term.onData((data) => {
        void invoke("pty_write", { id, data });
        handlers.current.onInput?.();
      });
      // Selecting copies, as in herdr: no key to press after the drag.
      const host = el.current;
      const copySelected = () => {
        if (term.hasSelection()) void writeText(term.getSelection());
      };
      host.addEventListener("mouseup", copySelected);
      const noKeyMenu = (e: MouseEvent) => {
        if (e.timeStamp - ctrlEnter < 500) e.preventDefault();
      };
      host.addEventListener("contextmenu", noKeyMenu, true);
      // A press on the workspace's own buttons — a tab, +, a menu's item — keeps
      // the keys here, as a terminal's tab bar does: WebKit would otherwise
      // leave focus nowhere once the menu closes.
      const keepFocus = (e: MouseEvent) => {
        const at = e.target as Element;
        if (document.activeElement === term.textarea && at.closest?.("button") && at.closest('[aria-label="Workspace"], [role="menu"]'))
          e.preventDefault();
      };
      window.addEventListener("mousedown", keepFocus, true);
      // Files dragged from Finder: their paths typed at the cursor, as a
      // terminal does — pasted, so Claude Code takes an image's for the image.
      // The window's native drop handler takes OS drops, so the page's own
      // drop events never carry paths; the one under the pointer is this
      // terminal only if nothing (the floating window, a menu) lies over it.
      // On macOS wry reports the drop in points, which Tauri labels physical:
      // scaling it down there would look half way to the window's corner.
      const under = (at: { x: number; y: number; toLogical: (f: number) => { x: number; y: number } }) => {
        const p = isMac() ? at : at.toLogical(window.devicePixelRatio || 1);
        const hit = document.elementFromPoint(p.x, p.y);
        return !!hit && !!pane.current?.contains(hit);
      };
      const drops = getCurrentWebview().onDragDropEvent(({ payload: d }) => {
        if (d.type === "leave") return setDropping(false);
        const here = under(d.position);
        setDropping(here && d.type !== "drop");
        if (d.type === "drop" && here && d.paths.length) {
          term.paste(`${d.paths.map(quote).join(" ")} `);
          term.focus();
        }
      });
      // Pointing at the terminal is enough to type into it, no click needed.
      const focusOnHover = () => term.focus();
      host.addEventListener("mouseenter", focusOnHover);
      const offFocus = onFocusClaude((pty) => {
        if (pty === id && host.checkVisibility()) term.focus();
      });
      const seen = new ResizeObserver(refit);
      seen.observe(el.current);
      show.current = () => {
        refit();
        term.focus();
      };
      show.current();
      // Zoom in one tab, and every tab follows; the grid is re-fitted to the new cells.
      const onZoom = (e: Event) => {
        term.options.fontSize = (e as CustomEvent<number>).detail;
        refit();
      };
      window.addEventListener(ZOOMED, onZoom);
      const recolour = new MutationObserver(() => (term.options.theme = palette()));
      recolour.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
      cleanup = () => {
        window.removeEventListener(ZOOMED, onZoom);
        recolour.disconnect();
        host.removeEventListener("mouseup", copySelected);
        host.removeEventListener("contextmenu", noKeyMenu, true);
        window.removeEventListener("mousedown", keepFocus, true);
        void drops.then((off) => off());
        host.removeEventListener("mouseenter", focusOnHover);
        offFocus();
        seen.disconnect();
        input.dispose();
        planLinks.dispose();
        fileLinks.dispose();
        term.dispose();
        if (id !== null) {
          screens.delete(id);
          void invoke("pty_kill", { id });
        }
      };
    })();

    return () => {
      gone = true;
      show.current = null;
      cleanup();
    };
    // A tab's kind and directory are fixed at birth, so this runs once per tab.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Before paint, so a tab shown again never draws a frame at its old size.
  useLayoutEffect(() => {
    if (visible) show.current?.();
  }, [visible]);

  return (
    // Chrome wherever it is, the window or the main view.
    <div ref={pane} data-chrome className={cn("absolute inset-0 bg-surface-container-low px-3 pb-1", !visible && "hidden")}>
      {error ? (
        <p className="font-mono text-[11.5px] text-clay-ink">{error}</p>
      ) : (
        <div ref={el} className="h-full w-full" />
      )}
      {dropping ? <div className="pointer-events-none absolute inset-1 border border-dashed border-accent-line bg-accent/5" /> : null}
    </div>
  );
}

