"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, MotionConfig, motion } from "motion/react";
import { cn } from "@/lib/client/utils";
import type { RowCtx } from "@/components/bluprint/anatomy";
import { Zoom } from "@/components/chrome/zoom";
import { Crumbs, goTo, useLocation } from "@/components/chrome/crumbs";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { useFlash } from "@/components/bluprint/flash";
import { DocView, closeDoc, useOpenDoc } from "@/components/bluprint/docs";
import { TimelineView, closeTimeline, useTimelineOpen } from "@/components/review/timeline";
import { FileView, closeFile, useOpenFile } from "@/components/bluprint/code";
import { section, type Target } from "@/lib/agent/context";
import { DragChip, SectionTabs, dropAt, dropInTab, openInTab, setPartDrag, tabTitle, type Drop } from "@/components/chrome/tabs";
import { DiffBar, HereChanges } from "@/components/review/diagram-diff";
import { STATIC_BLUPRINT } from "@/lib/bluprint/source";
import { useSettings, type Ground } from "@/lib/client/settings";
import { useDesktop } from "@/lib/client/platform";
import { PICKABLE, PickMenu, opener, opensAt, targetOf, wordsOf } from "@/components/bluprint/pick";
import { Level } from "@/components/bluprint/level";

/**
 * The whole screen: ONE level at a time.
 *
 * The board used to be a pan/zoom canvas where every drill unfolded another
 * row of cards beside the last. Each level added width, siblings were squeezed
 * to fit a 360px wrapper (Formulas rendered one word per line), and the top
 * level was a hand-placed serpentine whose second row read right-to-left. See
 * D28.
 *
 * Now the node you opened is the header, its children are the body, and the
 * way back is the trail on the left. Every level — the repo included — is the
 * same template, so depth costs nothing visually: level six looks like level
 * one, and the bottom of every branch is the code itself.
 */

export function Canvas() {
  const bluprint = useBluprint();
  const { RUN, nodeAt, name, bluprints } = bluprint;
  const scrollRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  // A rewrite of the bluprint lights what it changed (components/bluprint/flash.tsx).
  useFlash(contentRef);

  /**
   * The open path, root-first, read from the URL (useLocation in
   * components/chrome/crumbs.tsx); depth is its length. Clicking empty space used to
   * go back, and an accidental click on the background threw away where you
   * were.
   */
  const { path, crumbs } = useLocation();
  // An update held back while this level was open is taken in on the way to another (components/bluprint/bluprint-context.tsx).
  const { onScreen, apply } = bluprint;
  const at = JSON.stringify(path);
  useEffect(() => {
    onScreen(JSON.parse(at));
    apply();
  }, [at, onScreen, apply]);
  // A doc opened over the level (components/bluprint/docs.tsx) takes its place until closed.
  const doc = useOpenDoc();
  // So does the history (components/review/timeline.tsx).
  const timeline = useTimelineOpen();
  // And a whole file open to edit (components/bluprint/code.tsx).
  const file = useOpenFile();
  const key = doc ? `doc:${doc.file}` : file ? `file:${file.file}` : timeline ? "timeline" : path.join("/");
  const focus = path.length ? nodeAt(path) : null;

  // Which way the level slides: deeper or back. Derived when the depth
  // changes, during render, so the exiting level already knows its direction.
  const [moved, setMoved] = useState({ depth: path.length, dir: 1 });
  if (moved.depth !== path.length) {
    setMoved({ depth: path.length, dir: path.length > moved.depth ? 1 : -1 });
  }
  const dir = moved.dir;

  // A trace belongs to the level it was started on, and ends when you leave.
  const [trace, setTrace] = useState<{ at: string; id: string } | null>(null);
  const traced = trace?.at === key ? trace.id : null;
  const setTraced = useCallback(
    (id: string | null) => setTrace(id ? { at: key, id } : null),
    [key],
  );

  // A level gone into starts at its top; one come back to, where it was left.
  const scrolls = useRef(new Map<string, number>());
  const [came, setCame] = useState({ key, back: false });
  if (came.key !== key) setCame({ key, back: isBack(came.key, key) });

  /* ── rows that open their own level ───────────────────────── */

  const onOpenRow = useCallback(
    (id: string) => {
      // The row id names its owner (`eng-path:2` owns `eng-path:2:not expired`,
      // hence lastIndexOf). The owner is either the open node or a card on the
      // level below it, so cut the path back to it or step into it — never
      // just append.
      const owner = id.slice(0, id.lastIndexOf(":"));
      const ownerAt = path.indexOf(owner);
      const at = ownerAt === -1 ? [...path, owner] : path.slice(0, ownerAt + 1);
      if (nodeAt([...at, id])) goTo([...at, id]);
    },
    [path, nodeAt],
  );

  const ctx = useMemo<RowCtx>(
    () => ({
      traced,
      onTrace: (rid) => setTraced(traced === rid ? null : rid),
      open: path[path.length - 1] ?? null,
      onOpenRow,
    }),
    [traced, setTraced, path, onOpenRow],
  );

  /* ── keyboard ─────────────────────────────────────────────── */

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLElement && e.target.closest("textarea, input")) return;
      if (e.key === "Escape") {
        // Unwind one layer at a time: an open doc, file or the history, the trace, then one level.
        if (doc) closeDoc();
        else if (file) closeFile();
        else if (timeline) closeTimeline();
        else if (traced) setTraced(null);
        else if (path.length) goTo(path.slice(0, -1));
      } else if (e.key === "0" && !e.metaKey && !e.ctrlKey && !e.altKey) {
        // ⌘0 belongs to the zoom reset, which listens on window too.
        goTo([]);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [traced, setTraced, path, doc, file, timeline]);

  /* ── handing a section to Claude ──────────────────────────── */

  // Right-click offers Claude the nearest thing under the pointer: a card or
  // the open level's header (`data-path`, a whole section), else a row, box,
  // block or line of code (`data-row`, `data-pick`). In the desktop app, and on
  // a published bluprint, whose Claude is its panel; a plain browser keeps its own menu.
  const desktop = useDesktop();
  const { ground } = useSettings();
  const [menu, setMenu] = useState<{ x: number; y: number; target: Target; words: string; opens: string[] | null } | null>(null);
  const closeMenu = useCallback(() => setMenu(null), []);
  const onContextMenu = (e: React.MouseEvent) => {
    // Anything else on the level — a caption, the space between blocks — is
    // part of the section you are in, so that is what it offers.
    const el = (e.target as Element).closest<HTMLElement | SVGElement>(PICKABLE);
    const target = el ? targetOf(bluprint, el, path) : section(bluprint, path);
    if (!target) return;
    e.preventDefault();
    setMenu({ x: e.clientX, y: e.clientY, target, words: wordsOf(bluprint, el, path), opens: opensAt(e.target as Element, path) });
  };

  // A part opens in a new tab the way a link does: a middle click, or a click
  // with ⌘/Ctrl. Taken in the capture phase, before the part's own click opens
  // it in place.
  const toTab = (e: React.MouseEvent) => {
    const opens = opensAt(e.target as Element, path);
    if (!opens) return;
    e.preventDefault();
    e.stopPropagation();
    openInTab(name, opens);
  };

  // A part dragged off the bluprint onto its strip of tabs opens there, as a link
  // dragged onto Chrome's tabs does (components/chrome/tabs.tsx). A press that hardly
  // moves is still a click, which opens the part in place.
  const grab = (e: React.PointerEvent) => {
    if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    const target = e.target as Element;
    if (target.closest(":disabled")) return;
    const part = opener(target, path);
    if (!part) return;
    const { el, at } = part;
    const label = tabTitle(nodeAt, at);
    const x0 = e.clientX;
    const y0 = e.clientY;
    let moving = false;
    const move = (m: PointerEvent) => {
      if (!moving && Math.hypot(m.clientX - x0, m.clientY - y0) < 6) return;
      if (!moving) {
        moving = true;
        document.body.dataset.dragging = "";
        el.setAttribute("data-drag-source", "");
        window.getSelection()?.removeAllRanges();
      }
      setPartDrag({ label, x: m.clientX, y: m.clientY, drop: dropAt(m.clientX, m.clientY) });
    };
    const end = (drop: Drop | null) => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", cancel);
      window.removeEventListener("blur", cancel);
      window.removeEventListener("keydown", key, true);
      if (!moving) return;
      delete document.body.dataset.dragging;
      el.removeAttribute("data-drag-source");
      setPartDrag(null);
      // The click this press ends in would open the part in place too.
      const swallow = (c: MouseEvent) => {
        c.preventDefault();
        c.stopPropagation();
      };
      window.addEventListener("click", swallow, { capture: true, once: true });
      setTimeout(() => window.removeEventListener("click", swallow, true));
      if (drop) dropInTab(name, at, drop);
    };
    const up = (u: PointerEvent) => end(dropAt(u.clientX, u.clientY));
    const cancel = () => end(null);
    // Esc lets go of the part, before it can take the bluprint up a level.
    const key = (k: KeyboardEvent) => {
      if (k.key !== "Escape" || !moving) return;
      k.preventDefault();
      k.stopImmediatePropagation();
      end(null);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", cancel);
    window.addEventListener("blur", cancel);
    window.addEventListener("keydown", key, true);
  };

  return (
    <div
      className="flex h-full w-full flex-col overflow-hidden bg-paper"
      onContextMenu={desktop || STATIC_BLUPRINT ? onContextMenu : undefined}
      onClickCapture={(e) => (e.metaKey || e.ctrlKey ? toTab(e) : undefined)}
      onAuxClickCapture={(e) => (e.button === 1 ? toTab(e) : undefined)}
      onPointerDown={grab}
      // The browser's own drag of a link would take the pointer from ours.
      onDragStart={(e) => (opensAt(e.target as Element, path) ? e.preventDefault() : undefined)}
    >
      {menu ? <PickMenu {...menu} onClose={closeMenu} /> : null}
      <DragChip />
      <SectionTabs path={path} />
      <main
        ref={scrollRef}
        className={cn(GROUND[ground], "relative min-h-0 min-w-0 flex-1 overflow-auto")}
        // The level is laid out in what the workspace window leaves of the
        // width (components/agent/workspace.tsx), but never in less than 480px: a
        // window dragged nearly full width covers the bluprint rather than crushing it.
        style={{ paddingRight: "min(var(--workspace-inset, 0px), max(0px, 100% - 480px))" }}
      >
        {/* In the desktop app the title bar carries where you are. */}
        {desktop ? null : (
          <Crumbs repo={RUN.repo} bluprint={name} bluprints={bluprints} crumbs={crumbs} onJump={(d) => goTo(path.slice(0, d))} />
        )}
        {doc || file || timeline ? null : <DiffBar path={path} />}
        <Zoom scrollRef={scrollRef}>
        <div ref={contentRef} className="relative mx-auto max-w-[1680px] px-10 pb-28 pt-5">
          {/* The CSS reduced-motion rule (app/globals.css) does not reach motion's own animations. */}
          <MotionConfig reducedMotion="user">
          <AnimatePresence mode="wait" initial={false} custom={dir}>
            <motion.div
              key={key}
              custom={dir}
              variants={{
                in: { opacity: 1, y: 0 },
                out: (d: number) => ({ opacity: 0, y: 10 * d }),
                // Leaving is quicker than arriving, and takes no clicks: a
                // second click on the level going away would open one of its parts.
                gone: (d: number) => ({ opacity: 0, y: -6 * d, pointerEvents: "none", transition: { duration: 0.1, ease: [0.22, 1, 0.36, 1] } }),
              }}
              initial="out"
              animate="in"
              exit="gone"
              transition={{ duration: 0.18, ease: [0.22, 1, 0.36, 1] }}
            >
              <Arrive pane={scrollRef} kept={scrolls} at={key} back={came.back} />
              {doc ? (
                <DocView file={doc.file} line={doc.line} />
              ) : file ? (
                <FileView key={file.file} file={file.file} line={file.line} />
              ) : timeline ? (
                <TimelineView />
              ) : (
                <>
                  <HereChanges path={path} />
                  <Level node={focus ?? bluprint.TOP} path={path} ctx={ctx} onOpen={goTo} />
                </>
              )}
            </motion.div>
          </AnimatePresence>
          </MotionConfig>
        </div>
        </Zoom>
      </main>
    </div>
  );
}

const overlaid = (key: string) => key === "timeline" || key.startsWith("doc:") || key.startsWith("file:");

/** Whether `to` is where `from` was reached from: up the path, or out from under a doc, file or the history. */
function isBack(from: string, to: string) {
  if (overlaid(to)) return false;
  return overlaid(from) || (from !== to && (to === "" || from.startsWith(`${to}/`)));
}

/**
 * Scrolls the pane for a level as it arrives, and keeps where it was left as
 * it goes. Mounted inside the level rather than run on the change of path: the
 * level leaving is still on screen while it fades, and scrolling then jerked it
 * to its top under the reader's eyes.
 */
function Arrive({ pane, kept, at, back }: { pane: React.RefObject<HTMLElement | null>; kept: React.RefObject<Map<string, number>>; at: string; back: boolean }) {
  useLayoutEffect(() => {
    const el = pane.current;
    const tops = kept.current;
    if (!el) return;
    el.scrollTo({ top: back ? (tops.get(at) ?? 0) : 0 });
    return () => void tops.set(at, el.scrollTop);
  }, [pane, kept, at, back]);
  return null;
}

const GROUND: Record<Ground, string> = { dots: "dotfield", squares: "gridfield", plain: "" };

app/components/bluprint/code.tsx:
"use client";

import { useSearchParams } from "next/navigation";
import { useCallback, useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { CodeEditor } from "@/components/ui/editor";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { Eyebrow } from "@/components/ui/state";
import type { Slice, WriteResult } from "@/lib/server/repo";
import { readSource, SOURCE_URL } from "@/lib/bluprint/source";
import { openTab } from "@/lib/client/tabs";

/**
 * A whole file, to read and edit as in an editor (D74). It takes the level's
 * place while `?file=` is in the URL, as a doc does (D66), and usually opens
 * in a tab of its own beside the level it came from — "Open the whole file"
 * on any code — so Back, Escape and closing the tab all return there.
 *
 * Text comes through `/api/source` and goes back through it, behind the same
 * containment and stale-read check as the code pane: a file that changed on
 * disk since it was opened is refused, never overwritten.
 */

const urlOf = (path: string[], file: string, line?: number) => {
  const q = new URLSearchParams();
  const now = new URLSearchParams(window.location.search);
  const bluprint = now.get("bluprint");
  if (bluprint) q.set("bluprint", bluprint);
  for (const id of path) q.append("at", id);
  q.set("file", file);
  if (line) q.set("line", String(line));
  return `?${q}`;
};

/** Opens a file over the level at `path`. */
export function openFile(path: string[], file: string, line?: number) {
  window.history.pushState(null, "", urlOf(path, file, line));
}

/** Opens a file in a new tab beside the one in front, over the level at `path`. */
export function openFileInTab(bluprint: string, path: string[], file: string, line?: number) {
  openTab(bluprint, path, file);
  openFile(path, file, line);
}

export function closeFile() {
  const q = new URLSearchParams(window.location.search);
  q.delete("file");
  q.delete("line");
  window.history.pushState(null, "", q.size ? `?${q}` : window.location.pathname);
}

/** The file open in the URL, if any. */
export function useOpenFile(): { file: string; line?: number } | null {
  const params = useSearchParams();
  const file = params.get("file");
  return file ? { file, line: Number(params.get("line")) || undefined } : null;
}

export function FileView({ file, line }: { file: string; line?: number }) {
  const { name: bluprint } = useBluprint();
  const [slice, setSlice] = useState<Slice | null | "failed">(null);
  const [draft, setDraft] = useState<string | null>(null);
  const [saved, setSaved] = useState<WriteResult | null>(null);

  const read = useCallback(
    (signal?: AbortSignal) =>
      readSource({ bluprint, file, start: 1, end: Number.MAX_SAFE_INTEGER }, signal)
        .then((r) => ("slice" in r ? r.slice : ("failed" as const)))
        .catch(() => "failed" as const),
    [bluprint, file],
  );
  useEffect(() => {
    const ac = new AbortController();
    void read(ac.signal).then((s) => !ac.signal.aborted && setSlice(s));
    return () => ac.abort();
  }, [read]);

  const text = slice && slice !== "failed" ? slice.code : "";
  const dirty = draft !== null && draft !== text;

  async function save() {
    if (!dirty || !slice || slice === "failed") return;
    const res = await fetch("/api/source", {
      method: "POST",
      headers: { "content-type": "application/json" },
      // writeSlice drops one trailing newline from what it is sent; a whole
      // file may end in one of its own, so give it one to drop.
      body: JSON.stringify({ bluprint, file, start: 1, end: slice.total, code: `${draft}\n`, expected: text }),
    });
    const body = (await res.json()) as WriteResult;
    setSaved(body);
    if (body.ok) {
      // What is on disk now is the only thing this view may show as the file.
      setSlice(await read());
      setDraft(null);
    }
  }

  return (
    <>
      <header className="mb-5 border-b border-border-gray pb-5">
        <div className="mb-4">
          <Button onClick={closeFile}>‹ Back to the bluprint</Button>
        </div>
        <Eyebrow>Code</Eyebrow>
        <h1 className="mt-2 break-all font-mono text-[20px] font-semibold tracking-[-0.01em] text-ink">{file}</h1>
        {slice && slice !== "failed" ? (
          <div className="mt-3 flex flex-wrap items-center gap-3">
            <span className="tnum font-mono text-[11px] text-faint">{slice.total.toLocaleString()} lines</span>
            {SOURCE_URL ? null : dirty ? (
              <>
                <Button variant="primary" onClick={() => void save()}>
                  Save to disk
                </Button>
                <Button variant="ghost" onClick={() => (setDraft(null), setSaved(null))}>
                  Discard changes
                </Button>
                <span className="text-[12px] text-muted-slate">⌘S saves. Nothing is written until you do.</span>
              </>
            ) : (
              <span className="text-[12px] text-muted-slate">Type to edit; ⌘S saves to disk.</span>
            )}
            {saved?.ok && !dirty ? <span className="text-[12px] text-accent">Saved.</span> : null}
            {saved && !saved.ok ? (
              <span className="text-[12px] text-clay-ink">
                Not saved: {saved.refused}
                {saved.refused === "stale" ? " — the file changed on disk since it was opened. Discard and reopen to get the current text." : ""}
              </span>
            ) : null}
          </div>
        ) : null}
      </header>
      {slice === null ? <p className="text-[13px] text-faint">Reading…</p> : null}
      {slice === "failed" ? <p className="text-[13px] text-clay-ink">Could not read this file from the repository.</p> : null}
      {slice && slice !== "failed" ? (
        <div className="overflow-hidden border border-border-gray">
          <CodeEditor
            file={file}
            start={1}
            value={draft ?? text}
            onChange={setDraft}
            onSave={() => void save()}
            readOnly={Boolean(SOURCE_URL)}
            lit={line}
            className="max-h-[calc(100vh-260px)]"
          />
        </div>
      ) : null}
    </>
  );
}

app/components/bluprint/docs.tsx:
"use client";

import { createContext, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { Fragment, jsx, jsxs } from "react/jsx-runtime";
import { useSearchParams } from "next/navigation";
import Markdown, { type Components } from "react-markdown";
import { raw } from "hast-util-raw";
import { defaultSchema, sanitize } from "hast-util-sanitize";
import { toJsxRuntime } from "hast-util-to-jsx-runtime";
import type { Root } from "hast";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { Eyebrow } from "@/components/ui/state";
import { Button } from "@/components/ui/button";
import { STATIC_BLUPRINT, readSource } from "@/lib/bluprint/source";
import type { Doc } from "@/lib/server/docs";
import { cn } from "@/lib/client/utils";
import { PLUGINS, REHYPE } from "@/lib/client/markdown";

/**
 * The docs reader: a project's Markdown (README, design notes, decision logs)
 * and HTML pages, read in place of the open level, rendered for reading. It lives in the URL
 * like a level does — `?doc=<path>`, with `&line=` to land on a passage the
 * bluprint cites — so Back closes it, and walking anywhere on the bluprint leaves it.
 * The text comes through `/api/source`, behind the same containment check as
 * the code. HTML in a doc is drawn after GitHub's cleaning — never run — and
 * its images come through `/api/image`, which keeps web ones for offline use.
 */

/** Opens a doc over the open level, which stays in the URL to come back to. */
export function openDoc(file: string, at?: { line?: number; heading?: string }) {
  const q = new URLSearchParams(window.location.search);
  q.set("doc", file);
  q.delete("line");
  if (at?.line) q.set("line", String(at.line));
  window.history.pushState(null, "", `?${q}${at?.heading ? `#${at.heading}` : ""}`);
}

/** Back to the level the doc was opened over. */
export function closeDoc() {
  const q = new URLSearchParams(window.location.search);
  q.delete("doc");
  q.delete("line");
  window.history.pushState(null, "", q.size ? `?${q}` : window.location.pathname);
}

/** The doc open in the URL, if any. */
export function useOpenDoc(): { file: string; line?: number } | null {
  const params = useSearchParams();
  const file = params.get("doc");
  const line = Number(params.get("line")) || undefined;
  return file ? { file, line } : null;
}

const lists = new Map<string, Promise<Doc[]>>();

/** The open bluprint's docs, fetched once per bluprint. Null while loading. */
export function useDocList(): Doc[] | null {
  const { name } = useBluprint();
  const [docs, setDocs] = useState<{ bluprint: string; list: Doc[] } | null>(null);
  useEffect(() => {
    if (!lists.has(name))
      lists.set(
        name,
        fetch(`/api/docs?bluprint=${encodeURIComponent(name)}`)
          .then((r) => r.json())
          .then((r: { docs?: Doc[] }) => r.docs ?? [])
          .catch(() => {
            lists.delete(name);
            return [];
          }),
      );
    let live = true;
    void lists.get(name)!.then((list) => live && setDocs({ bluprint: name, list }));
    return () => {
      live = false;
    };
  }, [name]);
  return docs?.bluprint === name ? docs.list : null;
}

/* ── links and headings ──────────────────────────────────────── */

/** GitHub's heading anchors, so links written for GitHub land here too. */
function slug(text: string) {
  return text
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s_-]/gu, "")
    .replace(/\s/g, "-");
}

type Hast = { type: string; value?: string; children?: Hast[]; position?: { start: { line: number } } };
/** What a block override is handed: its syntax node, for the line it starts on, and what it holds. */
type Rendered = { node?: Hast; children?: React.ReactNode; align?: string };
const textOf = (n: Hast | undefined): string => (n?.value ?? "") + (n?.children ?? []).map(textOf).join("");

/** `href` from a doc at `from`, resolved against the repo root; null for one that leaves it. */
function resolve(from: string, href: string): string | null {
  const parts = href.startsWith("/") ? [] : from.split("/").slice(0, -1);
  for (const seg of href.replace(/^\//, "").split("/")) {
    if (seg === "..") {
      if (!parts.length) return null;
      parts.pop();
    } else if (seg && seg !== ".") parts.push(seg);
  }
  return parts.join("/");
}

/** The doc being read, for anything inside it that names another file. */
const Reading = createContext<{ bluprint: string; file: string }>({ bluprint: "", file: "" });

/**
 * Where an image in a doc is fetched from (app/api/image): a path in the
 * repository through the same containment as the code, a web image through
 * the offline cache. A published page has no server, so it keeps what the
 * doc says.
 */
function imageSrc(at: { bluprint: string; file: string }, src: string | undefined): string | undefined {
  if (!src || STATIC_BLUPRINT || src.startsWith("data:")) return src;
  if (/^https?:\/\//i.test(src)) return `/api/image?url=${encodeURIComponent(src)}`;
  if (/^[a-z][a-z0-9+.-]*:/i.test(src)) return undefined;
  const path = resolve(at.file, decodeURIComponent(src.split(/[?#]/)[0]));
  return path ? `/api/image?bluprint=${encodeURIComponent(at.bluprint)}&file=${encodeURIComponent(path)}` : undefined;
}

/** A `srcset`'s candidates, each URL through imageSrc and its descriptor kept. */
const imageSet = (at: { bluprint: string; file: string }, set: string | undefined) =>
  set
    ?.split(",")
    .map((c) => {
      const [url, ...rest] = c.trim().split(/\s+/);
      const to = imageSrc(at, url);
      return to ? [to, ...rest].join(" ") : "";
    })
    .filter(Boolean)
    .join(", ");

/** Docs that are a page of HTML rather than Markdown. */
const isHtml = (file: string) => /\.html?$/i.test(file);
/** Docs the reader opens: Markdown, and HTML pages. */
const isDoc = (path: string) => /\.(mdx?|html?)$/i.test(path);

function scrollToHeading(root: HTMLElement | null, id: string) {
  const el = root?.querySelector<HTMLElement>(`[id="${CSS.escape(id)}"]`);
  el?.scrollIntoView({ block: "start", behavior: "smooth" });
  return Boolean(el);
}

/**
 * How the doc's Markdown is drawn, beyond plain elements. Fixed at module
 * level, so a re-render of the reader never remounts the text. Blocks carry
 * the line they start on, which is how a passage the bluprint cites is found
 * again; headings carry their slug, and the reader numbers repeats and makes
 * them anchors once the page is drawn. Links read the doc they are in off
 * the article (`data-file`).
 */
const heading = (Tag: "h1" | "h2" | "h3" | "h4" | "h5" | "h6") =>
  function Heading({ node, children, align }: Rendered) {
    return (
      // `align` is what a README centres its logo and title with; the cleaning keeps it.
      <Tag data-slug={slug(textOf(node))} data-line={node?.position?.start.line} {...(align ? { align: align as "center" } : {})}>
        {children}
      </Tag>
    );
  };
const lined = (Tag: "p" | "li" | "pre" | "blockquote" | "table") =>
  function Lined({ node, children, align }: Rendered) {
    return (
      <Tag data-line={node?.position?.start.line} {...(align ? { align: align as "center" } : {})}>
        {children}
      </Tag>
    );
  };

const COMPONENTS: Components = {
  h1: heading("h1"),
  h2: heading("h2"),
  h3: heading("h3"),
  h4: heading("h4"),
  h5: heading("h5"),
  h6: heading("h6"),
  p: lined("p"),
  li: lined("li"),
  pre: lined("pre"),
  blockquote: lined("blockquote"),
  table: lined("table"),
  a({ href = "", children }) {
    if (/^(https?:|mailto:)/i.test(href))
      return (
        <a href={href} target="_blank" rel="noreferrer">
          {children}
        </a>
      );
    if (href.startsWith("#"))
      return (
        <a
          href={href}
          onClick={(e) => {
            e.preventDefault();
            scrollToHeading(e.currentTarget.closest("article"), decodeURIComponent(href.slice(1)));
          }}
        >
          {children}
        </a>
      );
    // Another file in the repository: a doc opens here, resolved against the
    // doc it is in; anything else is named, since this reader shows only docs.
    const [path, hash] = href.split("#");
    if (!isDoc(path)) return <span title={href}>{children}</span>;
    return (
      <a
        href={href}
        onClick={(e) => {
          e.preventDefault();
          const from = e.currentTarget.closest("article")?.dataset.file ?? "";
          const target = resolve(from, decodeURIComponent(path));
          if (target) openDoc(target, { heading: hash });
        }}
      >
        {children}
      </a>
    );
  },
  img: function Img({ src, srcSet, alt, title, width, height, align }: React.ImgHTMLAttributes<HTMLImageElement> & { align?: string }) {
    const at = useContext(Reading);
    return (
      // eslint-disable-next-line @next/next/no-img-element -- a doc's own image, at the size it asks for
      <img
        src={imageSrc(at, typeof src === "string" ? src : undefined)}
        srcSet={imageSet(at, srcSet)}
        alt={alt ?? ""}
        title={title}
        width={width}
        height={height}
        {...(align ? { align } : {})}
        loading="lazy"
      />
    );
  },
  source: function Source({ srcSet, media, type }: React.SourceHTMLAttributes<HTMLSourceElement>) {
    return <source srcSet={imageSet(useContext(Reading), srcSet)} media={media} type={type} />;
  },
};

/* ── the reader ──────────────────────────────────────────────── */

type Text = { text: string } | { failed: true } | null;

/** A doc that is an HTML page: parsed, cleaned the same way, and drawn with the same parts. */
function HtmlDoc({ html }: { html: string }) {
  const tree = useMemo(
    () => sanitize(raw({ type: "root", children: [{ type: "raw", value: html }] } as unknown as Root), defaultSchema) as Root,
    [html],
  );
  return toJsxRuntime(tree, { Fragment, jsx, jsxs, passNode: true, components: COMPONENTS as never });
}

export function DocView({ file, line }: { file: string; line?: number }) {
  const { name: bluprint } = useBluprint();
  const [loaded, setLoaded] = useState<{ file: string; text: Text }>({ file, text: null });
  const text = loaded.file === file ? loaded.text : null;
  const article = useRef<HTMLElement>(null);
  const [outline, setOutline] = useState<{ id: string; label: string; depth: number }[]>([]);

  useEffect(() => {
    const ctl = new AbortController();
    readSource({ bluprint, file, start: 1, end: 1_000_000 }, ctl.signal)
      .then((r) => setLoaded({ file, text: "slice" in r ? { text: r.slice.code } : { failed: true } }))
      .catch(() => !ctl.signal.aborted && setLoaded({ file, text: { failed: true } }));
    return () => ctl.abort();
  }, [bluprint, file]);

  // The outline is read off the rendered headings, so its anchors are the
  // ones the page actually has. Then the reader lands where they asked: a
  // heading named in the hash, else the passage at `line`, lit once.
  useLayoutEffect(() => {
    const root = article.current;
    if (!root || !text || !("text" in text)) return;
    // GitHub's anchors, numbered on a repeat, so links written for GitHub land here.
    const seen = new Map<string, number>();
    for (const h of root.querySelectorAll<HTMLElement>("[data-slug]")) {
      const base = h.dataset.slug!;
      const n = seen.get(base) ?? 0;
      seen.set(base, n + 1);
      h.id = n ? `${base}-${n}` : base;
    }
    setOutline(
      [...root.querySelectorAll<HTMLElement>("h1[id], h2[id], h3[id]")].map((h) => ({
        id: h.id,
        label: h.textContent ?? "",
        depth: Number(h.tagName[1]),
      })),
    );
    const hash = decodeURIComponent(window.location.hash.slice(1));
    if (hash && scrollToHeading(root, hash)) return;
    if (!line) return;
    const at = [...root.querySelectorAll<HTMLElement>("[data-line]")].filter((el) => Number(el.dataset.line) <= line).pop();
    if (!at) return;
    at.scrollIntoView({ block: "start" });
    const ring = getComputedStyle(document.documentElement).getPropertyValue("--color-accent-surface").trim();
    at.animate([{ backgroundColor: ring }, { backgroundColor: "transparent" }], { duration: 2400, easing: "ease-out" });
  }, [text, line]);


  return (
    <>
      <header className="mb-8 border-b border-border-gray pb-6">
        <div className="mb-4">
          <Button onClick={closeDoc}>‹ Back to the bluprint</Button>
        </div>
        <Eyebrow>Doc</Eyebrow>
        <h1 className="mt-2 font-mono text-[22px] font-semibold tracking-[-0.01em] text-ink">{file}</h1>
      </header>
      {text === null ? (
        <p className="text-[13px] text-faint">Reading…</p>
      ) : "failed" in text ? (
        <p className="text-[13px] text-clay-ink">Could not read this doc from the repository.</p>
      ) : (
        <div className="flex items-start gap-12">
          <article ref={article} data-file={file} className="doc-prose min-w-0 max-w-[760px] flex-1">
            <Reading.Provider value={{ bluprint, file }}>
              {isHtml(file) ? (
                <HtmlDoc html={text.text} />
              ) : (
                <Markdown remarkPlugins={PLUGINS} rehypePlugins={REHYPE} components={COMPONENTS}>
                  {text.text}
                </Markdown>
              )}
            </Reading.Provider>
          </article>
          {outline.length > 2 ? (
            <nav aria-label="Outline" className="sticky top-4 hidden max-h-[calc(100vh-10rem)] w-[240px] shrink-0 overflow-auto xl:block">
              <Eyebrow>On this page</Eyebrow>
              <ul className="mt-3 flex flex-col gap-0.5">
                {outline.map((h) => (
                  <li key={h.id}>
                    <a
                      href={`#${h.id}`}
                      onClick={(e) => {
                        e.preventDefault();
                        scrollToHeading(article.current, h.id);
                      }}
                      className={cn(
                        "block truncate py-1 text-[12.5px] text-muted-slate hover:text-ink",
                        h.depth === 3 && "pl-3 text-[12px]",
                      )}
                      title={h.label}
                    >
                      {h.label}
                    </a>
                  </li>
                ))}
              </ul>
            </nav>
          ) : null}
        </div>
      )}
    </>
  );
}

/** A small page, for the palette and the title bar: a doc. */
export function DocIcon() {
  return (
    <>
      <path d="M4 1.5h5.5L12 4v10.5H4z" />
      <path d="M6 7h4M6 9.5h4M6 12h2.5" />
    </>
  );
}

app/components/bluprint/explain.tsx:
"use client";

import { useEffect, useState, useSyncExternalStore } from "react";
import { cn } from "@/lib/client/utils";
import { Eyebrow, Prose, SymbolLinks } from "@/components/ui/state";
import { Button } from "@/components/ui/button";
import { Overlay, DIALOG } from "@/components/ui/dialog";
import { AnatomyView, type RowCtx } from "@/components/bluprint/anatomy";
import { SourceView } from "@/components/bluprint/source-view";
import { ExplainedBlock, isExplained } from "@/components/bluprint/blocks";
import { Hunks, useDiff } from "@/components/review/diff";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { goTo, useLocation } from "@/components/chrome/crumbs";
import { useCitations, useTrail } from "@/components/bluprint/files";
import { nodesAt } from "@/lib/bluprint/coverage";
import { hunksOf, type HunkLines } from "@/lib/client/hunks";
import { readSource } from "@/lib/bluprint/source";
import type { Slice } from "@/lib/server/repo";
import type { Anatomy, Explainer as ExplainerData, Walkthrough } from "@/lib/bluprint/schema";
import { signal } from "@/lib/client/signal";

/* ── the toggle ──────────────────────────────────────────────── */

/**
 * Whether the plain-words layer is showing. A per-reader preference, kept in
 * the browser: on by default, since the reader it serves is the one who does
 * not yet know to look for it.
 */
const KEY = "bluprint.explain";
const { subscribe, emit } = signal();

function readExplain(): boolean {
  try {
    return localStorage.getItem(KEY) !== "off";
  } catch {
    return true;
  }
}

export function useExplain(): [boolean, (on: boolean) => void] {
  const on = useSyncExternalStore(subscribe, readExplain, () => true);
  const set = (v: boolean) => {
    try {
      localStorage.setItem(KEY, v ? "on" : "off");
    } catch {
      /* private window: the choice lasts this page */
    }
    emit();
  };
  return [on, set];
}

export function ExplainToggle() {
  const [on, set] = useExplain();
  return (
    <Button
      onClick={() => set(!on)}
      aria-pressed={on}
      title={on ? "Hide the plain-words explanations" : "Show plain-words explanations for someone new to this"}
      className={on ? "border-accent-line bg-accent-surface text-accent hover:border-accent-line hover:bg-accent-surface hover:text-accent" : undefined}
    >
      <span aria-hidden className="text-[13px] leading-none">{on ? "◉" : "○"}</span>
      Explain
    </Button>
  );
}

/* ── one level, in plain words ───────────────────────────────── */

/**
 * An explainer's picture draws the idea, not the code, so it makes no claim to
 * be uncertain about: a row the generator left without a `state` would
 * otherwise render as "not certain".
 */
function settled(b: Anatomy): Anatomy {
  const rows = "rows" in b ? (b.rows as unknown[]).map((r) => (r && typeof r === "object" && !Array.isArray(r) ? { state: "derived", ...r } : r)) : undefined;
  return { ...b, ...(rows ? { rows } : {}), ...(b.kind === "table" ? { state: b.state ?? "derived" } : {}) } as Anatomy;
}

/**
 * The level said again for someone new to the project and its field
 * (`Node.explain`): prose that defines its words, then a picture where one
 * teaches more than the prose. Set apart by a green rule, so it reads as a
 * gloss on the level rather than more of it.
 */
export function Explainer({ owner, explain, ctx }: { owner: string; explain: ExplainerData; ctx: RowCtx }) {
  return (
    <section data-pick="In plain words" data-pick-text={explain.body} className="border-l-2 border-accent-line pl-5">
      <Eyebrow className="text-accent">In plain words</Eyebrow>
      <div className="max-w-[720px]">
        {explain.body.split(/\n\s*\n/).map((para, i) => (
          <p key={i} className="mt-3 text-[14.5px] leading-[1.65] text-on-surface">
            <Prose text={para} />
          </p>
        ))}
      </div>
      {(explain.blocks ?? []).map(settled).map((b, i) => (
        <div key={i} className="mt-6">
          {isExplained(b) ? (
            <div className={b.kind === "diagram" ? "" : "max-w-[1100px]"}>
              <ExplainedBlock block={b} />
            </div>
          ) : (
            <div className="max-w-[900px] [zoom:1.18]">
              <AnatomyView owner={`${owner}@explain${i}`} blocks={[b]} ctx={ctx} />
            </div>
          )}
        </div>
      ))}
    </section>
  );
}

/**
 * The repository level's way in: the core things the system does, each
 * followed through the roots, each step opening the part where it happens.
 * The bluprint's words are defined where they are used, on hover, so they get no
 * list of their own.
 */
export function StartHere({
  walkthroughs,
  onOpen,
}: {
  walkthroughs: Walkthrough[];
  onOpen: (path: string[]) => void;
}) {
  return (
    <div className="flex flex-col gap-10">
      {walkthroughs.map((w, i) => (
        <Walk key={i} walkthrough={w} onOpen={onOpen} />
      ))}
    </div>
  );
}

function Walk({ walkthrough, onOpen }: { walkthrough?: Walkthrough; onOpen: (path: string[]) => void }) {
  const { nodeAt } = useBluprint();
  return (
    <section data-pick="Start here" className="border-l-2 border-accent-line pl-5">
      {walkthrough ? (
        <div>
          <Eyebrow className="text-accent">Follow one thing through</Eyebrow>
          <p className="mt-2 text-[17px] font-semibold tracking-[-0.01em] text-ink">{walkthrough.title}</p>
          <ol className="mt-4 flex max-w-[820px] flex-col">
            {walkthrough.steps.map((s, i) => {
              const last = i === walkthrough.steps.length - 1;
              const where = s.path.map((_, k) => nodeAt(s.path.slice(0, k + 1))?.title).filter(Boolean);
              return (
                <li key={i} className="flex gap-3.5">
                  <div className="flex w-[22px] shrink-0 flex-col items-center pt-[11px]">
                    <span className="flex size-[22px] items-center justify-center rounded-full border border-accent-line bg-accent-surface font-mono text-[10.5px] font-semibold text-accent">
                      {i + 1}
                    </span>
                    {last ? null : <span className="mt-1 w-px flex-1 bg-border-strong" />}
                  </div>
                  <button
                    onClick={() => onOpen(s.path)}
                    className={cn(
                      "group min-w-0 flex-1 px-3 py-2.5 text-left transition-colors hover:bg-surface-container",
                      last ? "" : "mb-1",
                    )}
                  >
                    <span className="flex items-baseline gap-2">
                      <span className="text-[14px] font-semibold text-ink">{s.title}</span>
                      <span className="ml-auto shrink-0 truncate text-[11.5px] text-faint group-hover:text-accent">
                        {where.join(" › ")} ›
                      </span>
                    </span>
                    <span className="mt-1 block text-[13.5px] leading-relaxed text-on-surface-variant">
                      {/* The step is a button already; a link inside it would nest one. */}
                      <SymbolLinks.Provider value={() => undefined}>
                        <Prose text={s.detail} />
                      </SymbolLinks.Provider>
                    </span>
                  </button>
                </li>
              );
            })}
          </ol>
        </div>
      ) : null}
    </section>
  );
}

/* ── code, opened from what explains it ──────────────────────── */

/** What the code popup shows: the thing clicked, and the lines behind it. */
export interface CodeFocus {
  heading: string;
  detail?: string;
  refs: { file: string; start: number; end: number; label?: string }[];
  /** The level's own verification, for the level's code; a step's lines were not checked on their own. */
  verified?: { claims: number; corrected: number };
}

/** `file:start-end` or `file:line`, as a step's `at` cites it. */
export function parseAt(at: string): { file: string; start: number; end: number } | null {
  const m = /^(.+):(\d+)(?:-(\d+))?$/.exec(at);
  return m ? { file: m[1], start: +m[2], end: +(m[3] ?? m[2]) } : null;
}

/**
 * The lines behind one step (or one leaf), over the page. It opens with where
 * it belongs — the trail down to this level and the step's own words — so the
 * code never arrives without the sentence that explains it.
 */
export function CodePopup({
  focus,
  trail,
  owner,
  ctx,
  onClose,
}: {
  focus: CodeFocus;
  trail: string[];
  owner: string;
  ctx: RowCtx;
  onClose: () => void;
}) {
  return (
    <Overlay onClose={onClose}>
      <div role="dialog" aria-label={focus.heading} className={cn(DIALOG, "max-w-[1060px]")}>
        <div className="border-b border-border-gray px-5 pb-4 pt-3.5">
          <div className="flex items-center gap-3">
            <p className="min-w-0 flex-1 truncate text-[12px] text-faint">{trail.join(" › ")}</p>
            <Button variant="ghost" size="sm" onClick={onClose} title="Close (Esc)">
              ✕
            </Button>
          </div>
          <p className="mt-1.5 text-[17px] font-semibold tracking-[-0.01em] text-ink">{focus.heading}</p>
          {focus.detail ? (
            <p className="mt-1 max-w-[760px] text-[13.5px] leading-relaxed text-on-surface-variant">
              <Prose text={focus.detail} />
            </p>
          ) : null}
          {focus.verified ? (
            <p className="mt-2 text-[12px] text-faint">
              {focus.verified.claims === 1 ? "The one claim" : `All ${focus.verified.claims} claims`} on this level were checked against these lines by a second model
              {focus.verified.corrected ? ` · ${focus.verified.corrected} ${focus.verified.corrected === 1 ? "was" : "were"} corrected` : ""}
            </p>
          ) : null}
        </div>
        <div className="flex flex-col gap-5 overflow-y-auto p-5">
          {focus.refs.map((r) => (
            <div key={`${r.file}:${r.start}`}>
              <p className="mb-2 flex items-baseline gap-3">
                {r.label ? <span className="text-[13.5px] text-ink">{r.label}</span> : null}
                <span className="ml-auto font-mono text-[11px] text-faint">
                  {r.file}:{r.start === r.end ? r.start : `${r.start}–${r.end}`}
                </span>
              </p>
              <ChangedHere file={r.file} start={r.start} end={r.end} />
              <AlsoExplained file={r.file} start={r.start} end={r.end} onGo={onClose} />
              <CodeSlice owner={owner} file={r.file} start={r.start} end={r.end} ctx={ctx} />
            </div>
          ))}
        </div>
      </div>
    </Overlay>
  );
}

/**
 * In diff mode, the hunks that landed on these lines, above the code as it is
 * now: the answer to "what did that commit do here". Lines are matched where
 * the diff starts, so a ref the server carried to another commit
 * (lib/server/diff.ts `bluprintDiff`) is matched where it was carried to.
 */
function ChangedHere({ file, start, end }: { file: string; start: number; end: number }) {
  const diff = useDiff()?.diff;
  const change = diff?.files.find((f) => (f.mapped ?? f.path) === file);
  if (!diff || !change) return null;
  const cited = diff.sections.flatMap((s) => s.files.filter((f) => f.path === file).flatMap((f) => f.lines));
  const span = cited.find((l) => l.s === start && l.e === end)?.at ?? { s: start, e: end };
  const near = (h: HunkLines) => {
    const old = h.lines.map((l) => l.old ?? h.oldStart);
    return Math.min(...old) <= span.e && Math.max(...old) >= span.s;
  };
  if (!hunksOf(change.diff).some(near)) return null;
  return (
    <div className="mb-3">
      <p className="mb-1 text-[12px] font-medium text-muted-slate">What changed here — red is gone, green is new</p>
      <Hunks file={change} only={near} />
    </div>
  );
}

/**
 * Other levels that open these same lines: a function shared by two features
 * is explained where each one uses it, and a reader on one should know the
 * other exists rather than find it by chance.
 */
function AlsoExplained({ file, start, end, onGo }: { file: string; start: number; end: number; onGo: () => void }) {
  const cited = useCitations();
  const trail = useTrail();
  const here = useLocation().path.join("/");
  const others = [...new Map(nodesAt(cited, file, start, end).filter((c) => c.path.join("/") !== here).map((c) => [c.path.join("/"), c.path])).values()];
  if (!others.length) return null;
  return (
    <p className="mb-2 flex flex-wrap items-baseline gap-x-3 gap-y-0.5 text-[12px]">
      <span className="text-faint">Also explained in</span>
      {others.slice(0, 4).map((p) => (
        <button key={p.join("/")} type="button" onClick={() => (goTo(p), onGo())} className="cursor-pointer text-accent hover:underline">
          {trail(p)}
        </button>
      ))}
    </p>
  );
}

function CodeSlice({ owner, file, start, end, ctx }: { owner: string; file: string; start: number; end: number; ctx: RowCtx }) {
  const { name: bluprint } = useBluprint();
  const [slice, setSlice] = useState<Slice | null | "failed">(null);
  useEffect(() => {
    const ac = new AbortController();
    readSource({ bluprint, file, start, end }, ac.signal)
      .then((r) => !ac.signal.aborted && setSlice("slice" in r ? r.slice : "failed"))
      .catch(() => !ac.signal.aborted && setSlice("failed"));
    return () => ac.abort();
  }, [bluprint, file, start, end]);
  if (slice === "failed") return <p className="text-[12.5px] text-clay-ink">Could not read this file from the repository.</p>;
  if (!slice) return <p className="text-[12.5px] text-faint">Reading…</p>;
  return <SourceView owner={`${owner}@${file}:${start}`} block={{ kind: "source", file, start: slice.start, code: slice.code }} ctx={ctx} />;
}

app/components/bluprint/files.tsx:
"use client";

import { useEffect, useMemo, useState } from "react";
import { DIALOG, INPUT, Overlay, QUIET } from "@/components/ui/dialog";
import { goTo } from "@/components/chrome/crumbs";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { followTurn } from "@/lib/agent/turns";
import { citations, required, symbolsOf, type Citation, type IndexFile, type BluprintIndex } from "@/lib/bluprint/coverage";
import { cn } from "@/lib/client/utils";

/**
 * Every file of the checkout, and where the bluprint explains each part of it.
 *
 * The bluprint is cut by what people do (D16), which is the right way down for a
 * reader who knows what they are looking for by name — and no way at all for
 * one holding a path from a stack trace or a function from a review. This is
 * the other way in: the repository's own files, each saying how much of it the
 * bluprint explains, why it was left out, or that it arrived after the bluprint was
 * made, and each top-level symbol a click from the level that explains it.
 * Nothing in the checkout is absent from this list, so "where is this part?"
 * always has an answer, even when the answer is "nowhere yet".
 *
 * The panel routes, the level shows (D58): a pick opens that level and closes
 * the panel.
 */

const OPEN = "bluprint:files";

export type FilesFilter = "all" | "gaps" | "excluded" | "added";
export const openFiles = (filter: FilesFilter = "all") => window.dispatchEvent(new CustomEvent<FilesFilter>(OPEN, { detail: filter }));

interface Files {
  index: BluprintIndex | null;
  /** New files of a kind the bluprint explains. */
  added: string[];
  /** Files git ignores that are edited by hand: `.env` and its kin. */
  local?: string[];
  /** Every file in the checkout now, whatever the bluprint knows of it. */
  present?: string[];
}

const fetched = new Map<string, Files>();

/** The open bluprint's file index (app/api/files), fetched again whenever the bluprint is rewritten. Null until it arrives, or on a bluprint with no checkout. */
export function useFiles(): Files | null {
  const bluprint = useBluprint();
  // Tagged with its bluprint, so a switch never shows the last bluprint's files while (or if) the new one's fail to load.
  const [got, setFiles] = useState<{ name: string; files: Files } | null>(null);
  useEffect(() => {
    let live = true;
    fetch(`/api/files?bluprint=${encodeURIComponent(bluprint.name)}`)
      .then((r) => (r.ok ? r.json() : null))
      .then((r: Files | null) => {
        if (!live || !r) return;
        fetched.set(bluprint.name, r);
        setFiles({ name: bluprint.name, files: r });
      })
      .catch(() => {});
    return () => {
      live = false;
    };
  }, [bluprint.name, bluprint.RUN]);
  return got?.name === bluprint.name ? got.files : (fetched.get(bluprint.name) ?? null);
}

/** Every span the reader can open on the open bluprint, by file. */
export function useCitations() {
  const { L0 } = useBluprint();
  return useMemo(() => citations(L0), [L0]);
}

/** The trail to a level in the titles the reader sees. */
export function useTrail() {
  const { nodeAt } = useBluprint();
  return (path: string[]) => path.map((_, i) => nodeAt(path.slice(0, i + 1))?.title ?? path[i]).join(" › ");
}

type Row = { path: string; file?: IndexFile; added?: boolean };

export function FilesPanel() {
  const bluprint = useBluprint();
  const files = useFiles();
  const cited = useCitations();
  const trail = useTrail();
  const [filter, setFilter] = useState<FilesFilter | null>(null);
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState<string | null>(null);
  const [asked, setAsked] = useState<Set<string>>(new Set());

  useEffect(() => {
    const on = (e: Event) => setFilter((e as CustomEvent<FilesFilter>).detail ?? "all");
    window.addEventListener(OPEN, on);
    return () => window.removeEventListener(OPEN, on);
  }, []);

  const rows = useMemo<Row[]>(() => {
    const out: Row[] = Object.entries(files?.index?.files ?? {}).map(([path, file]) => ({ path, file }));
    for (const path of files?.added ?? []) out.push({ path, added: true });
    return out.sort((a, b) => a.path.localeCompare(b.path));
  }, [files]);

  const gapsOf = (r: Row) => (r.file?.status === "source" ? symbolsOf(cited, r.path, r.file).filter((s) => required(s) && !s.by.length) : []);
  const counts = useMemo(
    () => ({
      all: rows.length,
      gaps: rows.filter((r) => gapsOf(r).length).length,
      excluded: rows.filter((r) => r.file?.status === "excluded").length,
      added: rows.filter((r) => r.added).length,
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- gapsOf reads only rows and cited
    [rows, cited],
  );

  if (!filter) return null;
  const close = () => setFilter(null);
  const q = query.trim().toLowerCase();
  const shown = rows.filter((r) => {
    if (filter === "gaps" && !gapsOf(r).length) return false;
    if (filter === "excluded" && r.file?.status !== "excluded") return false;
    if (filter === "added" && !r.added) return false;
    return !q || r.path.toLowerCase().includes(q) || r.file?.symbols.some((s) => s.name.toLowerCase().includes(q));
  });

  /** Ask the updater to explain what no level opens yet, or to take in new files. */
  const ask = (r: Row) => {
    const root = bluprint.RUN.root;
    if (!root) return;
    const gaps = gapsOf(r);
    // The section nearest the file already, else the root that owns it: where the updater starts.
    const near = (cited.get(r.path) ?? [])[0]?.path.at(-1) ?? r.file?.roots[0];
    void followTurn(root, {
      transcript: null,
      corrections:
        gaps.length && near
          ? [{ section: near, note: `Explain ${gaps.map((s) => `\`${s.name}\` (${r.path}:${s.start}-${s.end})`).join(", ")}: no leaf or step opens them yet. Give each a leaf, or a step that cites it.` }]
          : [],
    });
    setAsked(new Set(asked).add(r.path));
  };

  return (
    <Overlay onClose={close}>
      <div className={DIALOG + " max-w-[760px]"}>
        <header className="shrink-0 border-b border-border-gray px-5 py-3.5">
          <h2 className="text-[15px] font-semibold text-ink">Every file</h2>
          <p className="mt-0.5 text-[12px] text-muted-slate">Where each part of the code is explained. Pick a symbol to open the level that explains it.</p>
          {files && !files.index ? (
            <p className="mt-2 text-[12px] text-amber-ink">This bluprint was made before bluprints kept a file index; regenerate it to see every file here.</p>
          ) : null}
          <div className="mt-2.5 flex flex-wrap items-center gap-1.5">
            {(
              [
                ["all", "All"],
                ["gaps", "Not fully explained"],
                ["excluded", "Left out"],
                ["added", "Not on the bluprint yet"],
              ] as const
            ).map(([k, label]) =>
              k === "all" || counts[k] ? (
                <button
                  key={k}
                  type="button"
                  aria-pressed={filter === k}
                  onClick={() => setFilter(k)}
                  className={cn(
                    "cursor-pointer border px-2 py-0.5 text-[12px]",
                    filter === k ? "border-accent text-accent" : "border-border-gray text-muted-slate hover:text-ink",
                  )}
                >
                  {label} <span className="font-mono text-[11px]">{counts[k]}</span>
                </button>
              ) : null,
            )}
            <span className="flex-1" />
            <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Filter by path or symbol" aria-label="Filter files" className={INPUT + " w-[220px] py-1 text-[12px]"} />
          </div>
        </header>
        <div className="min-h-0 flex-1 overflow-auto px-5 py-3">
          {!files ? <p className="text-[13px] text-muted-slate">Reading the checkout…</p> : null}
          {files && !shown.length ? <p className="text-[13px] text-muted-slate">Nothing matches.</p> : null}
          <ul className="flex flex-col">
            {shown.map((r) => (
              <li key={r.path} className="border-b border-border-gray last:border-0">
                <FileRow
                  row={r}
                  cited={cited.get(r.path) ?? []}
                  gaps={gapsOf(r).length}
                  open={open === r.path || (Boolean(q) && shown.length <= 5)}
                  onToggle={() => setOpen(open === r.path ? null : r.path)}
                  onGo={(path) => (goTo(path), close())}
                  trail={trail}
                  asked={asked.has(r.path)}
                  onAsk={bluprint.RUN.root ? () => ask(r) : undefined}
                />
              </li>
            ))}
          </ul>
        </div>
        <footer className="flex shrink-0 justify-end border-t border-border-gray px-5 py-2.5">
          <button type="button" onClick={close} className={QUIET}>
            Close
          </button>
        </footer>
      </div>
    </Overlay>
  );
}

function FileRow({
  row,
  cited,
  gaps,
  open,
  onToggle,
  onGo,
  trail,
  asked,
  onAsk,
}: {
  row: Row;
  cited: Citation[];
  gaps: number;
  open: boolean;
  onToggle: () => void;
  onGo: (path: string[]) => void;
  trail: (path: string[]) => string;
  asked: boolean;
  onAsk?: () => void;
}) {
  const f = row.file;
  const syms = f ? symbolsOf(new Map([[row.path, cited]]), row.path, f) : [];
  const need = syms.filter(required).length;
  // Levels citing the file, each once, deepest first: the way in for a file with no symbols to pick.
  const levels = [...new Map(cited.map((c) => [c.path.join("/"), c.path])).values()].sort((a, b) => b.length - a.length);
  const badge = row.added
    ? { text: "not on the bluprint yet", tone: "text-amber-ink" }
    : f?.status === "excluded"
      ? { text: "left out", tone: "text-faint" }
      : f?.status === "other"
        ? { text: f.kind ?? "other", tone: "text-faint" }
        : need
          ? { text: `${need - gaps}/${need} explained`, tone: gaps ? "text-amber-ink" : "text-accent" }
          : { text: levels.length ? "explained" : "not explained", tone: levels.length ? "text-accent" : "text-amber-ink" };
  return (
    <div className="py-1.5">
      <button type="button" aria-expanded={open} onClick={onToggle} className="flex w-full cursor-pointer items-baseline gap-3 text-left">
        <span className="min-w-0 flex-1 truncate font-mono text-[12px] text-ink">{row.path}</span>
        <span className={cn("shrink-0 text-[11.5px]", badge.tone)}>{badge.text}</span>
      </button>
      {f?.purpose && !open ? <p className="truncate text-[11.5px] text-muted-slate">{f.purpose}</p> : null}
      {open ? (
        <div className="mt-1 flex flex-col gap-1 pb-1 pl-3">
          {f?.purpose ? <p className="text-[12px] leading-snug text-muted-slate">{f.purpose}</p> : null}
          {f?.reason ? <p className="text-[12px] text-muted-slate">Left out: {f.reason}</p> : null}
          {row.added ? <p className="text-[12px] text-muted-slate">Added since the bluprint was made; the next update takes it in.</p> : null}
          {syms.map((s) => (
            <div key={`${s.name}:${s.start}`} className="flex items-baseline gap-2 text-[12px]">
              <span className="shrink-0 font-mono text-ink">{s.name}</span>
              <span className="shrink-0 font-mono text-[10.5px] text-faint">
                {s.start}–{s.end}
              </span>
              <span className="min-w-0 flex-1 truncate text-muted-slate">{s.does}</span>
              {s.by.length ? (
                <button type="button" onClick={() => onGo(s.by[0].path)} className="max-w-[45%] shrink-0 cursor-pointer truncate text-accent hover:underline">
                  {trail(s.by[0].path)}
                </button>
              ) : (
                <span className={cn("shrink-0", required(s) ? "text-amber-ink" : "text-faint")}>not explained</span>
              )}
            </div>
          ))}
          {!syms.length && levels.length ? (
            <div className="flex flex-col gap-0.5 text-[12px]">
              <span className="text-faint">Explained in</span>
              {levels.slice(0, 6).map((p) => (
                <button key={p.join("/")} type="button" onClick={() => onGo(p)} className="cursor-pointer truncate text-left text-accent hover:underline">
                  {trail(p)}
                </button>
              ))}
            </div>
          ) : null}
          {onAsk && (gaps || row.added) ? (
            <button type="button" disabled={asked} onClick={onAsk} className={QUIET + " mt-1 self-start"}>
              {asked ? "Asked — the bluprint is updating" : row.added ? "Update the bluprint" : "Explain these on the bluprint"}
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

app/components/bluprint/flash.tsx:
"use client";

import { useEffect } from "react";
import { useBluprint } from "@/components/bluprint/bluprint-context";

const LIT_MS = 2000;

/**
 * Lights what a rewrite of the bluprint just changed, where it is on screen: a row
 * or a list entry (`data-path`), or a box on the level's picture that opens a
 * changed part (`data-opens`, components/bluprint/blocks.tsx). A change deep in the
 * tree lights the row that leads to it, since its ancestors differ too
 * (lib/bluprint/share.ts). The level's own header lights only when nothing on it did,
 * which is when the change is the level's own text. Once per rewrite: walking
 * to a level later shows it as it is, unlit.
 */
export function useFlash(content: React.RefObject<HTMLElement | null>) {
  const { fresh } = useBluprint();

  useEffect(() => {
    const root = content.current;
    if (!fresh.at || !root) return;
    const css = getComputedStyle(document.documentElement);
    const ring = css.getPropertyValue("--color-accent").trim();
    const wash = css.getPropertyValue("--color-accent-surface").trim();
    // The open level, as its header names it; read when a rewrite lands,
    // not followed, since moving on is not a change.
    const header = root.querySelector<HTMLElement>("header[data-path]");
    const here = header?.dataset.path ?? "[]";
    const lit: Element[] = [];

    for (const el of root.querySelectorAll<HTMLElement>("[data-path]"))
      if (el !== header && fresh.paths.has(el.dataset.path!)) lit.push(el);
    const at: string[] = JSON.parse(here);
    for (const el of root.querySelectorAll<SVGElement>("[data-opens]")) {
      const rect = el.querySelector("rect");
      if (rect && fresh.paths.has(JSON.stringify([...at, el.dataset.opens]))) lit.push(rect);
    }
    if (!lit.length && header && fresh.paths.has(here)) lit.push(header);

    const timing = { duration: LIT_MS, easing: "ease-out" };
    for (const el of lit) {
      const now = getComputedStyle(el);
      if (el instanceof SVGElement)
        el.animate(
          [
            { stroke: ring, strokeWidth: "3", strokeOpacity: "1" },
            { stroke: now.stroke, strokeWidth: now.strokeWidth, strokeOpacity: now.strokeOpacity },
          ],
          timing,
        );
      else
        el.animate(
          [
            { boxShadow: `0 0 0 2px ${ring}`, backgroundColor: wash },
            { boxShadow: "0 0 0 2px transparent", backgroundColor: now.backgroundColor },
          ],
          timing,
        );
    }
  }, [fresh, content]);
}

app/components/bluprint/header.tsx:
"use client";

import { Fragment } from "react";
import { cn } from "@/lib/client/utils";
import { InlineMarks } from "@/components/bluprint/shapes";
import { Eyebrow, OriginMark, Prose, StateChip } from "@/components/ui/state";
import { useMayBeStale } from "@/components/chrome/crumbs";
import { Button, CodeIcon } from "@/components/ui/button";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { useRedoing } from "@/components/chrome/statusbar";
import { openReview } from "@/components/review/diff";
import type { Node } from "@/lib/bluprint/schema";
import type { Shape } from "@/lib/bluprint/view";

/* ── the node you are in ─────────────────────────────────────── */

export function Header({
  path,
  deepening,
  back,
  eyebrow,
  title,
  state,
  origin,
  alarm,
  sub,
  detail,
  unsure,
  meta,
  link,
  shape,
  onCode,
  actions,
}: {
  /** Where this level is, so it can be handed to Claude from its header. */
  path: string[];
  /** A quick section's place in being written in full: still waiting, or being written now. */
  deepening?: "queued" | "drafting";
  /** The level above, named — so "back" says where it goes. */
  back?: { label: string; path: string[]; onClick: () => void }[];
  eyebrow?: string;
  title: string;
  state?: Node["state"];
  /** Set where the reader rewrote this level's own words (lib/server/overlay.ts). */
  origin?: Node["origin"];
  alarm?: boolean;
  sub?: string;
  detail?: string;
  /** Why this level is not certain, shown with the mark it explains. */
  unsure?: string;
  meta?: string;
  /** Where the code lives, outside this page. */
  link?: { href: string; label: string };
  shape?: Shape;
  onCode?: () => void;
  /** What the reader can do to this level itself: keep an answer, fix it. */
  actions?: React.ReactNode;
}) {
  const stale = useMayBeStale(origin);
  // This level, or the section it sits in, is being redone by an update.
  const redoing = useRedoing();
  const rewriting = path.some((id) => redoing.includes(id));
  // An update rewrote this level and holds it back until asked (components/bluprint/bluprint-context.tsx).
  const { pending, apply } = useBluprint();
  return (
    <header data-path={JSON.stringify(path)} className="mb-8 border-b border-border-gray pb-7">
      {/* One toolbar row: the way back on the left, what you can do to this
          level on the right. They used to be a back link here and a column of
          mismatched buttons in a rail beside the prose, which read as parts
          from different apps (D62). */}
      <div className="mb-5 flex min-h-7 flex-wrap items-center gap-2">
        {/* The whole way down, each step a way back to it, so a level always
            says what it is part of; the last is the one Esc goes back to. */}
        {back?.map((crumb, i) => (
          <Fragment key={i}>
            {i > 0 ? <span aria-hidden className="text-muted-slate">›</span> : null}
            <Button
              variant="ghost"
              data-opens-at={JSON.stringify(crumb.path)}
              onClick={crumb.onClick}
              className={`${i === 0 ? "-ml-2.5" : ""} text-muted-slate`}
              title={i === back.length - 1 ? "Back (Esc)" : undefined}
            >
              {i === 0 ? <span aria-hidden>←</span> : null}
              {crumb.label}
            </Button>
          </Fragment>
        ))}
        {/* Where you are, as a step that goes nowhere: without it the last
            link read as the current page and took clicks meant for none. */}
        {back?.length ? (
          <>
            <span aria-hidden className="text-muted-slate">›</span>
            <span aria-current="page" className="inline-flex h-7 items-center whitespace-nowrap px-2.5 font-mono text-[11.5px] font-medium uppercase tracking-[0.04em] text-ink">
              {title}
            </span>
          </>
        ) : null}
        <span className="flex-1" />
        {pending ? (
          <span role="status" className="arrive flex items-center gap-2 text-[12.5px] text-muted-slate">
            <span aria-hidden className="size-[6px] shrink-0 rounded-full bg-accent" />
            Updated to match the code
            <Button variant="ghost" onClick={() => (apply(), openReview("turn:latest"))}>
              Show changes
            </Button>
            <Button variant="ghost" onClick={apply}>
              Refresh
            </Button>
          </span>
        ) : null}
        {onCode ? (
          <Button onClick={onCode} icon={<CodeIcon />}>
            View the code
          </Button>
        ) : null}
        {actions}
      </div>
      {deepening && !rewriting ? (
        <div role="status" className={cn("mb-5 flex max-w-[720px] items-center gap-2 border border-accent-line bg-accent-surface/60 px-3 py-2 text-[13px] text-accent", deepening === "drafting" && "shimmer")}>
          <span aria-hidden className={cn("size-[7px] shrink-0 rounded-full bg-accent", deepening === "drafting" && "animate-pulse")} />
          {deepening === "drafting"
            ? "This is a quick first version. The full one is being written now; it usually takes a minute or two and appears here by itself."
            : "This is a quick first version. The full one is written next, since you opened it, and appears here by itself."}
        </div>
      ) : null}
      {rewriting ? (
        <div role="status" className="shimmer mb-5 flex max-w-[720px] items-center gap-2 border border-amber-line bg-amber-surface/60 px-3 py-2 text-[13px] text-amber-ink">
          <span aria-hidden className="size-[7px] shrink-0 animate-pulse rounded-full bg-amber-ink" />
          Rewriting this section to match its code. It usually takes a minute or two and updates here by itself.
        </div>
      ) : null}
      <div className="max-w-[720px]">
        {eyebrow ? <Eyebrow>{eyebrow}</Eyebrow> : null}
        <div className={cn("flex flex-wrap items-center gap-x-3 gap-y-2", eyebrow && "mt-2")}>
          <h1 className="font-display text-[clamp(32px,3.2vw,46px)] font-normal leading-[1.02] tracking-[-0.018em] text-ink">
            {title}
          </h1>
          {state ? <StateChip state={state} alarm={alarm} /> : null}
          {/* Beside the state mark, never instead of it: the two answer
              different questions (see `Origin` in lib/bluprint/schema.ts). */}
          {origin ? <OriginMark origin={origin} stale={stale} /> : null}
          {shape?.kind === "marks" ? <InlineMarks ids={shape.ids} note={shape.note} /> : null}
          {shape?.kind === "count" ? (
            <span className=" border border-border-gray bg-card px-2.5 py-1 text-[12px] text-on-surface-variant">
              <span className="tnum font-semibold text-ink">{shape.value}</span> {shape.unit}
            </span>
          ) : null}
        </div>
        {sub ? (
          <p className="mt-1.5 text-[15px] leading-snug text-on-surface-variant">{sub}</p>
        ) : null}
        {/* Where this lives: one quiet line under the title, not a rail. */}
        {meta || link ? (
          <p className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-[12px] text-faint">
            {meta ? <span className="whitespace-pre-wrap font-mono text-[11.5px]">{meta}</span> : null}
            {link ? (
              <a href={link.href} target="_blank" rel="noreferrer" className="font-mono text-[11.5px] text-accent hover:underline">
                {link.label}
              </a>
            ) : null}
          </p>
        ) : null}
        {detail
          ? detail.split(/\n\s*\n/).map((para, i) => (
              <p key={i} className="mt-4 text-[14.5px] leading-relaxed text-on-surface">
                <Prose text={para} />
              </p>
            ))
          : null}
        {unsure ? (
          <p className="mt-4 border-l-2 border-amber-line bg-amber-surface/60 py-2 pl-3 pr-3 text-[13px] leading-snug text-amber-ink">
            <span className="font-semibold">Not certain: </span>
            <Prose text={unsure} />
          </p>
        ) : null}
      </div>
    </header>
  );
}

app/components/bluprint/layouts.tsx:
"use client";

import { useState } from "react";
import { cn } from "@/lib/client/utils";
import { sectionTone } from "@/components/bluprint/blocks";
import { Eyebrow, StateChip } from "@/components/ui/state";
import { useChangedCode, useBluprint } from "@/components/bluprint/bluprint-context";
import { SectionTint } from "@/components/review/diff";
import type { Edge, Node } from "@/lib/bluprint/schema";
import type { Link } from "@/lib/bluprint/coverage";
import { BLURB_LINES } from "@/lib/bluprint/view";
import { authored, openable } from "@/components/bluprint/nodes";
import { openInTab } from "@/components/chrome/tabs";

/* ── layout ──────────────────────────────────────────────────── */

/**
 * Real order, drawn as one numbered line down the left — the same rail the
 * steps inside a flow use. It never wraps, so there is no row-end arrow
 * pointing at nothing. Where the data names the hand-off ("uploads to") it is
 * written on the line; where the hand-off is only partly established the line
 * is dashed.
 */
export function Steps({
  nodes,
  edges,
  at,
  onOpen,
}: {
  nodes: Node[];
  edges: Edge[];
  at: string[];
  onOpen: (p: string[]) => void;
}) {
  return (
    <ol className="flex max-w-[880px] flex-col">
      {nodes.map((n, i) => {
        const last = i === nodes.length - 1;
        const edge = last
          ? undefined
          : edges.find((e) => e.from === n.id && e.to === nodes[i + 1].id);
        const partial = edge && edge.state !== "derived";
        return (
          <li key={n.id} className="flex gap-4">
            <div className="flex w-[22px] shrink-0 flex-col items-center pt-[15px]">
              <StepDot n={i + 1} state={n.state} />
              {last ? null : (
                <span
                  className={cn(
                    "mt-1.5 w-0 flex-1 border-l",
                    partial ? "border-dashed border-amber-line" : "border-border-strong",
                  )}
                />
              )}
            </div>
            <div className={cn("min-w-0 flex-1", last ? "" : "pb-3")}>
              <Row node={n} at={at} onOpen={onOpen} />
              {edge?.label ? (
                <p
                  className={cn(
                    "mt-2.5 pl-1 text-[11.5px] italic",
                    partial ? "text-amber-ink" : "text-faint",
                  )}
                >
                  {edge.label} {nodes[i + 1].title}
                </p>
              ) : null}
            </div>
          </li>
        );
      })}
    </ol>
  );
}


/** A set has no order, so it gets no numbers and no line — a grid. */
export function Grid({
  nodes,
  at,
  onOpen,
}: {
  nodes: Node[];
  at: string[];
  onOpen: (p: string[]) => void;
}) {
  return (
    <div className="grid max-w-[1100px] grid-cols-[repeat(auto-fill,minmax(340px,1fr))] gap-3">
      {nodes.map((n) => (
        <SectionTint key={n.id} path={[...at, n.id]}>
          <Row node={n} at={at} onOpen={onOpen} />
        </SectionTint>
      ))}
    </div>
  );
}

/**
 * The parts as an index, for when the diagram above is already the way down
 * (D40). One line each: the name, and a problem count if there is one. No
 * blurb, no block counts, no file path — the picture carries the shape of the
 * level, and this is here so a part is still reachable by keyboard, by screen
 * reader, and when a part has no box of its own.
 */
export function List({
  nodes,
  at,
  onOpen,
  hue = [],
}: {
  nodes: Node[];
  at: string[];
  onOpen: (p: string[]) => void;
  /** The order the picture above assigned its section hues, by node id. */
  hue?: string[];
}) {
  const changed = useChangedCode();
  return (
    <ul className="max-w-[560px]">
      {nodes.map((n) => {
        const go = openable(n) ? () => onOpen([...at, n.id]) : undefined;
        const sec = hue.indexOf(n.id);
        return (
          <li key={n.id}>
            <button
              data-node-id={n.id}
              data-path={JSON.stringify([...at, n.id])}
              onClick={go}
              disabled={!go}
              className={cn(
                "group flex w-full items-center gap-2.5 border-b border-border-gray/70 px-1.5 py-2.5 text-left transition-colors",
                go && "hover:bg-surface-container-low",
                "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent",
              )}
            >
              {/* The same hue the box carries upstairs. A part with no box
                  of its own gets no dot rather than a colour that matches
                  nothing — 3 of 13 levels have one. */}
              <span
                aria-hidden
                className={cn("size-[9px] shrink-0 rounded-full", sec < 0 && "opacity-0")}
                style={sec >= 0 ? { background: sectionTone(sec).ink } : undefined}
              />
              <span className="truncate text-[14px] font-medium tracking-[-0.01em] text-ink">
                {n.title}
              </span>
              <ChangeDot files={changed.get(n.id)} />
              {n.issues?.length ? (
                <span className="shrink-0 font-mono text-[10.5px] text-clay-ink">
                  ⚠ {n.issues.length}
                </span>
              ) : null}
              <span className="flex-1" />
              {go ? (
                <span
                  aria-hidden
                  className="shrink-0 text-[14px] text-faint transition-colors group-hover:text-accent"
                >
                  ›
                </span>
              ) : null}
            </button>
          </li>
        );
      })}
    </ul>
  );
}

/**
 * What a level's code imports, and what imports it, each as the section that
 * explains the other side (lib/bluprint/coverage.ts neighbours): where to read next,
 * and what a change here reaches. Grouped under the area each sits in, so a
 * long list reads as a few places rather than a heap of names. Each opens in
 * a new tab, so the level being read stays one tab back.
 */
export function Reach({ uses, usedBy }: { uses: Link[]; usedBy: Link[] }) {
  const { name: bluprint, nodeAt } = useBluprint();
  const [all, setAll] = useState<Record<string, boolean>>({});
  if (!uses.length && !usedBy.length) return null;
  const SHOWN = 12;

  const block = (label: string, gloss: string, links: Link[]) => {
    if (!links.length) return null;
    const shown = all[label] ? links : links.slice(0, SHOWN);
    const groups = new Map<string, Link[]>();
    for (const l of shown) {
      const area = l.path && nodeAt(l.path.slice(0, 1))?.title;
      const k = area || "Not on the bluprint";
      groups.set(k, [...(groups.get(k) ?? []), l]);
    }
    return (
      <div className="flex flex-col gap-2.5">
        <div className="flex items-baseline gap-2">
          <Eyebrow>{label}</Eyebrow>
          <span className="font-mono text-[11px] text-faint">{links.length}</span>
          <span className="text-[12px] text-faint">· {gloss}</span>
        </div>
        <div className="flex flex-col gap-1.5 border-l border-border-gray pl-3">
          {[...groups].map(([area, ls]) => (
            <div key={area} className="flex items-baseline gap-3">
              <span className="w-[150px] shrink-0 truncate text-[12px] text-muted-slate" title={area}>
                {area}
              </span>
              <div className="flex min-w-0 flex-wrap gap-1.5">
                {ls.map((l) => {
                  const title = `${l.via}${l.count > 1 ? ` and ${l.count - 1} more` : ""}`;
                  const leaf = l.path && nodeAt(l.path)?.title;
                  if (!l.path || !leaf)
                    return (
                      <span key={l.file} title={title} className="px-1 font-mono text-[11.5px] text-faint">
                        {l.file.split("/").pop()}
                      </span>
                    );
                  return (
                    <button
                      key={l.path.join("/")}
                      onClick={() => openInTab(bluprint, l.path!)}
                      title={`${title}\nOpens in a new tab`}
                      className="group/reach flex items-center gap-1.5 border border-border-gray px-2 py-0.5 text-[12.5px] text-ink transition-colors hover:border-accent hover:bg-surface-container-low focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent"
                    >
                      {l.path.length > 1 ? leaf : "the area itself"}
                      <span aria-hidden className="text-[11px] text-faint group-hover/reach:text-accent">
                        ↗
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
          {links.length > SHOWN ? (
            <button
              onClick={() => setAll((a) => ({ ...a, [label]: !a[label] }))}
              className="self-start text-[12px] text-faint hover:text-ink"
            >
              {all[label] ? "Show fewer" : `Show all ${links.length}`}
            </button>
          ) : null}
        </div>
      </div>
    );
  };
  return (
    <section data-pick="Uses and used by" className="flex max-w-[820px] flex-col gap-5">
      {block("Uses", "what its code imports", uses)}
      {block("Used by", "what a change here reaches", usedBy)}
    </section>
  );
}

export function Caption({ count, what, how }: { count: number; what: string; how: string }) {
  return (
    <div className="mb-3 flex items-baseline gap-2">
      <Eyebrow className="text-muted-slate">
        {count} {what}
      </Eyebrow>
      <span className="text-[12px] text-faint">· {how}</span>
    </div>
  );
}

export function Note({ children }: { children: React.ReactNode }) {
  return <p className="-mt-1 mb-4 text-[12px] italic text-faint">{children}</p>;
}

/* ── a part: named, not opened ───────────────────────────────── */

export const BLOCK_NOUN: Record<string, string> = {
  flow: "steps",
  facts: "facts",
  bluprint: "entries",
  schema: "columns",
  routes: "routes",
  chips: "kinds",
  bars: "measures",
  parts: "parts",
  table: "rows",
  sequence: "steps",
};

/**
 * What is behind the click, in a few words: the author's own `summary` when
 * there is one, else the names of the parts, else a count of what kind of
 * thing is inside — and whether real code is at the bottom of it.
 */
function inside(node: Node): string {
  if (node.summary) return node.summary;
  const kids = authored(node);
  if (kids.length) return kids.map((k) => k.title).join(" · ");
  // Code is not listed: it is behind every level now, not a destination.
  return (node.anatomy ?? [])
    .map((b) =>
      b.kind === "diagram" ? "diagram"
      : b.kind === "screen" ? `the ${b.title} screen`
      : b.kind === "example" ? "an example"
      : b.kind === "source" ? null
      // A reader's note is named as theirs here too: "what you will find if
      // you open it" is a different promise when part of it is their own.
      : b.kind === "note" ? "a note of yours"
      : `${b.rows.length} ${BLOCK_NOUN[b.kind]}`,
    )
    .filter(Boolean)
    .join(" · ");
}

/**
 * A quiet mark on a part whose code changed and that no update has rewritten
 * yet (lib/server/live.ts), naming the files on hover. Still: the bluprint is not redrawn
 * while the code is being written.
 */
function ChangeDot({ files }: { files?: string[] }) {
  if (!files?.length) return null;
  const said = `Code changed: ${files.join(", ")}. The bluprint follows once your edits settle.`;
  return <span role="img" aria-label={said} title={said} className="size-[7px] shrink-0 rounded-full bg-amber-ink" />;
}

/**
 * One part of the level: what it is, in a line, and what you will find if you
 * open it. Never its contents — those are the next step down.
 */
function Row({ node, at, onOpen }: { node: Node; at: string[]; onOpen: (p: string[]) => void }) {
  const changed = useChangedCode();
  const go = openable(node) ? () => onOpen([...at, node.id]) : undefined;
  // No path on a card at all (D42): a card says what the part IS, and the
  // level it opens says where that lives.
  const peek = inside(node);
  const count = node.shape?.kind === "count" ? `${node.shape.value} ${node.shape.unit}` : null;

  return (
    <button
      data-node-id={node.id}
      data-path={JSON.stringify([...at, node.id])}
      onClick={go}
      disabled={!go}
      className={cn(
        "group flex w-full items-start gap-3 border bg-card px-4 py-3 text-left transition-[border-color,box-shadow] duration-150",
        node.ghost ? "border-dashed border-border-strong bg-surface-container-low/60" : "border-border-gray",
        go && "hover:border-border-strong hover:shadow-panel",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent",
      )}
    >
      <span className="min-w-0 flex-1">
        <span className="flex items-center gap-2">
          <span className="truncate text-[15px] font-semibold tracking-[-0.01em] text-ink">
            {node.title}
          </span>
          <ChangeDot files={changed.get(node.id)} />
          <StateChip state={node.state} alarm={node.alarm} />
          {node.issues?.length ? (
            <span className="shrink-0 border border-clay-line bg-clay-surface px-2 py-[3px] font-mono text-[10px] leading-none text-clay-ink">
              ⚠ {node.issues.length} {node.issues.length === 1 ? "problem" : "problems"}
            </span>
          ) : null}
        </span>
        <span
          className="mt-0.5 block text-[13px] leading-snug text-on-surface-variant [display:-webkit-box] [overflow:hidden] [-webkit-box-orient:vertical]"
          style={{ WebkitLineClamp: BLURB_LINES }}
        >
          {node.sub}
        </span>
        {count || peek ? (
          <span className="mt-1.5 block truncate text-[11.5px] text-muted-slate">
            {[count, peek].filter(Boolean).join(" · ")}
          </span>
        ) : null}
      </span>
      {go ? (
        <span
          aria-hidden
          className="pt-0.5 text-[15px] text-faint transition-colors group-hover:text-accent"
        >
          ›
        </span>
      ) : null}
    </button>
  );
}

function StepDot({ n, state }: { n: number; state: Node["state"] }) {
  return (
    <span
      className={cn(
        "flex size-[22px] shrink-0 items-center justify-center rounded-full border font-mono text-[10.5px] font-semibold",
        state === "derived"
          ? "border-accent-line bg-accent-surface text-accent"
          : "border-amber-line bg-amber-surface text-amber-ink",
      )}
    >
      {n}
    </span>
  );
}

app/components/bluprint/level.tsx:
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { cn } from "@/lib/client/utils";
import { AnatomyView, type RowCtx } from "@/components/bluprint/anatomy";
import { TableGlyph } from "@/components/bluprint/anatomy/glyphs";
import { DocsList, Example, ExplainedBlock, WatchOut, isExplained, sectionOrder } from "@/components/bluprint/blocks";
import { Building, DraftNote, Stages, NoBluprint, isBuilding, useDrawIn } from "@/components/projects/building";
import { CodePopup, ExplainToggle, Explainer, StartHere, parseAt, useExplain, type CodeFocus } from "@/components/bluprint/explain";
import { Glossary, SymbolLinks } from "@/components/ui/state";
import { Button } from "@/components/ui/button";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { openFile } from "@/components/bluprint/code";
import { AgentIcon, CLAUDE, useAgents } from "@/components/agent/agents";
import { handTo, sectionKey, usePicked } from "@/lib/agent/context";
import { FixAndKeep, onAnswer } from "@/components/review/keep";
import { BlockDiffView, RemovedSections, useBlockDiffs } from "@/components/review/diff";
import type { Exchange } from "@/lib/agent/keep";
import { codeAt, describeProblems, problemSpans } from "@/lib/bluprint/build";
import { STATIC_BLUPRINT, readSource } from "@/lib/bluprint/source";
import type { Anatomy, Node } from "@/lib/bluprint/schema";
import { citations, neighbours, nodesAt, symbolsOf } from "@/lib/bluprint/coverage";
import { useFiles } from "@/components/bluprint/files";
import { useDesktop } from "@/lib/client/platform";
import { projectAction } from "@/lib/client/api";
import { authored, nearBottom, setNote, siblingEdges } from "@/components/bluprint/nodes";
import { Header } from "@/components/bluprint/header";
import { BLOCK_NOUN, Caption, Grid, List, Note, Reach, Steps } from "@/components/bluprint/layouts";

/**
 * The last answer Claude gave, so any level can offer to keep it. Held here
 * rather than per level: the reader asks from one level and may well want it on
 * the one they moved to, and a level unmounting must not forget it.
 */
function useLatestAnswer(): Exchange | null {
  const [answer, setAnswer] = useState<Exchange | null>(null);
  useEffect(() => onAnswer(setAnswer), []);
  return answer;
}

/**
 * Asks the default agent (Settings) about a section's problems, all of them,
 * straight away: Claude takes them as context with the question, and the
 * button follows them there; another agent gets them in its prompt with the
 * question, sent. In the desktop app, where the agents run, and on a published
 * bluprint, to its Claude panel.
 */
function HandProblems({ node, path }: { node: Node; path: string[] }) {
  const bluprint = useBluprint();
  const { main } = useAgents();
  const desktop = useDesktop();
  const key = `${sectionKey(path)}#problems`;
  const status = usePicked(key);
  const [pasted, setPasted] = useState(false);
  useEffect(() => {
    if (!pasted) return;
    const timer = setTimeout(() => setPasted(false), 2500);
    return () => clearTimeout(timer);
  }, [pasted]);
  if (!desktop && !STATIC_BLUPRINT) return null;
  const claude = main.id === CLAUDE.id;
  const label = claude
    ? status === "queued"
      ? "Asking Claude…"
      : status === "sent"
        ? "Sent to Claude — ask again"
        : "Ask Claude"
    : pasted
      ? `Sent to ${main.label}`
      : `Ask ${main.label}`;
  return (
    <Button
      size="sm"
      tone="alarm"
      icon={<AgentIcon id={main.id} />}
      disabled={claude && status === "queued"}
      onClick={async () => {
        // The code goes along, so the agent answers from it instead of
        // spending calls finding it; a file it cannot read is left out.
        const read = await Promise.all(
          problemSpans(bluprint, path).map(async (s) => {
            const r = await readSource({ bluprint: bluprint.name, ...s }).catch(() => null);
            return r && "slice" in r ? { ...s, end: s.start + r.slice.code.split("\n").length - 1, code: r.slice.code } : null;
          }),
        );
        const source = read.filter((s) => s !== null);
        handTo(
          main.id,
          { key, title: `Problems in ${node.title}`, text: describeProblems(bluprint, path, source) },
          source.length
            ? `Look into the problems in "${node.title}" from the bluprint. The code each one points at is attached: check each against it, explain what goes wrong, and suggest a fix. Read more of the repo only if what is attached is not enough.`
            : `Look into the problems in "${node.title}" from the bluprint: check each against the code, explain what goes wrong, and suggest a fix.`,
        );
        if (!claude) setPasted(true);
      }}
      title={
        claude
          ? "Asks Claude about every problem here, with its section and code"
          : `Asks ${main.label} about every problem here, with its section and code`
      }
    >
      {label}
    </Button>
  );
}

/** What a whole block is called when it is handed over. */
function blockLabel(b: Anatomy): string {
  if ("caption" in b && b.caption) return b.caption;
  if (b.kind === "screen") return `The ${b.title} screen`;
  if (b.kind === "schema") return `The ${b.table} table`;
  if (b.kind === "source") return b.file;
  return BLOCK_NOUN[b.kind] ? `The ${BLOCK_NOUN[b.kind]}` : b.kind;
}

/* ── levels ──────────────────────────────────────────────────── */

/**
 * One open node, explained. Top to bottom: what it is (header), the picture of
 * how it fits together, its own data — tables, screens, who talks to whom —
 * then its parts to go deeper, what to watch out for, and last, folded, the
 * code (D34).
 *
 * A level still shows ONE step of depth: a part below is named, never opened
 * in place (D31). What changed is that the open level itself now carries
 * enough to be understood without reading the code.
 */
export function Level({
  node,
  path,
  ctx,
  onOpen,
}: {
  node: Node;
  path: string[];
  ctx: RowCtx;
  onOpen: (p: string[]) => void;
}) {
  const bluprint = useBluprint();
  const { RUN, nodeAt } = bluprint;
  const kids = authored(node);
  const parent = path.length > 1 ? nodeAt(path.slice(0, -1)) : null;
  // The empty path is the repository itself (D60): nothing above it to go back to.
  const top = path.length === 0;
  const note = setNote(node);
  const sequence = node.group?.ordering === "sequence";
  const blocks = node.anatomy ?? [];
  // Which parts a box on this level's diagram already opens — those drive the
  // list below down to a quiet index (D40).
  const onDiagram = new Set(
    blocks
      .flatMap((b) => (b.kind === "diagram" ? b.boxes : []))
      .map((box) => box.opens)
      .filter((id): id is string => Boolean(id) && kids.some((k) => k.id === id)),
  );
  // The order the picture assigns its section hues, so the list below can
  // carry the same ones. Taken from the first diagram that leads anywhere —
  // the same one whose boxes the reader just looked at.
  // A box may open a row-built child too (check.ts allows it), so owning is
  // tested against every child, not only the authored ones listed below.
  const owns = (id: string) => Boolean(node.children?.some((k) => k.id === id));
  const hueOrder = sectionOrder(
    blocks.find(
      (b): b is Extract<Anatomy, { kind: "diagram" }> =>
        b.kind === "diagram" && b.boxes.some((x) => x.opens && owns(x.opens)),
    ) ?? { kind: "diagram", caption: "", boxes: [], arrows: [] },
    owns,
  );
  // The code is the last layer: a level with parts below it points down at
  // them, and only a level with nothing below it shows its lines — opened
  // over the page from the step that explains them, or all at once from the
  // header, never listed under the level (D68).
  const code = node.children?.length ? [] : codeAt(bluprint, path);
  const [codeFocus, setCodeFocus] = useState<CodeFocus | null>(null);
  const showStep = (at: string, heading: string, detail?: string) => {
    const ref = parseAt(at);
    if (ref) setCodeFocus({ heading, detail, refs: [ref] });
  };
  const levelCtx: RowCtx = { ...ctx, onStepCode: showStep };
  const [explainOn] = useExplain();
  const index = useFiles()?.index ?? null;
  const key = path.join("/");
  // eslint-disable-next-line react-hooks/exhaustive-deps -- `key` is `path` by value
  const reach = useMemo(() => neighbours(bluprint.L0, index, path), [bluprint.L0, index, key]);
  const walks = bluprint.OVERVIEW?.walkthroughs ?? (explainOn && bluprint.OVERVIEW?.walkthrough ? [bluprint.OVERVIEW.walkthrough] : []);
  // Each indexed symbol a level cites, by name, to the deepest level citing it;
  // a name two places define links nowhere rather than to the wrong one.
  const symbols = useMemo(() => {
    const cited = citations(bluprint.L0);
    const at = new Map<string, string[] | null>();
    for (const [file, f] of Object.entries(index?.files ?? {}))
      for (const s of symbolsOf(cited, file, f)) {
        const p = s.by[0]?.path;
        if (!p) continue;
        const prev = at.get(s.name);
        at.set(s.name, prev === undefined || prev?.join("/") === p.join("/") ? p : null);
      }
    return at;
  }, [bluprint.L0, index]);
  const linkOf = (name: string) => {
    const p = symbols.get(name.replace(/\(.*\)$/, "")) ?? symbols.get(name.replace(/\(.*\)$/, "").split(".").pop()!);
    return p && p.join("/") !== key ? () => onOpen(p) : undefined;
  };
  // A scenery box's code, opened at the section that explains it: the deepest
  // citing that line, else the root that owns the file, else the file itself.
  const openRef = (ref: string) => {
    const m = /^(.+?)(?::(\d+))?(?:-\d+)?$/.exec(ref);
    if (!m) return;
    const cited = citations(bluprint.L0);
    const hit = m[2] ? nodesAt(cited, m[1], +m[2])[0] : (cited.get(m[1]) ?? []).slice().sort((a, b) => a.path.length - b.path.length)[0];
    const root = index?.files[m[1]]?.roots.find((r) => bluprint.L0.some((n) => n.id === r));
    if (hit) onOpen(hit.path);
    else if (root) onOpen([root]);
    else openFile(path, m[1], m[2] ? +m[2] : undefined);
  };
  // Only a bluprint made with the plain-words layer offers the toggle.
  const explains = Boolean(bluprint.OVERVIEW?.explain || bluprint.L0.some((r) => r.explain));
  const trail = [RUN.repo, ...path.map((_, i) => nodeAt(path.slice(0, i + 1))?.title ?? "")];
  const answer = useLatestAnswer();
  // Empty outside diff mode, so the block render below is unchanged then.
  const blockDiffs = useBlockDiffs(path);
  // Two or more data shapes (a table, a file's fields, a stored value) are one
  // section of names, each opening its own body, instead of a stack of full
  // cards. Not in a diff that touches one: the red and green must be on screen.
  const shapes = blocks.flatMap((b, i) => (b.kind === "schema" || b.kind === "example" ? [i] : []));
  const grouped = shapes.length > 1 && !shapes.some((i) => blockDiffs.has(i));
  // A bluprint still being made (D69): until its overview lands the repository's
  // level is the run itself, and a root still being checked is a draft.
  const run = top && isBuilding(bluprint.progress, Boolean(bluprint.OVERVIEW)) ? bluprint.progress : undefined;
  const [watched, setWatched] = useState(false);
  if (run && !watched) setWatched(true);
  const column = useRef<HTMLDivElement>(null);
  useDrawIn(column, top && watched && !run);
  const draft = !top && Boolean(nodeAt(path.slice(0, 1))?.draft);
  // A quick section still to be written in full (pipeline.ts, --fast): the
  // reader opening it asks for it next, and its header says what is coming.
  const section = top ? undefined : path[0];
  const queued = section && bluprint.progress?.stage === "deepen" ? bluprint.progress.roots.find((r) => r.id === section) : undefined;
  const deepening = queued?.status === "queued" || queued?.status === "drafting" ? queued.status : undefined;
  useEffect(() => {
    if (deepening === "queued" && section) void projectAction({ action: "focus", id: bluprint.name, section }).catch(() => {});
  }, [deepening, section, bluprint.name]);
  // A project opened without a bluprint, and no run making one (lib/server/bluprints.ts, noBluprint).
  const noBluprint = top && !STATIC_BLUPRINT && !bluprint.progress && !node.children?.length && !blocks.length;

  return (
    <Glossary.Provider value={explainOn ? (bluprint.OVERVIEW?.glossary ?? []) : []}>
    <SymbolLinks.Provider value={linkOf}>
      <Header
        path={path}
        deepening={deepening}
        back={
          top
            ? undefined
            : path.slice(0, -1).reduce(
                (crumbs, _, i) => [
                  ...crumbs,
                  { label: nodeAt(path.slice(0, i + 1))?.title ?? "", path: path.slice(0, i + 1), onClick: () => onOpen(path.slice(0, i + 1)) },
                ],
                [{ label: RUN.repo, path: [] as string[], onClick: () => onOpen([]) }],
              )
        }
        eyebrow={top ? undefined : `Inside ${parent?.title ?? RUN.repo}`}
        title={node.title}
        state={node.state}
        origin={node.origin}
        alarm={node.alarm}
        // A row-built node's fallback sub is "Inside <parent>", which the
        // eyebrow already says.
        sub={node.sub === `Inside ${parent?.title}` ? undefined : node.sub}
        detail={node.detail}
        unsure={node.state === "derived" ? undefined : node.unsure}
        meta={
          top
            ? RUN.commit ? `${RUN.files} files · commit ${RUN.commit}` : undefined
            : !nearBottom(node)
            ? undefined
            : node.footprint
              ? `${node.footprint.dirs.join("  ")}  ·  ${node.footprint.files} files`
              : node.evidence
        }
        link={top && RUN.url && RUN.commit ? { href: `${RUN.url}/tree/${RUN.commit}`, label: `${RUN.url.replace(/^https:\/\//, "")} ↗` } : undefined}
        shape={node.shape}
        onCode={code.length ? () => setCodeFocus({ heading: `The code behind ${node.title}`, refs: code, verified: node.verified }) : undefined}
        actions={
          <>
            {explains ? <ExplainToggle /> : null}
            <FixAndKeep path={path} answer={answer} />
          </>
        }
      />

      {/* One hairline between every block, the full width of the level, so it
          is plain where one thing ends and the next begins — a picture under
          a table is its own thing, not more of the table. Each block's width
          cap is on an inner box, so the line never stops at a ragged edge. */}
      {draft ? (
        <div className="mb-8">
          <DraftNote detail={bluprint.progress?.roots.find((r) => r.id === path[0])?.detail} />
        </div>
      ) : null}
      <div
        ref={column}
        className={cn("flex flex-col [&>*+*]:mt-10 [&>*+*]:border-t [&>*+*]:border-border-gray [&>*+*]:pt-10", draft && "opacity-60")}
      >
        {run ? <Building progress={run} onOpen={onOpen} /> : null}
        {noBluprint ? <NoBluprint id={bluprint.name} /> : null}
        {top && !run && bluprint.progress && bluprint.progress.stage !== "done" ? <Stages progress={bluprint.progress} /> : null}
        {/* For a reader new to all of this: the level in plain words, before
            any of the terse parts. */}
        {explainOn && node.explain ? <Explainer owner={node.id} explain={node.explain} ctx={levelCtx} /> : null}

        {(run ? [] : blocks).map((b, i) =>
          grouped && shapes.includes(i) ? (
            i === shapes[0] ? (
              <DataShapes key={i} owner={node.id} blocks={shapes.map((j) => blocks[j] as DataBlock)} ctx={levelCtx} />
            ) : null
          ) : blockDiffs.has(i) ? (
            <div key={i} data-pick={blockLabel(b)}>
              <div className={b.kind === "diagram" ? "" : "max-w-[1100px]"}>
                <BlockDiffView block={b} diff={blockDiffs.get(i)!} />
              </div>
            </div>
          ) : isExplained(b) ? (
            <div key={i} data-pick={blockLabel(b)}>
              <div className={b.kind === "diagram" ? "" : "max-w-[1100px]"}>
                <ExplainedBlock
                  block={b}
                  onOpen={(id) =>
                    owns(id) ? onOpen([...path, id]) : undefined
                  }
                  hrefFor={(id) =>
                    `?${[...path, id].map((p) => `at=${encodeURIComponent(p)}`).join("&")}`
                  }
                  onCode={showStep}
                  onRef={openRef}
                />
              </div>
            </div>
          ) : (
            // The older blocks are typeset for a 340px card (11px rows); zoom
            // lifts them to reading size without forking their type scale.
            <div key={i} data-pick={blockLabel(b)}>
              <div className="max-w-[900px] [zoom:1.18]">
                <AnatomyView owner={node.id} blocks={[b]} ctx={levelCtx} />
              </div>
            </div>
          ),
        )}

        {/* When every part is a box on the picture, the picture is the list. */}
        {kids.length && onDiagram.size < kids.length && !run ? (
          <section>
            <Caption
              count={kids.length}
              what={kids.length === 1 ? "part" : "parts"}
              how={
                onDiagram.size
                  ? `${onDiagram.size} of them on the picture above`
                  : sequence
                    ? "in order — open one to go deeper"
                    : "open one to go deeper"
              }
            />
            {note ? <Note>{note}</Note> : null}
            {sequence ? (
              <Steps nodes={kids} edges={siblingEdges(node, kids)} at={path} onOpen={onOpen} />
            ) : onDiagram.size ? (
              // The picture is the way down, so the list stops competing with
              // it: names and problems, no cards, no blurbs, no paths (D40).
              <List nodes={kids} at={path} onOpen={onOpen} hue={hueOrder} />
            ) : (
              <Grid nodes={kids} at={path} onOpen={onOpen} />
            )}
          </section>
        ) : null}

        {/* A part the commit deleted stays on screen, in red: the whole point
            of a diff is seeing what went, beside what replaced it. Outside the
            parts section, because a level whose only part was deleted has no
            parts left to hang it under — and that is when it matters most.
            Renders nothing when there are none, diff mode or not. */}
        <RemovedSections path={path} />

        {!run ? <Reach uses={reach.uses} usedBy={reach.usedBy} /> : null}

        {/* The repository's way in comes after its picture: the walkthroughs
            open parts the reader has just seen drawn. A bluprint from before they
            were core keeps its one under the Explain layer. */}
        {top && !run && walks.length ? <StartHere walkthroughs={walks} onOpen={onOpen} /> : null}

        {node.issues?.length ? (
          <div>
            <div className="max-w-[820px]">
              <WatchOut issues={node.issues} action={<HandProblems node={node} path={path} />} onCode={showStep} />
            </div>
          </div>
        ) : null}

        {node.docs?.length ? (
          <div>
            <div className="max-w-[820px]">
              <DocsList refs={node.docs} />
            </div>
          </div>
        ) : null}

      </div>

      {codeFocus ? (
        <CodePopup focus={codeFocus} trail={trail} owner={node.id} ctx={ctx} onClose={() => setCodeFocus(null)} />
      ) : null}
    </SymbolLinks.Provider>
    </Glossary.Provider>
  );
}

/* ── data shapes ─────────────────────────────────────────────── */

type DataBlock = Extract<Anatomy, { kind: "schema" | "example" }>;

/** A shape's name, what it is in a few words, and how much is inside. */
function shapeLabel(b: DataBlock): { name: string; gloss?: string; size: string } {
  if (b.kind === "schema") {
    const file = /\.\w+$/.test(b.table);
    return { name: b.table, size: `${b.rows.length} ${file ? "fields" : "columns"}` };
  }
  const [name, ...rest] = b.caption.split(" — ");
  return { name, gloss: rest.join(" — ") || undefined, size: "example" };
}

/**
 * The level's data shapes, listed by name; each opens in place to its fields
 * or its example, the way the code drawer's places do.
 */
function DataShapes({ owner, blocks, ctx }: { owner: string; blocks: DataBlock[]; ctx: RowCtx }) {
  const [open, setOpen] = useState<Set<number>>(() => new Set());
  const labels = blocks.map(shapeLabel);
  const what = labels.every((l) => /\.\w+$/.test(l.name))
    ? "files"
    : blocks.every((b) => b.kind === "schema")
      ? "tables"
      : "shapes of data";
  const toggle = (i: number) =>
    setOpen((was) => {
      const next = new Set(was);
      if (!next.delete(i)) next.add(i);
      return next;
    });
  return (
    <section>
      <Caption count={blocks.length} what={what} how="open one to see what is in it" />
      <ul className="flex max-w-[1100px] flex-col gap-2">
        {blocks.map((b, i) => {
          const { name, gloss, size } = labels[i];
          const shown = open.has(i);
          return (
            <li key={i} data-pick={blockLabel(b)} className="overflow-hidden border border-border-gray bg-card">
              <button
                onClick={() => toggle(i)}
                aria-expanded={shown}
                className="flex w-full items-baseline gap-3 px-4 py-2.5 text-left transition-colors hover:bg-surface-container-low"
              >
                <span className="self-center">{b.kind === "schema" ? <TableGlyph /> : <ExampleGlyph />}</span>
                <span className="shrink-0 font-mono text-[13px] font-semibold text-ink">{name}</span>
                {gloss ? <span className="min-w-0 truncate text-[13px] text-on-surface-variant">{gloss}</span> : null}
                <span className="ml-auto shrink-0 font-mono text-[11px] text-faint">{size}</span>
                <span aria-hidden className="text-[11px] text-faint">{shown ? "▾" : "▸"}</span>
              </button>
              {shown ? (
                <div className="border-t border-border-gray">
                  {b.kind === "schema" ? (
                    // The schema rows are typeset for a 340px card; zoom lifts them as elsewhere on a level.
                    <div className="[zoom:1.18]">
                      <AnatomyView owner={owner} blocks={[b]} ctx={ctx} headless />
                    </div>
                  ) : (
                    <div className="p-3">
                      <Example block={b} bare />
                    </div>
                  )}
                </div>
              ) : null}
            </li>
          );
        })}
      </ul>
    </section>
  );
}

/** A page with lines: a stored value, as the table glyph is a table. */
function ExampleGlyph() {
  return (
    <svg width="11" height="11" viewBox="0 0 12 12" fill="none" aria-hidden="true">
      <path d="M2.5 1.5h5l2 2v7h-7z" stroke="currentColor" strokeWidth="1" strokeLinejoin="round" className="text-muted-slate" />
      <path d="M4 6h4M4 8h3" stroke="currentColor" strokeWidth="1" className="text-muted-slate" />
    </svg>
  );
}

