/**
 * The things a card can show instead of another paragraph.
 *
 * "There are no logos, diagrams, or anything that makes it appealing. Right now
 * it's very text-heavy." The shapes in `Shape` (lib/bluprint/view.ts) are the answer, and the rule
 * that governs them is D19's: an invented picture is the same failure as an
 * invented arrow. Every glyph here names a real dependency in the repo's
 * package.json.
 *
 * Everything is hand-authored inline SVG. There is no icon library in this
 * project and there is deliberately not going to be one — a brand-mark set is
 * nine paths, and a dependency that ships four thousand icons to render nine is
 * a worse trade than the drawing.
 *
 * On the marks specifically: these are simplified geometric interpretations —
 * a recognisable silhouette at 14px, single-colour, inheriting `currentColor`.
 * They are NOT the corporate artwork and do not claim to be. The job is "you
 * recognise this is the AWS one before you read the word AWS", which a
 * silhouette does at a glance and a faithful reproduction would do no better at
 * this size.
 */

/**
 * The glyph table, keyed by the id a bluprint's chips use.
 *
 * Each entry draws inside a 16×16 box and uses `currentColor` only, so a chip
 * can tint the pair — glyph and name — as one thing. Anything not in here
 * renders as a name-only chip rather than crashing or guessing a drawing: an id
 * we have no mark for is a missing fact, and a wrong glyph would assert one.
 */
const MARKS: Record<string, { name: string; draw: React.ReactNode }> = {
  aws: {
    name: "AWS",
    // The smile, and the wordmark's stacked-block feel above it.
    draw: (
      <>
        <path
          d="M3 6.4c1.1.7 2.9 1.1 5 1.1s3.9-.4 5-1.1"
          stroke="currentColor"
          strokeWidth="1.3"
          strokeLinecap="round"
          fill="none"
        />
        <path
          d="M2.2 10.6c2 1.5 4.4 2.2 5.8 2.2s3.8-.7 5.8-2.2"
          stroke="currentColor"
          strokeWidth="1.3"
          strokeLinecap="round"
          fill="none"
        />
        {/* The smile's upward flick. Solid, not stroked — a 1.3px open chevron
            at this size disappeared and the mark read as two plain curves. */}
        <path d="M12.3 9.5l2.2-.5-.6 2.2z" fill="currentColor" />
      </>
    ),
  },
  bedrock: {
    name: "Bedrock",
    // Strata: a foundation model service drawn as bedded layers.
    draw: (
      <>
        <path d="M2 11.5h12" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
        <path d="M3 8.7h10" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
        <path d="M4.5 6h7" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
        <path d="M6.5 3.4h3" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
      </>
    ),
  },
  s3: {
    name: "S3",
    // A straight-sided bucket with a banded seam. The tapered version read as a
    // trash can at 14px — the taper plus the rim ellipse IS a wastebasket
    // silhouette, and "delete" is the worst possible wrong reading for storage.
    draw: (
      <>
        <path d="M3.2 3.6h9.6v8.8a1.2 1.2 0 01-1.2 1.2H4.4a1.2 1.2 0 01-1.2-1.2z" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" fill="none" />
        <ellipse cx="8" cy="3.6" rx="4.8" ry="1.7" stroke="currentColor" strokeWidth="1.2" fill="none" />
        <path d="M3.2 8.6h9.6" stroke="currentColor" strokeWidth="1.1" />
      </>
    ),
  },
  supabase: {
    name: "Supabase",
    // The two offset lightning halves, as one folded bolt.
    draw: (
      <path
        d="M8.8 1.6L3.1 8.4a.5.5 0 00.38.83H7.5v5.2l5.7-6.8a.5.5 0 00-.38-.83H8.8z"
        stroke="currentColor"
        strokeWidth="1.2"
        strokeLinejoin="round"
        fill="none"
      />
    ),
  },
  openai: {
    name: "OpenAI",
    // The interlocked hexagonal knot, reduced to a hexagon with its seams.
    draw: (
      <>
        <path
          d="M8 1.9l5.3 3.05v6.1L8 14.1 2.7 11.05v-6.1z"
          stroke="currentColor"
          strokeWidth="1.2"
          strokeLinejoin="round"
          fill="none"
        />
        <path d="M8 5.1v5.8M5.3 6.6l5.4 2.8M10.7 6.6L5.3 9.4" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" />
      </>
    ),
  },
  postgres: {
    name: "Postgres",
    // Cylinder. The elephant does not survive 14px.
    draw: (
      <>
        <ellipse cx="8" cy="4" rx="4.8" ry="2" stroke="currentColor" strokeWidth="1.2" fill="none" />
        <path d="M3.2 4v8c0 1.1 2.15 2 4.8 2s4.8-.9 4.8-2V4" stroke="currentColor" strokeWidth="1.2" fill="none" />
        <path d="M3.2 8c0 1.1 2.15 2 4.8 2s4.8-.9 4.8-2" stroke="currentColor" strokeWidth="1.1" fill="none" />
      </>
    ),
  },
  nextjs: {
    name: "Next.js",
    // The circle with the rising diagonal of the N.
    draw: (
      <>
        <circle cx="8" cy="8" r="6.2" stroke="currentColor" strokeWidth="1.2" fill="none" />
        <path d="M5.6 10.8V5.2l5.2 6.6" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" fill="none" />
        <path d="M10.4 5.2v4" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
      </>
    ),
  },
  zod: {
    name: "Zod",
    // The shield-ish chevron with the Z inside it.
    draw: (
      <>
        <path d="M2.4 4.6L8 1.8l5.6 2.8L8 14.2z" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" fill="none" />
        <path d="M5.6 5.6h4.8L5.6 9.9h4.8" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round" fill="none" />
      </>
    ),
  },
  pdf: {
    name: "pdf-lib",
    // A folded page. The only one of these that is a file format, not a vendor.
    draw: (
      <>
        <path d="M3.4 1.6h5.2L12.6 5.4v9H3.4z" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" fill="none" />
        <path d="M8.4 1.7v3.6h3.8" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" fill="none" />
        {/* Text lines, not the letters "PDF" — three glyphs inside a 9px page
            collapse into a smudge. Ruled lines still say "document". */}
        <path d="M5.6 8.4h4.8M5.6 10.6h4.8M5.6 12.2h2.6" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" />
      </>
    ),
  },

  /* explorify — every id below is a real dependency of that repo: `expo` in
     package.json, `react-native-google-places-autocomplete` in package.json,
     Flask in api/requirements.txt, and Deno as the runtime the two
     supabase/functions/ files import from deno.land and esm.sh. */
  expo: {
    name: "Expo",
    // The chevron, open at the base.
    draw: (
      <path
        d="M8 2.6l5.6 10.4h-2.3L8 6.9 4.7 13H2.4z"
        stroke="currentColor"
        strokeWidth="1.2"
        strokeLinejoin="round"
        fill="none"
      />
    ),
  },
  googlemaps: {
    name: "Google Places",
    // A bluprint pin: the address field is Places autocomplete.
    draw: (
      <>
        <path d="M8 14.4s4.6-4.7 4.6-8.1a4.6 4.6 0 00-9.2 0c0 3.4 4.6 8.1 4.6 8.1z" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" fill="none" />
        <circle cx="8" cy="6.3" r="1.6" stroke="currentColor" strokeWidth="1.1" fill="none" />
      </>
    ),
  },
  flask: {
    name: "Flask",
    // A lab flask — the Python API.
    draw: (
      <>
        <path d="M6.4 2.2v4.3L2.9 12.7a.9.9 0 00.8 1.3h8.6a.9.9 0 00.8-1.3L9.6 6.5V2.2" stroke="currentColor" strokeWidth="1.2" strokeLinejoin="round" fill="none" />
        <path d="M5.4 2.2h5.2M4.6 10.4h6.8" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" />
      </>
    ),
  },
  deno: {
    name: "Deno",
    // A circle with an eye: the edge functions' runtime.
    draw: (
      <>
        <circle cx="8" cy="8" r="6.2" stroke="currentColor" strokeWidth="1.2" fill="none" />
        <circle cx="9.6" cy="5.8" r="0.9" fill="currentColor" />
        <path d="M6.2 9.2c.8 1.6 1.3 3 1.4 4.8" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" fill="none" />
      </>
    ),
  },
};

/** The brand marks there is a drawing for — the only ids a generated bluprint may use. */
export const MARK_IDS = Object.keys(MARKS);

/**
 * The technologies behind a level, inline in its title row (D39). They used to
 * own a 300px column beside the header — tiny glyphs in a big empty space —
 * so they now sit where the eye already is. The note becomes the tooltip.
 */
export function InlineMarks({ ids, note }: { ids: string[]; note?: string }) {
  return (
    <span className="inline-flex flex-wrap items-center gap-1.5" title={note}>
      {ids.map((id) => {
        const mark = MARKS[id];
        return (
          <span
            key={id}
            className="inline-flex items-center gap-1.5 border border-border-gray bg-card px-2.5 py-1 text-[12px] font-medium text-on-surface-variant"
          >
            {mark ? (
              <svg width="15" height="15" viewBox="0 0 16 16" aria-hidden className="shrink-0">
                {mark.draw}
              </svg>
            ) : null}
            {mark ? mark.name : id}
          </span>
        );
      })}
    </span>
  );
}

app/components/bluprint/source-view.tsx:
"use client";

import { cn } from "@/lib/client/utils";
import { rowId, type Anatomy } from "@/lib/bluprint/schema";
import { useCallback, useEffect, useRef, useState } from "react";
import type { Slice, WriteResult } from "@/lib/server/repo";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { readSource, SOURCE_URL } from "@/lib/bluprint/source";
import { useLocation } from "@/components/chrome/crumbs";
import { openFileInTab } from "@/components/bluprint/code";
import { CodeEditor } from "@/components/ui/editor";
import type { RowCtx } from "@/components/bluprint/anatomy";
import { rowClass } from "@/components/bluprint/anatomy/layout";
import { FileGlyph } from "@/components/bluprint/anatomy/glyphs";

/**
 * The bottom of the bluprint, read from the real repository.
 *
 * Three things are kept strictly apart, and the separation is the point:
 *
 *   the CODE       verbatim from a real file at a real line, read from disk
 *   the WHY        synthesized commentary, in its own tinted band
 *   the FINDING    when disk no longer says what the bluprint quoted
 *
 * The fixture's text is still what renders first, so the card is readable
 * before any request finishes and readable at all if the repo is not there.
 * Once the read lands, disk wins — with a mark saying it drifted, if it did.
 * Silently swapping fresh code under a stale explanation is the exact failure
 * this project exists to study, so it is the one thing that cannot happen here.
 */
export function SourceView({
  owner,
  block,
  ctx,
}: {
  owner: string;
  block: Extract<Anatomy, { kind: "source" }>;
  ctx: RowCtx;
}) {
  const id = rowId(owner, "source");
  const isLit = ctx.traced === id;

  const quoted = block.code.replace(/\n$/, "");
  const end = block.start + quoted.split("\n").length - 1;

  const [slice, setSlice] = useState<Slice | null>(null);
  const [failed, setFailed] = useState<string | null>(null);
  // Null until the reader types: the pane is always editable, and only a
  // change makes a draft (D74).
  const [draft, setDraft] = useState<string | null>(null);
  const [saved, setSaved] = useState<WriteResult | null>(null);
  const { name: bluprint } = useBluprint();
  const { path } = useLocation();

  /**
   * One read of the repository, resolved to what the UI should show.
   *
   * Pure apart from the read: it sets no state, which is what lets the effect
   * below subscribe to it rather than call setState in its own body.
   */
  const read = useCallback(
    async (signal?: AbortSignal) => {
      try {
        const r = await readSource({ bluprint, file: block.file, start: block.start, end, fixture: quoted }, signal);
        return "slice" in r ? { slice: r.slice, failed: null } : { slice: null, failed: r.refused };
      } catch {
        return { slice: null, failed: "unreachable" };
      }
    },
    [bluprint, block.file, block.start, end, quoted],
  );

  // Aborted on unmount and whenever the block changes, so a slow response for
  // one source block can never land as the state of a different one.
  useEffect(() => {
    const ac = new AbortController();
    read(ac.signal).then((r) => {
      if (ac.signal.aborted) return;
      setSlice(r.slice);
      setFailed(r.failed);
    });
    return () => ac.abort();
  }, [read]);

  // Disk is the truth once we have it; the fixture is the fallback.
  const shown = slice?.code ?? quoted;
  const dirty = draft !== null && draft !== shown;
  const drifted = slice != null && !slice.matchesFixture;

  // Nothing is ever written without an explicit act — the Save button or ⌘S.
  // Never a keystroke, a blur, a timer or navigation.
  async function save() {
    if (!dirty) return;
    const res = await fetch("/api/source", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        bluprint,
        file: block.file,
        start: block.start,
        end,
        code: draft,
        // What we read is what we claim is there. A write built on anything
        // else is the stale-read clobber the contract exists to refuse.
        expected: shown,
      }),
    });
    const body = (await res.json()) as WriteResult;
    setSaved(body);
    if (body.ok) {
      setDraft(null);
      // Re-read rather than trusting the draft: what is now on disk is the
      // only thing this card is allowed to show as the file's contents.
      const r = await read();
      setSlice(r.slice);
      setFailed(r.failed);
    }
  }

  return (
    <div
      data-pick={`${block.file}:${block.start}`}
      data-pick-code={`${block.file}:${block.start}-${end}`}
      className={cn(
        "overflow-hidden border bg-card",
        drifted ? "border-amber-line" : isLit ? "border-accent" : "border-border-gray",
      )}
    >
      <div
        className={cn(
          "flex items-center gap-2 border-b border-border-gray px-3 py-1.5",
          drifted ? "bg-amber-surface" : "bg-surface",
        )}
      >
        <button
          data-row={id}
          onClick={() => ctx.onTrace(id)}
          className={rowClass(id, ctx, "flex min-w-0 flex-1 items-center gap-2")}
        >
          <FileGlyph />
          {/* file:line as one addressable string, not a path with a number
              stranded on the far side of the row. */}
          <span
            className={cn(
              "min-w-0 truncate text-left font-mono text-[11px]",
              isLit ? "font-semibold text-accent" : "text-on-surface",
            )}
          >
            {block.file}
            <span className="text-faint">:{block.start}</span>
          </span>
        </button>
        {/* "733 of 779 lines" — where this sits in the file, which a quote
            with no denominator cannot say. */}
        {slice ? (
          <span className="tnum shrink-0 font-mono text-[9.5px] text-faint">
            {block.start.toLocaleString()} of {slice.total.toLocaleString()} lines
          </span>
        ) : null}
        <CopyPath text={`${block.file}:${block.start}`} />
        {/* A static export has no repository to write to: it links to the code host instead. */}
        {SOURCE_URL ? (
          <a
            href={`${SOURCE_URL}/${block.file}#L${block.start}-L${end}`}
            target="_blank"
            rel="noreferrer"
            onClick={(e) => e.stopPropagation()}
            className="shrink-0 border border-border-strong px-1.5 py-0.5 font-mono text-[9px] text-muted-slate transition-colors hover:text-on-surface"
          >
            github ↗
          </a>
        ) : (
          /* The code here is a slice; the whole file opens in a tab of its own. */
          <button
            onClick={(e) => {
              e.stopPropagation();
              openFileInTab(bluprint, path, block.file, block.start);
            }}
            title={`Open all of ${block.file} in a new tab, to read and edit`}
            className="shrink-0 border border-border-strong px-1.5 py-0.5 font-mono text-[9px] text-muted-slate transition-colors hover:text-on-surface"
          >
            open file ↗
          </button>
        )}
      </div>

      {/* The finding, stated before the code it is about. */}
      {drifted ? (
        <p className="border-b border-amber-line bg-amber-surface px-3 py-1.5 text-[10px] leading-relaxed text-amber-ink">
          <span className="font-semibold">Drifted.</span> The file no longer says
          what the bluprint quoted here. The code below is what is on disk now; the
          explanation under it was written about the older text.
        </p>
      ) : null}
      {failed ? (
        <p className="border-b border-border-gray bg-surface-container-low px-3 py-1.5 text-[10px] leading-relaxed text-muted-slate">
          Could not read the repository ({failed}). Showing the quote the bluprint
          was authored with, which nothing has verified against disk.
        </p>
      ) : null}

      {/* Real line numbers, counting from the file's own offset, coloured by
          lib/client/highlight.ts — and editable where it is read. */}
      <CodeEditor file={block.file} start={block.start} value={draft ?? shown} onChange={setDraft} onSave={() => void save()} readOnly={Boolean(SOURCE_URL)} />
      {/* The diff is shown BEFORE the write, and the write needs Save or ⌘S.
          There is no other path to disk. */}
      {dirty ? (
        <div className="border-t border-border-gray px-3 py-2">
          <div className="flex items-center gap-2">
            <button
              onClick={(e) => {
                e.stopPropagation();
                void save();
              }}
              className=" bg-accent px-2 py-1 font-mono text-[10px] text-on-accent"
            >
              save to disk ⌘S
            </button>
            <button
              onClick={(e) => {
                e.stopPropagation();
                setDraft(null);
                setSaved(null);
              }}
              className=" border border-border-strong px-2 py-1 font-mono text-[10px] text-muted-slate hover:text-on-surface"
            >
              discard
            </button>
            <span className="font-mono text-[9.5px] text-faint">rewrites {block.file}:{block.start}-{end}</span>
          </div>
          <DraftDiff before={shown} after={draft!} />
        </div>
      ) : null}
      {saved && !saved.ok ? (
        <p className="border-t border-border-gray px-3 py-2 text-[10px] leading-relaxed text-clay-ink">
          Refused: {saved.refused}
          {saved.refused === "stale" ? " — the file changed since this was read. Discard and reopen to get the current text." : null}
        </p>
      ) : null}

      {/* Commentary, in its own band, below the code, labelled. It is
          synthesized and must never be able to read as something the file
          says. */}
      {block.why ? (
        <div className="flex gap-2 border-t border-border-gray bg-surface-container-low px-3 py-2">
          <span className="mt-[3px] shrink-0 font-mono text-[9px] uppercase tracking-[0.09em] text-faint">
            why
          </span>
          <p className="text-[10px] leading-relaxed text-on-surface-variant">
            {block.why}
          </p>
        </div>
      ) : null}
    </div>
  );
}

/** Line-wise diff of the pending edit, shown before anything is written. */
function DraftDiff({ before, after }: { before: string; after: string }) {
  // Only the lines between the first and last that differ: the pane is
  // always editable, so one typed character must not paint the whole slice.
  let b = before.split("\n");
  let a = after.split("\n");
  let head = 0;
  while (head < b.length && head < a.length && b[head] === a[head]) head++;
  let tail = 0;
  while (tail < b.length - head && tail < a.length - head && b[b.length - 1 - tail] === a[a.length - 1 - tail]) tail++;
  b = b.slice(head, b.length - tail);
  a = a.slice(head, a.length - tail);
  return (
    <pre className="mt-2 overflow-x-auto border border-border-gray bg-card py-1.5 font-mono text-[10.5px] leading-[1.5]">
      {b.map((l, i) => (
        <div key={`b${i}`} className="bg-clay-surface px-3 text-clay-ink">
          <span className="select-none">- </span>
          {l || " "}
        </div>
      ))}
      {a.map((l, i) => (
        <div key={`a${i}`} className="bg-accent-surface px-3 text-accent">
          <span className="select-none">+ </span>
          {l || " "}
        </div>
      ))}
    </pre>
  );
}

/** Copies `file:line`, the string you paste into an editor or a message. */
function CopyPath({ text }: { text: string }) {
  const [done, setDone] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => () => void (timer.current && clearTimeout(timer.current)), []);
  return (
    <button
      onClick={(e) => {
        e.stopPropagation();
        void navigator.clipboard.writeText(text);
        setDone(true);
        if (timer.current) clearTimeout(timer.current);
        timer.current = setTimeout(() => setDone(false), 1200);
      }}
      title={`Copy ${text}`}
      className="shrink-0 border border-border-strong px-1.5 py-0.5 font-mono text-[9px] text-muted-slate transition-colors hover:text-on-surface"
    >
      {done ? "copied" : "copy path"}
    </button>
  );
}

app/components/chrome/copied.tsx:
"use client";

import { useEffect, useState, useSyncExternalStore } from "react";
import { signal } from "@/lib/client/signal";

/** The terminal copies on select with no key pressed (components/agent/shell.tsx), so this says it did. */
let shown = 0;
const { subscribe, emit } = signal();

export function showCopied() {
  shown++;
  emit();
}

export function Copied() {
  const n = useSyncExternalStore(subscribe, () => shown, () => 0);
  const [gone, setGone] = useState(0);
  useEffect(() => {
    if (!n) return;
    const t = setTimeout(() => setGone(n), 1800);
    return () => clearTimeout(t);
  }, [n]);
  if (!n || gone === n) return null;
  return (
    <div role="status" className="pointer-events-none fixed inset-x-0 bottom-10 z-50 flex justify-center px-4">
      <div className="flex items-center gap-2.5 border border-accent bg-card px-5 py-3 font-mono text-[14px] text-ink shadow-lift">
        <span aria-hidden className="text-accent">✓</span>
        Copied to clipboard
      </div>
    </div>
  );
}

app/components/chrome/crumbs.tsx:
"use client";

import { Fragment, useEffect, useMemo, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import type { Node, Origin } from "@/lib/bluprint/schema";
import type { BluprintEntry } from "@/lib/server/bluprints";
import { cn } from "@/lib/client/utils";
import { useDesktop } from "@/lib/client/platform";

/**
 * Where you are, and the way back — one line across the top of the page.
 *
 * This is the sentence you say out loud when someone asks what you are looking
 * at — "explorify, Sign Up, Student Sign-Up". It used to be a 232px rail down
 * the left, which spent a whole column on two or three names and boxed the
 * page in. Now it sits on the page's own background, sticks while you scroll,
 * and WRAPS rather than eliding when the path gets deep, so no stop is ever
 * hidden — the reason the rail existed.
 */

/** One stop on the way down: a level below the repo, outermost first. */
export interface Crumb {
  id: string;
  title: string;
}

/**
 * Where you are: the open path, root-first, read from the URL
 * (`?at=engine&at=eng-math`), and its levels as crumbs. `[]` is the repo.
 *
 * The URL rather than state because every level is then a history entry:
 * the browser's back button and the trackpad's two-finger swipe step back
 * the way they do everywhere else, and a level can be linked or reloaded.
 * The bluprint and the title bar both read it, so they always agree.
 */
export function useLocation(): { path: string[]; crumbs: Crumb[] } {
  const { nodeAt } = useBluprint();
  const params = useSearchParams();
  // The deepest level asked for that the bluprint still has: an update can take
  // a section away while it is open.
  const path = useMemo(() => {
    const asked = params.getAll("at");
    let n = asked.length;
    while (n && !nodeAt(asked.slice(0, n))) n--;
    return asked.slice(0, n);
  }, [params, nodeAt]);
  const crumbs = useMemo(
    () =>
      path
        .map((_, i) => nodeAt(path.slice(0, i + 1)))
        .filter((n): n is Node => n !== null)
        .map((n) => ({ id: n.id, title: n.title })),
    [path, nodeAt],
  );
  return { path, crumbs };
}

type Redone = { at: string; sections?: { id: string; ok: boolean }[] }[];

/**
 * Whether an update redid the open level, or a section it is inside, after
 * this was kept. An update rewrites the generator's words from the code, never
 * the reader's (lib/server/overlay.ts), so what they kept can now describe code that
 * is no longer there; it is marked, not removed, because it may still be true.
 */
export function useMayBeStale(origin?: Origin): boolean {
  const { name, L0 } = useBluprint();
  const { path } = useLocation();
  const [turns, setTurns] = useState<Redone>([]);
  useEffect(() => {
    if (!origin) return;
    let live = true;
    fetch(`/api/diff?bluprint=${encodeURIComponent(name)}&turns=1`)
      .then((r) => r.json())
      .then((j: { turns?: Redone }) => live && setTurns(j.turns ?? []))
      .catch(() => {});
    return () => {
      live = false;
    };
  }, [name, L0, origin]);
  return useMemo(
    () => Boolean(origin) && turns.some((t) => t.at > origin!.at && t.sections?.some((s) => s.ok && path.includes(s.id))),
    [turns, origin, path],
  );
}

/**
 * Opens a level. Native pushState is integrated with the App Router:
 * `useSearchParams` follows it, and so does back/forward.
 */
export function goTo(next: string[]) {
  const q = new URLSearchParams();
  const now = new URLSearchParams(window.location.search);
  const bluprint = now.get("bluprint");
  if (bluprint) q.set("bluprint", bluprint);
  // The landing page's frame stays an embed as the visitor goes deeper.
  if (now.has("embed")) q.set("embed", "");
  for (const id of next) q.append("at", id);
  window.history.pushState(null, "", q.size ? `?${q}` : window.location.pathname);
}

/** Which bluprint is open, and every other one of the reader's projects to switch to. */
function BluprintSwitcher({ bluprint, bluprints, className }: { bluprint: string; bluprints: BluprintEntry[]; className?: string }) {
  const router = useRouter();
  return (
    <select
      value={bluprint}
      aria-label="Bluprint"
      onChange={(e) => router.push(`?bluprint=${encodeURIComponent(e.target.value)}`)}
      className={className}
    >
      {bluprints.map((m) => (
        <option key={m.id} value={m.id}>
          {m.label}
        </option>
      ))}
    </select>
  );
}

export function Crumbs({
  repo,
  crumbs,
  onJump,
  bluprint,
  bluprints,
}: {
  repo: string;
  /** The open bluprint and every bluprint on disk; outside the desktop app a switcher shows when there are two. */
  bluprint: string;
  bluprints: BluprintEntry[];
  /** One entry per level below the repo, outermost first. */
  crumbs: { id: string; title: string }[];
  /** Jump to depth `n` — 0 is the repo. */
  onJump: (depth: number) => void;
}) {
  const desktop = useDesktop();
  const stops = [{ id: "", title: repo }, ...crumbs];
  const switcher = !desktop && bluprints.length >= 2;
  // At the top, a trail of one is the repo's name standing alone.
  if (!crumbs.length && !switcher) return null;
  return (
    <nav
      aria-label="Location"
      className="sticky left-0 top-0 z-20 bg-paper/85 backdrop-blur-sm"
    >
      {/* The level's own width and gutter (components/bluprint/canvas.tsx), so the trail starts where its title does. */}
      <div className="mx-auto flex max-w-[1680px] items-start gap-6 px-10 py-3">
        {/* In the desktop app the switcher lives in the title bar. */}
        {switcher ? (
          <label className="flex shrink-0 items-center gap-2">
            <span className="font-mono text-[10.5px] uppercase tracking-[0.08em] text-faint">bluprint</span>
            <BluprintSwitcher
              bluprint={bluprint}
              bluprints={bluprints}
              className="cursor-pointer border border-border-strong bg-card px-2 py-1 text-[12.5px] text-ink focus-visible:outline-2 focus-visible:outline-accent"
            />
          </label>
        ) : null}
        {/* Pulled out by the first stop's padding, so its word lines up with the title's. */}
        <ol className={cn("flex min-w-0 flex-1 flex-wrap items-center gap-x-1 gap-y-1", !switcher && "-ml-1.5")}>
          {stops.map((c, i) => {
            const here = i === stops.length - 1;
            return (
              <Fragment key={c.id || "repo"}>
                {i > 0 ? (
                  <li aria-hidden className="text-[13px] text-faint">
                    ›
                  </li>
                ) : null}
                <li>
                  <button
                    onClick={() => onJump(i)}
                    disabled={here}
                    aria-current={here ? "page" : undefined}
                    className={cn(
                      "px-1.5 py-0.5 text-[13px] transition-colors focus-visible:outline-2 focus-visible:outline-accent",
                      !here && "cursor-pointer",
                      i === 0 && "font-mono text-[12.5px]",
                      here ? "font-semibold text-ink" : "text-muted-slate hover:bg-surface-container-low hover:text-ink",
                    )}
                  >
                    {c.title}
                  </button>
                </li>
              </Fragment>
            );
          })}
        </ol>
      </div>
    </nav>
  );
}

