"use client";

import { useEffect, useState } from "react";
import { answerQuietMedia, cancelDictation, stopDictation, useDictation, useDictationKey } from "@/lib/agent/dictate";
import { cn } from "@/lib/client/utils";

/**
 * On-device dictation's only chrome (lib/agent/dictate.ts): a pill over the bottom
 * of the window while it listens or writes out, and for a moment after when
 * it put nothing in. Mounted once; it also holds the Control+Option keys.
 */
export function Dictation() {
  useDictationKey();
  const d = useDictation();
  // The note on an empty result goes after a few seconds; a new one brings it back.
  const [faded, setFaded] = useState<typeof d | null>(null);
  useEffect(() => {
    if (d.phase !== "idle" || !d.error) return;
    const t = setTimeout(() => setFaded(d), 4000);
    return () => clearTimeout(t);
  }, [d]);
  if (d === faded || (d.phase === "idle" && !d.error && !d.ask)) return null;
  const listening = d.phase === "listening";
  return (
    <div
      role="status"
      className="pointer-events-none fixed inset-x-0 bottom-10 z-50 flex justify-center px-4"
    >
      <div className="pointer-events-auto flex items-center gap-2.5 border border-border-gray bg-card px-3.5 py-1.5 font-mono text-[11.5px] text-ink shadow-lift">
        <span
          aria-hidden
          className={cn("h-2 w-2 rounded-full", listening ? "animate-pulse bg-clay-ink" : d.phase === "working" ? "bg-accent" : "bg-faint")}
        />
        {d.ask ? (
          <>
            While you talk, pause Music and Spotify and mute other sound?
            <button type="button" onClick={() => answerQuietMedia(true)} className="cursor-pointer text-accent hover:underline">
              yes
            </button>
            <button type="button" onClick={() => answerQuietMedia(false)} className="cursor-pointer text-faint hover:text-ink">
              no
            </button>
          </>
        ) : listening ? "Listening… let go of ⌃⌥" : d.phase === "working" ? "Writing it out…" : d.error}
        {listening ? (
          <>
            <button type="button" onClick={() => void stopDictation()} className="cursor-pointer text-accent hover:underline">
              done
            </button>
            <button type="button" onClick={cancelDictation} className="cursor-pointer text-faint hover:text-ink">
              cancel
            </button>
          </>
        ) : null}
      </div>
    </div>
  );
}

app/components/chrome/palette.tsx:
"use client";

import { useRouter } from "next/navigation";
import { useEffect, useMemo, useRef, useState } from "react";
import { goTo, useLocation } from "@/components/chrome/crumbs";
import { openFileInTab } from "@/components/bluprint/code";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { Kbd, keys } from "@/components/ui/button";
import { StateChip } from "@/components/ui/state";
import { newProject, openFolder, openProjects } from "@/components/projects/projects";
import { openAudit } from "@/components/bluprint/audit";
import { openHistory } from "@/components/review/additions";
import { openDiff } from "@/components/review/diff";
import { openTimeline } from "@/components/review/timeline";
import { openFiles, useCitations, useFiles, useTrail } from "@/components/bluprint/files";
import { toggleWorkspace } from "@/lib/agent/workspace-toggle";
import { DocIcon, openDoc, useDocList } from "@/components/bluprint/docs";
import { openSettings, readSettings, saveSettings } from "@/lib/client/settings";
import type { Theme } from "@/lib/client/theme";
import { startDictation } from "@/lib/agent/dictate";
import type { Node } from "@/lib/bluprint/schema";
import { cn } from "@/lib/client/utils";
import { useMac } from "@/lib/client/platform";

/**
 * The palette: one box that goes anywhere. Type part of a level's name and
 * Enter opens it however deep it is, and a doc of the project's opens the
 * same way; start with `>` for the app's actions; Cmd+K finds a file or
 * symbol instead and opens it in the editor;
 * the bluprint name in the title bar opens it on the bluprints, and the status bar's
 * counts open it on the levels that are not certain or the problems found.
 *
 * It is what a sidebar tree would have been for — reaching a level without
 * walking down to it — without spending a column on it (D35, D62).
 */

const OPEN = "bluprint:palette";
export type PaletteMode = "all" | "code" | "actions" | "bluprints" | "unsure" | "problems" | "docs";
export const openPalette = (mode: PaletteMode = "all") =>
  window.dispatchEvent(new CustomEvent<PaletteMode>(OPEN, { detail: mode }));

interface Item {
  key: string;
  label: string;
  /** Where it is or what it does, after the label. */
  hint?: string;
  /** A second line: why a level is not certain, or what goes wrong. */
  detail?: string;
  kind: "level" | "action" | "bluprint" | "unsure" | "problem" | "doc" | "file" | "folder" | "symbol";
  node?: Node;
  /** Words it is about, matched last and weakest: a level's sub, detail and plain-words layer. */
  body?: string;
  kbd?: string;
  run: () => void;
}

/**
 * How well `q` matches `text`: every character of the query in order, scored
 * higher for a run of adjacent characters and for starting a word. Null when
 * it does not match at all.
 */
function score(q: string, text: string): number | null {
  if (!q) return 0;
  const t = text.toLowerCase();
  const at = t.indexOf(q);
  if (at !== -1) return 100 - at + (at === 0 || t[at - 1] === " " ? 50 : 0);
  let s = 0;
  let i = 0;
  let prev = -2;
  for (const ch of q) {
    const j = t.indexOf(ch, i);
    if (j === -1) return null;
    s += j === prev + 1 ? 3 : j === 0 || t[j - 1] === " " ? 2 : 0;
    prev = j;
    i = j + 1;
  }
  return s;
}

export function Palette() {
  const bluprint = useBluprint();
  const router = useRouter();
  const { path } = useLocation();
  const [mode, setMode] = useState<PaletteMode | null>(null);
  const [query, setQuery] = useState("");
  const [sel, setSel] = useState(0);
  const input = useRef<HTMLInputElement>(null);
  const list = useRef<HTMLUListElement>(null);
  const mac = useMac();

  useEffect(() => {
    const show = (m: PaletteMode) => {
      setMode(m);
      setQuery(m === "actions" ? ">" : "");
      setSel(0);
    };
    const onOpen = (e: Event) => show((e as CustomEvent<PaletteMode>).detail);
    const onKey = (e: KeyboardEvent) => {
      if (!(e.ctrlKey || e.metaKey) || e.altKey) return;
      // On a Mac the palette is Cmd+K; Ctrl+K in a terminal is the program's kill-line.
      if (e.code === "KeyK" && !e.metaKey && /Mac/.test(navigator.platform) && (e.target as Element | null)?.closest?.(".xterm")) return;
      if (e.code === "KeyK") {
        e.preventDefault();
        show("code");
      } else if (e.code === "KeyP" && !e.shiftKey) {
        e.preventDefault();
        show("all");
      } else if (e.code === "KeyP" && e.shiftKey) {
        e.preventDefault();
        show("actions");
      }
    };
    window.addEventListener(OPEN, onOpen);
    // Capture, so a focused terminal does not swallow the shortcut.
    window.addEventListener("keydown", onKey, true);
    return () => {
      window.removeEventListener(OPEN, onOpen);
      window.removeEventListener("keydown", onKey, true);
    };
  }, []);

  useEffect(() => {
    if (mode) input.current?.focus();
  }, [mode]);

  const levels = useMemo<Item[]>(() => {
    const out: Item[] = [];
    const walk = (nodes: Node[], at: string[], trail: string[]) => {
      for (const n of nodes) {
        const p = [...at, n.id];
        out.push({
          key: `level:${p.join("/")}`,
          label: n.title,
          hint: trail.join(" › ") || bluprint.RUN.repo,
          kind: "level",
          node: n,
          body: [n.sub, n.detail, n.explain?.body].filter(Boolean).join(" ").toLowerCase(),
          run: () => goTo(p),
        });
        walk(n.children ?? [], p, [...trail, n.title]);
      }
    };
    out.push({ key: "level:", label: bluprint.RUN.repo, hint: "The top of the bluprint", kind: "level", kbd: "0", run: () => goTo([]) });
    walk(bluprint.L0, [], []);
    return out;
  }, [bluprint]);

  // The checkout's own names — paths and top-level symbols — each opening in
  // the editor over the deepest level that explains it, so closing the file
  // lands where it sits on a bluprint cut by features.
  const files = useFiles();
  const cited = useCitations();
  const trailOf = useTrail();
  const code = useMemo(() => {
    const out: Item[] = [];
    const deepest = (file: string, s = 1, e = Infinity) =>
      (cited.get(file) ?? []).filter((c) => c.start <= e && c.end >= s).sort((a, b) => b.path.length - a.path.length)[0]?.path;
    for (const [file, f] of Object.entries(files?.index?.files ?? {})) {
      const at = deepest(file);
      out.push({
        key: `file:${file}`,
        label: file,
        hint: at ? trailOf(at) : f.status === "excluded" ? "left out of the bluprint · opens the file" : "not on any level · opens the file",
        kind: "file",
        run: () => openFileInTab(bluprint.name, at ?? path, file),
      });
      for (const sym of f.symbols) {
        const by = deepest(file, sym.start, sym.end);
        out.push({
          key: `sym:${file}:${sym.name}:${sym.start}`,
          label: sym.name,
          hint: `${file} → ${by ? trailOf(by) : at ? `not explained; nearest ${trailOf(at)}` : "not explained"}`,
          kind: "symbol",
          run: () => openFileInTab(bluprint.name, by ?? at ?? path, file, sym.start),
        });
      }
    }
    // Files the bluprint has not seen: new since it was made, or ignored by git
    // and kept by hand, like the .env an API key goes in.
    for (const file of files?.added ?? [])
      out.push({ key: `file:${file}`, label: file, hint: "new since the bluprint was made · opens the file", kind: "file", run: () => openFileInTab(bluprint.name, path, file) });
    for (const file of files?.local ?? [])
      out.push({ key: `file:${file}`, label: file, hint: "not in git · opens the file", kind: "file", run: () => openFileInTab(bluprint.name, path, file) });
    // The rest of the checkout: everything, while a bluprint is still being made
    // and has no index; after, files the bluprint would not explain, like a README.
    const seen = new Set(out.map((it) => it.key));
    for (const file of files?.present ?? []) {
      if (seen.has(`file:${file}`)) continue;
      out.push({
        key: `file:${file}`,
        label: file,
        hint: files?.index ? "not on the bluprint · opens the file" : "the bluprint is still being made · opens the file",
        kind: "file",
        run: () => openFileInTab(bluprint.name, path, file),
      });
    }
    // Folders, each opening as a listing of what is directly inside it, so the
    // palette browses like a file explorer as well as searching.
    const browse = (dir: string) => () => {
      setMode("code");
      setQuery(dir && `${dir}/`);
      setSel(0);
    };
    const inside = new Map<string, number>();
    const tree = new Map<string, Item[]>([["", []]]);
    const childOf = (dir: string) => tree.get(dir) ?? tree.set(dir, []).get(dir)!;
    for (const it of out) {
      if (it.kind !== "file") continue;
      const parts = it.label.split("/");
      for (let i = 1; i < parts.length; i++) {
        const dir = parts.slice(0, i).join("/");
        inside.set(dir, (inside.get(dir) ?? 0) + 1);
      }
      childOf(parts.slice(0, -1).join("/")).push({ ...it, label: parts[parts.length - 1] });
    }
    for (const [dir, n] of inside) {
      const folder: Item = { key: `dir:${dir}`, label: `${dir}/`, hint: `${n} file${n === 1 ? "" : "s"}`, kind: "folder", run: browse(dir) };
      out.push(folder);
      const parent = dir.split("/").slice(0, -1).join("/");
      childOf(parent).push({ ...folder, label: `${dir.split("/").pop()}/` });
    }
    // Folders first, then files, each by name; and a way up out of any folder.
    for (const [dir, items] of tree) {
      items.sort((a, b) => (a.kind === b.kind ? a.label.localeCompare(b.label) : a.kind === "folder" ? -1 : 1));
      if (dir) items.unshift({ key: "dir:..", label: "../", hint: dir.split("/").slice(0, -1).join("/") || "the top", kind: "folder", run: browse(dir.split("/").slice(0, -1).join("/")) });
    }
    return { all: out, tree };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- trailOf reads the same bluprint as cited
  }, [files, cited, path, bluprint.name]);

  const docList = useDocList();
  const docs = useMemo<Item[]>(
    () =>
      (docList ?? []).map((d) => ({
        key: `doc:${d.path}`,
        // The file is what people call a doc; its heading says what is in it.
        label: d.path,
        hint: d.title || undefined,
        kind: "doc" as const,
        run: () => openDoc(d.path),
      })),
    [docList],
  );

  const actions = useMemo<Item[]>(() => {
    const theme = (t: Theme) => () => saveSettings({ ...readSettings(), theme: t });
    return [
      { key: "a:back", label: "Go back a level", kind: "action", kbd: "Esc", run: () => path.length && goTo(path.slice(0, -1)) },
      { key: "a:workspace", label: "Toggle Claude Code & terminal", kind: "action", kbd: keys(mac, "`"), run: toggleWorkspace },
      { key: "a:diff", label: "What changed in the code", hint: "Diff two commits over the bluprint", kind: "action", run: openDiff },
      { key: "a:files", label: "Every file", hint: "Where each part of the code is explained", kind: "action", run: () => openFiles() },
      { key: "a:timeline", label: "How the code got here", hint: "Its commits over time, on the bluprint's sections", kind: "action", run: openTimeline },
      { key: "a:audit", label: "How sure is this bluprint", hint: "What was checked, and what to double-check", kind: "action", run: () => openAudit(bluprint.name) },
      { key: "a:history", label: "What you added to this bluprint", kind: "action", run: openHistory },
      { key: "a:docs", label: "Read the docs…", hint: "The project's Markdown: design notes, decisions", kind: "action", run: () => setTimeout(() => openPalette("docs")) },
      { key: "a:open", label: "Open Folder…", hint: "Make a bluprint of a folder on this machine", kind: "action", run: () => void openFolder() },
      { key: "a:new", label: "New Project…", hint: "Start an empty folder", kind: "action", run: newProject },
      { key: "a:projects", label: "Projects", hint: "Your bluprints: open, regenerate, remove", kind: "action", run: () => openProjects() },
      { key: "a:bluprints", label: "Switch bluprint…", kind: "action", run: () => setTimeout(() => openPalette("bluprints")) },
      { key: "a:settings", label: "Settings", kind: "action", run: openSettings },
      // After the palette has closed, so the words go to Claude's prompt rather than the palette's field.
      { key: "a:dictate", label: "Dictate on this machine", hint: "Speak, then done; or hold the key", kind: "action", kbd: "Hold ⌃⌥", run: () => setTimeout(startDictation) },
      { key: "a:classic", label: "Theme: classic", hint: "Cobalt ink, as on the landing page", kind: "action", run: theme("classic") },
      { key: "a:light", label: "Theme: light", kind: "action", run: theme("light") },
      { key: "a:dark", label: "Theme: dark", kind: "action", run: theme("dark") },
    ];
  }, [bluprint.name, path, mac]);

  const bluprints = useMemo<Item[]>(
    () =>
      bluprint.bluprints.map((m) => ({
        key: `bluprint:${m.id}`,
        label: m.label,
        hint: m.id === bluprint.name ? "open now" : undefined,
        kind: "bluprint" as const,
        run: () => router.push(`?bluprint=${encodeURIComponent(m.id)}`),
      })),
    [bluprint.bluprints, bluprint.name, router],
  );

  // What the status bar counts, each a way to the level it is on. Walked in
  // bluprint order, so the list reads top to bottom the way the bluprint does.
  const findings = useMemo(() => {
    const unsure: Item[] = [];
    const problems: Item[] = [];
    const walk = (n: Node, p: string[], trail: string[]) => {
      const where = trail.join(" › ") || bluprint.RUN.repo;
      const run = () => goTo(p);
      if (n.state !== "derived") {
        unsure.push({ key: `u:${p.join("/")}`, label: n.title, hint: where, detail: n.unsure, kind: "unsure", node: n, run });
      }
      n.issues?.forEach((is, i) =>
        problems.push({
          key: `p:${p.join("/")}:${i}`,
          label: is.title,
          hint: `in ${n.title}`,
          detail: is.detail,
          kind: "problem",
          run,
        }),
      );
      for (const c of n.children ?? []) walk(c, [...p, c.id], p.length ? [...trail, n.title] : []);
    };
    // The repository itself is a level too (D60), and can carry both.
    walk(bluprint.TOP, [], []);
    return { unsure, problems };
  }, [bluprint]);

  const shown = useMemo(() => {
    const actionsOnly = query.startsWith(">");
    const q = (actionsOnly ? query.slice(1) : query).trim().toLowerCase();
    // Nothing typed, or a folder's path: list that folder, as an explorer would.
    if (mode === "code" && (!query.trim() || query.endsWith("/"))) {
      const listing = code.tree.get(query.trim().replace(/\/$/, ""));
      if (listing) return listing;
    }
    const pool =
      mode === "bluprints" ? bluprints
      : mode === "unsure" ? findings.unsure
      : mode === "problems" ? findings.problems
      : mode === "docs" ? docs
      : mode === "code" ? code.all
      : actionsOnly ? actions
      : q ? [...levels, ...docs, ...actions]
      : levels;
    return pool
      // A hint or a body counts only as a plain substring: scattered letters
      // across a sentence match nearly anything.
      .map((it) => ({ it, s: score(q, it.label) ?? (it.hint?.toLowerCase().includes(q) ? 1 : it.body?.includes(q) ? 0.5 : null) }))
      .filter((x): x is { it: Item; s: number } => x.s !== null)
      .sort((a, b) => b.s - a.s)
      .slice(0, 60)
      .map((x) => x.it);
  }, [mode, query, levels, code, docs, actions, bluprints, findings]);

  useEffect(() => {
    list.current?.querySelector(`[data-i="${sel}"]`)?.scrollIntoView({ block: "nearest" });
  }, [sel]);

  if (!mode) return null;
  const close = () => setMode(null);
  const run = (it: Item | undefined) => {
    if (!it) return;
    close();
    it.run();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex justify-center bg-night/20 px-4 pt-[12vh]"
      onPointerDown={(e) => e.target === e.currentTarget && close()}
    >
      <div
        role="dialog"
        aria-label="Go to"
        className="flex h-fit max-h-[60vh] w-full max-w-[600px] flex-col overflow-hidden border border-border-strong bg-card shadow-lift"
      >
        <input
          ref={input}
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setSel(0);
          }}
          onKeyDown={(e) => {
            if (e.key === "Escape") {
              e.preventDefault();
              e.stopPropagation();
              close();
            } else if (e.key === "ArrowDown") {
              e.preventDefault();
              setSel((s) => Math.min(s + 1, shown.length - 1));
            } else if (e.key === "ArrowUp") {
              e.preventDefault();
              setSel((s) => Math.max(s - 1, 0));
            } else if (e.key === "Enter") {
              e.preventDefault();
              run(shown[sel]);
            }
          }}
          placeholder={
            mode === "bluprints" ? "Switch to a bluprint…"
            : mode === "unsure" ? `${findings.unsure.length} levels the bluprint is not certain about — filter…`
            : mode === "problems" ? `${findings.problems.length} problems found in the code — filter…`
            : mode === "docs" ? (docList === null ? "Finding the docs…" : `${docList.length} docs in this project — filter…`)
            : mode === "code" ? "Open a file, folder or symbol in the editor…"
            : "Go to a level, or type > for actions"
          }
          className="h-11 w-full shrink-0 border-b border-border-gray bg-transparent px-4 text-[14px] text-ink placeholder:text-faint focus:outline-none"
        />
        <ul ref={list} role="listbox" className="min-h-0 overflow-y-auto py-1">
          {shown.length ? (
            shown.map((it, i) => (
              <li key={it.key} data-i={i} role="option" aria-selected={i === sel}>
                <button
                  type="button"
                  onPointerMove={() => setSel(i)}
                  onClick={() => run(it)}
                  className={cn(
                    "flex w-full cursor-pointer gap-2.5 px-4 text-left",
                    it.detail ? "items-start py-2" : "items-center py-[7px]",
                    // Not surface-container-low: in Dark that is the card's own colour, a step too close to show.
                    i === sel && "bg-surface-container",
                  )}
                >
                  <KindIcon kind={it.kind} />
                  <span className="min-w-0 flex-1">
                    <span className="flex items-center gap-2.5">
                      <span className={cn("truncate text-[13px] text-ink", it.kind === "symbol" && "shrink-0")}>{it.label}</span>
                      {it.node && it.kind === "level" ? <StateChip state={it.node.state} alarm={it.node.alarm} /> : null}
                      {it.hint ? <span className="min-w-0 truncate text-[12px] text-faint">{it.hint}</span> : null}
                      <span className="flex-1" />
                      {it.kbd ? <Kbd>{it.kbd}</Kbd> : null}
                    </span>
                    {it.detail ? (
                      <span className="mt-0.5 line-clamp-2 text-[12px] leading-snug text-muted-slate">{it.detail}</span>
                    ) : null}
                  </span>
                </button>
              </li>
            ))
          ) : (
            <li className="px-4 py-3 text-[13px] text-faint">
              {mode === "unsure" && !findings.unsure.length
                ? "Every level is certain."
                : mode === "problems" && !findings.problems.length
                  ? "The bluprint found no problems."
                  : mode === "docs" && docList && !docList.length
                    ? "This project has no Markdown."
                    : "Nothing matches."}
            </li>
          )}
        </ul>
        <footer className="flex shrink-0 items-center gap-3 border-t border-border-gray bg-surface px-4 py-1.5 text-[11.5px] text-faint">
          <span className="flex items-center gap-1"><Kbd>↑</Kbd><Kbd>↓</Kbd> move</span>
          <span className="flex items-center gap-1"><Kbd>Enter</Kbd> open</span>
          {mode === "all" || mode === "actions" ? <span className="flex items-center gap-1"><Kbd>&gt;</Kbd> actions</span> : null}
          <span className="flex-1" />
          <span className="flex items-center gap-1"><Kbd>Esc</Kbd> close</span>
        </footer>
      </div>
    </div>
  );
}

function KindIcon({ kind }: { kind: Item["kind"] }) {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.3"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={cn(
        "shrink-0",
        kind === "unsure" ? "mt-[3px] text-amber-ink" : kind === "problem" ? "mt-[3px] text-clay-ink" : "text-faint",
      )}
      aria-hidden
    >
      {kind === "unsure" ? (
        <>
          <circle cx="8" cy="8" r="6" />
          <path d="M6.3 6.2a1.8 1.8 0 1 1 2.4 1.7c-.5.2-.7.5-.7 1v.4M8 11.4v.1" />
        </>
      ) : kind === "problem" ? (
        <path d="M8 2 14.5 13.5h-13zM8 6.5v3M8 11.6v.1" />
      ) : kind === "level" ? (
        <>
          <rect x="2" y="2.5" width="12" height="11" rx="2" />
          <path d="M5 6h6M5 9h4" />
        </>
      ) : kind === "doc" ? (
        <DocIcon />
      ) : kind === "file" ? (
        <path d="M4 1.5h5l3 3v10H4zM9 1.5v3h3" />
      ) : kind === "symbol" ? (
        <path d="M6 3.5c-1.5 0-2 .7-2 2v1c0 .8-.5 1.5-1.5 1.5 1 0 1.5.7 1.5 1.5v1c0 1.3.5 2 2 2M10 3.5c1.5 0 2 .7 2 2v1c0 .8.5 1.5 1.5 1.5-1 0-1.5.7-1.5 1.5v1c0 1.3-.5 2-2 2" />
      ) : kind === "bluprint" || kind === "folder" ? (
        <path d="M1.5 4.5a1 1 0 0 1 1-1h3.6l1.5 1.5h5.9a1 1 0 0 1 1 1v6.5a1 1 0 0 1-1 1h-11a1 1 0 0 1-1-1z" />
      ) : (
        <path d="m5 4 4 4-4 4M9 12h3" />
      )}
    </svg>
  );
}

app/components/chrome/settings.tsx:
"use client";

import { invoke } from "@tauri-apps/api/core";
import { useCallback, useEffect, useState } from "react";
import { DIALOG, Field, INPUT, Overlay } from "@/components/ui/dialog";
import { keys } from "@/components/ui/button";
import { AgentIcon, CLAUDE, useInstalled } from "@/components/agent/agents";
import { PanelHead } from "@/components/ui/panel";
import { cn } from "@/lib/client/utils";
import { followTheme, onOpenSettings, readSettings, saveSettings, useSettings, type Ground, type Settings, type Theme } from "@/lib/client/settings";
import { useMac } from "@/lib/client/platform";

/**
 * Settings, as a dialog over the bluprint. There is little to set: the theme,
 * the agent new tabs open into, where Claude Code is when it was not found by
 * itself, which model it runs, and what the bluprint is drawn on. Every change is
 * saved as it is made, so there is nothing to confirm and nothing to undo.
 */

const THEMES: { value: Theme; label: string }[] = [
  { value: "classic", label: "Classic" },
  { value: "light", label: "Light" },
  { value: "dark", label: "Dark" },
];

const GROUNDS: { value: Ground; label: string }[] = [
  { value: "plain", label: "Plain" },
  { value: "dots", label: "Dots" },
  { value: "squares", label: "Squares" },
];

type Found = { path: string; version: string | null } | null;

/** One choice of a row of them. */
const SEGMENT =
  "cursor-pointer px-3.5 py-1 text-[12.5px] transition-colors focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent";

export function SettingsDialog() {
  const [open, setOpen] = useState(false);
  // What is on screen is what is saved: there is no draft to keep in step.
  const draft = useSettings();
  // undefined while looking.
  const [found, setFound] = useState<Found | undefined>(undefined);
  const agents = [CLAUDE, ...useInstalled()];
  const mac = useMac();

  const detect = useCallback((claudePath: string) => {
    setFound(undefined);
    invoke<Found>("claude_detect", { configured: claudePath.trim() || null })
      .then(setFound)
      .catch(() => setFound(null));
  }, []);

  useEffect(
    () =>
      onOpenSettings(() => {
        setOpen(true);
        detect(readSettings().claudePath);
      }),
    [detect],
  );

  // Mounted for the app's whole life, so this keeps the page on the saved theme.
  useEffect(followTheme, []);

  if (!open) return null;
  const close = () => {
    tidy();
    setOpen(false);
  };
  // Typing keeps its spaces until the field is left, so a trim never moves the caret.
  const set = (next: Partial<Settings>) => saveSettings({ ...readSettings(), ...next });
  const tidy = () => {
    const now = readSettings();
    set({ claudePath: now.claudePath.trim(), model: now.model.trim() });
  };

  return (
    <Overlay onClose={close}>
      <form
        role="dialog"
        aria-label="Settings"
        onSubmit={(e) => {
          e.preventDefault();
          close();
        }}
        className={cn(DIALOG, "max-w-[520px]")}
      >
        <PanelHead
          title="Settings"
          right={
            <button
              type="submit"
              aria-label="Close"
              title="Close (Esc)"
              className="-mr-1.5 -mt-1 flex h-7 w-7 shrink-0 cursor-pointer items-center justify-center text-muted-slate hover:bg-surface-container hover:text-ink focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent"
            >
              <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" aria-hidden>
                <path d="m4.5 4.5 7 7m0-7-7 7" />
              </svg>
            </button>
          }
        />
        <div className="flex min-h-0 flex-col gap-5 overflow-y-auto px-5 py-5">
          <Field group label="Theme" hint="Classic is the landing page's cobalt ink. Light and Dark are plain.">
            <div role="radiogroup" aria-label="Theme" className="inline-flex border border-border-gray p-0.5">
              {THEMES.map((t) => (
                <button
                  key={t.value}
                  type="button"
                  role="radio"
                  aria-checked={draft.theme === t.value}
                  onClick={() => set({ theme: t.value })}
                  className={cn(
                    SEGMENT,
                    draft.theme === t.value ? "bg-accent text-on-accent" : "text-muted-slate hover:text-ink",
                  )}
                >
                  {t.label}
                </button>
              ))}
            </div>
          </Field>
          <Field group label="Background" hint="What the bluprint is drawn on.">
            <div role="radiogroup" aria-label="Background" className="inline-flex border border-border-gray p-0.5">
              {GROUNDS.map((g) => (
                <button
                  key={g.value}
                  type="button"
                  role="radio"
                  aria-checked={draft.ground === g.value}
                  onClick={() => set({ ground: g.value })}
                  className={cn(
                    SEGMENT,
                    draft.ground === g.value ? "bg-accent text-on-accent" : "text-muted-slate hover:text-ink",
                  )}
                >
                  {g.label}
                </button>
              ))}
            </div>
          </Field>
          <Field
            group
            label="Default agent"
            hint={`What a tab opens into when the app opens one for you: ${keys(mac, "`")}, ${keys(mac, "T", { shift: true })}, the title bar, or the first in the + menu. Bluprint context goes to Claude either way.`}
          >
            <div role="radiogroup" aria-label="Default agent" className="inline-flex border border-border-gray p-0.5">
              {agents.map((a) => (
                <button
                  key={a.id}
                  type="button"
                  role="radio"
                  aria-checked={draft.agent === a.id}
                  onClick={() => set({ agent: a.id })}
                  className={cn(
                    SEGMENT, "flex items-center gap-1.5",
                    draft.agent === a.id ? "bg-accent text-on-accent" : "text-muted-slate hover:text-ink",
                  )}
                >
                  <AgentIcon id={a.id} />
                  {a.label}
                </button>
              ))}
            </div>
          </Field>
          <Field group label="Dev server" hint="Start a project's dev server when it opens, and show the running app in a Preview tab.">
            <div role="radiogroup" aria-label="Dev server" className="inline-flex border border-border-gray p-0.5">
              {[
                { value: true, label: "Start it" },
                { value: false, label: "Leave it" },
              ].map((o) => (
                <button
                  key={o.label}
                  type="button"
                  role="radio"
                  aria-checked={draft.devServer === o.value}
                  onClick={() => set({ devServer: o.value })}
                  className={cn(
                    SEGMENT,
                    draft.devServer === o.value ? "bg-accent text-on-accent" : "text-muted-slate hover:text-ink",
                  )}
                >
                  {o.label}
                </button>
              ))}
            </div>
          </Field>
          <Field label="Claude Code" hint="Leave blank to find it automatically.">
            <input
              value={draft.claudePath}
              onChange={(e) => set({ claudePath: e.target.value })}
              onBlur={() => {
                tidy();
                detect(draft.claudePath);
              }}
              placeholder={found?.path ?? "~/.local/bin/claude"}
              spellCheck={false}
              className={INPUT}
            />
            <div className="mt-1.5 flex items-baseline gap-3 font-mono text-[11.5px]">
              {found === undefined ? (
                <span className="text-faint">Looking…</span>
              ) : found ? (
                <span className="truncate text-accent">
                  ✓ {found.path}
                  {found.version ? ` (${found.version})` : ""}
                </span>
              ) : (
                <span className="text-clay-ink">
                  {draft.claudePath.trim() ? "Nothing at that path." : "Not found — install Claude Code, or enter its path."}
                </span>
              )}
              <button
                type="button"
                onClick={() => detect(draft.claudePath)}
                className="ml-auto shrink-0 cursor-pointer text-accent hover:underline"
              >
                Detect again
              </button>
            </div>
          </Field>
          <Field label="Model" hint="Blank uses Claude Code's default. An alias like sonnet or opus, or a full model id.">
            <input
              value={draft.model}
              onChange={(e) => set({ model: e.target.value })}
              onBlur={tidy}
              placeholder="default"
              spellCheck={false}
              className={INPUT}
            />
          </Field>
          <Field
            group
            label="Claude Code dictation"
            hint="Hold Control+Option (⌃⌥), or Space in a Claude tab, and speak into Claude's prompt. Transcribed by Anthropic at no cost to your usage; needs a claude.ai sign-in, not Bedrock or an API key."
          >
            <div role="radiogroup" aria-label="Claude Code dictation" className="inline-flex border border-border-gray p-0.5">
              {[
                { value: true, label: "On" },
                { value: false, label: "As in Claude Code" },
              ].map((o) => (
                <button
                  key={o.label}
                  type="button"
                  role="radio"
                  aria-checked={draft.voice === o.value}
                  onClick={() => set({ voice: o.value })}
                  className={cn(
                    SEGMENT,
                    draft.voice === o.value ? "bg-accent text-on-accent" : "text-muted-slate hover:text-ink",
                  )}
                >
                  {o.label}
                </button>
              ))}
            </div>
          </Field>
          <Field
            group
            label="Skills and web research"
            hint="Claude loads skills and searches or reads the web without asking each time. Plan mode always does, and still never edits files."
          >
            <div role="radiogroup" aria-label="Skills and web research" className="inline-flex border border-border-gray p-0.5">
              {[
                { value: true, label: "Without asking" },
                { value: false, label: "As in Claude Code" },
              ].map((o) => (
                <button
                  key={o.label}
                  type="button"
                  role="radio"
                  aria-checked={draft.research === o.value}
                  onClick={() => set({ research: o.value })}
                  className={cn(
                    SEGMENT,
                    draft.research === o.value ? "bg-accent text-on-accent" : "text-muted-slate hover:text-ink",
                  )}
                >
                  {o.label}
                </button>
              ))}
            </div>
          </Field>
          <p className="text-[12px] text-faint">Claude Code changes apply to Claude tabs opened from now on.</p>
          <Field
            group
            label="On-device dictation"
            hint="Hold Control+Option (⌃⌥) in a field in the app, or for Claude's prompt where Claude Code dictation isn't available. Runs on this machine, for any sign-in; nothing is sent anywhere."
          >
            <OnDevice />
          </Field>
          <Field
            group
            label="Saved sign-ins"
            hint="Sites you signed in to in the Preview when Claude asked. Bluprint keeps their sign-in cookies, never your password. Forget signs you out."
          >
            <SignIns />
          </Field>
          <Field group label="Media while dictating" hint="Pauses Music and Spotify, and mutes everything else, while you hold ⌃⌥; all of it comes back when you let go.">
            <div role="radiogroup" aria-label="Media while dictating" className="inline-flex border border-border-gray p-0.5">
              {[
                { value: true, label: "Quiet it" },
                { value: false, label: "Leave it" },
              ].map((o) => (
                <button
                  key={o.label}
                  type="button"
                  role="radio"
                  aria-checked={draft.quietMedia === o.value}
                  onClick={() => set({ quietMedia: o.value })}
                  className={cn(
                    SEGMENT,
                    draft.quietMedia === o.value ? "bg-accent text-on-accent" : "text-muted-slate hover:text-ink",
                  )}
                >
                  {o.label}
                </button>
              ))}
            </div>
          </Field>
          <Field
            group
            label="Run reports"
            hint="When a bluprint finishes, Bluprint sends the Bluprint team how long it took, what it cost, the repository's name and the end of its log, so the mapping keeps getting better. Never your code."
          >
            <RunReports />
          </Field>
        </div>
      </form>
    </Overlay>
  );
}

/** Whether finished runs are reported (lib/server/telemetry.ts); kept by the server, which sends them. */
function RunReports() {
  const [on, setOn] = useState<boolean | null>(null);
  useEffect(() => {
    fetch("/api/telemetry")
      .then((r) => r.json())
      .then((t: { on: boolean }) => setOn(t.on), () => setOn(null));
  }, []);
  const choose = (value: boolean) => {
    setOn(value);
    void fetch("/api/telemetry", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ on: value }) });
  };
  return (
    <div role="radiogroup" aria-label="Run reports" className="inline-flex border border-border-gray p-0.5">
      {[
        { value: true, label: "Send" },
        { value: false, label: "Don't send" },
      ].map((o) => (
        <button
          key={o.label}
          type="button"
          role="radio"
          aria-checked={on === o.value}
          onClick={() => choose(o.value)}
          className={cn(SEGMENT, on === o.value ? "bg-accent text-on-accent" : "text-muted-slate hover:text-ink")}
        >
          {o.label}
        </button>
      ))}
    </div>
  );
}

type ModelStatus = { model: "missing" | "downloading" | "ready"; bytes: number; total: number; error: string | null };

/** The speech model for on-device dictation (src-tauri/src/dictate.rs): fetched once, kept until removed. */
function OnDevice() {
  const [s, setS] = useState<ModelStatus | null>(null);
  const [failed, setFailed] = useState<string | null>(null);
  const read = useCallback(() => {
    invoke<ModelStatus>("dictate_status").then(setS, (e) => setFailed(String(e)));
  }, []);
  useEffect(() => {
    read();
  }, [read]);
  // Polled only while it downloads, for the progress and for when it lands.
  useEffect(() => {
    if (s?.model !== "downloading") return;
    const t = setInterval(read, 1000);
    return () => clearInterval(t);
  }, [s?.model, read]);
  const act = (cmd: string) => invoke(cmd).then(read, (e) => setFailed(String(e)));
  const mb = (n: number) => Math.round(n / 1e6);
  if (!s) return <span className="font-mono text-[11.5px] text-faint">{failed ?? "Looking…"}</span>;
  return (
    <div className="flex items-baseline gap-3 font-mono text-[11.5px]">
      {s.model === "ready" ? (
        <span className="text-accent">✓ Parakeet v3, {mb(s.total)} MB, on this machine</span>
      ) : s.model === "downloading" ? (
        <span className="text-ink">
          Downloading… {mb(s.bytes)} of {mb(s.total)} MB
        </span>
      ) : (
        <span className={s.error || failed ? "text-clay-ink" : "text-faint"}>
          {s.error ?? failed ?? `Needs its speech model, ${mb(s.total)} MB, downloaded once.`}
        </span>
      )}
      {s.model === "missing" ? (
        <button type="button" onClick={() => act("dictate_download")} className="ml-auto shrink-0 cursor-pointer text-accent hover:underline">
          {s.bytes ? "Resume download" : "Download"}
        </button>
      ) : (
        <button type="button" onClick={() => act("dictate_remove")} className="ml-auto shrink-0 cursor-pointer text-faint hover:text-ink">
          {s.model === "ready" ? "Remove" : "Stop"}
        </button>
      )}
    </div>
  );
}

type Kept = { global: string[]; projects: Record<string, string[]> };

/** The sign-ins the preview keeps (src-tauri/src/signins.rs): for all projects, then each project's own. */
function SignIns() {
  const [kept, setKept] = useState<Kept | null>(null);
  const [failed, setFailed] = useState<string | null>(null);
  const read = useCallback(() => {
    invoke<Kept>("signin_list").then(setKept, (e) => setFailed(String(e)));
  }, []);
  useEffect(read, [read]);
  if (!kept) return <span className="font-mono text-[11.5px] text-faint">{failed ?? "Looking…"}</span>;
  const rows = [
    ...kept.global.map((site) => ({ site, root: null as string | null, where: "All projects" })),
    ...Object.entries(kept.projects).flatMap(([root, sites]) =>
      sites.map((site) => ({ site, root, where: root.split("/").filter(Boolean).pop() ?? root })),
    ),
  ];
  if (!rows.length) return <span className="font-mono text-[11.5px] text-faint">None yet.</span>;
  return (
    <ul className="flex flex-col gap-1 font-mono text-[11.5px]">
      {rows.map((r) => (
        <li key={`${r.root ?? ""}:${r.site}`} className="flex items-baseline gap-3">
          <span className="truncate text-ink">{r.site}</span>
          <span className="truncate text-faint" title={r.root ?? undefined}>
            {r.where}
          </span>
          <button
            type="button"
            onClick={() => invoke("signin_forget", { root: r.root, site: r.site }).then(read, (e) => setFailed(String(e)))}
            className="ml-auto shrink-0 cursor-pointer text-faint hover:text-ink"
          >
            Forget
          </button>
        </li>
      ))}
      {failed ? <li className="text-clay-ink">{failed}</li> : null}
    </ul>
  );
}

app/components/chrome/statusbar.tsx:
"use client";

import { useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";
import { AgentIcon } from "@/components/agent/agents";
import { Kbd, keys } from "@/components/ui/button";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { openReview } from "@/components/review/diff";
import { openFiles, useFiles } from "@/components/bluprint/files";
import { openPalette } from "@/components/chrome/palette";
import { openProjects } from "@/components/projects/projects";
import { UNFOLLOWED, claudeMidTurnIn, followTurn } from "@/lib/agent/turns";
import { toggleWorkspace } from "@/lib/agent/workspace-toggle";
import type { Node } from "@/lib/bluprint/schema";
import { STATIC_BLUPRINT } from "@/lib/bluprint/source";
import { cn } from "@/lib/client/utils";
import { useMac } from "@/lib/client/platform";

/**
 * The line along the bottom of the window: what is true of the whole bluprint,
 * whatever level is open. Which commit it describes, the problems it found,
 * whether an update is running, and the two keys that get you
 * anywhere. It is the one place this lives, so no level has to repeat it.
 */
export function StatusBar() {
  const { name, bluprints, RUN, L0, TOP } = useBluprint();
  const local = bluprints.some((m) => m.id === name && m.local);

  const problems = useMemo(() => {
    let problems = 0;
    const walk = (nodes: Node[]) => {
      for (const n of nodes) {
        problems += n.issues?.length ?? 0;
        walk(n.children ?? []);
      }
    };
    walk(L0);
    // The repository is a level too (D60): its problems count, as the list this opens includes them.
    problems += TOP.issues?.length ?? 0;
    return problems;
  }, [L0, TOP]);
  const files = useFiles();
  const mac = useMac();

  return (
    <footer data-chrome="bar" className="flex h-6 shrink-0 select-none items-center gap-0.5 border-t border-border-gray bg-surface-container-low px-2 text-[11.5px] text-muted-slate">
      <Item title="The commit this bluprint describes" mono>
        <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden>
          <circle cx="8" cy="8" r="2.5" />
          <path d="M1 8h4.5M10.5 8H15" />
        </svg>
        {RUN.commit?.slice(0, 7) ?? "no commit"}
      </Item>
      {files?.added.length ? (
        <Item title="Files added since the bluprint was made — click to list them" onClick={() => openFiles("added")} className="text-amber-ink">
          {files.added.length} not on the bluprint yet
        </Item>
      ) : null}
      {problems ? (
        <Item title="Problems the bluprint found in the code — click to list them" onClick={() => openPalette("problems")} className="text-clay-ink">
          <span aria-hidden>⚠</span>
          {problems} {problems === 1 ? "problem" : "problems"}
        </Item>
      ) : null}
      <span className="min-w-0 flex-1" />
      <BluprintUpdates key={name} id={name} root={RUN.root} local={local} />
      <Item title="Go to a level, or run an action" onClick={() => openPalette()}>
        Go to <Kbd className={KEY}>{keys(mac, "P")}</Kbd>
      </Item>
      {STATIC_BLUPRINT ? (
        <Item title="Ask Claude about this code" onClick={toggleWorkspace}>
          <AgentIcon id="claude" />
          {/* A published page takes Control+` only (components/agent/claude-web.tsx). */}
          Claude <Kbd className={KEY}>{keys(mac, "`", { ctrl: true })}</Kbd>
        </Item>
      ) : (
        <Item title="Claude Code & terminal" onClick={toggleWorkspace}>
          <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
            <rect x="1.5" y="2.5" width="13" height="11" rx="2" />
            <path d="M4.5 6.5 6.5 8l-2 1.5M8.5 10h3" />
          </svg>
          Workspace <Kbd className={KEY}>{keys(mac, "`")}</Kbd>
        </Item>
      )}
    </footer>
  );
}

/** A key, sized to the bar. */
const KEY = "h-[15px] min-w-[15px] text-[10px]";

function Item({
  children,
  title,
  onClick,
  mono,
  className,
}: {
  children: React.ReactNode;
  title: string;
  onClick?: () => void;
  mono?: boolean;
  className?: string;
}) {
  const cls = cn(
    "flex h-full shrink-0 items-center gap-1.5 px-1.5",
    mono && "font-mono text-[11px]",
    onClick && "cursor-pointer hover:bg-surface-container hover:text-ink focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent",
    className,
  );
  return onClick ? (
    <button type="button" title={title} onClick={onClick} className={cls}>
      {children}
    </button>
  ) : (
    <span title={title} className={cls}>
      {children}
    </span>
  );
}

/** How long the changed files must stay as they are before the bluprint follows them by itself. */
const SETTLE = 3_000;

interface Update {
  status: "running" | "done" | "failed";
  finishedAt?: string;
  changed?: string[];
  sections?: string[];
  error?: string;
}

/**
 * The section ids an update is rewriting right now, for the open level to say
 * so where the reader is looking (components/bluprint/canvas.tsx): the status bar alone
 * was missed, and a minute with nothing changing read as the update not working.
 */
let redoing: string[] = [];
const redoListeners = new Set<() => void>();
function setRedoing(next: string[]) {
  if (next.join("\n") === redoing.join("\n")) return;
  redoing = next;
  redoListeners.forEach((l) => l());
}
const NONE: string[] = [];
export function useRedoing(): string[] {
  return useSyncExternalStore(
    (l) => (redoListeners.add(l), () => redoListeners.delete(l)),
    () => redoing,
    () => NONE,
  );
}

/**
 * Follows the open bluprint while an agent changes its code: an update redoing
 * the touched sections (lib/server/vault.ts) shows here while it runs. The bluprint takes
 * each section as it lands by itself (components/bluprint/bluprint-context.tsx); this only
 * says what is happening. Only the user's own projects update; an
 * example describes some other copy of its code, so when an agent edits its
 * checkout this says so and offers to import it.
 *
 * Edits made outside a Bluprint tab (another editor, a pull) never ask for an
 * update, so between updates this says how far the code has moved from what
 * the bluprint describes (lib/server/live.ts, followed with the bluprint each second), and
 * updates it once those files have stopped changing for SETTLE. Not while
 * Claude is mid-turn in the checkout: its turn updates the bluprint when it ends,
 * with its account of what it did. The same change is never retried after it
 * failed, since each try is a paid run.
 */
function BluprintUpdates({ id, root, local }: { id: string; root?: string; local: boolean }) {
  const [u, setU] = useState<Update | null>(null);
  const [unfollowed, setUnfollowed] = useState(false);

  useEffect(() => {
    const on = (e: Event) => (e as CustomEvent<string>).detail === root && setUnfollowed(true);
    window.addEventListener(UNFOLLOWED, on);
    return () => window.removeEventListener(UNFOLLOWED, on);
  }, [root]);
  // The last finished update already on screen, so only a new one reloads.
  const seen = useRef<string | undefined>(undefined);
  const [fresh, setFresh] = useState(false);

  useEffect(() => {
    if (!local) return;
    let first = true;
    const tick = () =>
      fetch(`/api/projects?id=${encodeURIComponent(id)}`)
        .then((r) => r.json())
        .then((p: { update: Update | null; redoing?: string[] } | null) => {
          const next = p?.update ?? null;
          setU(next);
          setRedoing(next?.status === "running" ? (p?.redoing ?? []) : []);
          const done = next?.status !== "running" ? next?.finishedAt : undefined;
          if (!first && done && done !== seen.current) setFresh(true);
          if (done) seen.current = done;
          first = false;
        })
        .catch(() => {});
    void tick();
    const timer = setInterval(tick, 2000);
    return () => (clearInterval(timer), setRedoing([]));
  }, [id, local]);

  const { live } = useBluprint();
  const behind = local ? (live?.files ?? []) : [];
  const sig = local ? (live?.sig ?? "") : "";
  // The change last updated for, so a failed one is not paid for again.
  const [tried, setTried] = useState("");
  const follow = (sig: string) => {
    setTried(sig);
    if (root) void followTurn(root, { transcript: null, corrections: [] });
  };
  // Each save starts the wait again; one that runs out with the code still
  // ahead updates. An update already running takes it after (lib/server/vault.ts, `again`).
  useEffect(() => {
    if (!sig || !root || sig === tried) return;
    const t = setTimeout(() => {
      if (claudeMidTurnIn(root)) return;
      setTried(sig);
      void followTurn(root, { transcript: null, corrections: [] });
    }, SETTLE);
    return () => clearTimeout(t);
  }, [sig, root, tried]);

  useEffect(() => {
    if (!fresh) return;
    const t = setTimeout(() => setFresh(false), 15000);
    return () => clearTimeout(t);
  }, [fresh]);

  if (unfollowed && root)
    return (
      <span className="mr-2 flex min-w-0 items-center gap-2 text-amber-ink">
        <span className="truncate" title="This bluprint was made from another copy of the code, so it cannot follow edits here.">
          This bluprint doesn&apos;t follow edits
        </span>
        <button
          type="button"
          onClick={() => {
            setUnfollowed(false);
            openProjects(root);
          }}
          className="shrink-0 cursor-pointer text-accent underline"
        >
          Import to keep it updated
        </button>
        <button type="button" onClick={() => setUnfollowed(false)} aria-label="Dismiss" className="shrink-0 cursor-pointer text-faint hover:text-ink">
          ×
        </button>
      </span>
    );
  // A turn that changed nothing the bluprint covers passes silently.
  if (!u || (u.status === "done" && (!fresh || !u.sections?.length)))
    return behind.length && root ? (
      <span className="mr-2 flex min-w-0 items-center gap-2 text-amber-ink">
        <span className="truncate" title={behind.map((f) => `${f.path} +${f.add} −${f.del}`).join("\n")}>
          Editing · {live?.touched.length ?? 0} {live?.touched.length === 1 ? "section" : "sections"} affected
          {tried === sig ? "" : " · bluprint follows when edits settle"}
        </span>
        <button
          type="button"
          onClick={() => follow(sig)}
          className="shrink-0 cursor-pointer text-accent underline"
        >
          Update now
        </button>
      </span>
    ) : null;
  const what = u.sections?.length ? u.sections.join(", ") : u.changed?.join(", ");
  return (
    <span
      title={u.status === "failed" ? u.error : what}
      className={cn(
        "mr-2 flex min-w-0 max-w-[420px] items-center gap-1.5 truncate",
        u.status === "failed" ? "text-clay-ink" : u.status === "running" ? "text-amber-ink" : "text-accent",
      )}
    >
      {u.status === "running" ? <span aria-hidden className="size-[7px] shrink-0 animate-pulse rounded-full bg-amber-ink" /> : null}
      <span className="truncate">
        {u.status === "running"
          ? "Updating the bluprint to match the code…"
          : u.status === "failed"
            ? "✗ Bluprint update failed"
            : `✓ Bluprint updated: ${u.sections!.join(", ")}`}
      </span>
      {u.status === "done" ? (
        <button type="button" onClick={() => (setFresh(false), openReview("turn:latest"))} className="shrink-0 cursor-pointer underline">
          see what changed
        </button>
      ) : null}
    </span>
  );
}

app/components/chrome/tabs.tsx:
"use client";

import { useEffect, useState, useSyncExternalStore, type ReactNode } from "react";
import { goTo } from "@/components/chrome/crumbs";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { openFile, useOpenFile } from "@/components/bluprint/code";
import { closeTab, follow, insertTab, justOpened, openTab, readTabs, replaceTab, selectTab, useTabs, type Tab } from "@/lib/client/tabs";
import { Menu } from "@/components/ui/menu";
import { cn } from "@/lib/client/utils";

/** What a tab holds, opened: its level, and its file over it. */
/** A tab's name: its file, else its level's title. The top level is "Bluprint": the project's own tab above already names the repository. */
export const tabTitle = (nodeAt: (path: string[]) => { title: string } | null | undefined, path: string[], file?: string) =>
  file ? file.split("/").pop()! : path.length ? (nodeAt(path)?.title ?? "Bluprint") : "Bluprint";

/** A floor plan: the Bluprint tab, the top of the bluprint. Drawn like the workspace's tab glyphs. */
export function BlueprintIcon() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden className="mr-0.5 size-3 shrink-0">
      <rect x="2.5" y="2.5" width="11" height="11" rx="1" />
      <path d="M7.5 2.5v6h6" />
      <path d="M2.5 10.5h3" />
    </svg>
  );
}

export const show = (t: Tab) => (t.file ? openFile(t.path, t.file) : goTo(t.path));

/** Opens a level of the open bluprint in a new tab, in front. */
export function openInTab(bluprint: string, path: string[]) {
  openTab(bluprint, path);
  goTo(path);
}

/**
 * Where a part dragged off the bluprint (components/bluprint/canvas.tsx) goes on a strip of
 * the bluprint's tabs, as Chrome takes a dragged link: between two tabs, a new tab
 * there (`at`, with `x` the gap's place on the strip); over a tab's middle,
 * that tab. `strip` says which strip: the bluprint's own, or the main view's
 * (components/agent/workspace.tsx), drawn over it while a workspace tab is there.
 */
export type Drop = { strip: string } & ({ at: number; x: number } | { on: number });

/** Where on the strip in view a part let go at (x, y) lands, if on it at all. */
export function dropAt(x: number, y: number): Drop | null {
  const inside = (r: DOMRect) => x >= r.left && x <= r.right && y >= r.top && y <= r.bottom;
  const strips = [...document.querySelectorAll<HTMLElement>("[data-section-tabs]")].filter(
    (el) => el.checkVisibility() && inside(el.getBoundingClientRect()),
  );
  const strip = strips.find((el) => el.dataset.sectionTabs === "main") ?? strips[0];
  if (!strip) return null;
  const which = strip.dataset.sectionTabs!;
  const s = strip.getBoundingClientRect();
  const tabs = [...strip.querySelectorAll<HTMLElement>('[role="tab"][data-tab-id]')];
  const gap = (left: number) => left - s.left + strip.scrollLeft;
  for (const [i, el] of tabs.entries()) {
    const r = el.getBoundingClientRect();
    if (x < r.left + r.width / 4) return { strip: which, at: i, x: gap(r.left - 1) };
    if (x <= r.right - r.width / 4) return { strip: which, on: Number(el.dataset.tabId) };
  }
  const last = tabs.at(-1)?.getBoundingClientRect();
  return { strip: which, at: tabs.length, x: gap(last ? last.right + 1 : s.left + 6) };
}

/** A part being dragged: its name, where the pointer is, and where it would land. */
export interface PartDrag {
  label: string;
  x: number;
  y: number;
  drop: Drop | null;
}

let dragged: PartDrag | null = null;
const watchers = new Set<() => void>();
const watch = (f: () => void) => {
  watchers.add(f);
  return () => void watchers.delete(f);
};

export function setPartDrag(next: PartDrag | null) {
  dragged = next;
  for (const f of watchers) f();
}

const usePartDrag = () => useSyncExternalStore(watch, () => dragged, () => null);

/** Where a part dragged over `strip` would land there, if it is over it. */
export function useDropOn(strip: string) {
  const drop = usePartDrag()?.drop;
  return drop?.strip === strip ? drop : null;
}

/** A tab a dragged part would be let go into. */
export const DROP_TARGET = "border-accent bg-accent/25 text-ink hover:bg-accent/25";

/** The gap a dragged part would open a new tab in. */
export function DropMarker({ drop }: { drop: Drop | null }) {
  return drop && "at" in drop ? (
    <span
      aria-hidden
      style={{ left: drop.x }}
      className="pointer-events-none absolute bottom-0.5 top-[5px] w-[2px] -translate-x-1/2 bg-accent"
    />
  ) : null;
}

/** A part let go on the strip: into a new tab between two, or into the tab it was dropped on. */
export function dropInTab(bluprint: string, path: string[], drop: Drop) {
  if ("on" in drop) replaceTab(bluprint, drop.on, path);
  else insertTab(bluprint, path, drop.at);
  goTo(path);
}

/** What follows the pointer while a part is dragged: its name, and what letting go here does. */
export function DragChip() {
  const d = usePartDrag();
  if (!d) return null;
  const { label, x, y, drop } = d;
  return (
    <div
      aria-hidden
      style={{ left: x + 12, top: y + 10 }}
      className="pointer-events-none fixed z-50 flex max-w-[320px] items-center gap-1.5 border border-border-gray bg-card px-2.5 py-1 text-[12px] text-ink shadow-lift"
    >
      <span className="truncate">{label}</span>
      {drop ? <span className="shrink-0 text-faint">→ {"on" in drop ? "replace" : "new tab"}</span> : null}
    </div>
  );
}

/** A Preview tab asked for from the main view's `+`; the workspace (components/agent/workspace.tsx) opens it. */
export const OPEN_PREVIEW = "bluprint:new-preview";
/** An empty tab asked for from the main view's `+`; the workspace opens it too. */
export const OPEN_BLANK = "bluprint:new-blank";

/** The main view's `+`: another tab of the bluprint, a Preview, or an empty tab. */
export function NewTab({ onBluprint }: { onBluprint: () => void }) {
  const [menu, setMenu] = useState<{ x: number; y: number } | null>(null);
  return (
    <>
      <button
        type="button"
        onClick={(e) => {
          const r = e.currentTarget.getBoundingClientRect();
          setMenu({ x: r.left, y: r.bottom + 4 });
        }}
        aria-label="New tab"
        aria-haspopup="menu"
        title="New tab"
        className="flex h-6 w-6 shrink-0 cursor-pointer items-center self-center justify-center text-faint transition-colors hover:bg-surface-container hover:text-ink focus-visible:outline-2 focus-visible:outline-accent"
      >
        <svg aria-hidden width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round">
          <path d="M5 1.5v7M1.5 5h7" />
        </svg>
      </button>
      {menu ? (
        <Menu
          x={menu.x}
          y={menu.y}
          onClose={() => setMenu(null)}
          items={[
            { label: "Bluprint", onClick: onBluprint },
            { label: "Preview", onClick: () => window.dispatchEvent(new Event(OPEN_PREVIEW)) },
            { label: "Empty tab", onClick: () => window.dispatchEvent(new Event(OPEN_BLANK)) },
          ]}
        />
      ) : null}
    </>
  );
}

/**
 * The landing page's demo repositories, when it frames this bluprint
 * (landing/components/landing-demo.tsx): it posts them in, and the strip
 * shows one tab per repository, as if each were open, instead of the bluprint's
 * own. Picking one posts back, and the landing points the frame at it.
 */
type Demos = { repos: { id: string; label: string }[]; open: string };
let demos: Demos | null = null;
const demoWatchers = new Set<() => void>();
if (typeof window !== "undefined" && window.parent !== window) {
  window.addEventListener("message", (e) => {
    if (e.origin !== location.origin || e.data?.type !== "bluprint:repos") return;
    demos = { repos: e.data.repos, open: e.data.open };
    for (const f of demoWatchers) f();
  });
  // The landing's own post on load can come before this listens, so ask too.
  window.parent.postMessage({ type: "bluprint:ready" }, location.origin);
}
const watchDemos = (f: () => void) => {
  demoWatchers.add(f);
  return () => void demoWatchers.delete(f);
};
const useDemos = () => useSyncExternalStore(watchDemos, () => demos, () => null);

/**
 * The open bluprint's tabs, across the top of the bluprint: one per level the reader
 * has open, named by that level's title, and `+` for another at the top. A
 * part opens in a new tab with a middle click, ⌘/Ctrl-click, or "Open in new
 * tab" on its right-click menu (components/bluprint/canvas.tsx). Ctrl+Tab and
 * Ctrl+Shift+Tab (⌘⇧] and ⌘⇧[ on a Mac) step through them; Ctrl+W (⌘W on a
 * Mac) closes the one in front.
 */
export function SectionTabs({ path }: { path: string[] }) {
  const { name, nodeAt } = useBluprint();
  const state = useTabs(name);
  const file = useOpenFile()?.file;
  const key = `${path.join("/")}|${file ?? ""}`;
  // Only when the level or its file changes, not when a tab comes forward:
  // the tab brought forward already holds what is about to open.
  useEffect(() => {
    follow(name, path, file);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [name, key]);
  const tabs = state?.tabs ?? [{ id: 0, path }];
  const active = state?.active ?? 0;
  const many = tabs.length > 1;
  const drop = useDropOn("bluprint");
  const framed = useDemos();
  const titleOf = (t: Tab) => tabTitle(nodeAt, t.path, t.file);

  const select = (id: number) => {
    const p = selectTab(name, id);
    if (p) show(p);
  };
  const close = (id: number) => {
    const p = closeTab(name, id);
    if (p) show(p);
  };

  // Read fresh on each key rather than closed over, so a held Ctrl+Tab steps
  // from the tab it just reached.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      // Inside the workspace these keys are its own tabs' (components/agent/workspace.tsx).
      if ((e.target as Element | null)?.closest?.('[aria-label="Workspace"]')) return;
      const t = readTabs(name);
      if (!t) return;
      const at = t.tabs.findIndex((x) => x.id === t.active);
      const mac = /Mac|iPhone|iPad/.test(navigator.platform);
      const bracket = mac && e.metaKey && e.shiftKey && !e.ctrlKey && !e.altKey && (e.code === "BracketRight" || e.code === "BracketLeft");
      if ((e.code === "Tab" && e.ctrlKey && !e.altKey && !e.metaKey) || bracket) {
        e.preventDefault();
        const step = bracket ? (e.code === "BracketRight" ? 1 : -1) : e.shiftKey ? -1 : 1;
        const next = t.tabs[(at + step + t.tabs.length) % t.tabs.length];
        if (next.id !== t.active) {
          const p = selectTab(name, next.id);
          if (p) show(p);
        }
        return;
      }
      const mod = mac ? e.metaKey : e.ctrlKey;
      if (e.code === "KeyW" && mod && !e.shiftKey && !e.altKey) {
        e.preventDefault();
        const p = closeTab(name, t.active);
        if (p) show(p);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [name]);

  if (framed)
    return (
      // On the landing page the strip is the sheet's, white with a line of its ink, not one of the app's black bars.
      <div role="tablist" data-chrome aria-label="Repository" className={cn(TAB_STRIP, "shadow-[inset_0_-1px_0_var(--color-ink)]")}>
        {framed.repos.map((r, i) => (
          <SectionTab
            key={r.id}
            id={i}
            label={r.label}
            home={false}
            active={r.id === framed.open}
            target={false}
            onSelect={() => window.parent.postMessage({ type: "bluprint:open", id: r.id }, location.origin)}
          />
        ))}
      </div>
    );

  return (
    <div
      role="tablist"
      data-chrome="bar"
      data-section-tabs="bluprint"
      aria-label={`Open sections of ${name}`}
      className={cn(TAB_STRIP, "relative")}
    >
      {tabs.map((t) => (
        <SectionTab
          key={t.id}
          id={t.id}
          label={titleOf(t)}
          home={!t.path.length && !t.file}
          active={t.id === active}
          target={drop !== null && "on" in drop && drop.on === t.id}
          onSelect={() => select(t.id)}
          onClose={many ? () => close(t.id) : undefined}
        />
      ))}
      <NewTab onBluprint={() => openInTab(name, [])} />
      <DropMarker drop={drop} />
    </div>
  );
}

/** One tab: a click brings it to the front, × or a middle click closes it. */
function SectionTab({
  id,
  label,
  home,
  active,
  target,
  onSelect,
  onClose,
}: {
  id: number;
  label: string;
  /** The top of the bluprint, marked with a floor plan. */
  home: boolean;
  active: boolean;
  /** A part is dragged over it, to be let go into it. */
  target: boolean;
  onSelect: () => void;
  onClose?: () => void;
}) {
  return (
    <div
      role="tab"
      data-tab-id={id}
      aria-selected={active}
      tabIndex={0}
      title={label}
      onClick={active ? undefined : onSelect}
      onKeyDown={(e) => {
        if (!active && (e.key === "Enter" || e.key === " ")) {
          e.preventDefault();
          onSelect();
        }
      }}
      onAuxClick={(e) => {
        if (e.button === 1 && onClose) {
          e.preventDefault();
          onClose();
        }
      }}
      className={cn(
        tabLook(active, !!onClose),
        !active && "cursor-pointer",
        target && DROP_TARGET,
        justOpened(id) && TAB_OPENED,
      )}
    >
      {home ? <BlueprintIcon /> : null}
      <TabLabel>{label}</TabLabel>
      {onClose ? <TabClose label={label} active={active} onClose={onClose} /> : null}
    </div>
  );
}

/*
 * The look of a strip of tabs over the main view, shared with the main view's
 * strip when a workspace tab is dragged into it (components/agent/workspace.tsx),
 * so the bluprint's tabs read the same with or without one there.
 */

/** A tab just opened from inside the page: it rises in lit with the accent, so the eye finds it. */
export const TAB_OPENED = "animate-[tab-opened_1.4s_ease-out]";

/** The strip. Its bottom line is an inset shadow rather than a border, so the
 * tab in front can paint over it and run on into what is below. */
export const TAB_STRIP =
  "flex h-8 shrink-0 items-end gap-0.5 overflow-x-auto bg-surface-container-low px-1.5 shadow-[inset_0_-1px_0_var(--color-border-gray)]";

/** A tab. The one in front is the bluprint's own ground, open at the bottom, so it
 * reads as the top of the page beneath rather than a button on the strip. */
export function tabLook(active: boolean, closable: boolean) {
  return cn(
    "group flex h-[29px] min-w-0 max-w-[200px] shrink-0 items-center gap-1 border border-b-0 pl-2.5 text-[12px] transition-colors focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent",
    closable ? "pr-1" : "pr-2.5",
    active
      ? "border-border-gray bg-paper font-semibold text-ink"
      : "border-transparent text-muted-slate hover:bg-surface-container hover:text-ink",
  );
}

/** A tab's name. A hidden bold copy holds every tab at the width it has in
 * front, so bringing one forward doesn't shift the others along. */
export function TabLabel({ children }: { children: ReactNode }) {
  return (
    <span className="grid min-w-0">
      <span className="truncate [grid-area:1/1]">{children}</span>
      <span aria-hidden className="invisible truncate font-semibold [grid-area:1/1]">
        {children}
      </span>
    </span>
  );
}

/** A tab's ×, shown on the tab in front and on hover. */
export function TabClose({ label, active, onClose }: { label: string; active: boolean; onClose: () => void }) {
  return (
    <button
      type="button"
      data-close
      onClick={(e) => {
        e.stopPropagation();
        onClose();
      }}
      aria-label={`Close ${label}`}
      className={cn(
        "flex h-4 w-4 shrink-0 cursor-pointer items-center justify-center text-faint hover:bg-border-gray hover:text-ink",
        active ? "" : "opacity-0 group-hover:opacity-100 focus-visible:opacity-100",
      )}
    >
      <svg aria-hidden width="8" height="8" viewBox="0 0 8 8" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round">
        <path d="m1.5 1.5 5 5m0-5-5 5" />
      </svg>
    </button>
  );
}

app/components/chrome/titlebar.tsx:
"use client";

import { listen } from "@tauri-apps/api/event";
import { getCurrentWindow } from "@tauri-apps/api/window";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";
import { openSettings } from "@/lib/client/settings";
import { openPalette } from "@/components/chrome/palette";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { openProjects } from "@/components/projects/projects";
import { keys } from "@/components/ui/button";
import { openHistory } from "@/components/review/additions";
import { openDiff, useDiff } from "@/components/review/diff";
import { StatusDot } from "@/components/agent/status-dot";
import { toggleWorkspace } from "@/lib/agent/workspace-toggle";
import { TabClose } from "@/components/chrome/tabs";
import { arrived, closeProject, keepOnly, useOpenProjects } from "@/lib/client/open-projects";
import { DocIcon } from "@/components/bluprint/docs";
import { LOGOS } from "@/components/agent/agents";
import { STATIC_BLUPRINT } from "@/lib/bluprint/source";
import { cn } from "@/lib/client/utils";
import { useDesktop } from "@/lib/client/platform";

/**
 * The window's own title bar. The native one is off (`decorations: false` in
 * tauri.conf.json), so this draws the bluprint's name, which switches bluprints, the tools, and the window
 * buttons, in the page's palette rather than the desktop's. The bluprint below has no header of its
 * own in the desktop app.
 *
 * Everything marked `data-tauri-drag-region` moves the window, and a double
 * click on it maximizes, as a native bar does. Buttons sit outside those
 * regions so a click on one is never read as the start of a drag. Outside the
 * desktop app (plain `next dev` in a browser) there is no window to drive, so
 * nothing is drawn.
 *
 * On a Mac the window keeps its own traffic lights (tauri.macos.conf.json
 * overlays them on this bar), so the bar leaves room for them on the left and
 * draws no buttons of its own on the right.
 */


/**
 * `bare` is the window with no bluprint open (components/chrome/welcome.tsx): the frame,
 * settings and the window buttons, so it can still be moved and closed. The
 * page itself offers Open Folder there, as VS Code's welcome does.
 */
export function Titlebar({ bare }: { bare?: boolean }) {
  const desktop = useDesktop();
  const [maximized, setMaximized] = useState(false);
  // Only read once `desktop` is true, which is never on the server.
  const mac = desktop && /Mac/.test(navigator.userAgent);

  useEffect(() => {
    if (!desktop) return;
    const win = getCurrentWindow();
    let live = true;
    const sync = () => win.isMaximized().then((m) => live && setMaximized(m));
    sync();
    const off = win.onResized(sync);
    return () => {
      live = false;
      off.then((f) => f());
    };
  }, [desktop]);

  if (!desktop) return null;
  const win = getCurrentWindow();
  return (
    // Two columns: the right one never gives up its buttons; when the window
    // is too narrow for both, the bluprint's name truncates first.
    <header
      data-tauri-drag-region
      data-chrome="bar"
      className="grid h-9 shrink-0 select-none grid-cols-[minmax(0,1fr)_max-content] items-center border-b border-border-gray bg-surface-container-low"
    >
      {/* The Mac's traffic lights take the left edge. */}
      <div data-tauri-drag-region className={cn("flex h-full min-w-0 items-center", mac ? "pl-[78px]" : "pl-1.5")}>
        {bare ? (
          <span data-tauri-drag-region className="px-2 font-mono text-[11.5px] font-semibold text-ink">
            Bluprint
          </span>
        ) : (
          <Where mac={mac} />
        )}
      </div>
      <div data-tauri-drag-region className="flex h-full items-center justify-end">
        {bare ? null : <BluprintTools />}
        <span aria-hidden className="mx-1 h-4 w-px bg-border-strong" />
        {bare ? null : (
          <Control
            label={STATIC_BLUPRINT ? `Claude (${keys(mac, "`", { ctrl: true })})` : `Claude Code & terminal (${keys(mac, "`")})`}
            onClick={toggleWorkspace}
          >
            {/* A published page has no terminal, only Claude (components/agent/claude-web.tsx). */}
            {STATIC_BLUPRINT ? (
              <path d={LOGOS.claude.d} transform="scale(0.6667)" fill={LOGOS.claude.color} stroke="none" />
            ) : (
              <>
                <rect x="1.5" y="2.5" width="13" height="11" rx="2" />
                <path d="M4.5 6.5 6.5 8l-2 1.5M8.5 10h3" />
              </>
            )}
          </Control>
        )}
        <Control label="Settings" onClick={openSettings}>
          {/* Lucide's gear, drawn on 24 and scaled to the 16 grid; the stroke
              is scaled up to match so it reads as heavy as its neighbours. */}
          <g transform="scale(0.6667)" strokeWidth="1.875">
            <path d="M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.08a2 2 0 0 1-1-1.74v-.5a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z" />
            <circle cx="12" cy="12" r="3" />
          </g>
        </Control>
        {mac ? null : (
          <>
            <span aria-hidden className="mx-1 h-4 w-px bg-border-strong" />
            <Control win label="Minimize" onClick={() => win.minimize()}>
              <path d="M4 8h8" />
            </Control>
            <Control win label={maximized ? "Restore" : "Maximize"} onClick={() => win.toggleMaximize()}>
              {maximized ? (
                <>
                  <rect x="3.5" y="5.5" width="7" height="7" rx="1" />
                  <path d="M6 5.5V4.5a1 1 0 0 1 1-1h4.5a1 1 0 0 1 1 1V9a1 1 0 0 1-1 1h-1" />
            </>
          ) : (
            <rect x="4" y="4" width="8" height="8" rx="1" />
          )}
        </Control>
        <Control win label="Close" onClick={() => win.close()} danger>
          <path d="m4.5 4.5 7 7m0-7-7 7" />
        </Control>
          </>
        )}
      </div>
    </header>
  );
}

/**
 * The projects open in the window, a tab each, with the dot of the loudest
 * Claude among its workspace tabs (components/agent/workspace.tsx); + opens another,
 * imports one, or manages them. Switching keeps every terminal running, and
 * the workspace shows the tabs of the project switched to. Cmd+1–9 (Ctrl+1–9
 * off a Mac) picks one, Ctrl+Tab the last. Where you are inside the bluprint is
 * the bluprint tabs' to say (components/chrome/tabs.tsx).
 */
function Where({ mac }: { mac: boolean }) {
  const { name, bluprints } = useBluprint();
  const router = useRouter();
  const { open, last, status } = useOpenProjects();
  const shown = open.flatMap((id) => bluprints.filter((m) => m.id === id));
  const go = useCallback((id: string | null | undefined) => id && id !== name && router.push(`/?bluprint=${encodeURIComponent(id)}`), [name, router]);

  const was = useRef<string | null>(null);
  useEffect(() => {
    arrived(name, was.current);
    was.current = name;
  }, [name]);
  useEffect(() => keepOnly(bluprints.map((m) => m.id)), [bluprints]);

  // Off a Mac here; on one the menu bar takes the keys (src-tauri/src/lib.rs),
  // so they work from inside a Preview's page too.
  const ids = shown.map((m) => m.id).join("\n");
  useEffect(() => {
    const pick = (n: string) => go(n === "last" ? last : ids.split("\n")[Number(n) - 1]);
    const onKey = (e: KeyboardEvent) => {
      if (!e.ctrlKey || e.metaKey || e.altKey) return;
      // Ctrl+Tab is the tabs' own (components/agent/workspace.tsx, components/chrome/tabs.tsx).
      const n = !e.shiftKey && /^Digit[1-9]$/.test(e.code) ? e.code.slice(5) : null;
      if (!n) return;
      e.preventDefault();
      e.stopPropagation();
      pick(n);
    };
    if (!mac) window.addEventListener("keydown", onKey, true);
    const fromMenu = mac ? listen<string>("bluprint:project", (e) => pick(e.payload)) : undefined;
    return () => {
      window.removeEventListener("keydown", onKey, true);
      void fromMenu?.then((f) => f());
    };
  }, [mac, go, last, ids]);

  const close = (id: string) => {
    if (id === name) {
      const at = shown.findIndex((m) => m.id === id);
      go((shown[at + 1] ?? shown[at - 1])?.id);
    }
    const root = shown.find((m) => m.id === id)?.root;
    closeProject(id, root && !shown.some((m) => m.id !== id && m.root === root) ? root : undefined);
  };

  return (
    <>
      <div role="tablist" aria-label="Open projects" className="flex min-w-0 items-center gap-0.5">
        {shown.map((m, i) => {
          const here = m.id === name;
          const dot = m.root ? status[m.root] : undefined;
          return (
            // Outside the drag region, so a click switches rather than moving the window.
            <div
              key={m.id}
              role="tab"
              aria-selected={here}
              title={`${m.label}${i < 9 ? ` (${keys(mac, String(i + 1))})` : ""}`}
              className={cn(
                "group flex h-6 min-w-0 max-w-48 items-center gap-1.5 pl-2 pr-1 font-mono text-[11.5px] transition-colors",
                here ? "bg-surface-container font-semibold text-ink" : "text-muted-slate hover:bg-surface-container hover:text-ink",
              )}
            >
              <button type="button" onClick={() => go(m.id)} className="flex min-w-0 cursor-pointer items-center gap-1.5 focus-visible:outline-2 focus-visible:outline-accent">
                <span className="truncate">{m.label}</span>
                {dot && <StatusDot status={dot} />}
              </button>
              {shown.length > 1 ? <TabClose label={m.label} active={here} onClose={() => close(m.id)} /> : <span className="w-1" />}
            </div>
          );
        })}
      </div>
      <button
        type="button"
        onClick={() => openProjects()}
        aria-label="Open another project"
        title="Open another project"
        className="flex h-6 w-6 shrink-0 cursor-pointer items-center justify-center text-faint transition-colors hover:bg-surface-container hover:text-ink focus-visible:outline-2 focus-visible:outline-accent"
      >
        <svg aria-hidden width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round">
          <path d="M5 1.5v7M1.5 5h7" />
        </svg>
      </button>
    </>
  );
}

/** The tools that act on the open bluprint. */
function BluprintTools() {
  const diff = useDiff();
  return (
    <>
      <Control
        label={diff?.diff || diff?.loading ? "Version control — showing changes on the bluprint. Open the history" : "Version control — the commit history, and what each changed"}
        onClick={openDiff}
        active={Boolean(diff?.diff || diff?.loading)}
      >
        {/* Lucide's git-branch, the glyph editors give source control. */}
        <g transform="scale(0.6667)" strokeWidth="1.875">
          <path d="M6 3v12" />
          <circle cx="18" cy="6" r="3" />
          <circle cx="6" cy="18" r="3" />
          <path d="M18 9a9 9 0 0 1-9 9" />
        </g>
      </Control>
      <Control label="Docs — read the project's Markdown" onClick={() => openPalette("docs")}>
        <DocIcon />
      </Control>
      <Control label="What you added to this bluprint — and a way back" onClick={openHistory}>
        {/* A clock turned back: the history of the reader's own additions. */}
        <circle cx="8" cy="8" r="6" />
        <path d="M8 4.5V8l2.5 1.5" />
      </Control>
    </>
  );
}

function Control({
  label,
  onClick,
  danger,
  win,
  className,
  active,
  children,
}: {
  label: string;
  onClick: () => void;
  danger?: boolean;
  /** On: the mode this button turns on is showing. */
  active?: boolean;
  /** One of the window's own buttons: minimize, maximize, close. */
  win?: boolean;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={label}
      aria-pressed={active}
      title={label}
      className={cn(
        "flex cursor-pointer items-center justify-center text-muted-slate transition-colors focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent",
        // Window buttons fill the bar's height, as native ones do; the tools
        // are small square targets, as in an editor's title bar.
        win ? "h-full w-11" : "mx-px h-7 w-7",
        danger ? "hover:bg-clay-ink hover:text-paper" : "hover:bg-surface-container hover:text-ink",
        active && "bg-accent text-on-accent hover:bg-accent-strong hover:text-on-accent",
        className,
      )}
    >
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.25" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
        {children}
      </svg>
    </button>
  );
}

app/components/chrome/welcome.tsx:
"use client";

import { useRouter } from "next/navigation";
import { useState, useSyncExternalStore } from "react";
import { Button, Kbd } from "@/components/ui/button";
import { newProject, openFolder, openProjects } from "@/components/projects/projects";
import { cn } from "@/lib/client/utils";
import { readSettings, saveSettings, useSettings, type Theme } from "@/lib/client/settings";
import type { BluprintEntry } from "@/lib/server/bluprints";

/**
 * The blank page: what the window shows with no project open — none asked
 * for, the one asked for is gone, or the open one was just deleted. Laid out
 * as VS Code's welcome is: Start on one side, Recent on the other, which with
 * no projects yet is just Start.
 */
export function NoProject({ bluprints }: { bluprints: BluprintEntry[] }) {
  const router = useRouter();
  const { onboarded } = useSettings();
  // The saved settings are only known in the browser: until then show
  // nothing, so a returning reader never sees the tour flash by.
  const ready = useSyncExternalStore(noop, () => true, () => false);
  if (!ready) return <main className="flex-1 bg-paper" />;
  if (!onboarded && !bluprints.length) return <Tour />;
  return (
    <main className="flex min-h-0 flex-1 justify-center overflow-y-auto bg-paper px-6 py-16">
      <div className="w-full max-w-[640px]">
        <h1 className="font-display text-[32px] font-normal leading-[1.05] tracking-[-0.016em] text-ink">Make a bluprint of a repository</h1>
        <p className="mt-1 text-[14px] text-on-surface-variant">Claude Code reads it and writes a bluprint you can open a level at a time, down to the line.</p>
        <div className="mt-8 grid gap-10 sm:grid-cols-2">
          <section>
            <h2 className="mb-2 text-[13px] font-semibold text-ink">Start</h2>
            <ul className="flex flex-col gap-1.5 text-[13px]">
              <li>
                <button type="button" onClick={() => void openFolder()} className={LINK}>
                  Open Folder…
                </button>
              </li>
              <li>
                <button type="button" onClick={newProject} className={LINK}>
                  New Project…
                </button>
              </li>
              {bluprints.length ? (
                <li>
                  <button type="button" onClick={() => openProjects()} className={LINK}>
                    Manage Projects…
                  </button>
                </li>
              ) : null}
            </ul>
          </section>
          {bluprints.length ? (
            <section>
              <h2 className="mb-2 text-[13px] font-semibold text-ink">Recent</h2>
              <ul className="flex flex-col gap-1.5 text-[13px]">
                {bluprints.map((m) => (
                  <li key={m.id}>
                    <button type="button" onClick={() => router.push(`/?bluprint=${encodeURIComponent(m.id)}`)} className={cn(LINK, "max-w-full truncate font-mono")}>
                      {m.label}
                    </button>
                  </li>
                ))}
              </ul>
            </section>
          ) : null}
        </div>
        <p className="mt-10 flex items-center gap-1.5 text-[12px] text-faint">
          Once its bluprint is made, <Kbd>Ctrl K</Kbd> goes to any level.
        </p>
      </div>
    </main>
  );
}

const noop = () => () => {};
const finish = () => saveSettings({ ...readSettings(), onboarded: true });

/**
 * The first run: what a bluprint is, shown by opening one, then the theme, then
 * the way in. Three steps, any of them skippable.
 */
function Tour() {
  const [step, setStep] = useState(0);
  const steps = [
    { title: "Your code, as a bluprint", body: "Bluprint reads a repository and draws it a level at a time. Click a box to go down a level.", view: <Demo /> },
    { title: "Pick a look", body: "It changes as you choose. Settings can change it later.", view: <Themes /> },
    { title: "Make your first bluprint", body: "Open a folder on this machine, or clone one from GitHub. Claude Code writes the bluprint. When it finishes, Bluprint sends us how long it took and what it cost, never your code; Settings turns that off.", view: <Begin /> },
  ];
  const last = step === steps.length - 1;
  return (
    <main className="flex min-h-0 flex-1 justify-center overflow-y-auto bg-paper px-6 py-16">
      <div className="w-full max-w-[640px]">
        <p className="font-mono text-[11px] uppercase tracking-[0.08em] text-faint">
          {step + 1} / {steps.length}
        </p>
        <div key={step} className="animate-[tour-in_220ms_ease-out]">
          <h1 className="mt-2 font-display text-[32px] font-normal leading-[1.05] tracking-[-0.016em] text-ink">{steps[step].title}</h1>
          <p className="mt-1 text-[14px] text-on-surface-variant">{steps[step].body}</p>
          <div className="mt-8">{steps[step].view}</div>
        </div>
        <div className="mt-10 flex items-center gap-2">
          <div className="mr-auto flex gap-1.5" aria-hidden>
            {steps.map((_, i) => (
              <span key={i} className={cn("h-1.5 w-6 transition-colors", i <= step ? "bg-accent" : "bg-border-gray")} />
            ))}
          </div>
          <Button variant="ghost" onClick={finish}>
            {last ? "Not now" : "Skip"}
          </Button>
          {step > 0 ? <Button onClick={() => setStep(step - 1)}>Back</Button> : null}
          {last ? null : (
            <Button variant="primary" onClick={() => setStep(step + 1)}>
              Next
            </Button>
          )}
        </div>
      </div>
    </main>
  );
}

/* ── step 1: a bluprint you can open ───────────────────────────────── */

type Node = { label: string; sub: string; kids?: Node[]; code?: string[] };

const SAMPLE: Node = {
  label: "my-app",
  sub: "the whole repository",
  kids: [
    {
      label: "Sign in",
      sub: "what a person does first",
      kids: [
        { label: "Login form", sub: "components/login.tsx", code: ["export function Login() {", "  const [email, setEmail] = useState(\"\");", "  return <form onSubmit={send}>…</form>;", "}"] },
        { label: "Session", sub: "lib/session.ts", code: ["export async function signIn(email: string) {", "  const token = await api.post(\"/login\", { email });", "  cookies.set(\"session\", token);", "}"] },
      ],
    },
    {
      label: "Checkout",
      sub: "paying for the cart",
      kids: [
        { label: "Cart", sub: "lib/cart.ts", code: ["export const total = (items: Item[]) =>", "  items.reduce((n, i) => n + i.price * i.qty, 0);"] },
        { label: "Payment", sub: "api/pay.ts", code: ["export async function POST(req: Request) {", "  const { cart } = await req.json();", "  return charge(total(cart.items));", "}"] },
      ],
    },
    { label: "Data", sub: "where things are kept", kids: [{ label: "Database", sub: "db/schema.sql", code: ["create table users (", "  id serial primary key,", "  email text unique", ");"] }] },
  ],
};

function Demo() {
  const [path, setPath] = useState<Node[]>([SAMPLE]);
  const here = path[path.length - 1];
  return (
    <div className="border border-border-strong bg-surface">
      <div className="flex items-center gap-1 border-b border-border-gray px-3 py-2 font-mono text-[11.5px]">
        {path.map((n, i) => (
          <span key={i} className="flex items-center gap-1">
            {i ? <span className="text-faint">/</span> : null}
            <button
              type="button"
              disabled={i === path.length - 1}
              onClick={() => setPath(path.slice(0, i + 1))}
              className={cn(i === path.length - 1 ? "text-ink" : "cursor-pointer text-accent hover:underline")}
            >
              {n.label}
            </button>
          </span>
        ))}
      </div>
      <div key={here.label} className="min-h-[168px] animate-[tour-in_180ms_ease-out] p-4">
        {here.code ? (
          <pre className="overflow-x-auto bg-code p-3 font-mono text-[12px] leading-[1.6] text-code-plain">{here.code.join("\n")}</pre>
        ) : (
          <div className="grid gap-3 sm:grid-cols-3">
            {here.kids?.map((k, i) => (
              <button
                key={k.label}
                type="button"
                onClick={() => setPath([...path, k])}
                className="group cursor-pointer border border-border-strong bg-card p-3 text-left transition-[border-color,transform] duration-100 hover:-translate-y-px hover:border-accent"
              >
                <span className="block font-display text-[16px] text-ink" style={{ color: `var(--color-sec-${i + 1}-ink)` }}>
                  {k.label}
                </span>
                <span className="mt-0.5 block truncate text-[12px] text-muted-slate">{k.sub}</span>
                <span className="mt-3 block font-mono text-[10.5px] uppercase tracking-[0.06em] text-faint group-hover:text-accent">
                  {k.code ? "View code →" : "Open →"}
                </span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/* ── step 2: the theme ────────────────────────────────────────── */

/** Each theme's own colours, so a card shows its theme whatever the page is in. */
const LOOKS: { value: Theme; label: string; note: string; bar: string; paper: string; ink: string; line: string; box: string; tint: string }[] = [
  { value: "classic", label: "Classic", note: "Cobalt ink on white", bar: "#0a0a0b", paper: "#ffffff", ink: "#2438c8", line: "#a9b3ee", box: "#f6f8fe", tint: "#e3e8fc" },
  { value: "light", label: "Light", note: "Plain, near-black ink", bar: "#f4f4f5", paper: "#ffffff", ink: "#111113", line: "#e4e4e7", box: "#f7f7f8", tint: "#ebebed" },
  { value: "dark", label: "Dark", note: "Easy at night", bar: "#000000", paper: "#0f0f11", ink: "#fafafa", line: "#3a3a40", box: "#18181b", tint: "#222226" },
];

function Themes() {
  const { theme } = useSettings();
  return (
    <div role="radiogroup" aria-label="Theme" className="grid gap-3 sm:grid-cols-3">
      {LOOKS.map((l) => {
        const on = theme === l.value;
        return (
          <button
            key={l.value}
            type="button"
            role="radio"
            aria-checked={on}
            onClick={() => saveSettings({ ...readSettings(), theme: l.value })}
            className={cn(
              "cursor-pointer border p-2 text-left transition-[border-color,box-shadow] duration-100",
              on ? "border-accent shadow-[0_0_0_1px_var(--color-accent)]" : "border-border-gray hover:border-border-strong",
            )}
          >
            <Mini look={l} />
            <span className="mt-2 flex items-center justify-between px-1">
              <span className="text-[13px] font-semibold text-ink">{l.label}</span>
              {on ? <span className="font-mono text-[10.5px] uppercase tracking-[0.06em] text-accent">On</span> : null}
            </span>
            <span className="block px-1 text-[12px] text-muted-slate">{l.note}</span>
          </button>
        );
      })}
    </div>
  );
}

/** The app in miniature: a title bar, a heading, three boxes, a line of code. */
function Mini({ look: l }: { look: (typeof LOOKS)[number] }) {
  return (
    <span className="block aspect-[4/3] overflow-hidden border" style={{ background: l.paper, borderColor: l.line }} aria-hidden>
      <span className="flex h-[12%] items-center gap-[3px] px-1.5" style={{ background: l.bar }}>
        {[0, 1, 2].map((i) => (
          <span key={i} className="size-[5px] rounded-full" style={{ background: l.line }} />
        ))}
      </span>
      <span className="block px-2.5 pt-2.5">
        <span className="block font-display text-[13px] leading-none" style={{ color: l.ink }}>
          my-app
        </span>
        <span className="mt-1.5 block h-[3px] w-1/2" style={{ background: l.line }} />
        <span className="mt-2.5 grid grid-cols-3 gap-1.5">
          {[0, 1, 2].map((i) => (
            <span key={i} className="block h-7 border p-1" style={{ background: l.box, borderColor: l.line }}>
              <span className="block h-[3px] w-3/4" style={{ background: l.ink }} />
            </span>
          ))}
        </span>
        <span className="mt-2 block h-5 p-1" style={{ background: l.tint }}>
          <span className="block h-[3px] w-2/3" style={{ background: l.ink, opacity: 0.6 }} />
        </span>
      </span>
    </span>
  );
}

/* ── step 3: the way in ───────────────────────────────────────── */

function Begin() {
  const go = (f: () => unknown) => () => {
    finish();
    void f();
  };
  return (
    <div className="grid gap-3 sm:grid-cols-2">
      <button type="button" onClick={go(openFolder)} className={CARD}>
        <span className="block text-[14px] font-semibold text-ink">Open Folder…</span>
        <span className="mt-1 block text-[12.5px] text-muted-slate">A repository already on this machine.</span>
      </button>
      <button type="button" onClick={go(newProject)} className={CARD}>
        <span className="block text-[14px] font-semibold text-ink">New Project…</span>
        <span className="mt-1 block text-[12.5px] text-muted-slate">Clone one from GitHub, then make its bluprint.</span>
      </button>
      <p className="flex items-center gap-1.5 text-[12px] text-faint sm:col-span-2">
        Once its bluprint is made, <Kbd>Ctrl K</Kbd> goes to any level.
      </p>
    </div>
  );
}

const CARD =
  "cursor-pointer border border-border-strong bg-card p-4 text-left transition-[border-color,transform] duration-100 hover:-translate-y-px hover:border-accent focus-visible:outline-2 focus-visible:outline-accent";

const LINK = "cursor-pointer text-left text-accent hover:underline focus-visible:outline-2 focus-visible:outline-accent";

