"use client";

import { invoke, isTauri } from "@tauri-apps/api/core";
import { listen } from "@tauri-apps/api/event";
import { bare } from "@/components/preview/address";
import { DRAIN, type Parts, type Said } from "@/components/preview/parts";

/** Hands what the frame's page and the webview's pages say to `hear`, until the returned call. */
export function listenToPage({ frame, onWeb, browser, hear, replace, setShown }: Pick<Parts, "frame" | "onWeb" | "browser" | "hear" | "replace" | "setShown">) {
  const on = (e: MessageEvent) => {
    if (!frame.current || e.source !== frame.current.contentWindow || !e.data?.__bluprint) return;
    // Behind a page from the web, the frame's page is not the one in front:
    // where it is, what it logs and that it loaded are not this tab's.
    if (onWeb.current && e.data.type !== "reply") return;
    hear.current(e.data);
  };
  window.addEventListener("message", on);
  // Every page of the webview, heard from its first: a load can finish
  // before the webview is shown, or before its open has returned.
  const off = isTauri()
    ? listen<{ label: string; url: string; done: boolean }>("bluprint:browser", (e) => {
        if (e.payload.label !== browser.current || !onWeb.current) return;
        replace.current();
        if (!e.payload.done) return setShown(bare(e.payload.url));
        // Where it ended up, before the page's own word on it is next collected.
        hear.current({ type: "location", url: e.payload.url });
        hear.current({ type: "loaded" });
      })
    : undefined;
  return () => {
    window.removeEventListener("message", on);
    void off?.then((f) => f());
  };
}

/** A page from the web keeps what it says until it is collected: collected for `hear`, until the returned call. */
export function collect(hear: Parts["hear"], web: string) {
  let busy = false;
  const timer = setInterval(() => {
    if (busy) return;
    busy = true;
    invoke<Said[] | null>("browser_eval", { label: web, js: DRAIN })
      .then((all) => all?.forEach((m) => hear.current(m)))
      .catch(() => {})
      .finally(() => (busy = false));
  }, 120);
  return () => clearInterval(timer);
}

app/components/preview/navigation.ts:
"use client";

import { invoke } from "@tauri-apps/api/core";
import { covers, isWeb, pathOf, toWeb } from "@/components/preview/address";
import type { Parts } from "@/components/preview/parts";
import { hostOf } from "@/lib/agent/preview";
import { sleep } from "@/lib/client/utils";

let nextView = 1;

/** How a Preview moves between pages: its own, its address bar's, its keys' and Claude's. */
export function navigation({
  id,
  root,
  frame,
  sheet,
  proxy,
  browser,
  ownStore,
  signingNow,
  onWeb,
  here,
  server,
  missed,
  trail,
  view,
  setPointed,
  setSrc,
  setWeb,
  display,
  fail,
  nextLoad,
}: Parts) {
  /**
   * Opens a page: one from the web in its webview, opened the first time;
   * the dev server's in the frame, without a step in the window's history.
   */
  const go = (url: string) => {
    if (isWeb(url)) {
      onWeb.current = true;
      return void (async () => {
        // A webview has one store for its life: a page kept in the other is opened in a new one.
        const s = signingNow.current;
        const own = s && covers(s.site, url) ? s.project : await invoke<boolean>("signin_project", { root, url }).catch(() => false);
        const label = browser.current;
        if (label && ownStore.current === own) {
          setWeb(label);
          return invoke("browser_go", { label, url });
        }
        if (label) void invoke("browser_close", { label });
        const r = sheet.current?.getBoundingClientRect();
        const { scale: zoom } = view.current;
        // Named before it opens: its first load can be heard before the open returns.
        const opened = `browser-${id}-${nextView++}`;
        browser.current = opened;
        ownStore.current = own;
        try {
          await invoke("browser_open", {
            label: opened,
            url,
            x: r?.x ?? 0,
            y: r?.y ?? 0,
            width: r?.width || 1,
            height: r?.height || 1,
            zoom,
            project: own ? root : null,
          });
        } catch (e) {
          if (browser.current === opened) browser.current = null;
          throw e;
        }
        if (onWeb.current) setWeb(opened);
      })().catch(fail);
    }
    onWeb.current = false;
    setWeb(null);
    const w = frame.current?.contentWindow;
    if (w) w.location.replace(url);
    else setSrc(url);
  };

  /** Opens a page and waits for it: the answer is where it ended up, not where it was asked to go. */
  const arrive = async (open: () => void) => {
    missed.current = null;
    const done = nextLoad();
    open();
    await done;
    if (missed.current) throw new Error(missed.current);
    return `Now at ${display(here.current)}.`;
  };

  /** A path, an address on this machine or the web, a search, or back, forward, reload. */
  const navigate = async (raw: string): Promise<string> => {
    const v = raw.trim();
    if (v === "back" || v === "forward" || v === "reload") {
      const t = trail.current;
      const at = v === "back" ? t.at - 1 : v === "forward" ? t.at + 1 : t.at;
      const url = v === "reload" ? here.current : t.list[at];
      if (!url) return `There is no page to go ${v} to.`;
      if (v !== "reload") {
        t.at = at;
        t.stepping = true;
      }
      return arrive(() => go(url));
    }
    const host = hostOf(v);
    if (!host && !v.startsWith("/")) return arrive(() => go(toWeb(v)));
    if (host && host !== hostOf(server.current ?? "")) {
      // Another server: this tab follows it (the Preview's proxy effect), in front of any page from the web.
      return arrive(() => {
        onWeb.current = false;
        setWeb(null);
        setPointed(/^https?:/.test(v) ? v : `http://${v}`);
      });
    }
    // A tab just opened is still opening its proxy.
    for (let i = 0; i < 50 && server.current && !proxy.current; i++) await sleep(100);
    const p = proxy.current;
    if (!p) throw new Error("The preview has no page open yet.");
    const path = host ? pathOf(v) : v.startsWith("/") ? v : `/${v}`;
    return arrive(() => go(`http://localhost:${p.port}${path}`));
  };

  return { go, navigate };
}

app/components/preview/parts.ts:
import type { Dispatch, RefObject, SetStateAction } from "react";
import type { Target } from "@/lib/agent/context";
import type { Size } from "@/components/preview/viewport";

/** Claude waiting on the user to sign in, and where they chose to keep it. */
export type Signing = { site: string; project: boolean };

export interface Line {
  level: string;
  text: string;
}

/** A message from the agent in the page (src-tauri/src/agent.js). */
export type Said =
  | { type: "location"; url: string; title?: string }
  | { type: "console"; level: string; text: string }
  | { type: "open"; url: string }
  | { type: "reply"; id: number; ok: boolean; value: unknown }
  | { type: "loaded" }
  /** The proxy's waiting page: the server behind it did not answer (src-tauri/src/preview.rs). */
  | { type: "down" }
  /** The user picked one or more things to hand to Claude, the last at (x, y) in the page. */
  | { type: "pick"; x: number; y: number; targets: Target[] }
  | { type: "unpick" }
  /** The page's select mode went on or off (agent.js). */
  | { type: "selecting"; on: boolean }
  /** The page took the keyboard, or was given a browser's key off a Mac. */
  | { type: "focus" }
  | { type: "key"; key: string };

/** What a page from the web has said since it was last asked (agent.js). */
export const DRAIN = "window.__bluprint ? window.__bluprint.drain() : []";

type Set<T> = Dispatch<SetStateAction<T>>;

/**
 * A Preview's refs, setters and own calls (components/preview/preview.tsx),
 * for its code kept outside it: navigation.ts, tools.ts, messages.ts and webview.ts. The
 * Preview gathers them when a call is made, never in render, as refs are
 * only read outside it.
 */
export type Parts = {
  id: number;
  root: string;
  frame: RefObject<HTMLIFrameElement | null>;
  stage: RefObject<HTMLDivElement | null>;
  sheet: RefObject<HTMLDivElement | null>;
  sizeBadge: RefObject<HTMLDivElement | null>;
  proxy: RefObject<{ id: number; port: number } | null>;
  browser: RefObject<string | null>;
  ownStore: RefObject<boolean>;
  signingNow: RefObject<Signing | null>;
  signedIn: RefObject<((done: boolean) => void) | null>;
  onWeb: RefObject<boolean>;
  here: RefObject<string>;
  server: RefObject<string | undefined>;
  log: RefObject<Line[]>;
  dialogs: RefObject<string[]>;
  pending: RefObject<Map<number, { resolve: (v: unknown) => void; reject: (e: Error) => void }>>;
  everLoaded: RefObject<boolean>;
  missed: RefObject<string | null>;
  trail: RefObject<{ list: string[]; at: number; stepping: boolean }>;
  view: RefObject<{ vw: number; vh: number; scale: number }>;
  hear: RefObject<(m: Said) => void>;
  replace: RefObject<() => void>;
  setPointed: Set<string | undefined>;
  setSrc: Set<string | null>;
  setShown: Set<string>;
  setBadge: Set<boolean>;
  setWeb: Set<string | null>;
  setSigning: Set<Signing | null>;
  display: (url: string) => string;
  go: (url: string) => void;
  fail: (e: unknown) => void;
  loaded: () => void;
  nextLoad: () => Promise<void>;
  navigate: (raw: string) => Promise<string>;
  agent: (name: string, args: Record<string, unknown>) => Promise<unknown>;
  resize: (next: Size | null) => void;
};

