app/components/preview/tools.ts:
"use client";

import { invoke } from "@tauri-apps/api/core";
import { getCurrentWebview } from "@tauri-apps/api/webview";
import { covers, isWeb, originOf, SHARED, siteOf, toWeb } from "@/components/preview/address";
import { REAL } from "@/components/preview/keys";
import { DRAIN, type Parts, type Said } from "@/components/preview/parts";
import { clamp } from "@/components/preview/viewport";
import { PRESETS, type Call } from "@/lib/agent/preview";
import { sleep } from "@/lib/client/utils";

type Act = { kind: "move" | "down" | "up" | "drag" | "key" | "text"; x?: number; y?: number; button?: number; clicks?: number; text?: string };

/** Where the agent found a click's target (agent.js `locate`). */
type Located = { x: number; y: number; what: string; native: { kind: "select" | "file" | "color"; ref: string; options?: string } | null };

let nextCall = 1;

/** A call to the agent in the page, answered by its reply as the Preview hears it. */
export const agent = (
  { frame, proxy, onWeb, browser, pending }: Pick<Parts, "frame" | "proxy" | "onWeb" | "browser" | "pending">,
  name: string,
  args: Record<string, unknown>,
) =>
  new Promise<unknown>((resolve, reject) => {
    const w = frame.current?.contentWindow;
    const p = proxy.current;
    const label = onWeb.current ? browser.current : null;
    if (!label && (!w || !p)) return reject(new Error("The preview has no page open yet."));
    const id = nextCall++;
    pending.current.set(id, { resolve, reject });
    if (label)
      void invoke<boolean>("browser_eval", { label, js: `window.__bluprint ? (window.__bluprint.run(${id}, ${JSON.stringify(name)}, ${JSON.stringify(args)}), true) : false` })
        .then((ok) => {
          if (!ok && pending.current.delete(id)) reject(new Error("This page cannot be read or used yet: it may still be loading."));
        })
        .catch((e) => pending.current.delete(id) && reject(new Error(String(e))));
    else w!.postMessage({ __bluprintCmd: true, id, name, args }, `http://localhost:${p!.port}`);
    const wait = args.action === "wait" ? 15000 : 10000;
    setTimeout(() => {
      if (pending.current.delete(id))
        reject(new Error("The page did not answer. It may still be loading: take a screenshot, or try again."));
    }, wait);
  });

/** Claude's browser tools on a Preview, and the sign-in it asks the user for. */
export function tools({
  root,
  frame,
  stage,
  sheet,
  sizeBadge,
  proxy,
  browser,
  signingNow,
  signedIn,
  onWeb,
  here,
  server,
  log,
  dialogs,
  everLoaded,
  view,
  hear,
  setBadge,
  setSigning,
  display,
  go,
  nextLoad,
  navigate,
  agent,
  resize,
}: Parts) {
  /**
   * Whether real input can reach the page: always for a page from the web,
   * which has its own webview; for the frame, only while it is on screen and
   * nothing is over it, since the input lands at that point of the window.
   */
  const reachable = () => {
    if (!REAL) return false;
    if (onWeb.current) return !!browser.current;
    const el = frame.current;
    const r = el?.getBoundingClientRect();
    if (!el || !r || r.width < 2) return false;
    const top = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
    return top === el;
  };

  /**
   * Mouse and key events at CSS pixels of the page, as points in its webview.
   * Whether the window was active, as a hover needs it to be.
   */
  const real = async (acts: Act[]) => {
    const label = onWeb.current ? browser.current : null;
    const { scale: k } = view.current;
    const r = frame.current?.getBoundingClientRect();
    const ox = label ? 0 : (r?.x ?? 0);
    const oy = label ? 0 : (r?.y ?? 0);
    // Only when the keyboard is elsewhere in the app: focusing the frame's
    // window takes it from a frame inside the page that a click just gave it to.
    if (!label && document.activeElement !== frame.current) frame.current?.contentWindow?.focus();
    return invoke<boolean>("native_input", {
      view: label,
      acts: acts.map((a) => (a.x === undefined ? a : { ...a, x: ox + a.x * k, y: oy + (a.y ?? 0) * k })),
    });
  };

  /** One of Claude's `computer` actions done with real input, or null to leave it to the agent. */
  const act = async (a: Record<string, unknown>): Promise<string | null> => {
    const action = a.action as string;
    const clicks = { left_click: 1, right_click: 1, double_click: 2, triple_click: 3 } as Record<string, number>;
    if (clicks[action]) {
      const { x, y, what, native } = (await agent("locate", a)) as Located;
      // Its menu, file picker or color panel would open on the user's screen,
      // out of Claude's sight and reach, and stay there.
      if (native?.kind === "select")
        return `${what} is a dropdown, whose menu is the system's: it was not opened. Choose an option with form_input on ${native.ref}. Options: ${native.options}.`;
      if (native?.kind === "file")
        return `${what} opens the system's file picker, which you cannot use, so it was not opened. Files cannot be chosen from these tools.`;
      if (native?.kind === "color")
        return `${what} opens the system's color panel, which you cannot use, so it was not opened. Set a color with form_input on ${native.ref}, as #rrggbb.`;
      const button = action === "right_click" ? 2 : 0;
      const acts: Act[] = [{ kind: "move", x, y }];
      for (let n = 1; n <= clicks[action]; n++) acts.push({ kind: "down", x, y, button, clicks: n }, { kind: "up", x, y, button, clicks: n });
      await real(acts);
      void agent("press", { x, y }).catch(() => {});
      await sleep(250);
      const done = `Clicked ${what} at (${Math.round(x)}, ${Math.round(y)}).`;
      if (button === 2 && !(await agent("menu", {}).catch(() => true)))
        return `${done} The page has no menu of its own there; the browser's was kept closed.`;
      return done;
    }
    if (action === "hover") {
      const { x, y, what } = (await agent("locate", a)) as Located;
      // WebKit hit-tests a move only in the active window: with the app in
      // the back, the agent's events at least reach the page's own listeners.
      if (!(await real([{ kind: "move", x, y }])))
        return `${await agent("computer", a)} The app is behind other windows, so this reached the page's mouse listeners but not its :hover styles.`;
      await sleep(150);
      return `Hovering ${what}.`;
    }
    if (action === "left_click_drag") {
      const [x0, y0] = (a.start_coordinate as number[]) ?? [];
      const [x1, y1] = (a.coordinate as number[]) ?? [];
      if ([x0, y0, x1, y1].some((n) => typeof n !== "number")) throw new Error("A drag needs start_coordinate and coordinate.");
      // AppKit's drag session follows the real mouse, never these events: the agent drags instead.
      if (await agent("draggable", { x: x0, y: y0 })) return null;
      await agent("glide", { x: x0, y: y0 });
      await real([{ kind: "move", x: x0, y: y0 }, { kind: "down", x: x0, y: y0 }]);
      void agent("glide", { x: x1, y: y1 }).catch(() => {});
      const steps: Act[] = [];
      for (let i = 1; i <= 12; i++) steps.push({ kind: "drag", x: x0 + ((x1 - x0) * i) / 12, y: y0 + ((y1 - y0) * i) / 12 });
      for (const step of steps) {
        await real([step]);
        await sleep(25);
      }
      await real([{ kind: "up", x: x1, y: y1 }]);
      await sleep(200);
      return `Dragged from (${x0}, ${y0}) to (${x1}, ${y1}).`;
    }
    if (action === "type") {
      const into = (await agent("focused", {})) as string | null;
      if (!into) throw new Error("Nothing has focus to type into: click a field first.");
      await real([{ kind: "text", text: String(a.text ?? "") }]);
      await sleep(150);
      return `Typed into ${into}.`;
    }
    if (action === "key") {
      const text = String(a.text ?? "").trim();
      // Puts back the field the page dropped while hidden; a password field still takes Enter.
      await agent("focused", {}).catch(() => {});
      // One at a time: the page takes keys in turn, but an edit (cmd+v) at once.
      for (const k of text.split(/\s+/)) {
        await real([{ kind: "key", text: k }]);
        await sleep(60);
      }
      await sleep(140);
      return `Pressed ${text}.`;
    }
    return null;
  };

  /** Where a sign-in is kept, changed while the user is signing in: the page reopens in that store. */
  const keepIn = (project: boolean) => {
    const s = signingNow.current;
    if (!s || s.project === project) return;
    signingNow.current = { ...s, project };
    setSigning(signingNow.current);
    go(isWeb(here.current) && covers(s.site, here.current) ? here.current : `https://${s.site}`);
  };

  /** Claude's `sign_in`: the page opened, and the user asked to sign in on it themselves. */
  const signIn = async (raw: string): Promise<string> => {
    const url = toWeb(raw.trim());
    const site = siteOf(url);
    if (!site) throw new Error(`Not an address: ${raw}`);
    if (signedIn.current) throw new Error(`The user is already being asked to sign in to ${signingNow.current?.site}.`);
    signingNow.current = { site, project: !SHARED.test(site) };
    setSigning(signingNow.current);
    const done = new Promise<boolean>((r) => (signedIn.current = r));
    go(url);
    const ok = await done;
    const kept = signingNow.current;
    signedIn.current = null;
    signingNow.current = null;
    setSigning(null);
    if (!ok) return `The user did not sign in to ${site}.`;
    await invoke("signin_keep", { root, site, project: kept.project });
    return `The user signed in to ${site}, kept for ${kept.project ? "this project only" : "all projects"}. The preview is at ${display(here.current)}.`;
  };

  // Claude's calls (src-tauri/src/mcp.rs), by way of the workspace.
  const run = async (call: Call): Promise<unknown> => {
    if (!everLoaded.current && call.op !== "navigate" && call.op !== "sign_in") await nextLoad();
    switch (call.op) {
      case "frame": {
        // Drawn first: the tab may have just come to the front.
        await Promise.race([
          new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r))),
          new Promise((r) => setTimeout(r, 200)),
        ]);
        // Claude's pointer is not part of the page, nor is the size over it:
        // gone at once, not faded out after the picture is taken.
        sizeBadge.current?.style.setProperty("display", "none");
        setBadge(false);
        await agent("veil", {}).catch(() => {});
        const label = onWeb.current ? browser.current : null;
        const r = (label ? sheet.current : frame.current)?.getBoundingClientRect();
        if (!r || (!label && !proxy.current)) throw new Error("The preview has no page open yet.");
        // Whole pixels inside the frame, so no edge of what surrounds it is caught.
        const x = Math.ceil(r.x);
        const y = Math.ceil(r.y);
        return {
          x,
          y,
          width: Math.floor(r.right) - x,
          height: Math.floor(r.bottom) - y,
          viewportWidth: view.current.vw,
          viewportHeight: view.current.vh,
          dpr: window.devicePixelRatio || 1,
          url: display(here.current),
          view: label,
        };
      }
      case "agent": {
        if (signingNow.current)
          throw new Error(`The user is signing in to ${signingNow.current.site} in the preview. Wait for sign_in to return before using the page.`);
        dialogs.current = [];
        // Real input takes the keyboard: where the user was typing elsewhere in the
        // app, a Claude prompt, it is handed back, so their keys never land in the page.
        const theirs = document.hasFocus() ? document.activeElement : null;
        const handBack = theirs instanceof HTMLElement && theirs !== document.body && !stage.current?.contains(theirs);
        let said: string | null;
        try {
          said = call.name === "computer" && reachable() ? await act(call.args) : null;
        } finally {
          if (handBack && theirs.isConnected) {
            if (onWeb.current) await getCurrentWebview().setFocus().catch(() => {});
            theirs.focus({ preventScroll: true });
          }
        }
        if (said === null) said = (await agent(call.name, call.args)) as string;
        // A page from the web is heard by polling: heard once more, so a dialog the action set off is in its answer.
        if (onWeb.current && browser.current)
          (await invoke<Said[] | null>("browser_eval", { label: browser.current, js: DRAIN }).catch(() => null))?.forEach((m) => hear.current(m));
        if (dialogs.current.length) said += ` The page showed a dialog, answered OK: ${dialogs.current.join("; ")}.`;
        // The page knows itself by the proxy's address; Claude knows the dev server's.
        const p = proxy.current;
        return typeof said === "string" && p && server.current
          ? said.replaceAll(`http://localhost:${p.port}`, originOf(server.current))
          : said;
      }
      case "navigate":
        return navigate(call.url);
      case "sign_in":
        return signIn(call.url);
      case "resize": {
        const { width, height, preset } = call.args;
        if (preset === "fill") {
          resize(null);
          return "The viewport fills the tab again.";
        }
        const p = PRESETS.find((x) => x.id === preset);
        const w = clamp(p?.w ?? width ?? view.current.vw);
        const h = clamp(p?.h ?? height ?? view.current.vh);
        resize({ w, h });
        return `The viewport is now ${w}×${h}.`;
      }
      case "console": {
        const { pattern, only_errors, clear, limit } = call.args;
        let test: RegExp | null = null;
        try {
          test = pattern ? new RegExp(pattern, "i") : null;
        } catch {
          throw new Error(`Not a pattern: ${pattern}`);
        }
        const lines = log.current
          .filter((l) => (!only_errors || l.level === "error") && (!test || test.test(l.text)))
          .slice(-(limit ?? 100));
        if (clear) log.current = [];
        return lines.length ? lines.map((l) => `[${l.level}] ${l.text}`).join("\n") : "Nothing logged.";
      }
    }
  };

  return { keepIn, run };
}

app/components/preview/viewport.ts:
export type Size = { w: number; h: number };

/** Space around a sized viewport, where its handles sit. */
export const PAD = 20;
const MIN = 200;
const MAX = 3840;
const SIZE_KEY = "bluprint.preview.size:";

export const clamp = (n: number) => Math.max(MIN, Math.min(MAX, Math.round(n)));

export function storedSize(root: string): Size | null {
  try {
    const v = JSON.parse(localStorage.getItem(SIZE_KEY + root) ?? "null") as Size | null;
    if (v && v.w >= MIN && v.h >= MIN) return v;
  } catch {
    /* storage blocked: fill the tab */
  }
  return null;
}

export function keepSize(root: string, size: Size | null) {
  try {
    if (size) localStorage.setItem(SIZE_KEY + root, JSON.stringify(size));
    else localStorage.removeItem(SIZE_KEY + root);
  } catch {
    /* applies until reload */
  }
}

app/components/preview/webview.ts:
"use client";

import { invoke } from "@tauri-apps/api/core";
import type { Parts } from "@/components/preview/parts";

/**
 * The webview of a page from the web, kept over the viewport: moved with
 * it, and hidden while it is out of sight or anything of the app's (a menu,
 * a dialog) is over it, as it would otherwise cover that. Until the returned call.
 */
export function keepOver({ sheet, stage, view, replace }: Pick<Parts, "sheet" | "stage" | "view" | "replace">, web: string) {
  let last = "";
  let frameId = 0;
  const place = () => {
    const el = sheet.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    // The viewport's own resize edges lie over the page's sides when it
    // fills the tab: they are the preview's, not something over it.
    const own = stage.current ?? el;
    const inside = (x: number, y: number) => {
      const top = document.elementFromPoint(x, y);
      return !!top && own.contains(top);
    };
    const shown =
      r.width > 0 &&
      inside(r.x + r.width / 2, r.y + r.height / 2) &&
      inside(r.x + 4, r.y + 4) &&
      inside(r.right - 4, r.y + 4) &&
      inside(r.x + 4, r.bottom - 4) &&
      inside(r.right - 4, r.bottom - 4);
    const at = { x: r.x, y: r.y, width: r.width, height: r.height, zoom: view.current.scale, shown };
    const key = JSON.stringify(at);
    if (key === last) return;
    last = key;
    void invoke("browser_place", { label: web, ...at }).catch(() => {});
  };
  const loop = () => {
    frameId = requestAnimationFrame(loop);
    place();
  };
  // WebKit sets the zoom back to 1 for each new page: given again.
  replace.current = () => {
    last = "";
    place();
  };
  loop();
  return () => {
    cancelAnimationFrame(frameId);
    void invoke("browser_place", { label: web, x: 0, y: 0, width: 1, height: 1, zoom: 1, shown: false }).catch(() => {});
  };
}

app/components/projects/building.tsx:
"use client";

import { useEffect, useState } from "react";
import { cn } from "@/lib/client/utils";
import { Eyebrow } from "@/components/ui/state";
import { Button } from "@/components/ui/button";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import type { Progress } from "@/lib/server/vault";
import { claudePath } from "@/lib/client/claude";
import { projectAction } from "@/lib/client/api";

/*
 * A bluprint being made, shown as it is made (D69): the files being read, then a
 * box per part the code was divided into, each filling in as its author hands
 * it in and the checker accepts it, then the real picture of how the parts
 * connect drawn over those boxes. A first bluprint takes 15–30 minutes; this is
 * what the reader watches instead of a spinner.
 */

const STAGES = [
  ["summarize", "Reading the code"],
  ["cut", "Dividing it into parts"],
  ["author", "Writing each part"],
  ["overview", "Drawing how they connect"],
] as const;
/** A quick bluprint first, then each part written in full in its place (scripts/generate/pipeline.ts, --fast). */
const FAST_STAGES = [
  ["summarize", "Reading the code"],
  ["author", "Drawing a quick bluprint"],
  ["deepen", "Writing each part in full"],
  ["overview", "Drawing how they connect"],
] as const;
const stagesOf = (progress: Progress) => (progress.fast ? FAST_STAGES : STAGES);

/** Whether the top level is the run itself rather than its picture: until the overview lands. */
export function isBuilding(progress: Progress | undefined, hasOverview: boolean): progress is Progress {
  if (!progress || progress.stage === "done") return false;
  return !hasOverview || progress.stage === "summarize" || progress.stage === "cut";
}

export function Building({ progress, onOpen }: { progress: Progress; onOpen: (path: string[]) => void }) {
  const stage = progress.stage;
  const ended = stage === "failed" || stage === "cancelled";
  return (
    <section data-pick="The bluprint being made" className="flex flex-col gap-8">
      <Stages progress={progress} />
      {ended ? (
        <p className="max-w-[720px] text-[13.5px] leading-relaxed text-clay-ink">
          {stage === "cancelled" ? "This run was cancelled." : "This run stopped before the bluprint was made."}
          {progress.line ? <span className="mt-1 block font-mono text-[11.5px]">{progress.line}</span> : null}
          <span className="mt-1 block text-on-surface-variant">Open Projects to run it again.</span>
        </p>
      ) : null}
      {progress.roots.length ? (
        <Skeleton progress={progress} onOpen={onOpen} />
      ) : stage === "cut" ? (
        <Dividing />
      ) : null}
      {progress.reading && !progress.roots.length ? <Reading reading={progress.reading} /> : null}
    </section>
  );
}

/*
 * How long each stage takes on a typical first bluprint, in minutes, which is all
 * the run's share of the bar and its time-left guess go on until a stage
 * reports how far it has got.
 */
const TYPICAL: Record<string, number> = { summarize: 6, cut: 2, author: 10, overview: 3, verify: 4 };
/** The same for a quick bluprint and its deepening: the quick bluprint is a minute or two, the deepening most of the run. */
const FAST_TYPICAL: Record<string, number> = { summarize: 2, author: 1.5, deepen: 5, overview: 1.5 };
const typicalOf = (progress: Progress) => (progress.fast ? FAST_TYPICAL : TYPICAL);

/** How far through its own stage the run is, 0–1. */
function within(progress: Progress, now: number) {
  const { stage, reading, roots } = progress;
  if (stage === "summarize" && reading?.files.length) return reading.read.length / reading.files.length;
  if ((stage === "author" || stage === "deepen") && roots.length) {
    const settled = roots.filter((r) => r.status === "done" || r.status === "failed").length;
    const drafting = roots.filter((r) => r.status === "drafting").length;
    return (settled + drafting / 3) / roots.length;
  }
  // A stage that says nothing until it ends: closer to done the longer it
  // runs, never quite there.
  const since = progress.stageAt ? (now - Date.parse(progress.stageAt)) / 60000 : 0;
  return 0.95 * (1 - Math.exp(-since / (typicalOf(progress)[stage] ?? 3)));
}

/** A clock that moves on its own between the run's reports. */
function useNow(on: boolean) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!on) return;
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, [on]);
  return now;
}

const clock = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;

/** Where the run is, of the five things it does. */
export function Stages({ progress }: { progress: Progress }) {
  const stages = stagesOf(progress);
  const typical = typicalOf(progress);
  const total = stages.reduce((a, [k]) => a + typical[k], 0);
  const at = stages.findIndex(([k]) => k === progress.stage);
  const done = progress.stage === "done";
  const live = at >= 0;
  const tick = useNow(live);
  const part = live ? Math.min(1, within(progress, tick)) : 0;
  const share = (i: number) => (done || (at >= 0 && i < at) ? 1 : i === at ? part : 0);
  const fraction = stages.reduce((a, [k], i) => a + share(i) * typical[k], 0) / total;
  const started = progress.startedAt ? Date.parse(progress.startedAt) : NaN;
  const elapsed = Number.isNaN(started) ? undefined : Math.max(0, (tick - started) / 1000);
  // Too early, the pace says nothing; after that, the time so far scaled to
  // what is left, so it does not twitch every second.
  const left = elapsed !== undefined && elapsed > 30 && fraction > 0.03 ? (elapsed * (1 - fraction)) / fraction : undefined;
  const leftLabel =
    left === undefined ? "estimating time left…" : left < 60 ? "under a minute left" : `about ${Math.ceil(left / 60)} min left`;
  return (
    <div className="flex flex-col gap-4">
      {live ? (
        <div className="max-w-[1100px]">
          <div className="flex items-baseline gap-3 font-mono text-[11.5px]">
            <span className="text-[13px] font-semibold text-accent tabular-nums">{Math.floor(fraction * 100)}%</span>
            {elapsed !== undefined ? <span className="text-faint tabular-nums">{clock(elapsed)} elapsed</span> : null}
            <span className="ml-auto text-on-surface-variant">{leftLabel}</span>
          </div>
          <div
            role="progressbar"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.floor(fraction * 100)}
            aria-valuetext={leftLabel}
            className="mt-2 flex gap-[3px]"
          >
            {stages.map(([k, label], i) => (
              <div
                key={k}
                title={label}
                style={{ flexGrow: typical[k] }}
                className={cn("relative h-1.5 basis-0 overflow-hidden rounded-full bg-border-gray", i === at && "shimmer")}
              >
                <div
                  className={cn("h-full rounded-full transition-[width] duration-700 ease-out", i < at ? "bg-accent-line" : "bg-accent")}
                  style={{ width: `${share(i) * 100}%` }}
                />
              </div>
            ))}
          </div>
        </div>
      ) : null}
      <ol className="flex flex-wrap items-center gap-x-2 gap-y-2 text-[12.5px]">
        {stages.map(([k, label], i) => {
          const past = done || (at >= 0 && i < at);
          const now = i === at;
          return (
            <li key={k} className="flex items-center gap-2">
              {i ? <span aria-hidden className="h-px w-5 bg-border-strong" /> : null}
              <span
                className={cn(
                  "flex items-center gap-1.5 border px-2.5 py-1",
                  now ? "border-accent-line bg-accent-surface text-accent" : past ? "border-border-gray text-on-surface-variant" : "border-dashed border-border-gray text-faint",
                )}
                aria-current={now ? "step" : undefined}
              >
                <span aria-hidden className={cn("size-1.5 rounded-full", now ? "animate-pulse bg-accent" : past ? "bg-accent-line" : "bg-border-strong")} />
                {past ? `${label} ✓` : label}
              </span>
            </li>
          );
        })}
      </ol>
    </div>
  );
}

/* ── reading ─────────────────────────────────────────────────── */

/**
 * The code being read: every file to read as a cell under its folder, lit as
 * it is read, beside what the last few turned out to be for.
 */
function Reading({ reading }: { reading: NonNullable<Progress["reading"]> }) {
  const read = new Set(reading.read);
  const recent = new Set(reading.recent.map((r) => r.path));
  const dirs = new Map<string, string[]>();
  for (const f of reading.files) {
    const dir = f.includes("/") ? f.slice(0, f.lastIndexOf("/")) : ".";
    dirs.set(dir, [...(dirs.get(dir) ?? []), f]);
  }
  const of = reading.files.length;
  return (
    <div>
      <div className="flex items-baseline gap-3">
        <Eyebrow>Reading the code</Eyebrow>
        <span className="font-mono text-[11.5px] text-faint">
          {reading.read.length} of {of} files
        </span>
      </div>
      <div className="mt-2 h-1 max-w-[720px] overflow-hidden rounded-full bg-border-gray">
        <div className="h-full bg-accent transition-[width] duration-300" style={{ width: `${of ? (100 * reading.read.length) / of : 0}%` }} />
      </div>
      <div className="mt-6 grid gap-8 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
        <div className="max-h-[440px] overflow-y-auto pr-2">
          {[...dirs].sort(([a], [b]) => a.localeCompare(b)).map(([dir, files]) => (
            <div key={dir} className="flex items-start gap-3 py-[3px]">
              <span className="w-[46%] shrink-0 truncate text-right font-mono text-[11px] text-faint" title={dir}>
                {dir}/
              </span>
              <span className="flex flex-wrap gap-[3px] pt-[3px]">
                {files.map((f) => (
                  <span
                    key={f}
                    title={f}
                    className={cn(
                      "size-[9px] transition-colors duration-500",
                      recent.has(f) ? "bg-accent" : read.has(f) ? "bg-accent-line" : "bg-border-gray",
                    )}
                  />
                ))}
              </span>
            </div>
          ))}
        </div>
        <ol className="flex flex-col gap-3">
          {reading.recent.map((r) => (
            <li key={r.path} className="arrive">
              <p className="truncate font-mono text-[11px] text-faint">{r.path}</p>
              <p className="mt-0.5 text-[13.5px] leading-snug text-on-surface">{r.purpose}</p>
            </li>
          ))}
        </ol>
      </div>
    </div>
  );
}

/** Before the parts have names: the space they will take, waiting. */
function Dividing() {
  return (
    <div>
      <Eyebrow>Dividing it into parts</Eyebrow>
      <p className="mt-2 max-w-[720px] text-[13.5px] leading-relaxed text-on-surface-variant">
        Every file is read. The code is being divided by what someone does with it — each part one journey or feature,
        not one folder.
      </p>
      <div className="mt-5 grid max-w-[1100px] grid-cols-[repeat(auto-fill,minmax(240px,1fr))] gap-4">
        {Array.from({ length: 6 }, (_, i) => (
          <div key={i} className="shimmer h-[74px] border border-dashed border-border-strong" />
        ))}
      </div>
    </div>
  );
}

/* ── the parts ───────────────────────────────────────────────── */

/**
 * One box per part the code was divided into, where the picture of how they
 * connect will be drawn. A part opens as soon as there is something to read:
 * its draft while it is checked, then the part itself.
 */
function Skeleton({ progress, onOpen }: { progress: Progress; onOpen: (path: string[]) => void }) {
  const { nodeAt } = useBluprint();
  const ready = progress.roots.filter((r) => r.status === "done").length;
  const of = progress.roots.length;
  return (
    <div>
      <div className="flex items-baseline gap-3">
        <Eyebrow>{progress.stage === "author" ? "Writing each part" : "The parts"}</Eyebrow>
        <span className="font-mono text-[11.5px] text-faint">
          {ready} of {of} ready
        </span>
      </div>
      <p className="mt-2 max-w-[720px] text-[13.5px] leading-relaxed text-on-surface-variant">
        {progress.stage === "author"
          ? "Each part is written by its own agent and checked against the code before it is accepted. Open a ready one now; the rest arrive as they pass."
          : progress.stage === "overview"
            ? "Every part is in. Now the picture of how they connect is being drawn, each arrow cited to the line where one part calls another."
            : "The parts so far."}
      </p>
      <div className="mt-5 grid max-w-[1100px] grid-cols-[repeat(auto-fill,minmax(240px,1fr))] gap-4">
        {progress.roots.map((r) => {
          const node = nodeAt([r.id]);
          const open = node ? () => onOpen([r.id]) : undefined;
          const working = r.status === "drafting" || r.status === "queued";
          return (
            <button
              key={r.id}
              type="button"
              data-path={JSON.stringify([r.id])}
              onClick={open}
              disabled={!open}
              className={cn(
                "group flex min-h-[86px] flex-col border px-4 py-3 text-left transition-[background-color,border-color,opacity] duration-500",
                r.status === "done" && "border-border-strong bg-surface-container-low hover:border-accent",
                r.status === "drafting" && "shimmer border-border-strong",
                r.status === "drafting" && node?.draft && "border-amber-line",
                r.status === "queued" && "border-dashed border-border-gray opacity-70",
                r.status === "failed" && "border-clay-line bg-clay-surface/50",
                open ? "cursor-pointer" : "cursor-default",
              )}
            >
              <span className="text-[14.5px] font-semibold tracking-[-0.01em] text-ink">{r.title}</span>
              {r.sub ? <span className="mt-0.5 text-[12.5px] leading-snug text-on-surface-variant">{r.sub}</span> : null}
              <span
                className={cn(
                  "mt-auto pt-2 font-mono text-[11px]",
                  r.status === "done" ? "text-accent" : r.status === "failed" ? "text-clay-ink" : "text-faint",
                )}
              >
                {r.status === "done"
                  ? "✓ ready — open it"
                  : r.status === "failed"
                    ? `✗ ${r.detail ?? "not accepted"}`
                    : node?.draft
                      ? `draft, being checked${r.detail?.startsWith("revising — ") ? ` · ${r.detail.slice(11)}` : ""} — open it`
                      : working && r.status === "drafting"
                        ? "writing…"
                        : "waiting"}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

/* ── no bluprint yet ──────────────────────────────────────────────── */

/**
 * A project opened without a bluprint: the shape of what its page will hold, drawn
 * empty, and the button that makes it. Starting the run turns the project's
 * bluprint back on (lib/server/vault.ts, generate); the bluprint's poll then brings the run in,
 * which replaces this.
 */
export function NoBluprint({ id }: { id: string }) {
  const [starting, setStarting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const start = async () => {
    setStarting(true);
    setError(null);
    try {
      await projectAction({ action: "regenerate", id, claude: await claudePath() });
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setStarting(false);
    }
  };
  return (
    <section data-pick="No bluprint yet" className="flex flex-col gap-8">
      <div className="flex max-w-[720px] flex-col items-start gap-3">
        <Eyebrow>No bluprint yet</Eyebrow>
        <p className="text-[13.5px] leading-relaxed text-on-surface-variant">
          This project is open without a bluprint. Generate one and the code is read, divided into the parts someone does
          something with, and drawn here as the picture of how they connect.
        </p>
        <Button variant="primary" onClick={() => void start()} disabled={starting}>
          {starting ? "Starting…" : "Generate bluprint"}
        </Button>
        {error ? <p className="text-[12.5px] text-clay-ink">{error}</p> : null}
      </div>
      <Wireframe />
    </section>
  );
}

const WIRE_BOXES = [
  { x: 20, y: 30 },
  { x: 250, y: 30 },
  { x: 480, y: 30 },
  { x: 710, y: 30 },
  { x: 250, y: 190 },
  { x: 480, y: 190 },
];
const WIRE_ARROWS = ["M190 70 H244", "M420 70 H474", "M650 70 H704", "M335 110 V184", "M565 110 V184", "M420 230 H474"];

/** The page a bluprint makes, as an empty wireframe: a diagram of parts, then the parts. */
function Wireframe() {
  return (
    <div aria-hidden className="flex max-w-[1100px] flex-col gap-8 opacity-80">
      <svg viewBox="0 0 900 270" className="block h-auto w-full text-border-strong">
        <defs>
          <marker id="wire-head" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
            <path d="M0 0 L8 4 L0 8 z" fill="currentColor" />
          </marker>
        </defs>
        {WIRE_ARROWS.map((d) => (
          <path key={d} d={d} fill="none" stroke="currentColor" strokeWidth={1.5} strokeDasharray="5 4" markerEnd="url(#wire-head)" />
        ))}
        {WIRE_BOXES.map(({ x, y }) => (
          <g key={`${x}-${y}`}>
            <rect x={x} y={y} width={170} height={80} rx={3} fill="none" stroke="currentColor" strokeWidth={1.5} strokeDasharray="6 4" />
            <rect x={x + 16} y={y + 20} width={96} height={9} rx={2} fill="currentColor" opacity={0.6} />
            <rect x={x + 16} y={y + 40} width={128} height={6} rx={2} fill="currentColor" opacity={0.35} />
            <rect x={x + 16} y={y + 54} width={80} height={6} rx={2} fill="currentColor" opacity={0.35} />
          </g>
        ))}
      </svg>
      <div className="grid grid-cols-[repeat(auto-fill,minmax(240px,1fr))] gap-4">
        {Array.from({ length: 6 }, (_, i) => (
          <div key={i} className="flex min-h-[86px] flex-col gap-2 border border-dashed border-border-strong px-4 py-3">
            <span className="h-2.5 w-2/5 bg-border-gray" />
            <span className="h-1.5 w-4/5 bg-border-gray" />
            <span className="h-1.5 w-3/5 bg-border-gray" />
          </div>
        ))}
      </div>
    </div>
  );
}

/** Over a part that is still a draft: what the reader is looking at, before they take it as the bluprint. */
export function DraftNote({ detail }: { detail?: string }) {
  return (
    <div className="max-w-[820px] border border-amber-line bg-amber-surface px-4 py-3 text-[13.5px] leading-relaxed text-amber-ink">
      <span className="font-semibold">Draft, being checked.</span> The checker found problems with this part
      {detail ? ` (${detail.replace(/^revising — /, "")})` : ""} and its author is fixing them, so what is here may
      still change. It is shown now so there is something to read while you wait.
    </div>
  );
}

/* ── the picture arriving ────────────────────────────────────── */

/**
 * When the overview lands over the boxes the reader was watching, it is drawn
 * rather than swapped in: the boxes settle, then each arrow is traced from one
 * part to the next, its label after it. Once, on arrival; a bluprint opened later
 * just shows its picture.
 */
export function useDrawIn(root: React.RefObject<HTMLElement | null>, on: boolean) {
  useEffect(() => {
    const svg = on ? root.current?.querySelector<SVGSVGElement>("svg.dg-nav") : null;
    if (!svg || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const boxes = [...svg.children].filter((g) => g.querySelector(":scope > rect"));
    boxes.forEach((b, i) =>
      b.animate([{ opacity: 0.2 }, { opacity: 1 }], { duration: 500, delay: i * 70, easing: "ease-out", fill: "backwards" }),
    );
    const start = boxes.length * 70 + 250;
    const arrows = [...svg.querySelectorAll<SVGPathElement>(":scope > g > path[marker-end]")];
    const running = arrows.map((p, i) => {
      const length = p.getTotalLength();
      const head = p.getAttribute("marker-end")!;
      const dash = `${length} ${length}`;
      // The head waits for its line: drawn at once, it would float ahead of it.
      p.removeAttribute("marker-end");
      const a = p.animate([{ strokeDasharray: dash, strokeDashoffset: length }, { strokeDasharray: dash, strokeDashoffset: 0 }], {
        duration: 650,
        delay: start + i * 160,
        easing: "ease-in-out",
        fill: "backwards",
      });
      a.onfinish = a.oncancel = () => p.setAttribute("marker-end", head);
      p.parentElement?.querySelector("text")?.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 300, delay: start + i * 160 + 500, fill: "backwards" });
      return a;
    });
    return () => running.forEach((a) => a.cancel());
  }, [root, on]);
}

app/components/projects/projects.tsx:
"use client";

import { isTauri } from "@tauri-apps/api/core";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";
import { DIALOG, INPUT, Overlay, PRIMARY, QUIET } from "@/components/ui/dialog";
import { useMaybeBluprint } from "@/components/bluprint/bluprint-context";
import { Menu, type MenuItem } from "@/components/ui/menu";
import { cloneUrl, repoName } from "@/lib/client/clone";
import type { Explain, Progress, Project } from "@/lib/server/vault";
import { cn } from "@/lib/client/utils";
import { projectAction } from "@/lib/client/api";
import { claudePath } from "@/lib/client/claude";

/**
 * The project list: the reader's own projects, imported from this machine and
 * kept in the app's vault (lib/server/vault.ts). Starting one works as VS Code's Open
 * Folder does: the system's folder picker first, then one screen to confirm
 * before the bluprint is made through the reader's Claude Code. New Project makes
 * an empty folder instead, or clones one from GitHub when given a repository.
 * The list follows the run, and the bluprint opens from here or the picker once it
 * is made.
 */

const OPEN = "bluprint:projects";
type Mode = "open" | "new";
interface Asked {
  mode?: Mode;
  root?: string;
}
const show = (detail: Asked) => window.dispatchEvent(new CustomEvent<Asked>(OPEN, { detail }));
/** Opens the list; with a folder, ready to import it. */
export const openProjects = (root?: string) => show(root ? { mode: "open", root } : {});

/** The system's folder picker; undefined outside the desktop app, or when the reader cancels. */
async function pickFolder(title: string): Promise<string | undefined> {
  if (!isTauri()) return undefined;
  const { open } = await import("@tauri-apps/plugin-dialog");
  const dir = await open({ directory: true, title });
  return typeof dir === "string" ? dir : undefined;
}

/**
 * Open Folder…: the picker straight away, then the confirm screen. Outside the
 * desktop app there is no picker, so the screen asks for the path instead.
 */
export async function openFolder() {
  if (!isTauri()) return show({ mode: "open" });
  const root = await pickFolder("Open a folder to bluprint");
  if (root) show({ mode: "open", root });
}

export const newProject = () => show({ mode: "new" });

type Listed = Project & { hasBluprint: boolean; stale: boolean; progress?: Progress };
interface List {
  vault: string;
  projects: Listed[];
}

export function ProjectsDialog() {
  const router = useRouter();
  const current = useMaybeBluprint()?.name;
  const [open, setOpen] = useState(false);
  const [list, setList] = useState<List | null>(null);
  const [root, setRoot] = useState("");
  const [label, setLabel] = useState("");
  const [url, setUrl] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // Confirming an Open Folder or New Project; the list alone when null.
  const [mode, setMode] = useState<Mode | null>(null);
  const close = useCallback(() => setOpen(false), []);

  // Which bluprints were ready last time, so a run finishing refreshes the picker.
  const ready = useRef<Set<string>>(new Set());
  const refresh = useCallback(async () => {
    const next: List = await fetch("/api/projects").then((r) => r.json());
    const now = new Set(next.projects.filter((p) => p.bluprint.status === "ready").map((p) => p.id));
    if ([...now].some((id) => !ready.current.has(id))) router.refresh();
    ready.current = now;
    setList(next);
  }, [router]);

  useEffect(() => {
    const show = (e: Event) => {
      const asked = (e as CustomEvent<Asked>).detail;
      setRoot(asked.root ?? "");
      setLabel(asked.mode === "open" && asked.root ? folderName(asked.root) : "");
      setUrl("");
      setMode(asked.mode ?? null);
      setOpen(true);
      setError(null);
      void refresh();
    };
    window.addEventListener(OPEN, show);
    return () => window.removeEventListener(OPEN, show);
  }, [refresh]);

  // Follow a run while the list is open.
  const running = list?.projects.some((p) => p.bluprint.status === "generating");
  useEffect(() => {
    if (!open || !running) return;
    const t = setInterval(() => void refresh(), 3000);
    return () => clearInterval(t);
  }, [open, running, refresh]);

  if (!open) return null;

  // The project the action returned, or null when it failed.
  const act = async (body: Record<string, unknown>): Promise<Partial<Project> | null> => {
    setBusy(true);
    setError(null);
    try {
      const out = await projectAction(body);
      await refresh();
      return out ?? {};
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      return null;
    } finally {
      setBusy(false);
    }
  };

  // The name starts as the folder's and follows it, until the reader names it something else.
  const changeRoot = (next: string) => {
    if (mode === "open") setLabel((l) => (!l.trim() || l === folderName(root) ? folderName(next) : l));
    setRoot(next);
  };

  // A clone's name follows the repository's the same way.
  const changeUrl = (next: string) => {
    setLabel((l) => (!l.trim() || l === repoName(url) ? repoName(next) : l));
    setUrl(next);
  };

  const browse = async () => {
    const dir = await pickFolder(mode === "new" ? "Choose where the new folder goes" : "Open a folder to bluprint");
    if (dir) changeRoot(dir);
  };

  const start = async (explain: Explain | undefined, paused: boolean) => {
    try {
      const clone = mode === "new" && Boolean(url.trim());
      const claude = (mode === "new" && !clone) || paused ? undefined : await claudePath();
      const body =
        mode === "open"
          ? { action: "import", root: root.trim(), name: label.trim(), claude, explain, paused }
          : clone
            ? { action: "clone", url: url.trim(), root: root.trim(), name: label.trim(), claude, explain, paused }
            : { action: "create", root: root.trim(), name: label.trim(), paused };
      const made = await act(body);
      if (made) {
        setRoot("");
        setLabel("");
        setUrl("");
        setMode(null);
        // A bluprint being made opens to watch it build (D69); one without a bluprint opens for its tabs.
        if (made.id) openBluprint(made.id);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  };

  // `full` makes the whole bluprint again; without it a finished bluprint at the same
  // depth is only brought up to its code (lib/server/vault.ts, generate).
  const regenerate = async (id: string, explain?: Explain, full?: boolean) => {
    try {
      if (await act({ action: "regenerate", id, claude: await claudePath(), explain, ...(full ? { full: true } : {}) })) openBluprint(id);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  };

  // Deleting the open project goes to the blank page (components/chrome/welcome.tsx)
  // rather than quietly opening some other project.
  const remove = async (id: string) => {
    if (!(await act({ action: "remove", id }))) return;
    if (id === current) router.push("/?none");
    else router.refresh();
  };

  // `at` is the level to open at, as chrome.tsx's goTo spells it: a finished
  // root is explorable from the list while the rest are still being made.
  const openBluprint = (id: string, at?: string) => {
    router.push(`/?bluprint=${encodeURIComponent(id)}${at ? `&at=${encodeURIComponent(at)}` : ""}`);
    close();
  };

  const home = list ? homeOf(list.vault) : undefined;

  return (
    <Overlay onClose={close}>
      <div role="dialog" aria-label="Projects" className={cn(DIALOG, "max-w-[600px]")}>
        {mode ? (
          <StartProject
            mode={mode}
            root={root}
            setRoot={changeRoot}
            label={label}
            setLabel={setLabel}
            url={url}
            setUrl={changeUrl}
            busy={busy}
            error={error}
            onBrowse={isTauri() ? () => void browse() : undefined}
            onStart={(explain, paused) => void start(explain, paused)}
            onCancel={() => {
              setMode(null);
              setRoot("");
              setLabel("");
              setUrl("");
              setError(null);
            }}
          />
        ) : (
          <>
            <header className="flex items-center gap-1.5 border-b border-border-gray px-5 py-3">
              <h2 className="flex-1 text-[15px] font-semibold tracking-[-0.01em] text-ink">Projects</h2>
              <button type="button" onClick={newProject} className={QUIET}>
                New Project…
              </button>
              <button type="button" onClick={() => void openFolder()} className={PRIMARY}>
                Open Folder…
              </button>
            </header>
            <div className="min-h-0 overflow-y-auto px-2 py-2">
              {list?.projects.length ? (
                <ul className="flex flex-col">
                  {list.projects.map((p) => (
                    <ProjectRow
                      key={p.id}
                      p={p}
                      home={home}
                      current={p.id === current}
                      busy={busy}
                      onOpen={(at) => openBluprint(p.id, at)}
                      onRegenerate={(explain, full) => void regenerate(p.id, explain, full)}
                      onCancel={() => void act({ action: "cancel", id: p.id })}
                      onPause={(paused) => void act({ action: "pause", id: p.id, paused })}
                      onRemove={() => void remove(p.id)}
                    />
                  ))}
                </ul>
              ) : list ? (
                <div className="px-3 py-10 text-center">
                  <p className="text-[13.5px] font-medium text-ink">No projects yet</p>
                  <p className="mt-1 text-[12.5px] text-muted-slate">Open a folder of code to make its bluprint, or start a new one, empty or cloned from GitHub.</p>
                </div>
              ) : (
                <p className="px-3 py-10 text-center text-[12.5px] text-faint">Loading…</p>
              )}
            </div>
            {error ? <p className="border-t border-border-gray px-5 py-2.5 text-[12.5px] text-clay-ink">{error}</p> : null}
            <footer className="truncate border-t border-border-gray bg-surface px-5 py-2 text-[11.5px] text-faint" title={list?.vault}>
              {list ? `Kept on this machine, in ${tilde(list.vault, home)}` : " "}
            </footer>
          </>
        )}
      </div>
    </Overlay>
  );
}

/** The home folder, read off the vault's path: the browser has no other way to know it. */
const homeOf = (vault: string) => vault.match(/^(\/Users\/[^/]+|\/home\/[^/]+|[A-Za-z]:\\Users\\[^\\]+)/)?.[1];
const tilde = (path: string, home?: string) => (home && path.startsWith(home) ? `~${path.slice(home.length)}` : path);

/**
 * How much the bluprint explains (D70), from how well the reader says they
 * understand the repo: each stop of the slider is one level, the less they
 * know the more it says.
 */
const UNDERSTAND: { label: string; explain: Explain }[] = [
  { label: "New to it", explain: "full" },
  { label: "Read some", explain: "detailed" },
  { label: "Used it", explain: "brief" },
  { label: "Worked in it", explain: "minimal" },
  { label: "Wrote it", explain: "none" },
];

const EXPLAINS: Record<Explain, { label: string; note: string }> = {
  none: { label: "No explanations", note: "The bluprint alone: parts, pictures and the code behind each step." },
  minimal: { label: "Minimal explanations", note: "One line per level on what this project calls it, a few of its own words defined, a short walkthrough." },
  brief: { label: "Brief explanations", note: "A sentence or two per level on what it is for, a short glossary and walkthrough." },
  detailed: { label: "Detailed explanations", note: "A paragraph or two per level in plain words, the odd picture, a glossary and a walkthrough." },
  full: { label: "Full explanations", note: "Every level said again in plain words, with pictures, a glossary and a walkthrough." },
};

/**
 * How well the reader understands the repo, as a slider of UNDERSTAND's
 * stops. Drawn rather than a native range, which the webviews style each
 * their own way; it drags, clicks to a stop, and takes the arrow keys.
 */
function Understanding({ value, onChange }: { value: number; onChange: (v: number) => void }) {
  const track = useRef<HTMLDivElement>(null);
  const last = UNDERSTAND.length - 1;
  const at = (x: number) => {
    const r = track.current!.getBoundingClientRect();
    return Math.round(Math.min(1, Math.max(0, (x - r.left) / r.width)) * last);
  };
  const left = (i: number) => `${(i / last) * 100}%`;
  const explain = UNDERSTAND[value].explain;

  return (
    <div className="flex flex-col gap-3">
      <div>
        <span id="understand-q" className="text-[13px] font-semibold text-ink">
          How well do you understand this repo?
        </span>
        <span className="mt-0.5 block text-[12px] text-muted-slate">So the bluprint says as much as you need, and no more.</span>
      </div>
      <div className="px-8">
        <div
          role="slider"
          tabIndex={0}
          aria-labelledby="understand-q"
          aria-valuemin={0}
          aria-valuemax={last}
          aria-valuenow={value}
          aria-valuetext={`${UNDERSTAND[value].label}: ${EXPLAINS[explain].label}`}
          onPointerDown={(e) => {
            e.currentTarget.setPointerCapture(e.pointerId);
            e.currentTarget.focus();
            onChange(at(e.clientX));
          }}
          onPointerMove={(e) => {
            if (e.currentTarget.hasPointerCapture(e.pointerId)) onChange(at(e.clientX));
          }}
          onKeyDown={(e) => {
            const step = { ArrowLeft: -1, ArrowDown: -1, ArrowRight: 1, ArrowUp: 1 }[e.key];
            const next = e.key === "Home" ? 0 : e.key === "End" ? last : step === undefined ? null : Math.min(last, Math.max(0, value + step));
            if (next === null) return;
            e.preventDefault();
            onChange(next);
          }}
          className="group relative h-7 cursor-pointer touch-none select-none outline-none"
        >
          <div ref={track} className="absolute inset-x-0 top-1/2 h-1 -translate-y-1/2 bg-border-gray">
            <div className="h-full bg-accent transition-[width] duration-200 ease-out" style={{ width: left(value) }} />
          </div>
          {UNDERSTAND.map((u, i) => (
            <span
              key={u.label}
              className={cn(
                "absolute top-1/2 size-2 -translate-x-1/2 -translate-y-1/2 rounded-full transition-colors duration-200",
                i <= value ? "bg-accent" : "bg-border-strong",
              )}
              style={{ left: left(i) }}
            />
          ))}
          <span
            className="absolute top-1/2 size-[18px] -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-accent bg-card shadow-panel transition-[left,box-shadow,transform] duration-200 ease-out group-focus-visible:shadow-[0_0_0_4px_var(--color-accent-surface)] group-active:scale-110"
            style={{ left: left(value) }}
          />
        </div>
        <div className="relative h-4 select-none">
          {UNDERSTAND.map((u, i) => (
            <span
              key={u.label}
              onClick={() => onChange(i)}
              className={cn(
                "absolute top-0 -translate-x-1/2 cursor-pointer whitespace-nowrap text-[11.5px] transition-colors",
                i === value ? "font-semibold text-ink" : "text-faint hover:text-muted-slate",
              )}
              style={{ left: left(i) }}
            >
              {u.label}
            </span>
          ))}
        </div>
      </div>
      <div className="border border-border-gray bg-card px-3 py-2.5">
        <span className="block font-mono text-[10.5px] uppercase tracking-[0.09em] text-accent">{EXPLAINS[explain].label}</span>
        <span className="mt-1 block text-[12px] text-muted-slate">{EXPLAINS[explain].note}</span>
      </div>
    </div>
  );
}

const folderName = (root: string) => root.trim().replace(/[\\/]+$/, "").split(/[\\/]/).pop() ?? "";
const joinPath = (parent: string, name: string) => `${parent.trim().replace(/[\\/]+$/, "")}/${name}`;

/**
 * Confirming a project, on one screen: for a new one the repository to clone,
 * if any, and where it goes; for an existing one the folder (already picked
 * when the picker was there to pick it); its name; and for code to bluprint how
 * much the bluprint explains and what making it costs. Folders and repositories
 * are checked by the server, so a bad one comes back here to fix.
 */
function StartProject({
  mode,
  root,
  setRoot,
  label,
  setLabel,
  url,
  setUrl,
  busy,
  error,
  onBrowse,
  onStart,
  onCancel,
}: {
  mode: Mode;
  root: string;
  setRoot: (v: string) => void;
  label: string;
  setLabel: (v: string) => void;
  url: string;
  setUrl: (v: string) => void;
  busy: boolean;
  error: string | null;
  onBrowse?: () => void;
  onStart: (explain: Explain | undefined, paused: boolean) => void;
  onCancel: () => void;
}) {
  const fresh = mode === "new";
  const clone = fresh && Boolean(url.trim());
  const known = Boolean(cloneUrl(url));
  // A new empty folder has nothing to make a bluprint of yet: it gets one from Projects once it has code.
  const canBluprint = !fresh || clone;
  const [making, setMaking] = useState(true);
  const [understand, setUnderstand] = useState(2);
  const explain = UNDERSTAND[understand].explain;
  const name = label.trim() || (clone ? repoName(url) : fresh ? "" : folderName(root));
  const ready = Boolean(root.trim()) && (clone ? known && Boolean(name) : !fresh || Boolean(label.trim()));

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (ready) onStart(canBluprint && making ? explain : undefined, canBluprint && !making);
      }}
      className="flex min-h-0 flex-col"
    >
      <header className="flex items-center gap-1 border-b border-border-gray px-3 py-3">
        <button
          type="button"
          onClick={onCancel}
          aria-label="Back to projects"
          className="flex size-7 cursor-pointer items-center justify-center text-[15px] text-muted-slate hover:bg-surface-container hover:text-ink focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent"
        >
          ←
        </button>
        <h2 className="text-[15px] font-semibold tracking-[-0.01em] text-ink">{fresh ? "New Project" : "Open Folder"}</h2>
      </header>

      <div className="flex min-h-0 flex-col gap-5 overflow-y-auto px-5 py-5">
        {fresh ? (
          <label className="block">
            <span className={LABEL}>
              Clone from GitHub <span className="font-normal text-faint">optional</span>
            </span>
            <input
              autoFocus
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              placeholder="https://github.com/owner/repo"
              spellCheck={false}
              aria-invalid={clone && !known}
              className={INPUT}
            />
            <span className={cn("mt-1.5 block text-[11.5px]", clone && !known ? "text-clay-ink" : "text-faint")}>
              {clone && !known ? "Paste its GitHub link, owner/repo, or a git address." : "Leave it empty to start an empty folder."}
            </span>
          </label>
        ) : null}

        <label className="block">
          <span className={LABEL}>{fresh ? "Location" : "Folder"}</span>
          <div className="flex gap-2">
            <input
              autoFocus={!root && !fresh}
              value={root}
              onChange={(e) => setRoot(e.target.value)}
              placeholder={fresh ? "~/code" : "~/code/my-app"}
              spellCheck={false}
              className={INPUT}
            />
            {onBrowse ? (
              <button type="button" onClick={onBrowse} className={cn(QUIET, "h-auto self-stretch border border-border-strong")}>
                {root ? "Change…" : "Browse…"}
              </button>
            ) : null}
          </div>
        </label>

        <label className="block">
          <span className={LABEL}>
            Name
          </span>
          <input
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            placeholder={(clone ? repoName(url) : !fresh && folderName(root)) || "my-app"}
            spellCheck={false}
            className={INPUT}
          />
          {fresh && root.trim() && name ? (
            <span className="mt-1.5 block truncate font-mono text-[11.5px] text-faint">
              {clone ? "Clones into" : "Creates"} {joinPath(root, name)}
            </span>
          ) : null}
        </label>

        {canBluprint ? (
          <div className="flex items-start gap-4 border-t border-border-gray pt-5">
            <div className="min-w-0 flex-1">
              <span className="block text-[13px] font-semibold text-ink">Make a bluprint</span>
              <span className="mt-0.5 block text-[12px] leading-snug text-muted-slate">
                {making
                  ? "Your Claude Code reads it now. About 20 minutes for a mid-sized repo, on your plan's usage."
                  : "It opens with just your tabs. Nothing is read or spent until you make a bluprint."}
              </span>
            </div>
            <Switch on={making} onChange={setMaking} label="Make a bluprint" />
          </div>
        ) : null}

        {canBluprint && making ? <Understanding value={understand} onChange={setUnderstand} /> : null}
      </div>

      <footer className="flex items-center justify-end gap-2 border-t border-border-gray bg-surface px-5 py-3">
        {error ? <p className="mr-auto text-[12.5px] text-clay-ink">{error}</p> : null}
        <button type="button" onClick={onCancel} className={QUIET}>
          Cancel
        </button>
        <button type="submit" disabled={busy || !ready} className={PRIMARY}>
          {clone ? (busy ? "Cloning…" : making ? "Clone and make bluprint" : "Clone") : fresh ? "Create" : making ? "Make bluprint" : "Open"}
        </button>
      </footer>
    </form>
  );
}

const LABEL = "mb-1.5 block text-[12.5px] font-semibold text-ink";

function Switch({ on, onChange, label }: { on: boolean; onChange: (on: boolean) => void; label: string }) {
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      aria-label={label}
      onClick={() => onChange(!on)}
      className={cn(
        "relative mt-0.5 h-5 w-9 shrink-0 cursor-pointer transition-colors duration-150 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent",
        on ? "bg-accent" : "bg-border-strong",
      )}
    >
      <span
        className={cn(
          "absolute left-0.5 top-0.5 size-4 bg-card transition-transform duration-150",
          on && "translate-x-4",
        )}
      />
    </button>
  );
}

const minutes = (from: string) => Math.max(1, Math.round((Date.now() - Date.parse(from)) / 60000));

/** What the run is doing before any root exists; once they do, the list below says it. */
function stageLine(g?: Progress) {
  if (!g) return "";
  if (g.roots.length) return "";
  if (g.stage === "summarize") return "reading the code";
  if (g.stage === "cut") return "dividing it into parts";
  return g.line ?? "";
}

const GLYPH = { done: "✓", drafting: "◷", failed: "✗", queued: "○" } as const;

/**
 * The parts of a bluprint being made, in the order the cut put them. A finished one
 * opens straight away: it passed the same check inside the author's submit that
 * a root of a finished bluprint passes, so there is nothing provisional about it.
 */
function Roots({ roots, onOpen }: { roots: Progress["roots"]; onOpen: (at: string) => void }) {
  return (
    <ul className="flex flex-col gap-0.5 font-mono text-[11.5px]">
      {roots.map((r) => (
        <li key={r.id} className="flex items-baseline gap-2">
          <span className={cn("w-3 shrink-0", r.status === "done" ? "text-accent" : r.status === "failed" ? "text-clay-ink" : r.status === "drafting" ? "text-amber-ink" : "text-faint")}>
            {GLYPH[r.status]}
          </span>
          {r.status === "done" ? (
            <button type="button" onClick={() => onOpen(r.id)} className="min-w-0 flex-1 cursor-pointer truncate text-left text-ink hover:underline">
              {r.title}
            </button>
          ) : (
            <span className={cn("min-w-0 flex-1 truncate", r.status === "queued" ? "text-faint" : "text-on-surface-variant")}>{r.title}</span>
          )}
          <span className={cn("shrink-0", r.status === "done" ? "text-accent" : r.status === "failed" ? "text-clay-ink" : "text-faint")}>{r.detail}</span>
        </li>
      ))}
    </ul>
  );
}

/** The row's one-word state, and its tone; the detail is in the title. */
function statusOf(p: Listed): { text: string; title?: string; tone: string } {
  const { status, commit, seconds } = p.bluprint;
  if (status === "generating") return { text: `Mapping · ${minutes(p.bluprint.startedAt)} min`, tone: "text-amber-ink" };
  if (status === "failed" && !p.paused) return { text: "Mapping failed", tone: "text-clay-ink" };
  if (p.paused) return p.hasBluprint ? { text: "Updates off", title: `The bluprint from ${commit ?? "earlier"} is kept as it is.`, tone: "text-faint" } : { text: "No bluprint", tone: "text-faint" };
  if (status === "ready")
    return p.stale
      ? { text: "Out of date", title: `Bluprint made at ${commit ?? "?"}; the code has changed since.`, tone: "text-amber-ink" }
      : { text: commit ? `Bluprint · ${commit}` : "Bluprint ready", title: seconds ? `Took ${Math.round(seconds / 60)} min` : undefined, tone: "text-faint" };
  if (status === "cancelled") return { text: "Cancelled", tone: "text-faint" };
  return { text: "Empty", title: "Make its bluprint once it has code.", tone: "text-faint" };
}

function ProjectRow({
  p,
  home,
  current,
  busy,
  onOpen,
  onRegenerate,
  onCancel,
  onPause,
  onRemove,
}: {
  p: Listed;
  home?: string;
  current: boolean;
  busy: boolean;
  onOpen: (at?: string) => void;
  onRegenerate: (explain: Explain, full?: boolean) => void;
  onCancel: () => void;
  onPause: (paused: boolean) => void;
  onRemove: () => void;
}) {
  // What opens under the row: making the bluprint (again), or confirming removal,
  // which deletes the bluprint but never the code.
  const [panel, setPanel] = useState<"make" | "remove" | null>(null);
  const [menu, setMenu] = useState<{ x: number; y: number } | null>(null);
  const [understand, setUnderstand] = useState(() => Math.max(0, UNDERSTAND.findIndex((u) => u.explain === (p.explain ?? "full"))));
  const { status } = p.bluprint;
  const generating = status === "generating";
  const openable = p.hasBluprint || p.paused || status === "empty";
  const s = statusOf(p);

  const items: MenuItem[] = [];
  if (openable) items.push({ label: "Open", onClick: () => onOpen() });
  if (generating) items.push({ label: "Cancel bluprint", onClick: onCancel, disabled: busy });
  else {
    if (status === "ready") items.push({ label: "Update bluprint to the code", onClick: () => onRegenerate(p.explain ?? "full"), disabled: busy });
    if (status === "failed" || status === "cancelled") items.push({ label: "Retry bluprint", onClick: () => onRegenerate(p.explain ?? "full"), disabled: busy });
    items.push({ label: p.hasBluprint ? "Remake bluprint…" : "Make a bluprint…", onClick: () => setPanel("make") });
    if (p.hasBluprint) items.push({ label: p.paused ? "Keep the bluprint updated" : "Stop updating the bluprint", onClick: () => onPause(!p.paused), disabled: busy });
  }
  items.push({ label: "Remove from Projects…", onClick: () => setPanel("remove"), separated: true });

  return (
    <li className="flex flex-col">
      <div className="group flex items-center gap-3 px-3 py-2 hover:bg-surface-container">
        <button
          type="button"
          onClick={() => openable && onOpen()}
          disabled={!openable}
          className="flex min-w-0 flex-1 cursor-pointer flex-col items-start text-left disabled:cursor-default"
        >
          <span className="flex max-w-full items-center gap-2">
            <span className="truncate text-[13.5px] font-medium text-ink">{p.name}</span>
            {current ? <span className="shrink-0 bg-accent-surface px-1.5 text-[10.5px] font-medium text-accent">Open</span> : null}
          </span>
          <span className="max-w-full truncate font-mono text-[11.5px] text-faint" title={p.root}>
            {tilde(p.root, home)}
          </span>
        </button>
        <span className={cn("shrink-0 text-[12px]", s.tone)} title={s.title}>
          {s.text}
        </span>
        {generating ? (
          <button type="button" onClick={onCancel} disabled={busy} className={cn(QUIET, "shrink-0")}>
            Cancel
          </button>
        ) : null}
        <button
          type="button"
          aria-label={`Actions for ${p.name}`}
          aria-haspopup="menu"
          onClick={(e) => {
            const r = e.currentTarget.getBoundingClientRect();
            setMenu({ x: r.right - 220, y: r.bottom + 4 });
          }}
          className={cn(
            "flex size-7 shrink-0 cursor-pointer items-center justify-center text-[16px] leading-none text-faint hover:bg-border-gray hover:text-ink focus-visible:opacity-100",
            menu ? "bg-border-gray text-ink" : "opacity-60 group-hover:opacity-100",
          )}
        >
          ⋯
        </button>
      </div>

      {menu ? <Menu x={menu.x} y={menu.y} items={items} onClose={() => setMenu(null)} /> : null}

      {generating && (stageLine(p.progress) || p.progress?.roots.length) ? (
        <div className="px-3 pb-2">
          {stageLine(p.progress) ? <p className="font-mono text-[11.5px] text-amber-ink">◷ {stageLine(p.progress)}</p> : null}
          {p.progress?.roots.length ? <Roots roots={p.progress.roots} onOpen={onOpen} /> : null}
        </div>
      ) : null}

      {status === "failed" && !p.paused && p.bluprint.error ? (
        <pre className="mx-3 mb-2 max-h-28 overflow-auto whitespace-pre-wrap bg-clay-surface/60 px-2.5 py-2 font-mono text-[11px] text-clay-ink">
          {p.bluprint.error}
        </pre>
      ) : null}

      {panel === "make" ? (
        <div className="mx-3 mb-2 mt-1 flex flex-col gap-4 border border-border-gray bg-surface px-4 py-4">
          <Understanding value={understand} onChange={setUnderstand} />
          <div className="flex items-center justify-end gap-2">
            <p className="mr-auto text-[12px] text-muted-slate">About 20 min with your Claude Code, on your plan.</p>
            <button type="button" onClick={() => setPanel(null)} className={cn(QUIET, "shrink-0")}>
              Cancel
            </button>
            <button
              type="button"
              disabled={busy}
              onClick={() => {
                setPanel(null);
                onRegenerate(UNDERSTAND[understand].explain, p.hasBluprint);
              }}
              className={PRIMARY}
            >
              {p.hasBluprint ? "Remake bluprint" : "Make bluprint"}
            </button>
          </div>
        </div>
      ) : null}

      {panel === "remove" ? (
        <div className="mx-3 mb-2 mt-1 flex items-center gap-2 border border-clay-line bg-clay-surface/40 px-4 py-2.5">
          <p className="mr-auto text-[12.5px] text-ink">
            Remove <span className="font-semibold">{p.name}</span>? This deletes its bluprint, not the folder.
          </p>
          <button type="button" onClick={() => setPanel(null)} className={QUIET}>
            Cancel
          </button>
          <button
            type="button"
            disabled={busy}
            onClick={onRemove}
            className={cn(PRIMARY, "border-clay-ink bg-clay-ink text-paper hover:border-clay-ink hover:bg-clay-ink hover:opacity-90")}
          >
            Remove
          </button>
        </div>
      ) : null}
    </li>
  );
}

