"use client";

import { useState, useSyncExternalStore } from "react";
import { FilePane } from "@/components/review/commit-detail";
import type { View } from "@/components/review/diff-view";
import type { FileChange } from "@/lib/server/diff";
import { cn } from "@/lib/client/utils";

/**
 * The file picked in the history panel (components/review/diff-panel.tsx), read
 * in a tab of the workspace window (components/agent/workspace.tsx) rather than
 * inside the panel, so the panel stays a small popup and the lines get the room.
 * The workspace sits outside the diff's provider, hence a store both can reach.
 *
 * `open` is whether the panel is still up: closing it closes the tab, unless the
 * reader moved the tab into the main view to keep it.
 */
export interface DiffFile {
  files: FileChange[];
  path: string;
  open: boolean;
}

let now: DiffFile | null = null;
const heard = new Set<() => void>();

export function setDiffFile(next: DiffFile | null | ((was: DiffFile | null) => DiffFile | null)) {
  now = typeof next === "function" ? next(now) : next;
  for (const f of heard) f();
}

export const useDiffFile = () =>
  useSyncExternalStore(
    (f) => (heard.add(f), () => void heard.delete(f)),
    () => now,
    () => null,
  );

const VIEW_KEY = "bluprint.diff.view";

export function DiffTab({ visible, inset }: { visible: boolean; inset?: string }) {
  const d = useDiffFile();
  const [view, setView] = useState<View>(() => {
    try {
      return localStorage.getItem(VIEW_KEY) === "split" ? "split" : "inline";
    } catch {
      return "inline";
    }
  });
  const file = d?.files.find((f) => f.path === d.path);
  if (!d || !file) return null;
  const at = d.files.indexOf(file);
  const keep = (v: View) => {
    setView(v);
    try {
      localStorage.setItem(VIEW_KEY, v);
    } catch {}
  };
  return (
    <div className={cn("absolute inset-0 flex flex-col bg-card", !visible && "hidden")} style={inset ? { right: inset } : undefined}>
      <FilePane
        file={file}
        view={view}
        at={at}
        of={d.files.length}
        onStep={(k) => setDiffFile({ ...d, path: d.files[at + k]?.path ?? d.path })}
        layout={
          <div role="group" aria-label="Diff layout" className="flex shrink-0 border border-border-gray p-0.5">
            {(["inline", "split"] as const).map((v) => (
              <button
                key={v}
                type="button"
                aria-pressed={view === v}
                onClick={() => keep(v)}
                className={cn("cursor-pointer px-2 py-0.5 text-[11.5px]", view === v ? "bg-accent text-on-accent" : "text-muted-slate hover:text-ink")}
              >
                {v === "split" ? "Side by side" : "Inline"}
              </button>
            ))}
          </div>
        }
      />
    </div>
  );
}

app/components/review/diff-panel.tsx:
"use client";

import { Fragment, useEffect, useMemo, useRef, useState } from "react";
import { DIALOG, Overlay } from "@/components/ui/dialog";
import { OPEN_DIFF, TINT, useDiff } from "@/components/review/diff";
import { goTo } from "@/components/chrome/crumbs";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import type { Commit, SectionDiff } from "@/lib/server/diff";
import { ReviewCard, ReviewPicker, Outside } from "@/components/review/reviews";
import { FileRow, Rail, Row } from "@/components/review/commits";
import { Comparing, Details, EndTag, OnTheBluprint, Refs } from "@/components/review/commit-detail";
import { setDiffFile, useDiffFile } from "@/components/review/diff-file";
import { showBluprint } from "@/lib/agent/workspace-toggle";
import { ago } from "@/components/review/ago";
import { openTimeline } from "@/components/review/timeline";

/**
 * The history and what each commit did, laid out the way a code editor's
 * source control is (D75): the commits down the left on one line, the one
 * picked opening onto its files beneath it (clicked again, folding them
 * away). A file picked opens in a tab of the workspace window
 * (components/review/diff-file.tsx), so this stays a small popup; it closes
 * with the panel unless moved to the main view. The right side is the
 * commit itself — who, when, and which sections of the bluprint it moved, each
 * opening its level, where the red and green are drawn in place
 * (components/review/diff.tsx).
 *
 * ↑/↓ walk commits and files as one list, so reading a commit is the arrow
 * key and nothing else. Comparing is any two commits, as an editor's history
 * does it: "Compare with selected" on a row, or ⇧/⌘-click it; the right side
 * then names both ends and can swap them. It opens on the newest commit —
 * the bluprint keeps itself current, so "since the bluprint was made" is not a
 * question worth a row (D76).
 *
 * Mounted once beside the other dialogs and opened by the same event that
 * turns diff mode on, so there is one way in. Leaving is `off`, in the header.
 */

type Item = { k: "commit"; c: Commit } | { k: "file"; path: string };

export function DiffPanel() {
  const d = useDiff();
  const { nodeAt, name: bluprint } = useBluprint();
  const [shown, setShownRaw] = useState(false);
  // A commit clicked again folds its files away.
  const [folded, setFolded] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const reading = useDiffFile();
  const list = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const on = () => setShownRaw(true);
    window.addEventListener(OPEN_DIFF, on);
    return () => window.removeEventListener(OPEN_DIFF, on);
  }, []);

  const diff = d?.diff ?? null;
  const all = useMemo(() => d?.commits ?? [], [d?.commits]);
  const q = query.trim().toLowerCase();
  const commits = useMemo(
    () => (q ? all.filter((c) => c.subject.toLowerCase().includes(q) || c.author.toLowerCase().includes(q) || c.sha.startsWith(q)) : all),
    [all, q],
  );

  const is = (c: Commit, ref?: string) => !!ref && (c.sha === ref || c.short === ref || c.sha.startsWith(ref));
  const single = d?.to && d.from === `${d.to}~1` ? d.to : undefined;
  const picked = single ? all.find((c) => is(c, single)) : undefined;
  // Two commits compared: `from` is the base, `to` what it is compared with.
  const pair = !single && d && !d.review && d.from && d.to ? { base: all.find((c) => is(c, d.from)), with: all.find((c) => is(c, d.to)) } : null;
  const span = pair?.base && pair.with ? [all.indexOf(pair.base), all.indexOf(pair.with)].sort((a, b) => a - b) : null;
  const files = d && !d.loading ? (diff?.files ?? []) : [];
  // The file read in the workspace (components/review/diff-file.tsx), while it is one of this pick's.
  const open = reading?.open && reading.files === files ? (files.find((f) => f.path === reading.path) ?? null) : null;
  const setFile = (path: string | null) => setDiffFile(path ? { files, path, open: true } : null);
  const setShown = (on: boolean) => {
    setShownRaw(on);
    // The file's tab goes with the panel, unless it was moved into the main view to keep.
    if (!on) setDiffFile((was) => was && { ...was, open: false });
  };

  const items: Item[] = [];
  for (const c of commits) {
    items.push({ k: "commit", c });
    if (c === (picked ?? pair?.with) && folded !== c.sha) for (const f of files) items.push({ k: "file", path: f.path });
  }
  const atCommit = items.findIndex((it) => it.k === "commit" && it.c === (picked ?? pair?.with));
  const atFile = open ? items.findIndex((it) => it.k === "file" && it.path === open.path) : -1;
  // A file folded away under its commit leaves the commit lit.
  const active = atFile >= 0 ? atFile : atCommit;

  useEffect(() => {
    if (shown) list.current?.querySelector('[data-active="true"]')?.scrollIntoView({ block: "nearest" });
  }, [shown, active]);
  useEffect(() => {
    if (shown) list.current?.focus({ preventScroll: true });
  }, [shown]);

  if (!shown || !d) return null;

  function pick(it: Item, click = false) {
    if (it.k === "file") return setFile(it.path);
    if (it.c === picked) {
      if (click) setFolded((f) => (f === it.c.sha ? null : it.c.sha));
      return;
    }
    setFolded(null);
    d!.setRange(`${it.c.sha}~1`, it.c.sha);
  }

  /** The commit in view, compared with `c`: the older is the base. */
  const anchor = picked ?? pair?.with;
  function compare(c: Commit) {
    if (!anchor || anchor === c) return pick({ k: "commit", c });
    const [newer, older] = all.indexOf(anchor) < all.indexOf(c) ? [anchor, c] : [c, anchor];
    d!.setRange(older.sha, newer.sha);
  }

  /** The trail to a section, in the titles the reader sees rather than ids. */
  const trail = (s: SectionDiff) =>
    s.path
      .slice(0, -1)
      .map((_, i) => nodeAt(s.path.slice(0, i + 1))?.title ?? s.path[i])
      .join(" › ");

  const short = (ref?: string) => (ref ? (all.find((c) => is(c, ref))?.short ?? ref.slice(0, 7)) : "");
  const caption = d.review
    ? d.review.startsWith("turn:")
      ? "What one agent turn changed"
      : d.review.startsWith("pr:")
        ? `Reviewing pull request #${d.review.slice(3)}`
        : `Reviewing ${d.review.split("...")[1]} since it left ${d.review.split("...")[0]}`
    : picked
      ? `${picked.short} · ${picked.subject}`
      : single
        ? single
        : d.from || d.to
          ? `Comparing ${short(d.from) || "the start"} ⇄ ${short(d.to) || "your working tree"}`
          : "Reading the history…";

  return (
    <Overlay
      onClose={() => setShown(false)}
      dim
      // A file open in the workspace window: the popup keeps clear of it.
      style={reading?.open ? { paddingRight: "calc(var(--workspace-inset, 0px) + 24px)" } : undefined}
    >
      {/* With a file open beside it, only the list stays: the commit's details would be crushed, and the file is what is being read. */}
      <div className={DIALOG + " pop h-[min(620px,100%)] " + (reading?.open ? "max-w-[360px]" : "max-w-[940px]")}>
        <header className="flex shrink-0 items-center gap-3 border-b border-border-gray px-4 py-2.5">
          <h2 className="text-[14px] font-semibold text-ink">History</h2>
          <span className="min-w-0 flex-1 truncate text-[12px] text-muted-slate">{reading?.open ? null : caption}</span>
          <button
            type="button"
            onClick={() => {
              setShown(false);
              openTimeline();
              // A tab docked in the main view would hide the timeline it opens on.
              showBluprint();
            }}
            title="How the code got here — every commit on the bluprint's sections, over time"
            className="shrink-0 cursor-pointer px-2 py-1 text-[12px] text-muted-slate hover:bg-surface-container-low hover:text-ink"
          >
            Timeline
          </button>
          <button
            type="button"
            onClick={() => setShown(false)}
            title="Close this and keep the bluprint coloured by what changed"
            className={(reading?.open ? "hidden " : "") + "shrink-0 cursor-pointer px-2 py-1 text-[12px] text-accent hover:bg-surface-container-low"}
          >
            See it on the bluprint
          </button>
          <button
            type="button"
            onClick={() => {
              d.off();
              setShown(false);
            }}
            className="shrink-0 cursor-pointer px-2 py-1 text-[12px] text-muted-slate hover:bg-surface-container-low hover:text-ink"
          >
            Leave diff
          </button>
          <button
            type="button"
            aria-label="Close"
            onClick={() => setShown(false)}
            className="shrink-0 cursor-pointer px-1.5 py-0.5 text-[15px] leading-none text-muted-slate hover:bg-surface-container-low hover:text-ink"
          >
            ×
          </button>
        </header>

        <div className="flex min-h-0 flex-1">
          {/* ── history ── */}
          <aside className={reading?.open ? "flex min-w-0 flex-1 flex-col" : "flex w-[320px] shrink-0 flex-col border-r border-border-gray"}>
            <div className="shrink-0 border-b border-border-gray p-2">
              <ReviewPicker bluprint={bluprint} value={d.review} onPick={d.setReview} />
              <input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Filter commits by message, author or sha"
                aria-label="Filter commits"
                className="mt-2 w-full border border-border-gray bg-card px-2.5 py-1.5 text-[12px] text-ink placeholder:text-faint focus:border-accent focus:outline-none"
              />
            </div>
            <div
              ref={list}
              role="listbox"
              aria-label="Commits and their files"
              tabIndex={0}
              onKeyDown={(e) => {
                if (e.key !== "ArrowDown" && e.key !== "ArrowUp") return;
                e.preventDefault();
                const at = Math.max(0, Math.min(items.length - 1, (active < 0 ? 0 : active) + (e.key === "ArrowDown" ? 1 : -1)));
                pick(items[at]);
              }}
              className="min-h-0 flex-1 overflow-y-auto py-1 outline-none"
            >
              {items.map((it, i) => {
                const on = i === active;
                const first = i === 0;
                const last = i === items.length - 1;
                if (it.k === "file") {
                  const f = files.find((x) => x.path === it.path)!;
                  return <FileRow key={`f:${it.path}:${i}`} file={f} on={on} last={last} onPick={() => pick(it)} />;
                }
                const c = it.c;
                const n = all.indexOf(c);
                const end = c === pair?.base ? "base" : c === pair?.with ? "compare" : null;
                const inPair = !!span && n >= span[0] && n <= span[1];
                return (
                  <Fragment key={c.sha}>
                    <Row
                      on={on || !!end}
                      soft={inPair}
                      onPick={(e) => (e.shiftKey || e.metaKey || e.ctrlKey ? compare(c) : pick(it, true))}
                      title={`${c.subject}\n${c.author} <${c.email ?? ""}> · ${new Date(c.at).toLocaleString()}\n${c.sha}`}
                    >
                      <Rail dot={(c.parents?.length ?? 0) > 1 ? "merge" : on || inPair ? "on" : "off"} first={first} last={last} />
                      <span className="min-w-0 flex-1 py-1.5">
                        <span className="flex items-center gap-1">
                          {end ? <EndTag end={end} /> : null}
                          <Refs refs={c.refs} max={2} />
                          <span className="min-w-0 truncate text-[12.5px] text-ink">{c.subject}</span>
                        </span>
                        <span className="block truncate text-[11px] text-muted-slate">
                          {ago(c.at)} · {c.author}
                        </span>
                      </span>
                      <span className="shrink-0 py-1.5 text-right font-mono text-[10.5px] leading-[1.55]">
                        <span className="block text-faint">{c.short}</span>
                        <span className="tnum block">
                          <span style={{ color: TINT.added.ink }}>+{c.added}</span> <span style={{ color: TINT.removed.ink }}>−{c.removed}</span>
                        </span>
                      </span>
                      {anchor && anchor !== c ? (
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            compare(c);
                          }}
                          title={`Compare ${c.short} with ${anchor.short}`}
                          className="absolute right-2 top-1/2 hidden -translate-y-1/2 cursor-pointer border border-border-strong bg-card px-1.5 py-0.5 text-[10.5px] text-ink shadow-sm hover:border-accent group-hover:block"
                        >
                          ⇄ Compare with {anchor.short}
                        </button>
                      ) : null}
                    </Row>
                    {/* The commit's own paths, from the log, while its diff is read. */}
                    {c === picked && d.loading && folded !== c.sha
                      ? c.files.slice(0, 200).map((p) => (
                          <div key={p} className="flex items-center gap-1.5 pr-3 text-faint">
                            <Rail />
                            <span className="min-w-0 flex-1 truncate pl-3 font-mono text-[11.5px]">{p}</span>
                          </div>
                        ))
                      : null}
                  </Fragment>
                );
              })}
              {!all.length ? <p className="px-4 py-3 text-[12px] text-muted-slate">Reading the history…</p> : null}
              {q && !commits.length ? <p className="px-4 py-3 text-[12px] text-muted-slate">No commit matches “{query}”.</p> : null}
            </div>
            <p className="shrink-0 border-t border-border-gray px-3 py-1.5 text-[11px] text-faint">↑↓ to move · ⇧ or ⌘-click a second commit to compare</p>
          </aside>

          {/* ── what the pick changed ── */}
          <main className={reading?.open ? "hidden" : "flex min-w-0 flex-1 flex-col"}>
            <div className="min-h-0 flex-1 overflow-y-auto px-6 py-5">
                {picked ? (
                  <Details key={picked.sha} bluprint={bluprint} commit={picked} all={all} onPick={(c) => pick({ k: "commit", c })} />
                ) : pair?.base && pair.with ? (
                  <Comparing
                    base={pair.base}
                    other={pair.with}
                    between={span ? span[1] - span[0] : 0}
                    onSwap={() => d.setRange(d.to, d.from)}
                    onDone={() => pick({ k: "commit", c: pair.with! })}
                  />
                ) : (
                  <h3 className="text-[17px] font-semibold leading-snug text-ink">{caption}</h3>
                )}
                {diff?.review ? <ReviewCard r={diff.review} bluprint={bluprint} spec={d.review} onMade={d.reload} /> : null}
                {d.loading ? <p className="mt-4 text-[13px] text-muted-slate">Reading what changed…</p> : null}
                {d.error ? (
                  <p className="mt-4 text-[13px]" style={{ color: TINT.removed.ink }}>
                    {d.error}
                  </p>
                ) : null}
                {diff && !d.loading ? (
                  <>
                    <p className="tnum mt-2 font-mono text-[11.5px] text-muted-slate">
                      {diff.files.length} {diff.files.length === 1 ? "file" : "files"} ·{" "}
                      <span style={{ color: TINT.added.ink }}>+{diff.files.reduce((n, f) => n + f.added, 0)}</span>{" "}
                      <span style={{ color: TINT.removed.ink }}>−{diff.files.reduce((n, f) => n + f.removed, 0)}</span>
                    </p>
                    {/* A file-level answer never pretends to be a section-level one. */}
                    <h3 className="mt-6 text-[12px] font-medium text-muted-slate">Files — pick one to read its lines</h3>
                    {diff.files.length ? (
                      <div className="mt-1.5 overflow-hidden border border-border-gray">
                        {diff.files.map((f) => (
                          <FileRow key={f.path} file={f} flat onPick={() => setFile(f.path)} />
                        ))}
                      </div>
                    ) : (
                      <p className="mt-1.5 text-[13px] text-muted-slate">Nothing changed.</p>
                    )}
                    {diff.basis === "files" ? <p className="mt-4 text-[12.5px] leading-snug text-on-surface-variant">{diff.why}</p> : null}
                    {diff.basis === "sections" ? <OnTheBluprint sections={diff.sections} trail={trail} onOpen={(s) => (goTo(s.path), setShown(false))} /> : null}
                    {diff.outside?.length ? <Outside outside={diff.outside} title={(p) => nodeAt(p)?.title ?? p.at(-1)!} onOpen={(p) => (goTo(p), setShown(false))} /> : null}
                  </>
                ) : null}
            </div>
          </main>
        </div>
      </div>
    </Overlay>
  );
}

app/components/review/diff-view.tsx:
"use client";

import { Fragment, memo, useMemo } from "react";
import { TINT } from "@/components/review/diff";
import type { HunkLines } from "@/lib/client/hunks";
import { startNote, useNotes } from "@/lib/agent/notes";
import type { Target } from "@/lib/agent/context";
import { TOKEN_COLOR, highlight, langOf } from "@/lib/client/highlight";
import { cn } from "@/lib/client/utils";

export type View = "split" | "inline";

/* ── the lines ───────────────────────────────────────────────── */

type Cell = { n: number; text: string; kind: "+" | "-" | " " } | null;

/** A hunk as rows of [old, new]: removals beside the additions that replaced them. */
function pairsOf(h: HunkLines): [Cell, Cell][] {
  const out: [Cell, Cell][] = [];
  const ls = h.lines;
  for (let i = 0; i < ls.length; ) {
    if (ls[i].kind === " ") {
      out.push([{ n: ls[i].old!, text: ls[i].text, kind: " " }, { n: ls[i].new!, text: ls[i].text, kind: " " }]);
      i++;
      continue;
    }
    const del: Cell[] = [];
    const add: Cell[] = [];
    for (; i < ls.length && ls[i].kind === "-"; i++) del.push({ n: ls[i].old!, text: ls[i].text, kind: "-" });
    for (; i < ls.length && ls[i].kind === "+"; i++) add.push({ n: ls[i].new!, text: ls[i].text, kind: "+" });
    for (let k = 0; k < Math.max(del.length, add.length); k++) out.push([del[k] ?? null, add[k] ?? null]);
  }
  return out;
}

const BG = { "+": TINT.added.surface, "-": TINT.removed.surface, " ": undefined };
// Where one side has no line, the other's is not stretched to meet it.
const FILLER = "repeating-linear-gradient(-45deg, transparent 0 5px, var(--color-border-gray) 5px 6px)";

/**
 * The unchanged lines between two hunks, as one row both sides share. On the
 * side that carries it, the hunk below can be commented on, for the review
 * (components/review/review-tray.tsx).
 */
function Gap({ h, prev, path }: { h: HunkLines; prev?: HunkLines; path?: string }) {
  const end = prev ? Math.max(...prev.lines.map((l) => l.old ?? 0), prev.oldStart - 1) : 0;
  const n = h.oldStart - end - 1;
  const noted = useNotes().some((x) => x.status === "draft" && x.anchor.key === (path ? hunkKey(path, h) : ""));
  return (
    <div className="sticky left-0 flex h-6 w-max items-center gap-3 bg-surface-container-low px-3 font-sans text-[10.5px] leading-6 text-faint">
      <span>{n > 0 ? `⋯ ${n} unchanged ${n === 1 ? "line" : "lines"}` : "⋯"}</span>
      {path ? (
        <button
          type="button"
          onClick={(e) => startNote({ x: e.clientX, y: e.clientY + 12, kind: "comment", anchor: hunkTarget(path, h) })}
          className="cursor-pointer text-accent hover:underline"
        >
          {noted ? "✎ commented — add another" : "✎ Comment on this change"}
        </button>
      ) : null}
    </div>
  );
}

const hunkKey = (path: string, h: HunkLines) => `hunk:${path}:${h.oldStart}:${h.newStart}`;

/** A hunk as Claude reads it in a review: where it is, and the lines, as a unified diff. */
function hunkTarget(path: string, h: HunkLines): Target {
  const news = h.lines.filter((l) => l.new !== undefined).map((l) => l.new!);
  const span = news.length ? `${Math.min(...news)}-${Math.max(...news)}` : `${h.newStart}`;
  const CAP = 80;
  const lines = h.lines.slice(0, CAP).map((l) => `${l.kind}${l.text}`);
  if (h.lines.length > CAP) lines.push(`… ${h.lines.length - CAP} more lines`);
  return {
    key: hunkKey(path, h),
    title: `${path}:${span}`,
    text: [`[Diff hunk: ${path}, now lines ${span}`, "```diff", ...lines, "```]"].join("\n"),
  };
}

function Code({ text, lang }: { text: string; lang: ReturnType<typeof langOf> }) {
  return (
    <code className="whitespace-pre pr-4 text-code-plain">
      {text
        ? highlight(text, lang)[0].map((t, k) => (
            <span key={k} style={{ color: TOKEN_COLOR[t.kind] }}>
              {t.text}
            </span>
          ))
        : " "}
    </code>
  );
}

// Memoised, as is InlineDiff: every line is highlighted as it is drawn, and
// typing in the commit filter re-renders the whole panel around an open file.
export const SplitDiff = memo(function SplitDiff({ hunks, path }: { hunks: HunkLines[]; path: string }) {
  const lang = langOf(path);
  const rows = useMemo(() => hunks.map(pairsOf), [hunks]);
  // Each side scrolls sideways on its own, as two editors would; rows are one
  // fixed height so the two stay level without measuring.
  const side = (s: 0 | 1) => (
    <div className={cn("min-w-0 flex-1 overflow-x-auto", s === 1 && "border-l border-border-gray")}>
      <div className="w-max min-w-full font-mono text-[12px]">
        {hunks.map((h, i) => (
          <Fragment key={i}>
            <Gap h={h} prev={hunks[i - 1]} path={s === 1 ? path : undefined} />
            {rows[i].map((r, j) => {
              const c = r[s];
              return (
                <div key={j} className="flex h-5 leading-5" style={{ background: c ? BG[c.kind] : FILLER }}>
                  <span className="tnum w-11 shrink-0 select-none pr-2 text-right text-faint">{c?.n ?? ""}</span>
                  <span className="w-4 shrink-0 select-none text-center" style={{ color: c?.kind === "+" ? TINT.added.ink : TINT.removed.ink }}>
                    {c?.kind === "+" ? "+" : c?.kind === "-" ? "−" : ""}
                  </span>
                  {c ? <Code text={c.text} lang={lang} /> : null}
                </div>
              );
            })}
          </Fragment>
        ))}
      </div>
    </div>
  );
  return (
    <div className="flex">
      {side(0)}
      {side(1)}
    </div>
  );
});

export const InlineDiff = memo(function InlineDiff({ hunks, path }: { hunks: HunkLines[]; path: string }) {
  const lang = langOf(path);
  return (
    <div className="overflow-x-auto">
      <div className="w-max min-w-full font-mono text-[12px]">
        {hunks.map((h, i) => (
          <Fragment key={i}>
            <Gap h={h} prev={hunks[i - 1]} path={path} />
            {h.lines.map((l, j) => (
              <div key={j} className="flex h-5 leading-5" style={{ background: BG[l.kind] }}>
                <span className="tnum w-11 shrink-0 select-none pr-2 text-right text-faint">{l.old ?? ""}</span>
                <span className="tnum w-11 shrink-0 select-none pr-2 text-right text-faint">{l.new ?? ""}</span>
                <span className="w-4 shrink-0 select-none text-center" style={{ color: l.kind === "+" ? TINT.added.ink : TINT.removed.ink }}>
                  {l.kind === "+" ? "+" : l.kind === "-" ? "−" : ""}
                </span>
                <Code text={l.text} lang={lang} />
              </div>
            ))}
          </Fragment>
        ))}
      </div>
    </div>
  );
});

app/components/review/diff.tsx:
"use client";

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { BOX_H, layoutDiagram } from "@/lib/bluprint/diagram";
import type { Anatomy } from "@/lib/bluprint/schema";
import type { BlockDiff, Commit, FileChange, BluprintDiff, PartDiff, RowDiff, Verdict } from "@/lib/server/diff";
import { hunksOf, type HunkLines } from "@/lib/client/hunks";
import { TOKEN_COLOR, highlight, langOf } from "@/lib/client/highlight";
import { cn } from "@/lib/client/utils";

/**
 * Diff mode: the same level, saying what a commit did to it.
 *
 * Not a separate screen. A diff view beside the bluprint would be a second thing to
 * learn and would lose the one property that makes this worth building — that
 * the reader already knows where everything on this level is, so a red row and
 * a green row in a place they recognise is a review they can do at a glance.
 * So every piece here DECORATES: `SectionTint` wraps a card the canvas already
 * draws, `SchemaDiff` replaces one block with the same block in two colours.
 *
 * What is gone stays on screen. The whole claim of "the old schema in red
 * beside the new in green" is that both are visible at once; a diff that only
 * shows what is now there is the file listing the reader was already able to
 * get from git.
 *
 * Red/green are `--color-diff-*` (app/globals.css), read through inline
 * `var()` rather than Tailwind classes — see the note there. They are
 * deliberately not the state families: a verdict is about a commit, a state is
 * about the analysis, and tinting one with the other's colours would claim
 * that a deleted thing was alarming.
 */

/* ── the tokens, as the only place that names them ───────────── */

export const TINT: Record<Exclude<Verdict, "untouched">, { ink: string; surface: string; line: string; mark: string }> = {
  added: { ink: "var(--color-diff-add-ink)", surface: "var(--color-diff-add-surface)", line: "var(--color-diff-add-line)", mark: "+" },
  removed: { ink: "var(--color-diff-remove-ink)", surface: "var(--color-diff-remove-surface)", line: "var(--color-diff-remove-line)", mark: "−" },
  // `changed` borrows the amber family, which already means "look here, this
  // is not settled" everywhere else on the page.
  changed: { ink: "var(--color-amber-ink)", surface: "var(--color-amber-surface)", line: "var(--color-amber-line)", mark: "~" },
};

export const WORD: Record<Verdict, string> = { added: "new", removed: "gone", changed: "changed", untouched: "unchanged" };

/* ── loading one ─────────────────────────────────────────────── */

export interface DiffState {
  /** null while off: diff mode is the presence of an answer, not a flag beside one. */
  diff: BluprintDiff | null;
  loading: boolean;
  error?: string;
  from?: string;
  to?: string;
  /** `pr:<n>` or `<base>...<branch>`, where the diff is a review (lib/server/review.ts); it then sets both ends. */
  review?: string;
  commits: Commit[];
  setRange: (from?: string, to?: string) => void;
  setReview: (spec?: string) => void;
  /** Asks again for the same diff, when something it is drawn from was made since (a review's bluprint after). */
  reload: () => void;
  off: () => void;
}

const Ctx = createContext<DiffState | null>(null);

/** The open diff, or null. Any component on a level can ask without being passed it. */
export const useDiff = () => useContext(Ctx);

/** The verdict on one section, by the path the canvas navigates by. */
function useVerdict(path: string[]): Verdict {
  const d = useDiff();
  const key = path.join("/");
  return useMemo(() => d?.diff?.sections.find((s) => s.path.join("/") === key)?.verdict ?? "untouched", [d, key]);
}

/** This level's block diffs, by index in `anatomy`. */
export function useBlockDiffs(path: string[]): Map<number, BlockDiff> {
  const d = useDiff();
  const key = path.join("/");
  return useMemo(
    () => new Map((d?.diff?.blocks ?? []).filter((b) => b.path.join("/") === key).map((b) => [b.at, b])),
    [d, key],
  );
}

/**
 * Holds the comparison for everything below it. Mounted once, around the
 * canvas; `on` turns the mode on and the provider does the fetching, so no
 * level has to know the API exists.
 */
export const OPEN_DIFF = "bluprint:diff";

/**
 * Anything can ask for diff mode: the title bar's button dispatches this, and
 * `DiffPanel` (components/review/diff-panel.tsx) opens on the same event.
 */
export const openDiff = () => window.dispatchEvent(new Event(OPEN_DIFF));

const OPEN_REVIEW = "bluprint:review";
/** Diff mode on one review (`pr:<n>`, `<base>...<branch>`, `turn:<id>` or `turn:latest`), from outside the provider, as the status bar is. */
export const openReview = (spec: string) => {
  window.dispatchEvent(new CustomEvent<string>(OPEN_REVIEW, { detail: spec }));
  openDiff();
};

/**
 * Diff mode, owned here and asked for from anywhere — the same event-bus shape
 * Settings and Projects use, so the title bar does not have to hold state the
 * canvas is the one to read.
 *
 * The event only ever turns the mode ON. Leaving is `off`, which the panel's
 * "Leave diff" calls — one way in and one way out, rather than a flip whose
 * meaning depends on state the title bar cannot see.
 */
export function DiffMode({ bluprint, children }: { bluprint: string; children: React.ReactNode }) {
  const [on, setOn] = useState(false);
  useEffect(() => {
    const go = () => setOn(true);
    window.addEventListener(OPEN_DIFF, go);
    return () => window.removeEventListener(OPEN_DIFF, go);
  }, []);
  return (
    <DiffProvider bluprint={bluprint} on={on} onOff={() => setOn(false)}>
      {children}
    </DiffProvider>
  );
}

function DiffProvider({ bluprint, on, onOff, children }: { bluprint: string; on: boolean; onOff: () => void; children: React.ReactNode }) {
  const [range, setR] = useState<{ from?: string; to?: string; review?: string }>({});
  const [commits, setCommits] = useState<Commit[]>([]);
  const [listed, setListed] = useState(false);
  // Nothing asked for is the newest commit, as a history opens (D76) — read
  // here, so the panel, the bar and the bluprint all mean the same change.
  const idle = !range.from && !range.to && !range.review;
  const newest = commits[0];
  const shown = idle && newest ? { from: `${newest.sha}~1`, to: newest.sha } : range;
  /**
   * The answer and the question it answers, in one piece of state. `loading` is
   * then derived — whether the answer in hand is for the comparison being
   * asked about — rather than a second flag set from inside the effect, which
   * is the cascading render `react-hooks/set-state-in-effect` is about and
   * which `useInstalled` (components/agent/agents.tsx) avoids the same way.
   */
  const [got, setGot] = useState<{ q: string; diff?: BluprintDiff; error?: string }>();
  const q = new URLSearchParams({ bluprint });
  if (shown.from) q.set("from", shown.from);
  if (shown.to) q.set("to", shown.to);
  if (range.review) q.set("review", range.review);
  const asked = q.toString();
  const [again, setAgain] = useState(0);

  useEffect(() => {
    // Nothing is cleared on the way out: `value` below hands out null while
    // off, so the last answer is simply not read, and turning the mode back on
    // re-fetches over it.
    // Idle, it waits for the list that names the newest commit.
    if (!on || (idle && !listed)) return;
    let live = true;
    fetch(`/api/diff?${asked}`)
      .then((r) => r.json())
      .then((j) => live && setGot(j.error ? { q: asked, error: j.error } : { q: asked, diff: j as BluprintDiff }))
      .catch(() => live && setGot({ q: asked, error: "Could not read the checkout." }));
    return () => {
      live = false;
    };
  }, [on, asked, again, idle, listed]);

  useEffect(() => {
    if (!on || listed) return;
    let live = true;
    fetch(`/api/diff?bluprint=${encodeURIComponent(bluprint)}&commits=1`)
      .then((r) => r.json())
      .then((j) => live && setCommits(j.commits ?? []))
      .catch(() => {})
      .finally(() => live && setListed(true));
    return () => {
      live = false;
    };
  }, [bluprint, on, listed]);

  const setRange = useCallback((from?: string, to?: string) => setR({ from, to }), []);
  const setReview = useCallback((review?: string) => setR({ review }), []);
  const reload = useCallback(() => setAgain((n) => n + 1), []);
  useEffect(() => {
    const on = (e: Event) => setR({ review: (e as CustomEvent<string>).detail });
    window.addEventListener(OPEN_REVIEW, on);
    return () => window.removeEventListener(OPEN_REVIEW, on);
  }, []);
  const here = got?.q === asked ? got : undefined;
  const value = useMemo<DiffState>(
    () => ({ diff: on ? (here?.diff ?? null) : null, loading: on && !here, error: here?.error, ...range, from: shown.from, to: shown.to, commits, setRange, setReview, reload, off: onOff }),
    [on, here, range, shown.from, shown.to, commits, setRange, setReview, reload, onOff],
  );
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

/** A verdict as a word in its own colours. */
function Pill({ verdict, children }: { verdict: Exclude<Verdict, "untouched">; children: React.ReactNode }) {
  const t = TINT[verdict];
  return (
    <span
      className=" border px-2 py-[3px] font-mono text-[10.5px] leading-none"
      style={{ color: t.ink, background: t.surface, borderColor: t.line }}
    >
      {children}
    </span>
  );
}

/**
 * A file's hunks as the code pane draws code (components/bluprint/source-view.tsx
 * `SourceView`): real line numbers, old and new, and the code coloured by
 * lib/client/highlight.ts. Each line is coloured on its own, so a block comment
 * spanning a hunk boundary reads as code; that is the price of drawing only
 * what changed.
 */
export function Hunks({ file, only }: { file: FileChange; only?: (h: HunkLines) => boolean }) {
  const hunks = useMemo(() => hunksOf(file.diff).filter((h) => !only || only(h)), [file.diff, only]);
  const lang = langOf(file.path);
  if (!hunks.length) return <p className="px-1 py-1 text-[12px] text-muted-slate">No lines to show: the file is binary, or only its mode changed.</p>;
  const BG = { "+": TINT.added.surface, "-": TINT.removed.surface, " ": undefined };
  return (
    <div className="mt-1 overflow-x-auto border border-border-gray bg-code">
      <pre className="min-w-full font-mono text-[12px] leading-[1.6]">
        {hunks.map((h, i) => (
          <div key={i} className={cn(i > 0 && "border-t border-border-gray")}>
            <div className="sticky left-0 px-3 py-0.5 text-[10.5px] text-faint">
              line {h.newStart}
            </div>
            {h.lines.map((l, j) => (
              <div key={j} className="flex" style={{ background: BG[l.kind] }}>
                <span className="tnum w-9 shrink-0 select-none pr-1.5 text-right text-faint">{l.old ?? ""}</span>
                <span className="tnum w-9 shrink-0 select-none border-r border-border-gray pr-1.5 text-right text-faint">{l.new ?? ""}</span>
                <span
                  className="w-4 shrink-0 select-none text-center"
                  style={{ color: l.kind === "+" ? TINT.added.ink : l.kind === "-" ? TINT.removed.ink : undefined }}
                >
                  {l.kind === " " ? "" : l.kind === "+" ? "+" : "−"}
                </span>
                <code className="whitespace-pre pr-4 text-code-plain">
                  {l.text
                    ? highlight(l.text, lang)[0].map((t, k) => (
                        <span key={k} style={{ color: TOKEN_COLOR[t.kind] }}>
                          {t.text}
                        </span>
                      ))
                    : " "}
                </code>
              </div>
            ))}
          </div>
        ))}
      </pre>
    </div>
  );
}

/* ── a section card, tinted ──────────────────────────────────── */

/**
 * Wraps a card or row the canvas already drew. `untouched` returns the child
 * untouched — a diff that restyled every card would make the three that moved
 * harder to find, not easier.
 */
export function SectionTint({ path, children }: { path: string[]; children: React.ReactNode }) {
  const verdict = useVerdict(path);
  if (verdict === "untouched") return children;
  const t = TINT[verdict];
  return (
    <div className="relative" style={{ background: t.surface, boxShadow: `inset 0 0 0 1.5px ${t.line}` }}>
      <span
        className="absolute -top-2 left-3 z-10 border px-1.5 py-[2px] font-mono text-[9.5px] uppercase leading-none tracking-[0.08em]"
        style={{ color: t.ink, background: t.surface, borderColor: t.line }}
      >
        {WORD[verdict]}
      </span>
      {/* Struck, not hidden: the reader has to be able to read what went. */}
      <div className={cn(verdict === "removed" && "opacity-70 [&_*]:line-through")}>{children}</div>
    </div>
  );
}

/**
 * The sections this level had and no longer does, listed under its own cards.
 * Nothing else on the page can show these — they are not in the tree any more
 * — so without this the one verdict a reviewer most needs is the one that
 * cannot be rendered.
 */
export function RemovedSections({ path }: { path: string[] }) {
  const d = useDiff();
  const here = (d?.diff?.sections ?? []).filter((s) => s.verdict === "removed" && s.path.length === path.length + 1 && s.path.slice(0, -1).join("/") === path.join("/"));
  if (!here.length) return null;
  const t = TINT.removed;
  return (
    <div className="mt-4 space-y-2">
      {here.map((s) => (
        <div
          key={s.id}
          className=" border px-4 py-3"
          style={{ background: t.surface, borderColor: t.line }}
        >
          <span className="flex items-center gap-2">
            <span className="truncate text-[15px] font-semibold tracking-[-0.01em] line-through" style={{ color: t.ink }}>
              {s.title}
            </span>
            <Pill verdict="removed">gone</Pill>
          </span>
          {s.files.length ? (
            <span className="mt-1 block font-mono text-[11px] text-muted-slate">{s.files.map((f) => f.path).join(", ")}</span>
          ) : null}
        </div>
      ))}
    </div>
  );
}

/* ── a block, in two colours ─────────────────────────────────── */

/**
 * One block, diffed. Returns null where this block did not move, so the level
 * goes on rendering its own — the diff only ever replaces what it has
 * something to say about.
 */
export function BlockDiffView({ block, diff }: { block: Anatomy; diff: BlockDiff }) {
  if (diff.boxes && block.kind === "diagram") return <DiagramDiff block={block} boxes={diff.boxes} arrows={diff.arrows ?? []} />;
  if (diff.rows) return <RowsDiff kind={diff.kind} rows={diff.rows} block={block} />;
  return <Replaced verdict={diff.verdict} kind={diff.kind} />;
}

function Replaced({ verdict, kind }: { verdict: Verdict; kind: string }) {
  if (verdict === "untouched") return null;
  return (
    <p className="text-[12.5px] text-on-surface-variant">
      <Pill verdict={verdict as Exclude<Verdict, "untouched">}>{WORD[verdict]}</Pill>{" "}
      <span className="font-mono text-[11.5px]">{kind}</span> block
    </p>
  );
}

/**
 * A `schema` or `table`, row-wise: the dropped column red and struck, the new
 * ones green, in place among the ones that stayed. One table, not two side by
 * side — a reader comparing two tables is doing the diff themselves, which is
 * the work this is meant to have already done.
 */
function RowsDiff({ kind, rows, block }: { kind: Anatomy["kind"]; rows: RowDiff[]; block: Anatomy }) {
  const columns =
    block.kind === "schema"
      ? ["column", "type", "key", "null", "note"]
      : block.kind === "table"
        ? block.columns
        : null;
  const title = block.kind === "schema" ? block.table : block.kind === "table" ? block.caption : undefined;
  return (
    <div className="min-w-0">
      {title ? <p className="mb-2.5 font-mono text-[12.5px] font-semibold text-ink">{title}</p> : null}
      <div className="overflow-x-auto border border-border-gray bg-card">
        <table className="w-full border-collapse text-left text-[13px]">
          {columns ? (
            <thead>
              <tr className="border-b border-border-gray bg-surface">
                <th className="w-7 px-2 py-2" />
                {columns.map((c) => (
                  <th key={c} className="px-3 py-2 font-mono text-[10.5px] font-medium uppercase tracking-[0.07em] text-faint">
                    {c}
                  </th>
                ))}
              </tr>
            </thead>
          ) : null}
          <tbody>
            {rows.map((r, i) => {
              const t = r.verdict === "untouched" ? null : TINT[r.verdict];
              // A removed row shows what it was; everything else shows what it
              // is now, with the old cells kept beside a changed one.
              const cells = r.verdict === "removed" ? (r.before ?? []) : (r.after ?? r.before ?? []);
              return (
                <tr key={`${r.key}-${i}`} className="border-b border-border-gray last:border-0" style={t ? { background: t.surface } : undefined}>
                  <td className="px-2 py-2 align-top font-mono text-[12px] leading-snug" style={t ? { color: t.ink } : undefined}>
                    {t?.mark}
                  </td>
                  {cells.map((cell, j) => (
                    <td
                      key={j}
                      className={cn("px-3 py-2 align-top leading-snug", r.verdict === "removed" && "line-through", j === 0 && "font-medium")}
                      style={t ? { color: t.ink } : undefined}
                    >
                      {cell}
                      {/* Only a changed cell carries its old value, right where
                          the reader is already looking. */}
                      {r.verdict === "changed" && r.before?.[j] !== undefined && r.before[j] !== cell ? (
                        <span className="ml-2 line-through" style={{ color: TINT.removed.ink }}>
                          {r.before[j]}
                        </span>
                      ) : null}
                    </td>
                  ))}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <p className="mt-2 font-mono text-[10.5px] text-faint">{kind} · red went, green arrived</p>
    </div>
  );
}

/**
 * The picture, diffed: the boxes a commit took out in red, the ones it added
 * in green, on ONE diagram. Both sets are laid out together — a box that is
 * gone keeps its place in the grid, so a changed database architecture reads
 * as the old shape fading out of the new one rather than as two pictures the
 * reader has to align by eye.
 *
 * Fills and strokes are inline `var()`, which is exactly why the diff tokens
 * are declared outside `@theme` (app/globals.css).
 */
export function DiagramDiff({
  block,
  boxes,
  arrows,
  legend = "red went, green arrived",
}: {
  block: Extract<Anatomy, { kind: "diagram" }>;
  boxes: PartDiff[];
  arrows: PartDiff[];
  /** What the colours mean here: a plan's are still to come (components/agent/plan.tsx). */
  legend?: string;
}) {
  const verdictOf = new Map(boxes.map((b) => [b.key, b.verdict]));
  const arrowOf = new Map(arrows.map((a) => [a.key, a.verdict]));
  // Boxes only the other side has are not in this block — added ones when it
  // is the `from` side's (a plan), gone ones when it is the `to` side's (the
  // bluprint on screen) — so they are placed after the ones that are, on a row of
  // their own. Arrows the other side had between boxes now drawn come back
  // the same way, so a dropped hand-off is a red line where it used to run.
  const extra = boxes.filter((b) => b.verdict !== "untouched" && !block.boxes.some((x) => x.id === b.key));
  const row = Math.max(0, ...block.boxes.map((b) => b.row)) + 1;
  const ids = new Set([...block.boxes.map((b) => b.id), ...extra.map((b) => b.key)]);
  const lost = arrows
    .filter((a) => a.verdict !== "untouched" && !block.arrows.some((x) => `${x.from}→${x.to}` === a.key))
    .map((a) => ({ from: a.key.split("→")[0], to: a.key.split("→")[1], label: a.label }))
    .filter((a) => ids.has(a.from) && ids.has(a.to));
  const whole: Extract<Anatomy, { kind: "diagram" }> = {
    ...block,
    boxes: [...block.boxes, ...extra.map((b, i) => ({ id: b.key, label: b.label ?? b.key, col: i, row }))],
    arrows: [...block.arrows, ...lost],
  };
  const { W, H, boxes: placed, arrows: drawn } = layoutDiagram(whole);

  return (
    <figure className="min-w-0">
      <figcaption className="mb-3 max-w-[1000px]">
        <span className="text-[14px] font-medium text-on-surface">{block.caption}</span>
        <span className="ml-2.5 whitespace-nowrap font-mono text-[10.5px] text-faint">{legend}</span>
      </figcaption>
      <div className="overflow-x-auto">
        <svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label={`${block.caption} — what changed`} className="block h-auto" style={{ width: "100%", maxWidth: W * 1.35, minWidth: W * 0.7 }}>
          <defs>
            {(["added", "removed", "changed", "untouched"] as const).map((v) => (
              <marker key={v} id={`dd-${v}`} viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
                <path d="M1 1.2L7 4 1 6.8z" fill={v === "untouched" ? "var(--color-wire)" : TINT[v].line} />
              </marker>
            ))}
          </defs>
          {/* `from`/`to` and not the index: the layout collapses two arrows
              between the same pair into one line, so positions do not line up
              with `block.arrows`. */}
          {drawn.map(({ d, label, from, to }, i) => {
            const v = arrowOf.get(`${from}→${to}`) ?? "untouched";
            const t = v === "untouched" ? null : TINT[v];
            return (
              <g key={i} opacity={v === "untouched" ? 0.45 : 1}>
                <path
                  d={d}
                  fill="none"
                  stroke={t?.line ?? "var(--color-wire)"}
                  strokeWidth={t ? 2 : 1.5}
                  strokeDasharray={v === "removed" ? "5 4" : undefined}
                  markerEnd={`url(#dd-${v})`}
                />
                {label ? (
                  <text
                    x={label.x}
                    y={label.y}
                    textAnchor={label.anchor}
                    fontSize="12"
                    fill={t?.ink ?? "var(--color-muted-slate)"}
                    stroke="var(--color-paper)"
                    strokeWidth="4"
                    strokeLinejoin="round"
                    paintOrder="stroke"
                  >
                    {label.text}
                  </text>
                ) : null}
              </g>
            );
          })}
          {placed.map(({ x, y, w, b }) => {
            const v = verdictOf.get(b.id) ?? "untouched";
            const t = v === "untouched" ? null : TINT[v];
            return (
              <g key={b.id} opacity={v === "untouched" ? 0.5 : 1}>
                <rect
                  x={x}
                  y={y}
                  width={w}
                  height={BOX_H}
                  rx="3"
                  fill={t?.surface ?? "var(--color-card)"}
                  stroke={t?.line ?? "var(--color-border-strong)"}
                  strokeWidth={t ? 2 : 1.5}
                  strokeDasharray={v === "removed" ? "5 4" : undefined}
                />
                <text
                  x={x + w / 2}
                  y={b.sub ? y + 26 : y + BOX_H / 2 + 6}
                  textAnchor="middle"
                  fontFamily="var(--font-display), Georgia, serif"
                  fontSize="18"
                  letterSpacing="-0.01em"
                  fill={t?.ink ?? "var(--color-ink)"}
                  textDecoration={v === "removed" ? "line-through" : undefined}
                >
                  {b.label}
                </text>
                {b.sub ? (
                  <text x={x + w / 2} y={y + 43} textAnchor="middle" fontSize="12" fill="var(--color-faint)">
                    {b.sub}
                  </text>
                ) : null}
                {t ? (
                  <text x={x + w - 11} y={y + 18} textAnchor="middle" fontSize="15" fontWeight="700" fill={t.ink}>
                    {t.mark}
                  </text>
                ) : null}
              </g>
            );
          })}
        </svg>
      </div>
    </figure>
  );
}

app/components/review/keep.tsx:
"use client";

import { Button } from "@/components/ui/button";
import { useCallback, useEffect, useRef, useState } from "react";
import { AgentIcon, CLAUDE } from "@/components/agent/agents";
import { ExplainedBlock, isExplained } from "@/components/bluprint/blocks";
import { DIALOG, Field, INPUT, Overlay, PRIMARY, QUIET } from "@/components/ui/dialog";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { Prose } from "@/components/ui/state";
import { ask, section } from "@/lib/agent/context";
import { draftPrompt, parseBlock, revisePrompt, type Exchange } from "@/lib/agent/keep";
import { cn } from "@/lib/client/utils";
import type { Anatomy, Origin } from "@/lib/bluprint/schema";
import { useDesktop } from "@/lib/client/platform";

/**
 * Keeping an answer: it adds something the bluprint never knew, marked as the
 * reader's (lib/server/overlay.ts).
 *
 * Desktop only. It needs a Claude tab, and the tabs are the desktop app's.
 */


/* ── the turn just finished ───────────────────────────────────── */

/** The last answer Claude gave in any tab, offered once (src-tauri/src/pty.rs). */
const ANSWERED = "bluprint:answered";

export const announceAnswer = (e: Exchange) =>
  window.dispatchEvent(new CustomEvent<Exchange>(ANSWERED, { detail: e }));

export function onAnswer(f: (e: Exchange) => void) {
  const on = (ev: Event) => f((ev as CustomEvent<Exchange>).detail);
  window.addEventListener(ANSWERED, on);
  return () => window.removeEventListener(ANSWERED, on);
}

/**
 * The reply Claude gave to a drafting prompt, from the same place. True when a
 * waiting dialog took it — it cancels the event — so it is not also an answer.
 */
const DRAFTED = "bluprint:drafted";
export const announceDraft = (said: string) =>
  !window.dispatchEvent(new CustomEvent<string>(DRAFTED, { detail: said, cancelable: true }));
const onDraft = (f: (said: string) => boolean) => {
  const on = (ev: Event) => {
    if (f((ev as CustomEvent<string>).detail)) ev.preventDefault();
  };
  window.addEventListener(DRAFTED, on);
  return () => window.removeEventListener(DRAFTED, on);
};

/* ── keep an answer ───────────────────────────────────────────── */

type Stage =
  | { at: "asking" }
  | { at: "drafting" }
  | { at: "preview"; block: Anatomy }
  | { at: "failed"; why: string };

/**
 * Offered after Claude answers: turn that answer into a block, look at it, and
 * keep it. The draft goes through the tab the reader is already talking to, so
 * nothing here holds a key or calls an API.
 */
function KeepAnswer({
  exchange,
  path,
  onClose,
}: {
  exchange: Exchange;
  path: string[];
  onClose: () => void;
}) {
  const bluprint = useBluprint();
  const where = path.length ? (bluprint.nodeAt(path)?.title ?? bluprint.RUN.repo) : bluprint.RUN.repo;
  const [stage, setStage] = useState<Stage>({ at: "asking" });
  const [changes, setChanges] = useState("");
  const [saving, setSaving] = useState(false);
  // The draft reply arrives on a window event from the workspace's poll, and
  // only the request we are waiting on should be taken.
  const waiting = useRef(false);

  useEffect(
    () =>
      onDraft((said) => {
        if (!waiting.current) return false;
        waiting.current = false;
        const r = parseBlock(said);
        setStage("block" in r ? { at: "preview", block: r.block } : { at: "failed", why: r.error });
        return true;
      }),
    [],
  );

  const send = useCallback((text: string) => {
    waiting.current = true;
    setStage({ at: "drafting" });
    ask(section(bluprint, path), text);
  }, [bluprint, path]);

  async function keep() {
    if (stage.at !== "preview") return;
    setSaving(true);
    const origin: Origin = { by: "claude", at: new Date().toISOString(), note: exchange.asked || undefined };
    // A note carries its own origin; every other kind wears the section's.
    const block = stage.block.kind === "note" ? { ...stage.block, origin } : stage.block;
    const res = await fetch("/api/overlay", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ action: "add", bluprint: bluprint.name, kind: "block", path, block, origin }),
    }).catch(() => null);
    setSaving(false);
    if (!res?.ok) {
      setStage({ at: "failed", why: "That could not be saved to this project." });
      return;
    }
    onClose();
    // The bluprint is read on the server, so the level redraws from the overlay.
    window.location.reload();
  }

  return (
    <Overlay onClose={onClose}>
      <div className={cn(DIALOG, "max-w-[720px]")}>
        <header className="border-b border-border-gray px-5 py-3.5">
          <h2 className="text-[15px] font-semibold text-ink">Keep this on the bluprint</h2>
          <p className="mt-0.5 text-[12px] text-muted-slate">
            It goes on <span className="font-medium text-ink">{where}</span>, marked as yours — not as something read
            from the code.
          </p>
        </header>

        <div className="min-h-0 flex-1 overflow-auto px-5 py-4">
          {stage.at === "asking" ? (
            <>
              <div className="mb-4 border border-border-gray bg-surface-container-low px-3.5 py-3">
                <p className="mb-1.5 font-mono text-[10.5px] uppercase tracking-[0.09em] text-faint">What Claude said</p>
                <div className="max-h-[260px] overflow-auto whitespace-pre-wrap text-[13px] leading-[1.6] text-on-surface-variant">
                  <Prose text={exchange.said} />
                </div>
              </div>
              <button type="button" className={PRIMARY} onClick={() => send(draftPrompt(where))}>
                Draw it as a block
              </button>
              <p className="mt-2 text-[12px] text-muted-slate">
                Claude picks the shape that fits — a picture, a table, or a note where sentences really are the answer.
              </p>
            </>
          ) : null}

          {stage.at === "drafting" ? (
            <p className="flex items-center gap-2 py-6 text-[13px] text-amber-ink">
              <AgentIcon id={CLAUDE.id} />◷ Drawing it…
            </p>
          ) : null}

          {stage.at === "preview" ? (
            <>
              <p className="mb-2.5 font-mono text-[10.5px] uppercase tracking-[0.09em] text-faint">
                How it will look on the level
              </p>
              <div className="mb-4 border border-border-gray px-4 py-4">
                {isExplained(stage.block) ? (
                  <ExplainedBlock block={stage.block} />
                ) : (
                  <p className="text-[13px] text-clay-ink">This kind cannot be drawn here.</p>
                )}
              </div>
              <Field label="Not quite right?" hint="Say what to change and Claude redraws it.">
                <input
                  className={INPUT}
                  value={changes}
                  placeholder="drop the last box, it is not real"
                  onChange={(e) => setChanges(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key !== "Enter" || !changes.trim()) return;
                    send(revisePrompt(stage.block, changes.trim()));
                    setChanges("");
                  }}
                />
              </Field>
            </>
          ) : null}

          {stage.at === "failed" ? <p className="py-4 text-[13px] text-clay-ink">{stage.why}</p> : null}
        </div>

        <footer className="flex items-center justify-end gap-1.5 border-t border-border-gray px-5 py-3">
          <button type="button" className={QUIET} onClick={onClose}>
            {stage.at === "preview" ? "Discard" : "Close"}
          </button>
          {stage.at === "preview" ? (
            <button type="button" className={PRIMARY} disabled={saving} onClick={keep}>
              {saving ? "Keeping…" : "Keep it"}
            </button>
          ) : null}
        </footer>
      </div>
    </Overlay>
  );
}

/** The button on a level's header that keeps Claude's last answer. Desktop only, and only for a project. */
export function FixAndKeep({ path, answer }: { path: string[]; answer: Exchange | null }) {
  const desktop = useDesktop();
  const [open, setOpen] = useState(false);
  if (!desktop) return null;
  return (
    <>
      {answer ? (
        <Button onClick={() => setOpen(true)} icon={<AgentIcon id={CLAUDE.id} />} title="Turn Claude's last answer into a block on this level">
          Keep the answer
        </Button>
      ) : null}
      {open && answer ? <KeepAnswer exchange={answer} path={path} onClose={() => setOpen(false)} /> : null}
    </>
  );
}

app/components/review/review-tray.tsx:
"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { addNote, clearSent, dropNote, editNote, reviewFor, sendNow, sendReview, stopEditing, useEditing, useNotes, type Editing, type Note } from "@/lib/agent/notes";
import { keys } from "@/components/ui/button";
import { PRIMARY, QUIET } from "@/components/ui/dialog";
import { cn } from "@/lib/client/utils";
import { useDesktop, useMac } from "@/lib/client/platform";
import { GAP, STATUSBAR } from "@/lib/client/layout";

/**
 * The review: notes left on the bluprint, in a diff or in the code (lib/agent/notes.ts),
 * gathered in a tray in the corner until they go to Claude as one turn. Also
 * the editor a note is written in, opened at the pointer from any right-click
 * menu. Above the history panel, so a hunk can be commented on while it is in
 * view. In the desktop app only, where Claude runs.
 */

/** A field to write a note in. */
const FIELD = "w-full border border-border-gray bg-card px-2 py-1.5 text-[12.5px] text-ink outline-none placeholder:text-faint focus:border-accent";

export function ReviewTray() {
  const { name } = useBluprint();
  const desktop = useDesktop();
  useEffect(() => reviewFor(name), [name]);
  const notes = useNotes();
  const editing = useEditing();
  if (!desktop) return null;
  return (
    <>
      {editing ? <NoteEditor key={`${editing.anchor.key}:${editing.kind}`} e={editing} /> : null}
      {notes.length ? <Tray notes={notes} /> : null}
    </>
  );
}

function Tray({ notes }: { notes: Note[] }) {
  const [extra, setExtra] = useState("");
  const [folded, setFolded] = useState(false);
  const drafts = notes.filter((n) => n.status === "draft");
  const sending = notes.some((n) => n.status === "sending");
  const sent = notes.filter((n) => n.status === "sent");
  return (
    <section
      aria-label="Review"
      data-chrome
      style={{ bottom: STATUSBAR + GAP, left: GAP }}
      className="fixed z-[60] flex max-h-[min(460px,60vh)] w-[340px] flex-col overflow-hidden border border-border-gray bg-card shadow-lift"
    >
      <header className="flex shrink-0 items-center gap-2 border-b border-border-gray px-3 py-2">
        <button type="button" onClick={() => setFolded((f) => !f)} className="flex min-w-0 flex-1 cursor-pointer items-center gap-1.5 text-left">
          <span className="text-[10px] text-faint">{folded ? "▸" : "▾"}</span>
          <span className="text-[13px] font-semibold text-ink">Review</span>
          <span className="text-[12px] text-muted-slate">
            {drafts.length ? `${drafts.length} note${drafts.length === 1 ? "" : "s"}` : sending ? "sending" : "sent"}
          </span>
        </button>
        {sent.length && !sending ? (
          <button type="button" onClick={clearSent} className="shrink-0 cursor-pointer text-[11.5px] text-faint hover:text-ink">
            clear sent
          </button>
        ) : null}
      </header>
      {folded ? null : (
        <>
          <ol className="min-h-0 flex-1 overflow-y-auto">
            {notes.map((n) => (
              <NoteRow key={n.id} n={n} />
            ))}
          </ol>
          {drafts.length || sending ? (
            <div className="flex shrink-0 flex-col gap-2 border-t border-border-gray p-2.5">
              {sending ? (
                <div className="flex items-center gap-2 text-[12px] text-muted-slate">
                  <span className="min-w-0 flex-1">Waiting for Claude to finish its turn…</span>
                  <button type="button" onClick={sendNow} className="shrink-0 cursor-pointer text-accent hover:underline">
                    Send now
                  </button>
                </div>
              ) : (
                <>
                  <textarea
                    value={extra}
                    onChange={(e) => setExtra(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
                        e.preventDefault();
                        void sendReview(extra).then(() => setExtra(""));
                      }
                    }}
                    rows={2}
                    placeholder="Anything else for Claude… (optional)"
                    className={cn(FIELD, "resize-none")}
                  />
                  <button
                    type="button"
                    onClick={() => void sendReview(extra).then(() => setExtra(""))}
                    title="Sends every note to Claude as one turn, once it has finished the one it is on"
                    className={cn(PRIMARY, "justify-center")}
                  >
                    Send review to Claude
                  </button>
                </>
              )}
            </div>
          ) : null}
        </>
      )}
    </section>
  );
}

function NoteRow({ n }: { n: Note }) {
  const draft = n.status === "draft";
  const [open, setOpen] = useState(false);
  return (
    <li className={cn("group border-b border-border-gray px-3 py-2 last:border-b-0", !draft && "opacity-60")}>
      <div className="flex items-start gap-2">
        <span
          className={cn(
            "mt-px shrink-0 px-1 font-mono text-[10px] uppercase",
            n.kind === "suggest" ? "bg-accent/12 text-accent" : "bg-surface-container text-muted-slate",
          )}
        >
          {n.kind === "suggest" ? "edit" : "note"}
        </span>
        <button
          type="button"
          onClick={() => draft && setOpen((o) => !o)}
          className={cn("min-w-0 flex-1 text-left", draft && "cursor-pointer")}
          title={draft ? "Edit this note" : undefined}
        >
          <p className="truncate text-[11.5px] text-faint">{n.anchor.title}</p>
          {n.kind === "suggest" ? (
            <p className="text-[12.5px] leading-snug">
              <del className="text-muted-slate">{n.before}</del> <ins className="text-ink no-underline">{n.after}</ins>
            </p>
          ) : null}
          {n.note.trim() ? <p className="whitespace-pre-line text-[12.5px] leading-snug text-ink">{n.note}</p> : null}
        </button>
        <span className="shrink-0 text-[11px] text-faint">{n.status === "sending" ? "◷" : n.status === "sent" ? "✓" : null}</span>
        {draft ? (
          <button
            type="button"
            aria-label={`Remove the note on ${n.anchor.title}`}
            onClick={() => dropNote(n.id)}
            className="shrink-0 cursor-pointer text-faint opacity-0 hover:text-ink focus-visible:opacity-100 group-hover:opacity-100"
          >
            ×
          </button>
        ) : null}
      </div>
      {open && draft ? (
        <div className="mt-1.5 flex flex-col gap-1.5">
          {n.kind === "suggest" ? (
            <textarea
              value={n.after ?? ""}
              onChange={(e) => editNote(n.id, { after: e.target.value })}
              rows={2}
              className={cn(FIELD, "resize-none py-1")}
            />
          ) : null}
          <textarea
            value={n.note}
            onChange={(e) => editNote(n.id, { note: e.target.value })}
            rows={2}
            placeholder={n.kind === "suggest" ? "Why, or anything else (optional)" : "Your comment"}
            className={cn(FIELD, "resize-none py-1")}
          />
        </div>
      ) : null}
    </li>
  );
}

/**
 * Writing one note, at the pointer. A comment is one field; a suggestion
 * starts from the words on screen, to be rewritten, and can say why.
 * ⌘/Ctrl+Enter adds it, Escape lets it go.
 */
function NoteEditor({ e }: { e: Editing }) {
  const suggest = e.kind === "suggest";
  const [after, setAfter] = useState(e.before ?? "");
  const [note, setNote] = useState("");
  const ref = useRef<HTMLDivElement>(null);
  const first = useRef<HTMLTextAreaElement>(null);
  const [at, setAt] = useState({ x: e.x, y: e.y });
  useLayoutEffect(() => {
    const box = ref.current?.getBoundingClientRect();
    if (box)
      setAt({
        x: Math.max(4, Math.min(e.x, window.innerWidth - box.width - 4)),
        y: Math.max(4, Math.min(e.y, window.innerHeight - box.height - 4)),
      });
    first.current?.focus();
    if (suggest) first.current?.select();
  }, [e.x, e.y, suggest]);

  const ready = suggest ? after.trim() !== (e.before ?? "").trim() || note.trim() !== "" : note.trim() !== "";
  const add = () => {
    if (!ready) return;
    addNote({ kind: e.kind, anchor: e.anchor, note, ...(suggest ? { before: e.before, after } : {}) });
  };
  const onKey = (k: React.KeyboardEvent) => {
    if (k.key === "Escape") {
      k.stopPropagation();
      stopEditing();
    } else if (k.key === "Enter" && (k.metaKey || k.ctrlKey)) {
      k.preventDefault();
      add();
    }
  };
  const field = cn(FIELD, "resize-y");
  const mac = useMac();

  return (
    <div
      ref={ref}
      role="dialog"
      aria-label={suggest ? "Suggest an edit" : "Comment"}
      data-chrome
      data-note-editor
      onKeyDown={onKey}
      style={{ left: at.x, top: at.y }}
      className="fixed z-[70] flex w-[340px] flex-col gap-2 border border-border-gray bg-card p-3 shadow-lift"
    >
      <p className="truncate text-[11.5px] text-faint">
        {suggest ? "Suggest an edit to" : "Comment on"} <span className="text-ink">{e.anchor.title}</span>
      </p>
      {suggest ? (
        <>
          <p className="max-h-20 overflow-y-auto text-[12px] leading-snug text-muted-slate line-through">{e.before}</p>
          <textarea ref={first} value={after} onChange={(x) => setAfter(x.target.value)} rows={3} className={field} />
          <textarea value={note} onChange={(x) => setNote(x.target.value)} rows={1} placeholder="Why (optional)" className={field} />
        </>
      ) : (
        <textarea
          ref={first}
          value={note}
          onChange={(x) => setNote(x.target.value)}
          rows={3}
          placeholder="What should change here?"
          className={field}
        />
      )}
      <div className="flex items-center justify-end gap-2">
        <span className="mr-auto text-[11px] text-faint">{keys(mac, mac ? "↵" : "Enter")} to add</span>
        <button type="button" onClick={stopEditing} className={QUIET}>
          Cancel
        </button>
        <button
          type="button"
          disabled={!ready}
          onClick={add}
          className={PRIMARY}
        >
          Add to review
        </button>
      </div>
    </div>
  );
}

app/components/review/reviews.tsx:
"use client";

import { useEffect, useState } from "react";
import { undoTurn } from "@/lib/agent/undo";
import { cn } from "@/lib/client/utils";
import type { BluprintDiff } from "@/lib/server/diff";
import type { Branch, Pull, Review } from "@/lib/server/review";
import { claudePath } from "@/lib/client/claude";
import { ago } from "@/components/review/ago";

/* ── reviews ─────────────────────────────────────────────────── */

const SELECT =
  "w-full border border-border-gray bg-card px-2 py-1.5 text-[12px] text-ink focus:border-accent focus:outline-none";

/**
 * Something to review as one change: a pull request or a branch, from where
 * it left its base (lib/server/review.ts), or one turn of the agent in the app, as
 * the bluprint saw it before and after (scripts/generate/update.ts).
 */
export function ReviewPicker({ bluprint, value, onPick }: { bluprint: string; value?: string; onPick: (spec?: string) => void }) {
  const [got, setGot] = useState<{ branches: Branch[]; base: string; pulls?: Pull[]; why?: string; turns: { id: string; prompt: string; at: string }[] } | null>(null);
  useEffect(() => {
    let live = true;
    const read = (q: string) => fetch(`/api/diff?bluprint=${encodeURIComponent(bluprint)}&${q}`).then((r) => r.json());
    Promise.all([read("branches=1"), read("turns=1")])
      .then(([b, t]) => live && setGot({ branches: b.branches ?? [], base: b.base ?? "", pulls: b.pulls, why: b.why, turns: t.turns ?? [] }))
      .catch(() => {});
    return () => {
      live = false;
    };
  }, [bluprint]);
  return (
    <>
      <select value={value ?? ""} aria-label="Review a pull request, branch or agent turn" onChange={(e) => onPick(e.target.value || undefined)} className={SELECT}>
        <option value="">{got ? "Review a pull request, branch or turn…" : "Reading branches…"}</option>
        {got?.turns.length ? (
          <optgroup label="What the agent changed, turn by turn">
            {got.turns.map((t) => (
              <option key={t.id} value={`turn:${t.id}`}>
                {ago(t.at)} · {t.prompt.slice(0, 70) || "a correction"}
              </option>
            ))}
          </optgroup>
        ) : null}
        {got?.pulls?.length ? (
          <optgroup label="Pull requests">
            {got.pulls.map((p) => (
              <option key={p.number} value={`pr:${p.number}`}>
                #{p.number} {p.title.slice(0, 70)} — {p.author}
              </option>
            ))}
          </optgroup>
        ) : null}
        {got?.branches.length ? (
          <optgroup label={`Branches, since they left ${got.base}`}>
            {got.branches
              .filter((b) => b.name !== got.base)
              .map((b) => (
                <option key={b.name} value={`${got.base}...${b.name}`}>
                  {b.name}
                </option>
              ))}
          </optgroup>
        ) : null}
      </select>
      {got?.why ? <p className="mt-1 text-[11px] leading-snug text-faint">{got.why}</p> : null}
    </>
  );
}

/** What is under review: the pull request as its author described it, the branch and its base, or the turn's prompt. */
export function ReviewCard({ r, bluprint, spec, onMade }: { r: Review; bluprint: string; spec?: string; onMade: () => void }) {
  return (
    <div className="mt-3 border border-border-gray px-3 py-2">
      {r.kind !== "turn" && spec ? <BluprintAfter key={spec} bluprint={bluprint} spec={spec} commit={r.to} pr={r.kind === "pr"} onMade={onMade} /> : null}
      {r.kind === "pr" ? (
        <>
          <p className="text-[13px] font-semibold text-ink">
            #{r.number} {r.title}
          </p>
          <p className="mt-0.5 text-[11.5px] text-muted-slate">
            {r.author ? `${r.author} wants to merge ` : "Merging "}
            <span className="font-mono">{r.head}</span> into <span className="font-mono">{r.base}</span>
            {r.url ? (
              <>
                {" · "}
                <a href={r.url} target="_blank" rel="noreferrer" className="text-accent hover:underline">
                  on GitHub
                </a>
              </>
            ) : null}
          </p>
          {r.body ? <p className="mt-1 line-clamp-3 whitespace-pre-line text-[12px] leading-snug text-on-surface-variant">{r.body}</p> : null}
        </>
      ) : r.kind === "turn" ? (
        <>
          <p className="text-[12.5px] text-ink">
            The agent, asked: <span className="italic">{r.title || "to correct the bluprint"}</span>
            <span className="ml-1.5 text-[11.5px] text-muted-slate">· the bluprint before and after it</span>
          </p>
          {spec ? <UndoTurn key={spec} bluprint={bluprint} turn={spec.slice(5)} onUndone={onMade} /> : null}
        </>
      ) : (
        <p className="text-[12.5px] text-ink">
          What <span className="font-mono">{r.head}</span> did since it left <span className="font-mono">{r.base}</span>
          <span className="ml-1.5 font-mono text-[10.5px] text-faint">
            {r.from.slice(0, 7)}…{r.to.slice(0, 7)}
          </span>
        </p>
      )}
    </div>
  );
}

/**
 * Puts back every file the turn edited (lib/agent/undo.ts), after asking once. Only
 * when nothing has touched those files since: otherwise it names them, and
 * changes nothing.
 */
function UndoTurn({ bluprint, turn, onUndone }: { bluprint: string; turn: string; onUndone: () => void }) {
  const [stage, setStage] = useState<"idle" | "confirm" | "busy" | "done">("idle");
  const [said, setSaid] = useState<string | null>(null);
  const go = async () => {
    setStage("busy");
    const r = await undoTurn(bluprint, turn);
    if (r.ok) {
      setStage("done");
      setSaid(`Put back ${r.restored.length} file${r.restored.length === 1 ? "" : "s"}. The bluprint is catching up.`);
      onUndone();
    } else {
      setStage("idle");
      setSaid(
        r.conflicts?.length
          ? `Not undone: changed since this turn — ${r.conflicts.join(", ")}.`
          : r.refused?.length
            ? `Not undone: cannot write ${r.refused.join(", ")}.`
            : (r.error ?? "Not undone."),
      );
    }
  };
  const btn = "cursor-pointer px-2 py-0.5 text-[12px]";
  return (
    <div className="mt-1.5 flex flex-wrap items-center gap-2">
      {stage === "idle" ? (
        <button type="button" onClick={() => setStage("confirm")} className={cn(btn, "border border-border-gray text-ink hover:bg-surface-container-low")}>
          ↶ Undo this turn
        </button>
      ) : stage === "confirm" ? (
        <>
          <span className="text-[12px] text-ink">Put every file this turn edited back as it was?</span>
          <button type="button" onClick={() => void go()} className={cn(btn, "bg-accent text-card hover:opacity-90")}>
            Undo
          </button>
          <button type="button" onClick={() => setStage("idle")} className={cn(btn, "text-muted-slate hover:text-ink")}>
            Cancel
          </button>
        </>
      ) : stage === "busy" ? (
        <span className="text-[12px] text-muted-slate">Undoing…</span>
      ) : null}
      {said ? <span className="text-[11.5px] text-muted-slate">{said}</span> : null}
    </div>
  );
}

/**
 * The bluprint as it would be after the review (app/api/review): until it is made
 * the diff shows which levels the change reaches; once it is, their boxes,
 * arrows and rows diff too. Made only when asked, since it is a paid run.
 */
function BluprintAfter({ bluprint, spec, commit, pr, onMade }: { bluprint: string; spec: string; commit: string; pr: boolean; onMade: () => void }) {
  const [s, setS] = useState<{ status: "none" | "running" | "done" | "failed"; error?: string }>();
  const q = `bluprint=${encodeURIComponent(bluprint)}&commit=${commit}`;
  useEffect(() => {
    if (s && s.status !== "running") return;
    let live = true;
    const t = setTimeout(
      () =>
        fetch(`/api/review?${q}`)
          .then((r) => r.json())
          .then((j) => {
            if (!live) return;
            if (s?.status === "running" && j.status === "done") onMade();
            setS(j);
          })
          .catch(() => {}),
      s ? 4000 : 0,
    );
    return () => {
      live = false;
      clearTimeout(t);
    };
  }, [q, s, onMade]);
  const start = async () => {
    setS({ status: "running" });
    const j = await fetch("/api/review", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ bluprint, review: spec, claude: await claudePath() }),
    })
      .then((r) => r.json())
      .catch(() => ({ status: "failed", error: "Could not start it." }));
    setS(j);
  };
  if (!s) return null;
  return (
    <p className="mb-1.5 flex items-center gap-2 text-[11.5px] text-muted-slate">
      {s.status === "done" ? (
        <span className="text-accent">The bluprint after {pr ? "this PR" : "this branch"} is drawn: its levels diff box by box.</span>
      ) : s.status === "running" ? (
        <span className="text-amber-ink">Making the bluprint of {pr ? "this PR" : "this branch"}… a few minutes</span>
      ) : (
        <>
          <button type="button" onClick={() => void start()} className="cursor-pointer text-accent underline">
            Make the bluprint of {pr ? "this PR" : "this branch"}
          </button>
          <span>to see its new and changed boxes, not only which levels it reaches (an update run)</span>
          {s.error ? <span className="text-clay-ink">{s.error}</span> : null}
        </>
      )}
    </p>
  );
}

/** Changed code no level's lines reach: listed with the level nearest it, never dropped. */
export function Outside({ outside, title, onOpen }: { outside: NonNullable<BluprintDiff["outside"]>; title: (path: string[]) => string; onOpen: (path: string[]) => void }) {
  return (
    <>
      <h3 className="mt-6 text-[12px] font-medium text-muted-slate">Changed where no level&apos;s lines reach</h3>
      <ul className="mt-1.5 flex flex-col gap-1">
        {outside.map((o) => (
          <li key={o.path} className="flex items-baseline gap-2 text-[11.5px]">
            <span className="min-w-0 flex-1 truncate font-mono text-on-surface">{o.path}</span>
            {o.near ? (
              <button type="button" onClick={() => onOpen(o.near!)} className="max-w-[50%] shrink-0 cursor-pointer truncate text-accent hover:underline">
                near {o.near.map((_, i) => title(o.near!.slice(0, i + 1))).join(" › ")}
              </button>
            ) : (
              <span className="shrink-0 text-amber-ink">not on the bluprint yet</span>
            )}
          </li>
        ))}
      </ul>
    </>
  );
}

app/components/review/timeline.tsx:
"use client";

import { useSearchParams } from "next/navigation";
import { useEffect, useMemo, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { goTo } from "@/components/chrome/crumbs";
import { sectionTone } from "@/components/bluprint/blocks";
import { TINT, openDiff, useDiff } from "@/components/review/diff";
import { useBluprint } from "@/components/bluprint/bluprint-context";
import { Eyebrow } from "@/components/ui/state";
import type { Chapter, Story, Timeline as Data, TimelineCommit } from "@/lib/server/history";
import { claudePath } from "@/lib/client/claude";

/** lib/server/history.ts's ELSEWHERE, the row for files no root owns; that file reads git, so it is never imported here. */
const ELSEWHERE = "";

/**
 * How the code got here (D73): every commit, as a dot on the rows of the
 * bluprint's own top-level sections, left to right in time. It takes the level's
 * place while `?timeline` is in the URL, as the docs reader does (D66), so
 * Back and Escape close it and the level it was opened over is still there.
 *
 * It routes, as the diff panel does (D58): a dot opens what that commit did,
 * a dragged span what that stretch did, and a chapter what it covered — each
 * as diff mode on the bluprint, never as a screen of its own (D56).
 */

export function openTimeline() {
  const q = new URLSearchParams(window.location.search);
  // A doc or file open over the level outranks the timeline (components/bluprint/canvas.tsx), so it gives way.
  q.delete("doc");
  q.delete("file");
  q.delete("line");
  q.set("timeline", "");
  window.history.pushState(null, "", `?${q}`);
}

export function closeTimeline() {
  const q = new URLSearchParams(window.location.search);
  q.delete("timeline");
  window.history.pushState(null, "", q.size ? `?${q}` : window.location.pathname);
}

export const useTimelineOpen = () => useSearchParams().has("timeline");

const LABEL_W = 168;
const ROW_H = 30;
const STRIP_H = 34;
const BAND_H = 22;
const AXIS_H = 22;

const day = (iso: string) => new Date(iso).toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
/** A label cut to about `px` wide at 11.5px sans, whole when it fits; the band's tooltip has it all. */
const fit = (text: string, px: number) => {
  const n = Math.floor(px / 6.6);
  return text.length <= n ? text : n < 2 ? "" : `${text.slice(0, n - 1)}…`;
};
const size = (c: TimelineCommit) => Math.sqrt(c.added + c.removed);

export function TimelineView() {
  const { name } = useBluprint();
  const diff = useDiff();
  const [got, setGot] = useState<{ timeline: Data; story: Story | null; telling: boolean } | { error: string } | null>(null);
  const [asked, setAsked] = useState(false);
  const [hover, setHover] = useState<{ c: TimelineCommit; x: number; y: number } | null>(null);
  const [drag, setDrag] = useState<{ a: number; b: number } | null>(null);
  const box = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);

  const telling = (got && "timeline" in got && got.telling) || asked;
  useEffect(() => {
    let live = true;
    const read = () =>
      fetch(`/api/timeline?bluprint=${encodeURIComponent(name)}`)
        .then((r) => r.json())
        .then((j) => {
          if (!live) return;
          setGot(j);
          if (!j.telling) setAsked(false);
        })
        .catch(() => live && setGot({ error: "Could not read the checkout's history." }));
    void read();
    // While the story is told, look again until its chapters land.
    const t = telling ? setInterval(read, 3000) : undefined;
    return () => {
      live = false;
      clearInterval(t);
    };
  }, [name, telling]);

  useEffect(() => {
    if (!box.current) return;
    const ro = new ResizeObserver(([e]) => setWidth(e.contentRect.width));
    ro.observe(box.current);
    return () => ro.disconnect();
  }, [got]);

  const data = got && "timeline" in got ? got.timeline : null;
  const story = got && "timeline" in got && got.story?.chapters.length ? got.story : null;
  // One step per commit, not to scale in time: work comes in bursts, and a
  // scale in days would crush a busy week into a few pixels beside empty
  // months. The dates under the axis say where the days fall.
  const scale = useMemo(() => {
    if (!data?.commits.length) return null;
    const n = data.commits.length;
    const w = Math.max(width - LABEL_W - 16, 200);
    const index = new Map(data.commits.map((c, i) => [c.sha, i]));
    const step = w / n;
    return { w, step, x: (c: TimelineCommit) => LABEL_W + (index.get(c.sha)! + 0.5) * step, at: (x: number) => Math.floor((x - LABEL_W) / step) };
  }, [data, width]);

  /** A range of commits, as diff mode on the bluprint. */
  const show = (from: TimelineCommit, to: TimelineCommit, root?: string) => {
    diff?.setRange(`${from.sha}~1`, to.sha);
    goTo(root ? [root] : []);
    openDiff();
  };

  const tell = async () => {
    setAsked(true);
    const claude = await claudePath().catch(() => undefined);
    await fetch(`/api/timeline?bluprint=${encodeURIComponent(name)}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ claude }) }).catch(() => setAsked(false));
  };

  const header = (
    <header className="mb-6 border-b border-border-gray pb-5">
      <div className="mb-4">
        <Button onClick={closeTimeline}>‹ Back to the bluprint</Button>
      </div>
      <Eyebrow>History</Eyebrow>
      <h1 className="mt-2 font-display text-[32px] font-normal leading-[1.05] tracking-[-0.016em] text-ink">How the code got here</h1>
      {data?.commits.length ? (
        <p className="mt-1.5 max-w-[720px] text-[13.5px] leading-relaxed text-on-surface-variant">
          {data.commits.length} commits{data.capped ? " (the most recent)" : ""} from {day(data.commits[0].at)} to {day(data.commits[data.commits.length - 1].at)}, on the bluprint&apos;s
          sections, one step per commit. The bars above are each commit&apos;s size; click a dot to see what it did, or drag across a stretch.
        </p>
      ) : null}
    </header>
  );

  if (!got) return <>{header}<p className="text-[13px] text-faint">Reading the history…</p></>;
  if ("error" in got) return <>{header}<p className="text-[13px] text-clay-ink">{got.error}</p></>;
  if (!data?.commits.length || !scale) return <>{header}<p className="text-[13px] text-muted-slate">This checkout has no commits yet.</p></>;

  const bands = story ? BAND_H : 0;
  const top = bands + STRIP_H;
  const h = top + data.roots.length * ROW_H + AXIS_H;
  const byShort = new Map(data.commits.map((c) => [c.short, c]));
  const rowOf = (id: string) => data.roots.findIndex((r) => r.id === id);

  // The strip: each commit's size, so the big ones stand out of the rows.
  const most = Math.max(...data.commits.map(size), 1);
  const r = Math.max(1.5, Math.min(4.5, scale.step / 2 - 0.5));

  // A date wherever the day changes, at least 80px from the last one.
  const ticks: TimelineCommit[] = [];
  for (const c of data.commits) {
    const last = ticks[ticks.length - 1];
    if (!last || (c.at.slice(0, 10) !== last.at.slice(0, 10) && scale.x(c) - scale.x(last) >= 80)) ticks.push(c);
  }

  const inSpan = (a: number, b: number) => data.commits.slice(Math.max(0, scale.at(Math.min(a, b))), scale.at(Math.max(a, b)) + 1);
  const local = (e: React.PointerEvent) => e.clientX - (box.current?.getBoundingClientRect().left ?? 0);

  return (
    <>
      {header}
      <div className="mb-4 flex flex-wrap items-center gap-3">
        {story ? (
          <p className="text-[12.5px] text-muted-slate">
            Told in {story.chapters.length} chapters by Claude from the commit messages — click one to see what it covered.
          </p>
        ) : telling ? (
          <p className="text-[12.5px] text-muted-slate">Claude is reading the commit messages… the chapters appear here when it is done.</p>
        ) : (
          <>
            <Button onClick={tell}>Tell the story</Button>
            <p className="text-[12.5px] text-muted-slate">Claude groups the commits into chapters from their messages. One short run, usually under a minute.</p>
          </>
        )}
      </div>
      <div ref={box} className="relative w-full select-none">
        <svg
          width="100%"
          height={h}
          role="img"
          aria-label={`${data.commits.length} commits over time, by section`}
          onPointerDown={(e) => {
            const x = local(e);
            if (x < LABEL_W || (e.target as Element).closest("[data-commit], [data-chapter]")) return;
            (e.currentTarget as Element).setPointerCapture(e.pointerId);
            setDrag({ a: x, b: x });
          }}
          onPointerMove={(e) => drag && setDrag({ ...drag, b: Math.max(LABEL_W, Math.min(local(e), LABEL_W + scale.w)) })}
          onPointerUp={() => {
            if (!drag) return;
            const picked = Math.abs(drag.b - drag.a) > 6 ? inSpan(drag.a, drag.b) : [];
            setDrag(null);
            if (picked.length) show(picked[0], picked[picked.length - 1]);
          }}
        >
          {/* Chapters, behind everything: a band over the dots each one tells. */}
          {story?.chapters.map((ch: Chapter, i) => {
            const a = byShort.get(ch.from);
            const b = byShort.get(ch.to);
            if (!a || !b) return null;
            const x0 = scale.x(a) - scale.step / 2;
            const x1 = scale.x(b) + scale.step / 2;
            // Every other chapter shaded: the colours are the sections' own.
            return (
              <g key={ch.from} data-chapter className="cursor-pointer" onClick={() => show(a, b)}>
                <title>{`${ch.title} — ${ch.detail}`}</title>
                <rect x={x0} y={0} width={Math.max(x1 - x0, 6)} height={h - AXIS_H} fill={i % 2 ? "transparent" : "var(--color-surface-container-low)"} />
                <line x1={x0} x2={x0} y1={0} y2={h - AXIS_H} stroke="var(--color-border-gray)" />
                <text x={x0 + 5} y={15} fontSize={11.5} fontWeight={600} fill="var(--color-ink)" className="font-sans">
                  {fit(ch.title, x1 - x0 - 10)}
                </text>
              </g>
            );
          })}

          {data.commits.map((c) => {
            const bh = Math.max(1, (size(c) / most) * (STRIP_H - 8));
            return (
              <rect key={c.sha} x={scale.x(c) - Math.max(scale.step - 1, 1) / 2} y={bands + STRIP_H - 4 - bh} width={Math.max(scale.step - 1, 1)} height={bh} fill={hover?.c === c ? "var(--color-ink)" : "var(--color-wire)"} />
            );
          })}

          {data.roots.map((row, i) => {
            const y = top + i * ROW_H + ROW_H / 2;
            const tone = row.id === ELSEWHERE ? { ink: "var(--color-faint)" } : sectionTone(i);
            const born = data.commits.find((c) => c.roots.includes(row.id));
            return (
              <g key={row.id || "elsewhere"}>
                <line x1={LABEL_W} x2={LABEL_W + scale.w} y1={y} y2={y} stroke="var(--color-border-gray)" />
                <text x={0} y={y + 4} fontSize={12.5} fill={tone.ink} className="font-sans">
                  {row.title.length > 22 ? `${row.title.slice(0, 21)}…` : row.title}
                </text>
                {born && row.id !== ELSEWHERE ? (
                  <line x1={scale.x(born)} x2={scale.x(born)} y1={y - 9} y2={y + 9} stroke={tone.ink} strokeWidth={1.5}>
                    <title>{`${row.title} first appears: ${born.subject} (${day(born.at)})`}</title>
                  </line>
                ) : null}
              </g>
            );
          })}

          {data.commits.flatMap((c) =>
            c.roots.map((id) => {
              const i = rowOf(id);
              const tone = id === ELSEWHERE ? "var(--color-faint)" : sectionTone(i).ink;
              const cx = scale.x(c);
              const cy = top + i * ROW_H + ROW_H / 2;
              return (
                <circle
                  key={`${c.sha}:${id}`}
                  data-commit
                  cx={cx}
                  cy={cy}
                  r={r}
                  fill={tone}
                  fillOpacity={hover?.c === c ? 1 : 0.55}
                  stroke={hover?.c === c ? "var(--color-ink)" : "none"}
                  className="cursor-pointer"
                  onPointerEnter={() => setHover({ c, x: cx, y: cy })}
                  onPointerLeave={() => setHover((v) => (v?.c === c ? null : v))}
                  onClick={() => show(c, c, id === ELSEWHERE ? undefined : id)}
                />
              );
            }),
          )}

          {ticks.map((c) => (
            <text key={c.sha} x={scale.x(c)} y={h - 6} fontSize={10.5} fill="var(--color-faint)" textAnchor="middle" className="tnum font-sans">
              {new Date(c.at).toLocaleDateString(undefined, { day: "numeric", month: "short" })}
            </text>
          ))}

          {drag && Math.abs(drag.b - drag.a) > 6 ? (
            <rect x={Math.min(drag.a, drag.b)} y={bands} width={Math.abs(drag.b - drag.a)} height={h - AXIS_H - bands} fill="var(--color-accent-surface)" opacity={0.5} stroke="var(--color-accent)" />
          ) : null}
        </svg>

        {hover ? (
          <div
            className="pointer-events-none absolute z-10 w-[280px] border border-border-gray bg-card px-3 py-2 shadow-sm"
            style={{ left: Math.min(hover.x + 12, Math.max(width - 290, 0)), top: hover.y + 12 }}
          >
            <p className="text-[12.5px] font-medium leading-snug text-ink">{hover.c.subject}</p>
            <p className="mt-0.5 text-[11px] text-muted-slate">
              {hover.c.author} · {day(hover.c.at)} · <span className="font-mono">{hover.c.short}</span>{" "}
              <span className="tnum font-mono" style={{ color: TINT.added.ink }}>
                +{hover.c.added}
              </span>{" "}
              <span className="tnum font-mono" style={{ color: TINT.removed.ink }}>
                −{hover.c.removed}
              </span>
            </p>
          </div>
        ) : null}
      </div>
      {story ? (
        <ol className="mt-6 flex max-w-[760px] flex-col gap-2.5">
          {story.chapters.map((ch, i) => {
            const a = byShort.get(ch.from);
            const b = byShort.get(ch.to);
            return (
              <li key={ch.from}>
                <button
                  type="button"
                  disabled={!a || !b}
                  onClick={() => a && b && show(a, b)}
                  className="block w-full cursor-pointer px-2 py-1.5 text-left hover:bg-surface-container focus-visible:outline-2 focus-visible:outline-accent"
                >
                  <span className="text-[13.5px] font-semibold text-ink">
                    <span className="tnum mr-1.5 text-faint">{i + 1}.</span>
                    {ch.title}
                  </span>
                  <span className="ml-2 text-[11.5px] text-faint">
                    {a ? day(a.at) : ch.from} – {b ? day(b.at) : ch.to}
                  </span>
                  <span className="mt-0.5 block text-[13px] leading-relaxed text-on-surface-variant">{ch.detail}</span>
                </button>
              </li>
            );
          })}
        </ol>
      ) : null}
    </>
  );
}

app/components/ui/button.tsx:
import { forwardRef } from "react";
import { cn } from "@/lib/client/utils";

/**
 * The app's one button. Every action on a level, in a dialog and in the
 * workspace is one of three weights, so a header with three actions reads as
 * a toolbar rather than three components that happened to land together:
 *
 * - `outline` — the default: a paper face and a hairline, for actions on the
 *   page (View the code, Keep the answer). On hover it fills with ink, as
 *   the landing page's buttons do.
 * - `ghost` — no face until hovered, for chrome (tab bars, the status bar).
 * - `primary` — filled with ink, the one thing a dialog is for.
 *
 * `tone="alarm"` recolours any of them for actions about problems.
 */
type Props = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: "outline" | "ghost" | "primary";
  size?: "sm" | "md";
  tone?: "alarm";
  /** Drawn before the label. */
  icon?: React.ReactNode;
};

export const Button = forwardRef<HTMLButtonElement, Props>(function Button(
  { variant = "outline", size = "md", tone, icon, className, children, type = "button", ...rest },
  ref,
) {
  return (
    <button
      ref={ref}
      type={type}
      className={cn(
        "inline-flex shrink-0 cursor-pointer items-center gap-1.5 whitespace-nowrap font-mono font-medium uppercase tracking-[0.04em] transition-[background-color,border-color,color] duration-100",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent/70",
        "disabled:cursor-default disabled:opacity-50",
        size === "sm" ? "h-6 px-2 text-[11px]" : "h-7 px-2.5 text-[11.5px]",
        variant === "outline" &&
          (tone === "alarm"
            ? "border border-clay-line bg-card text-clay-ink hover:border-clay-ink hover:bg-clay-ink hover:text-paper"
            : "border border-border-strong bg-card text-ink hover:border-accent hover:bg-accent hover:text-on-accent"),
        variant === "ghost" &&
          (tone === "alarm"
            ? "text-clay-ink hover:bg-clay-surface"
            : "text-muted-slate hover:bg-surface-container hover:text-ink"),
        variant === "primary" && "border border-accent bg-accent text-on-accent hover:border-accent-strong hover:bg-accent-strong",
        className,
      )}
      {...rest}
    >
      {icon}
      {children}
    </button>
  );
});

/**
 * A shortcut as the platform writes it: ⌘K on a Mac, Ctrl+K elsewhere. `ctrl`
 * for a key that is Control on a Mac too (⌃T in a terminal).
 */
export const keys = (mac: boolean, key: string, { ctrl = false, shift = false } = {}) =>
  mac ? `${ctrl ? "⌃" : "⌘"}${shift ? "⇧" : ""}${key}` : `Ctrl+${shift ? "Shift+" : ""}${key}`;

/** A key, as the app writes one everywhere: in tooltips, the palette, the status bar. */
export function Kbd({ children, className }: { children: React.ReactNode; className?: string }) {
  return (
    <kbd
      className={cn(
        "inline-flex h-[18px] min-w-[18px] items-center justify-center border border-border-gray bg-surface px-1 font-sans text-[10.5px] font-medium leading-none text-muted-slate",
        className,
      )}
    >
      {children}
    </kbd>
  );
}

/** The `</>` mark for anything that opens code. */
export function CodeIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="m5.5 4.5-3.5 3.5 3.5 3.5M10.5 4.5l3.5 3.5-3.5 3.5" />
    </svg>
  );
}

