"use client";

import { useEffect } from "react";

/**
 * The pieces the app's dialogs share: a dimmed layer over the bluprint that closes
 * on Escape or a click outside (Escape stops here rather than also leaving the
 * level), and the form parts inside one.
 */
export function Overlay({
  onClose,
  dim,
  style,
  children,
}: {
  onClose: () => void;
  /** A darker layer, for a popup that should read as lifted off the bluprint. */
  dim?: boolean;
  style?: React.CSSProperties;
  children: React.ReactNode;
}) {
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      // A note being written over the dialog (components/review/review-tray.tsx) takes its own Escape.
      if ((e.target as Element | null)?.closest?.("[data-note-editor]")) return;
      // A menu open over the dialog (components/ui/menu.tsx) closes first.
      if (document.querySelector('[role="menu"]')) return;
      e.stopPropagation();
      onClose();
    };
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, [onClose]);

  return (
    <div
      className={`fixed inset-0 z-50 flex items-center justify-center p-6 ${dim ? "bg-night/40" : "bg-night/20"}`}
      style={style}
      onPointerDown={(e) => e.target === e.currentTarget && onClose()}
    >
      {children}
    </div>
  );
}

export const DIALOG =
  "flex max-h-full w-full flex-col overflow-hidden border border-border-gray bg-card shadow-lift";

export const INPUT =
  "w-full border border-border-gray bg-card px-3 py-2 font-mono text-[12.5px] text-ink placeholder:text-faint focus:border-accent focus:outline-none";

/* A dialog's actions, drawn as Button's `primary` and `ghost` (components/ui/button.tsx),
   so a dialog's buttons read as the rest of the app's. */
const ACTION =
  "inline-flex h-7 shrink-0 cursor-pointer items-center gap-1.5 whitespace-nowrap px-2.5 font-mono text-[11.5px] font-medium uppercase tracking-[0.04em] transition-[background-color,border-color,color] duration-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent/70 disabled:cursor-default disabled:opacity-50";

export const PRIMARY = `${ACTION} border border-accent bg-accent text-on-accent hover:border-accent-strong hover:bg-accent-strong`;

export const QUIET = `${ACTION} text-muted-slate hover:bg-surface-container hover:text-ink`;

/**
 * A labelled setting. `group` for one that holds buttons rather than a field:
 * a <label> passes a click on its words to the first button inside, so
 * clicking "Theme" would pick Classic.
 */
export function Field({ label, hint, group, children }: { label: string; hint: string; group?: boolean; children: React.ReactNode }) {
  const Box = group ? "div" : "label";
  return (
    <Box className="block" {...(group ? { role: "group", "aria-label": label } : {})}>
      <span className="text-[13px] font-semibold text-ink">{label}</span>
      <span className="mb-2 mt-0.5 block text-[12px] text-muted-slate">{hint}</span>
      {children}
    </Box>
  );
}

app/components/ui/editor.tsx:
"use client";

import { useEffect, useRef } from "react";
import { basicSetup } from "codemirror";
import { indentWithTab } from "@codemirror/commands";
import { HighlightStyle, indentUnit, syntaxHighlighting, LanguageDescription } from "@codemirror/language";
import { languages } from "@codemirror/language-data";
import { Compartment, EditorState, Prec, RangeSetBuilder } from "@codemirror/state";
import { Decoration, EditorView, keymap, lineNumbers } from "@codemirror/view";
import { tags as t } from "@lezer/highlight";
import { cn } from "@/lib/client/utils";

/**
 * Code you can type into where you read it: CodeMirror, with the file's own
 * grammar (loaded by its name, only when one is opened), and the editing a code
 * editor has — auto-indent, bracket matching and closing, folding, multiple
 * cursors, find and replace, completion from words in the file. Coloured with
 * the code pane's tokens, so the theme follows light and dark.
 *
 * Typing changes only the draft. Writing to disk is the caller's, on ⌘S or
 * its Save button — never on a keystroke, a blur or navigation.
 */

const v = (name: string) => `var(--color-${name})`;

const colours = HighlightStyle.define([
  { tag: [t.comment, t.lineComment, t.blockComment, t.docComment], color: v("code-comment"), fontStyle: "italic" },
  { tag: [t.string, t.special(t.string), t.regexp, t.character, t.attributeValue], color: v("code-string") },
  { tag: [t.number, t.bool, t.null, t.atom], color: v("code-number") },
  { tag: [t.keyword, t.controlKeyword, t.moduleKeyword, t.operatorKeyword, t.definitionKeyword, t.modifier, t.self], color: v("code-keyword") },
  { tag: [t.typeName, t.className, t.namespace, t.tagName, t.standard(t.tagName)], color: v("code-type") },
  { tag: [t.function(t.variableName), t.function(t.propertyName), t.macroName], color: v("code-call") },
  { tag: [t.punctuation, t.operator, t.bracket, t.angleBracket, t.separator], color: v("code-punct") },
  { tag: [t.annotation, t.meta, t.attributeName, t.labelName], color: v("code-annotation") },
  { tag: [t.heading], color: v("code-keyword"), fontWeight: "600" },
  { tag: [t.link, t.url], color: v("code-call"), textDecoration: "underline" },
  { tag: [t.emphasis], fontStyle: "italic" },
  { tag: [t.strong], fontWeight: "600" },
  { tag: t.invalid, color: v("code-string") },
]);

const look = EditorView.theme({
  "&": { flex: "1 1 auto", minHeight: "0", backgroundColor: v("code"), color: v("code-plain"), fontSize: "12.5px" },
  "&.cm-focused": { outline: "none" },
  ".cm-scroller": { fontFamily: "var(--font-mono), ui-monospace, monospace", lineHeight: "1.65", overflow: "auto" },
  ".cm-content": { padding: "8px 0", caretColor: v("ink") },
  ".cm-line": { padding: "0 16px 0 12px" },
  ".cm-cursor, .cm-dropCursor": { borderLeftColor: v("ink") },
  "&.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground, .cm-selectionBackground, ::selection": {
    backgroundColor: "color-mix(in srgb, var(--color-accent) 25%, transparent)",
  },
  ".cm-gutters": { backgroundColor: v("code"), color: v("faint"), border: "none", borderRight: `1px solid ${v("border-gray")}` },
  ".cm-lineNumbers .cm-gutterElement": { padding: "0 10px 0 12px", fontVariantNumeric: "tabular-nums" },
  ".cm-activeLine": { backgroundColor: "color-mix(in srgb, var(--color-accent) 6%, transparent)" },
  ".cm-activeLineGutter": { backgroundColor: "transparent", color: v("ink") },
  ".cm-lit": { backgroundColor: v("amber-surface") },
  ".cm-matchingBracket, &.cm-focused .cm-matchingBracket": {
    backgroundColor: "color-mix(in srgb, var(--color-accent) 18%, transparent)",
    outline: `1px solid color-mix(in srgb, var(--color-accent) 45%, transparent)`,
  },
  ".cm-searchMatch": { backgroundColor: v("amber-surface"), outline: `1px solid ${v("amber-ink")}` },
  ".cm-foldPlaceholder": { backgroundColor: "transparent", border: `1px solid ${v("border-gray")}`, color: v("faint") },
  ".cm-panels": { backgroundColor: v("surface-container"), color: v("ink"), borderColor: v("border-gray") },
  ".cm-panel.cm-search": { padding: "6px 10px", fontSize: "11px", display: "flex", flexWrap: "wrap", alignItems: "center", gap: "6px" },
  ".cm-panel.cm-search br": { flexBasis: "100%", height: 0 },
  ".cm-textfield": {
    margin: 0, padding: "3px 8px", font: "inherit", fontFamily: "var(--font-mono), ui-monospace, monospace",
    backgroundColor: v("surface"), color: v("ink"), border: `1px solid ${v("border-gray")}`, borderRadius: 0, outline: "none",
  },
  ".cm-textfield:focus": { borderColor: v("accent") },
  ".cm-button": {
    margin: 0, padding: "3px 10px", font: "inherit", backgroundImage: "none", backgroundColor: v("surface"),
    color: v("ink"), border: `1px solid ${v("border-gray")}`, borderRadius: 0, cursor: "pointer",
  },
  ".cm-button:hover": { borderColor: v("accent"), color: v("accent") },
  ".cm-panel.cm-search label": { display: "inline-flex", alignItems: "center", gap: "4px", margin: 0, color: v("faint"), fontSize: "11px" },
  ".cm-panel.cm-search input[type=checkbox]": { margin: 0, accentColor: v("accent") },
  ".cm-panel.cm-search [name=close]": { position: "static", marginLeft: "auto", fontSize: "16px", color: v("faint"), cursor: "pointer" },
  ".cm-tooltip": { backgroundColor: v("surface-container"), color: v("ink"), border: `1px solid ${v("border-gray")}` },
  ".cm-tooltip-autocomplete > ul > li[aria-selected]": { backgroundColor: v("accent"), color: v("on-accent") },
});

// The line the view opened on, lit in amber like the bluprint's citations.
const litLine = (line: number | undefined) =>
  EditorView.decorations.compute(["doc"], (s) => {
    const b = new RangeSetBuilder<Decoration>();
    if (line && line >= 1 && line <= s.doc.lines) {
      const at = s.doc.line(line).from;
      b.add(at, at, Decoration.line({ class: "cm-lit" }));
    }
    return b.finish();
  });

export function CodeEditor({
  file,
  start,
  value,
  onChange,
  onSave,
  readOnly,
  lit,
  className,
}: {
  file: string;
  /** The first line's number in the file. */
  start: number;
  value: string;
  onChange: (next: string) => void;
  onSave?: () => void;
  readOnly?: boolean;
  /** A line to light and bring into view, as the file numbers it. */
  lit?: number;
  className?: string;
}) {
  const box = useRef<HTMLDivElement>(null);
  const view = useRef<EditorView | null>(null);
  // Read through refs, so the editor is made once per file and never torn down
  // (losing its undo history and cursor) because a parent drew new callbacks.
  const handlers = useRef({ onChange, onSave });
  useEffect(() => {
    handlers.current = { onChange, onSave };
  });
  const lang = useRef(new Compartment());
  const editable = useRef(new Compartment());
  const lighting = useRef(new Compartment());

  useEffect(() => {
    const ed = new EditorView({
      parent: box.current!,
      state: EditorState.create({
        doc: value,
        extensions: [
          Prec.highest(keymap.of([{ key: "Mod-s", preventDefault: true, run: () => (handlers.current.onSave?.(), true) }])),
          lineNumbers({ formatNumber: (n) => String(start + n - 1) }),
          basicSetup,
          keymap.of([indentWithTab]),
          // Indent the way the file already does.
          indentUnit.of(/^\t/m.test(value) ? "\t" : "  "),
          EditorState.tabSize.of(4),
          syntaxHighlighting(colours),
          look,
          lang.current.of([]),
          editable.current.of(EditorState.readOnly.of(Boolean(readOnly))),
          lighting.current.of(litLine(lit && lit - start + 1)),
          EditorView.updateListener.of((u) => {
            if (u.docChanged) handlers.current.onChange(u.state.doc.toString());
          }),
          EditorView.contentAttributes.of({ "aria-label": `Code of ${file}` }),
        ],
      }),
    });
    view.current = ed;
    let live = true;
    void LanguageDescription.matchFilename(languages, file)
      ?.load()
      .then((support) => live && ed.dispatch({ effects: lang.current.reconfigure(support) }));
    return () => {
      live = false;
      ed.destroy();
      view.current = null;
    };
    // Made once per file; value, start and the rest are kept in step below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [file]);

  // A value changed from outside (reloaded from disk, a save that reformatted)
  // replaces the text; one that came from typing here is already in it.
  useEffect(() => {
    const ed = view.current;
    if (ed && ed.state.doc.toString() !== value) ed.dispatch({ changes: { from: 0, to: ed.state.doc.length, insert: value } });
  }, [value]);

  useEffect(() => {
    view.current?.dispatch({ effects: editable.current.reconfigure(EditorState.readOnly.of(Boolean(readOnly))) });
  }, [readOnly]);

  useEffect(() => {
    const ed = view.current;
    if (!ed) return;
    const n = lit ? lit - start + 1 : 0;
    ed.dispatch({ effects: lighting.current.reconfigure(litLine(n)) });
    // Once, where the view opened; not again as the reader types. Scrolls this
    // box only: CodeMirror's scrollIntoView also scrolls the page, hiding the header above.
    if (n >= 1 && n <= ed.state.doc.lines) {
      const at = ed.state.doc.line(n).from;
      ed.requestMeasure({
        read: () => ed.lineBlockAt(at).top,
        write: (top) => (ed.scrollDOM.scrollTop = top - ed.scrollDOM.clientHeight / 2),
      });
    }
  }, [lit, start]);

  // A column, so the editor shrinks to a height the caller caps and scrolls
  // inside itself, where CodeMirror can see which lines are in view.
  return <div ref={box} className={cn("flex flex-col overflow-hidden bg-code", className)} />;
}

app/components/ui/markdown-editor.tsx:
"use client";

import { invoke } from "@tauri-apps/api/core";
import { memo, useEffect, useLayoutEffect, useRef, useState } from "react";
import Markdown, { type Components } from "react-markdown";
import { cn } from "@/lib/client/utils";
import { PLUGINS, REHYPE } from "@/lib/client/markdown";

/**
 * A Markdown file read as a page and written where it is read, as Obsidian's
 * live preview does: every block is drawn, and the one being edited shows its
 * Markdown in place. The text is split into blocks at blank lines (a fence
 * holds its blank lines), and the block being edited is a fixed range of
 * lines, so typing a blank line inside it does not move the caret into a
 * different block mid-word.
 *
 * As CodeEditor, typing changes only the draft; ⌘S is the caller's save.
 */

type Range = { from: number; to: number };

const FENCE = /^ {0,3}(`{3,}|~{3,})/;

/** Line ranges of the blocks in `lines`, from line `base`: runs of non-blank lines, a fenced block whole. */
function blocks(lines: string[], base: number): Range[] {
  const out: Range[] = [];
  let open: string | null = null;
  let from = -1;
  lines.forEach((l, i) => {
    const fence = l.match(FENCE)?.[1];
    if (open) {
      if (fence && fence[0] === open[0] && fence.length >= open.length) open = null;
      return;
    }
    if (fence) open = fence;
    if (!l.trim()) {
      if (from >= 0) out.push({ from: base + from, to: base + i });
      from = -1;
    } else if (from < 0) from = i;
  });
  if (from >= 0) out.push({ from: base + from, to: base + lines.length });
  return out;
}


/** An image beside the file, read off disk; a web one as it is. */
function LocalImg({ dir, src, alt, ...rest }: React.ImgHTMLAttributes<HTMLImageElement> & { dir: string }) {
  const [url, setUrl] = useState<string>();
  const s = typeof src === "string" ? src : undefined;
  const local = s && !/^[a-z][a-z0-9+.-]*:/i.test(s) ? (s.startsWith("/") ? s : `${dir}/${decodeURIComponent(s.split(/[?#]/)[0])}`) : null;
  useEffect(() => {
    if (!local) return;
    let made: string | undefined;
    let gone = false;
    invoke<ArrayBuffer>("file_read", { path: local })
      .then((buf) => {
        made = URL.createObjectURL(new Blob([buf], local.toLowerCase().endsWith(".svg") ? { type: "image/svg+xml" } : {}));
        if (!gone) setUrl(made);
      })
      .catch(() => {});
    return () => {
      gone = true;
      if (made) URL.revokeObjectURL(made);
    };
  }, [local]);
  // eslint-disable-next-line @next/next/no-img-element -- a local file's own image
  return <img {...rest} src={local ? url : s} alt={alt ?? ""} />;
}

const Block = memo(function Block({ text, dir }: { text: string; dir: string }) {
  const components: Components = {
    a: ({ href, children }) => (
      <a href={href} target="_blank" rel="noreferrer">
        {children}
      </a>
    ),
    img: ({ src, alt, title, width, height }) => <LocalImg dir={dir} src={typeof src === "string" ? src : undefined} alt={alt} title={title} width={width} height={height} />,
    // GFM draws task boxes disabled; here a click ticks them in the text.
    input: ({ type, checked }) => <input type={type} defaultChecked={checked} key={String(checked)} className="cursor-pointer" />,
  };
  return (
    <Markdown remarkPlugins={PLUGINS} rehypePlugins={REHYPE} components={components}>
      {text}
    </Markdown>
  );
});

const TASK = /^(\s*(?:[-*+]|\d+[.)])\s+\[)([ xX])(\])/gm;

export function MarkdownEditor({
  file,
  value,
  onChange,
  onSave,
  lit,
  className,
}: {
  file: string;
  value: string;
  onChange: (next: string) => void;
  onSave?: () => void;
  /** A line to bring into view, as the file numbers it. */
  lit?: number;
  className?: string;
}) {
  const lines = value.split("\n");
  const [edit, setEdit] = useState<(Range & { caret?: number }) | null>(null);
  const area = useRef<HTMLTextAreaElement>(null);
  const box = useRef<HTMLDivElement>(null);
  const dir = file.slice(0, file.lastIndexOf("/"));

  const all: (Range & { editing?: boolean })[] = edit
    ? [...blocks(lines.slice(0, edit.from), 0), { ...edit, editing: true }, ...blocks(lines.slice(edit.to), edit.to)]
    : blocks(lines, 0);

  // The editing block grows with what it holds, and takes the caret where it was put.
  useLayoutEffect(() => {
    const t = area.current;
    if (!t) return;
    t.style.height = "0";
    t.style.height = `${t.scrollHeight}px`;
  });
  useEffect(() => {
    const t = area.current;
    if (!t || edit?.caret === undefined) return;
    t.focus();
    const at = edit.caret < 0 ? t.value.length : edit.caret;
    t.setSelectionRange(at, at);
    setEdit((e) => (e ? { from: e.from, to: e.to } : e));
  }, [edit?.caret]);

  useEffect(() => {
    if (!lit || !box.current) return;
    const at = [...box.current.querySelectorAll<HTMLElement>("[data-from]")].filter((el) => Number(el.dataset.from) < lit).pop();
    at?.scrollIntoView({ block: "center" });
  }, [lit]);

  const splice = (r: Range, text: string) => {
    const next = [...lines.slice(0, r.from), ...text.split("\n"), ...lines.slice(r.to)];
    onChange(next.join("\n"));
    return r.from + text.split("\n").length;
  };

  const open = (r: Range, caret = -1) => setEdit({ ...r, caret });

  /** A new empty block after the last one, to write into. */
  const append = () => {
    const last = all.at(-1);
    if (last && !lines.slice(last.from, last.to).join("").trim()) return open(last);
    const tail = value.endsWith("\n") ? (value.endsWith("\n\n") ? "" : "\n") : value ? "\n\n" : "";
    const next = value + tail;
    onChange(next);
    const at = next.split("\n").length - 1;
    open({ from: at, to: at + 1 });
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>, r: Range, i: number) => {
    const t = e.currentTarget;
    if ((e.metaKey || e.ctrlKey) && e.key === "s") {
      e.preventDefault();
      onSave?.();
    } else if (e.key === "Escape") {
      setEdit(null);
    } else if (e.key === "ArrowUp" && t.selectionStart === 0 && t.selectionEnd === 0 && i > 0) {
      e.preventDefault();
      open(all[i - 1]);
    } else if (e.key === "ArrowDown" && t.selectionStart === t.value.length && i < all.length - 1) {
      e.preventDefault();
      open(all[i + 1], 0);
    } else if (e.key === "Tab" && !e.shiftKey && !e.metaKey && !e.ctrlKey && !e.altKey) {
      e.preventDefault();
      const { selectionStart: a, selectionEnd: b } = t;
      setEdit({ ...r, to: splice(r, t.value.slice(0, a) + "  " + t.value.slice(b)), caret: a + 2 });
    }
  };

  // Edits begin on mousedown, not click: the block left behind redraws
  // between the two and moves what the pointer was on.
  const onBlockDown = (e: React.MouseEvent<HTMLElement>, r: Range) => {
    const target = e.target as HTMLElement;
    if (e.button !== 0 || target.closest("a") || (target instanceof HTMLInputElement && target.type === "checkbox")) return;
    e.preventDefault();
    open(r);
  };
  /** A task box ticked in the drawing is ticked in the text. */
  const onBlockClick = (e: React.MouseEvent<HTMLElement>, r: Range) => {
    const target = e.target;
    if (!(target instanceof HTMLInputElement && target.type === "checkbox")) return;
    const nth = [...e.currentTarget.querySelectorAll('input[type="checkbox"]')].indexOf(target);
    let k = 0;
    splice(r, lines.slice(r.from, r.to).join("\n").replace(TASK, (m, a, x, b) => (k++ === nth ? a + (x === " " ? "x" : " ") + b : m)));
  };
  const onEmptyDown = (e: React.MouseEvent<HTMLElement>) => {
    if (e.target !== e.currentTarget) return;
    e.preventDefault();
    append();
  };

  return (
    <div ref={box} className={cn("overflow-auto bg-code", className)} onMouseDown={onEmptyDown}>
      <div className="doc-prose mx-auto min-h-full max-w-[760px] px-8 pb-[40vh] pt-8" onMouseDown={onEmptyDown}>
        {all.length === 0 ? <p className="text-faint">Empty. Click to write.</p> : null}
        {all.map((r, i) =>
          r.editing ? (
            <textarea
              key={`e${r.from}`}
              ref={area}
              aria-label={`Markdown of ${file}`}
              value={lines.slice(r.from, r.to).join("\n")}
              onChange={(e) => setEdit({ from: r.from, to: splice(r, e.target.value) })}
              onKeyDown={(e) => onKeyDown(e, r, i)}
              onBlur={() => setEdit((cur) => (cur?.from === r.from && cur.caret === undefined ? null : cur))}
              spellCheck
              className="-mx-2 block w-[calc(100%+1rem)] resize-none overflow-hidden whitespace-pre-wrap bg-surface-container px-2 py-1 font-mono text-[13px] leading-[1.65] text-ink caret-ink outline-none"
            />
          ) : (
            <div key={`${r.from}:${r.to}`} data-from={r.from + 1} onMouseDown={(e) => onBlockDown(e, r)} onClick={(e) => onBlockClick(e, r)} className="doc-prose -mx-2 cursor-text px-2 hover:bg-surface-container/50">
              <Block text={lines.slice(r.from, r.to).join("\n")} dir={dir} />
            </div>
          ),
        )}
      </div>
    </div>
  );
}

app/components/ui/menu.tsx:
"use client";

import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { cn } from "@/lib/client/utils";

/**
 * A right-click menu: a small card at the pointer. It closes the way a native
 * one does — Escape, a click anywhere else, scrolling, or the window losing
 * focus — and Escape stops there rather than also leaving the level.
 *
 * It is drawn on the page's body, not where it was opened: opened from a bar
 * ([data-chrome="bar"], black in Classic), it would take the bar's colours
 * along with it, so the same menu would read two ways. Every menu is the
 * sheet's.
 */

export interface MenuItem {
  label: string;
  /** Drawn before the label, at text size. */
  icon?: React.ReactNode;
  onClick?: () => void;
  disabled?: boolean;
  /** A rule above it, setting it apart from the items before. */
  separated?: boolean;
}

export function Menu({
  x,
  y,
  title,
  items,
  onClose,
}: {
  x: number;
  y: number;
  /** What the menu acts on, named above the items. */
  title?: string;
  items: MenuItem[];
  onClose: () => void;
}) {
  const ref = useRef<HTMLDivElement>(null);
  // Kept on screen: opened near the right or bottom edge, it flips inward.
  const [at, setAt] = useState({ x, y });
  useLayoutEffect(() => {
    const box = ref.current?.getBoundingClientRect();
    if (!box) return;
    setAt({
      x: Math.max(4, Math.min(x, window.innerWidth - box.width - 4)),
      y: Math.max(4, Math.min(y, window.innerHeight - box.height - 4)),
    });
  }, [x, y]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      e.stopPropagation();
      onClose();
    };
    const onDown = (e: PointerEvent) => {
      if (!ref.current?.contains(e.target as globalThis.Node)) onClose();
    };
    window.addEventListener("keydown", onKey, true);
    window.addEventListener("pointerdown", onDown, true);
    window.addEventListener("scroll", onClose, true);
    window.addEventListener("blur", onClose);
    return () => {
      window.removeEventListener("keydown", onKey, true);
      window.removeEventListener("pointerdown", onDown, true);
      window.removeEventListener("scroll", onClose, true);
      window.removeEventListener("blur", onClose);
    };
  }, [onClose]);

  return createPortal(
    <div
      ref={ref}
      role="menu"
      data-chrome
      style={{ left: at.x, top: at.y }}
      className="fixed z-50 min-w-[220px] max-w-[320px] overflow-hidden border border-border-gray bg-card py-1 shadow-lift"
    >
      {title ? (
        <p className="truncate border-b border-border-gray px-3 pb-1.5 pt-1 text-[11.5px] text-faint">{title}</p>
      ) : null}
      {items.map((item, i) => (
        <button
          key={i}
          type="button"
          role="menuitem"
          disabled={item.disabled}
          onClick={() => {
            item.onClick?.();
            onClose();
          }}
          className={cn(
            "flex w-full items-center gap-2 px-3 py-1.5 text-left text-[13px] text-ink outline-none",
            // surface-container-low is the card's own white in Classic's chrome, so a hover on it would not show.
            item.disabled ? "text-faint" : "cursor-pointer hover:bg-surface-container focus-visible:bg-surface-container",
            item.separated && "mt-1 border-t border-border-gray pt-2",
          )}
        >
          {item.icon}
          {item.label}
        </button>
      ))}
    </div>,
    document.body,
  );
}

