import { updateBluprint, type Turn } from "@/lib/agent/update-bluprint";

/** The checkout each Claude tab is mid-turn in, by pty: that turn's end updates the bluprint with its transcript. */
export const midTurn = new Map<number, string>();

/** Whether Claude is mid-turn in `root`, so an update started now would race the one its turn will ask for. */
export function claudeMidTurnIn(root: string) {
  return [...midTurn.values()].some((cwd) => cwd === root || cwd.startsWith(`${root}/`) || cwd.startsWith(`${root}\\`));
}

/** Asks for the bluprint to follow a turn that edited `root`; a checkout no project bluprints is said so in the title bar. */
export async function followTurn(root: string, turn: Turn) {
  const res = await updateBluprint(root, turn);
  // Not one of the user's projects: the title bar says so, and offers to import it.
  if (res?.skipped) window.dispatchEvent(new CustomEvent(UNFOLLOWED, { detail: root }));
}

/** An agent edited a checkout whose bluprint cannot follow it; the detail is the checkout. */
export const UNFOLLOWED = "bluprint:bluprint-unfollowed";

app/lib/agent/undo.ts:
import { hasClaude, pick } from "@/lib/agent/context";
import { updateBluprint } from "@/lib/agent/update-bluprint";

export type Undone =
  | { ok: true; restored: string[] }
  | { ok: false; conflicts?: string[]; refused?: string[]; error?: string };

/**
 * Puts the files one agent turn edited back as they were (app/api/undo). Then
 * the bluprint is brought back up to the code, and Claude is told with its next
 * prompt, since its session still remembers making the edits.
 */
export async function undoTurn(bluprint: string, turn: string): Promise<Undone> {
  const r = await fetch("/api/undo", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ bluprint, turn }),
  })
    .then((x) => x.json())
    .catch(() => ({ ok: false, error: "The app could not be reached." }));
  if (!r.ok) return r;
  void updateBluprint(r.root);
  // A session that is not running has nothing to forget; none is opened to say so.
  if (hasClaude())
    pick({
      key: `undo:${turn}`,
      title: "Last turn undone",
      text: [
        `[Undone: the user reverted the edits of an earlier turn${r.prompt ? ` (asked: "${r.prompt}")` : ""}.`,
        `These files are back to how they were before it: ${r.restored.join(", ")}.`,
        "Do not assume those edits are still there; read the files again before changing them.]",
      ].join("\n"),
    });
  return { ok: true, restored: r.restored };
}

app/lib/agent/update-bluprint.ts:
import { findClaude } from "@/lib/client/claude";

/**
 * A turn of Claude's the bluprint follows (src-tauri/src/claude.rs): its session's
 * transcript, for what it did and why, and the sections it reported wrong
 * with bluprint-fix.
 */
export interface Turn {
  transcript?: string | null;
  corrections: { section: string; note: string }[];
}

/**
 * Asks for the bluprint of the project at `root` to be brought up to its code
 * (lib/server/vault.ts): only the sections the edits touched, or the agent found
 * wrong, are redone, by the same Claude Code the tabs run. With no turn it
 * only looks at the code, and a bluprint whose cited code is unchanged costs no
 * model call (scripts/generate/update.ts). `skipped` when the checkout is not
 * one of the user's projects.
 */
export async function updateBluprint(root: string, turn?: Turn): Promise<{ skipped?: boolean } | null> {
  const found = await findClaude();
  return fetch("/api/projects", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ action: "update", root, claude: found?.path, turn }),
  })
    .then((r) => r.json())
    .catch(() => null);
}

