app/lib/bluprint/build.ts:
/**
 * The bluprint on screen, whichever repository it describes.
 *
 * A bluprint file states facts — `RUN`, the `OVERVIEW` of the repository, the
 * and the authored tree — as `bluprints/<name>/bluprint.json`,
 * hand-exported or generated.
 * Everything derived from those lives here, so a second repository is a second
 * file, not a copy of the tree plumbing.
 */

import type { Anatomy, CodeRef, Node, Run, Term, Walkthrough } from "@/lib/bluprint/schema";
import { rowId } from "@/lib/bluprint/schema";
import type { Live } from "@/lib/server/live";
import { share } from "@/lib/bluprint/share";

/**
 * The repository as a level of its own: what it is, and one picture whose
 * boxes open the roots. Absent on a bluprint still being made, whose top level is
 * then its roots listed (D60).
 */
export type Overview = Pick<Node, "sub" | "detail" | "anatomy" | "issues" | "code" | "state" | "unsure" | "explain"> & {
  /** The words the whole bluprint leans on, defined once (the Explain layer). */
  glossary?: Term[];
  /** The core things the system does, each followed through the roots it crosses: 2-3, at every explain level. */
  walkthroughs?: Walkthrough[];
  /** Bluprints made before `walkthroughs`: one, under the Explain layer. */
  walkthrough?: Walkthrough;
};

export interface BluprintFile {
  RUN: Run;
  OVERVIEW?: Overview;
  AUTHORED: Node[];
  /** How far the code has moved past this bluprint while it is open (lib/server/live.ts); the bluprint's lines are already shifted to it. */
  LIVE?: Live;
}

/** In a bluprint's version, what follows this is the code moving, not the bluprint (lib/server/bluprints.ts, bluprintVersion). */
export const LIVE_SEP = "|live:";

/** The top level's id: the empty path, which is the repository itself. */
const TOP_ID = "";

/* ── rows that go deeper ──────────────────────────────────────
   A row carrying `under` becomes a REAL child node, spliced in beside whatever
   children its owner already had. See the note in lib/bluprint/schema.ts: the synthesized
   id is rowId(owner, key), the row's own id, so the row and the card it opens
   share an identity. */

/** The rows of one anatomy block that carry `under`, as {key, label, blocks}. */
function deepRows(blocks: Anatomy[]) {
  const out: { key: string; label: string; sub?: string; detail?: string; under: Anatomy[] }[] = [];
  for (const b of blocks) {
    if (b.kind === "map") {
      for (const r of b.rows) {
        // `to` is carried so the node can state the rule itself. On the engine
        // cards `from → to` IS the formula, and a card titled "dividendsTax"
        // whose subtitle only named its parent would hide the one line the
        // reader opened it for.
        if (r.under) out.push({ key: r.from, label: r.from, sub: r.to, under: r.under });
      }
    } else if (b.kind === "flow") {
      for (const r of b.rows) {
        // `detail` rides along. The card no longer renders a step's paragraph
        // when that step has somewhere to go (D24) — so if it does not land on
        // the child it lands nowhere, which is content present in the file and
        // invisible in the UI. That is the exact failure this tool exists to
        // find, and it stayed green through tsc and lint.
        if (r.under) out.push({ key: String(r.n), label: r.title, detail: r.detail, under: r.under });
      }
    }
  }
  return out;
}

/**
 * Walk the tree and give every `under`-carrying row a child node.
 *
 * Runs once at module load over the authored tree, so `nodeAt`, `levelAt`
 * and the canvas all see one uniform structure and none of them
 * needs to know a row was involved.
 */
function withRowChildren(nodes: Node[]): Node[] {
  return nodes.map((n) => {
    const authored = n.children ? withRowChildren(n.children) : [];
    // ⚠ The synthesized children are fed back through this function, NOT just
    // constructed and returned.
    //
    // A row's `under` is itself an Anatomy[], so it can hold rows that carry
    // their own `under` — which is the only way a branch reaches past three
    // levels. Building these nodes without recursing set `anatomy` correctly
    // and then never looked at it again, so the second `under` stayed data and
    // never became a node: every root measured exactly 3 levels deep however
    // deeply it was authored. The content was present in the file and
    // unreachable in the UI, which is the failure that looks most like "the
    // fixture is shallow" while being nothing of the kind.
    const fromRows = n.anatomy
      ? withRowChildren(
          deepRows(n.anatomy).map((r, i): Node => ({
            id: rowId(n.id, r.key),
            title: r.label,
            // Not authored per row: 93 of these exist. A bluprint row already
            // states the rule on its `to` side, so that becomes the subtitle —
            // on the engine cards it is literally the formula. Everything else
            // falls back to naming the card it opened out of, which is the
            // "what belongs to what" question. The generic "what happens to
            // it" it replaces said nothing on all 93.
            sub: r.sub ?? `Inside ${n.title}`,
            detail: r.detail,
            state: "derived",
            col: 0,
            row: authored.length + i,
            anatomy: r.under,
            evidence: n.evidence,
            fromRow: true,
          })),
        )
      : [];
    const children = [...authored, ...fromRows];
    return children.length ? { ...n, children } : { ...n, children: undefined };
  });
}

/**
 * Everything the screen reads, derived once from one bluprint file. Given the bluprint
 * it replaces, every part the new file left alone keeps its old identity
 * (lib/bluprint/share.ts), so a rewrite re-renders only what it changed.
 */
export function buildBluprint(file: BluprintFile, name: string, prev?: { RUN: Run; OVERVIEW?: Overview; TOP: Node }) {
  const RUN = prev ? share(prev.RUN, file.RUN) : file.RUN;
  const OVERVIEW = prev ? share(prev.OVERVIEW, file.OVERVIEW) : file.OVERVIEW;

  /** The repository as a node: the level the empty path opens, its parts the roots. */
  const built: Node = {
    state: "derived",
    ...OVERVIEW,
    id: TOP_ID,
    title: RUN.repo,
    sub: OVERVIEW?.sub ?? "",
    col: 0,
    row: 0,
    // The tree everything else reads: authored nodes, plus one node for every
    // row that carries `under`. Built once, so no consumer knows a row was
    // involved.
    children: withRowChildren(file.AUTHORED),
  };
  const TOP = prev ? share(prev.TOP, built) : built;
  const L0: Node[] = TOP.children!;

  /** Resolve a path of ids to the node it names; the empty path is the repository. */
  function nodeAt(path: string[]): Node | null {
    let found: Node | null = TOP;
    for (const id of path) {
      found = found?.children?.find((n) => n.id === id) ?? null;
      if (!found) return null;
    }
    return found;
  }

  /** The nodes shown at a given path's level — roots when the path is empty. */
  function levelAt(path: string[]): Node[] {
    return nodeAt(path)?.children ?? [];
  }

  return { name, RUN, OVERVIEW, L0, TOP, nodeAt, levelAt };
}

export type BuiltBluprint = ReturnType<typeof buildBluprint>;


/**
 * The code behind a level. A row-built level has no refs of its own; the code
 * of the nearest level above it is still the code behind it, up to the
 * repository's own.
 */
export function codeAt({ nodeAt }: BuiltBluprint, path: string[]): CodeRef[] {
  for (let i = path.length; i >= 0; i--) {
    const code = nodeAt(path.slice(0, i))?.code;
    if (code?.length) return code;
  }
  return [];
}

/** Past this a pick reads as the whole card pasted in, not a pointer to it. */
const DETAIL_CAP = 1500;

const cap = (text: string) => (text.length > DETAIL_CAP ? `${text.slice(0, DETAIL_CAP)}…` : text);

const trail = ({ nodeAt }: BuiltBluprint, path: string[]) =>
  path
    .map((_, i) => nodeAt(path.slice(0, i + 1))?.title)
    .filter(Boolean)
    .join(" › ");

/**
 * Every section's name, indented as the tree nests — what Claude reads to
 * learn what the bluprint calls things (`bluprint-list`, src-tauri/src/claude.rs).
 *
 * Titles and one-line subs only, no detail and no code: this is for choosing a
 * section to show, and a reader asking how sign-ups work is served by Claude
 * finding the one section called that, not by it reading the whole bluprint first.
 */
export function outline(m: BuiltBluprint): string {
  const lines = (nodes: Node[], depth = 0): string[] =>
    nodes.flatMap((n) => [
      `${"  ".repeat(depth)}- ${n.title}${n.sub ? ` — ${n.sub}` : ""}`,
      ...lines(n.children ?? [], depth + 1),
    ]);
  return [`${m.RUN.repo}${m.OVERVIEW?.sub ? `: ${m.OVERVIEW.sub}` : ""}`, "", ...lines(m.L0)].join("\n");
}

/**
 * One section of the bluprint as text for Claude: where it sits, what it says, and
 * the code behind it — the last so Claude reads the real thing, not only the
 * bluprint's account of it. `[]` is the repository as a whole.
 */
export function describe(m: BuiltBluprint, path: string[]): string {
  const { RUN, OVERVIEW, L0, nodeAt } = m;
  const node = path.length ? nodeAt(path) : null;
  if (!node) {
    return [
      `[Bluprint section: the whole repository (${RUN.repo})`,
      ...[OVERVIEW?.sub, OVERVIEW?.detail].filter(Boolean),
      `Its top-level sections: ${L0.map((n) => n.title).join(", ")}]`,
    ].join("\n");
  }
  const where = trail(m, path);
  const detail = node.detail && cap(node.detail);
  const code = codeAt(m, path);
  return [
    `[Bluprint section: ${where} (${RUN.repo})`,
    node.sub,
    detail,
    node.unsure ? `Not certain: ${node.unsure}` : "",
    node.issues?.length ? `Problems: ${node.issues.map((i) => i.title).join("; ")}` : "",
    code.length ? `Code:\n${code.map((c) => `- ${c.file}:${c.start}-${c.end} — ${c.label}`).join("\n")}` : "",
    node.docs?.length ? `What its docs say (read for why):\n${node.docs.map((c) => `- ${c.file}:${c.start}-${c.end} — ${c.label}`).join("\n")}` : "",
  ]
    .filter(Boolean)
    .join("\n")
    .concat("]");
}

/**
 * One thing on a level — a row, a box, a line of a screen — as text for
 * Claude: what it says, where on the bluprint it sits, and its code. With no code
 * of its own, the code behind its section is named instead.
 */
export function describeElement(m: BuiltBluprint, path: string[], label: string, text: string, code?: string): string {
  const where = path.length ? `${trail(m, path)} › ${label}` : label;
  const behind = code ? [] : codeAt(m, path);
  return [
    `[Bluprint element: ${where} (${m.RUN.repo})`,
    cap(text.trim()),
    code ? `Code: ${code}` : "",
    behind.length
      ? `Code behind its section:\n${behind.map((c) => `- ${c.file}:${c.start}-${c.end} — ${c.label}`).join("\n")}`
      : "",
  ]
    .filter(Boolean)
    .join("\n")
    .concat("]");
}

/** Lines of code to send along with a section's problems. */
export interface Span {
  file: string;
  start: number;
  end: number;
}

/** Around a problem's line: enough to see the function it sits in. */
const BEFORE = 10;
const AFTER = 20;
/** One code ref, and everything sent at once. */
const SPAN_CAP = 80;
const TOTAL_CAP = 600;
/**
 * Claude Code puts a prompt hook's output in the prompt only under about
 * 10,000 characters; past that it saves it to a file, and reading it back is
 * the call this was meant to save. Measured: 9,800 went inline, 10,200 did not.
 */
const INLINE_CAP = 9000;

/**
 * The code a section's problems point at, so it can go with them: each
 * problem's line with some around it, then the section's own code, each
 * file's ranges merged where they meet, within TOTAL_CAP lines.
 */
export function problemSpans(m: BuiltBluprint, path: string[]): Span[] {
  const node = path.length ? m.nodeAt(path) : null;
  const wanted: Span[] = [];
  for (const it of node?.issues ?? []) {
    const at = it.where?.match(/^(.+?):(\d+)(?:-(\d+))?$/);
    if (at) wanted.push({ file: at[1], start: Math.max(1, Number(at[2]) - BEFORE), end: Number(at[3] ?? at[2]) + AFTER });
  }
  for (const c of codeAt(m, path)) wanted.push({ file: c.file, start: c.start, end: Math.min(c.end, c.start + SPAN_CAP - 1) });
  const merged: Span[] = [];
  let total = 0;
  for (const s of wanted) {
    const same = merged.find((x) => x.file === s.file && s.start <= x.end + 1 && x.start <= s.end + 1);
    if (same) {
      const grown = Math.max(same.end, s.end) - Math.min(same.start, s.start) + 1;
      if (total - (same.end - same.start + 1) + grown > TOTAL_CAP) continue;
      total += grown - (same.end - same.start + 1);
      same.start = Math.min(same.start, s.start);
      same.end = Math.max(same.end, s.end);
    } else if (total + (s.end - s.start + 1) <= TOTAL_CAP) {
      merged.push({ ...s });
      total += s.end - s.start + 1;
    }
  }
  return merged;
}

/**
 * A section's problems as text for an agent: every one in full — what goes
 * wrong and where — then the section they belong to and its code. With the
 * code itself (`source`, read from problemSpans), it goes along numbered, so
 * the agent can answer from it rather than spend calls finding it.
 */
export function describeProblems(m: BuiltBluprint, path: string[], source: (Span & { code: string })[] = []): string {
  const node = path.length ? m.nodeAt(path) : null;
  const issues = node?.issues ?? [];
  const code = codeAt(m, path);
  const head = [
    `[Bluprint problems: ${trail(m, path)} (${m.RUN.repo})`,
    `The bluprint found ${issues.length} ${issues.length === 1 ? "problem" : "problems"} here:`,
    ...issues.map((it, i) => `${i + 1}. ${it.title} — ${it.detail}${it.where ? ` (${it.where})` : ""}`),
    node?.sub ? `The section: ${node.sub}` : "",
    code.length ? `Code:\n${code.map((c) => `- ${c.file}:${c.start}-${c.end} — ${c.label}`).join("\n")}` : "",
  ]
    .filter(Boolean)
    .join("\n");
  // The code, in order — problems' lines first — while it stays inline; the
  // range that would cross the line is cut short, and the rest left out.
  let room = INLINE_CAP - head.length - 60;
  const blocks: string[] = [];
  for (const s of source) {
    const lines = s.code.split("\n").map((l, i) => `${String(s.start + i).padStart(5)}  ${l}`);
    const kept: string[] = [];
    for (const l of lines) {
      if (l.length + 1 > room - s.file.length - 30) break;
      kept.push(l);
      room -= l.length + 1;
    }
    if (!kept.length) break;
    blocks.push(`${s.file}:${s.start}-${s.start + kept.length - 1}\n\`\`\`\n${kept.join("\n")}\n\`\`\``);
    room -= s.file.length + 30;
    if (kept.length < lines.length) break;
  }
  return (blocks.length ? `${head}\nThe code they point at, as it is now:\n${blocks.join("\n")}` : head).concat("]");
}

app/lib/bluprint/coverage.ts:
/**
 * How much of the repository the bluprint explains, and where each line of it is
 * explained — one definition shared by the generator, which holds a root to
 * it, and the app, which finds things with it.
 *
 * A line counts as explained only where the reader can open it: a leaf's own
 * code, or the lines a step or message cites (D67, D68). Refs above a leaf
 * back its claims but are never shown, so citing a whole file on a root says
 * nothing about whether anyone can find a function in it.
 */
import type { Anatomy, Node } from "@/lib/bluprint/schema";

/** One top-level thing in a file, as the summary named it. */
export interface Sym {
  name: string;
  start: number;
  end: number;
  does: string;
}

/** What the bluprint knows about one file of the checkout, explained or not. */
export interface IndexFile {
  /** The roots that own it, by the cut. */
  roots: string[];
  /** `source` must be explained; `excluded` was left out with `reason`; `other` is tests, config, docs or assets. */
  status: "source" | "excluded" | "other";
  reason?: string;
  kind?: string;
  purpose?: string;
  lines: number;
  symbols: Sym[];
}

/** `<out>/index.json`: every file of the checkout, written beside bluprint.json. */
export interface BluprintIndex {
  commit: string;
  files: Record<string, IndexFile>;
  /** Which code file uses which, every language (scripts/generate/imports.ts). Absent on bluprints made before it. */
  imports?: Record<string, string[]>;
}

/** One span the reader can open, and the level that opens it. */
export interface Citation {
  file: string;
  start: number;
  end: number;
  /** Node ids from the root down to the level citing it. */
  path: string[];
}

/** Shorter than this is a constant or a re-export: listed, never required. */
export const TRIVIAL_LINES = 3;

const AT = /^(.+):(\d+)(?:-(\d+))?$/;

/** Every step's and message's `at`, however deep under `under`. Diagram arrows are not drawn as code, so they do not count. */
function stepsIn(blocks: Anatomy[] | undefined, out: Omit<Citation, "path">[]) {
  const visit = (v: unknown) => {
    if (Array.isArray(v)) return v.forEach(visit);
    if (!v || typeof v !== "object") return;
    const o = v as Record<string, unknown>;
    const m = typeof o.at === "string" && ("title" in o || "from" in o) ? AT.exec(o.at) : null;
    if (m) out.push({ file: m[1], start: +m[2], end: +(m[3] ?? m[2]) });
    for (const x of Object.values(o)) if (x && typeof x === "object") visit(x);
  };
  for (const b of blocks ?? []) if (b.kind !== "diagram") visit(b);
}

/** Every span the reader can open, by file. */
export function citations(roots: Node[]): Map<string, Citation[]> {
  const out = new Map<string, Citation[]>();
  const walk = (n: Node, path: string[]) => {
    const here: Omit<Citation, "path">[] = [];
    if (!n.children?.length) for (const c of n.code ?? []) here.push({ file: c.file, start: c.start, end: c.end });
    stepsIn(n.anatomy, here);
    for (const c of here) out.set(c.file, [...(out.get(c.file) ?? []), { ...c, path }]);
    for (const c of n.children ?? []) walk(c, [...path, c.id]);
  };
  for (const r of roots) walk(r, [r.id]);
  return out;
}

/** The levels that open a line (or any of a span), deepest first. */
export function nodesAt(cited: Map<string, Citation[]>, file: string, start: number, end = start): Citation[] {
  return (cited.get(file) ?? []).filter((c) => c.start <= end && c.end >= start).sort((a, b) => b.path.length - a.path.length);
}

export const required = (s: Sym) => s.end - s.start + 1 > TRIVIAL_LINES;

/** A file's symbols, each with the levels that open it. */
export function symbolsOf(cited: Map<string, Citation[]>, file: string, f: Pick<IndexFile, "symbols">) {
  return f.symbols.map((s) => ({ ...s, by: nodesAt(cited, file, s.start, s.end) }));
}

/** Required symbols explained, over the files that must be explained. */
export function coverage(index: BluprintIndex, roots: Node[]) {
  const cited = citations(roots);
  let symbols = 0;
  let explained = 0;
  const gaps: { file: string; symbol: Sym }[] = [];
  for (const [file, f] of Object.entries(index.files)) {
    if (f.status !== "source") continue;
    for (const s of symbolsOf(cited, file, f)) {
      if (!required(s)) continue;
      symbols++;
      if (s.by.length) explained++;
      else gaps.push({ file, symbol: s });
    }
  }
  const files = Object.values(index.files);
  return { symbols, explained, gaps, excluded: files.filter((f) => f.status === "excluded").length, cited };
}

/** One link across a section's edge: the section that explains the other side (null when none does), and an import that makes it. */
export interface Link {
  path: string[] | null;
  /** The other side's file when no section explains it. */
  file: string;
  /** `from → to`, one import behind the link. */
  via: string;
  /** How many imports make it. */
  count: number;
}

/**
 * What a section's code uses and what uses it, by the import graph, each
 * named by the section that explains the other side: what a change here
 * reaches, and what it rests on. Empty on a bluprint whose index has no imports.
 */
export function neighbours(roots: Node[], index: BluprintIndex | null, path: string[]): { uses: Link[]; usedBy: Link[] } {
  const imports = index?.imports;
  if (!imports || !path.length) return { uses: [], usedBy: [] };
  const cited = citations(roots);
  const under = (p: string[]) => p.length >= path.length && path.every((x, i) => p[i] === x);
  const mine = new Set<string>();
  for (const [file, cs] of cited) if (cs.some((c) => under(c.path))) mine.add(file);
  if (path.length === 1) for (const [file, f] of Object.entries(index.files)) if (f.roots.includes(path[0]) && f.status === "source") mine.add(file);
  // The section that explains a file whole: in the root citing it most, the deepest level over all its citations there.
  const explainer = (file: string): string[] | null => {
    const outside = (cited.get(file) ?? []).filter((c) => !under(c.path));
    if (!outside.length) {
      const root = index.files[file]?.roots.find((r) => r !== path[0] && roots.some((n) => n.id === r));
      return root ? [root] : null;
    }
    const by = new Map<string, Citation[]>();
    for (const c of outside) by.set(c.path[0], [...(by.get(c.path[0]) ?? []), c]);
    const most = [...by.values()].sort((a, b) => b.length - a.length)[0];
    return most.reduce((common, c) => {
      let i = 0;
      while (i < common.length && i < c.path.length && common[i] === c.path[i]) i++;
      return common.slice(0, i);
    }, most[0].path);
  };
  const collect = (pairs: [string, string, string][]): Link[] => {
    const out = new Map<string, Link>();
    for (const [other, from, to] of pairs) {
      const p = explainer(other);
      if (p && under(p)) continue;
      const key = p ? p.join("/") : other;
      const l = out.get(key);
      if (l) l.count++;
      else out.set(key, { path: p, file: other, via: `${from} → ${to}`, count: 1 });
    }
    return [...out.values()].sort((a, b) => b.count - a.count);
  };
  const uses: [string, string, string][] = [];
  const usedBy: [string, string, string][] = [];
  for (const [a, bs] of Object.entries(imports))
    for (const b of bs) {
      if (mine.has(a) && !mine.has(b)) uses.push([b, a, b]);
      if (mine.has(b) && !mine.has(a)) usedBy.push([a, a, b]);
    }
  return { uses: collect(uses), usedBy: collect(usedBy) };
}

app/lib/bluprint/diagram.ts:
import type { Anatomy, DiagramArrow, DiagramBox } from "@/lib/bluprint/schema";

/**
 * Where everything in a diagram goes, as plain numbers: the component draws
 * it, and `scripts/generate/audit-diagrams.mts` checks every bluprint's diagrams
 * for text drawn over text without opening a browser. Text widths are
 * estimated from character counts, which is close enough at these fixed sizes.
 */

export const BOX_H = 58;
const ROW_GAP = 40;
const COL_GAP = 76;
const PAD = 18;
const LANE_GAP = 12;
/** Two arrows running opposite ways down one column sit this far apart. */
const PAIR_GAP = 7;
const LABEL_CHAR = 6.6;
const LABEL_H = 14;

type Block = Extract<Anatomy, { kind: "diagram" }>;
type Placed = { x: number; y: number; w: number };
export type Rect = { x: number; y: number; w: number; h: number };
export type PlacedBox = Placed & { b: DiagramBox };
export type PlacedArrow = {
  from: string;
  to: string;
  d: string;
  tone: NonNullable<DiagramArrow["tone"]>;
  label?: { text: string; x: number; y: number; anchor: "start" | "middle" | "end" };
};

function labelRect(l: NonNullable<PlacedArrow["label"]>): Rect {
  const w = l.text.length * LABEL_CHAR;
  const x = l.anchor === "start" ? l.x : l.anchor === "middle" ? l.x - w / 2 : l.x - w;
  return { x, y: l.y - 11, w, h: LABEL_H };
}

export const overlaps = (a: Rect, b: Rect) =>
  a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;

export function layoutDiagram(block: Block) {
  const cols = Math.max(...block.boxes.map((b) => b.col)) + 1;
  const rows = Math.max(...block.boxes.map((b) => b.row)) + 1;
  // Each column is as wide as its longest label.
  const colW = Array.from({ length: cols }, (_, c) =>
    Math.max(
      150,
      ...block.boxes
        .filter((b) => b.col === c)
        .map((b) => Math.max(b.label.length * 8.4, (b.sub?.length ?? 0) * LABEL_CHAR) + 32),
    ),
  );
  // The gap between columns is as wide as the longest straight-across label
  // that has to sit in it; a fixed 76px clipped any label past ten characters
  // under the next box. Elbow labels sit between rows, clear of the boxes, so
  // they need no room here. Capped, so one label cannot push the picture off
  // the page.
  const gap = Math.min(
    260,
    Math.max(
      COL_GAP,
      ...block.arrows.map((a) => {
        const f = block.boxes.find((b) => b.id === a.from);
        const t = block.boxes.find((b) => b.id === a.to);
        if (!a.label || !f || !t || f.col === t.col || f.row !== t.row) return 0;
        return a.label.length * LABEL_CHAR + 28;
      }),
    ),
  );
  const colX = colW.map((_, c) => PAD + colW.slice(0, c).reduce((a, w) => a + w + gap, 0));
  let W = colX[cols - 1] + colW[cols - 1] + PAD;
  let H = PAD * 2 + rows * BOX_H + (rows - 1) * ROW_GAP;
  // Below the bottom row: the way round for a line that has no other, such as
  // one row's last box back to its first, and the picture grows to hold it.
  const under = H - PAD + ROW_GAP / 2;
  const at = new Map<string, PlacedBox>(
    block.boxes.map((b) => [b.id, { x: colX[b.col], y: PAD + b.row * (BOX_H + ROW_GAP), w: colW[b.col], b }]),
  );

  // Arrows between the same two boxes the same way are one line: their labels
  // are joined rather than drawn on the same spot (the overlap a reader
  // reported, "sidebar link" over "post dropdown").
  const merged: (DiagramArrow & { labels: string[] })[] = [];
  for (const a of block.arrows) {
    if (!at.has(a.from) || !at.has(a.to)) continue;
    const same = merged.find((m) => m.from === a.from && m.to === a.to);
    if (same) {
      if (a.label && !same.labels.includes(a.label)) same.labels.push(a.label);
      continue;
    }
    merged.push({ ...a, labels: a.label ? [a.label] : [] });
  }

  const boxRects: Rect[] = [...at.values()].map(({ x, y, w }) => ({ x, y, w, h: BOX_H }));
  // Where a line may run clear of every box: down the middle of each gap
  // between columns, and along the middle of each gap between rows.
  const gx = colX.slice(1).map((x) => x - gap / 2);
  const gy = Array.from({ length: rows - 1 }, (_, r) => PAD + (r + 1) * (BOX_H + ROW_GAP) - ROW_GAP / 2);
  const lanes = laneOffsets(merged, at);
  const drawn: { seg: Rect; from: string; to: string }[] = [];
  const routes = merged.map((a, i) => {
    const f = at.get(a.from)!;
    const t = at.get(a.to)!;
    // A and B in one column, arrows both ways: side by side, not one line.
    const back = f.x === t.x && merged.some((m) => m.from === a.to && m.to === a.from);
    const first = route(f, t, gap, back ? (t.y > f.y ? -PAIR_GAP : PAIR_GAP) : (lanes.get(i) ?? 0));
    // The plain route unless it cuts through a box or runs along another
    // arrow's line; then the cheapest detour that does neither. A fan-out or
    // fan-in sharing its trunk is the bundle reading as one, so it is free.
    const cost = (pts: Pt[], bonus = 0) => {
      const segs = segmentsOf(pts);
      let c = bonus;
      for (const s of segs) {
        c += s.w + s.h + 30;
        for (const b of boxRects) if (overlaps(s, inset(b))) c += 10000;
        for (const o of drawn) if (o.from !== a.from && o.to !== a.to) c += 20 * collinear(s, o.seg);
      }
      return c;
    };
    let best = { pts: first, c: cost(first, -20) };
    for (const pts of detours(f, t, gx, gy)) {
      const c = cost(pts);
      if (c < best.c) best = { pts, c };
    }
    if (segmentsOf(best.pts).some((s) => boxRects.some((b) => overlaps(s, inset(b)))))
      for (const pts of detours(f, t, [], [under])) {
        const c = cost(pts);
        if (c < best.c) [best, H] = [{ pts, c }, under + PAD];
      }
    for (const seg of segmentsOf(best.pts)) drawn.push({ seg, from: a.from, to: a.to });
    return best;
  });

  const arrows: PlacedArrow[] = merged.map((a, i) => ({
    from: a.from,
    to: a.to,
    d: `M${routes[i].pts.map((p) => p.join(" ")).join("L")}`,
    tone: a.tone ?? "plain",
    // Placed below, once every line is down.
    label: a.labels.length ? { text: a.labels.join(" · "), x: 0, y: 0, anchor: "start" as const } : undefined,
  }));

  // A label that lands on a box, another label or another arrow's line
  // moves until it is clear, to the nearest spot still beside its own line.
  const taken: Rect[] = [];
  const W0 = W;
  const runsOf = routes.map((r) => segmentsOf(r.pts));
  arrows.forEach((a, i) => {
    if (!a.label) return;
    const others = drawn.filter((d) => d.from !== a.from || d.to !== a.to).map((d) => d.seg);
    // Text on text or on a box is unreadable; text across a line is drawn
    // with a halo and stays legible, so it is only a mild cost.
    const clashes = (r: Rect) => {
      const room = { x: r.x - 3, y: r.y - 3, w: r.w + 6, h: r.h + 6 };
      // Past the right edge widens the picture, which can push it into a
      // scroll that hides the label's end: better on the line's other side.
      const out = (r.y < 0 || r.y + r.h > H || r.x < 0 ? 1000 : 0) + (r.x + r.w + PAD > W0 ? 50 : 0);
      return out + 100 * [...boxRects, ...taken].filter((o) => overlaps(room, o)).length + others.filter((o) => overlaps(room, o)).length;
    };
    // A run another arrow also draws — a fan-in's trunk — names none of them,
    // so a label goes on a run that is this arrow's alone when it can.
    const shared = runsOf[i].map((s) => runsOf.some((rs, j) => j !== i && rs.some((o) => collinear(s, o) > 4)));
    const spots = spotsOn(routes[i].pts, a.label.text.length * LABEL_CHAR, shared);
    let fit = spots[0], least = Infinity;
    for (const s of spots) {
      // Beside a shared run is a last resort: worse than crossing a line.
      const c = clashes(labelRect({ ...a.label, ...s })) + (s.shared ? 5 : 0);
      if (c < least) [fit, least] = [s, c];
      if (!c) break;
    }
    Object.assign(a.label, { x: fit.x, y: fit.y, anchor: fit.anchor });
    const r = labelRect(a.label);
    taken.push(r);
    W = Math.max(W, r.x + r.w + PAD);
  });

  return { W, H, gap, boxes: [...at.values()], boxRects, arrows, labels: taken };
}

type Pt = [number, number];
type Label = { x: number; y: number; anchor: "start" | "middle" | "end"; shared?: boolean };

/** The straight runs of a polyline, as zero-thickness rects. */
export function segmentsOf(pts: Pt[]): Rect[] {
  return pts.slice(1).map(([x, y], i) => {
    const [px, py] = pts[i];
    return { x: Math.min(x, px), y: Math.min(y, py), w: Math.abs(x - px) || 0.1, h: Math.abs(y - py) || 0.1 };
  });
}

const inset = (b: Rect): Rect => ({ x: b.x + 1, y: b.y + 1, w: b.w - 2, h: b.h - 2 });

/** How far two runs lie along the same line. */
function collinear(a: Rect, b: Rect) {
  const horiz = (r: Rect) => r.h < 1;
  if (horiz(a) !== horiz(b)) return 0;
  if (horiz(a)) return Math.abs(a.y - b.y) < 4 ? Math.max(0, Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x)) : 0;
  return Math.abs(a.x - b.x) < 4 ? Math.max(0, Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y)) : 0;
}

/**
 * Every place a label can sit and still read as this line's: beside a run,
 * slid along it or on its other side — never off it, where it would be read
 * as naming whatever line is nearest. Runs no other arrow shares come first,
 * longest first; a short one takes its label at either end, beside the box
 * it leaves or enters, rather than centred over the line it joins.
 */
function spotsOn(pts: Pt[], width: number, shared: boolean[]): Label[] {
  const runs = pts.slice(1).map(([x2, y2], i) => ({ x1: pts[i][0], y1: pts[i][1], x2, y2, len: Math.abs(x2 - pts[i][0]) + Math.abs(y2 - pts[i][1]), shared: Boolean(shared[i]) }));
  return runs
    .sort((a, b) => Number(a.shared) - Number(b.shared) || b.len - a.len)
    .flatMap(({ x1, y1, x2, y2, len, shared }): Label[] => spotsBeside(x1, y1, x2, y2, len, width).map((l) => ({ ...l, shared })));
}

/** Beside one run: slid along it or on its other side. */
function spotsBeside(x1: number, y1: number, x2: number, y2: number, len: number, width: number): Label[] {
  if (x1 === x2) {
    const mid = (y1 + y2) / 2 + 4;
    const room = Math.max(0, len / 2 - 10);
    return [0, -14, 14, -28, 28, -42, 42]
      .filter((d) => Math.abs(d) <= room)
      .flatMap((d): Label[] => [{ x: x1 + 8, y: mid + d, anchor: "start" }, { x: x1 - 8, y: mid + d, anchor: "end" }]);
  }
  const mid = (x1 + x2) / 2;
  const room = Math.max(0, (len - width) / 2);
  const right = x2 > x1;
  const ends: Label[] =
    len < width + 16
      ? [y1 - 6, y1 + 15].flatMap((y): Label[] => [
          { x: x1 + (right ? 4 : -4), y, anchor: right ? "start" : "end" },
          { x: x2 + (right ? -6 : 6), y, anchor: right ? "end" : "start" },
        ])
      : [];
  return [
    ...[0, -30, 30, -60, 60, -90, 90]
      .filter((d) => Math.abs(d) <= room)
      .flatMap((d): Label[] => [{ x: mid + d, y: y1 - 6, anchor: "middle" }, { x: mid + d, y: y1 + 15, anchor: "middle" }]),
    ...ends,
  ];
}

/**
 * The other ways from one box to another: out a side, down a column gap and
 * in a side; or out the top or bottom, along a row gap and in the top or
 * bottom.
 */
function detours(f: Placed, t: Placed, gx: number[], gy: number[]): Pt[][] {
  const out: Pt[][] = [];
  const fy = f.y + BOX_H / 2;
  const ty = t.y + BOX_H / 2;
  for (const g of gx) {
    const x1 = g > f.x ? f.x + f.w : f.x;
    const x2 = g > t.x ? t.x + t.w + 2 : t.x - 2;
    out.push([[x1, fy], [g, fy], [g, ty], [x2, ty]]);
  }
  const fc = f.x + f.w / 2;
  const tc = t.x + t.w / 2;
  if (fc !== tc)
    for (const g of gy) {
      const y1 = g > f.y ? f.y + BOX_H : f.y;
      const y2 = g > t.y ? t.y + BOX_H + 2 : t.y - 2;
      out.push([[fc, y1], [fc, g], [tc, g], [tc, y2]]);
    }
  return out;
}

/**
 * Elbow arrows that run down the same gap between columns would draw on top
 * of each other. A fan-out from one box, or a fan-in to one box, SHOULD share
 * its trunk — that is what makes it read as one bundle — so arrows are
 * grouped into bundles per gap and each bundle gets its own lane.
 */
function laneOffsets(arrows: { from: string; to: string }[], at: Map<string, Placed>) {
  const gaps = new Map<string, { i: number; from: string; to: string }[]>();
  arrows.forEach((a, i) => {
    const f = at.get(a.from);
    const t = at.get(a.to);
    if (!f || !t || f.x === t.x || f.y === t.y) return;
    const key = t.x > f.x ? `r${f.x + f.w}` : `l${f.x}`;
    gaps.set(key, [...(gaps.get(key) ?? []), { i, from: a.from, to: a.to }]);
  });
  const out = new Map<number, number>();
  for (const list of gaps.values()) {
    const count = (k: "from" | "to", v: string) => list.filter((x) => x[k] === v).length;
    const bundleOf = (x: { from: string; to: string }) =>
      count("from", x.from) > 1 ? `f:${x.from}` : count("to", x.to) > 1 ? `t:${x.to}` : `a:${x.from}>${x.to}`;
    const bundles = [...new Set(list.map(bundleOf))];
    for (const x of list) {
      const b = bundles.indexOf(bundleOf(x));
      out.set(x.i, (b - (bundles.length - 1) / 2) * LANE_GAP);
    }
  }
  return out;
}

/**
 * The plain right-angled path between two boxes. Same column: straight down
 * (or up), shifted sideways by `lane`. Otherwise out of the facing side,
 * along the gap between columns, and in.
 */
function route(f: Placed, t: Placed, gap: number, lane = 0): Pt[] {
  const fy = f.y + BOX_H / 2;
  const ty = t.y + BOX_H / 2;
  if (f.x === t.x) {
    const down = t.y > f.y;
    const y1 = down ? f.y + BOX_H : f.y;
    const y2 = down ? t.y - 2 : t.y + BOX_H + 2;
    const cx = f.x + f.w / 2 + lane;
    return [[cx, y1], [cx, y2]];
  }
  const right = t.x > f.x;
  const x1 = right ? f.x + f.w : f.x;
  const x2 = right ? t.x - 2 : t.x + t.w + 2;
  if (fy === ty) return [[x1, fy], [x2, fy]];
  const mx = (right ? x1 + gap / 2 : x1 - gap / 2) + lane;
  return [[x1, fy], [mx, fy], [mx, ty], [x2, ty]];
}

app/lib/bluprint/lookup.ts:
/**
 * The bluprint as Claude reads it through its tools (src-tauri/src/mcp.rs):
 * searching it, opening one section, and asking which section explains a
 * file or line. Plain text, because the reader of it is a model choosing what
 * to read next, and every answer names sections by the id path that
 * `bluprint-show section` and plans take, so what Claude finds it can show.
 */
import { findSection } from "@/lib/agent/act";
import { citations, neighbours, nodesAt, symbolsOf, type Link, type BluprintIndex } from "@/lib/bluprint/coverage";
import type { Anatomy, Node } from "@/lib/bluprint/schema";
import { describe, type BuiltBluprint } from "@/lib/bluprint/build";

const trailOf = (m: BuiltBluprint, path: string[]) => path.map((_, i) => m.nodeAt(path.slice(0, i + 1))?.title ?? path[i]).join(" › ");
const named = (m: BuiltBluprint, path: string[]) => `${trailOf(m, path)} [${path.join("/")}]`;

/** Sections whose words match, then symbols and files by name: what to open next. */
export function bluprintSearch(m: BuiltBluprint, index: BluprintIndex | null, query: string): string {
  const q = query.trim().toLowerCase();
  if (!q) return "Give a query: words from what you are looking for, a symbol, or a path.";
  const levels: { path: string[]; score: number }[] = [];
  const walk = (nodes: Node[], at: string[]) => {
    for (const n of nodes) {
      const p = [...at, n.id];
      const title = n.title.toLowerCase();
      const body = [n.sub, n.detail, n.explain?.body].join(" ").toLowerCase();
      const score = title.includes(q) ? 3 : q.split(/\s+/).every((w) => title.includes(w)) ? 2 : body.includes(q) ? 1 : 0;
      if (score) levels.push({ path: p, score });
      walk(n.children ?? [], p);
    }
  };
  walk(m.L0, []);
  levels.sort((a, b) => b.score - a.score || b.path.length - a.path.length);
  const cited = citations(m.L0);
  const code: string[] = [];
  for (const [file, f] of Object.entries(index?.files ?? {})) {
    for (const s of symbolsOf(cited, file, f))
      if (s.name.toLowerCase().includes(q)) code.push(`- ${s.name} (${file}:${s.start}-${s.end}) → ${s.by[0] ? named(m, s.by[0].path) : "not explained by any section"}`);
    if (file.toLowerCase().includes(q)) {
      const by = (cited.get(file) ?? []).sort((a, b) => b.path.length - a.path.length)[0];
      code.push(`- ${file} → ${by ? named(m, by.path) : f.status === "excluded" ? `left out of the bluprint: ${f.reason ?? ""}` : "not explained by any section"}`);
    }
  }
  const out = [
    levels.length ? `Sections:\n${levels.slice(0, 12).map((l) => `- ${named(m, l.path)} — ${m.nodeAt(l.path)?.sub ?? ""}`).join("\n")}` : "",
    code.length ? `Code:\n${code.slice(0, 15).join("\n")}` : "",
  ].filter(Boolean);
  return out.length ? out.join("\n\n") : `Nothing on the bluprint matches "${query}".`;
}

const at = (x: { at?: string }) => (x.at ? ` (${x.at})` : "");
const ROWS = 20;

/**
 * A block as text: the picture's facts, each with the line it cites. Without
 * them a reader of the section got its two sentences and had to open the code
 * for what the level already drew (kafka: bluprint-only answers ran out of turns).
 */
function blockText(b: Anatomy): string {
  const head = "caption" in b && b.caption ? `${b.caption}: ` : "";
  const list = (xs: string[]) => xs.slice(0, ROWS).join("\n") + (xs.length > ROWS ? `\n… ${xs.length - ROWS} more` : "");
  switch (b.kind) {
    case "diagram": {
      const label = (id: string) => b.boxes.find((x) => x.id === id)?.label ?? id;
      return `${head}diagram\n${list(b.arrows.map((a) => `- ${label(a.from)} → ${label(a.to)}${a.label ? `: ${a.label}` : ""}${at(a)}`))}`;
    }
    case "flow": return `${head}steps\n${list(b.rows.map((r, i) => `${i + 1}. ${r.title} — ${r.detail}${at(r)}`))}`;
    case "sequence": return `${head}sequence\n${list(b.rows.map((r) => `- ${r.from} → ${r.to}: ${r.label}${at(r)}`))}`;
    case "table": return `${head}table (${b.columns.join(" | ")})\n${list(b.rows.map((r) => `- ${r.join(" | ")}`))}`;
    case "schema": return `${b.table}: schema\n${list(b.rows.map((c) => `- ${c.name}: ${c.type}${c.key ? ` ${c.key}` : ""}${c.note ? ` — ${c.note}` : ""}`))}`;
    case "routes": return `routes\n${list(b.rows.map((r) => `- ${r.method} ${r.path} (${r.auth})${r.note ? ` — ${r.note}` : ""}`))}`;
    case "facts": return `facts\n${list(b.rows.map((r) => `- ${r.label}: ${r.value}`))}`;
    case "map": return `${head}mapping\n${list(b.rows.map((r) => `- ${r.from} → ${r.to}`))}`;
    case "chips": return `${head}${b.rows.map((r) => r.label).join(", ")}`;
    case "screen": return `screen ${b.title}${b.route ? ` at ${b.route}` : ""}\n${list(b.items.map((x) => `- ${x.type} ${x.label}${x.when ? ` (when ${x.when})` : ""}${x.note ? ` — ${x.note}` : ""}${x.at ? ` [${x.at}]` : ""}`))}`;
    case "example": return `${head}example\n${b.value.slice(0, 800)}`;
    default: return "";
  }
}

const linked = (m: BuiltBluprint, ls: Link[]) => ls.slice(0, 12).map((l) => `- ${l.path ? named(m, l.path) : `${l.file} (no section explains it)`} — ${l.via}${l.count > 1 ? ` and ${l.count - 1} more` : ""}`).join("\n");

/** One section as `describe` gives it, with what it draws, what it uses and what uses it, and its parts listed so Claude can go deeper. */
export function bluprintSection(m: BuiltBluprint, name: string, index: BluprintIndex | null = null): string {
  const path = name.trim() ? findSection(m, name) : [];
  if (!path) return `No section is called "${name}". Use bluprint_search to find one.`;
  const node = path.length ? m.nodeAt(path) : null;
  const parts = (node ? node.children : m.L0) ?? [];
  const blocks = ((node ?? m.OVERVIEW)?.anatomy ?? []).map(blockText).filter(Boolean);
  const { uses, usedBy } = neighbours(m.L0, index, path);
  return [
    describe(m, path),
    path.length ? `Id path: ${path.join("/")}` : "",
    blocks.length ? `What it shows:\n${blocks.join("\n\n")}` : "",
    uses.length ? `Uses (its code imports):\n${linked(m, uses)}` : "",
    usedBy.length ? `Used by (what a change here reaches):\n${linked(m, usedBy)}` : "",
    parts.length ? `Its parts:\n${parts.map((c) => `- ${c.title} [${[...path, c.id].join("/")}] — ${c.sub}`).join("\n")}` : "",
    node?.issues?.length ? `Watch out:\n${node.issues.map((i) => `- ${i.title}: ${i.detail}${i.where ? ` (${i.where})` : ""}`).join("\n")}` : "",
  ]
    .filter(Boolean)
    .join("\n\n");
}

/** The files that import a file, each with the section that explains it. */
function importers(m: BuiltBluprint, index: BluprintIndex | null, file: string): string {
  const from = Object.entries(index?.imports ?? {}).filter(([, bs]) => bs.includes(file)).map(([a]) => a);
  if (!from.length) return "";
  const cited = citations(m.L0);
  const rows = from.slice(0, 12).map((a) => {
    const by = (cited.get(a) ?? []).slice().sort((x, y) => x.path.length - y.path.length)[0];
    return `- ${a}${by ? ` → ${named(m, by.path)}` : ""}`;
  });
  return `\n\nImported by ${from.length} file${from.length > 1 ? "s" : ""}:\n${rows.join("\n")}${from.length > 12 ? `\n… ${from.length - 12} more` : ""}`;
}

/** The sections that open a file, or a line of it, deepest first; or why none does. */
export function bluprintWhere(m: BuiltBluprint, index: BluprintIndex | null, file: string, line?: number): string {
  // Claude often names a file by its absolute path.
  const root = m.RUN.root?.replace(/\/$/, "");
  const path = (root && file.startsWith(`${root}/`) ? file.slice(root.length + 1) : file).replace(/^\.?\//, "");
  const cited = citations(m.L0);
  const hits = line ? nodesAt(cited, path, line) : (cited.get(path) ?? []).slice().sort((a, b) => b.path.length - a.path.length);
  const seen = new Set<string>();
  const levels = hits.filter((c) => !seen.has(c.path.join("/")) && seen.add(c.path.join("/")));
  if (levels.length) return `${path}${line ? `:${line}` : ""} is explained by:\n${levels.slice(0, 8).map((c) => `- ${named(m, c.path)} (cites ${c.start}-${c.end})`).join("\n")}${importers(m, index, path)}`;
  const f = index?.files[path];
  const inFile = cited.get(path) ?? [];
  const near = line ? inFile.slice().sort((a, b) => Math.min(Math.abs(a.start - line), Math.abs(a.end - line)) - Math.min(Math.abs(b.start - line), Math.abs(b.end - line)))[0] : inFile[0];
  if (!f && near) return `No section opens ${path}:${line}. Nearest in this file: ${named(m, near.path)} (cites ${near.start}-${near.end}).`;
  if (!f) return `${path} is not on the bluprint: it is not in the checkout the bluprint was made from (new since, or not a file).`;
  if (f.status === "excluded") return `${path} was left out of the bluprint: ${(f.reason ?? "no reason recorded").replace(/\.$/, "")}.`;
  if (f.status === "other") return `${path} is ${f.kind ?? "not source"}, which the bluprint does not explain.`;
  const roots = f.roots.map((r) => m.L0.find((n) => n.id === r)?.title ?? r).join(", ");
  return `No section opens ${path}${line ? `:${line}` : ""}.${near ? ` Nearest in this file: ${named(m, near.path)}.` : ""}${roots ? ` It belongs to ${roots}.` : ""}${importers(m, index, path)}`;
}

app/lib/bluprint/schema.ts:
/**
 * The bluprint's schema: the shape of the bluprint.json a generator run writes
 * (scripts/generate) and every part of the app reads.
 *
 * The bluprint is organised by CONCEPT, not by file. Someone new to a codebase asks
 * "how does billing work" and "what's in the database", not "what's in
 * identity.ts". Files appear only at the bottom, as the evidence for a claim.
 *
 * Every fact carries a state. `derived` is resolved by the TypeScript compiler
 * or read straight out of a migration; `partial` was found but the analysis
 * knows it is incomplete (and says why); `inferred` is a guess from naming or
 * layout and is never presented as fact.
 */

import type { Shape } from "@/lib/bluprint/view";

export type State = "derived" | "partial" | "inferred";

/* ── anatomy: level 2 renders in the SHAPE of the thing ───────
   A database capability shows columns. An API capability shows routes. A
   pipeline shows ordered steps. One prose paragraph for all three would throw
   away the structure that makes each legible. */

export interface Column {
  name: string;
  type: string;
  key?: "PK" | "FK" | "UQ";
  nullable?: boolean;
  state: State;
  note?: string;
}

export interface Route {
  method: "GET" | "POST" | "PATCH" | "DELETE";
  path: string;
  auth: string;
  state: State;
  note?: string;
}

export interface Step {
  n: number;
  title: string;
  detail: string;
  state: State;
  /**
   * `file:start-end` (or `file:line`): the lines where this step happens. The
   * reader clicks the step to see them, so the code arrives attached to the
   * sentence that explains it rather than in a list at the bottom. On a leaf
   * every step has one, usually inside the leaf's own `code`.
   */
  at?: string;
  /** What happens inside this step. Same contract as `Mapping.under`. */
  under?: Anatomy[];
}

export interface Pair {
  label: string;
  value: string;
  state: State;
}

/**
 * The bottom of the bluprint. Real source, quoted verbatim from a real file at a
 * real line — never paraphrased, never reconstructed from memory. `why` is the
 * one place a synthesized explanation is allowed, and it is separated from the
 * code so nobody mistakes the commentary for the thing itself.
 */
export interface Source {
  kind: "source";
  /** Repo-relative path. */
  file: string;
  /** Line number of `code`'s first line, so the gutter tells the truth. */
  start: number;
  /** Verbatim. Leading indentation preserved. */
  code: string;
  /** Why it is this way. Synthesized — rendered as commentary, not as fact. */
  why?: string;
}

/**
 * A quantity worth comparing. `value` is what draws the bar; `display` is what
 * a human reads, because "40 per day, 10 per hour" is the fact and 40 is only
 * the part of it that has a length.
 */
export interface Bar {
  label: string;
  value: number;
  display: string;
  state: State;
  note?: string;
}

/**
 * One slice of a whole. Used where the RATIO is the finding — three prompt
 * blocks whose sizes are the entire reason the split exists read as a bar in
 * one glance and as an essay in three rows.
 */
export interface Part {
  label: string;
  weight: number;
  display: string;
  /** Tints the slice: the thing being contrasted, not decoration. */
  tone?: "hold" | "vary";
  state: State;
}

/** One accepted kind of thing. The label IS the content; no sentence needed. */
export interface Chip {
  label: string;
  note?: string;
  state: State;
}

/** A rewrite rule: what goes in, what comes out. */
export interface Mapping {
  from: string;
  to: string;
  state: State;
  /**
   * What actually happens between `from` and `to`. An arrow is a summary of a
   * path, and for some rows the path is the question — "image → base64 image
   * block" is four stages in three files drawn as one hop.
   *
   * Deliberately `Anatomy[]` and not `Node[]`. A node owns a grid position, a
   * camera frame and a wire anchor; a row that opened one would push the
   * deepest level past the viewport, which is the failure D8 records after
   * twelve attempts. This expands in place instead — the camera never moves,
   * so no framing maths is involved at all.
   *
   * A row with no `under` is a row whose arrow really is the whole fact. Most
   * rows are that, and adding this everywhere would restate the summary one
   * click down, which is the clutter this tool exists to avoid.
   */
  under?: Anatomy[];
}

/** One message in a `sequence`: who asks whom for what, in order. */
export interface Message {
  /** Must be one of the block's `actors`. */
  from: string;
  to: string;
  /** Plain words: "sends the email and a made-up password". */
  label: string;
  note?: string;
  state: State;
  /** `file:start-end` where this message is sent or answered. Same contract as `Step.at`. */
  at?: string;
}

/**
 * The same level said again for a reader who has never seen this project or
 * its field — shown under a toggle, so a reader who already knows skips it.
 *
 * The rest of a level is terse on purpose (D38): a `detail` of 40 words and
 * pictures of the code. That serves someone who knows what a quorum or a
 * webhook is and fails someone who does not, because every sentence leans on
 * words it never defines. This is where those words get defined.
 */
export interface Explainer {
  /**
   * Plain prose, 2-4 short paragraphs (blank line between), about 60-160 words;
   * a leaf's can be shorter. What problem this solves and why it exists, then
   * how it works in everyday terms — each project or domain word defined the
   * first time it appears ("an *epoch* is a term number that goes up with
   * every election"). A small concrete case with names and numbers beats an
   * abstract definition. An analogy only when it is exact, saying where it
   * stops holding. Not a restatement of `detail`.
   */
  body: string;
  /**
   * 0-2 pictures that teach the idea, each picked for what it explains: how
   * things relate or where this sits in the system → `diagram`; back and forth
   * between parties over time → `sequence`; what the data looks like →
   * `example`; comparing cases, states or options → `table`; a process in
   * order → `flow`. Only when it shows what the prose cannot. A `diagram` here
   * draws the idea, not the code: its boxes open nothing and its arrows need
   * no `at`.
   */
  blocks?: Anatomy[];
}

/** A word the bluprint leans on, for the glossary on the repository's level. */
export interface Term {
  /** As it appears in the bluprint's text: "epoch", "broker". */
  term: string;
  /** One plain sentence, at most 25 words, for someone outside the field. */
  meaning: string;
}

/**
 * One concrete thing followed through the whole system — "a new broker joins
 * the cluster" — so a first-time reader sees the roots as a story before they
 * open any. Each step opens the part where it happens.
 */
export interface Walkthrough {
  /** What is being followed, as a short sentence: "A broker joins the cluster". */
  title: string;
  steps: {
    /** A few words: "Its disk is formatted". */
    title: string;
    /** One or two plain sentences on what happens here. */
    detail: string;
    /** The ids from a root down to the part where this happens: ["formatting-storage"] or ["electing-a-leader", "el-votes"]. */
    path: string[];
  }[];
}

/**
 * One thing on a screen, top to bottom, read out of the JSX. Not a mock-up: a
 * list of what is there, so a reader knows what the user sees and taps.
 */
export interface ScreenItem {
  type: "heading" | "text" | "field" | "choice" | "button" | "list" | "image";
  label: string;
  /** What happens or what it holds: "must be 8+ characters", "opens RSVP". */
  note?: string;
  /** The lines that draw it, `file:start-end`: clicking it shows them. */
  at?: string;
  /** Shown only in this state, instead of the items beside it with another `when`: "image file", "unsaved". */
  when?: string;
}

/**
 * A place in the repository behind a node. Read live from disk when the reader
 * opens the code — never pasted — so it is available on EVERY level without
 * the fixture carrying a copy that can drift.
 */
export interface CodeRef {
  file: string;
  /** 1-indexed, inclusive. */
  start: number;
  end: number;
  /** Plain words: what these lines do. */
  label: string;
}

/**
 * Who put this here, when a thing on the bluprint did not come from the code.
 *
 * Deliberately NOT a fourth `State`. `State` is an epistemic claim about how
 * well the analysis knows a fact about the repository — `derived` was resolved
 * by the compiler, `inferred` is a guess from naming. A reader's own note is
 * not a weaker form of those: it is true by a different authority, theirs. A
 * fourth state would make every unmarked thing look like an analysis failure,
 * which is the exact two-tier read D3 exists to prevent, and would put a
 * person's words on the same axis as a compiler's.
 *
 * So provenance is its own axis. A node or block carrying `origin` keeps
 * whatever `state` it has and renders an extra, quieter mark saying where it
 * came from. Code-derived content carries none and is unchanged.
 */
export interface Origin {
  /**
   * `user` wrote it themselves; `claude` drafted it and the user kept it. Both
   * are the reader's responsibility — the difference is who typed it, which is
   * worth saying because one of them can be wrong in a way the reader did not
   * read closely.
   */
  by: "user" | "claude";
  /** ISO 8601, when it was added. */
  at: string;
  /** What the reader asked, where that is what makes the addition make sense. */
  note?: string;
}

/** Something a developer should know before they touch this. */
export interface Issue {
  /** Plain words, a few: "Anyone can delete any account". */
  title: string;
  /** What goes wrong, for whom, and when. One to three sentences. */
  detail: string;
  /** file:line where it happens. */
  where?: string;
}

/**
 * A box in a `diagram`, placed on a grid: `col` left to right, `row` top to
 * bottom, both from 0. The renderer does the geometry, so a figure is authored
 * as WHAT connects to what, never as coordinates.
 */
export interface DiagramBox {
  id: string;
  /** 1-4 words. */
  label: string;
  /** A few words under the label: "row with this id". */
  sub?: string;
  col: number;
  row: number;
  /** `good` = where things end up fine; `warn` = a problem or dead end. */
  tone?: "plain" | "good" | "warn";
  /**
   * The id of the child node this box is part of (D40). The box then opens
   * that part, so the picture is the way down and the list below it is a
   * fallback, not the only route.
   *
   * Boxes outnumber parts — a level draws ~8 boxes and owns ~4 parts — and the
   * two name different things: a box is a thing at runtime (`individual
   * table`), a part is a chapter about it (`Checking Who You Are`). So the
   * link is authored, never matched on the label, and a box with no `opens`
   * stays inert scenery rather than promising a click it cannot honour.
   */
  opens?: string;
  /**
   * `file:line` of the code a scenery box stands for, when it is this
   * repository's but another section explains it. The page opens that
   * section (nodesAt), so the box leads somewhere without this level owning it.
   */
  ref?: string;
}

export interface DiagramArrow {
  from: string;
  to: string;
  /** A few words on the line: "not found", "publishes". */
  label?: string;
  tone?: "plain" | "good" | "warn";
  /**
   * `file:line` where this path happens in the code. Not drawn — the generator
   * must cite one and the checker confirms the line exists, so "every arrow is
   * a real path" (D19) is checked rather than trusted.
   */
  at?: string;
  /**
   * The code connects these two in a way the fact graph cannot follow: a
   * decorator, a callback passed as a value, an event, a queue, the network.
   * Every other arrow's `at` must be a call the graph has from the one's code
   * into the other's; this one is the author's reading, and is drawn dotted.
   */
  inferred?: boolean;
}

export type Anatomy =
  // How the pieces connect — the main picture of a level. Every arrow is a
  // real path in the code (D19); a dead end is drawn `warn`, not left out.
  | { kind: "diagram"; caption: string; boxes: DiagramBox[]; arrows: DiagramArrow[] }
  // The real values, as a table: the categories themselves, the 61 campuses,
  // the fields a form sends. One column is a list.
  | { kind: "table"; caption?: string; columns: string[]; rows: string[][]; state: State }
  // Who talks to whom, in order — phone, Supabase, email, a table.
  | { kind: "sequence"; caption?: string; actors: string[]; rows: Message[] }
  // What the user sees on one screen: `items` top to bottom, and those that
  // carry a `note` get a callout beside the screen (D37).
  // `device` is what the screen runs on, from the app's own framework: a
  // mobile app's (React Native, Expo, Flutter) is `phone`, a page in a
  // browser is `web`; absent reads as `web`. `route` is the URL path a web
  // screen lives at ("/settings/billing"), never a file path.
  | { kind: "screen"; title: string; caption?: string; device?: "phone" | "web"; route?: string; items: ScreenItem[] }
  // What a stored value looks like. Synthesized and labelled as an example.
  | { kind: "example"; caption: string; value: string; notes?: Pair[] }
  | { kind: "schema"; table: string; rows: Column[]; rel?: string[] }
  | { kind: "routes"; rows: Route[] }
  | { kind: "flow"; rows: Step[] }
  | { kind: "facts"; rows: Pair[] }
  // Measured against each other. A number nobody can compare is just text.
  | { kind: "bars"; unit: string; rows: Bar[] }
  // Measured against the whole.
  | { kind: "parts"; total: string; rows: Part[] }
  // A closed set. Five one-line sentences describing five accepted formats is
  // an essay about a list; the list itself is the fact.
  | { kind: "chips"; caption?: string; rows: Chip[] }
  // in → out. A mapping drawn as a mapping.
  | { kind: "map"; caption?: string; rows: Mapping[] }
  // Something the reader added, or kept from Claude, because the bluprint did not
  // say it. Prose, because the thing that made an explanation land is often a
  // sentence; `origin` is required, since a note only exists because a person
  // put it there.
  | { kind: "note"; title?: string; body: string; origin: Origin }
  | Source;

export interface Node {
  id: string;
  /**
   * The thing's own name, 1-3 words, Title Case. A LABEL, not a sentence.
   *
   * The board shipped with prose here — "Agreeing to be read", "Where it all
   * lands" — and a reader cannot tell from those what part of the product they
   * name, so the first level read as ten riddles. The sentence belongs in
   * `sub`.
   */
  title: string;
  /** One line, plain English. What this IS — never a file path. */
  sub: string;
  /**
   * Where this card's code actually lives: the direct answer to "what belongs
   * to what". Features cut across directories (`identity` spans
   * `app/(protected)`, `lib/rules` and `app/api`), so the footprint is stated
   * rather than left to be inferred from the title.
   */
  footprint?: { dirs: string[]; files: number };
  /**
   * Set on cards holding more than 8 rows: the shape of what is
   * inside, so the reader knows what they are scrolling before they scroll it.
   * e.g. "13 formulas, one per 1040-NR line".
   */
  summary?: string;
  /** How this node's CHILDREN relate to each other. */
  group?: Group;
  /**
   * Something to recognise before reading anything: brand marks for the real
   * technologies involved, a small diagram where the arrangement is the
   * finding, or a single number. See `Shape` in `lib/bluprint/view.ts`.
   *
   * Only ever drawn from facts the analysis actually has. A card with nothing
   * true to draw gets none — an invented diagram is an invented arrow (D19).
   */
  shape?: Shape;
  state: State;
  /**
   * Set only where the reader added or edited this. A generated or authored
   * node has none. See `Origin`: this does not weaken or replace `state`.
   */
  origin?: Origin;
  alarm?: boolean;
  ghost?: boolean;
  col: number;
  row: number;
  /**
   * At most two short sentences (≤ 40 words) — the one thing to know before
   * looking at the pictures. Everything else is a block: steps are a `flow` or
   * `sequence`, connections a `diagram`, values a `table`. A paragraph that
   * explains the code is exactly what this tool replaces (D38).
   */
  detail?: string;
  /** This level for a reader new to the project, behind the Explain toggle. Every generated node has one. */
  explain?: Explainer;
  /**
   * A root the generator handed in and is still checking, shown while the bluprint
   * is made (D69). Never in a bluprint file: lib/server/bluprints.ts marks it on the way to the page.
   */
  draft?: boolean;
  /** Where this lives in the code. Every authored node has at least one. */
  code?: CodeRef[];
  /**
   * What the repository's own docs say about this: passages of its Markdown
   * (a design note, a recorded decision, a plan) that explain WHY the code is
   * the way it is, or what it is meant to become. Only passages that bear on
   * this node, each labelled with what it says, never the code's stand-in:
   * `code` is still where it lives. Most nodes have none.
   */
  docs?: CodeRef[];
  /** Known problems, shown as "Watch out" on this level. */
  issues?: Issue[];
  /**
   * Why this is not certain, in plain words. Required when `state` is not
   * `derived` — a mark with no reason is the "what does partial mean" defect.
   */
  unsure?: string;
  /**
   * What verification found: how many of this level's claims a second model
   * read against the lines they cite, and how many a reviewer then corrected.
   * Absent when the level was never fully checked.
   */
  verified?: { claims: number; corrected: number };
  /** Where the claim came from. Always a real location. */
  evidence?: string;
  anatomy?: Anatomy[];
  /**
   * What is underneath. Depth is a property of the BRANCH, not a global level:
   * a node with children can be opened, one without is a leaf, and nothing
   * caps how far that nests. Some branches stop at two because nothing
   * different lives below them; the ones that keep going do so because each
   * level answers a question its parent could not.
   */
  children?: Node[];
  /** Edges among this node's own children, drawn when it is the open node. */
  edges?: Edge[];
  /**
   * Synthesized from a row that carried `under`, rather than authored.
   *
   * The distinction is what a level MEANS. Authored children are siblings you
   * are meant to see together — "Subject and mode" next to "What you can send"
   * is a comparison. Row children are answers to six different questions, and
   * you asked one: rendering the other five is the wall of context this tool
   * exists to remove. `Branch` shows only the row child on the open path.
   */
  fromRow?: boolean;
}

export interface Edge {
  from: string;
  to: string;
  state: State;
  alarm?: boolean;
  label?: string;
  /**
   * Position in a real sequence, 1-indexed.
   *
   * An edge claims that `from` genuinely precedes `to` — a pipeline stage, a
   * request path, an ordered write. Siblings with no true ordering get no edge
   * at all and render as a SET (see `Group.ordering`), because inventing
   * arrows to make a level look like a diagram turns a weak claim into a
   * confident-looking one.
   */
  order?: number;
}

/**
 * How a set of siblings relates to each other.
 *
 * The board shipped with 6 edges, all at the root, and none below it — so
 * every level past the first was a silent pile of cards with no stated
 * relationship. Saying "these are unordered" is information; saying nothing
 * reads as missing analysis.
 */
export interface Group {
  ordering: "sequence" | "set";
  /** Shown when `set`: why these belong together despite having no order. */
  note?: string;
}

/** One generator run: which repository, at which commit, and how it is cut. */
export interface Run {
  command: string;
  /** The generator's version that made it (scripts/generate/version.ts). Absent on older bluprints. */
  mapperVersion?: number;
  /** The checkout's directory name, looked for under the usual code folders (rootOf in lib/server/bluprints.ts) — also where the code level reads. */
  repo: string;
  commit: string;
  files: number;
  elapsed: string;
  /** Absolute path of the checkout the bluprint is of. Set by the generator; overrides `repo`. */
  root?: string;
  /**
   * How much the bluprint explains for a newcomer, chosen when the project was
   * imported (D70): no plain-words layer, one sentence per level, a sentence
   * or two, a paragraph or two, or the full layer. Absent means full, or a
   * bluprint made before the choice existed.
   */
  explain?: "none" | "minimal" | "brief" | "detailed" | "full";
  /** Which model ran each generator stage. Absent on hand-authored bluprints. */
  models?: Record<string, string>;
  /** The part of the repository a scoped bluprint covers (`--scope`), and who reads it; an update keeps to it. */
  scope?: { paths: string[]; focus: string };
  /** Web address of the repository, read from the checkout's git remote when the page is built. */
  url?: string;
}

/** Stable id for an anatomy row. */
export function rowId(owner: string, key: string | number) {
  return `${owner}:${key}`;
}

app/lib/bluprint/share.ts:
/**
 * A bluprint read again keeps every part of the old one it did not change.
 *
 * The bluprint on screen follows its file as the generator or an update rewrites
 * it (components/bluprint/bluprint-context.tsx). Parsing a file gives every object a new
 * identity, so without this one redone section would re-render, re-measure
 * and re-run the effects of everything on the bluprint. `share` walks the new
 * value against the old and returns the old object wherever nothing under it
 * differs — so identity means "unchanged", and `changedPaths` can read off
 * exactly which nodes moved by comparing references.
 */

import type { Node } from "@/lib/bluprint/schema";

type Json = unknown;

const isObj = (v: Json): v is Record<string, Json> => typeof v === "object" && v !== null;
const idOf = (v: Json) => (isObj(v) && typeof v.id === "string" ? v.id : undefined);

/** `next`, with every part equal to the same part of `prev` replaced by that part of `prev`. */
export function share<T>(prev: T, next: T): T {
  if (Object.is(prev, next)) return prev;
  if (!isObj(prev) || !isObj(next) || Array.isArray(prev) !== Array.isArray(next)) return next;
  if (Array.isArray(next)) {
    const old = prev as Json[];
    // Items with ids are matched by id, so a section inserted or removed
    // above another does not make everything after it look changed.
    const byId = new Map(old.flatMap((v) => (idOf(v) === undefined ? [] : [[idOf(v)!, v] as const])));
    const out = next.map((v, i) => {
      const id = idOf(v);
      return share(id !== undefined ? byId.get(id) : old[i], v);
    });
    return (out.length === old.length && out.every((v, i) => v === old[i]) ? prev : out) as T;
  }
  const old = prev as Record<string, Json>;
  const keys = Object.keys(next);
  let same = keys.length === Object.keys(old).length;
  const out: Record<string, Json> = {};
  for (const k of keys) {
    out[k] = share(old[k], (next as Record<string, Json>)[k]);
    if (out[k] !== old[k]) same = false;
  }
  return (same ? prev : out) as T;
}

/**
 * Every node of `next` that is new or differs from `prev`, by its path from
 * the top, as `JSON.stringify(path)` — the same string the canvas puts in
 * `data-path`. An ancestor of a change differs too, so a section redone deep
 * in the tree also marks the row that leads down to it. `next` must already
 * have been through `share` with `prev`.
 */
export function changedPaths(prev: Node, next: Node, at: string[] = []): string[] {
  if (prev === next) return [];
  const out = [JSON.stringify(at)];
  for (const n of next.children ?? []) {
    const was = prev.children?.find((c) => c.id === n.id);
    out.push(...(was ? changedPaths(was, n, [...at, n.id]) : [JSON.stringify([...at, n.id])]));
  }
  return out;
}

app/lib/bluprint/source.ts:
/**
 * Client-side: where the drawer reads code from.
 *
 * Served by `next dev`, that is `/api/source` over the real checkout. A static
 * export (scripts/export-static.mts) has no server, so it reads the files the
 * bluprint cites, baked into `source.json` beside the page at build time.
 */

import type { Slice } from "@/lib/server/repo";

/** Set only in a static export: the one bluprint it serves. */
export const STATIC_BLUPRINT = process.env.NEXT_PUBLIC_STATIC_BLUPRINT;
/** In a static export, the code host page a ref links to: `<base>/<file>#L<start>-L<end>`. */
export const SOURCE_URL = process.env.NEXT_PUBLIC_SOURCE_URL;

let baked: Promise<Record<string, string>> | undefined;

/** Lines `start`–`end` of a file, cut from its whole text. */
export function sliceOf(text: string, q: { file: string; start: number; end: number; fixture?: string }): Slice {
  const lines = text.split("\n");
  const code = lines.slice(q.start - 1, q.end).join("\n");
  return { file: q.file, start: q.start, end: q.end, code, total: lines.length, matchesFixture: q.fixture === undefined || code === q.fixture };
}

export async function readSource(
  q: { bluprint: string; file: string; start: number; end: number; fixture?: string },
  signal?: AbortSignal,
): Promise<{ slice: Slice } | { refused: string }> {
  if (!STATIC_BLUPRINT) {
    const params = new URLSearchParams({ bluprint: q.bluprint, file: q.file, start: String(q.start), end: String(q.end) });
    if (q.fixture !== undefined) params.set("fixture", q.fixture);
    const res = await fetch(`/api/source?${params}`, { signal });
    const body = await res.json();
    return res.ok ? { slice: body as Slice } : { refused: (body.refused as string) ?? "unreadable" };
  }
  baked ??= fetch(`${process.env.NEXT_PUBLIC_BASE_PATH ?? ""}/source.json`).then((r) => r.json());
  const text = (await baked)[q.file];
  if (text === undefined) return { refused: "not in this export" };
  return { slice: sliceOf(text, q) };
}

app/lib/client/api.ts:
/** A POST to /api/projects (app/api/projects/route.ts), throwing the error it answers with. */
export async function projectAction(body: Record<string, unknown>) {
  const res = await fetch("/api/projects", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });
  const out = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(out.error ?? "Something went wrong.");
  return out;
}

app/lib/client/claude.ts:
import { invoke, isTauri } from "@tauri-apps/api/core";
import { readSettings } from "@/lib/client/settings";

/** Claude Code as the desktop app finds it (src-tauri/src/claude.rs): where Settings says, or on the PATH. Null when it is nowhere. */
export const findClaude = (configured = readSettings().claudePath) =>
  invoke<{ path: string } | null>("claude_detect", { configured: configured || null }).catch(() => null);

/** The Claude Code a model run on the server is to use; none outside the desktop app. */
export async function claudePath(): Promise<string | undefined> {
  if (!isTauri()) return undefined;
  const found = await findClaude();
  if (!found) throw new Error("Claude Code was not found. Set where it is in Settings.");
  return found.path;
}

app/lib/client/clone.ts:
/**
 * What the reader typed as a repository to clone, read the way they would
 * paste it: `owner/repo`, a GitHub page's address (a branch or file view
 * included), or any https or ssh git address. Shared by the page, to name
 * the folder, and the server, which clones only what this accepts.
 */

const GITHUB = /^(?:https?:\/\/)?(?:www\.)?github\.com\/([\w.-]+)\/([\w.-]+?)(?:\.git)?(?:[/?#].*)?$/i;
const SHORT = /^([\w.-]+)\/([\w.-]+?)(?:\.git)?$/;
const HTTPS = /^https:\/\/[^\s/@]+(?::\d+)?\/[^\s]+$/i;
const SSH = /^(?:ssh:\/\/[^\s]+|[\w.-]+@[\w.-]+:[^\s]+)$/;

/** The address to clone, or undefined when it is not one. */
export function cloneUrl(input: string): string | undefined {
  const s = input.trim();
  const gh = s.match(GITHUB) ?? s.match(SHORT);
  if (gh) return gh[1] === "." || gh[1] === ".." ? undefined : `https://github.com/${gh[1]}/${gh[2]}.git`;
  if (HTTPS.test(s) || SSH.test(s)) return s;
  return undefined;
}

/** The repository's own name, which the folder and project take by default. */
export function repoName(input: string): string {
  const url = cloneUrl(input);
  if (!url) return "";
  const name = url.replace(/[\\/]+$/, "").split(/[/:]/).pop() ?? "";
  return name.replace(/\.git$/i, "");
}

app/lib/client/highlight.ts:
/**
 * Syntax colouring for the code the drawer reads off disk.
 *
 * The viewer used to draw every line in one ink, which is the one place the
 * app asked a reader to do work a code editor does for free: find the string,
 * find the comment, find where the call starts. The bluprint is supposed to make
 * code legible, so its own code pane cannot be the least legible pane in the
 * product.
 *
 * Deliberately a tokenizer, not a parser, and deliberately no dependency:
 * the bluprints cite nine languages (.ts/.tsx/.py/.java/.go/.js/.scala/.vue/.sql
 * and friends), and shipping a grammar per language to colour a 14-line slice
 * costs more than it returns. Everything here is the lexical layer those
 * languages share — strings, comments, numbers, keywords, call sites — which
 * is the part that carries the reading.
 *
 * It is told the LANGUAGE, never asked to guess: the file's extension is
 * already known at every call site.
 */

export type Kind =
  | "plain"
  | "comment"
  | "string"
  | "number"
  | "keyword"
  | "type"
  | "call"
  | "punct"
  | "annotation";

export interface Token {
  text: string;
  kind: Kind;
}

/** A language the tokenizer has been told about, resolved from a file path. */
export type Lang = "c" | "python" | "sql" | "markup" | "plain";

/**
 * Keywords by family. One list per family rather than per language: a Java
 * keyword highlighted in a Scala file is a word that really is a keyword in
 * Scala too, almost always, and the cost of being wrong is one word tinted
 * that should not have been.
 */
const C_KEYWORDS = new Set([
  // shared control flow
  "if", "else", "for", "while", "do", "switch", "case", "default", "break",
  "continue", "return", "goto", "try", "catch", "finally", "throw", "throws",
  // declarations
  "class", "interface", "enum", "struct", "record", "trait", "object", "type",
  "function", "func", "fun", "def", "val", "var", "let", "const", "static",
  "final", "abstract", "sealed", "override", "implements", "extends", "package",
  "import", "export", "from", "as", "public", "private", "protected", "internal",
  "namespace", "declare", "readonly", "implicit", "given", "using", "with",
  // values and operators that read as words
  "new", "delete", "typeof", "instanceof", "in", "of", "is", "await", "async",
  "yield", "this", "self", "super", "null", "nil", "none", "true", "false",
  "undefined", "void", "throw", "defer", "go", "chan", "select", "range",
  "map", "make", "synchronized", "volatile", "transient", "native", "assert",
  "match", "when", "lazy", "suspend", "operator", "data", "sealed", "satisfies",
  "keyof", "infer", "extends", "module", "require",
]);

const PY_KEYWORDS = new Set([
  "def", "class", "return", "yield", "if", "elif", "else", "for", "while",
  "break", "continue", "pass", "import", "from", "as", "with", "try", "except",
  "finally", "raise", "assert", "lambda", "global", "nonlocal", "del", "in",
  "is", "not", "and", "or", "async", "await", "True", "False", "None", "self",
  "cls", "match", "case",
]);

const SQL_KEYWORDS = new Set([
  "select", "from", "where", "join", "left", "right", "inner", "outer", "on",
  "group", "order", "by", "having", "limit", "offset", "insert", "into",
  "values", "update", "set", "delete", "create", "table", "alter", "drop",
  "index", "view", "primary", "key", "foreign", "references", "not", "null",
  "default", "unique", "constraint", "and", "or", "as", "distinct", "union",
  "all", "case", "when", "then", "else", "end", "with", "returning", "cascade",
]);

/** Which family a file is read as. Unknown extensions get no colour at all. */
export function langOf(file: string): Lang {
  const ext = file.slice(file.lastIndexOf(".") + 1).toLowerCase();
  if (["py", "pyi"].includes(ext)) return "python";
  if (["sql", "prisma"].includes(ext)) return "sql";
  if (["html", "vue", "svelte", "xml"].includes(ext)) return "markup";
  if (
    ["ts", "tsx", "js", "jsx", "mjs", "cjs", "java", "go", "scala", "kt", "kts",
      "c", "h", "cpp", "hpp", "cs", "rs", "swift", "php", "css", "scss", "json"].includes(ext)
  ) {
    return "c";
  }
  return "plain";
}

const KEYWORDS: Record<Lang, Set<string>> = {
  c: C_KEYWORDS,
  python: PY_KEYWORDS,
  sql: SQL_KEYWORDS,
  markup: new Set(),
  plain: new Set(),
};

/** The CSS colour each kind is drawn in. Theme tokens, so dark mode follows. */
export const TOKEN_COLOR: Record<Kind, string> = {
  plain: "var(--color-code-plain)",
  comment: "var(--color-code-comment)",
  string: "var(--color-code-string)",
  number: "var(--color-code-number)",
  keyword: "var(--color-code-keyword)",
  type: "var(--color-code-type)",
  call: "var(--color-code-call)",
  punct: "var(--color-code-punct)",
  annotation: "var(--color-code-annotation)",
};

const WORD = /[A-Za-z_$][\w$]*/y;
const NUMBER = /(?:0[xXbBoO][0-9a-fA-F_]+|\d[\d_]*(?:\.[\d_]+)?(?:[eE][+-]?\d+)?)[a-zA-Z]*/y;
const PUNCT = new Set("{}()[];,.:?!<>=+-*/%&|^~@#".split(""));

/**
 * One slice of code, tokenized line by line.
 *
 * Block comments and template/triple-quoted strings run across lines, so the
 * whole slice is scanned once and the result cut at newlines — a per-line pass
 * would restart inside a `/* ... *\/` and colour its body as code.
 */
export function highlight(code: string, lang: Lang): Token[][] {
  if (lang === "plain") return code.split("\n").map((l) => [{ text: l, kind: "plain" as const }]);

  const tokens: Token[] = [];
  const push = (text: string, kind: Kind) => {
    if (text) tokens.push({ text, kind });
  };

  const keywords = KEYWORDS[lang];
  const hash = lang === "python" || lang === "sql";
  let i = 0;
  const n = code.length;

  while (i < n) {
    const c = code[i];

    // ── whitespace and newlines: passed through so lines can be cut later
    if (c === "\n" || c === " " || c === "\t") {
      let j = i;
      while (j < n && (code[j] === "\n" || code[j] === " " || code[j] === "\t")) j++;
      push(code.slice(i, j), "plain");
      i = j;
      continue;
    }

    // ── comments
    const two = code.slice(i, i + 2);
    if (lang !== "sql" && two === "/*") {
      const end = code.indexOf("*/", i + 2);
      const j = end === -1 ? n : end + 2;
      push(code.slice(i, j), "comment");
      i = j;
      continue;
    }
    if ((two === "//" && lang !== "python") || (hash && c === "#") || (lang === "sql" && two === "--")) {
      let j = code.indexOf("\n", i);
      if (j === -1) j = n;
      push(code.slice(i, j), "comment");
      i = j;
      continue;
    }

    // ── strings. Python's triple quotes first: they contain lone quotes.
    if (lang === "python" && (code.startsWith('"""', i) || code.startsWith("'''", i))) {
      const q = code.slice(i, i + 3);
      const end = code.indexOf(q, i + 3);
      const j = end === -1 ? n : end + 3;
      push(code.slice(i, j), "string");
      i = j;
      continue;
    }
    if (c === '"' || c === "'" || c === "`") {
      let j = i + 1;
      while (j < n) {
        if (code[j] === "\\") {
          j += 2;
          continue;
        }
        if (code[j] === c) {
          j++;
          break;
        }
        // Only a backtick string may span lines; an unterminated quote ends
        // at the newline rather than swallowing the rest of the slice.
        if (code[j] === "\n" && c !== "`") break;
        j++;
      }
      push(code.slice(i, j), "string");
      i = j;
      continue;
    }

    // ── annotations and decorators: @Override, @property, #[derive]
    if (c === "@") {
      WORD.lastIndex = i + 1;
      const m = WORD.exec(code);
      if (m) {
        push(code.slice(i, WORD.lastIndex), "annotation");
        i = WORD.lastIndex;
        continue;
      }
    }

    // ── numbers
    if (c >= "0" && c <= "9") {
      NUMBER.lastIndex = i;
      const m = NUMBER.exec(code);
      if (m) {
        push(m[0], "number");
        i += m[0].length;
        continue;
      }
    }

    // ── words: keyword, type, call, or plain identifier
    WORD.lastIndex = i;
    const w = WORD.exec(code);
    if (w) {
      const text = w[0];
      const lower = lang === "sql" ? text.toLowerCase() : text;
      // What follows decides a call; what precedes decides a member.
      let k = i + text.length;
      while (k < n && (code[k] === " " || code[k] === "\t")) k++;
      const kind: Kind = keywords.has(lower)
        ? "keyword"
        : code[k] === "("
          ? "call"
          : // Capitalised and not a call: a type name, by convention in every
            // language here. SCREAMING_CASE is a constant, which reads as one.
            /^[A-Z]/.test(text)
            ? "type"
            : "plain";
      push(text, kind);
      i += text.length;
      continue;
    }

    // ── punctuation and anything else
    push(c, PUNCT.has(c) ? "punct" : "plain");
    i++;
  }

  return splitLines(tokens);
}

/** Cuts the flat token run at newlines, keeping each line's tokens in order. */
function splitLines(tokens: Token[]): Token[][] {
  const lines: Token[][] = [[]];
  for (const t of tokens) {
    if (!t.text.includes("\n")) {
      lines[lines.length - 1].push(t);
      continue;
    }
    const parts = t.text.split("\n");
    parts.forEach((part, i) => {
      if (i > 0) lines.push([]);
      if (part) lines[lines.length - 1].push({ text: part, kind: t.kind });
    });
  }
  return lines;
}

app/lib/client/hunks.ts:
/**
 * A unified diff (`FileChange.diff`, lib/server/diff.ts) read back into lines a view
 * can draw. Its own file because lib/server/diff.ts runs git and cannot reach the page.
 */

/** One run of a unified diff, line by line, numbered on both sides. */
export interface HunkLines {
  oldStart: number;
  newStart: number;
  lines: { kind: "+" | "-" | " "; text: string; old?: number; new?: number }[];
}

/** `unified`, as hunks: each line with its number on the side it exists on. */
export function hunksOf(unified: string): HunkLines[] {
  const out: HunkLines[] = [];
  let o = 0;
  let n = 0;
  for (const l of unified.split("\n")) {
    const at = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(l);
    if (at) {
      o = Number(at[1]);
      n = Number(at[2]);
      out.push({ oldStart: o, newStart: n, lines: [] });
      continue;
    }
    const h = out[out.length - 1];
    // The `---`/`+++` header comes before the first hunk, so a removed line
    // reading `-- x` is never taken for it.
    if (!h || l.startsWith("\\")) continue;
    const kind = l[0];
    if (kind === "+") h.lines.push({ kind, text: l.slice(1), new: n++ });
    else if (kind === "-") h.lines.push({ kind, text: l.slice(1), old: o++ });
    else if (kind === " ") h.lines.push({ kind, text: l.slice(1), old: o++, new: n++ });
  }
  return out;
}

