app/lib/server/assets.ts:
/**
 * Server-side: images a doc pulls from the web — badges, logos, diagrams on a
 * CDN — fetched once and kept in the vault, so a doc read on a train still
 * shows them. A copy younger than a day is served without asking; an older
 * one is refreshed, and kept serving when the network is not there.
 *
 * The URL comes from a doc, which comes from someone else's repository, so it
 * is treated as hostile: http(s) only, no address on this machine or its
 * network, an image type, and a size cap.
 */

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, renameSync, statSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { VAULT } from "@/lib/server/vault";

const DIR = join(VAULT, "cache", "images");
const FRESH = 24 * 60 * 60 * 1000;
const MAX = 5 << 20;

/** Hosts that name this machine or a private network: never fetched. */
const LOCAL = /^(localhost|.*\.local|127\.|10\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.|0\.|\[?::1\]?$|\[?f[cd][0-9a-f]{2}:|\[?fe80:)/i;

export class NotAnImage extends Error {}

function check(raw: string): URL {
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    throw new NotAnImage("bad url");
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") throw new NotAnImage("not http");
  if (LOCAL.test(url.hostname)) throw new NotAnImage("local address");
  return url;
}

export async function remoteImage(raw: string): Promise<{ body: Buffer; type: string }> {
  const url = check(raw);
  const key = createHash("sha256").update(url.href).digest("hex");
  const body = join(DIR, key);
  const meta = join(DIR, `${key}.json`);
  const cached = () =>
    existsSync(body) && existsSync(meta)
      ? { body: readFileSync(body), type: (JSON.parse(readFileSync(meta, "utf8")) as { type: string }).type }
      : null;
  if (existsSync(meta) && Date.now() - statSync(meta).mtimeMs < FRESH) {
    const hit = cached();
    if (hit) return hit;
  }
  try {
    // Redirects by hand, each hop checked before it is asked: a badge host
    // redirecting to this machine must not get the request made for it.
    let at = url;
    let res = await fetch(at, { signal: AbortSignal.timeout(6000), redirect: "manual" });
    for (let hop = 0; res.status >= 300 && res.status < 400 && res.headers.get("location"); hop++) {
      if (hop === 4) throw new NotAnImage("too many redirects");
      at = check(new URL(res.headers.get("location")!, at).href);
      res = await fetch(at, { signal: AbortSignal.timeout(6000), redirect: "manual" });
    }
    const type = res.headers.get("content-type")?.split(";")[0].trim() ?? "";
    if (!res.ok || !type.startsWith("image/")) throw new NotAnImage(`not an image (${res.status} ${type})`);
    const got = Buffer.from(await res.arrayBuffer());
    if (got.length > MAX) throw new NotAnImage("too large");
    mkdirSync(DIR, { recursive: true });
    writeFileSync(`${body}.part`, got);
    renameSync(`${body}.part`, body);
    writeFileSync(meta, JSON.stringify({ url: url.href, type }));
    return { body: got, type };
  } catch (e) {
    // Offline, or the host is down: the last copy, however old, beats a hole.
    const stale = cached();
    if (stale) return stale;
    throw e instanceof NotAnImage ? e : new NotAnImage("unreachable");
  }
}

app/lib/server/bluprints.ts:
/**
 * Server-side: every bluprint the app can open, and the repo each one reads its
 * code from. They are the reader's own projects in the vault (lib/server/vault.ts),
 * which stay on their machine; the app ships no example bluprints.
 */

import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, statSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import type { Node, Run } from "@/lib/bluprint/schema";
import { LIVE_SEP, type BluprintFile } from "@/lib/bluprint/build";
import { followLive, liveOf, shiftRefs } from "@/lib/server/live";
import { apply, overlayFile, readOverlay } from "@/lib/server/overlay";
import { listProjects, bluprintFileOf, markOpened, progressOf, projectDir, type Progress, type Project } from "@/lib/server/vault";

/** One entry in the bluprint picker. */
export interface BluprintEntry {
  id: string;
  label: string;
  /** One of the reader's projects, which follows edits; false only for the one bluprint a static export serves. */
  local: boolean;
  /** The checkout, which a workspace tab names as its `cwd`; absent for a static export. */
  root?: string;
}

/**
 * How the bluprint was made: the audit.md its last run wrote beside it
 * (scripts/generate/audit.ts). Only for a listed project, so the id, which
 * arrives from the page, never names a path; null when its bluprint was made
 * before runs kept one.
 */
export function auditOf(id: string): string | null {
  const dir = listProjects().some((p) => p.id === id) ? projectDir(id) : null;
  const f = dir && join(dir, "audit.md");
  return f && existsSync(f) ? readFileSync(f, "utf8") : null;
}

/**
 * A project opens as soon as its first run starts, before it has a bluprint: the
 * page shows the run building one (D69). One whose first run ended without a
 * bluprint still opens, on what went wrong.
 */
const runFile = (id: string) => join(projectDir(id), "progress.json");
// A project without a bluprint, by choice or because it has no code yet, still
// opens for its tabs, over an empty bluprint.
const noBluprint = (p: Project) => p.paused || p.bluprint.status === "empty";
const openable = (p: Project) => Boolean(bluprintFileOf(p.id)) || p.bluprint.status === "generating" || noBluprint(p) || existsSync(runFile(p.id));

/**
 * How far the run making this bluprint has got, while there is one to show: the
 * run in flight, or for a bluprint never made, the run that failed to make it.
 */
function progressFor(p: Project): Progress | undefined {
  if (p.bluprint.status === "generating") return progressOf(p.id);
  if (bluprintFileOf(p.id) || noBluprint(p)) return undefined;
  return { ...progressOf(p.id), stage: p.bluprint.status === "cancelled" ? "cancelled" : "failed" };
}

/** Every bluprint that can be opened: the reader's projects that have one, or are making one, the last opened first. */
export function listBluprints(): BluprintEntry[] {
  const opened = (p: Project) => Date.parse(p.openedAt ?? p.addedAt);
  return listProjects()
    .filter(openable)
    .sort((a, b) => opened(b) - opened(a))
    .map((p) => ({ id: p.id, label: p.name, local: true, root: p.root }));
}

/**
 * `name` arrives from the URL, so only a listed bluprint is ever read. A project's
 * bluprint is given the project's directory as its root: that is where the reader
 * keeps it, whatever the generator recorded. With no name, or one that is not
 * a project, the reader's most recently opened project opens; null when they
 * have none yet.
 */
export function loadBluprint(name: string | undefined): { name: string; version?: string; file: BluprintFile; progress?: Progress } | null {
  const projects = listProjects();
  const opened = (p: (typeof projects)[number]) => Date.parse(p.openedAt ?? p.addedAt);
  const project =
    (name ? projects.find((p) => p.id === name && openable(p)) : undefined) ??
    // The last one opened, with a bluprint or not: one without one yet still reopens where it was left.
    projects.filter(openable).sort((a, b) => opened(b) - opened(a))[0];
  if (!project || !openable(project)) return null;
  markOpened(project.id);
  const version = bluprintVersion(project.id);
  const progress = progressFor(project);
  return { name: project.id, version, file: readBluprint(project, progress), progress };
}

function readBluprint(p: Project, progress: Progress | undefined): BluprintFile {
  const file = bluprintFileOf(p.id);
  // Before the first root is accepted there is no file: the run's own
  // progress is the whole page, over an empty bluprint.
  const bluprint: BluprintFile = file
    ? JSON.parse(readFileSync(file, "utf8"))
    : { RUN: { command: `bluprint make ${p.name}`, repo: p.name, commit: "", files: 0, elapsed: "" }, AUTHORED: [] };
  bluprint.RUN.root = p.root;
  // The code may be ahead of the bluprint: its lines are read where they are now.
  if (file) {
    shiftRefs(p.id, bluprint);
    bluprint.LIVE = liveOf(p.id);
  }
  if (progress) withDrafts(bluprint, p.id, progress);
  // What the reader added, composed in here so every consumer sees it.
  return apply(bluprint, readOverlay(p.id)).file;
}

/**
 * The roots still being checked, in their place among the accepted ones and
 * marked `draft` so the page draws them dimmed (D69). A root accepted from a
 * previous run keeps its place until this run's version is accepted.
 */
function withDrafts(bluprint: BluprintFile, id: string, progress: Progress) {
  let drafts: Record<string, Node> = {};
  try {
    drafts = JSON.parse(readFileSync(join(projectDir(id), "drafts.json"), "utf8"));
  } catch {
    return;
  }
  const order = progress.roots.map((r) => r.id);
  const have = new Set(bluprint.AUTHORED.map((n) => n.id));
  const added = order.flatMap((r) => (drafts[r] && !have.has(r) ? [{ ...drafts[r], draft: true }] : []));
  if (!added.length) return;
  const at = (n: Node) => (order.includes(n.id) ? order.indexOf(n.id) : order.length);
  bluprint.AUTHORED = [...bluprint.AUTHORED, ...added].sort((a, b) => at(a) - at(b)).map((n, i) => ({ ...n, col: 0, row: i }));
}

const mtime = (f: string) => (existsSync(f) ? statSync(f).mtimeMs : 0);

/**
 * Which state of a project's bluprint is on disk: the times of the two files it is
 * composed from. The generator and the updater rename a whole new file into
 * place, so a new time is a new bluprint, and the open page follows it
 * (app/api/bluprint/route.ts). Undefined for anything that is not a project with a bluprint.
 * Past LIVE_SEP, how far the code has moved since (lib/server/live.ts).
 */
export function bluprintVersion(id: string): string | undefined {
  const p = listProjects().find((q) => q.id === id);
  if (!p || !openable(p)) return undefined;
  const file = bluprintFileOf(id);
  const made = `${file ? mtime(file) : 0}:${mtime(overlayFile(id))}`;
  // While a run makes the bluprint, its progress and drafts are part of what the page shows.
  const disk =
    p.bluprint.status === "generating" || !file ? `${made}:${p.bluprint.status}:${mtime(runFile(id))}:${mtime(join(projectDir(id), "drafts.json"))}` : made;
  // Asked only for the open bluprint, so this is what keeps its checkout watched.
  const live = file ? followLive(id, p.root)?.live : undefined;
  return live ? `${disk}${LIVE_SEP}${live.seq}` : disk;
}

/**
 * A project's bluprint as the open page shows it, read again because it changed.
 * The version is taken before the read: a write landing between the two makes
 * the file newer than its stamp, so the next poll reads it again rather than
 * missing it.
 */
export function liveBluprint(id: string): { version: string; file: BluprintFile; progress: Progress | null } | null {
  const project = listProjects().find((p) => p.id === id);
  const version = bluprintVersion(id);
  if (!project || !version) return null;
  const progress = progressFor(project);
  const file = readBluprint(project, progress);
  file.RUN.url ??= remoteOf(file.RUN);
  return { version, file, progress: progress ?? null };
}

/**
 * The landing page's demo bluprints (landing/demo/<name>), committed with that page
 * rather than shipped with the app (D63). Read only for a page the landing
 * frames (`?embed`) or a static export of one; the reader's own bluprint list never
 * includes them. Null outside a checkout of this repo, as in the desktop app.
 */
const DEMOS = join(process.cwd(), "..", "landing", "demo");

function isDemo(name: string | undefined): name is string {
  return Boolean(name && /^[\w.-]+$/.test(name) && existsSync(join(DEMOS, name, "bluprint.json")));
}

export function loadDemo(name: string | undefined): { name: string; file: BluprintFile } | null {
  return isDemo(name) ? { name, file: JSON.parse(readFileSync(join(DEMOS, name, "bluprint.json"), "utf8")) } : null;
}

const baked = new Map<string, Record<string, string>>();

/**
 * A demo's cited files as they were when its bluprint was made (`source.json`
 * beside it), for a machine without its checkout. Keyed by repo-relative path,
 * so a caller's path never reaches the disk. Undefined when one of the
 * reader's projects has the same name: a project whose bluprint was made from a demo's own
 * checkout takes its name too, and its code is on disk, as it is now, not as
 * the demo froze it.
 */
export function demoSource(name: string | undefined): Record<string, string> | undefined {
  if (!isDemo(name) || listProjects().some((p) => p.id === name && bluprintFileOf(p.id))) return undefined;
  const file = join(DEMOS, name, "source.json");
  if (!baked.has(name) && existsSync(file)) baked.set(name, JSON.parse(readFileSync(file, "utf8")));
  return baked.get(name);
}

/** Where checkouts usually live, under home, in the order they are tried. */
const CODE_DIRS = ["Desktop/Code", "projects", "Projects", "code", "Code", "src", "dev", "repos", "git"];

/**
 * Where a bluprint's code lives. A generated bluprint records its absolute root; a
 * hand-authored one names only its repo, so a literal `/Users/<name>/…` is
 * never baked into a fixture, and is looked for in the usual folders. With no
 * checkout found it stays at ~/Desktop/Code.
 */
export function rootOf(run: Run): string {
  if (run.root) return run.root;
  if (process.env.BLUPRINT_REPO_ROOT) return process.env.BLUPRINT_REPO_ROOT;
  const tried = CODE_DIRS.map((d) => resolve(homedir(), d, run.repo));
  return tried.find((d) => existsSync(d) && statSync(d).isDirectory()) ?? tried[0];
}

/** The checkout's `origin` as a web address (`git@host:o/r.git` → `https://host/o/r`), if it has one. */
export function remoteOf(run: Run): string | undefined {
  try {
    const url = execFileSync("git", ["-C", rootOf(run), "remote", "get-url", "origin"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"], windowsHide: true }).trim();
    return url.replace(/^git@([^:]+):/, "https://$1/").replace(/\.git$/, "").replace(/^https:\/\/[^@/]+@/, "https://") || undefined;
  } catch {
    return undefined;
  }
}

app/lib/server/diff.ts:
/**
 * What a commit did to the bluprint.
 *
 * Reviewing a diff by reading hunks is reading the change in the code's own
 * terms. This answers it in the bluprint's terms instead: which sections the change
 * touched, and — where there are two bluprints to compare — which boxes, rows and
 * columns went away and which arrived, so a dropped database column reads as a
 * red row beside the green ones rather than as a `-` in a migration file.
 *
 * The git and line arithmetic is scripts/generate/gitdiff.ts, shared verbatim
 * with the updater: a section is `changed` here under exactly the test that
 * makes the updater redo it, so the diff never marks a section the update
 * would have left alone.
 *
 * Two comparisons, both the reader's to pick:
 *   - the bluprint's commit → the working tree, the default, which is the one that
 *     answers "what have I done since the bluprint was made" and the only one that
 *     can see uncommitted work;
 *   - any two commits, for reviewing someone else's.
 *
 * Section verdicts need the bluprint's line references to mean something on the
 * `from` side. From the bluprint's own commit they do as written; from any other,
 * they are carried there first through the diff between the two (`bluprintDiff`).
 * Only a bluprint whose commit the checkout no longer has gets `basis: "files"`,
 * and says so, rather than citing sections against numbering they were never
 * written for.
 */

import type { Anatomy, Node } from "@/lib/bluprint/schema";
import type { BluprintFile } from "@/lib/bluprint/build";
import type { Review } from "@/lib/server/review";
import { changes, diffOf, git, hasAt, moved, refs, touches, type Base, type Change } from "@/scripts/generate/gitdiff";

export type Verdict = "added" | "removed" | "changed" | "untouched";

/** What a change did to one file, as the diff view needs it — without the two full texts. */
export interface FileChange {
  path: string;
  /** `added` and `removed` are the file's own fate, not a section's. */
  verdict: Exclude<Verdict, "untouched">;
  /** A unified diff with context, as `git diff` prints it. */
  diff: string;
  /** The path the bluprint knows this file by, where a rename since makes it another. */
  mapped?: string;
  added: number;
  removed: number;
}

export interface SectionDiff {
  id: string;
  title: string;
  /** Root first, this section last, as ids — the path the canvas navigates by. */
  path: string[];
  verdict: Verdict;
  /**
   * The files behind the verdict, and the lines in each this section cites,
   * as the bluprint numbers them; `at` is where they were on the `from` side, where
   * that is not the bluprint's own text.
   */
  files: { path: string; lines: { s: number; e: number; at?: { s: number; e: number } }[] }[];
  /** How many sections under this one changed: a level is worth opening when something below it moved, even where its own lines did not. */
  inside?: number;
}

/** One row of a `schema`, `table` or `facts` block, matched across the two bluprints by its key. */
export interface RowDiff {
  key: string;
  verdict: Verdict;
  /** The cells as the `from` bluprint had them, kept so a removed row can still be drawn. */
  before?: string[];
  after?: string[];
}

/** One box or arrow of a `diagram`, matched by id (boxes) or `from→to` (arrows). */
export interface PartDiff {
  key: string;
  verdict: Verdict;
  label?: string;
}

export interface BlockDiff {
  /** Where the block is: the section's path, then its index in `anatomy`. */
  path: string[];
  at: number;
  kind: Anatomy["kind"];
  verdict: Verdict;
  rows?: RowDiff[];
  boxes?: PartDiff[];
  arrows?: PartDiff[];
}

export interface BluprintDiff {
  /**
   * `sections` when the verdicts are the bluprint's own sections, `files` when the
   * two commits asked for leave the bluprint's line references meaningless and only
   * the file list can be trusted. The view says which it is showing; it never
   * dresses one up as the other.
   */
  basis: "sections" | "files";
  from: string;
  /** The resolved `to`, or null for the working tree. */
  to: string | null;
  /** Why the basis is `files`, where it is. */
  why?: string;
  /**
   * How a human-written `from`/`to` was understood, per side, where one was
   * given. Optional: a diff asked for by sha has nothing to explain.
   */
  read?: { from?: string; to?: string };
  files: FileChange[];
  sections: SectionDiff[];
  /** Only where a second bluprint was given to compare against. */
  blocks: BlockDiff[];
  /** The `at` of every diagram arrow whose line changed, as the bluprint cites it: the path itself was edited. */
  arrows?: string[];
  /**
   * Changed files no section's lines cover: new code, or edits between the
   * lines the bluprint cites. Each with the section citing that file nearest the
   * change, where one does; a review is never silent about code it cannot place.
   */
  outside?: { path: string; near?: string[] }[];
  /** The branch or pull request this diff reviews, where it was asked for as one. */
  review?: Review;
}

/* ── the two comparisons ─────────────────────────────────────── */

/** One `git diff` split by file, keyed by the file's path on the `to` side. */
function perFile(text: string): Map<string, string[]> {
  const out = new Map<string, string[]>();
  let cur: string[] | null = null;
  for (const l of text.split("\n")) {
    const m = /^diff --git a\/(.+) b\/(.+)$/.exec(l);
    if (m) out.set(m[2], (cur = []));
    else cur?.push(l);
  }
  return out;
}

const HUNK = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/;

/**
 * `from`..`to` as `Change`s, the shape `changes()` returns for the working tree.
 *
 * Two `git diff`s for the whole range, not a `git show` and a diff per file:
 * these calls are synchronous on the server, and a range holding a few
 * thousand files (a vendored directory, a build folder committed by mistake)
 * took minutes and froze every other request meanwhile. A range is only ever
 * read for its hunks, its diff and whether a file was created or deleted, so
 * `before`/`after` carry no text here — just `null` where the file is absent.
 */
function between(repo: string, from: string, to: string): Change[] {
  const full = perFile(git(repo, "diff", "--no-color", "--no-renames", "-U3", from, to));
  const zero = perFile(git(repo, "diff", "--no-color", "--no-renames", "-U0", from, to));
  const out: Change[] = [];
  for (const [path, lines] of [...full].sort(([a], [b]) => a.localeCompare(b))) {
    const created = lines.some((l) => l.startsWith("new file mode"));
    const deleted = lines.some((l) => l.startsWith("deleted file mode"));
    // A mode change alone moves no line.
    if (!created && !deleted && !lines.some((l) => l.startsWith("@@") || l.startsWith("Binary files"))) continue;
    const hunks = (zero.get(path) ?? []).flatMap((l) => {
      const m = HUNK.exec(l);
      return m ? [{ os: +m[1], ol: m[2] === undefined ? 1 : +m[2], ns: +m[3], nl: m[4] === undefined ? 1 : +m[4] }] : [];
    });
    const body = lines.filter((l) => !/^(index |--- |\+\+\+ |new file mode|deleted file mode|old mode|new mode)/.test(l));
    const diff = [`--- ${created ? "/dev/null" : `a/${path}`}`, `+++ ${deleted ? "/dev/null" : `b/${path}`}`, ...body].join("\n");
    out.push({ path, before: created ? null : "", after: deleted ? null : "", hunks, diff });
  }
  return out;
}

/** `rev` as git resolves it, or "" where it names nothing in this checkout. */
const resolve = (repo: string, rev: string) => git(repo, "rev-parse", "--short", rev).trim();

const counted = (c: Change): FileChange => {
  const lines = c.diff.split("\n");
  return {
    path: c.path,
    verdict: c.before === null ? "added" : c.after === null ? "removed" : "changed",
    diff: c.diff,
    added: lines.filter((l) => l.startsWith("+") && !l.startsWith("+++")).length,
    removed: lines.filter((l) => l.startsWith("-") && !l.startsWith("---")).length,
  };
};

/* ── sections ────────────────────────────────────────────────── */

interface Placed {
  node: Node;
  path: Node[];
}

/** Every section, root first. Mirrors `walk` in scripts/generate/update.ts. */
function walk(roots: Node[]): Placed[] {
  const out: Placed[] = [];
  const go = (n: Node, up: Node[]) => {
    const path = [...up, n];
    out.push({ node: n, path });
    for (const c of n.children ?? []) go(c, path);
  };
  roots.forEach((r) => go(r, []));
  return out;
}

/**
 * A section's verdict from its own references, the same test `targets()` makes:
 * `changed` where a reference overlaps a changed line, `removed` where every
 * file it cites is gone. `added` is never reached from one bluprint — a section the
 * `to` side has and the `from` side does not can only be seen by comparing two
 * trees, which `treeDiff` does.
 */
function verdicts(bluprint: BluprintFile, byPath: Map<string, Change>, carry?: (file: string) => Change | undefined): SectionDiff[] {
  return walk(bluprint.AUTHORED).map(({ node, path }) => {
    const files = new Map<string, { s: number; e: number }[]>();
    let gone = 0;
    let cited = 0;
    for (const ref of refs(node)) {
      // Every ref counts toward "all it cites is gone", including those in
      // files that did not change: a section still citing live code is not removed.
      cited++;
      const c = byPath.get(ref.file);
      if (!c) continue;
      // A ref numbered to the bluprint's text, carried to the `from` side's.
      const k = carry?.(ref.file);
      const r = k ? { ...ref, s: moved(k, ref.s), e: moved(k, ref.e) } : ref;
      if (c.after === null) gone++;
      if (!touches(c, r.s, r.e)) continue;
      files.set(r.file, [...(files.get(r.file) ?? []), { s: ref.s, e: ref.e, ...(k ? { at: { s: r.s, e: r.e } } : {}) }]);
    }
    return {
      id: node.id,
      title: node.title,
      path: path.map((n) => n.id),
      verdict: files.size === 0 ? "untouched" : cited > 0 && gone === cited ? "removed" : "changed",
      files: [...files].map(([path, lines]) => ({ path, lines })),
    };
  });
}

const AT = /^(.+):(\d+)(?:-(\d+))?$/;

/** The `at` of each diagram arrow whose cited line a change landed on. */
function arrowsChanged(bluprint: BluprintFile, byPath: Map<string, Change>, carry?: (file: string) => Change | undefined): string[] {
  const out: string[] = [];
  for (const { node } of walk(bluprint.AUTHORED))
    for (const b of node.anatomy ?? [])
      if (b.kind === "diagram")
        for (const a of b.arrows) {
          const m = a.at ? AT.exec(a.at) : null;
          const c = m && byPath.get(m[1]);
          if (!m || !c) continue;
          const k = carry?.(m[1]);
          const s = +m[2];
          const e = +(m[3] ?? m[2]);
          if (touches(c, k ? moved(k, s) : s, k ? moved(k, e) : e)) out.push(a.at!);
        }
  return out;
}

/** Each section's count of changed sections beneath it. */
function rollUp(sections: SectionDiff[]): SectionDiff[] {
  const moved = sections.filter((s) => s.verdict !== "untouched");
  return sections.map((s) => {
    const n = moved.filter((m) => m.path.length > s.path.length && s.path.every((id, i) => m.path[i] === id)).length;
    return n ? { ...s, inside: n } : s;
  });
}

/** Changed files whose changes no section covers, each with the section citing that file nearest its first change. */
function outsideOf(bluprint: BluprintFile, byPath: Map<string, Change>, sections: SectionDiff[]): BluprintDiff["outside"] {
  const covered = new Set(sections.flatMap((s) => s.files.map((f) => f.path)));
  const all = walk(bluprint.AUTHORED);
  const out: NonNullable<BluprintDiff["outside"]> = [];
  for (const [path, c] of byPath) {
    if (covered.has(path) || c.after === null) continue;
    const at = c.hunks[0]?.os ?? 1;
    let best: { p: Placed; d: number } | null = null;
    for (const p of all)
      for (const r of refs(p.node))
        if (r.file === path) {
          const d = Math.min(Math.abs(r.s - at), Math.abs(r.e - at));
          if (!best || d < best.d || (d === best.d && p.path.length > best.p.path.length)) best = { p, d };
        }
    out.push({ path, ...(best ? { near: best.p.path.map((n) => n.id) } : {}) });
  }
  return out;
}

/* ── two bluprints, block by block ────────────────────────────────── */

/** The key a row is matched by: a schema column's name, a table row's first cell, a pair's label. */
function rowsOf(b: Anatomy): { key: string; cells: string[] }[] | undefined {
  switch (b.kind) {
    case "schema":
      return b.rows.map((c) => ({ key: c.name, cells: [c.name, c.type, c.key ?? "", c.nullable ? "null" : "", c.note ?? ""] }));
    case "table":
      return b.rows.map((r) => ({ key: r[0] ?? "", cells: r }));
    case "facts":
      return b.rows.map((r) => ({ key: r.label, cells: [r.label, r.value] }));
    case "routes":
      return b.rows.map((r) => ({ key: `${r.method} ${r.path}`, cells: [r.method, r.path, r.auth, r.note ?? ""] }));
    case "flow":
      return b.rows.map((r) => ({ key: String(r.n), cells: [String(r.n), r.title, r.detail] }));
    case "chips":
      return b.rows.map((r) => ({ key: r.label, cells: [r.label, r.note ?? ""] }));
    case "map":
      return b.rows.map((r) => ({ key: r.from, cells: [r.from, r.to] }));
    default:
      return undefined;
  }
}

const same = (a: string[], b: string[]) => a.length === b.length && a.every((x, i) => x === b[i]);

/**
 * Rows matched by key: what the `from` side had, what the `to` side has, and
 * what changed in between.
 *
 * Keyed by the key AND how many rows before it already used that key, because
 * a first cell is not unique. The `explorify-example › ex-lifecycle` table
 * names `launch` and `create-event` twice each, as the start of two different
 * hops; matching on the bare key collapsed each pair to its last row and made
 * two byte-identical bluprints report four changed rows.
 */
function rowDiff(a: Anatomy, b: Anatomy): RowDiff[] | undefined {
  const was = rowsOf(a);
  const now = rowsOf(b);
  if (!was || !now) return undefined;
  const nth = (rows: { key: string }[]) => {
    const seen = new Map<string, number>();
    return rows.map((r) => {
      const n = seen.get(r.key) ?? 0;
      seen.set(r.key, n + 1);
      return `${r.key}#${n}`;
    });
  };
  const wasAt = nth(was);
  const nowAt = nth(now);
  const has = new Map(nowAt.map((k, i) => [k, i]));
  // Walked in the `to` side's order, with each removed row emitted where it
  // used to be — so a dropped column sits red among the ones that stayed and a
  // renamed one reads as a row out beside a row in, which is the whole point.
  const out: RowDiff[] = [];
  // A row the `to` side still has somewhere was only moved, so it is passed
  // over here and reported where it now is. Only a row with no counterpart
  // anywhere is `removed`.
  const gone = (i: number) => {
    if (!has.has(wasAt[i])) out.push({ key: was[i].key, verdict: "removed", before: was[i].cells });
  };
  let i = 0;
  for (const [j, k] of nowAt.entries()) {
    const from = wasAt.indexOf(k);
    // Everything the `from` side had before this row went away here.
    while (i < from || (i < was.length && from === -1 && !has.has(wasAt[i]))) gone(i++);
    if (from === -1) {
      out.push({ key: now[j].key, verdict: "added", after: now[j].cells });
      continue;
    }
    out.push({ key: now[j].key, verdict: same(was[from].cells, now[j].cells) ? "untouched" : "changed", before: was[from].cells, after: now[j].cells });
    // A row that moved earlier must not rewind `i` over rows already reported.
    i = Math.max(i, from + 1);
  }
  while (i < was.length) gone(i++);
  return out;
}

const parts = (
  was: { key: string; label?: string }[],
  now: { key: string; label?: string }[],
): PartDiff[] => {
  const has = new Set(now.map((p) => p.key));
  const had = new Map(was.map((p) => [p.key, p]));
  return [
    ...was.map((p): PartDiff => ({ key: p.key, label: p.label, verdict: has.has(p.key) ? (had.get(p.key)!.label === now.find((q) => q.key === p.key)!.label ? "untouched" : "changed") : "removed" })),
    ...now.filter((p) => !had.has(p.key)).map((p): PartDiff => ({ key: p.key, label: p.label, verdict: "added" })),
  ];
};

/** One block's diff, or null where the two are identical. */
function blockDiff(path: string[], at: number, a: Anatomy, b: Anatomy): BlockDiff | null {
  if (a.kind === "diagram" && b.kind === "diagram") {
    const boxes = parts(a.boxes.map((x) => ({ key: x.id, label: x.label })), b.boxes.map((x) => ({ key: x.id, label: x.label })));
    const arrows = parts(
      a.arrows.map((x) => ({ key: `${x.from}→${x.to}`, label: x.label })),
      b.arrows.map((x) => ({ key: `${x.from}→${x.to}`, label: x.label })),
    );
    const moved = [...boxes, ...arrows].some((p) => p.verdict !== "untouched");
    return moved ? { path, at, kind: "diagram", verdict: "changed", boxes, arrows } : null;
  }
  const rows = rowDiff(a, b);
  if (!rows) return JSON.stringify(a) === JSON.stringify(b) ? null : { path, at, kind: a.kind, verdict: "changed" };
  return rows.some((r) => r.verdict !== "untouched") ? { path, at, kind: a.kind, verdict: "changed", rows } : null;
}

/**
 * Two bluprints' section trees, matched by id: sections that arrived, sections that
 * went, and within the ones both have, the blocks whose rows or boxes moved.
 *
 * Exported because this is the half that does not need git at all: given any
 * two `BluprintFile`s — two commits' bluprints, or a bluprint before and after an update —
 * it says what changed on the bluprint itself. A block's `at` is its index in
 * `b`'s section, the bluprint the canvas draws; a block only `a` had keeps `a`'s.
 */
function treeDiff(a: BluprintFile, b: BluprintFile): { sections: SectionDiff[]; blocks: BlockDiff[] } {
  const was = walk(a.AUTHORED);
  const now = new Map(walk(b.AUTHORED).map((p) => [p.node.id, p]));
  const sections: SectionDiff[] = [];
  const blocks: BlockDiff[] = [];
  for (const { node, path } of was) {
    const ids = path.map((n) => n.id);
    const to = now.get(node.id);
    if (!to) {
      sections.push({ id: node.id, title: node.title, path: ids, verdict: "removed", files: [] });
      continue;
    }
    const mine = node.anatomy ?? [];
    const theirs = to.node.anatomy ?? [];
    for (const [i, block] of mine.entries()) {
      // Blocks are not identified, so they are matched by position within the
      // kinds of block the section has — the only stable handle on them.
      const other = theirs.filter((x) => x.kind === block.kind)[mine.slice(0, i).filter((x) => x.kind === block.kind).length];
      if (!other) {
        blocks.push({ path: ids, at: i, kind: block.kind, verdict: "removed" });
        continue;
      }
      // Indexed where `b` has it: `b` is the bluprint on screen.
      const d = blockDiff(ids, theirs.indexOf(other), block, other);
      if (d) blocks.push(d);
    }
    // Added is the mirror of removed: past the count of that kind it had.
    for (const [i, block] of theirs.entries())
      if (theirs.slice(0, i).filter((x) => x.kind === block.kind).length >= mine.filter((x) => x.kind === block.kind).length)
        blocks.push({ path: ids, at: i, kind: block.kind, verdict: "added" });
    const fields = (["title", "sub", "detail", "state"] as const).some((k) => node[k] !== to.node[k]);
    sections.push({
      id: node.id,
      title: to.node.title,
      path: ids,
      verdict: fields || blocks.some((x) => x.path.join("/") === ids.join("/")) ? "changed" : "untouched",
      files: [],
    });
  }
  for (const [id, { node, path }] of now)
    if (!was.some((p) => p.node.id === id))
      sections.push({ id, title: node.title, path: path.map((n) => n.id), verdict: "added", files: [] });
  return { sections, blocks };
}

/* ── a ref a human typed ─────────────────────────────────────── */

/**
 * What `resolveRef` understood, so the UI can show its reading back.
 *
 * `commit` is the sha the range side becomes. `span` is true where the phrase
 * named ONE commit and so means "what that commit did" — see `resolveRef`.
 */
export interface Resolved {
  commit: string;
  /** A short line for the UI: the reading, the sha, and the subject. */
  how: string;
  span?: boolean;
}

/** `%h "subject"`, for saying which commit a phrase landed on. */
const describe = (root: string, commit: string) => {
  const line = git(root, "log", "-1", "--format=%h %s", commit).trim();
  const at = line.indexOf(" ");
  return at === -1 ? line : `${line.slice(0, at)} "${line.slice(at + 1)}"`;
};

/** The phrase as git itself reads it, where git reads it at all. */
const verify = (root: string, rev: string) => git(root, "rev-parse", "--verify", "--quiet", `${rev}^{commit}`).trim();

/**
 * A commit from an English phrase, or an error naming what was tried.
 *
 * Anything git already understands — a sha, `HEAD`, `HEAD~2`, a tag, a branch —
 * is passed through first, because a caller who typed a real ref means it. Only
 * what git refuses is read as English, and only these shapes:
 *
 *   last/latest/previous commit [by <author>] · <author>'s last commit
 *   N commits ago · last N commits
 *
 * `span` marks the first group: naming a single commit ("the last commit by
 * hindra2") is how people say "show me what THAT commit changed", which is
 * `<it>~1..<it>`, not `<it>..`. The caller opens the range; this only says the
 * phrase asked for one, and `how` states the range either way so the reading is
 * never silent. "N commits ago" is a point, not a span — it names where to
 * start measuring from, so it is left alone.
 *
 * No phrase ever falls back to HEAD. A diff against the wrong commit that
 * claims to be right is worse than an error.
 */
export function resolveRef(root: string, phrase: string): Resolved | { error: string } {
  const raw = phrase.trim();
  if (!raw) return { error: "No revision given." };

  const asRef = verify(root, raw);
  if (asRef) return { commit: asRef, how: describe(root, asRef) };

  const text = raw.toLowerCase().replace(/[.!?]+$/, "").trim();

  // "3 commits ago", "last 3 commits" → HEAD~3.
  const back = /^(?:the\s+)?(?:last|previous)\s+(\d+)\s+commits?$/.exec(text) ?? /^(\d+)\s+commits?\s+(?:ago|back)$/.exec(text);
  if (back) {
    const n = Number(back[1]);
    const commit = verify(root, `HEAD~${n}`);
    return commit
      ? { commit, how: `${n} commit${n === 1 ? "" : "s"} before HEAD · ${describe(root, commit)}` }
      : { error: `Tried HEAD~${n} for "${raw}", and this checkout does not go back that far.` };
  }

  // "last commit", "the latest commit by hindra2", "hindra2's last commit".
  const mine = /^(?:the\s+)?(?:last|latest|previous|most\s+recent)\s+commit(?:\s+(?:by|from|of)\s+(.+))?$/.exec(text);
  const theirs = /^(.+?)(?:'s|s')\s+(?:last|latest|previous|most\s+recent)\s+commit$/.exec(text);
  if (!mine && !theirs) return { error: `Could not read "${raw}" as a revision: git does not know it, and it is not a phrase this understands (try "last commit", "last commit by <author>", or "2 commits ago").` };

  const author = (mine?.[1] ?? theirs?.[1])?.trim();
  if (!author) {
    const commit = verify(root, "HEAD");
    return commit ? { commit, how: `the last commit · ${describe(root, commit)}`, span: true } : { error: "This checkout has no commits." };
  }
  // `git log --author` already matches substrings and regex against both name
  // and email, so `hindra2` finds `Hindra2 <h@x.com>`. Reimplementing that
  // against a log dump would only be a worse version of it. `-i` because the
  // phrase reached here lowercased, and --author is case-sensitive without it:
  // a full name typed as the user says it would otherwise never match.
  const commit = git(root, "log", "-1", "-i", "--format=%H", `--author=${author}`).trim();
  if (!commit) return { error: `No commit by "${author}" in this checkout's history (searched author names and emails with git log --author).` };
  return { commit, how: `${author}'s last commit · ${describe(root, commit)}`, span: true };
}

/**
 * Where each file renamed between commits `a` and `b` ended up: its path at
 * `a` to its path at `b`. Followed one commit at a time, because one diff
 * across a long gap holds too many files for git to look for renames in.
 * Commits that are not one behind the other move nothing.
 */
function movesBetween(root: string, a: string, b: string): Map<string, string> {
  const ahead = (x: string, y: string) => git(root, "rev-list", "--count", `${y}..${x}`).trim() === "0";
  const forward = ahead(a, b);
  if (!forward && !ahead(b, a)) return new Map();
  const [from, to] = forward ? [a, b] : [b, a];
  // Today's path for each path as it was at `from`, renamed oldest commit first.
  const now = new Map<string, string>();
  const was = new Map<string, string>();
  for (const l of git(root, "log", "--reverse", "--format=", "--name-status", "-M", `${from}..${to}`).split("\n")) {
    const [status, old, moved] = l.split("\t");
    if (!status?.startsWith("R") || !moved) continue;
    const first = was.get(old) ?? old;
    was.delete(old);
    was.set(moved, first);
    now.set(first, moved);
  }
  return forward ? now : new Map([...now].map(([x, y]) => [y, x]));
}

/* ── the answer ──────────────────────────────────────────────── */

/**
 * What changed in `root` between `from` and `to`, in the bluprint's terms.
 *
 * `to` undefined is the working tree, uncommitted work included. `other` is the
 * `to` side's own bluprint where one exists, and then `bluprint` is the `from` side's:
 * the boxes, rows and sections between the two are compared as well. Without
 * it there is one bluprint, so the answer is section verdicts off the code and no
 * block diff.
 *
 * `seen` is the project's base.json: once an update has run, the bluprint's lines
 * are numbered to the code as that update saw it, not to its commit, so the
 * working-tree diff starts from that text exactly as the updater's does.
 */
export function bluprintDiff(root: string, from: string | undefined, to: string | undefined, bluprint: BluprintFile, seen: Base = {}, other?: BluprintFile): BluprintDiff {
  const base = resolve(root, from ?? bluprint.RUN.commit);
  const head = to ? resolve(root, to) : null;
  if (!base) throw new RangeError(`no such commit: ${from ?? bluprint.RUN.commit}`);
  if (to && !head) throw new RangeError(`no such commit: ${to}`);

  const made = resolve(root, bluprint.RUN.commit);
  // `seen` is the bluprint's text, so it is the starting point only from the bluprint's commit.
  const found = head ? between(root, base, head) : changes(root, base, base === made ? seen : {});
  if (!made) {
    const files = found.map(counted);
    return {
      basis: "files",
      from: base,
      to: head,
      why: `The bluprint was made at ${bluprint.RUN.commit}, which this checkout no longer has, so its line references cannot be carried to ${base}. Comparing files instead.`,
      files,
      sections: [],
      blocks: [],
    };
  }

  // The bluprint's line references are numbered to the text it was made from: its
  // commit, or base.json after an update. A diff starting anywhere else is
  // checked against them only once they are carried through the change from
  // that text to `from`, file by file, the same arithmetic the updater moves
  // refs with. A ref whose own lines changed on the way lands near, not on.
  //
  // A file may also have moved between `from` and the bluprint's commit, so a
  // commit made under its old path is still held to the sections citing it.
  const exact = base === made && (!head || !Object.keys(seen).length);
  const renamed = exact ? new Map<string, string>() : movesBetween(root, base, made);
  const back = new Map([...renamed].map(([was, now]) => [now, was]));
  const files = found.map((c) => ({ ...counted(c), ...(renamed.has(c.path) ? { mapped: renamed.get(c.path) } : {}) }));
  const byPath = new Map(found.map((c) => [renamed.get(c.path) ?? c.path, c]));

  const carried = new Map<string, Change | undefined>();
  const start = (path: string) => (path in seen ? seen[path] : hasAt(root, made, path) ? git(root, "show", `${made}:${path}`) : null);
  const carry = (path: string) => {
    if (!carried.has(path)) {
      const before = start(path);
      const there = back.get(path) ?? path;
      const after = hasAt(root, base, there) ? git(root, "show", `${base}:${there}`) : null;
      carried.set(path, before !== null && after !== null && before !== after ? { path, before, after, ...diffOf(path, before, after) } : undefined);
    }
    return carried.get(path);
  };
  const sections = rollUp(verdicts(bluprint, byPath, exact ? undefined : carry));
  const arrows = arrowsChanged(bluprint, byPath, exact ? undefined : carry);
  const outside = outsideOf(bluprint, byPath, sections);
  if (!other) return { basis: "sections", from: base, to: head, files, sections, blocks: [], arrows, outside };
  const both = overTree(sections, bluprint, other);
  return { basis: "sections", from: base, to: head, files, ...both, arrows, outside };
}

/**
 * Two bluprints: what the pictures say changed, over what the code says did,
 * keeping the files the code verdict found behind each section.
 */
function overTree(code: SectionDiff[], a: BluprintFile, b: BluprintFile): Pick<BluprintDiff, "sections" | "blocks"> {
  const tree = treeDiff(a, b);
  const byId = new Map(code.map((s) => [s.id, s]));
  const merged = tree.sections.map((t) => {
    const c = byId.get(t.id);
    return { ...t, verdict: t.verdict === "untouched" ? (c?.verdict ?? "untouched") : t.verdict, files: c?.files ?? [] };
  });
  return { sections: rollUp(merged), blocks: tree.blocks };
}

/**
 * What one agent turn did, from the snapshot the updater kept before it ran
 * (scripts/generate/update.ts): the code as that update read it, and the bluprint
 * before and after. No git is involved, so a turn's diff stays exact however
 * far the checkout has moved on since.
 */
export function turnDiff(before: BluprintFile, after: BluprintFile, texts: { path: string; before: string | null; after: string | null }[]): BluprintDiff {
  const found: Change[] = texts.filter((t) => t.before !== t.after).map((t) => ({ ...t, ...diffOf(t.path, t.before, t.after) }));
  const byPath = new Map(found.map((c) => [c.path, c]));
  const code = verdicts(before, byPath);
  const both = overTree(code, before, after);
  return {
    basis: "sections",
    from: before.RUN.commit,
    to: null,
    files: found.map(counted),
    ...both,
    arrows: arrowsChanged(before, byPath),
    outside: outsideOf(before, byPath, both.sections),
  };
}

/** One commit, as the commit list and the timeline draw it. */
export interface Commit {
  sha: string;
  short: string;
  /** ISO 8601, the author's date. */
  at: string;
  author: string;
  subject: string;
  email?: string;
  /** Who made the commit, where that is not the author (a rebase, a merge on a host). */
  committer?: string;
  committerEmail?: string;
  /** ISO 8601, the committer's date. */
  committed?: string;
  parents?: string[];
  /** Branches and tags pointing here, as `git log --decorate` names them: `HEAD -> main`, `tag: v1`. */
  refs?: string[];
  /** The message after its first line. */
  body?: string;
  added: number;
  removed: number;
  /** Every path it touched; a rename is its new path. */
  files: string[];
  /** Its renames, `[was, became]`, so older paths can be followed to today's. */
  moves?: [string, string][];
}

/** A numstat path, `a => b` or `dir/{a => b}/x`, as the path it was and the one it became. */
function sides(spec: string): [string, string] {
  const brace = /^(.*)\{(.*) => (.*)\}(.*)$/.exec(spec);
  if (brace) {
    const [, pre, a, b, post] = brace;
    const join = (m: string) => `${pre}${m}${post}`.replace(/\/\//g, "/").replace(/^\//, "");
    return [join(a), join(b)];
  }
  const plain = /^(.*) => (.*)$/.exec(spec);
  return plain ? [plain[1], plain[2]] : [spec, spec];
}

/**
 * The last `n` commits, newest first, from one `git log`. A binary file counts
 * no lines (numstat prints `-`), and a rename is listed as the path it became.
 */
const logs = new Map<string, { head: string; commits: Commit[] }>();

export function commitLog(root: string, n = 50): Commit[] {
  // Commits never change, so the log holds until HEAD moves.
  const head = git(root, "rev-parse", "HEAD").trim();
  const kept = logs.get(`${root}\0${n}`);
  if (kept && kept.head === head) return kept.commits;
  const out: Commit[] = [];
  // Files over 1 MB count as binary, unread: one commit of build output
  // otherwise costs seconds of numstat for lines nobody reads.
  // The message body runs over lines of its own, so \x1d closes the header
  // before numstat's lines begin.
  const log = git(
    root,
    "-c",
    "core.bigFileThreshold=1m",
    "log",
    `-n${n}`,
    "--format=%x1e%H%x1f%h%x1f%aI%x1f%an%x1f%s%x1f%ae%x1f%cn%x1f%ce%x1f%cI%x1f%P%x1f%D%x1f%b%x1d",
    "--numstat",
  );
  for (const block of log.split("\x1e")) {
    const cut = block.indexOf("\x1d");
    if (cut < 0) continue;
    const [sha, short, at, author, subject, email, committer, committerEmail, committed, parents, refs, body] = block.slice(0, cut).split("\x1f");
    if (!sha || subject === undefined) continue;
    const c: Commit = {
      sha,
      short,
      at,
      author,
      subject,
      email,
      committer,
      committerEmail,
      committed,
      parents: parents ? parents.split(" ") : [],
      refs: refs ? refs.split(", ") : [],
      body: body?.trim() || undefined,
      added: 0,
      removed: 0,
      files: [],
    };
    for (const line of block.slice(cut + 1).split("\n")) {
      const [a, r, path] = line.split("\t");
      if (path === undefined) continue;
      c.added += Number(a) || 0;
      c.removed += Number(r) || 0;
      const [was, now] = sides(path);
      c.files.push(now);
      if (was !== now) (c.moves ??= []).push([was, now]);
    }
    out.push(c);
  }
  logs.set(`${root}\0${n}`, { head, commits: out });
  return out;
}

app/lib/server/docs.ts:
/**
 * Server-side: the Markdown (and HTML pages) a project keeps beside its code —
 * its README, design notes, decision logs, agent instructions — for the docs reader
 * (components/bluprint/docs.tsx). Paths come from git, never from the caller, so this
 * lists only what the checkout tracks or would track; the text itself is read
 * through `/api/source`, behind the same containment check as the code.
 */

import { execFileSync } from "node:child_process";
import { closeSync, openSync, readSync } from "node:fs";
import { join } from "node:path";

export interface Doc {
  /** Repo-relative. */
  path: string;
  /** Its first heading, or "" when it has none. */
  title: string;
}

const MAX_DOCS = 500;
const SKIP = /(^|\/)(node_modules|vendor|dist|build|out|\.next)\//;
/** An HTML file is a doc only outside tests, fixtures and generated reports, where most HTML in a repository is. */
const NOT_DOC_HTML = /(^|\/)(tests?|__tests__|spec|fixtures?|e2e|coverage|public|static|templates?)\//i;

/** The first heading in the first few KB: enough for a title, cheap on a long log. */
function titleOf(file: string): string {
  try {
    const fd = openSync(file, "r");
    const buf = Buffer.alloc(4096);
    const n = readSync(fd, buf, 0, buf.length, 0);
    closeSync(fd);
    const head = buf.subarray(0, n).toString("utf8");
    return (
      head.match(/^#{1,3}\s+(.+)$/m)?.[1].trim() ??
      head.match(/<title[^>]*>([^<]+)<\/title>|<h1[^>]*>([^<]+)<\/h1>/i)?.slice(1).find(Boolean)?.trim() ??
      ""
    );
  } catch {
    return "";
  }
}

/** Root-level docs first, README leading, then the rest by path. */
const order = (a: string, b: string) => {
  const depth = (p: string) => p.split("/").length;
  const readme = (p: string) => (/(^|\/)readme\.mdx?$/i.test(p) ? 0 : 1);
  return depth(a) - depth(b) || readme(a) - readme(b) || a.localeCompare(b);
};

export function listDocs(root: string): Doc[] {
  let listed: string[];
  try {
    listed = execFileSync("git", ["-C", root, "ls-files", "-z", "--cached", "--others", "--exclude-standard", "--", "*.md", "*.mdx", "*.MD", "*.html", "*.htm"], {
      encoding: "utf8",
      maxBuffer: 16 << 20,
      stdio: ["ignore", "pipe", "ignore"],
      windowsHide: true,
    }).split("\0");
  } catch {
    return [];
  }
  return [...new Set(listed.filter((p) => p && !SKIP.test(p) && !(/\.html?$/i.test(p) && NOT_DOC_HTML.test(p))))]
    .sort(order)
    .slice(0, MAX_DOCS)
    .map((path) => ({ path, title: titleOf(join(root, path)) }));
}

/** A landing demo's docs: the Markdown among the files committed beside its bluprint. */
export function demoDocs(source: Record<string, string>): Doc[] {
  return Object.keys(source)
    .filter((p) => /\.(mdx?|html?)$/i.test(p))
    .sort(order)
    .map((path) => ({ path, title: source[path].match(/^#{1,3}\s+(.+)$/m)?.[1].trim() ?? "" }));
}

app/lib/server/history.ts:
/**
 * How the code got here: every commit, placed on the bluprint's own top-level
 * sections (D73).
 *
 * A commit is drawn on the roots that own the files it touched, by the cut the
 * bluprint was made from (`owners`, scripts/generate/cut.ts) — the same answer the
 * updater gives when it decides which root a new file belongs to. A bluprint with
 * no cut on disk falls back to the files each root's sections cite. A file no
 * root owns lands on "Elsewhere": a timeline that dropped it would draw a
 * quieter history than the one that happened.
 *
 * Paths are followed through renames, newest to oldest, so a file that lived
 * at `ui/x.ts` before it moved to `app/x.ts` still lands on today's root.
 *
 * Everything here is git and arithmetic, read on the server. Telling the
 * story in chapters is a model run (scripts/generate/story.ts); this is what
 * that run is handed, and what its chapters are checked against.
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { commitLog } from "@/lib/server/diff";
import type { Node } from "@/lib/bluprint/schema";
import type { BluprintFile } from "@/lib/bluprint/build";
import { owners, type Cut } from "@/scripts/generate/cut";
import { git, refs } from "@/scripts/generate/gitdiff";

/** The cap on commits read. Past it the oldest are left off, and `capped` says so. */
const MOST = 2000;

/** The id of the row for files no root owns. */
export const ELSEWHERE = "";

export interface TimelineCommit {
  sha: string;
  short: string;
  at: string;
  author: string;
  subject: string;
  added: number;
  removed: number;
  /** The roots its files belong to, by id; `ELSEWHERE` for files none owns. */
  roots: string[];
}

export interface Chapter {
  title: string;
  /** Short shas, oldest first: the chapter's first and last commit. */
  from: string;
  to: string;
  detail: string;
  roots: string[];
}

export interface Story {
  head: string;
  chapters: Chapter[];
  at: string;
  usd: number;
  seconds: number;
}

export interface Timeline {
  head: string;
  /** The bluprint's roots in its order, then Elsewhere when anything lands there. */
  roots: { id: string; title: string }[];
  /** Oldest first. */
  commits: TimelineCommit[];
  capped: boolean;
}

/** Every file cited anywhere under each root, for a bluprint with no cut on disk. */
function citedBy(roots: Node[]): Map<string, string[]> {
  const out = new Map<string, string[]>();
  const walk = (root: Node, n: Node) => {
    for (const r of refs(n)) if (!out.get(r.file)?.includes(root.id)) out.set(r.file, [...(out.get(r.file) ?? []), root.id]);
    (n.children ?? []).forEach((c) => walk(root, c));
  };
  roots.forEach((r) => walk(r, r));
  return out;
}

/** The timeline, from git, with no cache: what the route caches and the story run reads. */
export function timelineOf(root: string, bluprint: BluprintFile, cut: Cut | null): Timeline {
  const head = git(root, "rev-parse", "--short", "HEAD").trim();
  const ids = new Set(bluprint.AUTHORED.map((r) => r.id));
  const cited = cut ? null : citedBy(bluprint.AUTHORED);
  const ownersOf = (path: string) => (cut ? owners(cut, path) : (cited!.get(path) ?? [])).filter((id) => ids.has(id));

  const log = commitLog(root, MOST);
  // Newest first, so a rename is met before the commits that used its old path.
  const today = new Map<string, string>();
  const commits: TimelineCommit[] = [];
  for (const c of log) {
    const roots = new Set<string>();
    for (const f of c.files) {
      const mine = ownersOf(today.get(f) ?? f);
      if (!mine.length) roots.add(ELSEWHERE);
      mine.forEach((id) => roots.add(id));
    }
    for (const [was, now] of c.moves ?? []) today.set(was, today.get(now) ?? now);
    commits.push({ sha: c.sha, short: c.short, at: c.at, author: c.author, subject: c.subject, added: c.added, removed: c.removed, roots: [...roots] });
  }
  commits.reverse();
  const rows = bluprint.AUTHORED.map((r) => ({ id: r.id, title: r.title }));
  if (commits.some((c) => c.roots.includes(ELSEWHERE))) rows.push({ id: ELSEWHERE, title: "Elsewhere" });
  return { head, roots: rows, commits, capped: log.length === MOST };
}

/** The project's cut, where the generator left one. */
export function cutOf(dir: string): Cut | null {
  const file = join(dir, ".cache", "cut.json");
  return existsSync(file) ? JSON.parse(readFileSync(file, "utf8")) : null;
}

/**
 * The timeline for a project, cached in its vault directory as timeline.json.
 * The key is HEAD and the bluprint's roots: a new commit, or a remake that cut the
 * code differently, reads git again; opening it twice does not.
 */
export function cachedTimeline(root: string, dir: string, bluprint: BluprintFile): Timeline {
  const cut = cutOf(dir);
  const head = git(root, "rev-parse", "--short", "HEAD").trim();
  const key = [head, ...bluprint.AUTHORED.map((r) => r.id), cut ? "cut" : "cited"].join(" ");
  const file = join(dir, "timeline.json");
  try {
    const hit = JSON.parse(readFileSync(file, "utf8"));
    if (hit.key === key) return hit.timeline;
  } catch {
    /* none yet */
  }
  const timeline = timelineOf(root, bluprint, cut);
  writeFileSync(file, JSON.stringify({ key, timeline }) + "\n");
  return timeline;
}

/** The chapters a story run wrote, if one has. */
export function storyOf(dir: string): Story | null {
  const file = join(dir, "story.json");
  return existsSync(file) ? JSON.parse(readFileSync(file, "utf8")) : null;
}

/**
 * What is wrong with a set of chapters, against the timeline they tell:
 * every end a real commit, each chapter's ends in order, the chapters in
 * order without overlapping, and roots that exist. The words are held to the
 * bluprint's own rules (D38): a title of a few words, a detail of two sentences.
 */
export function chapterProblems(chapters: Chapter[], t: Timeline): string[] {
  const at = new Map(t.commits.map((c, i) => [c.short, i]));
  const ids = new Set(t.roots.map((r) => r.id));
  const out: string[] = [];
  if (chapters.length < 2 || chapters.length > 12) out.push(`Tell it in 2 to 12 chapters, not ${chapters.length}.`);
  let last = -1;
  chapters.forEach((c, n) => {
    const name = `Chapter ${n + 1} ("${c.title}")`;
    const a = at.get(c.from);
    const b = at.get(c.to);
    if (a === undefined) out.push(`${name}: "${c.from}" is not a commit in the list.`);
    if (b === undefined) out.push(`${name}: "${c.to}" is not a commit in the list.`);
    if (a !== undefined && b !== undefined) {
      if (a > b) out.push(`${name}: it starts at ${c.from}, which comes after its end ${c.to}.`);
      if (a <= last) out.push(`${name}: it starts at ${c.from}, inside the chapter before it.`);
      last = Math.max(last, b);
    }
    const words = c.title.trim().split(/\s+/).filter(Boolean).length;
    if (words < 1 || words > 4) out.push(`${name}: a title is 1 to 4 words, this is ${words}.`);
    if (c.detail.split(/\s+/).filter(Boolean).length > 40 || (c.detail.match(/[.!?](\s|$)/g)?.length ?? 0) > 2)
      out.push(`${name}: the detail is at most two sentences and 40 words.`);
    for (const r of c.roots) if (!ids.has(r)) out.push(`${name}: "${r}" is not one of the bluprint's roots.`);
  });
  return out;
}

/* ── one commit, in brief ────────────────────────────────────── */

/** A commit told in a few sentences, kept by its full sha: a commit never changes, so neither does this. */
export interface Summary {
  text: string;
  at: string;
  usd: number;
}

const SUMMARIES = "summaries.json";
/** The diff a summary reads, at most: a commit of build output says what it is long before its end. */
const PATCH_MAX = 40_000;

export function summariesOf(dir: string): Record<string, Summary> {
  try {
    return JSON.parse(readFileSync(join(dir, SUMMARIES), "utf8"));
  } catch {
    return {};
  }
}

const SUMMARY_TOOL = {
  name: "summary",
  description: "What one commit did, in brief.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["summary"],
    properties: {
      summary: {
        type: "string",
        description: "At most two plain sentences and 40 words: the change that matters most first, then why if the diff shows it. For someone who knows the project. No file lists, no line counts, no lists of everything touched.",
      },
    },
  },
};

const asking = new Map<string, Promise<Summary>>();

/**
 * What a commit did, read from its message and diff by one model call (the
 * Claude Code backend, as the story uses) — only ever on the reader's click,
 * since it is paid. Two clicks on one commit share the one run.
 */
export function summarize(root: string, dir: string, sha: string, claude?: string): Promise<Summary> {
  const full = git(root, "rev-parse", "--verify", "--quiet", `${sha}^{commit}`).trim();
  if (!full) return Promise.reject(new RangeError("No such commit."));
  const kept = summariesOf(dir)[full];
  if (kept) return Promise.resolve(kept);
  const key = `${dir}\0${full}`;
  const running = asking.get(key);
  if (running) return running;
  const run = (async () => {
    const big = ["-c", "core.bigFileThreshold=1m"];
    const message = git(root, "show", "-s", "--format=%an <%ae>, %aI%n%n%B", full).trim();
    const stat = git(root, ...big, "show", "--format=", "--stat=120", "-M", full).trim();
    const patch = git(root, ...big, "show", "--format=", "--patch", "-M", full);
    const prompt = [
      `## Commit ${full.slice(0, 7)}\n${message}`,
      `## Files\n${stat}`,
      `## Diff${patch.length > PATCH_MAX ? ` (the first ${PATCH_MAX} of ${patch.length} characters)` : ""}\n${patch.slice(0, PATCH_MAX)}`,
      "## Task\nSay what this commit did. A message like \"wip: checkpoint\" says nothing: read the diff instead.",
    ].join("\n\n");
    // The backend finds the binary by this name; the app knows where it is.
    if (claude) process.env.SLOP_CLAUDE = claude;
    const { ccAsk } = await import("@/scripts/generate/claude-code");
    const { bill, MODELS } = await import("@/scripts/generate/bedrock");
    const before = bill.summary?.usd ?? 0;
    const r = await ccAsk<{ summary: string }>({
      model: MODELS[(process.env.BLUPRINT_SUMMARY ?? "sonnet") as keyof typeof MODELS] ?? MODELS.sonnet,
      system: "You read one git commit and say plainly what it did.",
      messages: [{ role: "user", content: prompt }],
      tool: SUMMARY_TOOL,
      stage: "summary",
    });
    const s: Summary = { text: r.summary.trim(), at: new Date().toISOString(), usd: (bill.summary?.usd ?? 0) - before };
    writeFileSync(join(dir, SUMMARIES), JSON.stringify({ ...summariesOf(dir), [full]: s }, null, 2));
    return s;
  })().finally(() => asking.delete(key));
  asking.set(key, run);
  return run;
}

app/lib/server/live.ts:
/**
 * The bluprint following the code as it is typed, before any model has looked.
 *
 * While a project's bluprint is open (app/api/bluprint polls it each second), its
 * checkout is watched. Each save works out, with no model call, what an
 * update would start from: which files differ from what the bluprint describes,
 * which sections cite the lines that changed, and where every cited line has
 * moved to. The page marks those sections at once and reads its code at the
 * moved lines; the update that rewrites them (lib/server/vault.ts, updateBluprint) is
 * asked for once the edits settle (components/chrome/statusbar.tsx).
 *
 * What the bluprint describes: base.json after updates, the bluprint's commit before
 * the first. While an update runs, moved.json once it has written the bluprint:
 * that bluprint cites the code as the update found it (scripts/generate/update.ts).
 */
import { createHash } from "node:crypto";
import { watch, type FSWatcher } from "node:fs";
import { existsSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import type { Node } from "@/lib/bluprint/schema";
import type { BluprintFile } from "@/lib/bluprint/build";
import { diffOf, git, moved, readText, refs, touches, type Base, type Change } from "@/scripts/generate/gitdiff";
import { sourcePath } from "@/scripts/generate/inventory";
import { getProject, bluprintFileOf, projectDir } from "@/lib/server/vault";

/** What the open page is told: the files that moved and the sections they touch. */
export interface Live {
  seq: number;
  /** Changes with every save of a changed file, so the page can tell when the edits have stopped. */
  sig: string;
  files: { path: string; add: number; del: number }[];
  /** Each touched section, as its path of ids from the top, with the changed files it cites; deepest first. */
  touched: { path: string[]; files: string[] }[];
}

interface Watch {
  root: string;
  watcher?: FSWatcher;
  /** When the page last asked; a watch nobody asks about is closed. */
  seen: number;
  /** Something under the checkout changed since the last look. */
  dirty: boolean;
  timer?: ReturnType<typeof setTimeout>;
  /** The stamps of the bluprint and its base when last worked out, so an update landing is a change too. */
  stamp: string;
  looked: number;
  changes: Map<string, Change>;
  live: Live;
}

/** Kept on globalThis, so a hot reload of this module in dev does not leave its watchers running unowned. */
const watches: Map<string, Watch> = ((globalThis as { __bluprintLive?: Map<string, Watch> }).__bluprintLive ??= new Map());

const IDLE_MS = 30_000;
const DEBOUNCE_MS = 150;
/** Without a watcher (a platform fs.watch cannot recurse on), the poll looks this often instead. */
const UNWATCHED_MS = 5_000;
/** Never worth a git call: the repository's own bookkeeping, and installed packages. */
const NOISE = /(^|[\\/])(\.git|node_modules)([\\/]|$)/;

const mtime = (f: string) => statSync(f, { throwIfNoEntry: false })?.mtimeMs ?? 0;

function readJson<T>(f: string, empty: T): T {
  try {
    return JSON.parse(readFileSync(f, "utf8"));
  } catch {
    return empty;
  }
}

/** What the bluprint describes, per path, where it is not the bluprint's commit. */
function baseOf(id: string): Base {
  const dir = projectDir(id);
  const base = readJson<Base>(join(dir, "base.json"), {});
  // A running update's moved lines are in the bluprint once it has written the bluprint
  // since; one left by a run that died describes nothing.
  const m = join(dir, "moved.json");
  const moving = getProject(id)?.update?.status === "running" && mtime(join(dir, "bluprint.json")) > mtime(m);
  return moving ? { ...base, ...readJson<Base>(m, {}) } : base;
}

const stampOf = (id: string) => {
  const dir = projectDir(id);
  return [mtime(join(dir, "bluprint.json")), mtime(join(dir, "base.json")), mtime(join(dir, "moved.json"))].join(":");
};

function walk(nodes: Node[], at: string[] = [], out: { node: Node; path: string[] }[] = []) {
  for (const n of nodes) {
    out.push({ node: n, path: [...at, n.id] });
    walk(n.children ?? [], [...at, n.id], out);
  }
  return out;
}

/**
 * Every file that differs from what the bluprint describes, as an update would
 * take it (update.ts `found`; the files list `?behind=1`), against the bluprint as
 * it is on disk. A diff already worked out for the same text is kept.
 */
function work(id: string, w: Watch) {
  const file = bluprintFileOf(id);
  if (!file) return;
  const bluprint: BluprintFile = readJson(file, { RUN: { commit: "" }, AUTHORED: [] } as unknown as BluprintFile);
  const base = baseOf(id);
  const all = walk(bluprint.AUTHORED);
  const cited = new Set(all.flatMap((p) => refs(p.node).map((r) => r.file)));
  const commit = bluprint.RUN.commit;
  const paths = new Set([
    ...(commit ? git(w.root, "diff", "--name-only", "--relative", commit).split("\n") : []),
    ...git(w.root, "ls-files", "--others", "--exclude-standard").split("\n"),
    ...Object.keys(base),
  ]);
  paths.delete("");
  const changes = new Map<string, Change>();
  for (const path of [...paths].sort()) {
    const after = readText(join(w.root, path));
    if (!(after === null ? cited.has(path) : sourcePath(path) || cited.has(path))) continue;
    const before = path in base ? base[path] : commit && hasAt(w.root, commit, path) ? git(w.root, "show", `${commit}:./${path}`) : null;
    if (before === after) continue;
    const had = w.changes.get(path);
    changes.set(path, had && had.before === before && had.after === after ? had : { path, before, after, ...diffOf(path, before, after) });
  }

  const touched = all
    .map((p) => ({ path: p.path, files: [...new Set(refs(p.node).filter((r) => changes.has(r.file) && touches(changes.get(r.file)!, r.s, r.e)).map((r) => r.file))] }))
    .filter((t) => t.files.length)
    .sort((a, b) => b.path.length - a.path.length);
  const files = [...changes.values()].map((c) => ({
    path: c.path,
    add: c.hunks.reduce((n, h) => n + h.nl, 0),
    del: c.hunks.reduce((n, h) => n + h.ol, 0),
  }));
  w.changes = changes;
  const hash = createHash("sha1");
  for (const c of changes.values()) hash.update(`${c.path}\0${c.after ?? "\u0000gone"}\0`);
  const next = { sig: changes.size ? hash.digest("hex").slice(0, 16) : "", files, touched };
  if (JSON.stringify(next) !== JSON.stringify({ sig: w.live.sig, files: w.live.files, touched: w.live.touched })) w.live = { seq: w.live.seq + 1, ...next };
}

/** Whether `path` exists at `commit`, quietly: `git` here swallows the failure as empty output. */
function hasAt(root: string, commit: string, path: string) {
  return git(root, "rev-parse", "--verify", "--quiet", `${commit}:./${path}`).trim() !== "";
}

/** A burst of events, once it stops: anything git does not ignore makes the next look work it out again. */
function settle(w: Watch, names: Set<string>) {
  clearTimeout(w.timer);
  w.timer = setTimeout(() => {
    const list = [...names];
    names.clear();
    const ignored = new Set(
      git(w.root, "check-ignore", "--", ...list)
        .split("\n")
        .filter(Boolean),
    );
    if (list.some((n) => !ignored.has(n))) w.dirty = true;
  }, DEBOUNCE_MS);
}

function open(id: string, root: string): Watch {
  const w: Watch = { root, seen: Date.now(), dirty: true, stamp: "", looked: 0, changes: new Map(), live: { seq: 0, sig: "", files: [], touched: [] } };
  const names = new Set<string>();
  try {
    w.watcher = watch(root, { recursive: true }, (_event, name) => {
      if (!name || NOISE.test(name)) return;
      names.add(name.split("\\").join("/"));
      settle(w, names);
    });
    w.watcher.on("error", () => {
      w.watcher?.close();
      w.watcher = undefined;
    });
  } catch {
    // No recursive watching here: the poll looks every UNWATCHED_MS instead.
  }
  watches.set(id, w);
  return w;
}

/** Closes the watches no page has asked about lately. */
function sweep() {
  for (const [id, w] of watches)
    if (Date.now() - w.seen > IDLE_MS) {
      clearTimeout(w.timer);
      w.watcher?.close();
      watches.delete(id);
    }
}
const g = globalThis as { __bluprintLiveSweep?: ReturnType<typeof setInterval> };
g.__bluprintLiveSweep ??= setInterval(sweep, IDLE_MS / 3);
g.__bluprintLiveSweep.unref?.();

/**
 * The open page asking: starts watching the checkout if nothing was, and
 * brings what is known up to date when the code, the bluprint or its base moved.
 */
export function followLive(id: string, root: string): Watch | undefined {
  if (!existsSync(root) || !bluprintFileOf(id)) return undefined;
  let w = watches.get(id);
  if (w && w.root !== root) {
    w.watcher?.close();
    w = undefined;
  }
  w ??= open(id, root);
  w.seen = Date.now();
  if (!w.watcher && Date.now() - w.looked >= UNWATCHED_MS) w.dirty = true;
  const stamp = stampOf(id);
  if (w.dirty || stamp !== w.stamp) {
    w.dirty = false;
    w.stamp = stamp;
    w.looked = Date.now();
    try {
      work(id, w);
    } catch {
      // A file mid-write: the next save, or the next poll, looks again.
      w.dirty = true;
    }
  }
  return w;
}

/** What is known of a project's live changes, without looking again. */
export function liveOf(id: string): Live | undefined {
  return watches.get(id)?.live;
}

/** Every cited line in `bluprint` moved to where its code is now, so the page reads the right lines while the code is ahead. */
export function shiftRefs(id: string, bluprint: BluprintFile): BluprintFile {
  const changes = watches.get(id)?.changes;
  if (!changes?.size) return bluprint;
  for (const p of walk(bluprint.AUTHORED)) refs(p.node, (f, line) => (changes.has(f) ? moved(changes.get(f)!, line) : line));
  return bluprint;
}

app/lib/server/overlay.ts:
/**
 * Server-side: what the reader added to a bluprint, and every version of it.
 *
 * A generated bluprint is the generator's to rewrite — a regenerate replaces it
 * wholesale, and every update redoes the sections the code touched
 * (scripts/generate/update.ts). So the reader's own additions cannot live in
 * `bluprint.json`: the two writers would share one file and the generator would
 * win, silently, exactly when the reader had most invested in it.
 *
 * They live beside it instead, and are composed in at read time:
 *
 *   <vault>/projects/<id>/overlay.json   additions and edits, current
 *   <vault>/projects/<id>/history.json   every version before this one
 *
 * `apply` is the whole integration: `lib/server/bluprints.ts` calls it inside `loadBluprint`,
 * which every reader of a bluprint already goes through, so the canvas, the title
 * bar and the text handed to Claude all see composed content without knowing
 * this file exists.
 *
 * Nothing here is ever lost. A write appends what it replaced to the history,
 * and an entry whose section has gone is kept and reported rather than
 * dropped — a regenerate that renames a section must not delete a note.
 */

import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { Anatomy, Node, Origin } from "@/lib/bluprint/schema";
import type { BluprintFile } from "@/lib/bluprint/build";
import { projectDir } from "@/lib/server/vault";

/** A block the reader added to a section. */
export interface BlockEntry {
  kind: "block";
  id: string;
  /** The section it belongs to, as the URL carries it. `[]` is the repo level. */
  path: string[];
  block: Anatomy;
  /**
   * Who added it. A `note` carries its own, because it renders its own mark;
   * every other kind — a diagram, a table — is drawn by the same component a
   * generated one is, with nowhere to put a mark. So the block's origin is
   * recorded here and `apply` lifts it onto the section, which does have
   * somewhere: without this a kept diagram reads as something the analysis
   * found in the code, which is the one thing the reader must never be told.
   */
  origin?: Origin;
  /**
   * Where among the section's own blocks it sits: the number of authored
   * blocks to put it after. Absent means last, which is where an addition
   * goes unless the reader moved it.
   */
  after?: number;
}

/** A field of a section the reader rewrote in their own words. */
export interface FieldEntry {
  kind: "field";
  id: string;
  path: string[];
  field: "title" | "sub" | "detail";
  value: string;
  origin: Origin;
}

/** A whole new part the reader added under a section. */
export interface SectionEntry {
  kind: "section";
  id: string;
  /** The section it goes under. `[]` adds a new root. */
  parent: string[];
  node: Node;
}

export type Entry = BlockEntry | FieldEntry | SectionEntry;

export interface Overlay {
  version: 1;
  entries: Entry[];
}

/** One past version, newest first in the file. */
export interface Version {
  /** When it was replaced. */
  at: string;
  /** What the change was, in a few words, for the history list. */
  label: string;
  entries: Entry[];
}

interface History {
  version: 1;
  versions: Version[];
}

const EMPTY: Overlay = { version: 1, entries: [] };

export const overlayFile = (id: string) => join(projectDir(id), "overlay.json");
const historyFile = (id: string) => join(projectDir(id), "history.json");

/** Written whole and renamed into place, as the vault's index is: a crash never leaves half a file. */
function writeAtomic(file: string, data: unknown) {
  mkdirSync(join(file, ".."), { recursive: true });
  const tmp = `${file}.${process.pid}.tmp`;
  writeFileSync(tmp, JSON.stringify(data, null, 1) + "\n");
  renameSync(tmp, file);
}

export function readOverlay(id: string): Overlay {
  try {
    const o = JSON.parse(readFileSync(overlayFile(id), "utf8")) as Overlay;
    if (o.version === 1 && Array.isArray(o.entries)) return o;
  } catch {
    /* none yet, or unreadable: an empty overlay still shows the bluprint */
  }
  return EMPTY;
}

export function readHistory(id: string): Version[] {
  try {
    const h = JSON.parse(readFileSync(historyFile(id), "utf8")) as History;
    if (h.version === 1 && Array.isArray(h.versions)) return h.versions;
  } catch {
    /* no history yet */
  }
  return [];
}

/**
 * Replace the overlay, keeping what it was. `label` is what the history list
 * shows for the version being replaced, so it describes the change being made.
 */
export function writeOverlay(id: string, next: Overlay, label: string) {
  const before = readOverlay(id);
  // The first write has nothing to keep: an empty overlay is not a version
  // worth reverting to, and listing it would offer "undo to nothing" as a step.
  if (before.entries.length || existsSync(overlayFile(id))) {
    const versions = [{ at: new Date().toISOString(), label, entries: before.entries }, ...readHistory(id)];
    writeAtomic(historyFile(id), { version: 1, versions } satisfies History);
  }
  writeAtomic(overlayFile(id), next);
}

/**
 * Go back to a past version. The revert is itself a change, so what is being
 * replaced goes into the history too: reverting is never a way to lose work.
 */
export function revertTo(id: string, at: string): Overlay | undefined {
  const version = readHistory(id).find((v) => v.at === at);
  if (!version) return undefined;
  const next: Overlay = { version: 1, entries: version.entries };
  writeOverlay(id, next, `Reverted to ${new Date(at).toLocaleString()}`);
  return next;
}

export const newId = () => `u${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;

/* ── composing ────────────────────────────────────────────────── */

/** What `apply` could not place, so the UI can say so instead of pretending it applied. */
export interface Orphan {
  id: string;
  /** The section it named, for the message. */
  where: string;
  kind: Entry["kind"];
}

function at(nodes: Node[], path: string[]): Node | null {
  let level = nodes;
  let found: Node | null = null;
  for (const id of path) {
    found = level.find((n) => n.id === id) ?? null;
    if (!found) return null;
    level = found.children ?? [];
  }
  return found;
}

/**
 * One entry, into a tree already copied down its own path. Returns false when
 * the section it names is gone, which makes it an orphan rather than an error.
 */
function place(roots: Node[], e: Entry): boolean {
  if (e.kind === "section") {
    if (!e.parent.length) {
      roots.push({ ...e.node, col: 0, row: roots.length });
      return true;
    }
    const parent = at(roots, e.parent);
    if (!parent) return false;
    const children = [...(parent.children ?? [])];
    children.push({ ...e.node, col: 0, row: children.length });
    parent.children = children;
    return true;
  }
  const node = at(roots, e.path);
  if (!node) return false;
  if (e.kind === "field") {
    node[e.field] = e.value;
    // The reader's words are theirs, and the mark has to survive onto the node
    // the screen reads — a field edit with no visible origin is the one thing
    // this file exists to prevent.
    node.origin = e.origin;
    return true;
  }
  const blocks = [...(node.anatomy ?? [])];
  blocks.splice(e.after ?? blocks.length, 0, e.block);
  node.anatomy = blocks;
  // A block the reader kept marks the level, unless the level is already
  // marked as theirs by something more specific (a field they rewrote).
  const own = e.block.kind === "note" ? e.block.origin : e.origin;
  if (own && !node.origin) node.origin = own;
  return true;
}

/**
 * The bluprint as the reader has it: the generator's tree with their additions in
 * place. Pure — the file passed in is never mutated, so a caller holding the
 * generator's own copy keeps it.
 */
export function apply(file: BluprintFile, o: Overlay): { file: BluprintFile; orphans: Orphan[] } {
  if (!o.entries.length) return { file, orphans: [] };
  // A structured clone is enough and keeps this honest: every node the entries
  // touch is a fresh object, so nothing writes through to the caller's tree.
  const roots: Node[] = structuredClone(file.AUTHORED);
  const orphans: Orphan[] = [];
  for (const e of o.entries) {
    if (!place(roots, e)) {
      const where = (e.kind === "section" ? e.parent : e.path).join(" › ") || "the repository";
      orphans.push({ id: e.id, where, kind: e.kind });
    }
  }
  return { file: { ...file, AUTHORED: roots }, orphans };
}

app/lib/server/repo.ts:
/**
 * Binding the bluprint to a real repository: read a cited slice and check that the
 * bluprint's quote still holds, write an edited slice back, and undo an agent turn.
 * A quote drifts silently the moment the real file changes, which is exactly
 * the failure this project exists to study.
 */

/**
 * Where the repository a bluprint is of lives: absolute, one per bluprint, resolved by
 * `rootOf` in `lib/server/bluprints.ts` from the bluprint the reader has open. The route hands
 * it in; nothing caller-supplied ever chooses it.
 */
export type RepoRoot = string;

export interface SliceRequest {
  /** Repo-relative path. Must stay inside the repo root once resolved. */
  file: string;
  /** 1-indexed first line. */
  start: number;
  /** 1-indexed last line, inclusive. */
  end: number;
}

export interface Slice extends SliceRequest {
  /** Verbatim lines, newline-joined. Indentation preserved exactly. */
  code: string;
  /** Total lines in the file, so the UI can say "733 of 1,204". */
  total: number;
  /**
   * True when the file on disk still matches what the fixture quoted.
   * A false here is a FINDING, not an error: it means the bluprint has drifted from
   * the code, and the UI must say so rather than quietly showing fresh text
   * under a stale explanation.
   */
  matchesFixture: boolean;
}

/**
 * Read a slice of a real file.
 *
 * Path safety: resolve the path and confirm it is still under the repo root.
 * `../` traversal, absolute paths and symlinks pointing outside are refused —
 * this endpoint reads arbitrary caller-supplied paths, so the containment check
 * is the whole security model.
 */
export type ReadSlice = (req: SliceRequest, fixture: string | undefined, root: RepoRoot) => Promise<Slice>;

/**
 * Write an edited slice back.
 *
 * Deliberately narrow, because this is the one operation in the product that
 * can destroy work:
 *
 * - Inside the repo root only, same containment check as the read.
 * - One contiguous slice of one file per call.
 * - `expected` must match what is currently on disk, or the write is refused.
 *   This is optimistic concurrency: it stops a save built on a stale read from
 *   overwriting a change made in the editor since.
 * - The caller is shown a diff and confirms before this is ever invoked.
 *
 * The UI never writes on blur, on a timer, or on navigation. Only on an
 * explicit save.
 */
export interface WriteRequest extends SliceRequest {
  /** The replacement text for [start, end]. */
  code: string;
  /** What the caller believes is currently at [start, end]. Verified first. */
  expected: string;
}

export interface WriteResult {
  ok: boolean;
  /** Unified diff of what changed, for display after the fact. */
  diff: string;
  /** Set when refused: "outside repo", "stale", "not a file". */
  refused?: string;
}

export type WriteSlice = (req: WriteRequest, root: RepoRoot) => Promise<WriteResult>;

// ---------------------------------------------------------------------------
// Implementation. The types above are the frozen contract; everything below
// satisfies it and adds nothing to it.
// ---------------------------------------------------------------------------

import { readFile, writeFile, realpath, stat, unlink } from "node:fs/promises";
import { basename, dirname, join, resolve, sep } from "node:path";

/**
 * The entire security model, in one function.
 *
 * `file` arrives from the network, so it is assumed hostile. Three things are
 * checked, in this order, because each one defeats a different attack:
 *
 * 1. `resolve(the repo root, file)` collapses `../` textually — this is what stops
 *    `../../../etc/passwd` and, because `resolve` discards the base when given
 *    an absolute second argument, it also folds absolute paths back through the
 *    same prefix test rather than silently honouring them.
 * 2. The prefix test uses `root + sep`, not bare `startsWith(root)`. Without the
 *    separator `/Users/.../repo-secrets` passes as if it were inside
 *    `/Users/.../repo`.
 * 3. `realpath` resolves symlinks and the prefix test runs AGAIN on the result.
 *    Step 1 is pure string arithmetic and cannot see a link inside the repo
 *    pointing out of it; only asking the filesystem can.
 *
 * Returns the real absolute path, or null when the path escapes.
 */
async function contain(repoRoot: RepoRoot, file: string): Promise<string | null> {
  const root = await realpath(repoRoot);
  const inside = (p: string) => p === root || p.startsWith(root + sep);

  const target = resolve(root, file);
  if (!inside(target)) return null;

  // realpath throws ENOENT on a path that does not exist, which is a refusal
  // here rather than an error: there is nothing to read and nothing to write.
  let real: string;
  try {
    real = await realpath(target);
  } catch {
    return null;
  }
  return inside(real) ? real : null;
}

/** Thrown to the route handler, which turns it into a 400 with this message. */
export class Refused extends Error {}

/** What a doc may show from the repository: images, by extension, and their types. */
const IMAGE_TYPES: Record<string, string> = {
  svg: "image/svg+xml",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  avif: "image/avif",
  ico: "image/x-icon",
};

/** An image a doc in the repository shows (components/bluprint/docs.tsx), behind the same containment as the code. */
export async function readImage(root: RepoRoot, file: string): Promise<{ body: Buffer; type: string }> {
  const type = IMAGE_TYPES[file.split(".").pop()?.toLowerCase() ?? ""];
  if (!type) throw new Refused("not an image");
  const real = await contain(root, file);
  if (!real) throw new Refused("outside repo");
  const s = await stat(real);
  if (!s.isFile() || s.size > 20 << 20) throw new Refused("not a file");
  return { body: await readFile(real), type };
}

/**
 * `fixture` is what the BLUPRINT claims sits at these lines, which the repository
 * itself has no opinion about; undefined when the caller made no claim.
 */
export const readSlice: ReadSlice = async (req, fixture, root) => {
  const real = await contain(root, req.file);
  if (!real) throw new Refused("outside repo");
  if (!(await stat(real)).isFile()) throw new Refused("not a file");

  const lines = (await readFile(real, "utf8")).split(/\r?\n/);
  const start = Math.max(1, req.start);
  const end = Math.min(lines.length, Math.max(start, req.end));
  const code = lines.slice(start - 1, end).join("\n");

  return {
    file: req.file,
    start,
    end,
    code,
    total: lines.length,
    // No fixture to compare against is not a mismatch — a caller that asked
    // only for the file's text has made no claim that could have drifted.
    matchesFixture: fixture === undefined || quoteHolds(fixture, code),
  };
};

/**
 * Does the fixture's quote still hold against what is on disk?
 *
 * Exact equality is the normal answer. The one accepted relaxation is a quote
 * whose LAST line stops part-way through the real line — the fixture quotes
 * prose out of JSX that way, taking a sentence and leaving the rest of the
 * line. Every other line must match byte for byte, including indentation.
 *
 * Everything else is drift, and drift is a finding: the explanation attached to
 * this quote was written about text that is no longer there.
 */
function quoteHolds(fixture: string, disk: string): boolean {
  if (fixture === disk) return true;
  const f = fixture.replace(/\n$/, "").split("\n");
  const d = disk.replace(/\n$/, "").split("\n");
  if (f.length !== d.length) return false;
  const last = f.length - 1;
  return (
    f.slice(0, last).every((line, i) => line === d[i]) &&
    d[last].startsWith(f[last])
  );
}

export const writeSlice: WriteSlice = async (req, root) => {
  const real = await contain(root, req.file);
  if (!real) return { ok: false, diff: "", refused: "outside repo" };
  if (!(await stat(real)).isFile()) {
    return { ok: false, diff: "", refused: "not a file" };
  }

  const text = await readFile(real, "utf8");
  const eol = text.includes("\r\n") ? "\r\n" : "\n";
  const lines = text.split(/\r?\n/);
  if (req.start < 1 || req.end > lines.length || req.end < req.start) {
    return { ok: false, diff: "", refused: "stale" };
  }

  // Optimistic concurrency. The caller read [start, end] at some point and is
  // now writing back a change to it; if disk no longer holds what they read,
  // their edit was composed against text that has since been replaced and
  // applying it would silently destroy whoever made that replacement.
  const onDisk = lines.slice(req.start - 1, req.end).join("\n");
  if (onDisk !== req.expected) {
    return { ok: false, diff: "", refused: "stale" };
  }

  const replacement = req.code.replace(/\r?\n$/, "").split(/\r?\n/);
  const next = [
    ...lines.slice(0, req.start - 1),
    ...replacement,
    ...lines.slice(req.end),
  ];
  await writeFile(real, next.join(eol), "utf8");

  return { ok: true, diff: unified(req.file, req.start, onDisk, req.code) };
};

/**
 * A unified diff of just the replaced slice.
 *
 * Whole-line add/remove, no LCS: the slice is small, contiguous and already
 * known to be the only thing that changed, so the alignment a real diff
 * algorithm buys is alignment nobody would read. A dependency for this would
 * be a dependency for cosmetics.
 */
function unified(file: string, start: number, before: string, after: string) {
  const b = before.replace(/\n$/, "").split("\n");
  const a = after.replace(/\n$/, "").split("\n");
  return [
    `--- a/${file}`,
    `+++ b/${file}`,
    `@@ -${start},${b.length} +${start},${a.length} @@`,
    ...b.map((l) => `-${l}`),
    ...a.map((l) => `+${l}`),
  ].join("\n");
}

/**
 * Puts files back as they were before an agent turn (app/api/undo), from the
 * snapshot the bluprint updater kept (scripts/generate/update.ts).
 *
 * All or nothing, and only over the turn's own work: a file whose contents
 * are no longer what the turn left (`after`) has been changed since, by hand
 * or by a later turn, and undoing would destroy that; any such file refuses
 * the whole undo and is named. A file the turn created is deleted, one it
 * deleted is written back.
 *
 * Paths come from a snapshot on disk, not the network, but go through
 * `contain` all the same: a file that does not exist is checked by its
 * folder, and refused if that folder is gone too.
 */
export async function restoreFiles(
  root: RepoRoot,
  files: { path: string; before: string | null; after: string | null }[],
): Promise<{ ok: true; restored: string[] } | { ok: false; conflicts: string[]; refused: string[] }> {
  const placed: { abs: string; before: string | null }[] = [];
  const conflicts: string[] = [];
  const refused: string[] = [];
  for (const f of files) {
    if (f.before === f.after) continue;
    let at = await contain(root, f.path);
    const now = at ? await readFile(at, "utf8").catch(() => null) : null;
    if (!at) {
      // Missing: checked by its folder, which must still exist inside the checkout.
      const dir = await contain(root, dirname(f.path));
      if (!dir || f.path.endsWith(sep) || basename(f.path) === "..") {
        refused.push(f.path);
        continue;
      }
      at = join(dir, basename(f.path));
    }
    if (now !== f.after) conflicts.push(f.path);
    else placed.push({ abs: at, before: f.before });
  }
  if (conflicts.length || refused.length) return { ok: false, conflicts, refused };
  for (const p of placed) {
    if (p.before === null) await unlink(p.abs).catch(() => {});
    else await writeFile(p.abs, p.before, "utf8");
  }
  return { ok: true, restored: files.filter((f) => f.before !== f.after).map((f) => f.path) };
}

app/lib/server/review.ts:
/**
 * A branch or a pull request as a range to diff, the way a reviewer means it:
 * what the branch did since it left its base (`git merge-base`), not
 * everything that differs between two tips. A tip-to-tip compare against a
 * main that moved on shows main's own commits as the branch's.
 *
 * Pull requests come from GitHub through the `gh` CLI when it is installed and
 * signed in; without it branches still work and the panel says why PRs do not.
 * Server only: it runs git and gh.
 */
import { execFileSync } from "node:child_process";
import { git } from "@/scripts/generate/gitdiff";

export interface Review {
  /** `pr` names a pull request; `branch` a local or remote branch against its base; `turn` one agent turn the bluprint followed. */
  kind: "pr" | "branch" | "turn";
  base: string;
  head: string;
  /** The merge-base the diff starts from, and the head commit it ends at. */
  from: string;
  to: string;
  number?: number;
  title?: string;
  body?: string;
  author?: string;
  url?: string;
}

export interface Branch {
  name: string;
  /** ISO 8601, its last commit's date. */
  at: string;
  subject: string;
}

export interface Pull {
  number: number;
  title: string;
  author: string;
  head: string;
  base: string;
  url: string;
}

// A desktop app's server starts with launchd's PATH, which has no Homebrew.
const PATH = [process.env.PATH, "/opt/homebrew/bin", "/usr/local/bin"].filter(Boolean).join(":");

function gh(root: string, args: string[]): string | null {
  try {
    return execFileSync("gh", args, { cwd: root, encoding: "utf8", env: { ...process.env, PATH }, stdio: ["ignore", "pipe", "pipe"], timeout: 20_000, windowsHide: true });
  } catch {
    return null;
  }
}

/** The branch a review compares against when none is named: the remote's default, else main or master. */
export function defaultBase(root: string): string {
  const head = git(root, "symbolic-ref", "--short", "refs/remotes/origin/HEAD").trim();
  if (head) return head;
  for (const b of ["main", "master", "origin/main", "origin/master"]) if (git(root, "rev-parse", "--verify", "--quiet", `${b}^{commit}`).trim()) return b;
  return "HEAD";
}

/** Local and remote branches, most recently committed first. */
export function branches(root: string, n = 60): Branch[] {
  return git(root, "for-each-ref", "--sort=-committerdate", `--count=${n}`, "--format=%(refname:short)%09%(committerdate:iso-strict)%09%(subject)", "refs/heads", "refs/remotes")
    .split("\n")
    .map((l) => l.split("\t"))
    .filter(([name, at]) => name && at && !name.endsWith("/HEAD") && name !== "origin")
    .map(([name, at, subject]) => ({ name, at, subject: subject ?? "" }));
}

/** Open pull requests, or why there are none to show. */
export function pulls(root: string): { pulls: Pull[] } | { why: string } {
  const out = gh(root, ["pr", "list", "--limit", "30", "--json", "number,title,author,headRefName,baseRefName,url"]);
  if (out === null) return { why: "Pull requests need the GitHub CLI (`gh`), installed and signed in, in a checkout with a GitHub remote." };
  const raw = JSON.parse(out) as { number: number; title: string; author?: { login?: string }; headRefName: string; baseRefName: string; url: string }[];
  return { pulls: raw.map((p) => ({ number: p.number, title: p.title, author: p.author?.login ?? "", head: p.headRefName, base: p.baseRefName, url: p.url })) };
}

// A leading "-" would reach git as an option, so a name must start with a word character.
const BRANCH = /^\w[\w./-]{0,199}$/;

/**
 * `pr:<n>` or `<base>...<head>` as a range. A pull request's head and base
 * are fetched first, so the review is of the PR as GitHub has it now rather
 * than of whatever local copy is stale; the head lands in FETCH_HEAD and no
 * local branch is created or moved.
 */
export function reviewRange(root: string, spec: string): Review | { error: string } {
  const pr = /^pr:(\d{1,7})$/.exec(spec);
  if (pr) {
    const out = gh(root, ["pr", "view", pr[1], "--json", "number,title,body,author,url,baseRefName,headRefName,headRefOid"]);
    if (out === null) return { error: `Could not read pull request #${pr[1]}: the GitHub CLI (\`gh\`) must be installed, signed in, and this checkout's remote on GitHub.` };
    const p = JSON.parse(out) as { number: number; title: string; body: string; author?: { login?: string }; url: string; baseRefName: string; headRefName: string; headRefOid: string };
    if (!BRANCH.test(p.baseRefName)) return { error: `Unexpected base branch name on #${p.number}.` };
    try {
      execFileSync("git", ["-C", root, "fetch", "--no-tags", "--quiet", "origin", `+refs/heads/${p.baseRefName}:refs/remotes/origin/${p.baseRefName}`, `pull/${p.number}/head`], { stdio: "ignore", timeout: 60_000, windowsHide: true });
    } catch {
      return { error: `Could not fetch #${p.number} from origin.` };
    }
    const base = `origin/${p.baseRefName}`;
    const from = git(root, "merge-base", base, p.headRefOid).trim();
    if (!from) return { error: `#${p.number} shares no history with ${base}.` };
    return { kind: "pr", base, head: p.headRefName, from, to: p.headRefOid, number: p.number, title: p.title, body: p.body, author: p.author?.login, url: p.url };
  }
  const range = /^(.+?)\.\.\.(.+)$/.exec(spec);
  if (!range || !BRANCH.test(range[1]) || !BRANCH.test(range[2])) return { error: `Could not read "${spec}" as a review: give pr:<number> or <base>...<branch>.` };
  const [, base, head] = range;
  const to = git(root, "rev-parse", "--verify", "--quiet", `${head}^{commit}`).trim();
  if (!to) return { error: `No branch ${head} in this checkout.` };
  const from = git(root, "merge-base", base, to).trim();
  if (!from) return { error: `${head} shares no history with ${base}.` };
  return { kind: "branch", base, head, from, to };
}

