// usage (from app/): npx -y tsx --tsconfig tsconfig.json scripts/check-bluprint.mts <bluprint name> <repo dir> [--roots a,b,c] [--generated]
//   e.g. scripts/check-bluprint.mts flask ~/Code/flask
// The rules live in scripts/generate/check.ts.
import { readFileSync } from "node:fs";
import { check } from "./generate/check";

const args = process.argv.slice(2);
const flag = args.indexOf("--roots");
const only = flag === -1 ? undefined : new Set(args[flag + 1].split(","));
const generated = args.includes("--generated");
const [name, repo] = args.filter((a, i) => !a.startsWith("--") && (flag === -1 || i !== flag + 1));
const bluprint = JSON.parse(readFileSync(`bluprints/${name}/bluprint.json`, "utf8"));
const r = check(bluprint, repo, { only, generated });
for (const x of r.roots) console.log(`root ${x.id.padEnd(14)} depth ${x.depth}  nodes ${x.nodes}`);
console.log(`sources verbatim ${r.sources.ok}/${r.sources.ok + r.sources.bad}; code refs ${r.refs}; problems ${r.problems.length}`);
r.problems.slice(0, Number(process.env.SHOW ?? 60)).forEach((p) => console.log(p));
process.exit(r.problems.length ? 1 : 0);

app/scripts/export-static.mts:
// usage (from app/): npx -y tsx --tsconfig tsconfig.json scripts/export-static.mts <bluprint> --base-path /repo/bluprint --source-url https://github.com/o/r/blob/<sha> [--root <checkout>]
//   builds one bluprint as a static site in out/<bluprint>/, ready for GitHub Pages. The files the bluprint
//   cites are baked into source.json, so the drawer reads code with no server; each code card
//   links to --source-url instead of offering an edit.
import { spawnSync } from "node:child_process";
import { existsSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import type { Node } from "@/lib/bluprint/schema";
import { demoSource, loadDemo, loadBluprint, rootOf } from "@/lib/server/bluprints";

const args = process.argv.slice(2);
const opt = (k: string) => { const i = args.indexOf(k); return i === -1 ? undefined : args[i + 1]; };
const name = args[0];
// One of the landing's demos (landing/demo, D63), or one of this machine's projects.
const open = loadDemo(name) ?? loadBluprint(name);
if (!open || open.name !== name) throw new Error(`no demo or project named ${name}`);
const { file } = open;
const baked = demoSource(name);

// --root: the checkout to read, when it is not where the bluprint was made.
const root = opt("--root") ?? rootOf(file.RUN);
const cited = new Set<string>();
const walk = (n: Node) => {
  for (const c of n.code ?? []) cited.add(c.file);
  // A step's own lines open from the step, and may sit in a file the node does not cite.
  for (const b of n.anatomy ?? [])
    if (b.kind === "flow" || b.kind === "sequence") for (const r of b.rows) if (r.at) cited.add(r.at.replace(/:[\d-]+$/, ""));
  (n.children ?? []).forEach(walk);
};
file.AUTHORED.forEach(walk);
// A demo carries its cited files; a project's are read from its checkout.
const source = Object.fromEntries([...cited].sort().map((f) => [f, baked?.[f] ?? readFileSync(join(root, f), "utf8")]));

const out = resolve("out", name);
rmSync(out, { recursive: true, force: true });
// A static export cannot hold the route that reads and writes the checkout, so it sits out the build.
renameSync("app/api", ".api-aside");
let status: number | null;
try {
  const build = spawnSync("npx next build", {
    stdio: "inherit",
    shell: true,
    env: {
      ...process.env,
      NEXT_PUBLIC_STATIC_BLUPRINT: name,
      NEXT_PUBLIC_BASE_PATH: opt("--base-path") ?? "",
      NEXT_PUBLIC_SOURCE_URL: opt("--source-url") ?? "",
      BLUPRINT_EXPORT_DIR: `out/${name}`,
    },
  });
  if (build.error) throw build.error;
  status = build.status;
} finally {
  renameSync(".api-aside", "app/api");
}
// After the finally: exiting inside the try would leave app/api renamed.
if (status !== 0) process.exit(status ?? 1);
writeFileSync(join(out, "source.json"), JSON.stringify(source));
// Pages runs Jekyll by default, which drops `_next/`.
writeFileSync(join(out, ".nojekyll"), "");
console.log(`${out}: ${cited.size} cited files baked in${existsSync(join(out, "index.html")) ? "" : " — but no index.html!"}`);

