/** What an answer breaks of the bluprint's limits on words, which the check holds every card to. */
export function wordProblems(fields: [what: string, text: unknown, max: number][]): string[] {
  const out: string[] = [];
  for (const [what, text, max] of fields) {
    const t = typeof text === "string" ? text : "";
    if (words(t) > max) out.push(`${what} "${t}" is ${words(t)} words; at most ${max}`);
    if (looksLikePath(t)) out.push(`${what} "${t}" names a file; say what it does instead`);
  }
  return out;
}

/**
 * One structured answer, and if it breaks the limits on words, one more try
 * with what it broke: the model counts words loosely, and a long sub fails the
 * check on every card it is on. What is still over after that is listed by
 * the check, not tried again.
 */
export async function askWithin(req: { model: string; stage: string; maxTokens: number; prompt: string; tool: Tool }, problemsOf: (a: any) => string[]): Promise<any> {
  const messages = [{ role: "user" as const, content: req.prompt }];
  const first = await ask<any>({ model: req.model, stage: req.stage, maxTokens: req.maxTokens, system: SYSTEM, messages, tool: req.tool });
  const wrong = problemsOf(first);
  if (!wrong.length) return first;
  return ask<any>({
    model: req.model,
    stage: req.stage,
    maxTokens: req.maxTokens,
    system: SYSTEM,
    messages: [...messages, { role: "assistant" as const, content: JSON.stringify(first) }, { role: "user" as const, content: `Your answer breaks these limits:\n- ${wrong.join("\n- ")}\nAnswer again in full, with every one of them within its limit and the rest as it was.` }],
    tool: req.tool,
  });
}

const SYSTEM = "You describe one part of a bluprint of a codebase from facts already extracted from its code. Use only what you are given; answer only with the structure asked for.";

/** Code ranges for a file as a leaf cites them: the whole file if it is short, else its largest functions within the leaf's limits. */
export function leafCode(path: string, lines: number, s: FileSummary | undefined): NonNullable<Node["code"]> {
  if (lines <= LEAF.lines) return [{ file: path, start: 1, end: lines, label: s?.purpose?.split(/(?<=\.)\s/)[0] ?? basename(path) }];
  const out: NonNullable<Node["code"]> = [];
  let used = 0;
  // A summary's line numbers are the model's: one past the file's end is a reference to nothing.
  const syms = (s?.symbols ?? []).filter((x) => x.start >= 1 && x.start <= lines && x.end >= x.start).map((x) => ({ ...x, end: Math.min(x.end, lines) }));
  for (const sym of syms.sort((a, b) => b.end - b.start - (a.end - a.start))) {
    const n = sym.end - sym.start + 1;
    if (out.length >= LEAF.refs || used + n > LEAF.lines) continue;
    out.push({ file: path, start: sym.start, end: sym.end, label: sym.does || sym.name });
    used += n;
  }
  return out.length ? out.sort((a, b) => a.start - b.start) : [{ file: path, start: 1, end: LEAF.lines, label: "the start of the file" }];
}

/**
 * Boxes placed along their arrows: a box's column is the longest chain of
 * arrows leading to it (a cycle stops growing at the box count), capped at
 * COLS; its row is its place among its column's boxes in the order given.
 */
export function layered(ids: string[], arrows: { from: string; to: string }[]): Map<string, { col: number; row: number }> {
  const rank = new Map(ids.map((id) => [id, 0]));
  for (let pass = 0; pass < ids.length; pass++) {
    let moved = false;
    for (const a of arrows) {
      const r = (rank.get(a.from) ?? 0) + 1;
      if (a.from !== a.to && rank.has(a.to) && r < ids.length && r > rank.get(a.to)!) {
        rank.set(a.to, r);
        moved = true;
      }
    }
    if (!moved) break;
  }
  const rows = new Map<number, number>();
  return new Map(
    ids.map((id) => {
      const col = Math.min(rank.get(id)!, COLS - 1);
      const row = rows.get(col) ?? 0;
      rows.set(col, row + 1);
      return [id, { col, row }];
    }),
  );
}

/** A file summary's purpose as a card's detail: its sentences while they fit in 40 words (a first one alone over is kept, and the check lists it). */
export function within40(text: string): string {
  const ss = text.split(/(?<=[.!?])\s+/).filter(Boolean);
  const out: string[] = [];
  for (const x of ss) {
    if (out.length && words([...out, x].join(" ")) > 40) break;
    out.push(x);
  }
  return out.join(" ");
}
export const short = (s: string, n: number) => (s.length <= n ? s : `${s.slice(0, n - 1).trimEnd()}…`);
export type Arrow = { from: string; to: string; label: string; at: string; inferred?: boolean };

/**
 * A diagram drawer over the graph: a box per node, each standing for some
 * files, and an arrow wherever the graph has a call from one's files into
 * another's, at the call's line. A call into code the target does not cite is
 * drawn as inferred: the checker holds an arrow to land in its box's code.
 */
export function diagramOf(g: Graph) {
  const defById = new Map(g.defs.map((d) => [d.id, d]));
  const fileOfDef = (id: string) => defById.get(id)?.file ?? id;
  const calls = g.edges.filter((e) => e.kind !== "imports" && e.lines.length);
  return (
    caption: string,
    /** Each box's node and the files it stands for, or (parts of one file) the line ranges. */
    nodes: { node: Node; files: string[]; ranges?: { file: string; start: number; end: number }[] }[],
    boxPrefix: string,
    label?: (from: Node, to: Node) => string | undefined,
    /** The name an arrow's label describes, so its line is a call to that: the most-called, for the top level. */
    prefer?: (from: Node, to: Node) => string | undefined,
  ) => {
    const holder = new Map<string, Node>();
    for (const { node, files } of nodes) for (const f of files) holder.set(f, node);
    const ranged = nodes.filter((x) => x.ranges?.length);
    // The box a def's code is in: by its lines where boxes split a file, else by its file.
    const boxOf = (id: string, line?: number) => {
      const d = defById.get(id);
      const file = d?.file ?? id;
      const at = line ?? d?.start;
      if (at !== undefined) for (const x of ranged) if (x.ranges!.some((r) => r.file === file && r.start <= at && at <= r.end)) return x.node;
      return holder.get(file);
    };
    const best = new Map<string, Arrow & { score: number }>();
    for (const e of calls) {
      const a = boxOf(e.from, e.lines[0]), b = boxOf(e.to);
      if (!a || !b || a === b) continue;
      const def = defById.get(e.to);
      const lands = !def || (b.code ?? []).some((r) => r.file === def.file && r.start <= def.end && def.start <= r.end);
      const cand: Arrow = {
        from: `${boxPrefix}${a.id}`,
        to: `${boxPrefix}${b.id}`,
        label: short(label?.(a, b) ?? `uses ${def?.name ?? basename(e.to)}`, 24),
        at: `${fileOfDef(e.from)}:${e.lines[0]}`,
        ...(e.how !== "extracted" || !lands ? { inferred: true } : {}),
      };
      const k = `${a.id}\n${b.id}`;
      // A call to the name the label describes, then a call the source states.
      const score = (prefer && def?.name === prefer(a, b) ? 2 : 0) + (cand.inferred ? 0 : 1);
      const prev = best.get(k);
      if (!prev || score > prev.score) best.set(k, { ...cand, score });
    }
    const arrows: Arrow[] = [...best.values()].map(({ score, ...x }) => (void score, x));
    const place = layered(nodes.map(({ node }) => `${boxPrefix}${node.id}`), arrows);
    return { kind: "diagram", caption: short(caption, 30), boxes: nodes.map(({ node }) => ({ id: `${boxPrefix}${node.id}`, label: node.title, sub: node.sub, ...place.get(`${boxPrefix}${node.id}`)!, opens: node.id })), arrows };
  };
}

export interface FastResult {
  bluprint: BluprintFile;
  arch: { files: Record<string, { component: string; lines: number; symbols: { name: string; kind: string; line: number }[]; imports: string[] }>; components: Component[]; module_graph: ModuleEdge[]; entrypoints: string[]; external_deps: string[] };
  /** What the model said that the graph does not hold: listed, not fixed. */
  discrepancies: string[];
  /** What the check found: listed, not sent back for repair. */
  checkProblems: string[];
  timing: Record<string, number>;
}

/** Phases 2-4 over an inventory, its summaries and its graph (phase 1 is the caller's: inventory, summarize, graph). */
export async function fastBluprint(inv: Inventory, sums: Record<string, FileSummary>, g: Graph, model: string, run: BluprintFile["RUN"], say: (s: string) => void): Promise<FastResult> {
  const timing: Record<string, number> = {};
  const lap = async <T,>(stage: string, fn: () => Promise<T> | T): Promise<T> => {
    const t = Date.now();
    const r = await fn();
    timing[stage] = Math.round((Date.now() - t) / 100) / 10;
    say(`${stage} done in ${timing[stage]}s`);
    return r;
  };
  const lines = new Map(inv.files.map((f) => [f.path, f.lines]));
  const defById = new Map(g.defs.map((d) => [d.id, d]));
  const fileOfDef = (id: string) => defById.get(id)?.file ?? id;
  const calls = g.edges.filter((e) => e.kind !== "imports" && e.lines.length);

  // Phases 1-2: partition and the module graph, no model.
  const { comps, mod, entries } = await lap("partition", () => {
    const comps = partition(inv);
    return { comps, mod: moduleGraph(g, comps), entries: entrypoints(inv) };
  });
  for (const c of comps) say(`${c.id.padEnd(22)} ${c.dir} — ${c.files.length} files${c.groups.length ? ` in ${c.groups.length} groups` : ""}`);
  const owner = new Map<string, Component>();
  for (const c of comps) for (const f of c.files) owner.set(f, c);
  const byId = new Map(comps.map((c) => [c.id, c]));

  // Phase 3: one short call per component, all at once.
  /** What the rest of the code calls in some files, most called first: what a group is for, seen from outside it. */
  const usedFor = (files: string[]) => {
    const set = new Set(files);
    const n = new Map<string, number>();
    for (const e of calls) if (set.has(fileOfDef(e.to)) && !set.has(fileOfDef(e.from))) {
      const name = defById.get(e.to)?.name ?? basename(e.to);
      n.set(name, (n.get(name) ?? 0) + e.lines.length);
    }
    const top = [...n].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([k]) => k);
    return top.length ? ` — the rest of the code uses it for ${top.join(", ")}` : "";
  };
  const fileLine = (p: string) => (sums[p] ? `${oneLine(sums[p])}\n${sums[p].symbols.slice(0, 8).map((s) => `    ${s.name} (${s.start}-${s.end}): ${s.does}`).join("\n")}` : p);
  const described = await lap("fanout", () =>
    Promise.all(
      comps.map(async (c) => {
        const out = mod.filter((e) => e.from === c.id), into = mod.filter((e) => e.to === c.id);
        const prompt = [
          `# Repository: ${inv.name}`,
          `## Component "${c.id}" (${c.dir})`,
          c.groups.length
            ? `## Its groups, each with its files\n${c.groups.map((gr) => `### Group "${gr.key}"${usedFor(gr.files)}\n${gr.files.map(fileLine).join("\n")}`).join("\n\n")}`
            : `## Its files\n${c.files.map(fileLine).join("\n")}`,
          `## Depends on\n${out.map((e) => `${e.to}: calls ${e.names.join(", ") || "(imports only)"}`).join("\n") || "(nothing)"}`,
          `## Used by\n${into.map((e) => `${e.from}: calls ${e.names.join(", ") || "(imports only)"}`).join("\n") || "(nothing)"}`,
          `${entries.some((p) => c.files.includes(p)) ? `## Entry points here\n${entries.filter((p) => c.files.includes(p)).join("\n")}\n\n` : ""}## Task\nDescribe this component${c.groups.length ? ", each of its groups," : ""} and each of its files.`,
        ].join("\n\n");
        const a = await askWithin({ model, stage: "fast-fanout", maxTokens: 8000, prompt, tool: COMPONENT_TOOL }, (x) =>
          wordProblems([
            ["the component's title", x?.title, 4],
            ["the component's sub", x?.sub, SUB_WORDS],
            ["the component's responsibility", x?.responsibility, 40],
            ...(x?.groups ?? []).flatMap((gr: any): [string, unknown, number][] => [[`group ${gr?.key}'s title`, gr?.title, 3], [`group ${gr?.key}'s sub`, gr?.sub, SUB_WORDS], [`group ${gr?.key}'s detail`, gr?.detail, 40]]),
            ...(x?.files ?? []).flatMap((f: any): [string, unknown, number][] => [[`${f?.path}'s title`, f?.title, 3], [`${f?.path}'s sub`, f?.sub, SUB_WORDS]]),
          ]),
        );
        return [c.id, a] as const;
      }),
    ),
  );
  const about = new Map(described);

  // Phase 4: the top line, the order, and a label per arrow the graph has.
  const synth = await lap("synthesize", () => {
    const prompt = [
      `# Repository: ${inv.name}`,
      `## README\n${inv.readme.slice(0, 4000) || "(none)"}`,
      `## Components\n${comps
        .map((c) => {
          const a = about.get(c.id);
          return `- ${c.id}: ${a?.title} — ${a?.sub}\n  ${a?.responsibility}`;
        })
        .join("\n")}`,
      `## Links between them, from the code (from → to: weight; what is called, most called first)\n${mod.filter((e) => e.calls).map((e) => `- ${e.from} → ${e.to}: ${e.weight}; ${e.names.join(", ")}`).join("\n") || "(none)"}`,
      `## Task\nWrite the bluprint's top level: its line and detail, the order of the components, and a label for each link listed. A link's arrow cites a call to the first name it lists, so its label says what that call does.`,
    ].join("\n\n");
    return askWithin({ model, stage: "fast-synthesize", maxTokens: 4000, prompt, tool: SYNTH_TOOL }, (x) => [
      ...wordProblems([["the sub", x?.sub, SUB_WORDS], ["the detail", x?.detail, 40]]),
      ...(x?.arrows ?? []).filter((a: any) => typeof a?.label === "string" && a.label.length > 24).map((a: any) => `the label "${a.label}" of ${a.from} → ${a.to} is ${a.label.length} characters; at most 24`),
    ]);
  });

  const discrepancies: string[] = [];
  const order = [...(synth.order ?? []).filter((id: string) => byId.has(id)), ...comps.map((c) => c.id).filter((id) => !(synth.order ?? []).includes(id))];
  for (const id of synth.order ?? []) if (!byId.has(id)) discrepancies.push(`synthesize ordered "${id}", which is no component`);

  const diagram = diagramOf(g);
  /** The file of some files the others call into most: what a level's own code cites. */
  const keyFile = (files: string[]) => {
    const set = new Set(files);
    const into = (p: string) => calls.filter((e) => fileOfDef(e.to) === p && set.has(fileOfDef(e.from)) && fileOfDef(e.from) !== p).length;
    return [...files].sort((a, b) => into(b) - into(a) || a.localeCompare(b))[0];
  };

  // The tree: a node per component, a node per group in a big one, a leaf per file with its functions as steps.
  const AUTHORED: Node[] = order.map((id, row) => {
    const c = byId.get(id)!;
    const a = about.get(id) ?? {};
    const titled = new Map<string, any>((a.files ?? []).map((f: any) => [String(f.path).replace(/^\.?\//, ""), f]));
    for (const p of titled.keys()) if (!c.files.includes(p)) discrepancies.push(`${id}: fanout named a file ${p} that is not in it`);
    const ids = new Set<string>();
    const unique = (k: string) => {
      for (let n = 2; ids.has(k); n++) k = `${k.replace(/-\d+$/, "")}-${n}`;
      ids.add(k);
      return k;
    };
    // In the order the fanout gave, then any it left out.
    const ordered = (files: string[]) => [...[...titled.keys()].filter((p) => files.includes(p)), ...files.filter((p) => !titled.has(p))];
    const leaf = (p: string, i: number): Node => {
      const s = sums[p];
      const t = titled.get(p);
      // A step past the file's end is a summary's misreading: left out, not cited.
      const steps = (s?.symbols ?? []).filter((sym) => sym.start >= 1 && sym.start <= (lines.get(p) ?? 0)).slice(0, 8).map((sym, n) => ({ n: n + 1, title: short(sym.name, 40), detail: sym.does || sym.name, state: "derived", at: `${p}:${sym.start}` }));
      return {
        id: unique(`${c.prefix}-${slug(basename(p))}`),
        title: short(t?.title || basename(p), 40),
        sub: short(t?.sub || s?.kind || "", 60),
        state: "derived",
        col: 0,
        row: i,
        detail: within40(s?.purpose ?? ""),
        code: leafCode(p, lines.get(p) ?? 1, s),
        ...(steps.length ? { anatomy: [{ kind: "flow", rows: steps }] } : {}),
      } as unknown as Node;
    };
    const level = (nodeId: string, title: string, sub: string, detail: string, files: string[], kids: { node: Node; files: string[] }[], i: number): Node => {
      const key = keyFile(files);
      return {
        id: nodeId,
        title: short(title, 40),
        sub: short(sub, 60),
        state: "derived",
        col: 0,
        row: i,
        detail,
        code: key ? leafCode(key, lines.get(key) ?? 1, sums[key]) : [],
        anatomy: [diagram(title, kids, "b-")],
        children: kids.map((k) => k.node),
      } as unknown as Node;
    };
    let kids: { node: Node; files: string[] }[];
    if (c.groups.length) {
      const named = new Map<string, any>((a.groups ?? []).map((x: any) => [x.key, x]));
      for (const k of named.keys()) if (!c.groups.some((gr) => gr.key === k)) discrepancies.push(`${id}: fanout named a group "${k}" that is not in it`);
      const groups = [...[...named.keys()].map((k) => c.groups.find((gr) => gr.key === k)).filter((x): x is Group => Boolean(x)), ...c.groups.filter((gr) => !named.has(gr.key))];
      kids = groups.map((gr, i) => {
        const n = named.get(gr.key) ?? {};
        const files = ordered(gr.files);
        const leaves = files.map((p, j) => ({ node: leaf(p, j), files: [p] }));
        return { node: level(unique(`${c.prefix}-${slug(gr.key)}`), n.title || gr.key, n.sub || gr.dir, n.detail ?? "", gr.files, leaves, i), files: gr.files };
      });
    } else kids = ordered(c.files).map((p, i) => ({ node: leaf(p, i), files: [p] }));
    return level(id, a.title || id, a.sub || c.dir, a.responsibility ?? "", c.files, kids, row);
  });

  // The top level: a box per component, arrows only where the graph has calls.
  const labels = new Map<string, string>();
  for (const x of synth.arrows ?? []) {
    const edge = mod.find((e) => e.from === x.from && e.to === x.to && e.calls);
    if (edge) labels.set(`${x.from}\n${x.to}`, x.label);
    else discrepancies.push(`synthesize labelled ${x.from} → ${x.to}, a link the graph does not have`);
  }
  const top = diagram(
    "How the parts connect",
    AUTHORED.map((n) => ({ node: n, files: byId.get(n.id)!.files })),
    "bx-",
    (a, b) => labels.get(`${a.id}\n${b.id}`),
    (a, b) => mod.find((e) => e.from === a.id && e.to === b.id)?.names[0],
  );
  const OVERVIEW = {
    sub: short(synth.sub ?? inv.name, 60),
    detail: synth.detail ?? "",
    state: "derived",
    // Where the code starts, a range each.
    code: entries.slice(0, 3).map((p) => leafCode(p, lines.get(p) ?? 1, sums[p])[0]),
    anatomy: [top],
  } as unknown as Overview;

  const bluprint: BluprintFile = { RUN: run, OVERVIEW, AUTHORED };
  // Held to the quick bluprint's own standard: it writes no explainers, whatever the bluprint's level.
  const checkProblems = await lap("check", () => check({ ...bluprint, RUN: { ...run, explain: "none" } }, inv.repo, { generated: true }).problems);

  const arch: FastResult["arch"] = {
    files: Object.fromEntries(
      inv.files
        .filter(isSource)
        .map((f) => [f.path, { component: owner.get(f.path)?.id ?? "", lines: f.lines, symbols: g.defs.filter((d) => d.file === f.path && !d.parent).map((d) => ({ name: d.name, kind: d.kind, line: d.start })), imports: inv.imports[f.path] ?? [] }]),
    ),
    components: comps,
    module_graph: mod,
    entrypoints: entries,
    external_deps: inv.deps,
  };
  return { bluprint, arch, discrepancies, checkProblems, timing };
}

app/scripts/generate/fill.ts:
/**
 * What a submit leaves for the graph to fill, filled before it is checked.
 *
 * An author spends output on structure the graph already knows, and most
 * rejected submits were that structure gone wrong: an arrow citing a line
 * with no call on it, two boxes in one cell. So a submit may name code by its
 * graph id and leave the rest to this:
 * - `code: [{ def, label }]` becomes the definition's file and lines;
 * - a box `ref`, or a flow or sequence step's `at`, given as a graph id
 *   becomes its file:line (a step's lines are clamped by autofix);
 * - a diagram whose boxes lack `col`/`row` is laid out along its arrows;
 * - an arrow with no `at`, or one whose `at` has no call into its target, gets
 *   the line of a call the graph has between the two boxes' code.
 * What cannot be filled is left as it was, for the checker to name. Notes say
 * what was filled, so the author's next `replace` starts from the tree as it
 * now stands; problems name a graph id that matches nothing.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- model tool inputs */
import { boxRanges, callLine } from "./check";
import type { Graph } from "./graph";
import { resolveDef } from "./graph-tools";

const FILE_LINE = /^(.+?):(\d+)(?:-(\d+))?$/;

/** How many columns a laid-out diagram may span before it wraps to the next rows. */
const MAX_COLS = 4;

/** Columns along the arrows (a box sits one column right of what points at it), rows in the order given. */
function layout(b: any): number {
  const boxes: any[] = b.boxes;
  if (boxes.every((x) => Number.isInteger(x?.col) && Number.isInteger(x?.row))) return 0;
  const ids = new Set(boxes.map((x) => x.id));
  const into = new Map<string, string[]>();
  for (const a of b.arrows ?? []) if (ids.has(a.from) && ids.has(a.to) && a.from !== a.to) into.set(a.to, [...(into.get(a.to) ?? []), a.from]);
  const depth = new Map<string, number>();
  const visit = (id: string, seen: Set<string>): number => {
    if (depth.has(id)) return depth.get(id)!;
    if (seen.has(id)) return 0;
    seen.add(id);
    const d = Math.max(-1, ...(into.get(id) ?? []).map((f) => visit(f, seen))) + 1;
    seen.delete(id);
    depth.set(id, d);
    return d;
  };
  const taken = new Set<string>();
  const placed = boxes.filter((x) => Number.isInteger(x?.col) && Number.isInteger(x?.row));
  for (const x of placed) taken.add(`${x.col},${x.row}`);
  let n = 0;
  for (const x of boxes) {
    if (placed.includes(x)) continue;
    const d = visit(x.id, new Set());
    const col = d % MAX_COLS;
    let row = Math.floor(d / MAX_COLS) * 3;
    while (taken.has(`${col},${row}`)) row++;
    x.col = col;
    x.row = row;
    taken.add(`${col},${row}`);
    n++;
  }
  return n;
}

export function fillFromGraph(root: any, g: Graph | null): { notes: string[]; problems: string[] } {
  const notes: string[] = [];
  const problems: string[] = [];
  if (!root || typeof root !== "object") return { notes, problems };
  const unknown = (owner: string, what: string, raw: string) =>
    problems.push(`GRAPH ${owner} ${what} names "${raw}", which is not one definition in the graph — use an id graph_find or graph_file gives, or give file and lines`);

  // 1. Graph ids to lines, everywhere they may stand in for them.
  const nodes = new Map<string, any>();
  const blocksOf = (n: any) => [...(Array.isArray(n.anatomy) ? n.anatomy : []), ...(Array.isArray(n.explain?.blocks) ? n.explain.blocks : [])];
  const eachBlock = (list: any[], f: (b: any) => void) => {
    for (const b of list) {
      if (!b || typeof b !== "object") continue;
      f(b);
      for (const r of Array.isArray(b.rows) ? b.rows : []) if (Array.isArray(r?.under)) eachBlock(r.under, f);
    }
  };
  const expand = (n: any) => {
    if (!n || typeof n !== "object") return;
    if (typeof n.id === "string") nodes.set(n.id, n);
    if (g && Array.isArray(n.code))
      n.code.forEach((c: any, i: number) => {
        if (!c || typeof c !== "object" || typeof c.def !== "string" || (typeof c.file === "string" && Number.isInteger(c.start))) return;
        const d = resolveDef(g, c.def);
        if (!d) return unknown(n.id, `code[${i}].def`, c.def);
        n.code[i] = { file: d.file, start: d.start, end: d.end, label: c.label ?? d.name };
      });
    if (g)
      eachBlock(blocksOf(n), (b) => {
        if (b.kind === "diagram")
          for (const x of Array.isArray(b.boxes) ? b.boxes : []) {
            if (typeof x?.ref !== "string" || FILE_LINE.test(x.ref) || g.files.includes(x.ref)) continue;
            const d = resolveDef(g, x.ref);
            if (d) x.ref = `${d.file}:${d.start}`;
            else unknown(n.id, `box "${x.id}" ref`, x.ref);
          }
        if (b.kind === "flow" || b.kind === "sequence")
          for (const [i, r] of (Array.isArray(b.rows) ? b.rows : []).entries()) {
            if (typeof r?.at !== "string" || FILE_LINE.test(r.at)) continue;
            const d = resolveDef(g, r.at);
            if (d) r.at = `${d.file}:${d.start}-${d.end}`;
            else unknown(n.id, `${b.kind} row ${i + 1} at`, r.at);
          }
        if (b.kind === "screen")
          for (const it of Array.isArray(b.items) ? b.items : []) {
            if (typeof it?.at !== "string" || FILE_LINE.test(it.at)) continue;
            const d = resolveDef(g, it.at);
            if (d) it.at = `${d.file}:${d.start}-${d.end}`;
            else unknown(n.id, `screen item "${it.label}" at`, it.at);
          }
      });
    (Array.isArray(n.children) ? n.children : []).forEach(expand);
  };
  expand(root);

  // 2. Boxes laid out, and arrows given the line of their call.
  const draw = (n: any) => {
    if (!n || typeof n !== "object") return;
    eachBlock(blocksOf(n), (b) => {
      if (b.kind !== "diagram" || !Array.isArray(b.boxes)) return;
      const moved = layout(b);
      if (moved) notes.push(`${n.id}: ${moved} box${moved === 1 ? "" : "es"} placed on the grid along the arrows`);
    });
    if (g)
      for (const b of Array.isArray(n.anatomy) ? n.anatomy : []) {
        if (b?.kind !== "diagram" || !Array.isArray(b.boxes)) continue;
        for (const a of Array.isArray(b.arrows) ? b.arrows : []) {
          if (!a || a.inferred) continue;
          const from = boxRanges(g, b.boxes.find((x: any) => x.id === a.from), nodes);
          const to = boxRanges(g, b.boxes.find((x: any) => x.id === a.to), nodes);
          if (!from.length || !to.length) continue;
          const m = typeof a.at === "string" ? FILE_LINE.exec(a.at) : null;
          // An `at` already on a call into the target stands, with the same slack of a line either side as the checker allows.
          if (m && callLine(g, [{ file: m[1], start: +m[2] - 1, end: +(m[3] ?? m[2]) + 1 }], to)) continue;
          const at = callLine(g, from, to);
          if (!at) continue;
          notes.push(`${n.id}: arrow ${a.from}→${a.to} ${a.at ? `re-cited from ${a.at} to` : "cites"} ${at}, the call the graph has between them`);
          a.at = at;
        }
      }
    (Array.isArray(n.children) ? n.children : []).forEach(draw);
  };
  draw(root);
  return { notes, problems };
}

app/scripts/generate/gitdiff.ts:
/**
 * Reading what changed in a checkout, and moving a bluprint's line references with
 * it. Extracted from scripts/generate/update.ts, which still owns deciding
 * which sections to redo and redoing them; this is only the git and
 * line-arithmetic half.
 *
 * It is shared because the visual diff (lib/diff.ts) asks the same questions
 * an update asks — what changed since the bluprint was made, and where did each
 * cited line go — and two implementations of `moved` would drift into two
 * different answers about the same commit.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- walks bluprint JSON, typed or not */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { Node } from "@/lib/bluprint/schema";

/** A run of changed lines: `ol` old lines from `os` became `nl` new ones from `ns`. With `ol` 0, lines were inserted after `os`. */
export interface Hunk {
  os: number;
  ol: number;
  ns: number;
  nl: number;
}

export interface Change {
  path: string;
  before: string | null;
  after: string | null;
  hunks: Hunk[];
  /** For the agent: a unified diff with a little context. */
  diff: string;
}

export const git = (repo: string, ...args: string[]) => {
  try {
    return execFileSync("git", ["-C", repo, ...args], { encoding: "utf8", maxBuffer: 64 << 20, stdio: ["ignore", "pipe", "ignore"], windowsHide: true });
  } catch {
    return "";
  }
};

/* ── 1. what changed ─────────────────────────────────────────── */

/** The text the bluprint was made from, per path: null where the file did not exist. */
export type Base = Record<string, string | null>;

export function readText(path: string): string | null {
  if (!statSync(path, { throwIfNoEntry: false })?.isFile()) return null;
  const buf = readFileSync(path);
  return buf.includes(0) ? null : buf.toString("utf8");
}

/** `git diff --no-index` between two texts, as hunks and as a readable diff. */
export function diffOf(path: string, before: string | null, after: string | null): Pick<Change, "hunks" | "diff"> {
  const dir = mkdtempSync(join(tmpdir(), "slop-diff-"));
  try {
    const a = join(dir, "a");
    const b = join(dir, "b");
    writeFileSync(a, before ?? "");
    writeFileSync(b, after ?? "");
    const run = (u: number) => {
      try {
        return execFileSync("git", ["diff", "--no-index", "--no-color", `-U${u}`, a, b], { encoding: "utf8", maxBuffer: 64 << 20, windowsHide: true });
      } catch (e: any) {
        // 1 means "they differ", which is the point.
        return String(e.stdout ?? "");
      }
    };
    const hunks = [...run(0).matchAll(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/gm)].map((m) => ({
      os: Number(m[1]),
      ol: m[2] === undefined ? 1 : Number(m[2]),
      ns: Number(m[3]),
      nl: m[4] === undefined ? 1 : Number(m[4]),
    }));
    const body = run(3).split("\n").filter((l) => !/^(diff --git|index |--- |\+\+\+ )/.test(l));
    return { hunks, diff: [`--- ${before === null ? "/dev/null" : `a/${path}`}`, `+++ ${after === null ? "/dev/null" : `b/${path}`}`, ...body].join("\n") };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

/** Every file whose text differs from what the bluprint last saw. */
export function changes(repo: string, commit: string, base: Base): Change[] {
  const paths = new Set([
    ...git(repo, "diff", "--name-only", commit).split("\n"),
    ...git(repo, "ls-files", "--others", "--exclude-standard").split("\n"),
    ...Object.keys(base),
  ]);
  paths.delete("");
  const out: Change[] = [];
  for (const path of [...paths].sort()) {
    const before = path in base ? base[path] : hasAt(repo, commit, path) ? git(repo, "show", `${commit}:${path}`) : null;
    const after = readText(join(repo, path));
    if (before === after) continue;
    out.push({ path, before, after, ...diffOf(path, before, after) });
  }
  return out;
}

export const hasAt = (repo: string, commit: string, path: string) => {
  try {
    execFileSync("git", ["-C", repo, "cat-file", "-e", `${commit}:${path}`], { stdio: "ignore", windowsHide: true });
    return true;
  } catch {
    return false;
  }
};

/* ── 2. references ───────────────────────────────────────────── */

/** `path/to/file.ts:12` or `:12-30`, as issues, arrows and evidence cite code. */
export const CITE = /([\w@.()[\]/+-]+\.[A-Za-z0-9]+):(\d+)(?:-(\d+))?/g;

export interface Span {
  file: string;
  s: number;
  e: number;
}

/**
 * A node's own references, not its children's: `{file, start, end}` code
 * refs, `{file, start, code}` quoted source, and `file:line` in any text.
 * With `move`, each is rewritten through it.
 */
export function refs(n: Node, move?: (file: string, line: number) => number): Span[] {
  const out: Span[] = [];
  const visit = (v: any, parent?: any, key?: string | number) => {
    if (Array.isArray(v)) return v.forEach((x, i) => visit(x, v, i));
    if (typeof v === "string" && parent !== undefined) {
      for (const m of v.matchAll(CITE)) out.push({ file: m[1], s: Number(m[2]), e: Number(m[3] ?? m[2]) });
      if (move)
        parent[key!] = v.replace(CITE, (_all, f: string, a: string, b?: string) =>
          b === undefined ? `${f}:${move(f, Number(a))}` : `${f}:${move(f, Number(a))}-${move(f, Number(b))}`,
        );
      return;
    }
    if (!v || typeof v !== "object") return;
    if (typeof v.file === "string" && Number.isInteger(v.start)) {
      const e = Number.isInteger(v.end) ? v.end : typeof v.code === "string" ? v.start + v.code.split("\n").length - 1 : v.start;
      out.push({ file: v.file, s: v.start, e });
      if (move) {
        if (Number.isInteger(v.end)) v.end = move(v.file, v.end);
        v.start = move(v.file, v.start);
      }
    }
    // Quoted source stays verbatim, whatever it happens to contain.
    for (const [k, x] of Object.entries(v)) if (k !== "children" && k !== "file" && !(k === "code" && typeof x === "string")) visit(x, v, k);
  };
  visit(n);
  return out;
}

/** Whether lines s..e (old numbering) saw a change. */
export function touches(c: Change, s: number, e: number): boolean {
  if (c.after === null) return true;
  return c.hunks.some((h) => (h.ol > 0 ? h.os <= e && h.os + h.ol - 1 >= s : s <= h.os && h.os < e));
}

/** Where an old line is now, for a line no change landed on. */
export function moved(c: Change, line: number): number {
  let d = 0;
  for (const h of c.hunks) if ((h.ol > 0 ? h.os + h.ol - 1 : h.os) < line) d += h.nl - h.ol;
  return Math.max(1, line + d);
}

app/scripts/generate/graph-tools.ts:
/**
 * The fact graph (graph.ts) as tools an agent calls instead of grepping for
 * structure: find a definition, outline a file, list who calls something and
 * what it calls, trace a path between two things, and list where the code
 * starts. Every answer names file:line, so the agent reads only what it then
 * needs to explain. Edges say whether the source states them (extracted) or
 * the graph resolved them by name (inferred).
 */
import type { Tool } from "./bedrock";
import { unparsedSource, type Def, type Edge, type Graph } from "./graph";

export const GRAPH_TOOLS: Tool[] = [
  {
    name: "graph_find",
    description: "Find functions, methods and classes by name (or part of one, or Class.method). Returns each one's id, kind, file:lines and how many callers and callees it has. Start here to get ids for the other graph tools.",
    input_schema: { type: "object", required: ["name"], properties: { name: { type: "string" } } },
  },
  {
    name: "graph_show",
    description: "One function, method or class in full: its signature and decorators as written, its doc comment, what it does, its line range, what it sits in and what sits in it, and who calls it and what it calls. This is how you read code: there is no other way to see it.",
    input_schema: { type: "object", required: ["name"], properties: { name: { type: "string", description: "An id from another graph tool, a Class.method, or a name only one thing has." } } },
  },
  {
    name: "graph_links",
    description: "Every call and inheritance from one part of the code into another, each with the line it happens on: what to draw as arrows between two boxes. Each side is a list of file paths, directories (ending in /) or ids.",
    input_schema: { type: "object", required: ["from", "to"], properties: { from: { type: "array", items: { type: "string" } }, to: { type: "array", items: { type: "string" } } } },
  },
  {
    name: "graph_file",
    description: "Outline one file: what it is for, every function, method and class in it with line ranges and what each does, then which files it uses and which files use it. For a file the graph cannot parse (an Astro, Vue or Svelte file, or a language it has no grammar for) it shows the file's numbered lines instead, so you can cite one.",
    input_schema: { type: "object", required: ["path"], properties: { path: { type: "string" } } },
  },
  {
    name: "graph_callers",
    description: "Who calls or inherits from a function, method or class (an id, or a name if only one thing has it), with the file:line of each call. For a file path: which files import it.",
    input_schema: { type: "object", required: ["name"], properties: { name: { type: "string" } } },
  },
  {
    name: "graph_callees",
    description: "What a function, method or class calls or inherits from, with the file:line of each call. For a file path: what code at its top level calls, and which files it imports.",
    input_schema: { type: "object", required: ["name"], properties: { name: { type: "string" } } },
  },
  {
    name: "graph_path",
    description: "The shortest chain of calls (and inheritance) from one thing to another, each hop with the line it happens on. Use it to trace a flow or to check that A really reaches B.",
    input_schema: { type: "object", required: ["from", "to"], properties: { from: { type: "string" }, to: { type: "string" } } },
  },
  {
    name: "graph_entrypoints",
    description: "Where the code starts: files no other file imports, and functions nothing in the repository calls but that call others (often handlers a framework calls, such as routes, commands or event handlers).",
    input_schema: { type: "object", properties: {} },
  },
];

interface Index {
  byId: Map<string, Def>;
  out: Map<string, Edge[]>;
  in: Map<string, Edge[]>;
  files: Set<string>;
}
const indexes = new WeakMap<Graph, Index>();
function index(g: Graph): Index {
  let ix = indexes.get(g);
  if (ix) return ix;
  ix = { byId: new Map(g.defs.map((d) => [d.id, d])), out: new Map(), in: new Map(), files: new Set(g.defs.map((d) => d.file)) };
  for (const e of g.edges) {
    ix.out.set(e.from, [...(ix.out.get(e.from) ?? []), e]);
    ix.in.set(e.to, [...(ix.in.get(e.to) ?? []), e]);
    if (e.kind === "imports") ix.files.add(e.from).add(e.to);
    // A link found by name in a file with no grammar starts or ends at the file itself.
    for (const end of [e.from, e.to]) if (!ix.byId.has(end)) ix.files.add(end);
  }
  indexes.set(g, ix);
  return ix;
}

const qual = (d: Def) => d.id.slice(d.id.indexOf("#") + 1).replace(/@\d+$/, "");
const fileOf = (ix: Index, id: string) => ix.byId.get(id)?.file ?? id;
const label = (ix: Index, id: string) => {
  const d = ix.byId.get(id);
  return d ? `${qual(d)} (${d.kind}, ${d.file}:${d.start}-${d.end})` : `${id} (file)`;
};
const lines = (ix: Index, e: Edge) => (e.lines.length ? `${fileOf(ix, e.from)}:${e.lines.slice(0, 4).join(",")}${e.lines.length > 4 ? ",…" : ""}` : "");

/** An id, a file path, a Class.method or a bare name; several matches are listed for the agent to pick from. */
function resolveName(g: Graph, ix: Index, raw: string): { id: string } | { error: string } {
  // `file::name`, `file:name` and `file.name` are how agents guess an id; the graph writes `file#name`.
  const trimmed = raw.trim().replace(/^\.?\//, "");
  const guess = /^(.+\.\w+)(?:::|:(?!\d)|#)(.+)$/.exec(trimmed);
  const s = guess && ix.files.has(guess[1]) ? `${guess[1]}#${guess[2]}` : trimmed;
  if (ix.byId.has(s) || ix.files.has(s)) return { id: s };
  const hits = g.defs.filter((d) => qual(d) === s || d.name === s || qual(d).endsWith(`.${s}`));
  if (hits.length === 1) return { id: hits[0].id };
  if (!hits.length) {
    const file = [...ix.files].filter((f) => f.endsWith(s));
    if (file.length === 1) return { id: file[0] };
    return { error: `Nothing in the graph is called "${raw}". Try graph_find with part of the name. (The graph holds functions, methods and classes; framework wiring such as decorators or events is not in it.)` };
  }
  return { error: `"${raw}" is ${hits.length} things; call again with one id:\n${hits.slice(0, 20).map((d) => `  ${d.id}  ${d.kind}  ${d.file}:${d.start}-${d.end}`).join("\n")}` };
}

function find(g: Graph, ix: Index, name: string): string {
  const n = name.trim().toLowerCase();
  if (!n) return "Give a name.";
  const hits = g.defs
    .filter((d) => qual(d).toLowerCase().includes(n))
    .sort((a, b) => Number(b.name.toLowerCase() === n) - Number(a.name.toLowerCase() === n) || (ix.in.get(b.id)?.length ?? 0) - (ix.in.get(a.id)?.length ?? 0));
  if (!hits.length) return `No function, method or class matches "${name}".`;
  return hits.slice(0, 30).map((d) => `${d.id}  ${d.kind}  ${d.file}:${d.start}-${d.end}  ← ${ix.in.get(d.id)?.length ?? 0} callers, → ${ix.out.get(d.id)?.length ?? 0} callees${d.does ? `\n    ${d.does}` : ""}`).join("\n") + (hits.length > 30 ? `\n… ${hits.length - 30} more; narrow the name` : "");
}

/** How much of a file with no grammar graph_file shows: a page or component, not a dump. */
const SOURCE_LINES = 300;

function outline(g: Graph, ix: Index, path: string): string {
  const p = path.trim().replace(/^\.?\//, "");
  const defs = g.defs.filter((d) => d.file === p);
  if (!defs.length && !ix.files.has(p) && unparsedSource(g, p) === null) return `No code file ${p} in the graph.`;
  const depth = (d: Def): number => (d.parent ? 1 + depth(ix.byId.get(d.parent)!) : 0);
  const body = defs.map((d) => `${"  ".repeat(depth(d))}${d.start}-${d.end} ${d.name} (${d.kind})${d.does ? ` — ${d.does}` : ""}`).join("\n");
  const outFiles = new Map<string, number>();
  const inFiles = new Map<string, number>();
  const mine = new Set([p, ...defs.map((d) => d.id)]);
  for (const id of mine) {
    for (const e of ix.out.get(id) ?? []) if (fileOf(ix, e.to) !== p) outFiles.set(fileOf(ix, e.to), (outFiles.get(fileOf(ix, e.to)) ?? 0) + 1);
    for (const e of ix.in.get(id) ?? []) if (fileOf(ix, e.from) !== p) inFiles.set(fileOf(ix, e.from), (inFiles.get(fileOf(ix, e.from)) ?? 0) + 1);
  }
  const list = (m: Map<string, number>) => [...m].sort((a, b) => b[1] - a[1]).slice(0, 25).map(([f, n]) => `  ${f} (${n})`).join("\n") || "  nothing";
  // No grammar read it, so its lines are the outline: the only way to see where it uses what.
  const src = unparsedSource(g, p);
  const shown = src && src.split("\n").slice(0, SOURCE_LINES);
  const text = shown ? `\nThe graph cannot parse this file, so here are its lines${src!.split("\n").length > SOURCE_LINES ? ` (the first ${SOURCE_LINES})` : ""}; a link from it was found by name and is inferred:\n${shown.map((l, i) => `${String(i + 1).padStart(4)}  ${l}`).join("\n")}` : "";
  return `${p}${g.about?.[p] ? `\n${g.about[p]}` : ""}\n${body || (src ? "" : "  (no functions or classes)")}${text}\nUses:\n${list(outFiles)}\nUsed by:\n${list(inFiles)}`;
}

function neighbours(g: Graph, ix: Index, name: string, dir: "in" | "out"): string {
  const r = resolveName(g, ix, name);
  if ("error" in r) return r.error;
  const es = (dir === "in" ? ix.in : ix.out).get(r.id) ?? [];
  if (!es.length) return dir === "in" ? `Nothing in the repository calls, inherits from or imports ${label(ix, r.id)}. A framework, a test or another program may call it.` : `${label(ix, r.id)} calls nothing else in the repository.`;
  const order: Edge["kind"][] = ["inherits", "calls", "imports"];
  const shown = [...es].sort((a, b) => order.indexOf(a.kind) - order.indexOf(b.kind) || b.lines.length - a.lines.length).slice(0, 40);
  const head = label(ix, r.id);
  return `${head}\n${shown.map((e) => `  ${dir === "in" ? "←" : "→"} ${e.kind} ${label(ix, dir === "in" ? e.from : e.to)}${e.lines.length ? ` at ${lines(ix, e)}` : ""} [${e.how}]`).join("\n")}${es.length > 40 ? `\n  … ${es.length - 40} more` : ""}`;
}

function show(g: Graph, ix: Index, name: string): string {
  const r = resolveName(g, ix, name);
  if ("error" in r) return r.error;
  if (!ix.byId.has(r.id)) return outline(g, ix, r.id);
  const d = ix.byId.get(r.id)!;
  const kids = g.defs.filter((k) => k.parent === d.id);
  const ins = ix.in.get(d.id) ?? [];
  const outs = ix.out.get(d.id) ?? [];
  return [
    `${d.id}  ${d.kind}  ${d.file}:${d.start}-${d.end}`,
    d.head ? `\n${d.head}` : "",
    d.doc ? `\nDoc: ${d.doc}` : "",
    d.does ? `\nDoes: ${d.does}` : "",
    d.parent ? `\nIn: ${label(ix, d.parent)}` : "",
    kids.length ? `\nHolds:\n${kids.slice(0, 40).map((k) => `  ${k.start}-${k.end} ${k.name} (${k.kind})${k.does ? ` — ${k.does}` : ""}`).join("\n")}` : "",
    `\nCalled by (${ins.length}):${ins.length ? "\n" + ins.slice(0, 15).map((e) => `  ← ${e.kind} ${label(ix, e.from)}${e.lines.length ? ` at ${lines(ix, e)}` : ""} [${e.how}]`).join("\n") : " nothing in the repository"}`,
    `\nCalls (${outs.length}):${outs.length ? "\n" + outs.slice(0, 25).map((e) => `  → ${e.kind} ${label(ix, e.to)}${e.lines.length ? ` at ${lines(ix, e)}` : ""} [${e.how}]`).join("\n") : " nothing in the repository"}`,
  ].join("");
}

/** Whether a definition or file falls under a spec: its id, its file, or a directory it is in. */
const under = (ix: Index, id: string, specs: string[]) => {
  const file = fileOf(ix, id);
  return specs.some((raw) => {
    const s = raw.trim().replace(/^\.?\//, "");
    return s && (id === s || file === s || (s.endsWith("/") ? file.startsWith(s) : file.startsWith(`${s}/`)) || id.startsWith(`${s}.`) || id.startsWith(`${s}#`));
  });
};

function links(g: Graph, ix: Index, from: string[], to: string[]): string {
  if (!from.length || !to.length) return "Give both sides: files, directories ending in /, or ids.";
  const hits = g.edges.filter((e) => e.kind !== "imports" && under(ix, e.from, from) && under(ix, e.to, to) && !under(ix, e.from, to));
  if (!hits.length) {
    const imp = g.edges.filter((e) => e.kind === "imports" && under(ix, e.from, from) && under(ix, e.to, to));
    return `No call from ${from.join(", ")} into ${to.join(", ")}.${imp.length ? ` ${imp.length} import${imp.length === 1 ? "" : "s"} between them (${imp.slice(0, 5).map((e) => `${e.from} → ${e.to}`).join("; ")}), so they are linked some way the graph cannot follow: a callback, a decorator, an event or a framework. An arrow there must be marked inferred.` : " If they connect, it is through something the graph cannot see (a callback, an event, a queue, a framework, the network); an arrow there must be marked inferred."}`;
  }
  const shown = [...hits].sort((a, b) => Number(b.how === "extracted") - Number(a.how === "extracted")).slice(0, 60);
  return `${hits.length} link${hits.length === 1 ? "" : "s"}; cite one's line as the arrow's \`at\`:\n${shown.map((e) => `  ${label(ix, e.from)} —${e.kind}${e.lines.length ? ` at ${lines(ix, e)}` : ""} [${e.how}]→ ${label(ix, e.to)}`).join("\n")}${hits.length > 60 ? `\n  … ${hits.length - 60} more; narrow a side` : ""}`;
}

function path(g: Graph, ix: Index, from: string, to: string): string {
  const a = resolveName(g, ix, from);
  if ("error" in a) return a.error;
  const b = resolveName(g, ix, to);
  if ("error" in b) return b.error;
  // A file stands for the code in it: its top level and every definition.
  const starts = ix.files.has(a.id) ? [a.id, ...g.defs.filter((d) => d.file === a.id).map((d) => d.id)] : [a.id];
  const goal = (id: string) => id === b.id || (ix.files.has(b.id) && fileOf(ix, id) === b.id);
  const prev = new Map<string, Edge | null>(starts.map((s) => [s, null]));
  const queue = [...starts];
  while (queue.length) {
    const cur = queue.shift()!;
    if (goal(cur) && !starts.includes(cur)) {
      const hops: Edge[] = [];
      for (let e = prev.get(cur); e; e = prev.get(e.from)) hops.unshift(e);
      const weakest = hops.some((h) => h.how === "inferred") ? "inferred" : "extracted";
      return `${hops.length} hop${hops.length === 1 ? "" : "s"} (${weakest}):\n${label(ix, hops[0].from)}\n${hops.map((h) => `  —${h.kind}${h.lines.length ? ` at ${lines(ix, h)}` : ""} [${h.how}]→ ${label(ix, h.to)}`).join("\n")}`;
    }
    for (const e of ix.out.get(cur) ?? []) {
      if (e.kind === "imports" || prev.has(e.to)) continue;
      prev.set(e.to, e);
      queue.push(e.to);
    }
  }
  const imp = ix.files.has(fileOf(ix, a.id)) && (ix.out.get(fileOf(ix, a.id)) ?? []).some((e) => e.to === fileOf(ix, b.id));
  return `No chain of calls leads from ${label(ix, a.id)} to ${label(ix, b.id)}.${imp ? " Its file does import the other's file." : ""} The link may run through something the graph cannot see (a decorator, a callback passed as a value, an event, a queue, a framework); look in the code.`;
}

function entrypoints(g: Graph, ix: Index): string {
  const test = /(^|\/)(tests?|__tests__|specs?|e2e)\/|\.(test|spec)\.[a-z]+$|(^|\/)(test_[^/]+|[^/]+_test)\.(py|go)$/;
  const roots = [...ix.files]
    .filter((f) => !test.test(f) && !(ix.in.get(f) ?? []).some((e) => e.kind === "imports"))
    .map((f) => [f, (ix.out.get(f) ?? []).filter((e) => e.kind === "imports").length] as const)
    .filter(([, n]) => n > 0)
    .sort((x, y) => y[1] - x[1])
    .slice(0, 25);
  const fns = g.defs
    .filter((d) => (d.kind === "function" || d.kind === "method") && !test.test(d.file) && !(ix.in.get(d.id) ?? []).length)
    .map((d) => [d, (ix.out.get(d.id) ?? []).filter((e) => e.kind === "calls").length] as const)
    .filter(([, n]) => n >= 3)
    .sort((x, y) => y[1] - x[1])
    .slice(0, 25);
  return `Files nothing imports (imports they make):\n${roots.map(([f, n]) => `  ${f} (${n})`).join("\n") || "  none"}\nFunctions nothing calls (calls they make):\n${fns.map(([d, n]) => `  ${d.id}  ${d.file}:${d.start}-${d.end} (${n})`).join("\n") || "  none"}`;
}

/** Runs one graph tool call; the answer is the text the agent reads. */
export function graphTool(g: Graph, call: { name: string; input: Record<string, unknown> | undefined }): string {
  const ix = index(g);
  const i = call.input ?? {};
  switch (call.name) {
    case "graph_find": return find(g, ix, String(i.name ?? ""));
    case "graph_file": return outline(g, ix, String(i.path ?? ""));
    case "graph_show": return show(g, ix, String(i.name ?? ""));
    case "graph_links": return links(g, ix, (Array.isArray(i.from) ? i.from : [i.from]).filter(Boolean).map(String), (Array.isArray(i.to) ? i.to : [i.to]).filter(Boolean).map(String));
    case "graph_callers": return neighbours(g, ix, String(i.name ?? ""), "in");
    case "graph_callees": return neighbours(g, ix, String(i.name ?? ""), "out");
    case "graph_path": return path(g, ix, String(i.from ?? ""), String(i.to ?? ""));
    case "graph_entrypoints": return entrypoints(g, ix);
    default: return `No tool called ${call.name}.`;
  }
}
export const isGraphTool = (name: string) => GRAPH_TOOLS.some((t) => t.name === name);

/** A definition's signature on one line, decorators kept: what a brief lists in place of its bare name. */
export function signature(d: Def, max = 160): string {
  const s = (d.head ?? "").replace(/\s+/g, " ").replace(/\s*[{:]\s*$/, "").trim();
  if (!s) return `${d.name} (${d.kind})`;
  return s.length > max ? `${s.slice(0, max - 1)}…` : s;
}

/**
 * The calls a root's brief carries, so its author draws arrows without asking
 * graph_links for each pair: every call from one of its files into another,
 * and every call across its boundary, grouped by file pair, each with the line
 * to cite. `ownerOf` names the root that explains a file outside it.
 */
export function briefCalls(g: Graph, mine: string[], ownerOf: (file: string) => string, budget = 40_000): { inside: string; across: string } {
  const ix = index(g);
  const own = new Set(mine);
  const pairs = new Map<string, Edge[]>();
  for (const e of g.edges) {
    if (e.kind === "imports") continue;
    const a = fileOf(ix, e.from), b = fileOf(ix, e.to);
    if (a === b || (!own.has(a) && !own.has(b))) continue;
    const k = `${a}\n${b}`;
    pairs.set(k, [...(pairs.get(k) ?? []), e]);
  }
  const name = (id: string) => (ix.byId.has(id) ? qual(ix.byId.get(id)!) : "(top level)");
  const PER_PAIR = 6;
  const render = (keys: string[], tag: (a: string, b: string) => string) => {
    const out: string[] = [];
    let size = 0, cut = 0;
    for (const k of keys) {
      const [a, b] = k.split("\n");
      const es = [...pairs.get(k)!].sort((x, y) => Number(y.how === "extracted") - Number(x.how === "extracted") || y.lines.length - x.lines.length);
      const block = [`${tag(a, b)}`, ...es.slice(0, PER_PAIR).map((e) => `  ${name(e.from)} —${e.kind}→ ${name(e.to)}${e.lines.length ? ` at ${lines(ix, e)}` : ""}${e.how === "inferred" ? " [inferred]" : ""}`), ...(es.length > PER_PAIR ? [`  … ${es.length - PER_PAIR} more (graph_links)`] : [])].join("\n");
      if (size + block.length > budget) { cut++; continue; }
      out.push(block);
      size += block.length + 1;
    }
    return out.join("\n") + (cut ? `\n… ${cut} more file pairs left out for length; graph_links has them` : "");
  };
  const byCount = (ks: string[]) => ks.sort((x, y) => pairs.get(y)!.length - pairs.get(x)!.length || x.localeCompare(y));
  const keys = [...pairs.keys()];
  const insideKeys = byCount(keys.filter((k) => k.split("\n").every((f) => own.has(f))));
  const acrossKeys = byCount(keys.filter((k) => !k.split("\n").every((f) => own.has(f))));
  const who = (f: string) => (own.has(f) ? f : `${f}${ownerOf(f) ? ` (${ownerOf(f)})` : ""}`);
  return {
    inside: insideKeys.length ? render(insideKeys, (a, b) => `${a} → ${b}`) : "",
    across: acrossKeys.length ? render(acrossKeys, (a, b) => `${who(a)} → ${who(b)}`) : "",
  };
}

/** A definition named the way an author names one: its id, a Class.method, or a name only one thing has. Null when none or several match. */
export function resolveDef(g: Graph, raw: string): Def | null {
  const ix = index(g);
  const r = resolveName(g, ix, raw);
  return "id" in r ? (ix.byId.get(r.id) ?? null) : null;
}

app/scripts/generate/graph.mts:
// usage (from app/): npx -y tsx --tsconfig tsconfig.json scripts/generate/graph.mts <repo dir> [--out graph.json] [--ask "<tool> <arg>"]
//   Builds the repository's fact graph (graph.ts) and prints its size: definitions, edges by kind and
//   how sure, and how many calls it resolved. --out writes it; --ask runs one graph tool, as an agent would.
import { writeFileSync } from "node:fs";
import { parseArgs } from "./args";
import { buildGraph } from "./graph";
import { graphTool } from "./graph-tools";
import { inventory } from "./inventory";

const { repo, opt } = parseArgs(process.argv.slice(2));
const inv = inventory(repo ?? ".");
const g = await buildGraph(inv);
const count = (k: string, h: string) => g.edges.filter((e) => e.kind === k && e.how === h).length;
console.log(`${inv.name} @ ${g.commit}: ${g.stats.parsed}/${g.stats.files} code files parsed in ${g.stats.ms} ms`);
console.log(`  ${g.defs.length} definitions`);
for (const k of ["calls", "inherits", "imports"]) console.log(`  ${k}: ${count(k, "extracted")} extracted, ${count(k, "inferred")} inferred`);
console.log(`  calls: ${g.stats.resolved} of ${g.stats.calls} call sites resolved, ${g.stats.ambiguous} left out as ambiguous, ${g.stats.mentions ?? 0} found by name in files with no grammar`);
if (opt("--out")) writeFileSync(opt("--out")!, JSON.stringify(g) + "\n");
const q = opt("--ask");
if (q) {
  const [name, ...rest] = q.split(" ");
  if (name === "links") { const [a, b] = rest.join(" ").split(" -> "); console.log("\n" + graphTool(g, { name: "graph_links", input: { from: a.split(","), to: b.split(",") } })); process.exit(0); }
  const arg = rest.join(" ");
  console.log("\n" + graphTool(g, { name: `graph_${name}`, input: name === "path" ? { from: arg.split(" ")[0], to: arg.split(" ")[1] } : name === "file" ? { path: arg } : name === "entrypoints" ? {} : { name: arg } }));
}

app/scripts/generate/graph.ts:
/**
 * The fact graph: every function, method and class in the repository, and who
 * calls, inherits from and imports whom, read from the code with no model.
 *
 * One generic path for every language: tree-sitter parses the file with that
 * language's grammar (tree-sitter-wasms, prebuilt, no native build) and the
 * language's tags query (tags/<lang>.scm, the grammars' own tags.scm with
 * inheritance added) names its definitions and calls in the same words
 * everywhere. Nothing here knows Python from Go.
 *
 * What is language-specific is which definition a call means, and that is
 * resolved by name, never by type: a bare call to a name defined once in the
 * same file or a file it imports, or a self/this call to a method of the same
 * class, is `extracted` (the source says it); a call through any other
 * receiver, or to the only definition of a name anywhere, is `inferred`; a
 * name with several candidates is left out and counted, not guessed.
 */
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { extname, join } from "node:path";
import { Language, Parser, Query, type Node as SyntaxNode } from "web-tree-sitter";
import { langOf } from "./imports";
import type { Inventory } from "./inventory";

export interface Def {
  /** `path#Outer.inner`; `@line` is added when the same name is defined twice at one level. */
  id: string;
  name: string;
  kind: string;
  file: string;
  start: number;
  end: number;
  /** The definition this one sits in, if any. */
  parent?: string;
  /** Its decorators and signature as written: `@app.route("/login")\ndef login(form):`. */
  head?: string;
  /** Its doc comment or docstring, trimmed. */
  doc?: string;
  /** What it does, in one line: the summarize stage's reading of it (withSummaries). */
  does?: string;
}
export interface Edge {
  /** A def id, or a file path for code at a file's top level (and for every import). */
  from: string;
  to: string;
  kind: "calls" | "inherits" | "imports";
  how: "extracted" | "inferred";
  /** Lines in `from`'s file where it happens; empty for imports. */
  lines: number[];
}
export interface Graph {
  commit: string;
  /** Every file the graph parsed: only in these can it say what a line calls. */
  files: string[];
  /** What each file is for, from the summarize stage (withSummaries). */
  about?: Record<string, string>;
  defs: Def[];
  edges: Edge[];
  /** Files parsed, calls left out because their name had several candidates, links found by name in files with no grammar, and how long the build took. */
  stats: { files: number; parsed: number; calls: number; resolved: number; ambiguous: number; mentions?: number; ms: number };
}

/** Which grammar and which tags query each extension reads with. */
const GRAMMAR: Record<string, [wasm: string, tags: string]> = {
  ".ts": ["typescript", "typescript"], ".mts": ["typescript", "typescript"], ".cts": ["typescript", "typescript"], ".tsx": ["tsx", "typescript"],
  ".js": ["javascript", "javascript"], ".jsx": ["javascript", "javascript"], ".mjs": ["javascript", "javascript"], ".cjs": ["javascript", "javascript"],
  ".py": ["python", "python"],
  ".java": ["java", "java"], ".kt": ["kotlin", "kotlin"], ".scala": ["scala", "scala"],
  ".go": ["go", "go"],
  ".rs": ["rust", "rust"],
  ".cs": ["c_sharp", "c_sharp"],
  ".php": ["php", "php"],
  ".rb": ["ruby", "ruby"],
  ".c": ["c", "c"], ".h": ["cpp", "cpp"], ".cc": ["cpp", "cpp"], ".cpp": ["cpp", "cpp"], ".cxx": ["cpp", "cpp"], ".hpp": ["cpp", "cpp"], ".hh": ["cpp", "cpp"],
  ".swift": ["swift", "swift"],
  ".dart": ["dart", "dart"],
  ".ex": ["elixir", "elixir"], ".exs": ["elixir", "elixir"],
};
/** Definition kinds that are parts of the code; constants, variables and fields are not. */
const KINDS = new Set(["function", "method", "class", "interface", "module", "type", "struct", "trait", "enum", "object", "macro", "implementation"]);
const CLASSY = new Set(["class", "interface", "struct", "trait", "enum", "object", "type", "module", "implementation"]);
/** Receivers that mean the enclosing class. */
const SELF = new Set(["self", "this", "cls", "super", "Self", "@"]);
/**
 * Method names every language's built-in containers, strings and promises
 * have. Through a receiver of unknown type they are not resolved to a repo
 * method of the same name (Flask's `options.get(...)` is a dict, not
 * `Scaffold.get`), unless an earlier call showed the receiver's class.
 */
const GENERIC = new Set([
  "get", "set", "has", "add", "delete", "remove", "clear", "keys", "values", "items", "entries", "update", "append", "extend", "insert", "copy",
  "join", "split", "format", "replace", "strip", "trim", "lower", "upper", "startswith", "endswith", "startsWith", "endsWith", "includes", "indexOf",
  "map", "filter", "reduce", "forEach", "find", "some", "every", "sort", "slice", "splice", "concat", "then", "catch", "finally", "toString", "valueOf",
  "length", "size", "count", "index", "len", "pop", "setdefault", "discard", "print", "Add", "Get", "Set", "String", "Error", "close", "read", "write", "next", "call", "apply", "bind", "emit", "on",
]);
/** Languages whose file edges imports.ts reads from a parsed import statement; the rest are matched by name. */
const PARSED_IMPORTS = new Set(["ts", "python", "rust", "c", "dart", "ruby", "php"]);

let ready: Promise<void> | null = null;
const languages = new Map<string, Promise<Language>>();
const queries = new Map<string, Query>();
const req = createRequire(join(process.cwd(), "package.json"));

function language(name: string): Promise<Language> {
  if (!languages.has(name)) languages.set(name, Language.load(req.resolve(`tree-sitter-wasms/out/tree-sitter-${name}.wasm`)));
  return languages.get(name)!;
}
/** Grammars that parse JSX: their tags query also reads a component used in markup as a call to it (tags/jsx.scm). */
const JSX = new Set(["tsx", "javascript"]);
const tagsOf = (name: string) => readFileSync(join(process.cwd(), "scripts/generate/tags", `${name}.scm`), "utf8");
function query(lang: Language, wasm: string, tags: string): Query {
  const key = `${wasm}:${tags}`;
  if (!queries.has(key)) queries.set(key, new Query(lang, tagsOf(tags) + (JSX.has(wasm) ? `\n${tagsOf("jsx")}` : "")));
  return queries.get(key)!;
}

interface Raw { name: string; kind: string; startIndex: number; endIndex: number; start: number; end: number; nameIndex: number }
interface Ref { name: string; index: number; line: number; receiver: string | null; kind: "call" | "inherits" }

/** The token before a call's name, when the name is reached through one (`x.go()`, `$this->go()`, `Mod::go()`). */
function receiverOf(text: string, index: number): string | null {
  const before = text.slice(Math.max(0, index - 200), index);
  if (!/(\?\.|\.|->|::)\s*$/.test(before)) return null;
  const m = /([@$]?[A-Za-z_][\w]*|\)|\]|")\s*(\?\.|\.|->|::)\s*$/.exec(before);
  if (!m) return "?";
  return m[1].replace(/^\$/, "");
}

/** Definitions and references of one file, from its grammar's tags query. */
function read(parser: Parser, q: Query, text: string, wasm: string): { defs: Raw[]; refs: Ref[] } {
  const tree = parser.parse(text);
  if (!tree) return { defs: [], refs: [] };
  const defs: Raw[] = [];
  const refs: Ref[] = [];
  try {
    for (const m of q.matches(tree.rootNode)) {
      const name = m.captures.find((c) => c.name === "name")?.node;
      const outer = m.captures.find((c) => c.name.startsWith("definition.") || c.name.startsWith("reference."));
      if (!name || !outer) continue;
      const [role, kind] = outer.name.split(".");
      if (role === "definition") {
        if (!KINDS.has(kind)) continue;
        let node: SyntaxNode = outer.node;
        // Dart keeps a function's body beside its signature, not inside it.
        if (wasm === "dart" && node.nextNamedSibling?.type === "function_body") node = node.nextNamedSibling;
        defs.push({ name: name.text, kind, startIndex: outer.node.startIndex, endIndex: node.endIndex, start: outer.node.startPosition.row + 1, end: node.endPosition.row + 1, nameIndex: name.startIndex });
      } else if (kind === "call" || kind === "inherits") {
        refs.push({ name: name.text, index: name.startIndex, line: name.startPosition.row + 1, receiver: kind === "call" ? receiverOf(text, name.startIndex) : null, kind });
      }
    }
  } finally {
    tree.delete();
  }
  return { defs, refs };
}

/** Same name at the same level twice (overloads, if/else definitions): the later ones get their line. */
function nest(file: string, raws: Raw[]): { defs: Def[]; spans: (Def & { a: number; b: number })[] } {
  const sorted = [...raws].sort((x, y) => x.startIndex - y.startIndex || y.endIndex - x.endIndex);
  const seen = new Set<string>();
  const stack: (Def & { a: number; b: number })[] = [];
  const out: (Def & { a: number; b: number })[] = [];
  const taken = new Set<string>();
  for (const r of sorted) {
    const k = `${r.startIndex}:${r.nameIndex}`;
    if (seen.has(k)) continue;
    seen.add(k);
    while (stack.length && stack[stack.length - 1].b < r.endIndex) stack.pop();
    const parent = stack[stack.length - 1];
    const qual = parent ? `${parent.id.slice(parent.id.indexOf("#") + 1)}.${r.name}` : r.name;
    let id = `${file}#${qual}`;
    if (taken.has(id)) id = `${id}@${r.start}`;
    taken.add(id);
    const kind = r.kind === "function" && parent && CLASSY.has(parent.kind) ? "method" : r.kind;
    const d = { id, name: r.name, kind, file, start: r.start, end: r.end, ...(parent ? { parent: parent.id } : {}), a: r.startIndex, b: r.endIndex };
    out.push(d);
    stack.push(d);
  }
  return { defs: out.map((d) => { const { a, b, ...def } = d; void a; void b; return def; }), spans: out };
}

/** The innermost definition holding a position. */
function within(spans: { a: number; b: number; id: string }[], index: number): string | null {
  let best: { a: number; b: number; id: string } | null = null;
  for (const s of spans) if (s.a <= index && index < s.b && (!best || s.b - s.a < best.b - best.a)) best = s;
  return best?.id ?? null;
}

/** A module's name as code calls it: `src/file_utils.rs` → file_utils, `pkg/helpers/__init__.py` → helpers. */
function stem(path: string): string {
  const parts = path.split("/");
  const base = parts.pop()!.replace(/\.[^.]+$/, "");
  return /^(mod|__init__|index|lib)$/.test(base) ? parts.pop() ?? base : base;
}

/** Whether a function's parameter list names `name`: the text from its own name to the end of its signature. */
function shadows(def: string, own: string, name: string): boolean {
  const at = def.indexOf(own);
  if (at < 0) return false;
  const sig = def.slice(at + own.length, at + own.length + 600);
  const end = sig.search(/\)\s*(:|\{|->|=>|\bwhere\b|\bthrows\b|\bdo\b|$)/m);
  return new RegExp(`\\b${name.replace(/[$]/g, "\\$")}\\b`).test(end < 0 ? sig.split("\n")[0] : sig.slice(0, end));
}

/** Lines that annotate the definition below them: `@decorator`, `#[attr]`, `[Attribute]`. */
const ANNOTATION = /^\s*(@[\w.]+|#\[|\[[A-Z]\w*[\](])/;
/** Lines of comment, in any of the languages read. */
const COMMENT = /^\s*(\/\/\/?|#(?!\[)|\/\*\*?|\*(?!\/)|\*\/|--|%)/;
const HEAD_LINES = 4;
const DOC_CHARS = 400;

/**
 * A definition's header and doc, read from the lines around it with no
 * grammar: the annotations just above it and its first lines up to where its
 * body opens; the comment just above it, or a docstring just inside.
 */
function describe(lines: string[], start: number, end: number): { head?: string; doc?: string } {
  let top = start - 1;
  while (top > 0 && ANNOTATION.test(lines[top - 1])) top--;
  const sig: string[] = [];
  for (let i = start - 1; i < Math.min(end, start - 1 + HEAD_LINES); i++) {
    sig.push(lines[i].trimEnd());
    if (/(\{|:|=>|\bdo|=)\s*$/.test(lines[i]) || /\{\s*\S/.test(lines[i])) break;
  }
  const head = [...lines.slice(top, start - 1).map((l) => l.trim()), ...sig.map((l, i) => (i ? l.trim() : l.trim()))].join("\n").slice(0, 300);
  // A comment just above (past any annotations), nearest line last.
  const above: string[] = [];
  for (let i = top - 1; i >= 0 && COMMENT.test(lines[i]) && above.length < 12; i--) above.unshift(lines[i]);
  let doc = above.map((l) => l.replace(/^\s*(\/\/\/?|#|\/\*\*?|\*\/?|--|%)\s?/, "").replace(/\*\/\s*$/, "").trim()).filter(Boolean).join(" ");
  // Else a docstring just inside: Python's """...""", Elixir's @doc """...""".
  if (!doc) {
    const after = lines.slice(start - 1 + sig.length, Math.min(end, start - 1 + sig.length + 15)).join("\n");
    // A long one need not close within the lines looked at: its opening is what the reader needs.
    const m = /^\s*(?:@(?:module)?doc\s+)?[rRuUbB]?("""|\'\'\')([\s\S]*?)(?:\1|$)|^\s*(?:@(?:module)?doc\s+)?"([^"\n]*)"/.exec(after);
    if (m) doc = (m[2] ?? m[3] ?? "").replace(/\s+/g, " ").trim();
  }
  return { ...(head ? { head } : {}), ...(doc ? { doc: doc.slice(0, DOC_CHARS) } : {}) };
}

/** Lines that bring names in rather than use them, in any language: `import`, `from x import`, `use`, `#include`, `require(...)`. */
const IMPORT_LINE = /^\s*(import\b|from\s+\S+\s+import\b|export\s+(\*|\{[^}]*\})\s+from\b|use\s+[\w:]|#include\b|(const|let|var)\s+[\w{},\s]+=\s*require\()/;

/**
 * Which lines of a file only import: IMPORT_LINE, and the lines a JavaScript
 * `import {` spans until its `from`. Names on them are not uses.
 */
function importLines(lines: string[]): boolean[] {
  const out: boolean[] = [];
  let open = false;
  for (const l of lines) {
    const starts = IMPORT_LINE.test(l);
    out.push(open || starts);
    if (starts && /^\s*import\b/.test(l) && !/\bfrom\b|["'];?\s*$/.test(l)) open = true;
    else if (open && /\bfrom\b/.test(l)) open = false;
  }
  return out;
}

/** The names code calls a file by: `image-zoom.astro` → image_zoom, imageZoom, ImageZoom; `base.astro` → Base. */
function namesOfFile(path: string): string[] {
  const base = stem(path);
  const words = base.split(/[-_.\s]+/).filter(Boolean);
  if (!words.length) return [];
  const pascal = words.map((w) => w[0].toUpperCase() + w.slice(1)).join("");
  // A plain lowercase word (`base`, `article`) is as likely prose as a use; only its other spellings count.
  return [...new Set([base, words.join("_"), pascal[0].toLowerCase() + pascal.slice(1), pascal])].filter((n) => /^[A-Za-z_$][\w$]*$/.test(n) && n.length >= 3 && !/^[a-z]+$/.test(n));
}

const escape = (s: string) => s.replace(/[$]/g, "\\$");

/**
 * Lays the summarize stage's reading onto the graph: what each file is for,
 * and what each symbol it named does, onto the definition of that name whose
 * lines it spans. The only words in the graph a model wrote.
 */
export function withSummaries(g: Graph, sums: Record<string, { purpose: string; symbols: { name: string; start: number; end: number; does: string }[] }>): Graph {
  g.about = {};
  const byFile = new Map<string, Def[]>();
  for (const d of g.defs) byFile.set(d.file, [...(byFile.get(d.file) ?? []), d]);
  for (const [path, s] of Object.entries(sums)) {
    if (s.purpose && !s.purpose.startsWith("(not summarised")) g.about[path] = s.purpose;
    for (const sym of s.symbols ?? []) {
      const short = sym.name.split(/[.:#\s(]/).filter(Boolean).pop() ?? sym.name;
      const cands = (byFile.get(path) ?? []).filter((d) => d.name === short || d.name === sym.name);
      const d = cands.find((x) => x.start <= sym.end && sym.start <= x.end) ?? (cands.length === 1 ? cands[0] : undefined);
      if (d && sym.does && !d.does) d.does = sym.does;
    }
  }
  return g;
}

/**
 * The text of each code file the graph found no grammar for, so graph_file
 * can show its numbered lines: there is no other way for an author to see a
 * line in it. Kept beside the graph, not in graph.json.
 */
const unparsedText = new WeakMap<Graph, Map<string, string>>();
export const unparsedSource = (g: Graph, path: string) => unparsedText.get(g)?.get(path) ?? null;

let active: Graph | null = null;
/** The graph this run draws from: authors' graph tools answer from it, and the checker proves arrows against it. */
export function setGraph(g: Graph | null) {
  active = g;
}
export const activeGraph = () => active;

const cache = new Map<string, Promise<Graph>>();

/** The repository's fact graph; built once per inventory. */
export function buildGraph(inv: Inventory): Promise<Graph> {
  const key = `${inv.repo}@${inv.commit}:${inv.files.filter((f) => f.code).map((f) => f.hash).join("")}`;
  if (!cache.has(key)) cache.set(key, compile(inv));
  return cache.get(key)!;
}

async function compile(inv: Inventory): Promise<Graph> {
  const t0 = Date.now();
  ready ??= Parser.init();
  await ready;
  const code = inv.files.filter((f) => f.code);
  // Every grammar is loaded before a parser exists: loading one while a parser is alive took 4-5 s each (saas-starter).
  await Promise.all([...new Set(code.map((f) => GRAMMAR[extname(f.path).toLowerCase()]?.[0]).filter(Boolean))].map((l) => language(l!)));
  const parser = new Parser();
  const defs: Def[] = [];
  const perFile = new Map<string, { spans: (Def & { a: number; b: number })[]; refs: Ref[]; text: string }>();
  const tests = new Set(code.filter((f) => f.test).map((f) => f.path));
  let parsed = 0;
  const parsedFiles: string[] = [];
  const unparsed = new Map<string, string>();
  for (const f of code) {
    const g = GRAMMAR[extname(f.path).toLowerCase()];
    if (!g) {
      try {
        unparsed.set(f.path, readFileSync(join(inv.repo, f.path), "utf8"));
      } catch {
        /* unreadable: left out, as a parsed file would be */
      }
      continue;
    }
    let text: string;
    try {
      text = readFileSync(join(inv.repo, f.path), "utf8");
    } catch {
      continue;
    }
    const lang = await language(g[0]);
    parser.setLanguage(lang);
    const { defs: raws, refs } = read(parser, query(lang, g[0], g[1]), text, g[0]);
    const { defs: mine, spans } = nest(f.path, raws);
    const lines = text.split("\n");
    for (const d of mine) Object.assign(d, describe(lines, d.start, d.end));
    defs.push(...mine);
    parsedFiles.push(f.path);
    // A definition's own name is not a call to it (Elixir's `def run(x)` is a call node).
    const named = new Set(raws.map((r) => r.nameIndex));
    perFile.set(f.path, { spans, refs: refs.filter((r) => !named.has(r.index)), text });
    parsed++;
  }
  parser.delete();

  const byName = new Map<string, Def[]>();
  for (const d of defs) byName.set(d.name, [...(byName.get(d.name) ?? []), d]);
  const byId = new Map(defs.map((d) => [d.id, d]));
  const classOf = (id: string | null): Def | null => {
    for (let d = id ? byId.get(id) : undefined; d; d = d.parent ? byId.get(d.parent) : undefined) if (CLASSY.has(d.kind)) return d;
    return null;
  };

  const edges = new Map<string, Edge>();
  const add = (from: string, to: string, kind: Edge["kind"], how: Edge["how"], line?: number) => {
    if (from === to) return;
    const k = `${from}\u0000${to}\u0000${kind}`;
    const e = edges.get(k) ?? { from, to, kind, how, lines: [] };
    if (how === "extracted") e.how = "extracted";
    if (line && !e.lines.includes(line)) e.lines.push(line);
    edges.set(k, e);
  };

  // Inheritance first, so a self call can look in the class's parents.
  const parents = new Map<string, Def[]>();
  for (const [file, { spans, refs }] of perFile) {
    const near = new Set([file, ...(inv.imports[file] ?? [])]);
    for (const r of refs.filter((x) => x.kind === "inherits")) {
      const owner = classOf(within(spans, r.index));
      if (!owner) continue;
      const cands = (byName.get(r.name) ?? []).filter((d) => CLASSY.has(d.kind) && d.id !== owner.id);
      const local = cands.filter((d) => near.has(d.file));
      const pick = local.length === 1 ? local[0] : !local.length && cands.length === 1 ? cands[0] : null;
      if (!pick) continue;
      add(owner.id, pick.id, "inherits", local.length === 1 ? "extracted" : "inferred", r.line);
      parents.set(owner.id, [...(parents.get(owner.id) ?? []), pick]);
    }
  }

  let calls = 0;
  let resolved = 0;
  let ambiguous = 0;
  /** Which class a receiver turned out to be, per function: `from \0 receiver` → class id. */
  const seenOn = new Map<string, string>();
  for (const [file, { spans, refs, text }] of perFile) {
    const near = new Set([file, ...(inv.imports[file] ?? [])]);
    for (const r of refs.filter((x) => x.kind === "call")) {
      calls++;
      const from = within(spans, r.index) ?? file;
      // Code that ships never calls into a test file.
      const all = (byName.get(r.name) ?? []).filter((d) => tests.has(file) || !tests.has(d.file));
      if (!all.length) continue;
      let pick: Def | null = null;
      let how: Edge["how"] = "inferred";
      if (r.receiver && SELF.has(r.receiver)) {
        // self.x(): a method of this class, or of a class it inherits from.
        const cls = classOf(from);
        const lineage = cls ? [cls, ...(parents.get(cls.id) ?? [])] : [];
        for (const c of lineage) {
          const m = all.filter((d) => d.parent === c.id);
          if (m.length === 1) {
            pick = m[0];
            how = c === cls ? "extracted" : "inferred";
            break;
          }
        }
      } else if (r.receiver && /^[A-Z]/.test(r.receiver)) {
        // Mod.x() / Class.x(): a definition inside something of that name.
        const m = all.filter((d) => d.parent && byId.get(d.parent)?.name.split(".").pop() === r.receiver);
        if (m.length === 1) pick = m[0];
        else if (m.length > 1) ambiguous++;
      } else if (r.receiver) {
        // x.y(): the type of x is unknown, so only a single candidate nearby will do,
        // unless an earlier call on x in this function already showed which class x is.
        // A receiver named like a file it can reach is that module: `file_utils::f()`, `helpers.f()`.
        const mod = all.filter((d) => !d.parent && near.has(d.file) && d.file !== file && stem(d.file) === r.receiver);
        const m = mod.length ? mod : all.filter((d) => near.has(d.file) && d.parent);
        const known = seenOn.get(`${from}\u0000${r.receiver}`);
        if (!mod.length && GENERIC.has(r.name) && !known) {
          // dict.get(), list.append(), promise.then(): far likelier a built-in than the one repo method of that name.
          if (m.length) ambiguous++;
        } else if (m.length === 1) {
          pick = m[0];
          if (m[0].parent) seenOn.set(`${from}\u0000${r.receiver}`, m[0].parent);
        } else if (m.length > 1) {
          const cls = seenOn.get(`${from}\u0000${r.receiver}`);
          const same = cls ? m.filter((d) => d.parent === cls) : [];
          if (same.length === 1) pick = same[0];
          else ambiguous++;
        }
      } else {
        // y(): what this file defines or imports at the top level, else the only one anywhere.
        // Top-level definitions, and functions nested in one that encloses this call (closures).
        const enclosing = new Set<string>();
        for (let id: string | undefined = from; id && byId.has(id); id = byId.get(id)!.parent) enclosing.add(id);
        const top = all.filter((d) => !d.parent || enclosing.has(d.parent));
        // A parameter of the same name shadows them all: `def from_file(self, filename, load)` then `load(f)`.
        const own = spans.find((s) => s.id === from);
        if (own && top.every((d) => d.id !== own.id && d.parent !== own.id) && shadows(text.slice(own.a, own.b), own.name, r.name)) continue;
        const here = top.filter((d) => d.file === file);
        const imported = top.filter((d) => near.has(d.file));
        if (here.length === 1) [pick, how] = [here[0], "extracted"];
        else if (!here.length && imported.length === 1) [pick, how] = [imported[0], "extracted"];
        else if (!imported.length && top.length === 1) pick = top[0];
        else if (here.length > 1 || imported.length > 1 || top.length > 1) ambiguous++;
      }
      if (!pick) continue;
      resolved++;
      add(from, pick.id, "calls", how, r.line);
    }
  }

  // Mentions. A file with no grammar (an Astro page, a Vue or Svelte
  // component, a language not listed) is still read: each name of a thing it
  // imports, used on a line that is not an import, is a link from it on that
  // line — and so is any file's use of a grammarless file it imports, by the
  // names code calls that file (<Base> for base.astro). Matched by name, not
  // parsed, so every such link is `inferred`.
  let mentions = 0;
  for (const f of code) {
    const text = unparsed.get(f.path) ?? perFile.get(f.path)?.text;
    if (text === undefined) continue;
    const near = (inv.imports[f.path] ?? []).filter((p) => p !== f.path);
    const targets = new Map<string, Set<string>>();
    const want = (name: string, to: string) => {
      if (GENERIC.has(name)) return;
      targets.set(name, (targets.get(name) ?? new Set()).add(to));
    };
    if (unparsed.has(f.path)) for (const d of defs) if (!d.parent && near.includes(d.file) && d.name.length >= 2) want(d.name, d.id);
    for (const p of near) if (unparsed.has(p)) for (const n of namesOfFile(p)) want(n, p);
    if (!targets.size) continue;
    const spans = perFile.get(f.path)?.spans ?? [];
    const lines = text.split("\n");
    const skip = importLines(lines);
    const pattern = new RegExp(`(?<![\\w$.])(${[...targets.keys()].sort((a, b) => b.length - a.length).map(escape).join("|")})(?![\\w$])`, "g");
    let offset = 0;
    for (let i = 0; i < lines.length; offset += lines[i].length + 1, i++) {
      if (skip[i] || COMMENT.test(lines[i])) continue;
      for (const m of lines[i].matchAll(pattern)) {
        const tos = targets.get(m[1])!;
        // A name two imported things share is left out, as an ambiguous call is.
        if (tos.size !== 1) continue;
        const from = within(spans, offset + m.index!) ?? f.path;
        add(from, [...tos][0], "calls", "inferred", i + 1);
        mentions++;
      }
    }
  }

  for (const [a, bs] of Object.entries(inv.imports)) {
    const lang = langOf(a);
    for (const b of bs) add(a, b, "imports", lang && PARSED_IMPORTS.has(lang) ? "extracted" : "inferred");
  }

  const graph: Graph = {
    commit: inv.commit,
    files: parsedFiles,
    defs,
    edges: [...edges.values()],
    stats: { files: code.length, parsed, calls, resolved, ambiguous, mentions, ms: Date.now() - t0 },
  };
  unparsedText.set(graph, unparsed);
  return graph;
}

app/scripts/generate/imports.ts:
/**
 * Which file of the repository uses which, read from the code with no model.
 *
 * Each language's import statements are resolved to files the repository
 * holds: TS/JS through tsconfig paths, Python through its packages, Go
 * through go.mod, Rust through its module tree, Java/Kotlin/Scala, C#, PHP
 * and Elixir through the names files declare, Ruby through require and its
 * constants, C/C++ through #include, Dart through pubspec. Where a language
 * lets a file use another's names with no import at all (a Java package, a Go
 * package, a C# namespace, a Swift module), an edge is a declared type or
 * top-level name of the one file used as a word in the other.
 *
 * An import of anything outside the repository is not an edge: a package is
 * not a part of the bluprint. Parsed imports are precise (D2 measured 98–100% for
 * TS/JS); the name edges are what `PRECISION` is sampled for.
 */
import { readFileSync } from "node:fs";
import { basename, extname, join, posix } from "node:path";
import ts from "typescript";

export type Lang = "ts" | "python" | "jvm" | "go" | "rust" | "csharp" | "php" | "ruby" | "c" | "swift" | "dart" | "elixir";

const EXT: Record<string, Lang> = {
  ".ts": "ts", ".tsx": "ts", ".mts": "ts", ".cts": "ts", ".js": "ts", ".jsx": "ts", ".mjs": "ts", ".cjs": "ts", ".vue": "ts", ".svelte": "ts", ".astro": "ts",
  ".py": "python",
  ".java": "jvm", ".kt": "jvm", ".scala": "jvm",
  ".go": "go",
  ".rs": "rust",
  ".cs": "csharp",
  ".php": "php",
  ".rb": "ruby",
  ".c": "c", ".h": "c", ".cc": "c", ".cpp": "c", ".cxx": "c", ".hpp": "c", ".hh": "c", ".m": "c", ".mm": "c",
  ".swift": "swift",
  ".dart": "dart",
  ".ex": "elixir", ".exs": "elixir",
};
export const langOf = (path: string): Lang | null => EXT[extname(path).toLowerCase()] ?? null;

type Edges = Map<string, Set<string>>;
const dir = (p: string) => posix.dirname(p) === "." ? "" : posix.dirname(p);
const join2 = (a: string, b: string) => posix.normalize(a ? `${a}/${b}` : b).replace(/^\.\//, "");
const words = (s: string) => new Set(s.match(/[A-Za-z_]\w*/g) ?? []);

/** Comments blanked out, newlines kept, so a commented-out import or a name in a doc comment is not an edge. */
function uncommented(text: string, lang: Lang): string {
  const blank = (m: string) => m.replace(/[^\n]/g, " ");
  if (lang === "python" || lang === "ruby" || lang === "elixir") return text.replace(/#[^\n]*/g, blank);
  let out = text.replace(/\/\*[\s\S]*?\*\//g, blank).replace(/(^|[^:"'\\])\/\/[^\n]*/g, (m, pre: string) => pre + blank(m.slice(pre.length)));
  if (lang === "php") out = out.replace(/(^|\s)#[^\n[]*/g, blank);
  return out;
}

/* ── TS / JS ─────────────────────────────────────────────── */

/** `@/x` style aliases from every tsconfig, as prefix → directory. */
function aliases(repo: string, listed: string[]): [string, string][] {
  const out: [string, string][] = [];
  for (const f of listed.filter((x) => /(^|\/)tsconfig[^/]*\.json$/.test(x))) {
    const cfg = ts.readConfigFile(join(repo, f), ts.sys.readFile).config;
    const base = posix.join(posix.dirname(f), cfg?.compilerOptions?.baseUrl ?? ".");
    for (const [k, v] of Object.entries<string[]>(cfg?.compilerOptions?.paths ?? {}))
      if (k.endsWith("/*") && v[0]?.endsWith("/*")) out.push([k.slice(0, -1), posix.normalize(posix.join(base, v[0].slice(0, -1))) + "/"]);
  }
  return out;
}

function resolveTs(from: string, spec: string, known: Set<string>, alias: [string, string][]): string | null {
  let base: string | null = null;
  if (spec.startsWith(".")) base = posix.normalize(posix.join(posix.dirname(from), spec));
  else for (const [prefix, d] of alias) if (spec.startsWith(prefix)) { base = posix.normalize(d + spec.slice(prefix.length)); break; }
  if (base === null) return null;
  base = base.replace(/^\.\//, "");
  const tries = [base, ...[".ts", ".tsx", ".js", ".jsx", ".mjs", ".vue", ".svelte"].flatMap((e) => [base + e, `${base}/index${e}`])];
  // `./x.js` in TS source names `./x.ts`.
  if (/\.(m?js|jsx)$/.test(base)) tries.push(base.replace(/\.(m?js|jsx)$/, ".ts"), base.replace(/\.(m?js|jsx)$/, ".tsx"));
  return tries.find((t) => known.has(t)) ?? null;
}

function tsGraph(files: string[], text: (p: string) => string, known: Set<string>, alias: [string, string][], add: (a: string, b: string) => void) {
  for (const f of files) {
    let src = text(f);
    // A single-file component's imports are in its <script> blocks; an Astro page's in its front matter.
    if (/\.(vue|svelte)$/.test(f)) src = [...src.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)].map((m) => m[1]).join("\n");
    else if (f.endsWith(".astro")) src = /^---\n([\s\S]*?)\n---/.exec(src)?.[1] ?? "";
    for (const i of ts.preProcessFile(src, true, true).importedFiles) {
      const to = resolveTs(f, i.fileName, known, alias);
      if (to) add(f, to);
    }
  }
}

/* ── Python ──────────────────────────────────────────────── */

function pythonGraph(files: string[], text: (p: string) => string, known: Set<string>, add: (a: string, b: string) => void) {
  // A module's dotted name from the top of its package (the first directory up without an __init__.py), and from the repository's top.
  const byName = new Map<string, string>();
  for (const f of files) {
    const parts = f.replace(/\.py$/, "").split("/");
    if (parts[parts.length - 1] === "__init__") parts.pop();
    let i = parts.length - 1;
    while (i > 0 && known.has(`${parts.slice(0, i).join("/")}/__init__.py`)) i--;
    const fromPackage = parts.slice(i).join(".");
    if (fromPackage && !byName.has(fromPackage)) byName.set(fromPackage, f);
    const fromTop = parts.join(".");
    if (fromTop && !byName.has(fromTop)) byName.set(fromTop, f);
    if (parts[0] === "src" && parts.length > 1 && !byName.has(parts.slice(1).join("."))) byName.set(parts.slice(1).join("."), f);
  }
  const absolute = (name: string) => {
    for (let ps = name.split("."); ps.length; ps.pop()) {
      const hit = byName.get(ps.join("."));
      if (hit) return hit;
    }
    return null;
  };
  const relative = (f: string, dots: number, mod: string) => {
    let base = dir(f);
    for (let i = 1; i < dots; i++) base = dir(base);
    const path = join2(base, mod.replace(/\./g, "/"));
    return [`${path}.py`, `${path}/__init__.py`].find((p) => known.has(p)) ?? null;
  };
  for (const f of files) {
    const src = uncommented(text(f), "python");
    for (const m of src.matchAll(/^[ \t]*import[ \t]+([\w., \t]+)$/gm))
      for (const one of m[1].split(",")) {
        const to = absolute(one.trim().split(/\s+/)[0]);
        if (to) add(f, to);
      }
    for (const m of src.matchAll(/^[ \t]*from[ \t]+(\.*)([\w.]*)[ \t]+import[ \t]+(\([^)]*\)|[^\n]+)/gm)) {
      const dots = m[1].length;
      const names = m[3].replace(/[()\\]/g, " ").split(",").map((x) => x.trim().split(/\s+/)[0]).filter((x) => x && x !== "*");
      const base = dots ? (m[2] ? relative(f, dots, m[2]) : null) : absolute(m[2]);
      let any = false;
      // `from pkg import sub` names a module when there is one by that name.
      for (const n of names) {
        const sub = dots ? relative(f, dots, m[2] ? `${m[2]}.${n}` : n) : byName.get(`${m[2]}.${n}`) ?? null;
        if (sub) { add(f, sub); any = true; }
      }
      if (!any) {
        const to = base ?? (dots ? relative(f, dots, "__init__") : null);
        if (to) add(f, to);
      }
    }
  }
}

/* ── names a file declares, for the languages that resolve by name ───────── */

interface Decl { file: string; scope: string; names: string[] }

/**
 * The types a file declares at its top level: those indented least. A nested
 * type is reached through the one around it, and counting it is wrong: every
 * Kafka request class nests a `Builder`, which made each one "use" the rest.
 */
function topTypes(src: string, keywords: string): string[] {
  const found = [...src.matchAll(new RegExp(`^([ \\t]*)(?:[a-z@]+[ \\t]+)*(?:${keywords})[ \\t]+([A-Z]\\w*)`, "gm"))].map((m) => ({ indent: m[1].replace(/\t/g, "    ").length, name: m[2] }));
  const top = Math.min(...found.map((x) => x.indent));
  return found.filter((x) => x.indent === top).map((x) => x.name);
}

/** Each file's package / namespace / module and the names it declares there. */
function declared(files: string[], text: (p: string) => string, lang: Lang): Decl[] {
  return files.map((f) => {
    const src = uncommented(text(f), lang);
    let scope = "";
    const names = new Set<string>();
    if (lang === "jvm") {
      scope = [...src.matchAll(/^[ \t]*package[ \t]+([\w.]+)/gm)].map((m) => m[1]).join(".");
      topTypes(src, "class|interface|enum|record|object|trait|@interface").forEach((n) => names.add(n));
      if (f.endsWith(".kt")) for (const m of src.matchAll(/^(?:fun|val|var)[ \t]+(?:<[^>]+>[ \t]*)?([a-zA-Z]\w*)/gm)) names.add(m[1]);
      if (/^[A-Z]/.test(basename(f))) names.add(basename(f, extname(f)));
    } else if (lang === "csharp") {
      scope = /^[ \t]*namespace[ \t]+([\w.]+)/m.exec(src)?.[1] ?? "";
      topTypes(src, "class|interface|struct|enum|record").forEach((n) => names.add(n));
    } else if (lang === "php") {
      scope = /^[ \t]*namespace[ \t]+([\w\\]+)/m.exec(src)?.[1] ?? "";
      topTypes(src, "class|interface|trait|enum").forEach((n) => names.add(n));
    } else if (lang === "swift") {
      const target = /(?:^|\/)Sources\/([^/]+)\//.exec(f)?.[1];
      scope = target ?? "";
      topTypes(src, "class|struct|enum|protocol|actor|typealias").forEach((n) => names.add(n));
      for (const m of src.matchAll(/^(?:public |internal |private |fileprivate )?func[ \t]+([a-zA-Z]\w*)/gm)) names.add(m[1]);
    } else if (lang === "go") {
      scope = dir(f);
      for (const m of src.matchAll(/^func[ \t]+([A-Za-z]\w*)/gm)) names.add(m[1]);
      for (const m of src.matchAll(/^(?:type|var|const)[ \t]+([A-Za-z]\w*)/gm)) names.add(m[1]);
      for (const b of src.matchAll(/^(?:type|var|const)[ \t]*\(\n([\s\S]*?)^\)/gm))
        for (const m of b[1].matchAll(/^[ \t]+([A-Za-z]\w*)/gm)) names.add(m[1]);
      names.delete("init");
      names.delete("main");
    }
    return { file: f, scope, names: [...names].filter((n) => n.length >= 3) };
  });
}

/** Edges from each file to those in `scopes` whose declared names it uses as words. */
function byMention(f: string, used: Set<string>, decls: Decl[], add: (a: string, b: string) => void) {
  for (const d of decls) if (d.file !== f && d.names.some((n) => used.has(n))) add(f, d.file);
}

function groupBy(decls: Decl[]) {
  const m = new Map<string, Decl[]>();
  for (const d of decls) m.set(d.scope, [...(m.get(d.scope) ?? []), d]);
  return m;
}

/* ── Java / Kotlin / Scala ───────────────────────────────── */

function jvmGraph(files: string[], text: (p: string) => string, add: (a: string, b: string) => void) {
  const decls = declared(files, text, "jvm");
  const inScope = groupBy(decls);
  const fqn = new Map<string, string>();
  for (const d of decls) for (const n of d.names) if (!fqn.has(`${d.scope}.${n}`)) fqn.set(`${d.scope}.${n}`, d.file);
  for (const d of decls) {
    const src = uncommented(text(d.file), "jvm");
    const body = src.replace(/^[ \t]*(?:package|import)[^\n]*/gm, "");
    const used = words(body);
    for (const m of src.matchAll(/^[ \t]*import[ \t]+(?:static[ \t]+)?([\w.]+?)(\.\*|\._|\.\{([^}]*)\})?(?:[ \t]+as[ \t]+\w+)?[ \t;]*$/gm)) {
      const [, path, wild, braces] = m;
      if (braces !== undefined) {
        for (const one of braces.split(",")) { const to = fqn.get(`${path}.${one.trim().split(/\s/)[0]}`); if (to) add(d.file, to); }
        continue;
      }
      if (wild) { byMention(d.file, used, inScope.get(path) ?? [], add); continue; }
      // `a.b.C`, a nested `a.b.C.Inner`, or a static member `a.b.C.m`: the longest prefix that names a type.
      for (let ps = path.split("."); ps.length > 1; ps.pop()) {
        const to = fqn.get(ps.join("."));
        if (to) { add(d.file, to); break; }
      }
    }
    // A package's own types need no import.
    byMention(d.file, used, inScope.get(d.scope) ?? [], add);
  }
}

/* ── C# ──────────────────────────────────────────────────── */

function csharpGraph(files: string[], text: (p: string) => string, add: (a: string, b: string) => void) {
  const decls = declared(files, text, "csharp");
  const inScope = groupBy(decls);
  const global = new Set<string>();
  const usings = new Map<string, string[]>();
  for (const d of decls) {
    const src = uncommented(text(d.file), "csharp");
    const own: string[] = [];
    for (const m of src.matchAll(/^[ \t]*(global[ \t]+)?using[ \t]+(?:static[ \t]+)?(?:\w+[ \t]*=[ \t]*)?([\w.]+)[ \t]*;/gm)) { if (m[1]) global.add(m[2]); else own.push(m[2]); }
    usings.set(d.file, own);
  }
  for (const d of decls) {
    const used = words(uncommented(text(d.file), "csharp"));
    // Its own namespace and every one enclosing it are in scope, beside what it uses.
    const parents = d.scope.split(".").map((_, i, a) => a.slice(0, i + 1).join("."));
    const spaces = new Set([...parents, ...global, ...(usings.get(d.file) ?? [])]);
    for (const s of spaces) {
      byMention(d.file, used, inScope.get(s) ?? [], add);
      // `using static N.T` and `using X = N.T` name a type, not a namespace.
      const i = s.lastIndexOf(".");
      const t = i > 0 ? (inScope.get(s.slice(0, i)) ?? []).find((x) => x.names.includes(s.slice(i + 1))) : undefined;
      if (t && t.file !== d.file) add(d.file, t.file);
    }
  }
}

/* ── PHP ─────────────────────────────────────────────────── */

function phpGraph(files: string[], text: (p: string) => string, known: Set<string>, add: (a: string, b: string) => void) {
  const decls = declared(files, text, "php");
  const inScope = groupBy(decls);
  const fqn = new Map<string, string>();
  for (const d of decls) for (const n of d.names) fqn.set(`${d.scope}\\${n}`.replace(/^\\/, ""), d.file);
  for (const d of decls) {
    const src = uncommented(text(d.file), "php");
    for (const m of src.matchAll(/^[ \t]*use[ \t]+(?:function[ \t]+|const[ \t]+)?([\w\\]+?)(?:\\\{([^}]*)\})?(?:[ \t]+as[ \t]+\w+)?[ \t]*;/gm)) {
      const names = m[2] !== undefined ? m[2].split(",").map((x) => `${m[1]}\\${x.trim().split(/\s/)[0]}`) : [m[1]];
      for (const n of names) { const to = fqn.get(n.replace(/^\\/, "")); if (to) add(d.file, to); }
    }
    for (const m of src.matchAll(/\b(?:require|include)(?:_once)?[ \t]*\(?[ \t]*(?:__DIR__[ \t]*\.[ \t]*)?['"]([^'"]+\.php)['"]/g)) {
      const to = [join2(dir(d.file), m[1].replace(/^\//, "")), m[1].replace(/^\//, "")].find((p) => known.has(p));
      if (to) add(d.file, to);
    }
    byMention(d.file, words(src.replace(/^[ \t]*(?:namespace|use)[^\n]*/gm, "")), inScope.get(d.scope) ?? [], add);
  }
}

/* ── Go ──────────────────────────────────────────────────── */

function goGraph(files: string[], text: (p: string) => string, listed: string[], repo: string, add: (a: string, b: string) => void) {
  const mods = listed
    .filter((f) => /(^|\/)go\.mod$/.test(f))
    .map((f) => ({ dir: dir(f), path: /^module[ \t]+(\S+)/m.exec(readFileSync(join(repo, f), "utf8"))?.[1] ?? "" }))
    .filter((m) => m.path)
    .sort((a, b) => b.path.length - a.path.length);
  const decls = declared(files, text, "go");
  const inDir = groupBy(decls);
  const pkgName = new Map<string, string>();
  for (const d of decls) if (!pkgName.has(d.scope) && !d.file.endsWith("_test.go")) pkgName.set(d.scope, /^package[ \t]+(\w+)/m.exec(text(d.file))?.[1] ?? basename(d.scope));
  for (const d of decls) {
    const src = uncommented(text(d.file), "go");
    const specs: { alias?: string; path: string }[] = [];
    for (const m of src.matchAll(/^import[ \t]+(?:([\w.]+)[ \t]+)?"([^"]+)"/gm)) specs.push({ alias: m[1], path: m[2] });
    for (const b of src.matchAll(/^import[ \t]*\(([\s\S]*?)\)/gm))
      for (const m of b[1].matchAll(/^[ \t]*(?:([\w.]+)[ \t]+)?"([^"]+)"/gm)) specs.push({ alias: m[1], path: m[2] });
    for (const s of specs) {
      const mod = mods.find((m) => s.path === m.path || s.path.startsWith(`${m.path}/`));
      if (!mod) continue;
      const target = join2(mod.dir, s.path.slice(mod.path.length + 1));
      const there = inDir.get(target) ?? [];
      if (!there.length) continue;
      const alias = s.alias ?? pkgName.get(target) ?? basename(target);
      if (alias === "_") { there.filter((x) => !x.file.endsWith("_test.go")).forEach((x) => add(d.file, x.file)); continue; }
      if (alias === ".") { byMention(d.file, words(src), there, add); continue; }
      const used = new Set([...src.matchAll(new RegExp(`\\b${alias.replace(/\./g, "\\.")}\\.([A-Z]\\w*)`, "g"))].map((m) => m[1]));
      byMention(d.file, used, there, add);
    }
    // A package's files use each other's names with no import.
    byMention(d.file, words(src.replace(/^import[ \t]*\([\s\S]*?^\)/gm, "").replace(/^import[^\n]*/gm, "")), inDir.get(d.scope) ?? [], add);
  }
}

/* ── Rust ────────────────────────────────────────────────── */

function rustGraph(files: string[], text: (p: string) => string, known: Set<string>, listed: string[], repo: string, add: (a: string, b: string) => void) {
  // Each crate's root files, then the module tree its `mod x;` lines grow.
  const crates = new Map<string, string>(); // crate name → root file
  const moduleOf = new Map<string, { crate: string; path: string[] }>();
  const fileOf = new Map<string, string>(); // "crate::a::b" → file
  const roots: { file: string; crate: string }[] = [];
  for (const toml of listed.filter((f) => /(^|\/)Cargo\.toml$/.test(f))) {
    const body = readFileSync(join(repo, toml), "utf8");
    const base = dir(toml);
    const name = (/^\[package\][\s\S]*?^name[ \t]*=[ \t]*"([^"]+)"/m.exec(body)?.[1] ?? basename(base)).replace(/-/g, "_");
    // Each root is a crate of its own: `crate::` in main.rs is main's tree, and main reaches the library by its name.
    const bins = files.filter((f) => f.startsWith(join2(base, "src/bin/")) && f.split("/").length === join2(base, "src/bin/x").split("/").length);
    for (const [r, crate] of [[join2(base, "src/lib.rs"), name], [join2(base, "src/main.rs"), `${name}#main`], ...bins.map((b) => [b, `${name}#${b}`]), [join2(base, "build.rs"), `${name}#build`]])
      if (known.has(r)) roots.push({ file: r, crate });
    if (known.has(join2(base, "src/lib.rs"))) crates.set(name, join2(base, "src/lib.rs"));
  }
  const queue = roots.map((r) => ({ ...r, path: [] as string[] }));
  while (queue.length) {
    const { file, crate, path } = queue.shift()!;
    if (moduleOf.has(file)) continue;
    moduleOf.set(file, { crate, path });
    fileOf.set([crate, ...path].join("::"), file);
    const stem = basename(file, ".rs");
    const childDir = ["lib", "main", "mod"].includes(stem) || roots.some((r) => r.file === file) ? dir(file) : join2(dir(file), stem);
    const src = uncommented(text(file), "rust");
    for (const m of src.matchAll(/(?:#\[path[ \t]*=[ \t]*"([^"]+)"\][\s]*)?^[ \t]*(?:pub(?:\([^)]*\))?[ \t]+)?mod[ \t]+(\w+)[ \t]*;/gm)) {
      const to = m[1] ? join2(dir(file), m[1]) : [join2(childDir, `${m[2]}.rs`), join2(childDir, `${m[2]}/mod.rs`)].find((p) => known.has(p));
      if (to && known.has(to)) queue.push({ file: to, crate, path: [...path, m[2]] });
    }
  }
  /** The file of the longest module prefix of `segs`, from module `at` of `crate`. */
  const resolve = (crate: string, at: string[], segs: string[]): string | null => {
    let base: string[];
    let c = crate;
    let rest = segs;
    // Unanchored, a path may name a child module (2018 paths) or an outside crate; only a module found counts.
    let anchored = true;
    if (segs[0] === "crate") { base = []; rest = segs.slice(1); }
    else if (segs[0] === "self") { base = at; rest = segs.slice(1); }
    else if (segs[0] === "super") { base = at; while (rest[0] === "super") { base = base.slice(0, -1); rest = rest.slice(1); } }
    else if (crates.has(segs[0]) && segs[0] !== crate) { c = segs[0]; base = []; rest = segs.slice(1); }
    else { base = at; anchored = false; }
    for (let n = rest.length; n >= (anchored ? 0 : 1); n--) {
      const hit = fileOf.get([c, ...base, ...rest.slice(0, n)].join("::"));
      if (hit) return hit;
    }
    return null;
  };
  /** `a::b::{c, d::{e, f as g}, h::*}` flattened into paths. */
  const flatten = (tree: string): string[][] => {
    const out: string[][] = [];
    const walk = (s: string, prefix: string[]) => {
      s = s.trim();
      const brace = s.indexOf("{");
      if (brace === -1) { const p = s.split(/\s+as\s+/)[0].split("::").map((x) => x.trim()).filter((x) => x && x !== "*"); if (p.length || prefix.length) out.push([...prefix, ...p]); return; }
      const head = s.slice(0, brace).split("::").map((x) => x.trim()).filter(Boolean);
      const inner = s.slice(brace + 1, s.lastIndexOf("}"));
      let depth = 0, start = 0;
      for (let i = 0; i <= inner.length; i++) {
        const ch = inner[i];
        if (ch === "{") depth++;
        else if (ch === "}") depth--;
        else if ((ch === "," && depth === 0) || i === inner.length) { const part = inner.slice(start, i); if (part.trim()) walk(part, [...prefix, ...head]); start = i + 1; }
      }
    };
    walk(tree, []);
    return out;
  };
  for (const f of files) {
    const mod = moduleOf.get(f);
    if (!mod) continue;
    const src = uncommented(text(f), "rust");
    for (const m of src.matchAll(/^[ \t]*(?:pub(?:\([^)]*\))?[ \t]+)?use[ \t]+([^;]+);/gm))
      for (const segs of flatten(m[1])) { const to = resolve(mod.crate, mod.path, segs); if (to && to !== f) add(f, to); }
    for (const m of src.matchAll(/\b(crate|super|self)((?:::\w+)+)/g)) {
      const to = resolve(mod.crate, mod.path, [m[1], ...m[2].split("::").filter(Boolean)]);
      if (to && to !== f) add(f, to);
    }
  }
}

/* ── Ruby ────────────────────────────────────────────────── */

function rubyGraph(files: string[], text: (p: string) => string, known: Set<string>, add: (a: string, b: string) => void) {
  const camel = (s: string) => s.split("_").map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join("");
  // Rails autoloading (Zeitwerk): app/<kind>/a/b_c.rb is A::BC; lib/a/b.rb is A::B.
  const constant = new Map<string, string>();
  /** The full names of the classes and modules a file opens, nested by indentation: `module A` around `class B` is A::B. */
  const opened = (src: string) => {
    const stack: { indent: number; name: string }[] = [];
    const out: string[] = [];
    for (const m of src.matchAll(/^([ \t]*)(?:class|module)[ \t]+([A-Z][\w:]*)/gm)) {
      const indent = m[1].length;
      while (stack.length && stack[stack.length - 1].indent >= indent) stack.pop();
      stack.push({ indent, name: m[2] });
      out.push(stack.map((s) => s.name).join("::"));
    }
    return out;
  };
  const scopes = new Map<string, string[]>();
  for (const f of files) {
    const m = /^(?:.*\/)?(?:app\/[^/]+|lib)\/(.+)\.rb$/.exec(f);
    if (m) constant.set(m[1].split("/").map(camel).join("::"), f);
    const names = opened(uncommented(text(f), "ruby"));
    for (const n of names) if (!constant.has(n)) constant.set(n, f);
    // Where its constants are looked up: inside each name it opens and that name's parents, innermost first, then the top.
    scopes.set(f, [...new Set(names.flatMap((n) => n.split("::").map((_, i, a) => a.slice(0, a.length - i).join("::"))))].sort((a, b) => b.length - a.length));
  }
  for (const f of files) {
    const src = uncommented(text(f), "ruby");
    for (const m of src.matchAll(/\brequire_relative[ \t(]+['"]([^'"]+)['"]/g)) {
      const p = join2(dir(f), m[1].endsWith(".rb") ? m[1] : `${m[1]}.rb`);
      if (known.has(p)) add(f, p);
    }
    // `require "a/b"` loads a/b.rb from a load path: some gem's lib/, the nearest one first.
    for (const m of src.matchAll(/\brequire[ \t(]+['"]([^'"]+)['"]/g)) {
      const tail = `${m[1].replace(/\.rb$/, "")}.rb`;
      const shared = (p: string) => { let i = 0; while (i < p.length && p[i] === f[i]) i++; return i; };
      const p = [...known].filter((x) => x === tail || x === `lib/${tail}` || x.endsWith(`/lib/${tail}`)).sort((a, b) => shared(b) - shared(a))[0];
      if (p) add(f, p);
    }
    // The name a `class`/`module` line opens is not a use of it; what it inherits from is.
    for (const m of src.replace(/^([ \t]*(?:class|module)[ \t]+)[A-Z][\w:]*/gm, "$1").matchAll(/(::)?\b([A-Z]\w*(?:::[A-Z]\w*)*)/g)) {
      const tries = m[1] ? [m[2]] : [...(scopes.get(f) ?? []).map((s) => `${s}::${m[2]}`), m[2]];
      const to = tries.map((t) => constant.get(t)).find(Boolean);
      if (to && to !== f) add(f, to);
    }
  }
}

/* ── C / C++ / Objective-C ───────────────────────────────── */

function cGraph(files: string[], text: (p: string) => string, known: Set<string>, add: (a: string, b: string) => void) {
  const all = [...known];
  const impl = new Map<string, string>();
  for (const f of files) if (/\.(c|cc|cpp|cxx|m|mm)$/.test(f)) impl.set(f.replace(/\.[^.]+$/, ""), f);
  for (const f of files) {
    for (const m of uncommented(text(f), "c").matchAll(/^[ \t]*#[ \t]*(?:include|import)[ \t]*(["<])([^">]+)[">]/gm)) {
      const spec = m[2];
      const near = join2(dir(f), spec);
      const tail = all.filter((p) => p === spec || p.endsWith(`/${spec}`));
      const to = known.has(near) ? near : known.has(spec) ? spec : tail.length === 1 || (m[1] === '"' && tail.length) ? tail.sort((a, b) => a.length - b.length)[0] : null;
      if (!to || to === f) continue;
      add(f, to);
      // What uses a header uses the file that implements it.
      const body = /\.(h|hh|hpp)$/.test(to) ? impl.get(to.replace(/\.[^.]+$/, "")) : undefined;
      if (body && body !== f) add(f, body);
    }
  }
}

/* ── Swift ───────────────────────────────────────────────── */

function swiftGraph(files: string[], text: (p: string) => string, add: (a: string, b: string) => void) {
  const decls = declared(files, text, "swift");
  const inModule = groupBy(decls);
  for (const d of decls) {
    const src = uncommented(text(d.file), "swift");
    const used = words(src);
    const imported = [...src.matchAll(/^[ \t]*(?:@testable[ \t]+)?import[ \t]+(\w+)/gm)].map((m) => m[1]).filter((m) => inModule.has(m));
    for (const s of new Set([d.scope, ...imported])) byMention(d.file, used, inModule.get(s) ?? [], add);
  }
}

/* ── Dart ────────────────────────────────────────────────── */

function dartGraph(files: string[], text: (p: string) => string, known: Set<string>, listed: string[], repo: string, add: (a: string, b: string) => void) {
  const pubs = listed
    .filter((f) => /(^|\/)pubspec\.yaml$/.test(f))
    .map((f) => ({ dir: dir(f), name: /^name:[ \t]*(\S+)/m.exec(readFileSync(join(repo, f), "utf8"))?.[1] ?? "" }));
  for (const f of files)
    for (const m of uncommented(text(f), "dart").matchAll(/^[ \t]*(?:import|export|part)[ \t]+['"]([^'"]+)['"]/gm)) {
      const pkg = /^package:([^/]+)\/(.+)$/.exec(m[1]);
      const p = pkg ? pubs.filter((x) => x.name === pkg[1]).map((x) => join2(x.dir, `lib/${pkg[2]}`))[0] : m[1].includes(":") ? undefined : join2(dir(f), m[1]);
      if (p && known.has(p)) add(f, p);
    }
}

/* ── Elixir ──────────────────────────────────────────────── */

function elixirGraph(files: string[], text: (p: string) => string, add: (a: string, b: string) => void) {
  const modules = new Map<string, string>();
  for (const f of files) for (const m of uncommented(text(f), "elixir").matchAll(/\bdefmodule[ \t]+([A-Z][\w.]*)/g)) if (!modules.has(m[1])) modules.set(m[1], f);
  for (const f of files) {
    const src = uncommented(text(f), "elixir");
    const alias = new Map<string, string>();
    for (const m of src.matchAll(/\balias[ \t]+([A-Z][\w.]*)(?:[ \t]*,[ \t]*as:[ \t]*([A-Z]\w*))?/g)) alias.set(m[2] ?? m[1].split(".").pop()!, m[1]);
    for (const m of src.matchAll(/\b([A-Z]\w*(?:\.[A-Z]\w*)*)/g)) {
      const [head, ...rest] = m[1].split(".");
      const full = alias.has(head) ? [alias.get(head)!, ...rest].join(".") : m[1];
      const to = modules.get(full);
      if (to && to !== f) add(f, to);
    }
  }
}

/* ── all of them ─────────────────────────────────────────── */

/**
 * Repo-relative edges from each code file to the code files it uses, every
 * language at once. `listed` is every file git lists (manifests included);
 * `code` the files to read.
 */
export function importGraph(repo: string, code: string[], listed: string[]): Record<string, string[]> {
  const known = new Set(listed);
  const cache = new Map<string, string>();
  const text = (p: string) => {
    let t = cache.get(p);
    if (t === undefined) {
      try { t = readFileSync(join(repo, p), "utf8"); } catch { t = ""; }
      cache.set(p, t);
    }
    return t;
  };
  const edges: Edges = new Map();
  const add = (a: string, b: string) => { if (a !== b) (edges.get(a) ?? edges.set(a, new Set()).get(a)!).add(b); };
  const of = (l: Lang) => code.filter((f) => langOf(f) === l);
  const run = (l: Lang, fn: (files: string[]) => void) => { const files = of(l); if (files.length) fn(files); };

  run("ts", (fs) => tsGraph(fs, text, known, aliases(repo, listed), add));
  run("python", (fs) => pythonGraph(fs, text, known, add));
  run("jvm", (fs) => jvmGraph(fs, text, add));
  run("csharp", (fs) => csharpGraph(fs, text, add));
  run("php", (fs) => phpGraph(fs, text, known, add));
  run("go", (fs) => goGraph(fs, text, listed, repo, add));
  run("rust", (fs) => rustGraph(fs, text, known, listed, repo, add));
  run("ruby", (fs) => rubyGraph(fs, text, known, add));
  run("c", (fs) => cGraph(fs, text, known, add));
  run("swift", (fs) => swiftGraph(fs, text, add));
  run("dart", (fs) => dartGraph(fs, text, known, listed, repo, add));
  run("elixir", (fs) => elixirGraph(fs, text, add));

  const codeSet = new Set(code);
  return Object.fromEntries(
    [...edges].filter(([a]) => codeSet.has(a)).map(([a, bs]) => [a, [...bs].filter((b) => codeSet.has(b)).sort()] as const).filter(([, bs]) => bs.length).sort(([a], [b]) => a.localeCompare(b)),
  );
}

app/scripts/generate/inventory.ts:
/**
 * Stage 0 — what is in the repository, with no model involved.
 *
 * Everything the later stages are allowed to cite comes from here: the file
 * list, line counts, the manifest's dependencies, and which file uses which
 * (imports.ts). A model never sees a path this did not list.
 */

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, statSync } from "node:fs";
import { basename, extname, join } from "node:path";
import { MARK_IDS } from "@/components/bluprint/shapes";
import { importGraph } from "./imports";

export interface RepoFile {
  path: string;
  lines: number;
  hash: string;
  /** Source a model should read and summarise, as opposed to config, docs or assets. */
  code: boolean;
  /** A test, fixture or story: listed and citable, never summarised or required in a root. */
  test: boolean;
  /** Outside a --scope: readable and citable, but no root owns it. */
  outside?: boolean;
}

/** What a model summarises and a root must own: source, not tests. */
export const isSource = (f: RepoFile) => f.code && !f.test;
/** `isSource` by path alone, for a file not inventoried yet (app/api/files): what an update would take as code. */
export const sourcePath = (path: string) => !SKIP.some((r) => r.test(path)) && CODE.has(extname(path).toLowerCase()) && !TEST.test(path);

export interface Inventory {
  repo: string;
  name: string;
  commit: string;
  /** Files that differ from the commit, new ones included: the bluprint is read from disk, so it describes those edits, not the commit alone. */
  dirty: string[];
  files: RepoFile[];
  readme: string;
  /**
   * What the repository tells coding agents (AGENTS.md, CLAUDE.md, at any
   * depth): its conventions and rules, which say what its parts are meant to
   * be. Capped; empty when it has none.
   */
  instructions: string;
  /** Its other Markdown, with each file's first heading: the docs a section may cite for why (`Node.docs`). */
  docs: { path: string; lines: number; title: string }[];
  /** Dependency names from every manifest found, sorted. */
  deps: string[];
  /** Brand marks this repo has a real dependency for (D25). */
  marks: string[];
  /** What its screens run on, from its frameworks: a mobile app's, a browser's, or both (a mobile app beside a web one). */
  device: "phone" | "web" | "both";
  /** A bluprint of part of a large repo: the paths it covers and what a reader of it does. */
  scope?: { paths: string[]; focus: string };
  /** Repo-relative: the code files each code file uses, every language (imports.ts). */
  imports: Record<string, string[]>;
}

const CODE = new Set([
  ".ts", ".tsx", ".mts", ".cts", ".js", ".jsx", ".mjs", ".cjs", ".vue", ".svelte", ".astro",
  ".py", ".go", ".rb", ".rs", ".java", ".kt", ".scala", ".swift", ".php", ".cs", ".ex", ".exs",
  ".c", ".h", ".cc", ".cpp", ".cxx", ".hpp", ".hh", ".m", ".mm", ".dart",
  ".sql", ".prisma", ".graphql", ".gql", ".proto",
]);
const SKIP = [
  /(^|\/)(node_modules|vendor|third_party|thirdparty|dist|build|out|target|coverage|\.next|\.turbo|\.git|__snapshots__|migrations\/meta)\//,
  /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|bun\.lockb?|poetry\.lock|uv\.lock|Cargo\.lock|go\.sum|composer\.lock)$/,
  /\.(min\.js|bluprint|png|jpe?g|gif|webp|ico|svg|woff2?|ttf|otf|eot|mp4|mp3|wav|pdf|zip|gz|lock|snap)$/i,
  /\.d\.ts$/,
];
const TEST = /(^|\/)(tests?|__tests__|__mocks__|specs?|e2e|cypress|playwright|fixtures|stories)\/|\.(test|spec|stories|e2e)\.[a-z]+$|(^|\/)(test_[^/]+|[^/]+_test)\.(py|go)$|(^|\/)conftest\.py$/;
/**
 * Generated or minified code is listed, never summarised. Size alone is not
 * the sign: at 150 KB, Kafka's KafkaRaftClient.java (4,000 hand-written lines,
 * the heart of its consensus) was dropped from the bluprint and nothing said so.
 */
const MAX_BYTES = 1_000_000;
const GENERATED = /@generated|DO NOT EDIT|<auto-generated|automatically generated|autogenerated/i;
/** Generated, minified, or a bundled library (its `/*!` banner kept by the bundler that made it). */
const generated = (text: string) => {
  const lines = text.split("\n").length;
  return GENERATED.test(text.slice(0, 1500)) || (text.length > 20_000 && text.length / lines > 250) || (lines > 1000 && text.trimStart().startsWith("/*!"));
};
/** The files a repository writes for coding agents rather than for people. */
const AGENT_FILES = /(^|\/)(AGENTS|CLAUDE|GEMINI)\.md$/i;
const INSTRUCTIONS_CHARS = 6000;

/** Which dependency names stand for which brand mark. */
const MARK_DEPS: Record<string, RegExp> = {
  aws: /^@aws-sdk\/|^aws-sdk$|^boto3$/,
  bedrock: /bedrock/,
  s3: /client-s3|s3-request-presigner/,
  supabase: /^@supabase\/|^supabase$/,
  openai: /^openai$/,
  postgres: /^pg$|^postgres$|^psycopg|^@neondatabase|^@vercel\/postgres|^asyncpg$/,
  nextjs: /^next$/,
  zod: /^zod$/,
  pdf: /pdf/,
  expo: /^expo$/,
  googlemaps: /google-bluprints|googlemaps|places-autocomplete/,
  flask: /^flask$/i,
  deno: /^deno$/,
};

function git(repo: string, ...args: string[]) {
  return execFileSync("git", ["-C", repo, ...args], { encoding: "utf8", maxBuffer: 64 << 20, windowsHide: true }).trim();
}

// A mobile framework, by dependency or by the project files it leaves —
// not Tauri's generated mobile shell, which wraps the same web UI.
const PHONE_DEPS = /^(react-native|expo|@capacitor\/core|@ionic\/react|@ionic\/angular|nativescript)$/;
const PHONE_FILES = /(^|\/)(pubspec\.yaml|AndroidManifest\.xml|[^/]+\.xcodeproj\/project\.pbxproj)$/;
// A web front end of its own. Not react-dom: an Expo app's web build pulls it
// in; and not Flask or Django, which beside a mobile app are its API.
const WEB_DEPS = /^(next|vite|nuxt|@sveltejs\/kit|astro|@remix-run\/.+|@angular\/core|gatsby)$/;

function deviceOf(deps: string[], files: string[]): Inventory["device"] {
  const phone = deps.some((d) => PHONE_DEPS.test(d)) || files.some((f) => PHONE_FILES.test(f) && !f.includes("src-tauri/"));
  if (!phone) return "web";
  return deps.some((d) => WEB_DEPS.test(d)) ? "both" : "phone";
}

function manifests(repo: string, files: string[]): string[] {
  const deps = new Set<string>();
  for (const f of files) {
    if (f.endsWith("package.json")) {
      try {
        const p = JSON.parse(readFileSync(join(repo, f), "utf8"));
        for (const k of ["dependencies", "devDependencies", "peerDependencies"]) Object.keys(p[k] ?? {}).forEach((d) => deps.add(d));
      } catch { /* a broken manifest names nothing */ }
    } else if (/(^|\/)(requirements[^/]*\.txt|pyproject\.toml)$/.test(f)) {
      const text = readFileSync(join(repo, f), "utf8");
      for (const m of text.matchAll(/^\s*"?([A-Za-z][\w.-]+)\s*(?:[<>=~!\[;"]|$)/gm)) deps.add(m[1].toLowerCase());
    }
  }
  return [...deps].sort();
}

/**
 * The working tree as it is, files git does not know yet (not ignored)
 * included: a bluprint is of the code on disk, committed or not.
 */
export function inventory(repo: string): Inventory {
  const untracked = git(repo, "ls-files", "--others", "--exclude-standard").split("\n").filter(Boolean);
  const listed = [...new Set([...git(repo, "ls-files").split("\n").filter(Boolean), ...untracked])].sort();
  const files: RepoFile[] = [];
  for (const path of listed) {
    if (SKIP.some((r) => r.test(path))) continue;
    const abs = join(repo, path);
    if (!existsSync(abs) || !statSync(abs).isFile()) continue;
    const buf = readFileSync(abs);
    if (buf.includes(0)) continue;
    const text = buf.toString("utf8");
    files.push({
      path,
      lines: text.split("\n").length,
      hash: createHash("sha1").update(buf).digest("hex").slice(0, 12),
      code: CODE.has(extname(path).toLowerCase()) && buf.length <= MAX_BYTES && !generated(text),
      test: TEST.test(path),
    });
  }

  const imports = importGraph(repo, files.filter((f) => f.code).map((f) => f.path), listed);

  const readmeFile = listed.find((f) => /^readme(\.md|\.rst|\.txt)?$/i.test(f));
  const markdown = files.filter((f) => !f.test && /\.mdx?$/i.test(f.path) && f.path !== readmeFile);
  const forAgents = markdown.filter((f) => AGENT_FILES.test(f.path));
  const instructions = forAgents
    .map((f) => `### ${f.path}\n${readFileSync(join(repo, f.path), "utf8").trim()}`)
    .join("\n\n")
    .slice(0, INSTRUCTIONS_CHARS);
  const docs = markdown
    .filter((f) => !AGENT_FILES.test(f.path))
    .map((f) => {
      const heading = readFileSync(join(repo, f.path), "utf8").match(/^#{1,3}\s+(.+)$/m);
      return { path: f.path, lines: f.lines, title: heading ? heading[1].trim() : "" };
    });
  const deps = manifests(repo, listed);
  return {
    repo,
    name: basename(repo),
    commit: git(repo, "rev-parse", "--short", "HEAD"),
    dirty: [...git(repo, "diff", "HEAD", "--name-only", "--relative").split("\n").filter(Boolean), ...untracked],
    files,
    readme: readmeFile ? readFileSync(join(repo, readmeFile), "utf8").slice(0, 8000) : "",
    instructions,
    docs,
    deps,
    marks: MARK_IDS.filter((m) => MARK_DEPS[m] && deps.some((d) => MARK_DEPS[m].test(d))),
    device: deviceOf(deps, listed),
    imports,
  };
}

/** Keeps an inventory to part of the repository: files outside it stay readable and citable, but are no root's to explain. */
export function scopeTo(inv: Inventory, scope: { paths: string[]; focus: string }) {
  inv.scope = scope;
  for (const f of inv.files) if (!scope.paths.some((p) => f.path === p || f.path.startsWith(p.replace(/\/?$/, "/")))) Object.assign(f, { code: false, outside: true });
  const inside = new Set(inv.files.filter((f) => f.code).map((f) => f.path));
  inv.imports = Object.fromEntries(Object.entries(inv.imports).filter(([a]) => inside.has(a)).map(([a, bs]) => [a, bs.filter((b) => inside.has(b))]).filter(([, bs]) => bs.length));
}

/** A file's text with 1-indexed line numbers, the only form a model ever reads. */
export function numbered(repo: string, path: string, start = 1, end = Infinity): string {
  const lines = readFileSync(join(repo, path), "utf8").split(/\r?\n/);
  const s = Math.max(1, start);
  const e = Math.min(lines.length, end);
  return lines.slice(s - 1, e).map((l, i) => `${String(s + i).padStart(5)}  ${l}`).join("\n");
}

app/scripts/generate/overview.ts:
/**
 * Stage 3b — the repository's own level (D60): what it is, and one picture
 * whose boxes open the roots and whose arrows are paths the code really takes
 * from one root to another.
 *
 * It runs after the roots are accepted, so it draws what the authors found
 * rather than what the cut guessed. Its evidence for an arrow between two
 * roots is the import graph: each file of one that uses a file of the other,
 * with the first line that names what it uses. The authors' own arrows
 * across roots were the evidence before, and missed most of these (a root
 * draws its own parts, not who calls it). The same agent tools and checker as
 * an author; only the brief and what a submit must hold differ.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- model tool inputs */
import type { Node } from "@/lib/bluprint/schema";
import type { Overview } from "@/lib/bluprint/build";
import { authorTool, converse } from "./author";
import { type Handled } from "./claude-code";
import { bareLines, check, EXPLAIN_LEVEL, fileReader, OVERVIEW_ID, WALK_STEPS, WALKS } from "./check";
import { owners, type Cut } from "./cut";
import type { Inventory } from "./inventory";
import { shapeProblems } from "./schema";
import type { FileSummary } from "./summarize";

export interface Overviewed {
  overview: Overview | null;
  turns: number;
  submits: number;
  problems: string[];
}

/** An overview's own fields, out of the node it was checked as. */
export const toOverview = (n: any): Overview =>
  Object.fromEntries(["sub", "detail", "anatomy", "issues", "code", "state", "unsure", "explain", "glossary", "walkthroughs"].filter((k) => n[k] !== undefined).map((k) => [k, n[k]])) as Overview;

/** Symbol names too common to say which import a line uses. */
const COMMON = /^(default|constructor|main|init|__init__|new|run|get|set|handler|config|props|index|value|data|type|impl|fn|pub|struct|class|def|func|trait|enum|object)$/i;
const esc = (x: string) => x.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/**
 * Root-to-root edges from the import graph, each with up to three of the
 * files behind it and, where one can be found, the first line past the
 * imports that names a symbol of the file it uses: the call site to cite.
 */
export function edges(roots: Node[], cut: Cut, inv: Inventory, sums: Record<string, FileSummary>): string[] {
  const ids = new Set(roots.map((r) => r.id));
  const linesOf = fileReader(inv.repo);
  const site = (a: string, b: string) => {
    const names = [...new Set((sums[b]?.symbols ?? []).map((x) => x.name.split(/[.\s(:#]/).filter(Boolean).pop() ?? "").filter((n) => n.length >= 3 && !COMMON.test(n)))];
    const lines = linesOf(a);
    if (!names.length || !lines) return null;
    const re = new RegExp(`\\b(${names.map(esc).join("|")})\\b`);
    const bare = bareLines(lines);
    for (let i = 0; i < lines.length; i++) {
      const m = !bare[i] && re.exec(lines[i]);
      if (m) return { line: i + 1, name: m[1] };
    }
    return null;
  };
  const pairs = new Map<string, { count: number; seen: string[] }>();
  for (const [a, bs] of Object.entries(inv.imports))
    for (const b of bs)
      for (const x of owners(cut, a).filter((r) => ids.has(r)))
        for (const y of owners(cut, b).filter((r) => ids.has(r) && r !== x && !owners(cut, a).includes(r))) {
          const k = `${x} → ${y}`;
          const p = pairs.get(k) ?? { count: 0, seen: [] };
          p.count++;
          if (p.seen.length < 3) {
            const s = site(a, b);
            p.seen.push(s ? `${a}:${s.line} uses \`${s.name}\` (${b})` : `${a} imports ${b}`);
          }
          pairs.set(k, p);
        }
  return [...pairs].sort((a, b) => b[1].count - a[1].count).map(([k, p]) => `- ${k} (${p.count} import${p.count > 1 ? "s" : ""}): ${p.seen.join("; ")}`);
}

/** What each root's files read and write, as their summaries say: the evidence for where data lives. */
function stores(roots: Node[], cut: Cut, inv: Inventory, sums: Record<string, FileSummary>): string[] {
  return roots.flatMap((r) => {
    const mine = inv.files.filter((f) => owners(cut, f.path).includes(r.id)).map((f) => sums[f.path]).filter(Boolean);
    const w = [...new Set(mine.flatMap((s) => s.writes))].slice(0, 8);
    const rd = [...new Set(mine.flatMap((s) => s.reads))].slice(0, 8);
    return w.length || rd.length ? [`- ${r.id}: ${w.length ? `writes ${w.join(", ")}` : ""}${w.length && rd.length ? "; " : ""}${rd.length ? `reads ${rd.join(", ")}` : ""}`] : [];
  });
}

/** Every part's id and title, indented as the tree nests: what a walkthrough step's `path` is made of. */
function tree(roots: Node[]): string {
  const out: string[] = [];
  const walk = (n: Node, d: number) => { out.push(`${"  ".repeat(d)}- ${n.id}: ${n.title} — ${n.sub}`); (n.children ?? []).forEach((c) => walk(c, d + 1)); };
  roots.forEach((r) => walk(r, 0));
  return out.join("\n");
}

function brief(roots: Node[], cut: Cut, inv: Inventory, sums: Record<string, FileSummary>): string {
  const cross = edges(roots, cut, inv, sums);
  const data = stores(roots, cut, inv, sums);
  return [
    `# Repository: ${inv.name} @ ${inv.commit}`,
    `## README (excerpt)\n${inv.readme.slice(0, 2500) || "(none)"}`,
    `## Its roots, as their authors wrote them — ${cut.about}\n${roots
      .map((r) => `- ${r.id}: ${r.title} — ${r.sub}\n  ${r.detail ?? ""}\n  cites: ${(r.code ?? []).map((c) => `${c.file}:${c.start}-${c.end}`).join(", ")}`)
      .join("\n")}`,
    `## Every part, by id\n${tree(roots)}`,
    cross.length
      ? `## Where one root's code uses another's, by import — evidence for an arrow between roots\nEach line: the files behind the edge, and where one was found, the first line that names what it uses.\n${cross.slice(0, 60).join("\n")}`
      : "",
    data.length ? `## What each root's files read and write, as their summaries say\n${data.join("\n")}` : "",
    `## Task
Write the top level of the bluprint: the repository itself, the level a reader lands on before opening any root. Submit it with \`root\`, a node with no \`id\`, \`title\` or \`children\`:
- \`sub\`: at most 8 words, what this repository IS.
- \`detail\`: at most two sentences and 40 words, the one thing to know before the picture.
- \`anatomy\`: exactly one \`diagram\`, its \`caption\` a heading of at most 5 words ("How the roots connect"), not a sentence. One box per root, labelled with the root's title, with \`opens\` set to the root's id; lay them out left to right in the order someone meets them, a branch on a row of its own. Add a box that opens nothing only for a thing outside every root that the roots meet (the database, an outside API).
- Arrows only where the code goes from one root to another — a call, a redirect, a write another reads — each with \`at\` as file:line, a line in one of the two roots' files. Take them from graph_links, from one root's files to the other's: each link it lists is a real call, with the line to cite. Draw the ones a reader needs (the most-used, and every one a walkthrough crosses). Where roots meet in a way the graph cannot follow (an event, a queue, a route the framework calls, the network), draw the arrow \`inferred: true\`, citing the line that wires it. Roots with nothing between them get no arrow. You cannot open files; the graph tools are how you see the code.
- Where the code stores data (a database, files, a cache, browser storage, a queue), a \`table\` captioned "Where data lives", with columns Store | Holds | Defined at | Written by | Read by: one row per store, what it holds in a few words, the file:line where its schema or shape is defined (a migration, a model, a type), and the roots that write and read it, by title. Confirm each writer and reader in the graph (graph_callers on the function that writes or reads); the summaries above are leads. A repository that stores nothing has none.
- \`code\`: the lines that show how the whole fits together (the entry point, the router), \`state\`, and \`issues\` only if one spans roots.
- \`walkthroughs\`: ${WALKS[0]}-${WALKS[1]} of \`{title, steps}\` — the core things this system does, each followed from start to end across the roots it passes through ("A visitor pays for a plan", "A broker joins the cluster"): the ones a developer new to the code most needs, not edge cases. ${WALK_STEPS[0]}-${WALK_STEPS[1]} steps each, in the order they happen. Each step: \`title\` a few words, \`detail\` one or two plain sentences naming the function that does it, and \`path\` the ids from a root down to the part where it happens (from the list above), as deep as the step is specific.

${WAY_IN[EXPLAIN_LEVEL]}Budget: about 10 tool calls before you submit.`,
  ].filter(Boolean).join("\n\n");
}

/** What the top level adds for a newcomer, at the bluprint's explain level (D70). The full text is D68's, unchanged. */
const WAY_IN = {
  full: `Then the way in for a reader who has never seen this project or its field — shown under an Explain toggle, so it can say more than the rest of the bluprint:
- \`explain\`: \`body\` is 2-4 short paragraphs (blank line between, at most 200 words): what this system is for and who uses it, the problem it solves, and the idea behind how it works, defining each word of its field the first time. \`blocks\` holds 0-2 pictures only where they teach more than the prose — usually one \`diagram\` of the system in its world (the users, the machines, the outside services, and what flows between them), its boxes opening nothing and its arrows needing no \`at\`.
- \`glossary\`: 4-12 terms the bluprint's titles and details lean on, as \`{term, meaning}\`, each meaning one plain sentence of at most 25 words. Terms of the field ("quorum", "webhook") and of this project ("metadata image") alike; skip words everyone knows. It is never listed — each term is defined on hover where the bluprint uses it, so use the exact word the text uses.
`,
  detailed: `Then the way in for a reader who knows a little of this kind of software and none of this project — shown under an Explain toggle:
- \`explain\`: \`body\` is one or two short paragraphs (blank line between, at most 120 words): what this system is for and who uses it, and the idea behind how it works, defining each word of its field the first time. \`blocks\` holds at most one picture, only where it teaches more than the prose — usually a \`diagram\` of the system in its world, its boxes opening nothing and its arrows needing no \`at\`.
- \`glossary\`: 4-10 terms the bluprint's titles and details lean on, as \`{term, meaning}\`, each meaning one plain sentence of at most 25 words. Terms of the field and of this project alike; skip words everyone knows. It is never listed — each term is defined on hover where the bluprint uses it, so use the exact word the text uses.
`,
  brief: `Then a short way in for a reader who knows this kind of software but not this project — shown under an Explain toggle:
- \`explain\`: \`body\` is one to three sentences, at most 60 words: what this system is for and the idea behind how it is built. No \`blocks\`.
- \`glossary\`: 3-8 terms, as \`{term, meaning}\`, each meaning one plain sentence of at most 25 words — only this project's own words, or words a developer outside this field would not know. It is never listed — each term is defined on hover where the bluprint uses it, so use the exact word the text uses.
`,
  minimal: `Then a one-line way in for a reader who knows this kind of software and has used this project — shown under an Explain toggle:
- \`explain\`: \`body\` is one sentence, at most 30 words: what this system is for. No \`blocks\`.
- \`glossary\`: 2-5 terms, as \`{term, meaning}\`, each meaning one plain sentence of at most 25 words — only words this project uses in its own sense. It is never listed — each term is defined on hover where the bluprint uses it, so use the exact word the text uses.
`,
  none: "",
};

/** Problems with a submitted overview: its shape, the checker's verdict on it, a box for every root, and arrows between roots that cite one of theirs. */
export function overviewProblems(o: any, roots: Node[], repo: string, cut: Cut): string[] {
  if (!o || typeof o !== "object") return ["root is not an object"];
  const as = { ...o, id: OVERVIEW_ID, title: "Overview", children: [] };
  const shape = shapeProblems(as, "", true);
  if (shape.length) return shape;
  const diagrams = (o.anatomy ?? []).filter((b: any) => b.kind === "diagram");
  if (diagrams.length !== 1) return [`${OVERVIEW_ID}: anatomy needs exactly one diagram, has ${diagrams.length}`];
  const opened = diagrams[0].boxes.map((x: any) => x.opens).filter(Boolean);
  const out = roots.filter((r) => opened.filter((id: string) => id === r.id).length !== 1).map((r) => `${OVERVIEW_ID}: diagram needs exactly one box that opens root "${r.id}"`);
  const rootOf = (id: string) => diagrams[0].boxes.find((x: any) => x.id === id)?.opens;
  for (const a of diagrams[0].arrows ?? []) {
    const [x, y] = [rootOf(a.from), rootOf(a.to)];
    const file = /^(.+):\d+(?:-\d+)?$/.exec(a.at ?? "")?.[1];
    if (x && y && file && !owners(cut, file).some((r) => r === x || r === y))
      out.push(`ARROW ${OVERVIEW_ID} ${a.from}→${a.to} cites ${a.at}, a file neither ${x} nor ${y} owns — cite the line in one of theirs where the one reaches the other`);
  }
  out.push(...check({ AUTHORED: roots, OVERVIEW: toOverview(as) }, repo, { generated: true }).problems.filter((p) => p.includes(OVERVIEW_ID)));
  return out;
}

export async function overviewOf(roots: Node[], cut: Cut, inv: Inventory, model: string, onSubmit: (submit: number, problems: number) => void, sums: Record<string, FileSummary> = {}): Promise<Overviewed> {
  const res: Overviewed = { overview: null, turns: 0, submits: 0, problems: [] };
  let last: any = null;

  const handle = (name: string, input: any): Handled => {
    if (name !== "submit") return { content: authorTool({ name, input }) };
    res.submits++;
    // A fix after a rejection may send only what changed; it lands on the last submit.
    const fixes = typeof input?.replace === "string" ? JSON.parse(input.replace) : input?.replace;
    const o = input?.root ?? (Array.isArray(fixes) && last ? Object.assign(structuredClone(last), ...fixes) : null);
    if (o && typeof o === "object") last = structuredClone(o);
    const problems = overviewProblems(o, roots, inv.repo, cut);
    res.problems = problems;
    onSubmit(res.submits, problems.length);
    if (!problems.length) return { content: "Accepted. Stop now.", done: { ...res, overview: toOverview(o) } };
    return { content: `Not accepted. Fix every one of these, then submit the whole overview again with \`root\`:\n- ${problems.slice(0, 40).join("\n- ")}`, isError: true };
  };

  const r = await converse<Overviewed>({ prompt: brief(roots, cut, inv, sums), handle, model, stage: "overview", maxTurns: 22, nudge: "Continue: finish by calling submit with the overview as `root`." });
  return { ...(r.value ?? res), turns: r.turns };
}

app/scripts/generate/pipeline.ts:
/**
 * The whole generator, stage by stage. Lives in a .ts module rather than the
 * .mts entry point so every stage shares one instance of bedrock.ts: tsx loads
 * .mts as ESM and .ts as CommonJS, and two instances meant the cache and the
 * bill were set in one and read from the other.
 */
import { existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import type { Node, Run } from "@/lib/bluprint/schema";
import type { BluprintFile, Overview } from "@/lib/bluprint/build";
import type { Progress } from "@/lib/server/vault";
import { parseArgs } from "./args";
import { auditMarkdown } from "./audit";
import { coverage } from "@/lib/bluprint/coverage";
import { authorRoot, authorSplit, inParts, submitLine, tooBig, type Authored, type OnSubmit } from "./author";
import { catalogOf } from "./catalog";
import { BACKEND, bill, MODELS, cacheIn, sweepCache, throttle, UsageLimitError } from "./bedrock";
import { ccClose, type Turn } from "./claude-code";
import { deepOverview, deepRoot } from "./deep";
import { fastBluprint } from "./fast";
import { arrowStats, check, dedupeIssues, EXPLAIN_LEVEL, OVERVIEW_ID } from "./check";
import { cutRepo, place, unclaimed, type Cut } from "./cut";
import { activeGraph, buildGraph, setGraph, withSummaries } from "./graph";
import { inventory, isSource, scopeTo, type Inventory } from "./inventory";
import { overviewOf, toOverview, type Overviewed } from "./overview";
import { shapeProblems } from "./schema";
import { summarize, type FileSummary } from "./summarize";
import { MAPPER_VERSION } from "./version";

/** Written whole and renamed into place, so the app never parses half a file. */
function atomic(path: string, body: string) {
  const tmp = `${path}.${process.pid}.tmp`;
  writeFileSync(tmp, body);
  renameSync(tmp, path);
}

/** A cut as cached before D60 carried edges between roots; the overview draws those now. */
function withoutEdges(cut: Cut & { edges?: unknown }): Cut {
  delete cut.edges;
  return cut;
}

/**
 * The overview of a finished bluprint, drawn again from the code: for a bluprint made
 * before D60, whose top level was the cut's uncited path, or one whose roots
 * moved. The cut is the cached one when there is one; otherwise each root owns
 * the files its own levels cite, which is all the overview reads it for.
 */
async function redraw(out: string, inv: ReturnType<typeof inventory>, model: string) {
  const bluprint: BluprintFile = JSON.parse(readFileSync(`${out}/bluprint.json`, "utf8"));
  const cited = (n: Node): string[] => [...(n.code ?? []).map((c) => c.file), ...(n.children ?? []).flatMap(cited)];
  const cut: Cut = existsSync(`${out}/.cache/cut.json`)
    ? withoutEdges(JSON.parse(readFileSync(`${out}/.cache/cut.json`, "utf8")))
    : { about: "", excluded: [], roots: bluprint.AUTHORED.map((r) => ({ id: r.id, prefix: "", title: r.title, sub: r.sub, why: "", files: [...new Set(cited(r))] })) };
  const problems = await redrawOverview(bluprint, cut, inv, model);
  if (!problems) atomic(`${out}/bluprint.json`, JSON.stringify(bluprint, null, 1) + "\n");
  console.log(`${out}/bluprint.json — overview ${problems ? `not accepted: ${problems.slice(0, 5).join("; ")}` : "redrawn"}, $${Object.values(bill).reduce((a, b) => a + b.usd, 0).toFixed(2)}`);
  await ccClose();
}

/** Draws `bluprint`'s top level again from its roots as they are, in place; the checker's last word if it was not accepted. */
export async function redrawOverview(bluprint: BluprintFile, cut: Cut, inv: Inventory, model: string, sums: Record<string, FileSummary> = {}): Promise<string[] | null> {
  const drawn = await overviewOf(bluprint.AUTHORED, cut, inv, model, (n, problems) => console.log(`  overview: submit ${n} — ${problems ? `${problems} problems` : "clean"}`), sums);
  if (!drawn.overview) return drawn.problems;
  const node = { ...drawn.overview, id: OVERVIEW_ID, title: "Overview", sub: drawn.overview.sub ?? "", col: 0, row: 0 };
  const top = toOverview(node);
  if (EXPLAIN_LEVEL === "none") for (const k of ["explain", "glossary"] as const) delete top[k];
  bluprint.OVERVIEW = top;
  return null;
}

export type RootStatus = Progress["roots"][number]["status"];

/**
 * A bluprint asked to explain nothing (D70) keeps nothing explained: the types the
 * authors read describe `explain`, and measured, they wrote it on half the
 * levels unasked.
 */
/**
 * The check's findings a reader would be misled by — a reference to code
 * that is not there — marked on the level they are about, so the app shows
 * it as partial with the reason instead of as fact. Layout and wording
 * problems stay in the report. A level already partial keeps its reason.
 */
export function flagProblems(roots: Node[], problems: string[]): number {
  const why = (p: string): [string, string] | null => {
    let m = /^(?:CODE|DOCS) (\S+) (\S+):(\d+)-(\d+) out of range \(file has (\d+)\)/.exec(p);
    if (m) return [m[1], `It points at ${m[2]}:${m[3]}-${m[4]}, but that file has ${m[5]} lines, so this reference is wrong.`];
    m = /^(?:CODE|DOCS) (\S+) (\S+) does not exist/.exec(p) ?? /^MISSING (\S+) (\S+)/.exec(p);
    if (m) return [m[1], `It points at ${m[2]}, which is not in the repository.`];
    m = /^(ARROW|STEP) (\S+) .* cites (\S+), which does not exist$/.exec(p);
    if (m) return [m[2], `One of its ${m[1] === "ARROW" ? "arrows" : "steps"} cites ${m[3]}, which is not a line of the code.`];
    m = /^MISMATCH (\S+) (\S+)/.exec(p);
    if (m) return [m[1], `The code shown no longer matches ${m[2]}.`];
    return null;
  };
  const nodes = new Map<string, Node>();
  const index = (n: Node) => (nodes.set(n.id, n), (n.children ?? []).forEach(index));
  roots.forEach(index);
  let flagged = 0;
  for (const p of problems) {
    const w = why(p);
    const n = w && nodes.get(w[0]);
    if (!n || n.state !== "derived") continue;
    Object.assign(n, { state: "partial", unsure: w[1] });
    flagged++;
  }
  return flagged;
}

export function plain(n: Node): Node {
  if (EXPLAIN_LEVEL !== "none") return n;
  const out = { ...n, ...(n.children ? { children: n.children.map(plain) } : {}) };
  delete out.explain;
  return out;
}

/** Seconds, to one decimal. */
const tenths = (x: number) => Math.round(x * 10) / 10;

/**
 * Where one agent's time went, from its timed replies: waiting (tool calls,
 * Claude Code's overhead, reading context), thinking, writing; and how much
 * of it came before its first whole submit and after, in repairs.
 */
function spanOf(log: Turn[]) {
  const sum = (f: (t: Turn) => number, ts = log) => tenths(ts.reduce((a, t) => a + f(t), 0));
  const all = (t: Turn) => t.wait + t.think + t.write;
  const first = log.findIndex((t) => t.did.includes("submit"));
  return {
    turns: log.length,
    seconds: sum(all),
    wait: sum((t) => t.wait),
    think: sum((t) => t.think),
    write: sum((t) => t.write),
    out: sum((t) => t.out),
    thinking: sum((t) => t.thinking),
    toFirstSubmit: first < 0 ? null : sum(all, log.slice(0, first + 1)),
    repairTurns: first < 0 ? 0 : log.length - first - 1,
  };
}

/** A root's timing: one agent's span, or a split root's cut into parts, the parts (run side by side), and its join. */
function timingOf(log: Turn[]) {
  if (!log.some((t) => t.part)) return spanOf(log);
  const parts: Record<string, Turn[]> = {};
  for (const t of log) (parts[t.part!] ??= []).push(t);
  const spans = Object.fromEntries(Object.entries(parts).map(([k, ts]) => [k, spanOf(ts)]));
  // The cut, then the parts side by side, then the join: one after another.
  const { join, cut, ...rest } = spans;
  const wall = tenths((cut?.seconds ?? 0) + Math.max(0, ...Object.values(rest).map((x) => x.seconds)) + (join?.seconds ?? 0));
  return { ...spanOf(log), wall, parts: spans };
}

export async function main(args: string[]) {
  const { opt, has, repo: dir } = parseArgs(args);

  const repo = resolve(dir!);
  const inv = inventory(repo);
  const name = opt("--name") ?? inv.name.toLowerCase();
  // --scope bluprints part of a large repo; the rest stays readable to the authors.
  const scope = opt("--scope")?.split(",");
  if (scope) scopeTo(inv, { paths: scope, focus: opt("--focus") ?? "" });
  const only = opt("--roots")?.split(",");
  const stopAfter = opt("--stop-after");
  const pick = (env: string | undefined, fallback: keyof typeof MODELS = "opus") => MODELS[(env ?? fallback) as keyof typeof MODELS] ?? MODELS[fallback];
  // The parts of a split root draw a bounded piece against a set brief; Sonnet does that at a fraction of Opus.
  const models = {
    summarize: MODELS.haiku,
    cut: pick(process.env.SLOP_CUT),
    author: pick(process.env.SLOP_AUTHOR),
    part: pick(process.env.SLOP_PART, "sonnet"),
    // A leaf's words in a deepened --fast bluprint (deep.ts): its source is in front of it, nothing to find.
    words: pick(process.env.SLOP_WORDS, "sonnet"),
  };

  // --out puts the bluprint elsewhere: the app's project vault (lib/vault.ts), so an
  // imported project's bluprint never lands in this repo's committed examples.
  const out = opt("--out") ?? `bluprints/${name}`;
  mkdirSync(out, { recursive: true });
  cacheIn(`${out}/.cache`, { fresh: has("--fresh") });
  // --overview redraws only the top level of the bluprint that is there (D60).
  // The graph is what every author draws from and what the checker proves arrows against.
  setGraph(await buildGraph(inv));
  if (has("--overview")) return redraw(out, inv, models.author);
  const t0 = Date.now();
  const elapsed: Record<string, number> = {};
  const lap = async <T,>(stage: string, fn: () => Promise<T>): Promise<T> => {
    const t = Date.now();
    const r = await fn();
    elapsed[stage] = Math.round((Date.now() - t) / 1000);
    console.log(`· ${stage} done in ${elapsed[stage]}s — $${(bill[stage]?.usd ?? 0).toFixed(2)}`);
    return r;
  };
  // What the app shows while the run is on: the stage, and once the cut is in,
  // a line per root. A stale file from a previous run would be read as this
  // one's, so the first write happens before any work.
  const progress: Progress = { startedAt: new Date(t0).toISOString(), stage: "summarize", roots: [], ...(has("--fast") ? { fast: true } : {}) };
  // When the stage last changed: the app's time-left guess needs it for the
  // stages that report nothing until they end.
  let stageNow = progress.stage;
  const flush = () => {
    if (progress.stage !== stageNow || !progress.stageAt) [stageNow, progress.stageAt] = [progress.stage, new Date().toISOString()];
    atomic(`${out}/progress.json`, JSON.stringify(progress, null, 1) + "\n");
  };
  // A root's latest submit while it is still being checked, which the app
  // shows dimmed (D69). Its own file, beside the bluprint: it is not the bluprint.
  const drafts: Record<string, Node> = {};
  let drafting = Promise.resolve();
  const writeDrafts = () => (drafting = drafting.then(() => atomic(`${out}/drafts.json`, JSON.stringify(drafts) + "\n")));
  const mark = (id: string, status: RootStatus, detail?: string) => {
    const r = progress.roots.find((x) => x.id === id);
    if (!r) return;
    r.status = status;
    r.detail = detail;
    flush();
  };
  flush();

  const say = (s: string) => console.log(`  ${s}`);
  // Each submit's verdict is the one in-flight fact an author reports, so
  // "revising" is all the app can say of a root being drafted.
  const submitted = (id: string, prefix: string): OnSubmit => (n, list, draft, fixed) => {
    const problems = list.length;
    say(submitLine(id, n, list, fixed));
    if (problems) mark(id, "drafting", `revising — ${problems} problem${problems === 1 ? "" : "s"}`);
    // Only a tree the page can draw: one whose shape holds, whatever its claims.
    if (problems && draft && !shapeProblems(structuredClone(draft), prefix).length) {
      drafts[id] = draft as Node;
      void writeDrafts();
    }
  };

  const code = inv.files.filter(isSource);
  console.log(`${inv.name} @ ${inv.commit}: ${inv.files.length} files, ${code.length} to summarise, marks [${inv.marks.join(", ")}]`);

  // The reading, file by file, for the app to show while it waits (D69).
  // Written at most four times a second: a cached run reads hundreds at once.
  const reading = { files: code.map((f) => f.path), read: [] as string[], recent: [] as { path: string; purpose: string }[] };
  progress.reading = reading;
  flush();
  let flushed = 0;
  const sums = await lap("summarize", () =>
    summarize(inv, (n, of, path, purpose) => {
      if (n % 25 === 0 || n === of) say(`summarised ${n}/${of}`);
      reading.read.push(path);
      if (purpose) reading.recent = [{ path, purpose }, ...reading.recent].slice(0, 8);
      if (n === of || Date.now() - flushed > 250) {
        flushed = Date.now();
        flush();
      }
    }),
  );
  writeFileSync(`${out}/.cache/summaries.json`, JSON.stringify(sums, null, 1));
  // The one model reading of the code, laid onto the graph: what each file is for and each function does.
  withSummaries(activeGraph()!, sums);
  writeFileSync(`${out}/graph.json`, JSON.stringify(activeGraph()) + "\n");
  if (stopAfter === "summarize") return;
  // --fast: the four-phase bluprint (fast.ts) in place of the cut, the authors and
  // the overview; then, unless --no-deepen, each of its sections written in
  // full by the authors, in reading order, a section the reader has open first.
  if (has("--fast")) {
    progress.stage = "author";
    flush();
    const deepen = !has("--no-deepen");
    const agentDeepen = has("--deepen-agent");
    const run: Run = { command: `bluprint make ${inv.name} --fast`, mapperVersion: MAPPER_VERSION, repo: inv.scope ? name : inv.name, commit: inv.commit, files: code.length, elapsed: "", root: repo, explain: deepen ? EXPLAIN_LEVEL : "none", models };
    const r = await lap("fast", () => fastBluprint(inv, sums, activeGraph()!, models.author, run, say));
    const quick = Math.round((Date.now() - t0) / 1000);
    r.bluprint.RUN.elapsed = `${Math.max(1, Math.round(quick / 60))} min`;
    atomic(`${out}/bluprint.json`, JSON.stringify(r.bluprint, null, 1) + "\n");
    writeFileSync(`${out}/arch.json`, JSON.stringify(r.arch, null, 1) + "\n");
    console.log(`\n${out}/bluprint.json — ${r.bluprint.AUTHORED.length} components, ${r.checkProblems.length} check problems, ${r.discrepancies.length} discrepancies, ${quick}s`);
    for (const d of r.discrepancies) console.log(`  discrepancy: ${d}`);
    for (const p of r.checkProblems.slice(0, 30)) console.log(`  check: ${p}`);

    // The components as a cut, so the authors (and later updates, update.ts) read them as roots.
    const fastCut: Cut = {
      about: r.bluprint.OVERVIEW?.detail ?? "",
      roots: r.bluprint.AUTHORED.map((n) => {
        const c = r.arch.components.find((x) => x.id === n.id)!;
        return { id: n.id, prefix: c.prefix, title: n.title, sub: n.sub, why: n.detail ?? "", files: c.files };
      }),
      excluded: [],
    };
    writeFileSync(`${out}/.cache/cut.json`, JSON.stringify(fastCut, null, 1));
    atomic(`${out}/index.json`, JSON.stringify(catalogOf(inv, sums, fastCut)) + "\n");

    const deep: Record<string, Authored> = {};
    let overviewReport: { redrawn: boolean; problems: string[] } | undefined;
    if (deepen) {
      progress.stage = "deepen";
      progress.roots = fastCut.roots.map((x) => ({ id: x.id, title: x.title, sub: x.sub, status: "queued" as RootStatus, detail: "quick version" }));
      flush();
      const bluprint = r.bluprint;
      let writing = Promise.resolve();
      const save = () => {
        const body = JSON.stringify(bluprint, null, 1) + "\n";
        writing = writing.then(() => atomic(`${out}/bluprint.json`, body));
        return writing;
      };
      // The reader's open section, which the app writes when they open a quick one (lib/vault.ts, focus).
      const focused = () => {
        try {
          return (JSON.parse(readFileSync(`${out}/focus.json`, "utf8")) as { id?: string }).id;
        } catch {
          return undefined;
        }
      };
      const queue = fastCut.roots.map((x) => x.id);
      const next = () => {
        const f = focused();
        const i = f ? queue.indexOf(f) : -1;
        return queue.splice(i >= 0 ? i : 0, 1)[0];
      };
      // Out of usage: what is not written yet keeps its quick version, said so on it, and the bluprint stays usable.
      let outOfUsage = "";
      const keepQuick = (id: string, why: string) => {
        const n = bluprint.AUTHORED.find((x) => x.id === id);
        if (n) Object.assign(n, { state: "partial", unsure: `Not written in full: ${why}. This is the quick version, laid out by folder with short words.` });
      };
      const one = async (id: string) => {
        const root = fastCut.roots.find((x) => x.id === id)!;
        mark(id, "drafting", "writing in full");
        let done: Authored;
        // Code builds the section and a model writes its words (deep.ts); --deepen-agent writes it with an author agent, as before.
        if (!agentDeepen)
          // A section whose calls all fail keeps its quick version, as a failed author does.
          done = await deepRoot(root, r.bluprint.AUTHORED.find((n) => n.id === id)!, inv, sums, activeGraph()!, { group: models.author, words: models.words }, say).catch((e: Error) => {
            if (e instanceof UsageLimitError) {
              outOfUsage ||= e.message;
              queue.length = 0;
            }
            return { root: null, turns: 0, reads: 0, submits: 0, problems: [e.message.slice(0, 300)], trail: [] };
          });
        else if (tooBig(root, fastCut, inv, sums)) {
          const split = await authorSplit(root, fastCut, inv, sums, { cut: models.cut, part: models.part, join: models.author }, null, { submit: submitted(id, root.prefix), part: () => {}, say });
          done = split?.authored ?? (await authorRoot(root, fastCut, inv, sums, models.author, submitted(id, root.prefix)));
        } else done = await authorRoot(root, fastCut, inv, sums, models.author, submitted(id, root.prefix));
        deep[id] = done;
        delete drafts[id];
        void writeDrafts();
        if (done.root) {
          // In the quick one's place: same id and row, so the overview's boxes still open it.
          const i = bluprint.AUTHORED.findIndex((n) => n.id === id);
          bluprint.AUTHORED[i] = { ...plain(done.root), col: 0, row: i };
          dedupeIssues(bluprint.AUTHORED[i]);
          await save();
          mark(id, "done", done.fellBack ? `written in full, ${done.fellBack} part${done.fellBack === 1 ? "" : "s"} kept quick` : "written in full");
          say(`${id}: written in full after ${done.turns + 1} ${agentDeepen ? "turns" : "calls"}${done.fellBack ? `, ${done.fellBack} parts kept quick` : ""}`);
        } else {
          keepQuick(id, outOfUsage ? "the Claude usage ran out" : "its words could not be written in this run");
          await save();
          mark(id, "failed", outOfUsage ? "not written — usage ran out" : "kept the quick version");
          say(`${id}: kept the quick version — ${done.problems.length} problems unresolved`);
        }
      };
      // A section in words is a few short calls, so all of them at once; an agent per section, three.
      const AT_ONCE = Number(process.env.SLOP_DEEPEN_AT_ONCE ?? (agentDeepen ? 3 : queue.length));
      await lap("deepen", () =>
        Promise.all(
          Array.from({ length: Math.min(AT_ONCE, queue.length) }, async () => {
            for (let id = next(); id; id = next()) await one(id);
          }),
        ),
      );
      if (outOfUsage) {
        for (const x of progress.roots.filter((x) => x.status === "queued")) {
          keepQuick(x.id, "the Claude usage ran out");
          mark(x.id, "failed", "not written — usage ran out");
        }
        await save();
        say(`Stopped deepening: ${outOfUsage}`);
      }
      await writing;
      await drafting;
      rmSync(`${out}/drafts.json`, { force: true });
      rmSync(`${out}/focus.json`, { force: true });

      // The top level drawn again over the sections as written in full, as the
      // full pipeline draws it (D60): its explainer, glossary and walkthroughs,
      // which the quick bluprint has none of. If it fails the quick one stays.
      progress.stage = "overview";
      flush();
      const drawn: Overviewed = outOfUsage
        ? { overview: null, turns: 0, submits: 0, problems: ["skipped: the Claude usage ran out"] }
        : agentDeepen
        ? await lap("overview", () => overviewOf(bluprint.AUTHORED, fastCut, inv, models.author, (n, problems) => say(`overview: submit ${n} — ${problems ? `${problems} problems` : "clean"}`), sums))
        : await lap("overview", async () => {
            try {
              const o = await deepOverview(bluprint.AUTHORED, bluprint.OVERVIEW!, inv, activeGraph()!, models.author);
              return { overview: o.overview, turns: 0, submits: 1, problems: o.problems };
            } catch (e) {
              return { overview: null, turns: 0, submits: 0, problems: [(e as Error).message.slice(0, 300)] };
            }
          });
      if (drawn.overview) {
        const top = { ...drawn.overview };
        if (EXPLAIN_LEVEL === "none") for (const k of ["explain", "glossary"] as const) delete top[k];
        bluprint.OVERVIEW = top;
        atomic(`${out}/bluprint.json`, JSON.stringify(bluprint, null, 1) + "\n");
      }
      overviewReport = { redrawn: Boolean(drawn.overview), problems: drawn.problems.slice(0, 20) };
      say(`overview: ${drawn.overview ? "redrawn" : "kept the quick one"} after ${drawn.turns + 1} turns`);
    }

    const total = Math.round((Date.now() - t0) / 1000);
    const final = check(r.bluprint, repo, { generated: true });
    const flagged = flagProblems(r.bluprint.AUTHORED, final.problems);
    if (flagged) say(`${flagged} level${flagged === 1 ? "" : "s"} marked partial for code references that are not there`);
    r.bluprint.RUN.elapsed = `${Math.max(1, Math.round(total / 60))} min`;
    atomic(`${out}/bluprint.json`, JSON.stringify(r.bluprint, null, 1) + "\n");
    const usd = Object.values(bill).reduce((a, b) => a + b.usd, 0);
    writeFileSync(
      `${out}/report.json`,
      JSON.stringify(
        {
          repo: inv.name,
          commit: inv.commit,
          mapperVersion: MAPPER_VERSION,
          backend: BACKEND,
          mode: deepen ? `fast, then deepened${agentDeepen ? " by agents" : " in words"}` : "fast",
          models,
          elapsed: { ...elapsed, ...r.timing, quick, total },
          usd: Math.round(usd * 100) / 100,
          bill,
          components: r.arch.components.map((c) => ({ id: c.id, dir: c.dir, files: c.files.length })),
          discrepancies: r.discrepancies,
          quickCheck: { problems: r.checkProblems },
          check: { problems: final.problems },
          ...(overviewReport ? { overview: overviewReport } : {}),
          deepened: Object.entries(deep).map(([id, a]) => ({ id, accepted: Boolean(a.root), turns: a.turns + 1, submits: a.submits, ...(a.fellBack ? { fellBack: a.fellBack } : {}), lastProblems: a.problems.slice(0, 20), ...(a.log?.length ? { timing: timingOf(a.log) } : {}) })),
        },
        null,
        1,
      ) + "\n",
    );
    progress.stage = "done";
    flush();
    if (deepen) console.log(`\ndeepened ${Object.values(deep).filter((a) => a.root).length}/${fastCut.roots.length} sections; ${final.problems.length} check problems; $${usd.toFixed(2)}, quick bluprint at ${quick}s, done at ${total}s`);
    await ccClose();
    return;
  }
  progress.stage = "cut";
  flush();

  // A re-run keeps the cut of the bluprint that is there unless asked for a fresh
  // one: a new cut could rename every root. Code added since that no root
  // claims is placed in it (cut.ts, place) rather than cut again, so only the
  // roots that gain files are redone. Edges of a cut made before D60 are
  // dropped; the overview draws how roots connect now.
  const cached: Cut | null = !has("--fresh") && existsSync(`${out}/.cache/cut.json`) ? withoutEdges(JSON.parse(readFileSync(`${out}/.cache/cut.json`, "utf8"))) : null;
  const cutReused = Boolean(cached);
  let cut: Cut, leftover: string[] = [], rejected: string[][] = [];
  if (cached) {
    const added = unclaimed(cached, inv);
    if (added.length) {
      say(`${added.length} files the cut does not claim (${added.slice(0, 3).join(", ")}${added.length > 3 ? ", …" : ""}); placing them`);
      const placed = await lap("cut", () => place(cached, added, inv, sums, models.cut));
      for (const [id, files] of placed.gained) say(`${id} takes ${files.join(", ")}`);
      for (const r of placed.added) say(`new root ${r.id}: ${r.files.join(", ")}`);
      cut = placed.cut;
    } else cut = cached;
  } else ({ cut, leftover, rejected } = await lap("cut", () => cutRepo(inv, sums, models.cut)));
  writeFileSync(`${out}/.cache/cut.json`, JSON.stringify(cut, null, 1));
  const index = catalogOf(inv, sums, cut);
  atomic(`${out}/index.json`, JSON.stringify(index) + "\n");
  for (const r of cut.roots) say(`${r.id.padEnd(18)} ${r.title} — ${r.files.length} paths`);
  if (leftover.length) say(`${leftover.length} files left unassigned after three rounds`);
  if (stopAfter === "cut") return;

  // A re-run with --roots reuses the roots it is not asked to redo.
  const prev: BluprintFile | null = only && existsSync(`${out}/bluprint.json`) ? JSON.parse(readFileSync(`${out}/bluprint.json`, "utf8")) : null;
  const authored: Record<string, Authored> = {};
  let overview: Overview | undefined;

  /**
   * The authored roots as a bluprint file. The row is the root's place in the cut,
   * not its place among those done, so a root arriving never moves the ones
   * already on screen. Until the overview is drawn the top level lists them.
   */
  const assemble = (run: Run): BluprintFile => {
    const AUTHORED = cut.roots.flatMap((r, i) => {
      const n = authored[r.id]?.root;
      return n ? [{ ...plain(n), col: 0, row: i }] : [];
    });
    const top = overview && { ...overview };
    if (top && EXPLAIN_LEVEL === "none") for (const k of ["explain", "glossary"] as const) delete top[k];
    return { RUN: run, ...(top ? { OVERVIEW: top } : {}), AUTHORED };
  };

  // The parts each split root was cut into, kept as the top cut is (see above).
  const subcuts: Record<string, Cut> = !has("--fresh") && existsSync(`${out}/.cache/subcuts.json`) ? JSON.parse(readFileSync(`${out}/.cache/subcuts.json`, "utf8")) : {};

  progress.stage = "author";
  progress.roots = cut.roots.map((r) => ({ id: r.id, title: r.title, sub: r.sub, status: "queued" as RootStatus, detail: "queued" }));
  flush();

  // The RUN of a bluprint still being made: the same facts as the final one, with
  // the time so far in place of the total the run does not have yet.
  const runNow = (): Run => ({
    command: `bluprint make ${inv.name}`,
    mapperVersion: MAPPER_VERSION,
    // A scoped bluprint is named for its part and counts only the files it covers.
    repo: inv.scope ? name : inv.name,
    commit: inv.commit,
    files: inv.scope ? code.length : inv.files.length,
    elapsed: `${Math.round((Date.now() - t0) / 60000)} min`,
    root: repo,
    explain: EXPLAIN_LEVEL,
    models,
    ...(inv.scope ? { scope: inv.scope } : {}),
  });

  // The roots are authored concurrently, so their partial writes are chained:
  // each waits for the previous rename. Latest-wins would be enough for the
  // file's content, but the chain also keeps progress.json and bluprint.json from
  // disagreeing about which roots exist.
  let writing = Promise.resolve();
  const partial = () => {
    const bluprint = assemble(runNow());
    writing = writing.then(() => atomic(`${out}/bluprint.json`, JSON.stringify(bluprint, null, 1) + "\n"));
    return writing;
  };

  // Nothing re-reads an accepted root: its arrows were proven against the graph when it was submitted.
  const onAccept = (id: string, root: Node) => {
    if (only && !only.includes(id)) return;
    dedupeIssues(root);
  };

  await lap("author", () =>
    Promise.all(
      cut.roots.map(async (r) => {
        const kept = prev?.AUTHORED.find((n) => n.id === r.id);
        if (only && !only.includes(r.id) && kept) {
          authored[r.id] = { root: kept, turns: 0, reads: 0, submits: 0, problems: [], trail: [] };
          mark(r.id, "done", "kept");
          await partial();
          return;
        }
        mark(r.id, "drafting", "drafting");
        // A root too big for one agent is cut as the repository is; one past SLOP_PARALLEL_FILES is outlined quickly, so its parts are written side by side.
        const big = tooBig(r, cut, inv, sums);
        if (big || inParts(r, cut, inv, sums)) {
          mark(r.id, "drafting", "splitting into parts");
          const split = await authorSplit(r, cut, inv, sums, { cut: models.cut, part: models.part, join: models.author }, subcuts[r.id] ?? null, {
            submit: submitted(r.id, r.prefix),
            // The parts as they come back, under a placeholder of the root, shown dimmed until its own level is written.
            part: (draft) => {
              if (shapeProblems(structuredClone(draft), r.prefix).length) return;
              drafts[r.id] = draft;
              void writeDrafts();
              mark(r.id, "drafting", `${draft.children?.length ?? 0} parts written`);
            },
            say,
          }, !big);
          if (split) {
            subcuts[r.id] = split.cut;
            writeFileSync(`${out}/.cache/subcuts.json`, JSON.stringify(subcuts, null, 1));
          }
          authored[r.id] = split?.authored ?? (await authorRoot(r, cut, inv, sums, models.author, submitted(r.id, r.prefix)));
        } else authored[r.id] = await authorRoot(r, cut, inv, sums, models.author, submitted(r.id, r.prefix));
        delete drafts[r.id];
        void writeDrafts();
        const cov = authored[r.id].coverage;
        say(`${r.id}: ${authored[r.id].root ? "accepted" : "FAILED"} after ${authored[r.id].turns + 1} turns, ${authored[r.id].reads} reads${cov ? `, ${cov.symbols - cov.gaps.length}/${cov.symbols} symbols explained` : ""}`);
        // Accepted means it already passed, inside authorRoot's submit, the
        // same check() the finished bluprint passes — so showing it now shows
        // nothing a finished root would not.
        if (authored[r.id].root) {
          mark(r.id, "done", "explorable now");
          await partial();
          onAccept(r.id, authored[r.id].root!);
        } else mark(r.id, "failed", `${authored[r.id].problems.length} problems unresolved`);
      }),
    ),
  );
  await writing;
  await drafting;
  rmSync(`${out}/drafts.json`, { force: true });

  // The top level is drawn last, from the roots as accepted (D60). A repair
  // that leaves the same roots standing keeps the overview it had.
  const accepted = cut.roots.flatMap((r) => (authored[r.id].root ? [authored[r.id].root!] : []));
  const same = (o: BluprintFile | null) => o?.OVERVIEW && o.AUTHORED.map((n) => n.id).join() === accepted.map((n) => n.id).join();
  let drawn: Overviewed | null = null;
  if (same(prev)) overview = prev!.OVERVIEW;
  else if (accepted.length) {
    progress.stage = "overview";
    flush();
    drawn = await lap("overview", () => overviewOf(accepted, cut, inv, models.author, (n, problems) => say(`overview: submit ${n} — ${problems ? `${problems} problems` : "clean"}`), sums));
    overview = drawn.overview ?? undefined;
    say(`overview: ${overview ? "accepted" : "FAILED"} after ${drawn.turns + 1} turns`);
    await partial();
  }

  // A stage replayed wholly from cache took seconds and cost nothing, not what
  // generating it costs; the last report's time and bill for it stand, so the
  // record stays a plan.
  const last = existsSync(`${out}/report.json`) ? JSON.parse(readFileSync(`${out}/report.json`, "utf8")) : null;
  const before = last?.elapsed ?? {};
  const spent = { ...bill };
  let total = Math.round((Date.now() - t0) / 1000);
  for (const stage of Object.keys(elapsed)) {
    const runs = Object.entries(bill).filter(([k]) => k === stage || k.startsWith(`${stage}-`));
    if (runs.length && runs.every(([, b]) => b.calls === b.cached) && typeof before[stage] === "number") {
      total += before[stage] - elapsed[stage];
      elapsed[stage] = before[stage];
      for (const [k] of runs) if (last.bill?.[k]) spent[k] = last.bill[k];
    }
  }
  const bluprint = assemble({ ...runNow(), elapsed: `${Math.round(total / 60)} min` });
  const { AUTHORED } = bluprint;
  const final = check(bluprint, repo, { generated: true });
  const covered = coverage(index, AUTHORED);
  atomic(`${out}/bluprint.json`, JSON.stringify(bluprint, null, 1) + "\n");
  progress.stage = "done";
  flush();

  const usd = Object.values(spent).reduce((a, b) => a + b.usd, 0);
  const fullUsd = Object.values(spent).reduce((a, b) => a + b.fullUsd, 0);
  const report = {
    repo: inv.name,
    commit: inv.commit,
    mapperVersion: MAPPER_VERSION,
    // Through Claude Code, `usd` is what the same tokens cost at the API list
    // price; on a Claude plan they come out of the plan's usage instead.
    backend: BACKEND,
    models,
    // A --roots repair is not what the bluprint costs to make: the full run's
    // time and price stand, and the repair is listed beside them.
    ...(only && last
      ? { elapsed: last.elapsed, usd: last.usd, fullUsd: last.fullUsd, bill: last.bill, repairs: [...(last.repairs ?? []), { roots: only, seconds: total, usd: Math.round(Object.values(bill).reduce((a, b) => a + b.usd, 0) * 100) / 100, bill }] }
      : { elapsed: { ...elapsed, total }, usd: Math.round(usd * 100) / 100, fullUsd: Math.round(fullUsd * 100) / 100, bill: spent }),
    throttled: { waits: throttle.waits, seconds: Math.round(throttle.seconds) },
    files: { listed: inv.files.length, summarised: code.length, unassigned: leftover },
    excluded: cut.excluded,
    coverage: { symbols: covered.symbols, explained: covered.explained, gaps: covered.gaps.map((g) => `${g.file}: ${g.symbol.name}`) },
    overview: drawn ? { accepted: Boolean(drawn.overview), turns: drawn.turns + 1, submits: drawn.submits, lastProblems: drawn.overview ? [] : drawn.problems.slice(0, 20) } : (overview ? "kept" : null),
    roots: cut.roots.map((r) => ({
      id: r.id,
      title: r.title,
      accepted: Boolean(authored[r.id].root),
      turns: authored[r.id].turns + 1,
      reads: authored[r.id].reads,
      submits: authored[r.id].submits,
      lastProblems: authored[r.id].root ? [] : authored[r.id].problems.slice(0, 20),
      ...(authored[r.id].coverage ? { coverage: { symbols: authored[r.id].coverage!.symbols, unexplained: authored[r.id].coverage!.gaps.length } } : {}),
      ...(authored[r.id].log?.length ? { timing: timingOf(authored[r.id].log!), log: authored[r.id].log } : {}),
    })),
    check: { problems: final.problems, depth: final.roots },
    graph: { ...activeGraph()!.stats, defs: activeGraph()!.defs.length, edges: activeGraph()!.edges.length },
    arrows: arrowStats(bluprint),
  };
  writeFileSync(`${out}/report.json`, JSON.stringify(report, null, 1) + "\n");
  writeFileSync(
    `${out}/audit.md`,
    auditMarkdown({ inv, cut, rejected, leftover, cutReused, authored, drawn, overview, only, backend: BACKEND, models, seconds: total, checkProblems: final.problems }),
  );
  console.log(`\n${out}/bluprint.json — ${AUTHORED.length}/${cut.roots.length} roots, ${final.problems.length} check problems, ${covered.explained}/${covered.symbols} symbols explained, ${report.arrows.inferred}/${report.arrows.total} arrows inferred, $${report.usd} spent ($${report.fullUsd} uncached), ${report.elapsed.total}s`);
  final.problems.slice(0, 20).forEach((p) => console.log(`  ${p}`));
  // Where the writing stage's minutes went, root by root (replayed roots have no log).
  const timed = report.roots.flatMap((r) => (r.timing ? [{ id: r.id, ...r.timing }] : []));
  if (timed.length) {
    console.log(`\nauthor time by root (s): turns · wait / think / write · out tok (thinking) · to first submit · repair turns`);
    for (const t of timed.sort((a, b) => ("wall" in b ? b.wall : b.seconds) - ("wall" in a ? a.wall : a.seconds)))
      console.log(`  ${t.id.padEnd(22)} ${String("wall" in t ? `${t.wall} wall` : t.seconds).padStart(9)} · ${t.turns} turns · ${t.wait} / ${t.think} / ${t.write} · ${t.out} (${t.thinking}) · ${t.toFirstSubmit ?? "never"} · ${t.repairTurns}`);
  }
  // A whole bluprint asked for every reply it still needs; the rest can never replay.
  if (!only) {
    const swept = sweepCache();
    if (swept) console.log(`  swept ${swept} stale cached replies`);
  }
  await ccClose();
}

app/scripts/generate/run.mts:
// usage (from app/): npx -y tsx --tsconfig tsconfig.json scripts/generate/run.mts <repo dir> [--name x] [--out dir] [--fresh] [--roots a,b] [--stop-after summarize|cut] [--scope path,dir/ --focus "who reads it"]
//   writes bluprints/<name>/bluprint.json, report.json and audit.md, how the bluprint was reached (or <out>/…); model replies are cached in bluprints/<name>/.cache/
//   bluprints/ is local output, never committed; the app's Import writes to its own vault with --out instead.
//   SLOP_CLAUDE names the `claude` binary for SLOP_BACKEND=claude-code (default: `claude` on PATH).
// --overview redraws only the bluprint's top level from the code, keeping its roots (D60).
// --story tells the project's history in chapters from its commits (story.ts, D73); needs --out.
// --update redoes only the sections the code changed since the bluprint last looked (see update.ts); SLOP_UPDATE picks its model.
//   SLOP_CUT / SLOP_AUTHOR = haiku|sonnet|opus pick the model for those stages (default opus).
//   AWS credentials come from app/.env.local when it exists (AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY,
//   AWS_BEARER_TOKEN_BEDROCK, AWS_REGION), otherwise from the machine's default AWS profile.
import { existsSync } from "node:fs";

// Before the Bedrock client is imported, so it is built with these.
if (existsSync(".env.local")) process.loadEnvFile(".env.local");
const args = process.argv.slice(2);
try {
  if (args.includes("--update")) await (await import("./update")).update(args);
  else if (args.includes("--story")) await (await import("./story")).story(args);
  else await (await import("./pipeline")).main(args);
} catch (e) {
  // The app shows the log's last lines as why the run failed: the reason, not a stack.
  if (!((e as Error).name === "UsageLimitError")) throw e;
  console.error(`\nStopped: ${(e as Error).message}`);
  process.exit(1);
}

app/scripts/generate/schema.ts:
/**
 * The shape a generated node must have, checked field by field so the author
 * gets a precise list back instead of a renderer crash. The types themselves
 * stay in lib/bluprint/schema.ts — `typeReference` hands the model that file's own text,
 * comments included, because those comments ARE the standard each field is
 * held to.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- validates untrusted model output */
import { readFileSync } from "node:fs";
import type { Node } from "@/lib/bluprint/schema";
import { autofix, check } from "./check";
import { fillFromGraph } from "./fill";
import { activeGraph } from "./graph";

/** lib/bluprint/schema.ts from `State` to its end. */
export function typeReference(): string {
  const src = readFileSync("lib/bluprint/schema.ts", "utf8");
  return src.slice(src.indexOf("export type State"));
}

const STATES = ["derived", "partial", "inferred"];
const KINDS: Record<string, string[]> = {
  diagram: ["caption", "boxes", "arrows"],
  table: ["columns", "rows", "state"],
  sequence: ["actors", "rows"],
  screen: ["title", "items"],
  example: ["caption", "value"],
  schema: ["table", "rows"],
  routes: ["rows"],
  flow: ["rows"],
  facts: ["rows"],
  bars: ["unit", "rows"],
  parts: ["total", "rows"],
  chips: ["rows"],
  bluprint: ["rows"],
};

const isStr = (v: unknown) => typeof v === "string" && v.trim().length > 0;
const isInt = (v: unknown) => Number.isInteger(v);

/**
 * Problems with a node's shape, recursively. Mutates only what has one right
 * answer (`col`/`row` become the child's index) so the model is never asked to
 * spend a round on grid bookkeeping.
 */
export function shapeProblems(node: any, prefix: string, isRoot = true): string[] {
  const out: string[] = [];
  const at = (k: string) => `${node?.id ?? "?"}.${k}`;
  if (!node || typeof node !== "object") return ["node is not an object"];
  if (!isStr(node.id)) out.push(at("id") + " missing");
  else if (!isRoot && !node.id.startsWith(prefix + "-")) out.push(`${node.id}: ids under this root must start with "${prefix}-"`);
  for (const k of ["title", "sub"]) if (!isStr(node[k])) out.push(at(k) + " missing");
  if (!STATES.includes(node.state)) out.push(at("state") + ` must be one of ${STATES.join("/")}`);
  if (node.group && !["sequence", "set"].includes(node.group.ordering)) out.push(at("group.ordering") + " must be sequence or set");
  if (!Array.isArray(node.code)) out.push(at("code") + " must be an array of {file,start,end,label}");
  else node.code.forEach((c: any, i: number) => {
    if (!isStr(c?.file) || !isInt(c?.start) || !isInt(c?.end) || !isStr(c?.label)) out.push(at(`code[${i}]`) + " needs file, start, end (integers), label");
  });
  if (node.docs !== undefined && !Array.isArray(node.docs)) out.push(at("docs") + " must be an array of {file,start,end,label}");
  else (node.docs ?? []).forEach((c: any, i: number) => {
    if (!isStr(c?.file) || !isInt(c?.start) || !isInt(c?.end) || !isStr(c?.label)) out.push(at(`docs[${i}]`) + " needs file, start, end (integers), label");
    else if (!/\.mdx?$/i.test(c.file)) out.push(at(`docs[${i}]`) + ` ${c.file} is not a doc; code goes in code`);
  });
  for (const [i, iss] of (node.issues ?? []).entries())
    if (!isStr(iss?.title) || !isStr(iss?.detail)) out.push(at(`issues[${i}]`) + " needs title and detail");
  out.push(...blockShapeProblems(node.anatomy ?? [], "anatomy", at));
  if (node.explain !== undefined) {
    if (typeof node.explain !== "object" || typeof node.explain.body !== "string") out.push(at("explain") + " must be {body: string, blocks?: Anatomy[]}");
    else if (node.explain.blocks !== undefined && !Array.isArray(node.explain.blocks)) out.push(at("explain.blocks") + " must be an array of blocks");
    else out.push(...blockShapeProblems(node.explain.blocks ?? [], "explain.blocks", at));
  }
  if (node.children !== undefined && !Array.isArray(node.children)) out.push(at("children") + " must be an array");
  (node.children ?? []).forEach((c: any, i: number) => {
    if (c && typeof c === "object") { c.col = 0; c.row = i; }
    out.push(...shapeProblems(c, prefix, false));
  });
  if (isRoot) { node.col = 0; node.row = 0; }
  return out;
}

/** A list of blocks' shape, field by field, wherever on a node it sits. */
function blockShapeProblems(blocks: any[], field: string, at: (k: string) => string): string[] {
  const out: string[] = [];
  for (const [i, b] of blocks.entries()) {
    const need = KINDS[b?.kind];
    if (!need) { out.push(at(`${field}[${i}]`) + ` kind "${b?.kind}" is not one of ${Object.keys(KINDS).join(", ")}`); continue; }
    for (const k of need) if (b[k] === undefined) out.push(at(`${field}[${i}]`) + ` (${b.kind}) missing ${k}`);
    if (b.kind === "diagram") {
      for (const x of b.boxes ?? []) if (!isStr(x?.id) || !isStr(x?.label) || !isInt(x?.col) || !isInt(x?.row)) out.push(at(`${field}[${i}]`) + " diagram box needs id, label, col, row");
      for (const a of b.arrows ?? []) if (!isStr(a?.from) || !isStr(a?.to)) out.push(at(`${field}[${i}]`) + " diagram arrow needs from, to");
    }
    if (b.kind === "table" && (!Array.isArray(b.columns) || !Array.isArray(b.rows) || b.rows.some((r: any) => !Array.isArray(r)))) out.push(at(`${field}[${i}]`) + " table needs columns: string[] and rows: string[][]");
    if (b.kind === "screen" && (b.items ?? []).some((x: any) => !["heading", "text", "field", "choice", "button", "list", "image"].includes(x?.type)))
      out.push(at(`${field}[${i}]`) + " screen item type must be heading/text/field/choice/button/list/image");
    if (b.kind === "screen" && !["phone", "web"].includes(b.device)) out.push(at(`${field}[${i}]`) + ' screen needs device: "phone" or "web" — see the brief');
    if (b.kind === "screen" && b.route !== undefined && !(isStr(b.route) && b.route.startsWith("/")))
      out.push(at(`${field}[${i}]`) + ' screen route is a URL path starting with "/", not a file path');
  }
  return out;
}

/** Every id in a node's subtree, its own included. */
export function idsOf(n: Node, out = new Set<string>()): Set<string> {
  out.add(n.id);
  (n.children ?? []).forEach((c) => idsOf(c, out));
  return out;
}

/**
 * Everything wrong with a submitted node, as the agent gets it back: its
 * shape first (a malformed node would crash the checker), then ids already
 * `taken` elsewhere in the bluprint, then the checks the finished bluprint is held to.
 * A section is checked inside its root (`within` puts it there), and only the
 * problems with its own ids, or duplicate ids, are its to fix.
 */
export function submitProblems(
  node: any,
  prefix: string,
  repo: string,
  opts: { isRoot?: boolean; taken?: Set<string>; within?: (node: Node) => Node; fixed?: string[] } = {},
): string[] {
  // What the graph can fill is filled first: a code ref named by its graph id has no lines for the shape to check.
  const filled = fillFromGraph(node, activeGraph());
  opts.fixed?.push(...filled.notes);
  if (filled.problems.length) return filled.problems;
  const shape = shapeProblems(node, prefix, opts.isRoot ?? true);
  if (shape.length) return shape;
  // Once the shape holds, what has one right answer is fixed, not sent back.
  opts.fixed?.push(...autofix(node, repo));
  const mine = idsOf(node);
  const clash = [...mine].filter((id) => opts.taken?.has(id));
  if (clash.length) return clash.map((id) => `${id}: already used elsewhere in the bluprint`);
  const problems = check({ AUTHORED: [opts.within ? opts.within(node) : node] }, repo, { generated: true }).problems;
  return opts.within ? problems.filter((p) => [...mine].some((id) => p.includes(id)) || p.startsWith("DUP")) : problems;
}

app/scripts/generate/story.ts:
/**
 * The project's history, told in chapters (D73): one structured answer from
 * the commit list the timeline draws (lib/history.ts), checked against it.
 *
 * Only the commits are read — subjects, dates, authors, sizes and the roots
 * each touched — never the code: a chapter names what the history shows, and
 * a commit's subject is the author's own word for it. Each chapter's ends are
 * real commits in order, so a band on the timeline sits exactly over the dots
 * it tells, and a click on it opens that range in diff mode.
 *
 * Writes <out>/story.json, and appends what it cost to report.json the way an
 * update does.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import type { BluprintFile } from "@/lib/bluprint/build";
import { chapterProblems, cutOf, ELSEWHERE, timelineOf, type Chapter, type Story } from "@/lib/server/history";
import { parseArgs } from "./args";
import { ask, bill, cacheIn, MODELS, type Message } from "./bedrock";
import { ccClose } from "./claude-code";

/** The newest commits the model is shown. A longer history is told from its recent part, and says so. */
const SHOWN = 800;

const TOOL = {
  name: "story",
  description: "The history of this repository as chapters, oldest first.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["chapters"],
    properties: {
      chapters: {
        type: "array",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["title", "from", "to", "detail", "roots"],
          properties: {
            title: { type: "string", description: "1-4 words, Title Case, what happened: 'First Bluprint', 'Desktop App', 'Diff Mode'." },
            from: { type: "string", description: "The short sha of the chapter's first commit, exactly as listed." },
            to: { type: "string", description: "The short sha of its last commit, exactly as listed." },
            detail: { type: "string", description: "At most two plain sentences and 40 words: what changed for someone using it, and why if the subjects say." },
            roots: { type: "array", items: { type: "string" }, description: "The ids of the roots this chapter mostly shaped." },
          },
        },
      },
    },
  },
};

export async function story(args: string[]) {
  const { opt, repo: dir } = parseArgs(args);
  const repo = resolve(dir!);
  const out = opt("--out")!;
  const t0 = Date.now();
  const bluprint: BluprintFile = JSON.parse(readFileSync(`${out}/bluprint.json`, "utf8"));
  const t = timelineOf(repo, bluprint, cutOf(out));
  cacheIn(`${out}/.cache`);
  const model = MODELS[(process.env.SLOP_STORY ?? "sonnet") as keyof typeof MODELS] ?? MODELS.sonnet;

  const shown = t.commits.slice(-SHOWN);
  const day = (iso: string) => iso.slice(0, 10);
  const lines = shown.map((c) => `${c.short} ${day(c.at)} ${c.author} +${c.added} −${c.removed} [${c.roots.map((r) => r || "elsewhere").join(",")}] ${c.subject}`);
  const prompt = [
    `# ${bluprint.RUN.repo}: its history, oldest commit first`,
    `## The bluprint's roots\n${t.roots.filter((r) => r.id !== ELSEWHERE).map((r) => `- ${r.id}: ${r.title}`).join("\n")}`,
    `## Commits (${shown.length}${shown.length < t.commits.length ? ` most recent of ${t.commits.length}` : ""}): sha, date, author, lines added and removed, roots touched, subject\n${lines.join("\n")}`,
    `## Task
Tell how this codebase got to where it is, as 3 to 8 chapters in order, each a run of consecutive commits that belong together: a feature arriving, a rewrite, a move to a new platform. Every listed commit falls in exactly one chapter, so the first chapter starts at the first commit and the last ends at the last. Checkpoints ("wip", merges) belong to whatever they sit inside. Name a chapter by what changed, not by when.`,
  ].join("\n\n");

  const messages: Message[] = [{ role: "user", content: prompt }];
  let chapters: Chapter[] = [];
  let problems: string[] = [];
  for (let attempt = 0; attempt < 3; attempt++) {
    const r = await ask<{ chapters: Chapter[] }>({ model, system: "You read a repository's commit history and tell it plainly.", messages, tool: TOOL, stage: "story", maxTokens: 4000 });
    chapters = r.chapters;
    problems = chapterProblems(chapters, { ...t, commits: shown });
    if (!problems.length) break;
    messages.push({ role: "assistant", content: JSON.stringify(r) }, { role: "user", content: `Not accepted. Fix every one of these and answer again:\n- ${problems.join("\n- ")}` });
  }
  await ccClose();
  if (problems.length) {
    console.error(`story: not accepted after 3 attempts:\n- ${problems.join("\n- ")}`);
    process.exitCode = 1;
    return;
  }

  const usd = Math.round(Object.values(bill).reduce((a, b) => a + b.usd, 0) * 100) / 100;
  const seconds = Math.round((Date.now() - t0) / 1000);
  const told: Story = { head: t.head, chapters, at: new Date().toISOString(), usd, seconds };
  writeFileSync(`${out}/story.json`, JSON.stringify(told, null, 1) + "\n");
  if (existsSync(`${out}/report.json`)) {
    const report = JSON.parse(readFileSync(`${out}/report.json`, "utf8"));
    report.stories = [...(report.stories ?? []), { at: told.at, chapters: chapters.length, commits: shown.length, seconds, usd }];
    writeFileSync(`${out}/report.json`, JSON.stringify(report, null, 1) + "\n");
  }
  console.log(`${out}/story.json — ${chapters.length} chapters over ${shown.length} commits, $${usd}, ${seconds}s`);
}

app/scripts/generate/summarize.ts:
/**
 * Stage 1 — one short, structured reading of every source file (Haiku).
 *
 * The cut sees the whole repo only through these, so they record what a file
 * DOES for the product (what it reads, writes, shows, calls), with line ranges
 * the author can jump to. Keyed by content: an unchanged file is never re-read,
 * which is also what an incremental bluprint will need.
 */

import { ask, BACKEND, MODELS, UsageLimitError } from "./bedrock";
import { isSource, numbered, type Inventory, type RepoFile } from "./inventory";

export interface FileSummary {
  path: string;
  purpose: string;
  kind: string;
  symbols: { name: string; start: number; end: number; does: string }[];
  reads: string[];
  writes: string[];
  external: string[];
  user_sees: string;
}

const KINDS = ["screen", "component", "api-route", "server-action", "hook", "state", "data-model", "migration", "query", "lib", "config", "script", "job", "cli", "entry", "types", "other"];

const TOOL = {
  name: "summary",
  description: "Record what this file does.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["purpose", "kind", "symbols", "reads", "writes", "external", "user_sees"],
    properties: {
      purpose: { type: "string", description: "One plain sentence: what this file does for the product or its caller. Not a restatement of the file name." },
      kind: { type: "string", enum: KINDS },
      symbols: {
        type: "array",
        description: "The functions, components, routes, classes or tables that matter, up to 12, with their exact line ranges as numbered.",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["name", "start", "end", "does"],
          properties: { name: { type: "string" }, start: { type: "integer" }, end: { type: "integer" }, does: { type: "string", description: "A few words." } },
        },
      },
      reads: { type: "array", items: { type: "string" }, description: "Data it reads: tables, collections, storage keys, env vars, cookies, files. Concrete names." },
      writes: { type: "array", items: { type: "string" }, description: "Data it writes, same form." },
      external: { type: "array", items: { type: "string" }, description: "Outside services or HTTP endpoints it calls (Stripe, S3, /api/posts)." },
      user_sees: { type: "string", description: "If it renders UI: what a user sees and can do, in one sentence. Otherwise empty." },
    },
  },
};

const SYSTEM = `You read one source file from a repository and record what it does, for someone making a bluprint of the whole codebase.
Be concrete and literal: real table names, real routes, real env var names, real line numbers as shown in the left margin.
Never guess at code you cannot see. Call the summary tool once.`;

/** A file is read this many lines at a time; a longer one in parts, each adding the symbols and data in its lines. */
const MAX_LINES = 1500;

const shown = (inv: Inventory, f: RepoFile) =>
  `File: ${f.path} (${f.lines} lines)${f.lines > MAX_LINES ? `\n(Only lines 1-${MAX_LINES} of ${f.lines} are shown.)` : ""}\n\n${numbered(inv.repo, f.path, 1, MAX_LINES)}`;

async function one(inv: Inventory, f: RepoFile): Promise<FileSummary> {
  try {
    const read = (content: string) => ask<Omit<FileSummary, "path">>({ model: MODELS.haiku, stage: "summarize", maxTokens: 4000, system: SYSTEM, messages: [{ role: "user", content }], tool: TOOL });
    const s = await read(`Repository: ${inv.name}\n${shown(inv, f)}`);
    // The rest of a long file, part by part: a 4,000-line class's later methods are as much the bluprint's as its first.
    const parts = await Promise.all(
      Array.from({ length: Math.ceil(f.lines / MAX_LINES) - 1 }, (_, i) => {
        const start = (i + 1) * MAX_LINES + 1;
        const end = Math.min(f.lines, start + MAX_LINES - 1);
        return read(`Repository: ${inv.name}\nFile: ${f.path} (${f.lines} lines)\nIts lines 1-${start - 1} were read already: ${s.purpose}\nLines ${start}-${end} are shown. Record the symbols, reads, writes and outside calls in these lines; purpose and user_sees may be left empty.\n\n${numbered(inv.repo, f.path, start, end)}`);
      }),
    );
    const union = (k: "reads" | "writes" | "external") => [...new Set([s, ...parts].flatMap((p) => p[k] ?? []))];
    return { path: f.path, ...s, symbols: [s, ...parts].flatMap((p) => p.symbols ?? []), reads: union("reads"), writes: union("writes"), external: union("external") };
  } catch (e) {
    if (e instanceof UsageLimitError) throw e;
    // One unreadable file is a gap the cut is told about, not a failed run.
    return { path: f.path, purpose: `(not summarised: ${(e as Error).message.slice(0, 120)})`, kind: "other", symbols: [], reads: [], writes: [], external: [], user_sees: "" };
  }
}

const MANY = {
  name: "summaries",
  description: "Record what each file shown does.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["files"],
    properties: {
      files: {
        type: "array",
        items: { ...TOOL.input_schema, required: ["path", ...TOOL.input_schema.required], properties: { path: { type: "string", description: "The file's path exactly as shown." }, ...TOOL.input_schema.properties } },
      },
    },
  },
};

/** Lines a batch may carry, and files per batch. */
const BATCH_LINES = 3000;
const BATCH_FILES = 8;

/**
 * Small files in one call, for Claude Code: every `claude -p` pays its own
 * start-up and prompt, which one call per file multiplied by the repository.
 * A file the batch leaves out is summarised on its own.
 */
async function many(inv: Inventory, files: RepoFile[]): Promise<FileSummary[]> {
  let got: FileSummary[] = [];
  if (files.length > 1)
    got = (await ask<{ files: FileSummary[] }>({
      model: MODELS.haiku,
      stage: "summarize",
      system: `${SYSTEM.replace("one source file", "several source files").replace("Call the summary tool once.", "Record every file shown, each by its path.")}`,
      messages: [{ role: "user", content: `Repository: ${inv.name}\n\n${files.map((f) => shown(inv, f)).join("\n\n")}` }],
      tool: MANY,
    }).catch((e) => {
      if (e instanceof UsageLimitError) throw e;
      return { files: [] };
    })).files.filter((x) => files.some((f) => f.path === x.path));
  const left = files.filter((f) => !got.some((x) => x.path === f.path));
  return [...got, ...(await Promise.all(left.map((f) => one(inv, f))))];
}

/** `onDone` hears each file as it is read, with what it is for, so the app can show the reading as it happens. */
export async function summarize(
  inv: Inventory,
  onDone: (n: number, of: number, path: string, purpose?: string) => void,
): Promise<Record<string, FileSummary>> {
  const todo = inv.files.filter(isSource);
  const batches: RepoFile[][] = [];
  for (const f of todo) {
    const b = batches[batches.length - 1];
    const lines = (x: RepoFile) => Math.min(x.lines, MAX_LINES);
    if (BACKEND === "claude-code" && f.lines <= MAX_LINES && b && b.length < BATCH_FILES && b.every((x) => x.lines <= MAX_LINES) && b.reduce((a, x) => a + lines(x), 0) + lines(f) <= BATCH_LINES) b.push(f);
    else batches.push([f]);
  }
  const out: Record<string, FileSummary> = {};
  let n = 0;
  await Promise.all(
    batches.map(async (b) => {
      for (const s of b.length > 1 ? await many(inv, b) : [await one(inv, b[0])]) out[s.path] = s;
      for (const f of b) onDone(++n, todo.length, f.path, out[f.path]?.purpose);
    }),
  );
  return Object.fromEntries(Object.keys(out).sort().map((k) => [k, out[k]]));
}

/** One line per file — the form the cut reads the whole repo in. */
export function oneLine(s: FileSummary): string {
  const io = [
    s.reads.length ? `reads ${s.reads.slice(0, 4).join(", ")}` : "",
    s.writes.length ? `writes ${s.writes.slice(0, 4).join(", ")}` : "",
    s.external.length ? `calls ${s.external.slice(0, 3).join(", ")}` : "",
  ].filter(Boolean).join("; ");
  return `${s.path} [${s.kind}] ${s.purpose}${io ? ` (${io})` : ""}`;
}

/** A file's summary with its symbols, the form an author reads its own files in. */
export function full(s: FileSummary): string {
  const syms = s.symbols.map((x) => `    ${x.start}-${x.end} ${x.name}: ${x.does}`).join("\n");
  return `${oneLine(s)}${s.user_sees ? `\n    user sees: ${s.user_sees}` : ""}${syms ? `\n${syms}` : ""}`;
}

/** A directory folded into one line: its size, what kinds of file it holds, and its largest files' purposes. */
function folded(dir: string, files: RepoFile[], sums: Record<string, FileSummary>): string {
  const kinds = new Map<string, number>();
  for (const f of files) {
    const k = sums[f.path]?.kind ?? "other";
    kinds.set(k, (kinds.get(k) ?? 0) + 1);
  }
  const mix = [...kinds].sort((a, b) => b[1] - a[1]).slice(0, 3).map(([k, n]) => `${n} ${k}`).join(", ");
  const lines = files.reduce((a, f) => a + f.lines, 0);
  const largest = [...files]
    .sort((a, b) => b.lines - a.lines)
    .slice(0, 3)
    .map((f) => `${f.path.slice(dir.length + 1)}: ${(sums[f.path]?.purpose ?? "").slice(0, 90)}`)
    .join("; ");
  return `${dir}/ (${files.length} files, ${lines} lines: ${mix}) — largest: ${largest}`;
}

const parentOf = (p: string) => (p.includes("/") ? p.slice(0, p.lastIndexOf("/")) : "");

/**
 * The files one line each (`line`), unless that is more than `budget`
 * characters: then whole directories are folded into one line apiece
 * (`dir/ (N files …)`), deepest and largest first, until it fits. A large
 * repository is still seen whole, with detail where the tree is shallow,
 * rather than failing a prompt that cannot hold one line per file. Says
 * whether anything was folded, so a prompt can tell its reader how to read it.
 */
export function fit(
  files: RepoFile[],
  sums: Record<string, FileSummary>,
  line: (f: RepoFile) => string,
  budget: number,
): { text: string; folded: boolean } {
  type Entry = { key: string; dir: string; text: string; files: RepoFile[] };
  let entries: Entry[] = files.map((f) => ({ key: f.path, dir: parentOf(f.path), text: line(f), files: [f] }));
  let size = entries.reduce((a, e) => a + e.text.length + 1, 0);
  let any = false;
  while (size > budget) {
    const groups = new Map<string, Entry[]>();
    for (const e of entries) if (e.dir) groups.set(e.dir, [...(groups.get(e.dir) ?? []), e]);
    // The deepest directory first, and of those the one costing most: the top
    // of the tree is what a reader cuts by, so it keeps its detail longest.
    const depth = (d: string) => d.split("/").length;
    const cost = (es: Entry[]) => es.reduce((a, e) => a + e.text.length, 0);
    const pick = [...groups].sort(([a, x], [b, y]) => depth(b) - depth(a) || cost(y) - cost(x))[0];
    if (!pick) break;
    const [dir, inside] = pick;
    const all = inside.flatMap((e) => e.files);
    const one: Entry = { key: `${dir}/`, dir: parentOf(dir), text: folded(dir, all, sums), files: all };
    entries = [...entries.filter((e) => !inside.includes(e)), one];
    size += one.text.length - cost(inside);
    any = true;
  }
  return { text: entries.sort((a, b) => a.key.localeCompare(b.key)).map((e) => e.text).join("\n"), folded: any };
}

app/scripts/generate/update.ts:
/**
 * Keeping a bluprint up with its code, a few sections at a time.
 *
 * A full run bluprints a checkout once. After that, code moves: an agent edits a
 * file, a user saves one. An update finds what changed since the bluprint last
 * looked, and redoes only the sections it touches:
 *
 *   1. What changed: every file whose text differs from what the bluprint was made
 *      from — the bluprint's commit, or the copy this kept at the last update
 *      (<out>/base.json), new and deleted files included.
 *   2. Every line reference in the bluprint moves with the code (a ref below an
 *      inserted line shifts down), so the sections left alone stay true.
 *   3. The sections touched: the deepest ones whose own references overlap a
 *      changed line. A change no reference covers goes to the section nearest
 *      it in that file, or, for a new file, in its root's directory. A file no
 *      root claims is first placed in the cut (cut.ts, place): in the root
 *      whose work it does, which is then redone with it, or in a new root,
 *      written whole as a full run writes one, with the overview redrawn.
 *   4. One agent per touched section rewrites it, seeing the diff and the old
 *      section, able to read only the changed files, what they import and
 *      what imports them, and the files the section already cites. It is
 *      checked as a full run's root is, then verified.
 *   5. The sections go back in place. One that could not be redone stays, its
 *      references moved, marked partial with the reason; one whose code is
 *      gone is taken out.
 *
 * The coding agent's turns that asked for the update wait in
 * <out>/turns.json (lib/vault.ts). Each brings its transcript — what the
 * agent did and why, so a fix or a deletion is redone knowing it was one —
 * and the sections it reported wrong with slop-bluprint-fix, which are redone
 * with its notes even where no code changed.
 *
 * Writes <out>/bluprint.json, <out>/bluprint.base.json (once, before the first update), <out>/base.json, <out>/update.json (what this run
 * did, read by the app) and adds the run to <out>/report.json's `updates`.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- model tool inputs */
import { existsSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { basename, join, resolve } from "node:path";
import type { Node } from "@/lib/bluprint/schema";
import { lastExchange } from "@/lib/agent/keep";
import type { BluprintFile } from "@/lib/bluprint/build";
import { parseArgs } from "./args";
import { authorRoot, authorTool, converse, submitLine } from "./author";
import { catalogOf } from "./catalog";
import { changes, diffOf, moved, readText, refs, touches, type Base, type Change } from "./gitdiff";
import { bill, cacheIn, MODELS } from "./bedrock";
import { ccClose, type Handled } from "./claude-code";
import { check, fixedNote, tally } from "./check";
import { owners, place, unclaimed, type Cut, type Root } from "./cut";
import { inventory, isSource, scopeTo, type Inventory } from "./inventory";
import { plain, redrawOverview } from "./pipeline";
import { idsOf, submitProblems } from "./schema";
import { full, oneLine, summarize, type FileSummary } from "./summarize";
import { activeGraph, buildGraph, setGraph, withSummaries } from "./graph";
import { MAPPER_VERSION } from "./version";

/** Written whole and renamed into place, so the open bluprint never reads half a file. */
function atomic(path: string, body: string) {
  const tmp = `${path}.${process.pid}.tmp`;
  writeFileSync(tmp, body);
  renameSync(tmp, path);
}

/* ── 3. which sections ───────────────────────────────────────── */

interface Placed {
  node: Node;
  /** Root first, the node last. */
  path: Node[];
}

function walk(roots: Node[]): Placed[] {
  const out: Placed[] = [];
  const go = (n: Node, up: Node[]) => {
    const path = [...up, n];
    out.push({ node: n, path });
    for (const c of n.children ?? []) go(c, path);
  };
  roots.forEach((r) => go(r, []));
  return out;
}

const dirOf = (p: string) => p.slice(0, p.lastIndexOf("/") + 1);
const shared = (a: string, b: string) => {
  let i = 0;
  while (i < a.length && a[i] === b[i]) i++;
  return a.slice(0, i).lastIndexOf("/") + 1;
};

/** The sections to redo — the ones the code changes touch, and `also` — and the changed files no section could take. */
function targets(bluprint: BluprintFile, cut: Cut, byPath: Map<string, Change>, also: Placed[], isCode: (path: string) => boolean): { picked: Placed[]; homeless: string[] } {
  const all = walk(bluprint.AUTHORED);
  const picked = new Set<Placed>(also.map((a) => all.find((p) => p.node === a.node)!).filter(Boolean));
  const covered = new Set<string>();
  for (const p of all)
    for (const r of refs(p.node)) {
      const c = byPath.get(r.file);
      if (c && touches(c, r.s, r.e)) {
        picked.add(p);
        covered.add(c.path);
      }
    }
  const homeless: string[] = [];
  for (const c of byPath.values()) {
    // A doc edited away from every passage cited from it only moves those
    // passages' lines: adding a decision to a long log redoes nothing.
    if (covered.has(c.path) || c.after === null || !isCode(c.path)) continue;
    // The section citing this file nearest the first change; deeper wins a tie.
    const at = c.hunks[0]?.os ?? 1;
    let best: { p: Placed; d: number } | null = null;
    for (const p of all)
      for (const r of refs(p.node))
        if (r.file === c.path) {
          const d = Math.min(Math.abs(r.s - at), Math.abs(r.e - at));
          if (!best || d < best.d || (d === best.d && p.path.length > best.p.path.length)) best = { p, d };
        }
    if (!best) {
      // A file no section cites: the section of its root that cites the most
      // of its directory, else the root itself.
      const root = owners(cut, c.path).map((id) => all.find((p) => p.node.id === id && p.path.length === 1)).find(Boolean);
      if (!root) {
        homeless.push(c.path);
        continue;
      }
      let near = { p: root, d: 0 };
      for (const p of all)
        if (p.path[0] === root.node)
          for (const r of refs(p.node)) {
            const d = shared(dirOf(r.file), dirOf(c.path));
            if (d > near.d || (d === near.d && d > 0 && p.path.length > near.p.path.length)) near = { p, d };
          }
      best = { p: near.p, d: 0 };
    }
    picked.add(best.p);
  }
  // A section inside another being redone goes with it.
  const list = [...picked];
  return { picked: list.filter((p) => !list.some((q) => q !== p && p.path.includes(q.node))), homeless };
}

/* ── the agent's turns ───────────────────────────────────────── */

/** A turn of the coding agent's that asked for this update (lib/vault.ts). */
interface Turn {
  transcript?: string;
  corrections: { section: string; note: string }[];
}

/**
 * What the agent did in its last `n` turns of a session, in its own words:
 * what it was asked, the files it changed and the commands it ran, and what
 * it said — the end of it kept, where it sums up. Read from Claude Code's
 * transcript.
 */
function account(transcript: string, n: number): string {
  let entries: any[];
  try {
    entries = readFileSync(transcript, "utf8").split("\n").filter(Boolean).flatMap((l) => {
      try {
        return [JSON.parse(l)];
      } catch {
        return [];
      }
    });
  } catch {
    return "";
  }
  const content = (e: any) => e?.message?.content;
  // A prompt the user typed, not a tool's result coming back.
  const asked = (e: any) =>
    e.type === "user" && !e.isMeta && (typeof content(e) === "string" || (Array.isArray(content(e)) && !content(e).some((b: any) => b.type === "tool_result")));
  const starts = entries.flatMap((e, i) => (asked(e) ? [i] : []));
  const from = starts[Math.max(0, starts.length - n)] ?? 0;
  const lines: string[] = [];
  let said = "";
  for (const e of entries.slice(from)) {
    const c = content(e);
    if (asked(e)) lines.push(`Asked: ${(typeof c === "string" ? c : c.map((b: any) => b.text ?? "").join(" ")).slice(0, 400)}`);
    if (e.type !== "assistant" || !Array.isArray(c)) continue;
    for (const b of c) {
      if (b.type === "text") said = b.text;
      if (b.type !== "tool_use") continue;
      const i = b.input ?? {};
      if (i.file_path) lines.push(`${b.name} ${i.file_path}`);
      else if (b.name === "Bash" && i.command) lines.push(`Ran: ${String(i.command).slice(0, 160)}`);
    }
  }
  const head = [...new Set(lines)].join("\n").slice(0, 2500);
  return `${head}\nIt said, last:\n${said.slice(-2500)}`;
}

/** The section a correction names: by id, by title, or by the end of a "A › B" trail. */
function named(bluprint: BluprintFile, name: string): Placed | null {
  const all = walk(bluprint.AUTHORED);
  const want = name.trim().toLowerCase();
  const last = want.split("›").pop()!.trim();
  return (
    all.find((p) => p.node.id.toLowerCase() === want) ??
    all.find((p) => p.path.map((n) => n.title.toLowerCase()).join(" › ") === want) ??
    all.find((p) => p.node.title.toLowerCase() === want) ??
    all.find((p) => p.node.title.toLowerCase() === last) ??
    null
  );
}

/* ── 4. redoing one ──────────────────────────────────────────── */

/** A changed file as the updater sees it: the definitions the graph has on its changed lines, never the diff itself. */
function changedDefs(c: Change): string {
  if (c.after === null) return `- ${c.path}: deleted`;
  const g = activeGraph();
  const hit = (g?.defs ?? []).filter((d) => d.file === c.path && c.hunks.some((h) => d.start <= h.ns + Math.max(h.nl, 1) - 1 && h.ns <= d.end));
  const innermost = hit.filter((d) => !hit.some((x) => x !== d && x.parent === d.id));
  return `- ${c.path}: ${c.before === null ? "added" : "changed"}${innermost.length ? ` — ${innermost.slice(0, 12).map((d) => `${d.id.split("#")[1]} (${d.start}-${d.end})`).join(", ")}` : ""}`;
}

function brief(t: Placed, root: Root, cut: Cut, inv: Inventory, sums: Record<string, FileSummary>, mine: Change[], reach: string[], told: Told): string {
  const trail = t.path.map((n) => n.title).join(" › ");
  return [
    `# Repository: ${inv.name} @ ${inv.commit}, with uncommitted changes`,
    `## The whole bluprint's top level — ${cut.about}\n${cut.roots.map((r) => `- ${r.id}: ${r.title} — ${r.sub}`).join("\n")}`,
    `## The section to update\n${trail}\nIt sits in the root "${root.title}"; every id under that root starts with "${root.prefix}-".`,
    told.account ? `## What the coding agent did, in its own words\n${told.account}` : "",
    mine.length ? `## What changed in the code\nThe files, and the functions and classes on the lines that changed, as the graph has them now. Look them up with graph_show.\n${mine.map(changedDefs).join("\n")}` : "## The code under this section did not change",
    told.notes.length
      ? `## Where the coding agent found this section wrong\nIt read the code and reported:\n${told.notes.map((n) => `- ${n}`).join("\n")}\nCheck each against the graph yourself; correct what it is right about.`
      : "",
    `## The section as the bluprint has it now\nLine references are already moved to where that code is now; the ones on changed lines may be off.\n\`\`\`json\n${JSON.stringify(t.node, null, 1)}\n\`\`\``,
    `## Files around this change (${reach.length}) — the changed files, what they import and what imports them, and the files this section cites\n${reach.map((p) => (sums[p] ? (mine.some((c) => c.path === p) ? full(sums[p]) : oneLine(sums[p])) : p)).join("\n")}`,
    `## Task
The code under this section changed, or the coding agent found the section wrong. Update the section so it is true of the code as it is now, and submit it whole, with its full subtree.
- Keep what is still true as it is: the same id for this section ("${t.node.id}"), the same ids, titles and wording for children that still describe real code. Change what the diff makes wrong, add what it adds, remove what it removes.
- Problems (\`issues\`, and \`alarm\`/\`unsure\` where they name one) are part of this: look up what each one points at again in the graph. Drop one the change fixed, rewrite one it changed, add one it introduced. Keep only what the code still does wrong.
- Every line reference must point at the code as it is now: cite the line ranges and call lines the graph gives.
- New ids start with "${root.prefix}-" and must not reuse an id from elsewhere in the bluprint.
- You cannot open files: the graph tools are how you see the code. An arrow the graph cannot follow (an event, a decorator, a queue) is drawn \`inferred: true\`.
- If the code this section describes is gone altogether, submit \`{ "id": "${t.node.id}", "removed": true }\` instead, and the section is taken out.
Budget: about 15 tool calls before you submit.`,
  ].filter(Boolean).join("\n\n");
}

async function redo(
  t: Placed,
  bluprint: BluprintFile,
  cut: Cut,
  inv: Inventory,
  sums: Record<string, FileSummary>,
  byPath: Map<string, Change>,
  told: Told,
  model: string,
  say: (s: string) => void,
): Promise<Node | Removed | null> {
  const rootNode = t.path[0];
  const root = cut.roots.find((r) => r.id === rootNode.id);
  if (!root) return null;
  const cited = new Set(walk([t.node]).flatMap((p) => refs(p.node).map((r) => r.file)));
  const mine = [...byPath.values()].filter((c) => cited.has(c.path) || owners(cut, c.path).includes(root.id));
  const reach = new Set<string>();
  for (const c of mine) {
    reach.add(c.path);
    for (const to of inv.imports[c.path] ?? []) reach.add(to);
    for (const [from, tos] of Object.entries(inv.imports)) if (tos.includes(c.path)) reach.add(from);
  }
  for (const f of cited) reach.add(f);
  const list = inv.files.map((f) => f.path).filter((p) => reach.has(p)).sort();
  // Ids taken outside this section, which a new one may not reuse.
  const mineIds = idsOf(t.node);
  const elsewhere = new Set([...bluprint.AUTHORED.flatMap((r) => [...idsOf(r)])].filter((id) => !mineIds.has(id)));
  let submits = 0;
  const handle = (name: string, input: any): Handled => {
    if (name !== "submit") return { content: authorTool({ name, input }) };
    submits++;
    const node = input?.root;
    if (node?.removed === true) {
      say(`${t.node.id}: submit ${submits} — removed`);
      return { content: "Accepted: the section is taken out. Stop now.", done: { node: { id: t.node.id, removed: true } } };
    }
    if (node && typeof node === "object") node.id = t.node.id;
    // The whole root with this section in it, checked as a full run checks it.
    const fixed: string[] = [];
    const problems = submitProblems(node, root.prefix, inv.repo, { isRoot: t.path.length === 1, taken: elsewhere, within: (n) => spliced(rootNode, t, n), fixed });
    say(`${t.node.id}: submit ${submits} — ${problems.length ? `${problems.length} problems (${tally(problems)})` : "clean"}${fixed.length ? `, ${fixed.length} fixed` : ""}`);
    if (!problems.length) return { content: "Accepted. This section is done; stop now.", done: { node } };
    return { content: `Not accepted. Fix every one of these and submit the whole section again:\n- ${problems.slice(0, 80).join("\n- ")}${fixedNote(fixed)}`, isError: true };
  };
  const r = await converse<{ node: Node | Removed }>({ prompt: brief(t, root, cut, inv, sums, mine, list, told), handle, model, stage: "update", maxTurns: 30 });
  return r.value?.node ?? null;
}

/** What redo is told beyond the code: the agent's account of its turns, and its notes on this section. */
interface Told {
  account: string;
  notes: string[];
}

/** A section whose code is gone. */
interface Removed {
  id: string;
  removed: true;
}
const isRemoved = (n: Node | Removed): n is Removed => "removed" in n && n.removed === true;

/** `root` with the section at `t` replaced by `node`; `root` itself is left alone. */
function spliced(root: Node, t: Placed, node: Node): Node {
  if (t.path.length === 1) return { ...node, col: root.col, row: root.row };
  const copy = structuredClone(root);
  let at: Node = copy;
  for (const step of t.path.slice(1, -1)) at = at.children!.find((c) => c.id === step.id)!;
  at.children = at.children!.map((c) => (c.id === t.node.id ? { ...node, col: c.col, row: c.row } : c));
  return copy;
}

/* ── the run ─────────────────────────────────────────────────── */

/** How many turns keep their before-and-after: each snapshot is the whole bluprint. */
const SNAPSHOTS = 30;

export async function update(args: string[]) {
  const { opt, has, repo: dir } = parseArgs(args);
  const repo = resolve(dir!);
  const out = opt("--out") ?? `bluprints/${opt("--name") ?? basename(repo).toLowerCase()}`;
  const t0 = Date.now();
  const result = (r: Record<string, unknown>) =>
    writeFileSync(`${out}/update.json`, JSON.stringify({ finishedAt: new Date().toISOString(), seconds: Math.round((Date.now() - t0) / 1000), ...r }, null, 1) + "\n");

  if (!existsSync(`${out}/bluprint.json`) || !existsSync(`${out}/.cache/cut.json`)) {
    result({ ok: false, error: "This bluprint has no cut to update from; regenerate it." });
    process.exitCode = 1;
    return;
  }
  const bluprint: BluprintFile = JSON.parse(readFileSync(`${out}/bluprint.json`, "utf8"));
  // The bluprint as it was at its commit, kept once before the first update
  // changes it: the other side the diff draws the pictures against (D74).
  if (!existsSync(`${out}/bluprint.base.json`)) writeFileSync(`${out}/bluprint.base.json`, readFileSync(`${out}/bluprint.json`));
  let cut: Cut = JSON.parse(readFileSync(`${out}/.cache/cut.json`, "utf8"));
  const base: Base = existsSync(`${out}/base.json`) ? JSON.parse(readFileSync(`${out}/base.json`, "utf8")) : {};
  cacheIn(`${out}/.cache`);
  const model = MODELS[(process.env.SLOP_UPDATE ?? process.env.SLOP_AUTHOR ?? "opus") as keyof typeof MODELS] ?? MODELS.opus;

  // The turns that asked for this, taken so a run after this one gets only newer ones.
  let turns: Turn[] = [];
  // A run that died after taking its turns left them in turns.taken.json, where
  // nothing would read them again: they go back in front of any newer ones.
  const stranded = `${out}/turns.taken.json`;
  if (existsSync(stranded) && !has("--dry-run")) {
    let kept: Turn[] = [];
    try { kept = JSON.parse(readFileSync(stranded, "utf8")); } catch { /* torn: nothing to recover */ }
    const newer: Turn[] = existsSync(`${out}/turns.json`) ? JSON.parse(readFileSync(`${out}/turns.json`, "utf8")) : [];
    if (kept.length) atomic(`${out}/turns.json`, JSON.stringify([...kept, ...newer]) + "\n");
    rmSync(stranded);
  }
  if (existsSync(`${out}/turns.json`)) {
    // A dry run only looks.
    const taken = has("--dry-run") ? `${out}/turns.json` : `${out}/turns.taken.json`;
    if (taken !== `${out}/turns.json`) renameSync(`${out}/turns.json`, taken);
    turns = JSON.parse(readFileSync(taken, "utf8"));
    if (taken !== `${out}/turns.json`) rmSync(taken);
  }
  const sessions = new Map<string, number>();
  for (const t of turns) if (t.transcript) sessions.set(t.transcript, (sessions.get(t.transcript) ?? 0) + 1);
  const said = [...sessions].map(([f, n]) => account(f, n)).filter(Boolean).join("\n\n").slice(-6000);
  const corrections = turns.flatMap((t) => t.corrections ?? []);
  const wrong = new Map<Placed, string[]>();
  const unmatched: string[] = [];
  for (const c of corrections) {
    const p = named(bluprint, c.section);
    if (!p) unmatched.push(c.section);
    else wrong.set(p, [...(wrong.get(p) ?? []), c.note]);
  }
  if (corrections.length) console.log(`${corrections.length} corrections from the agent${unmatched.length ? `; no section named ${unmatched.join(", ")}` : ""}`);

  const inv = inventory(repo);
  setGraph(await buildGraph(inv));
  // A scoped bluprint keeps to its part. One made before the scope was saved covers
  // far fewer files than the checkout holds; what its cut claims is its part.
  // Without this, an update of a bluprint of Kafka's controller tried to place the
  // other 3,490 files of Kafka, and failed on the prompt's length.
  const legacy = !bluprint.RUN.scope && bluprint.RUN.files < inv.files.length / 2;
  const scope = bluprint.RUN.scope ?? (legacy ? { paths: [...new Set(cut.roots.flatMap((r) => r.files))], focus: "" } : undefined);
  if (scope) scopeTo(inv, scope);
  if (legacy) console.log(`a scoped bluprint from before scopes were saved: keeping to the ${scope!.paths.length} paths its roots claim`);
  const isCode = new Map(inv.files.map((f) => [f.path, isSource(f)]));
  const citedAnywhere = new Set(walk(bluprint.AUTHORED).flatMap((p) => refs(p.node).map((r) => r.file)));
  // Only code the bluprint covers or could, and docs it cites: a lockfile or a test changing moves nothing.
  const found = changes(repo, bluprint.RUN.commit, base).filter((c) => (c.after === null ? citedAnywhere.has(c.path) : isCode.get(c.path) || citedAnywhere.has(c.path)));
  console.log(`${found.length} changed code files${found.length ? `: ${found.map((c) => c.path).join(", ")}` : ""}`);
  // Code no root claims — added since the cut, or left out by an earlier
  // update — is placed in the cut as a full remake places it (cut.ts, place).
  const unplaced = unclaimed(cut, inv);
  if (unplaced.length) console.log(`${unplaced.length} files no root claims: ${unplaced.join(", ")}`);
  if (!found.length && !wrong.size && !unplaced.length) {
    result({ ok: true, changed: [], sections: [], unmatched });
    return;
  }
  const byPath = new Map(found.map((c) => [c.path, c]));
  const sums = has("--dry-run") ? {} : await summarize(inv, () => {});
  withSummaries(activeGraph()!, sums);
  let added: Root[] = [];
  if (unplaced.length && !has("--dry-run")) {
    const placed = await place(cut, unplaced, inv, sums, model);
    cut = placed.cut;
    added = placed.added;
    writeFileSync(`${out}/.cache/cut.json`, JSON.stringify(cut, null, 1));
    for (const [id, files] of placed.gained) console.log(`  ${id} takes ${files.join(", ")}`);
    for (const r of added) console.log(`  new root ${r.id}: ${r.files.join(", ")}`);
    // A file an earlier update saw but could not place is in base already, so
    // it reads as unchanged: it is new to the bluprint, so it comes in as new.
    for (const files of placed.gained.values())
      for (const path of files) {
        const after = byPath.has(path) ? null : readText(join(repo, path));
        if (after === null) continue;
        const c: Change = { path, before: null, after, ...diffOf(path, null, after) };
        found.push(c);
        byPath.set(path, c);
      }
  }
  // A new root's files are written from scratch with it, not into a section.
  const isNew = (path: string) => added.some((r) => owners(cut, path).includes(r.id));

  // The bluprint and the code as they stand before this update, so what one turn
  // changed can be shown afterwards as a before and after (changes.json).
  const turnId = new Date().toISOString().replace(/[:.]/g, "-");
  if (!has("--dry-run")) {
    mkdirSync(`${out}/snapshots`, { recursive: true });
    writeFileSync(`${out}/snapshots/${turnId}.json`, JSON.stringify({ bluprint: JSON.parse(readFileSync(`${out}/bluprint.json`, "utf8")), files: found.map(({ path, before, after }) => ({ path, before, after })) }));
  }

  // Which sections, read off the references as they were; then every
  // reference moves to where its code is now.
  const { picked, homeless } = targets(bluprint, cut, new Map([...byPath].filter(([p]) => !isNew(p))), [...wrong.keys()], (p) => Boolean(isCode.get(p)));
  for (const p of walk(bluprint.AUTHORED)) refs(p.node, (f, line) => (byPath.has(f) ? moved(byPath.get(f)!, line) : line));
  // The code as this update found it: once the bluprint is next written it cites
  // that, so the open page shifts the bluprint's lines from it (lib/live.ts).
  if (!has("--dry-run")) writeFileSync(`${out}/moved.json`, JSON.stringify(Object.fromEntries(found.map((c) => [c.path, c.after]))) + "\n");
  console.log(`${picked.length} sections to redo: ${picked.map((p) => p.node.id).join(", ")}`);
  // A section redone takes the notes on it and on anything inside it.
  const notesFor = (t: Placed) => [...wrong].filter(([p]) => p.path.includes(t.node)).flatMap(([p, n]) => n.map((x) => (p === t ? x : `${p.node.title}: ${x}`)));
  if (has("--dry-run")) {
    for (const p of picked) console.log(`  ${p.path.map((n) => n.id).join(" › ")}${notesFor(p).length ? ` — notes: ${notesFor(p).join(" | ")}` : ""}`);
    if (said) console.log(`the agent's account:\n${said}`);
    if (homeless.length) console.log(`  no section can take: ${homeless.join(", ")}`);
    if (unplaced.length) console.log(`  to place in the cut first: ${unplaced.join(", ")}`);
    const after = check(bluprint, repo, { generated: true }).problems;
    console.log(`references moved: ${after.length} check problems`);
    after.slice(0, 10).forEach((p) => console.log(`  ${p}`));
    return;
  }

  const say = (s: string) => console.log(`  ${s}`);
  const failed: string[] = [];
  const removed: string[] = [];
  // Each section goes into the bluprint the moment it is redone, and the bluprint is
  // written then, so the open page shows it while the others are still being
  // worked on (components/bluprint-context.tsx). The sections are redone
  // concurrently, but each one is spliced in without an await in between, so
  // no write ever sees half of one.
  const done: { t: Placed; node: Awaited<ReturnType<typeof redo>> }[] = new Array(picked.length);
  const land = (t: Placed, node: Awaited<ReturnType<typeof redo>>) => {
    done[picked.indexOf(t)] = { t, node };
    const at = t.path.length === 1 ? null : t.path[t.path.length - 2];
    const siblings = at ? at.children! : bluprint.AUTHORED;
    const i = siblings.findIndex((c) => c.id === t.node.id);
    if (node && isRemoved(node)) {
      siblings.splice(i, 1);
      removed.push(t.node.id);
      // A root goes with the lines drawn to it.
      if (!at) {
        const pic = bluprint.OVERVIEW?.anatomy?.find((b) => b.kind === "diagram");
        if (pic?.kind === "diagram") {
          const gone = new Set(pic.boxes.filter((x) => x.opens === t.node.id).map((x) => x.id));
          pic.boxes = pic.boxes.filter((x) => !gone.has(x.id));
          pic.arrows = pic.arrows.filter((x) => !gone.has(x.from) && !gone.has(x.to));
        }
      }
      say(`${t.node.id}: removed`);
    } else if (node) {
      siblings[i] = { ...node, col: t.node.col, row: t.node.row };
      say(`${t.node.id}: updated`);
    } else {
      failed.push(t.node.id);
      siblings[i] = { ...t.node, state: "partial", unsure: "This section was due an update — its code changed, or it was found wrong — and the update failed; parts of it may be out of date." };
      say(`${t.node.id}: FAILED, kept as it was`);
    }
    atomic(`${out}/bluprint.json`, JSON.stringify(bluprint, null, 1) + "\n");
  };
  const fresh: { id: string; title: string; ok: boolean }[] = [];
  await Promise.all([
    ...picked.map(async (t) => {
      const node = await redo(t, bluprint, cut, inv, sums, byPath, { account: said, notes: notesFor(t) }, model, say);
      land(t, node);
    }),
    // A root the placing added is written whole, as a full run writes one.
    ...added.map(async (r) => {
      const a = await authorRoot(r, cut, inv, sums, model, (n, problems, _draft, fixed) => say(submitLine(r.id, n, problems, fixed)));
      if (!a.root) {
        failed.push(r.id);
        fresh.push({ id: r.id, title: r.title, ok: false });
        say(`${r.id}: FAILED, not added`);
        return;
      }
      const node = plain(a.root);
      // Below the last root: rows can have gaps where a root was taken out.
      bluprint.AUTHORED.push({ ...node, col: 0, row: Math.max(-1, ...bluprint.AUTHORED.map((n) => n.row ?? 0)) + 1 });
      fresh.push({ id: r.id, title: node.title, ok: true });
      atomic(`${out}/bluprint.json`, JSON.stringify(bluprint, null, 1) + "\n");
      say(`${r.id}: added`);
    }),
  ]);
  // The top level draws how the roots connect, so a new one needs it drawn again.
  if (fresh.some((f) => f.ok)) {
    const problems = await redrawOverview(bluprint, cut, inv, model, sums);
    say(problems ? `overview: kept as it was — ${problems.slice(0, 3).join("; ")}` : "overview: redrawn");
  }

  const final = check(bluprint, repo, { generated: true });
  atomic(`${out}/bluprint.json`, JSON.stringify(bluprint, null, 1) + "\n");
  // Summaries of the changed files are fresh now, so the index (and every
  // file added since the cut) follows the code too.
  atomic(`${out}/index.json`, JSON.stringify(catalogOf(inv, sums, cut)) + "\n");
  // The bluprint now describes these files as they are: the next update starts here.
  for (const c of found) base[c.path] = c.after;
  writeFileSync(`${out}/base.json`, JSON.stringify(base) + "\n");
  rmSync(`${out}/moved.json`, { force: true });

  const usd = Math.round(Object.values(bill).reduce((a, b) => a + b.usd, 0) * 100) / 100;
  const sections = [
    ...done.map(({ t, node }) => ({ id: t.node.id, title: node && !isRemoved(node) ? node.title : t.node.title, ok: Boolean(node), removed: removed.includes(t.node.id) })),
    ...fresh.map((f) => ({ ...f, removed: false, added: true })),
  ];
  result({ ok: !failed.length, changed: found.map((c) => c.path), sections, homeless, unmatched, corrected: [...wrong.keys()].map((p) => p.node.id), usd, problems: final.problems.slice(0, 20), ...(failed.length ? { error: `Could not update ${failed.join(", ")}` } : {}) });
  if (existsSync(`${out}/report.json`)) {
    const report = JSON.parse(readFileSync(`${out}/report.json`, "utf8"));
    report.updates = [...(report.updates ?? []), { at: new Date().toISOString(), mapperVersion: MAPPER_VERSION, changed: found.map((c) => c.path), sections: sections.map((s) => s.id), failed, seconds: Math.round((Date.now() - t0) / 1000), usd, bill }];
    writeFileSync(`${out}/report.json`, JSON.stringify(report, null, 1) + "\n");
  }
  // What asked for it, in the user's words where a prompt did: the line the turns list shows.
  const last = [...turns].reverse().find((t) => t.transcript)?.transcript;
  const asked = last ? lastExchange(last, (f) => readFileSync(f, "utf8"))?.asked : undefined;
  const prompt = (asked ?? corrections.map((c) => c.note).join("; ")).split("\n")[0].slice(0, 200);
  const log = existsSync(`${out}/changes.json`) ? JSON.parse(readFileSync(`${out}/changes.json`, "utf8")) : [];
  log.push({ id: turnId, at: new Date().toISOString(), prompt, files: found.map((c) => c.path), sections, usd, seconds: Math.round((Date.now() - t0) / 1000) });
  const kept = log.slice(-SNAPSHOTS);
  writeFileSync(`${out}/changes.json`, JSON.stringify(kept, null, 1) + "\n");
  // By the log, not by count: a run that died after its snapshot leaves one no turn names.
  const listed = new Set(kept.map((c: { id: string }) => `${c.id}.json`));
  for (const f of readdirSync(`${out}/snapshots`)) if (!listed.has(f)) rmSync(`${out}/snapshots/${f}`);
  console.log(`\n${out}/bluprint.json — ${sections.length - failed.length}/${sections.length} sections updated, ${final.problems.length} check problems, $${usd}`);
  await ccClose();
}

