//! The web in the preview: pages from outside this machine (a search, a
//! library's docs, a service the project calls), which the proxy (preview.rs)
//! cannot frame. Each opens in a webview of its own laid over the Preview
//! tab's viewport (components/preview/preview.tsx keeps it there), with the same agent
//! inside (agent.js). The page never calls the app: the tab asks it things by
//! running script in it and collects what it has to say the same way, so a
//! site on the open web is handed nothing of the app's.
//!
//! And Claude's clicks and keys, on macOS: given to the webview as AppKit
//! events, the preview's own frame or one of these pages alike. A page cannot
//! tell them from a person's, so whatever works for the user works for Claude:
//! a popup, a file picker, a button in a frame from another site.

use serde::Deserialize;
use serde_json::{json, Value};
use std::sync::mpsc;
use std::time::Duration;
use tauri::webview::{NewWindowResponse, PageLoadEvent};
use tauri::{AppHandle, Emitter, LogicalPosition, LogicalSize, Manager, Rect, Url, WebviewBuilder, WebviewUrl};

const AGENT: &str = include_str!("agent.js");
const GONE: &str = "The page is gone from the preview.";

fn web(url: &str) -> Result<Url, String> {
    let u = Url::parse(url).map_err(|_| format!("Not an address: {url}"))?;
    if !matches!(u.scheme(), "http" | "https") {
        return Err(format!("Only http and https pages open in the preview, not {url}"));
    }
    Ok(u)
}

/// A page from the web, at a place in the window: CSS pixels of the app's
/// page, with `zoom` the scale the viewport is drawn at. With `project`, in
/// that project's own store of sign-ins rather than the shared one (signins.rs).
/// `label` is the tab's to choose, so the page's first load, which can finish
/// before this returns, is already known to be its own.
#[tauri::command]
pub async fn browser_open(
    app: AppHandle,
    label: String,
    url: String,
    x: f64,
    y: f64,
    width: f64,
    height: f64,
    zoom: f64,
    project: Option<String>,
) -> Result<String, String> {
    let window = app.get_window("main").ok_or("The window is gone.")?;
    if !label.starts_with("browser-") || app.get_webview(&label).is_some() {
        return Err(format!("Not a label for a new page: {label}"));
    }
    let (tell, me) = (app.clone(), label.clone());
    let (own, mine) = (app.clone(), label.clone());
    let mut builder = WebviewBuilder::new(&label, WebviewUrl::External(web(&url)?))
        // Told that it is asked, rather than posting to a page around it.
        .initialization_script(format!("(function (BLUPRINT_NATIVE) {{\n{AGENT}\n}})(true);"))
        .on_page_load(move |_, load| {
            let done = matches!(load.event(), PageLoadEvent::Finished);
            let _ = tell.emit_to("main", "bluprint:browser", json!({ "label": me, "url": load.url().as_str(), "done": done }));
        })
        // The preview is one page: what would open a window opens here.
        .on_new_window(move |url, _| {
            if let Some(view) = own.get_webview(&mine) {
                let _ = view.navigate(url);
            }
            NewWindowResponse::Deny
        });
    if let Some(root) = project {
        builder = builder.data_store_identifier(crate::signins::store_of(&root));
    }
    let view = window
        .add_child(builder, LogicalPosition::new(x, y), LogicalSize::new(width, height))
        .map_err(|e| e.to_string())?;
    let _ = view.set_zoom(zoom);
    Ok(label)
}

#[tauri::command]
pub async fn browser_place(app: AppHandle, label: String, x: f64, y: f64, width: f64, height: f64, zoom: f64, shown: bool) -> Result<(), String> {
    let view = app.get_webview(&label).ok_or(GONE)?;
    let bounds = Rect { position: LogicalPosition::new(x, y).into(), size: LogicalSize::new(width, height).into() };
    view.set_bounds(bounds).map_err(|e| e.to_string())?;
    view.set_zoom(zoom).map_err(|e| e.to_string())?;
    if shown { view.show() } else { view.hide() }.map_err(|e| e.to_string())
}

#[tauri::command]
pub async fn browser_go(app: AppHandle, label: String, url: String) -> Result<(), String> {
    app.get_webview(&label).ok_or(GONE)?.navigate(web(&url)?).map_err(|e| e.to_string())
}

/// Runs `js` in the page and returns its value. The tab's agent calls go
/// through this, and so does collecting what the page has said since.
#[tauri::command]
pub async fn browser_eval(app: AppHandle, label: String, js: String) -> Result<Value, String> {
    let view = app.get_webview(&label).ok_or(GONE)?;
    let (tx, rx) = mpsc::channel();
    view.eval_with_callback(js, move |out| {
        let _ = tx.send(out);
    })
    .map_err(|e| e.to_string())?;
    let out = rx.recv_timeout(Duration::from_secs(5)).map_err(|_| "The page did not answer.".to_string())?;
    Ok(serde_json::from_str(&out).unwrap_or(Value::Null))
}

#[tauri::command]
pub async fn browser_close(app: AppHandle, label: String) {
    if let Some(view) = app.get_webview(&label) {
        let _ = view.close();
    }
}

/// One thing a person does with a mouse or keyboard. `x` and `y` are points
/// from the top left of the webview it is done in.
#[derive(Deserialize)]
#[cfg_attr(not(target_os = "macos"), allow(dead_code))]
pub struct Act {
    kind: String,
    #[serde(default)]
    x: f64,
    #[serde(default)]
    y: f64,
    /// 0 the left button, 2 the right.
    #[serde(default)]
    button: u8,
    #[serde(default = "one")]
    clicks: isize,
    /// A key with its modifiers for `key` ("Enter", "cmd+a"), the characters for `text`.
    #[serde(default)]
    text: String,
}

fn one() -> isize {
    1
}

/// Does `acts` in a webview: a page from the web by its label, or the
/// window's own (where the preview's frame is) when there is none. Whether
/// the window was active: WebKit follows a hover only in one that is.
#[tauri::command]
pub async fn native_input(app: AppHandle, view: Option<String>, acts: Vec<Act>) -> Result<bool, String> {
    #[cfg(target_os = "macos")]
    {
        let (tx, rx) = mpsc::channel();
        let run = move |w: tauri::webview::PlatformWebview| {
            // On the main thread: Tauri's promise for with_webview.
            let _ = tx.send(unsafe { macos::send(&*(w.inner() as *const objc2_app_kit::NSView), &acts) });
        };
        let target = app.get_webview(view.as_deref().unwrap_or("main")).ok_or(GONE)?;
        target.with_webview(run).map_err(|e| e.to_string())?;
        rx.recv_timeout(Duration::from_secs(5)).map_err(|_| "The input was not taken.".to_string())?
    }
    #[cfg(not(target_os = "macos"))]
    {
        let _ = (app, view, acts);
        Err("native input is macOS only".into())
    }
}

#[cfg(target_os = "macos")]
mod macos {
    use super::{code_of, Act};
    use objc2::runtime::NSObjectProtocol;
    use objc2::{msg_send, sel, MainThreadMarker};
    use objc2_app_kit::{NSApplication, NSEvent, NSEventModifierFlags, NSEventType, NSView};
    use objc2_foundation::{NSPoint, NSProcessInfo, NSString};

    pub fn send(view: &NSView, acts: &[Act]) -> Result<bool, String> {
        let window = view.window().ok_or("The preview is not in a window.")?;
        let number = window.windowNumber();
        let start = NSProcessInfo::processInfo().systemUptime();
        let (flipped, height) = (view.isFlipped(), view.bounds().size.height);
        let at = |x: f64, y: f64| view.convertPoint_toView(NSPoint::new(x, if flipped { y } else { height - y }), None);
        // A press or a key takes the keyboard, as a person's click would; a hover does not.
        if acts.iter().any(|a| a.kind != "move") {
            window.makeFirstResponder(Some(view));
        }
        for (i, a) in acts.iter().enumerate() {
            let time = start + i as f64 * 0.001;
            match a.kind.as_str() {
                "move" | "down" | "up" | "drag" => {
                    let right = a.button == 2;
                    let kind = match a.kind.as_str() {
                        "move" => NSEventType::MouseMoved,
                        "drag" => NSEventType::LeftMouseDragged,
                        "down" if right => NSEventType::RightMouseDown,
                        "down" => NSEventType::LeftMouseDown,
                        _ if right => NSEventType::RightMouseUp,
                        _ => NSEventType::LeftMouseUp,
                    };
                    let pressure = if matches!(a.kind.as_str(), "down" | "drag") { 1.0 } else { 0.0 };
                    let event = NSEvent::mouseEventWithType_location_modifierFlags_timestamp_windowNumber_context_eventNumber_clickCount_pressure(
                        kind,
                        at(a.x, a.y),
                        NSEventModifierFlags::empty(),
                        time,
                        number,
                        None,
                        0,
                        a.clicks,
                        pressure,
                    )
                    .ok_or("AppKit made no mouse event.")?;
                    match kind {
                        // WKWebView has no mouseMoved: of its own (its tracking
                        // area takes moves), so a hover is given the way WebKit's
                        // tests give one: it reaches the page with the window in
                        // the back too.
                        NSEventType::MouseMoved if view.respondsToSelector(sel!(_simulateMouseMove:)) => unsafe {
                            let _: () = msg_send![view, _simulateMouseMove: &*event];
                        },
                        NSEventType::MouseMoved => window.sendEvent(&event),
                        NSEventType::LeftMouseDragged => view.mouseDragged(&event),
                        NSEventType::LeftMouseDown => view.mouseDown(&event),
                        NSEventType::RightMouseDown => view.rightMouseDown(&event),
                        NSEventType::RightMouseUp => view.rightMouseUp(&event),
                        _ => view.mouseUp(&event),
                    }
                }
                "key" => {
                    let (code, chars, flags) = combo(&a.text).ok_or_else(|| format!("Not a key: {}", a.text))?;
                    key(view, number, time, code, &chars, flags)?;
                }
                "text" => {
                    for c in a.text.chars() {
                        let (code, chars) = if c == '\n' { (36, "\r".to_string()) } else { (code_of(c), c.to_string()) };
                        key(view, number, time, code, &chars, NSEventModifierFlags::empty())?;
                    }
                }
                other => return Err(format!("Unknown input: {other}")),
            }
        }
        Ok(window.isKeyWindow())
    }

    fn key(view: &NSView, number: isize, time: f64, code: u16, chars: &str, flags: NSEventModifierFlags) -> Result<(), String> {
        let chars = NSString::from_str(chars);
        let event = |kind| {
            NSEvent::keyEventWithType_location_modifierFlags_timestamp_windowNumber_context_characters_charactersIgnoringModifiers_isARepeat_keyCode(
                kind,
                NSPoint::new(0.0, 0.0),
                flags,
                time,
                number,
                None,
                &chars,
                &chars,
                false,
                code,
            )
            .ok_or("AppKit made no key event.")
        };
        let down = event(NSEventType::KeyDown)?;
        view.keyDown(&down);
        // The page hears a shortcut, but the edit it stands for is the Edit
        // menu's, which acts only in the key window: done here instead, so it
        // works with the app behind others.
        if flags.contains(NSEventModifierFlags::Command) {
            let edit = match (chars.to_string().to_ascii_lowercase().as_str(), flags.contains(NSEventModifierFlags::Shift)) {
                ("a", _) => Some(sel!(selectAll:)),
                ("c", _) => Some(sel!(copy:)),
                ("x", _) => Some(sel!(cut:)),
                ("v", _) => Some(sel!(paste:)),
                ("z", false) => Some(sel!(undo:)),
                ("z", true) => Some(sel!(redo:)),
                _ => None,
            };
            if let Some(edit) = edit {
                // send() runs on the main thread (native_input).
                let app = NSApplication::sharedApplication(unsafe { MainThreadMarker::new_unchecked() });
                unsafe { app.sendAction_to_from(edit, Some(view), None) };
            }
        }
        let up = event(NSEventType::KeyUp)?;
        view.keyUp(&up);
        Ok(())
    }

    /// "Enter", "a", "shift+Tab", "cmd+a": the key code, its characters and the modifiers.
    fn combo(text: &str) -> Option<(u16, String, NSEventModifierFlags)> {
        let mut parts: Vec<&str> = text.split('+').collect();
        let name = parts.pop()?;
        let mut flags = NSEventModifierFlags::empty();
        for m in parts {
            flags |= match m.to_ascii_lowercase().as_str() {
                "ctrl" | "control" => NSEventModifierFlags::Control,
                "shift" => NSEventModifierFlags::Shift,
                "alt" | "option" => NSEventModifierFlags::Option,
                "cmd" | "command" | "meta" | "super" => NSEventModifierFlags::Command,
                _ => return None,
            };
        }
        let (code, chars) = super::key_of(name)?;
        Some((code, chars, flags))
    }
}

/// The key code and characters AppKit gives a key, by its name or its character.
#[cfg_attr(not(target_os = "macos"), allow(dead_code))]
fn key_of(name: &str) -> Option<(u16, String)> {
    let named = match name.to_ascii_lowercase().as_str() {
        "enter" | "return" => Some((36, "\r")),
        "tab" => Some((48, "\t")),
        "escape" | "esc" => Some((53, "\u{1b}")),
        "backspace" => Some((51, "\u{7f}")),
        "delete" => Some((117, "\u{f728}")),
        "space" => Some((49, " ")),
        "up" | "arrowup" => Some((126, "\u{f700}")),
        "down" | "arrowdown" => Some((125, "\u{f701}")),
        "left" | "arrowleft" => Some((123, "\u{f702}")),
        "right" | "arrowright" => Some((124, "\u{f703}")),
        "home" => Some((115, "\u{f729}")),
        "end" => Some((119, "\u{f72b}")),
        "pageup" => Some((116, "\u{f72c}")),
        "pagedown" => Some((121, "\u{f72d}")),
        _ => None,
    };
    if let Some((code, chars)) = named {
        return Some((code, chars.into()));
    }
    let mut it = name.chars();
    let c = it.next()?;
    it.next().is_none().then(|| (code_of(c), c.to_string()))
}

/// The key a character is on, on a US keyboard, by its position in this
/// string; 0 for one it has no key of its own for, which pages rarely read.
#[cfg_attr(not(target_os = "macos"), allow(dead_code))]
fn code_of(c: char) -> u16 {
    const KEYS: &str = "asdfhgzxcv\0bqweryt123465=97-80]ou[ip\rlj'k;\\,/nm.\t `";
    KEYS.chars().position(|k| k == c.to_ascii_lowercase()).map_or(0, |i| i as u16)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn keys_have_their_macos_codes() {
        assert_eq!(key_of("Enter"), Some((36, "\r".into())));
        assert_eq!(key_of("a").map(|k| k.0), Some(0));
        assert_eq!(key_of("B").map(|k| k.0), Some(11));
        assert_eq!(key_of("m").map(|k| k.0), Some(46));
        assert_eq!(key_of("0").map(|k| k.0), Some(29));
        assert_eq!(key_of("`").map(|k| k.0), Some(50));
        assert_eq!(key_of("ArrowUp").map(|k| k.0), Some(126));
        assert_eq!(key_of("nope"), None);
    }

    #[test]
    fn only_web_pages_open() {
        assert!(web("https://example.com/a?b").is_ok());
        assert!(web("file:///etc/passwd").is_err());
        assert!(web("javascript:alert(1)").is_err());
    }
}

app/src-tauri/src/claude.rs:
//! Claude Code in the workspace's tabs. Every tab is the user's shell on a
//! pty (pty.rs); a new one starts their own `claude` in it first, so it looks
//! and behaves exactly as it does in their terminal, and quitting Claude leaves
//! the shell behind. What this module adds is finding that binary, and the
//! launcher that lets the bluprint hand it context.
//!
//! The launcher is a small script, `bluprint-claude`, on each tab's PATH. It runs
//! the user's `claude` with `--settings` carrying a `UserPromptSubmit` hook,
//! and while it runs it keeps a `.live` marker beside the tab's queue: that is
//! how the UI knows Claude is in front in a tab, and able to take context.
//! `--settings` adds to the user's own settings, so their login, hooks, MCP
//! servers, theme and status line all still apply.
//!
//! The hand-off is a file. Each tab has its own queue under the temp dir,
//! named in `$BLUPRINT_CONTEXT`. Picking on the bluprint appends a block to it —
//! `[Bluprint section: …]` for a whole section, `[Bluprint element: …]` for one thing on
//! a level — and the hook drains it on the next prompt: whatever a prompt hook
//! prints is added to that prompt's context. The file being gone is how the
//! UI knows a pick was delivered (components/agent/workspace.tsx shows it).

use portable_pty::CommandBuilder;
use std::io::Write;
use std::path::{Path, PathBuf};

/// Every prompt first says where the user is on the bluprint (`.where`, kept by the
/// app as they move; see `place`): its first line always, so "what am I
/// reading?" has an answer, and the section itself only when it has changed
/// since the last prompt, so one page read for a while is not sent each turn.
/// Then it drains the queue: the `mv` is atomic, so a pick appended while
/// Claude reads lands in a fresh file for the next prompt rather than being lost.
const HOOK: &str = r#"f="$BLUPRINT_CONTEXT"; w="$f.where"; if [ -s "$w" ]; then head -n 1 "$w"; cmp -s "$w" "$w.sent" || { tail -n +2 "$w"; cp "$w" "$w.sent"; }; fi; [ -s "$f" ] || exit 0; mv "$f" "$f.sent" && cat "$f.sent""#;

/// The scripts beside the launcher, on the PATH of Claude's Bash tool. The
/// tab's PATH has them, but Claude Code builds its Bash tool's environment
/// from a shell of its own, which on Windows drops them; what a session-start
/// hook writes to `$CLAUDE_ENV_FILE` is what every command there starts with.
const ON_PATH: &str = r#"[ -n "$CLAUDE_ENV_FILE" ] && [ -n "$BLUPRINT_BIN" ] || exit 0; d="$BLUPRINT_BIN"; command -v cygpath >/dev/null 2>&1 && d=$(cygpath -u "$d"); printf 'export PATH="%s:$PATH"\n' "$d" >> "$CLAUDE_ENV_FILE""#;

/// The conversation Claude is having in this tab, from the hook's input, so
/// the app can resume it in the tab it reopens after a restart. A `/clear`
/// starts a new one, and this follows it.
const SESSION: &str = r#"id=$(sed -n 's/.*"session_id"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1); [ -n "$id" ] && printf '%s\n' "$id" > "$BLUPRINT_CONTEXT.session"; exit 0"#;

/// After a tool that can change files: this turn may have edited code.
const EDITED: &str = r#": > "$BLUPRINT_CONTEXT.dirty""#;
/// The tools EDITED follows. Bash among them, since a shell command can edit too.
const EDITING_TOOLS: &str = "Edit|Write|MultiEdit|NotebookEdit|Bash";

/// A plan Claude asks to start on: the hook's input, which carries the plan's
/// Markdown, kept whole for the app to draw (components/agent/plan.tsx). Renamed
/// into place, so a plan is never read half written. A new plan ends the last
/// one's checklist, before the app can draw the new one with its ticks, and
/// its file waits (`.pending`) to become the checklist's once accepted.
const PLAN: &str = r#"f="$BLUPRINT_CONTEXT"; rm -f "$f.steps" "$f.accepted"; cat > "$f.plan.part" && sed -n 's/.*"planFilePath": *"\([^"]*\)".*/\1/p' "$f.plan.part" | head -n 1 > "$f.pending" && mv "$f.plan.part" "$f.plan""#;
/// ExitPlanMode only runs once the user has accepted the plan, in the terminal
/// or from the plan's own tab.
const APPROVED: &str = r#": > "$BLUPRINT_CONTEXT.approved""#;

/// On a long build Claude loses its place, and the to-do tool it would keep a
/// list in is off for the newer models (Claude Code turns it on only for older
/// ones). So the plan's own Steps are the list: Claude marks them with
/// `bluprint-plan-step` (STEP), the plan's tab shows them ticked off (`steps_of`),
/// and the hooks below hold Claude to them. A macro, to be `concat!`ed into
/// each hook that says it; no quotes in it, since it goes out inside JSON.
macro_rules! checklist {
    () => {
        "Its Steps are your checklist, ticked off in the plan tab the user watches: run `bluprint-plan-step <n> doing` as you start a step and `bluprint-plan-step <n> done` as soon as it is finished, in order. A step that turns out wrong or unneeded is `bluprint-plan-step <n> skipped <why>`, and you tell the user why. Work the plan missed goes in the step it belongs to. Do not end the build with a step unmarked, and finish with the checks under Check."
    };
}
/// Said to Claude as the accepted plan comes back to it.
const TODOS: &str = concat!(
    r#"f="$BLUPRINT_CONTEXT"; [ -s "$f.pending" ] && mv "$f.pending" "$f.accepted"; printf '%s\n' '{"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":"The plan is accepted. "#,
    checklist!(),
    r#" Run `bluprint-plan-step 1 doing` before you change any file."}}'"#
);
/// A plan accepted with "Yes, clear context" never finishes its ExitPlanMode:
/// Claude Code denies the call, clears the conversation and starts a new one
/// with the plan as its first message. So a clear with a plan still waiting
/// may be that, or a `/clear` after the plan was turned down; Claude is told
/// which way to read it, and nothing holds it to the steps (UNFINISHED,
/// REMIND) until it marks one.
const CLEARED: &str = concat!(
    r#"f="$BLUPRINT_CONTEXT"; [ -s "$f.pending" ] || exit 0; p=$(cat "$f.pending"); mv "$f.pending" "$f.accepted"; [ -f "$p" ] || exit 0; printf '%s\n\n' 'If the first message asks you to implement the plan below, the user accepted it. "#,
    checklist!(),
    r#" Run `bluprint-plan-step 1 doing` before you change any file. The plan:'; cat "$p"; exit 0"#
);
/// Compacting summarizes the plan away mid-build; it is said again, whole,
/// with what is marked so far.
const REMIND: &str = concat!(
    r#"f="$BLUPRINT_CONTEXT"; p=$(cat "$f.accepted" 2>/dev/null); [ -s "$f.steps" ] && [ -f "$p" ] || exit 0; printf '%s\n\n' 'The conversation was compacted while you were building the plan below, which the user accepted: pick up from the first step not marked done. "#,
    checklist!(),
    r#" The plan:'; cat "$p"; printf '\n\nMarked so far (step, state, note):\n'; cat "$f.steps"; exit 0"#
);
/// A new Claude in the tab is not building the last one's plan.
const FRESH: &str = r#"rm -f "$BLUPRINT_CONTEXT.accepted" "$BLUPRINT_CONTEXT.pending""#;
/// At the end of a turn, steps of the accepted plan still unmarked keep Claude
/// going: exit 2 hands it the reason instead of stopping. Once per turn, since
/// Claude Code says when a stop is already one this sent back, so a Claude
/// waiting on the user can still stop. Writes the tab's `done` itself, so a
/// turn sent back never shows as finished. All marked, the plan is let go.
const UNFINISHED: &str = r#"f="$BLUPRINT_CONTEXT"; p=$(cat "$f.accepted" 2>/dev/null); if [ -s "$f.steps" ] && [ -f "$p" ] && ! grep -q '"stop_hook_active": *true'; then left=$(awk -v m="$f.steps" 'BEGIN { while ((getline l < m) > 0) { split(l, a, "\t"); s[a[1]] = a[2] } } /^##[ \t]/ { on = tolower($0) ~ /step/; next } on && /^[0-9]+[.)][ \t]/ { n = $0 + 0; if (s[n] != "done" && s[n] != "skipped") o = o (o == "" ? "" : ", ") n } END { print o }' "$p"); if [ -n "$left" ]; then printf 'Steps of the plan the user accepted not marked done yet: %s. Finish them now, in order, marking each with bluprint-plan-step. One already finished: mark it done. One no longer wanted, or that cannot be done: `bluprint-plan-step <n> skipped <why>`, and tell the user. If you are waiting on the user, say what you need and stop.\n' "$left" >&2; exit 2; fi; rm -f "$f.accepted"; fi; printf done > "$f.status""#;

/// Claude Code's own dialog shows the plan as its file reads once the hooks
/// have run, and the plan's tab is where it is read: its diagrams are JSON in
/// a terminal. So while the dialog is up the file is only the plan's title and
/// OPEN_PLAN, which the terminal makes a link that opens (or reopens) the
/// plan's tab (components/agent/shell.tsx); it stays in the scrollback, so a closed
/// plan can be found again. The whole plan waits beside the queue (`.hidden`)
/// for RESTORE.
const HIDE: &str = r#"h="$BLUPRINT_CONTEXT.hidden"; p=$(sed -n 's/.*"planFilePath": *"\([^"]*\)".*/\1/p' | head -n 1); [ -f "$p" ] || exit 0; awk '/^# / && !t { print; print ""; t = 1 } END { print "`▸ Open plan`" }' "$p" > "$h.shown" && ! cmp -s "$p" "$h.shown" && cp "$p" "$h" && printf '%s' "$p" > "$h.file" && cp "$h.shown" "$p"; exit 0"#;
/// The whole plan back in its file, at the first hook after the dialog is
/// answered, accepted or not, so a revision starts from it. Unless the file
/// changed meanwhile (the user edited it with ctrl+g): then it is theirs.
const RESTORE: &str = r#"h="$BLUPRINT_CONTEXT.hidden"; [ -e "$h.file" ] || exit 0; p=$(cat "$h.file"); cmp -s "$p" "$h.shown" && cp "$h" "$p"; rm -f "$h" "$h.file" "$h.shown"; exit 0"#;

/// Refuses a Bash call that would start a browser of its own: gstack's shared
/// Chromium (`$B`, browse/dist/browse, which its /browse, /qa, /scrape and
/// design skills drive), or Chrome itself. Exit 2 hands the reason to Claude.
const NO_BROWSER: &str = r#"grep -qE 'browse/dist/browse|\$B [a-z]|Google Chrome|chrome --headless' || exit 0; echo 'Browsing happens in the Preview here (the bluprint-preview tools), never a headless Chromium or Chrome. Do this step with navigate, computer and get_page_text instead.' >&2; exit 2"#;

/// Plan mode still prompts for these despite the allow rules in `prepare`; a
/// hook's allow skips that prompt and still loses to the deny rules.
const PLAN_READS: &str = r#"grep -qE '"permission_mode": *"plan"' || exit 0; echo '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"allow"}}'"#;

/// What Claude is doing, for the dot on its tab: each hook below writes one
/// word, `working`, `waiting` (a question or a permission only the user can
/// answer) or `done`.
fn status(word: &str) -> serde_json::Value {
    serde_json::json!({ "type": "command", "command": format!(r#"printf {word} > "$BLUPRINT_CONTEXT.status""#) })
}

/// At the end of every turn, two markers, for two different readers.
///
/// `.ended` is written always: it names the session's transcript, which is how
/// the app offers to keep an answer on the bluprint (lib/agent/keep.ts). A turn that only
/// answered a question changes no file and files no fix, so the bluprint-following
/// marker below never fires for it — and that is the common case for a reader
/// who just asked how something works.
///
/// `.turn` is written only when the turn may have edited code or found the bluprint
/// wrong (bluprint-fix), and is what makes the bluprint follow the agent. Keeping
/// the two separate means offering to keep an answer never triggers an update,
/// and an edit never implies the reader wanted a note.
const TURN: &str = r#"f="$BLUPRINT_CONTEXT"; s=$(cat); printf '%s' "$s" > "$f.ended.part" && mv "$f.ended.part" "$f.ended"; [ -e "$f.dirty" ] || [ -s "$f.fix" ] || exit 0; rm -f "$f.dirty"; printf '%s' "$s" > "$f.turn.part" && mv "$f.turn.part" "$f.turn"; exit 0"#;

/// What Claude runs when it finds the bluprint wrong: one line per section, kept
/// beside the tab's queue until the turn ends. Allowed without asking.
const FIX: &str = r#"#!/bin/sh
# Tells Bluprint the bluprint is wrong about a section (src-tauri/src/claude.rs).
[ -n "$BLUPRINT_CONTEXT" ] || { echo "Not in a Bluprint tab; nothing to correct." >&2; exit 1; }
[ $# -ge 2 ] || { echo 'usage: bluprint-fix "<section title>" "<what the bluprint gets wrong, and what is true>"' >&2; exit 2; }
printf '%s\t%s\n' "$(printf '%s' "$1" | tr '\t\n' '  ')" "$(printf '%s' "$2" | tr '\t\n' '  ')" >> "$BLUPRINT_CONTEXT.fix"
echo "Noted. The bluprint's \"$1\" will be corrected after this turn."
"#;

/// What Claude runs to put the user in front of what it is talking about: one
/// line per act, taken by the app on its next poll rather than at the end of
/// the turn. Refs are written as the user said them and resolved by the app.
/// Allowed without asking.
const SHOW: &str = r#"#!/bin/sh
# Drives the open bluprint: shows a section, a diff, or the history (src-tauri/src/claude.rs).
[ -n "$BLUPRINT_CONTEXT" ] || { echo "Not in a Bluprint tab; nothing to show." >&2; exit 1; }
clean() { printf '%s' "$1" | tr '\t\n' '  '; }
case "$1" in
section)
  [ -n "$2" ] || { echo 'usage: bluprint-show section "<section title or id>"' >&2; exit 2; }
  printf 'section\t%s\t\n' "$(clean "$2")" >> "$BLUPRINT_CONTEXT.act"
  echo "Showing \"$2\" on the bluprint."
  ;;
diff)
  [ $# -ge 2 ] || { echo 'usage: bluprint-show diff "<from>" ["<to>"]' >&2; exit 2; }
  printf 'diff\t%s\t%s\n' "$(clean "$2")" "$(clean "$3")" >> "$BLUPRINT_CONTEXT.act"
  echo "Showing the diff${2:+ from \"$2\"}${3:+ to \"$3\"} on the bluprint."
  ;;
timeline)
  printf 'timeline\t\t\n' >> "$BLUPRINT_CONTEXT.act"
  echo "Showing the history of the code over the bluprint."
  ;;
*)
  echo 'usage: bluprint-show section "<section title or id>" | bluprint-show diff "<from>" ["<to>"] | bluprint-show timeline' >&2
  exit 2
  ;;
esac
"#;

/// A terminal's output, for any agent in a tab: Claude has `read_terminal`
/// (mcp.rs), and this reaches the same tool for the agents that have no MCP
/// config. Allowed without asking.
const TERMINAL: &str = r#"#!/bin/sh
# Prints what a Bluprint terminal printed, the dev server's by default (src-tauri/src/mcp.rs).
[ -n "$BLUPRINT_MCP_URL" ] || { echo "Not in a Bluprint tab; no terminals to read." >&2; exit 1; }
case "$2" in ''|*[!0-9]*) lines=200 ;; *) lines=$2 ;; esac
name=$(printf '%s' "$1" | sed 's/\\/\\\\/g; s/"/\\"/g' | tr '\t\n' '  ')
curl -sS --fail-with-body "$BLUPRINT_MCP_URL/text" -H 'Content-Type: application/json' \
  -d "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/call\",\"params\":{\"name\":\"read_terminal\",\"arguments\":{\"name\":\"$name\",\"lines\":$lines}}}"
"#;

/// The bluprint's own table of contents, for naming a section that was not picked.
///
/// The user asks "how do sign ups work?" with nothing attached, so the only
/// section names in context are whatever they happened to pick earlier —
/// usually none. Without this, `bluprint-show section` would be a guess at a
/// title that may not exist, which is how a reader ends up somewhere they did
/// not ask to be. The outline is written beside the tab's queue when the tab
/// starts (pty.rs), from the bluprint the page already has.
const LIST: &str = r#"#!/bin/sh
# Lists the open bluprint, section by section (src-tauri/src/claude.rs).
[ -n "$BLUPRINT_CONTEXT" ] || { echo "Not in a Bluprint tab; no bluprint to list." >&2; exit 1; }
[ -s "$BLUPRINT_CONTEXT.bluprint" ] || { echo "This repository has no bluprint yet." >&2; exit 1; }
cat "$BLUPRINT_CONTEXT.bluprint"
"#;

/// What Claude runs to mark a step of the plan it is building (`checklist!`):
/// one line per mark, the latest for a step standing (`steps_of`). Allowed
/// without asking.
const STEP: &str = r#"#!/bin/sh
# Marks a step of the accepted plan, for its tab in Bluprint (src-tauri/src/claude.rs).
[ -n "$BLUPRINT_CONTEXT" ] || { echo "Not in a Bluprint tab; no plan to mark." >&2; exit 1; }
usage='usage: bluprint-plan-step <step number> doing|done|skipped ["why"]'
case "$1" in ''|*[!0-9]*) echo "$usage" >&2; exit 2 ;; esac
case "$2" in doing|done|skipped) ;; *) echo "$usage" >&2; exit 2 ;; esac
n=$1 state=$2
shift 2
printf '%s\t%s\t%s\n' "$n" "$state" "$(printf '%s' "$*" | tr '\t\n' '  ')" >> "$BLUPRINT_CONTEXT.steps"
echo "Step $n: $state."
"#;

const SYSTEM: &str = "This session was opened from Bluprint, an app that bluprints this \
repository as a tree of sections (user journey, data flow, the code behind each). The user \
can attach things they picked on the bluprint: a whole section arrives as a block starting with \
`[Bluprint section:`, one element of a section (a row, a diagram box, a step, a line of code) as \
one starting with `[Bluprint element:`. Each names where it sits on the bluprint, what it says, and \
the code behind it. Treat what is attached as what the user is asking about, and read the \
listed code when it is relevant. Each prompt also opens with a `[Reading now:` line naming \
the section the user has open, followed by that section when it has changed since the last \
prompt. When they ask what they are reading, or say \"this\" or \"here\" with nothing \
attached, they mean that section: summarize or answer from it and the code it lists. It is \
told to you, not shown to them, so never mention having been told where they are. Do not edit files unless asked. The bluprint can be wrong: when \
you find that it is (a listed problem that is not real, a description or a line reference \
that does not match the code), run `bluprint-fix \"<section title>\" \"<what it gets wrong, \
and what is true>\"` once per section, and the bluprint is corrected after your turn. Code you \
change updates the bluprint by itself, deletions included; there is no need to report edits. \
You also drive what the user is looking at. When they ask how something works and nothing \
is attached, run `bluprint-list` to see what the bluprint actually calls its sections, then, if \
one of them is what they are asking about, run `bluprint-show section \"<section title>\"` \
before you explain, naming it exactly as the outline spells it, so \
they are looking at the thing you are explaining as you explain it; the app takes it \
immediately, not at the end of your turn. When they ask to see what changed, run \
`bluprint-show diff \"<from>\" \"<to>\"` — `<to>` may be left off, meaning the working tree, \
and an empty `<from>` means the commit the bluprint was built from. Pass the refs through as the \
user said them, `HEAD~1`, a sha, a branch, or a phrase like \"last commit by hindra2\": the \
app resolves them against the repository, so do not run git to work one out first. When they \
ask how the code got here or how it changed over time, run `bluprint-show timeline`: it draws \
every commit on the bluprint's sections, and they can click through it while you tell the history. \
The `bluprint_search`, `bluprint_section` and `bluprint_where` tools read the bluprint itself. Before you change a \
file, ask `bluprint_where` which sections explain it, so the change fits the part of the product it \
lives in and the user can follow what you are building on the bluprint. \
Keeping the bluprint right is background upkeep, not part of the answer: never tell the user \
whether you edited files, whether the bluprint is accurate, or that there is nothing to correct, \
and mention a correction only in passing when you ran bluprint-fix. What you show is \
likewise not worth narrating — the user can see it, so never announce that you are taking \
them somewhere, though naming the section you are explaining is fine where the prose wants \
it. The app also runs the project: its web app in Preview tabs (often several at once, \
one per page or site, each numbered; the tools' replies list them), and its phone app on an iOS \
Simulator or Android emulator when the user has started one. The bluprint-preview tools use them \
as a person would (screenshot, click, type, read the page, navigate, resize); use them to check \
that a change you made works, or when the user asks about what the app shows; `read_terminal` \
reads the dev server's logs (and the project's other terminals) when something fails. They are also \
your browser: to search the web or read a page as the user would see it, navigate the preview \
there, never another browser: not Chrome, not a headless Chromium. When a skill says to \
drive its own browser (gstack's `$B`), do those steps with the bluprint-preview tools instead. WebSearch and WebFetch are fine for reading docs as text; they \
stay out of the preview. \
A plan you finish in plan mode opens beside you as a short design doc, drawn from its Markdown, \
and is accepted from there. Developers skip a wall of text, so write a plan they take in at a \
glance: short sentences, bullets over paragraphs, a table wherever facts line up in columns, \
nothing restated from the request and nothing written to fill a section. In this order, leaving \
out any part with nothing real to say: `# <what will be built>`, a name of a few words, then two \
sentences: what changes, and what the user gets from it. `## Overview`: three to five bullets on \
how it works, as you would sketch it for a colleague: which part does what, and the decision the \
rest follows from. A picture goes here only when it shows what the bullets cannot, of the kind this \
change calls for, never out of habit: most changes need none, and boxes in a row that restate the \
bullets are worse than none. Each is a fenced block of JSON: a ```diagram when parts are added, \
removed or rewired, {\"caption\" (a few words), \"boxes\": [{\"id\", \"label\" (1-3 words), \"sub\" \
(a file, or a few words), \"col\", \"row\", \"change\", \"section\" (the id path of the bluprint section \
this box is, from bluprint_where or bluprint_search, when it is one)}], \"arrows\": [{\"from\", \"to\", \
\"label\" (1-3 words), \"change\"}]}, on a grid read left to right and at most three columns wide, \
where `change` is \"new\", \"changed\" or \"gone\" and what stays as it is has none; a ```sequence \
when the order of calls is the point, {\"caption\", \"actors\": [names], \"rows\": [{\"from\", \"to\", \
\"label\", \"note\"}]}; a ```screen when the user will see something new, {\"title\", \"device\": \
\"web\" or \"phone\", \"route\", \"items\": [{\"type\": heading, text, field, choice, button, list or \
image, \"label\", \"note\"}]}, with a note on each new item. `## Data` when stored data or an API's \
shape changes: a Markdown table for each table, collection or payload, `| Field | Type | Change | \
Notes |`, a row per field added, changed or dropped, then one line on what happens to what is \
already stored. `## Steps`: numbered, at most eight, each one line in plain words naming a piece of \
work that can be finished and checked on its own, in the order you will do it; once the plan is \
accepted they are your checklist. `## Trade-offs` only when you chose between real options: \
`**Pros**` and `**Cons**`, two or three bullets each, then the option you passed over in one line \
with why. `## Files`: a ```files block, one line per file: `+ path — what it is`, `~ path — what \
changes` or `- path — why it goes`. `## Risks` only when there are real ones, a bullet each with \
what you will do about it. `## Check`: one to three bullets on how you will know it works. A \
one-file fix is the title, its two sentences, Steps, Files and Check. Stay under 250 words outside \
the fenced blocks, and write code only where a signature is the decision. \
End on the answer itself.";

#[derive(serde::Deserialize)]
pub struct Launch {
    path: String,
    model: Option<String>,
    #[serde(default)]
    voice: bool,
    #[serde(default)]
    research: bool,
}

/// Runs Claude with the hook, and marks the tab live while it does. The marker,
/// and the conversation the tab would be reopened into, go on any exit — a
/// quit, a crash, Ctrl+C — and the script's status is Claude's.
const LAUNCHER: &str = r#"#!/bin/sh
# Claude Code with the bluprint-context hook (src-tauri/src/claude.rs).
trap 'rm -f "$BLUPRINT_CONTEXT.live" "$BLUPRINT_CONTEXT.session"' EXIT INT TERM HUP
: > "$BLUPRINT_CONTEXT.live"
# A reopened tab's conversation, taken once: a `claude` typed later starts afresh.
r=$(cat "$BLUPRINT_CONTEXT.resume" 2>/dev/null); rm -f "$BLUPRINT_CONTEXT.resume"
# Claude Code keeps a conversation only once it has a message: one never
# written to cannot be resumed, so that tab starts afresh rather than failing.
[ -n "$r" ] && [ -z "$(find "${CLAUDE_CONFIG_DIR:-$HOME/.claude}/projects" -maxdepth 2 -name "$r.jsonl" 2>/dev/null | head -n 1)" ] && r=
"$BLUPRINT_CLAUDE_BIN" --settings "$BLUPRINT_CLAUDE_SETTINGS" --append-system-prompt "$BLUPRINT_CLAUDE_SYSTEM" ${BLUPRINT_CLAUDE_MODEL:+--model "$BLUPRINT_CLAUDE_MODEL"} ${BLUPRINT_CLAUDE_MCP:+--mcp-config "$BLUPRINT_CLAUDE_MCP"} ${r:+--resume "$r"} "$@"
"#;

/// `claude` typed in a tab: the launcher, so it is in front and takes context
/// like one the app started. Not from Claude's own Bash tool, nor from a script
/// with no terminal (the generator's `claude -p`, which clears `CLAUDECODE`),
/// where the launcher's exit would take the tab's live marker from the Claude still running.
#[cfg(unix)]
const CLAUDE_SHIM: &str = r#"#!/bin/sh
[ -n "$CLAUDECODE" ] && exec "$BLUPRINT_CLAUDE_BIN" "$@"
[ -t 0 ] || exec "$BLUPRINT_CLAUDE_BIN" "$@"
exec "$BLUPRINT_LAUNCHER" "$@"
"#;

/// zsh in a tab starts from here (`ZDOTDIR`), so the shim stays first on PATH
/// after the user's own startup files: a `.zshrc` that puts `~/.local/bin`
/// first would otherwise find the real `claude`, and a `claude` typed in the tab
/// would run without the hooks (no plan tab, no status, no bluprint context).
/// Each file loads the user's own from where zsh would have read it.
#[cfg(unix)]
const ZSHENV: &str = r#"# Bluprint's zsh startup (src-tauri/src/claude.rs).
_bluprint_dot=$ZDOTDIR
ZDOTDIR=${BLUPRINT_ZDOTDIR:-$HOME}
[ -f "$ZDOTDIR/.zshenv" ] && source "$ZDOTDIR/.zshenv"
# Their .zshenv may move ZDOTDIR: that is where their .zshrc is.
BLUPRINT_ZDOTDIR=$ZDOTDIR
ZDOTDIR=$_bluprint_dot
unset _bluprint_dot
"#;
/// Read by a login zsh (every tab on macOS) between .zshenv and .zshrc. The
/// re-prepend matters for `zsh -l -c`, which reads no .zshrc.
#[cfg(unix)]
const ZPROFILE: &str = r#"# Bluprint's zsh startup (src-tauri/src/claude.rs).
_bluprint_dot=$ZDOTDIR
ZDOTDIR=$BLUPRINT_ZDOTDIR
[ -f "$ZDOTDIR/.zprofile" ] && source "$ZDOTDIR/.zprofile"
ZDOTDIR=$_bluprint_dot
unset _bluprint_dot
[ -n "$BLUPRINT_BIN" ] && PATH="$BLUPRINT_BIN:$PATH"
"#;
#[cfg(unix)]
const ZSHRC: &str = r#"# Bluprint's zsh startup (src-tauri/src/claude.rs).
ZDOTDIR=$BLUPRINT_ZDOTDIR
[ "$ZDOTDIR" = "$HOME" ] && unset ZDOTDIR
[ -f "${ZDOTDIR:-$HOME}/.zshrc" ] && source "${ZDOTDIR:-$HOME}/.zshrc"
[ -n "$BLUPRINT_BIN" ] && PATH="$BLUPRINT_BIN:$PATH"
"#;

#[derive(serde::Serialize)]
pub struct Detected {
    path: String,
    version: Option<String>,
}

use crate::proc::home;

fn expand(p: &str, home: Option<&Path>) -> PathBuf {
    match (p.strip_prefix("~/"), home) {
        (Some(rest), Some(h)) => h.join(rest),
        _ => PathBuf::from(p),
    }
}

/// Where the installers put it. An app started from the desktop has no shell
/// PATH, so these are checked before asking a login shell.
#[cfg(not(windows))]
fn candidates(home: Option<&Path>) -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Some(h) = home {
        out.push(h.join(".local/bin/claude"));
        out.push(h.join(".claude/local/claude"));
    }
    out.push("/opt/homebrew/bin/claude".into());
    out.push("/usr/local/bin/claude".into());
    out
}

/// The native installer's, then npm's.
#[cfg(windows)]
fn candidates(home: Option<&Path>) -> Vec<PathBuf> {
    let mut out = Vec::new();
    if let Some(h) = home {
        out.push(h.join(r".local\bin\claude.exe"));
        out.push(h.join(r".claude\local\claude.exe"));
    }
    if let Some(appdata) = std::env::var_os("APPDATA") {
        out.push(PathBuf::from(appdata).join(r"npm\claude.cmd"));
    }
    out
}

#[cfg(not(windows))]
fn on_path() -> Option<PathBuf> {
    let shell = std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".into());
    let out = crate::proc::command(shell).args(["-lc", "command -v claude"]).output().ok()?;
    let p = PathBuf::from(String::from_utf8_lossy(&out.stdout).trim());
    p.is_file().then_some(p)
}

#[cfg(windows)]
fn on_path() -> Option<PathBuf> {
    crate::proc::where_is("claude").into_iter().find(|p| p.is_file())
}

/// Git for Windows' bash, which runs the launcher and the scripts beside it
/// on Windows, as it runs Claude Code's own hooks and Bash tool there: where
/// Claude Code is told it is, else beside the `git` on PATH, else where its
/// installer puts it.
#[cfg(windows)]
fn git_bash() -> Option<PathBuf> {
    let told = std::env::var_os("CLAUDE_CODE_GIT_BASH_PATH").map(PathBuf::from);
    let beside_git = crate::proc::where_is("git")
        .into_iter()
        .filter_map(|g| Some(g.parent()?.parent()?.join(r"bin\bash.exe")));
    let installed = ["ProgramFiles", "ProgramW6432", "LOCALAPPDATA"]
        .iter()
        .filter_map(std::env::var_os)
        .map(|d| PathBuf::from(d).join(r"Git\bin\bash.exe"));
    told.into_iter().chain(beside_git).chain(installed).find(|p| p.is_file())
}

fn find(configured: Option<&str>, home: Option<&Path>) -> Option<PathBuf> {
    if let Some(c) = configured.map(str::trim).filter(|c| !c.is_empty()) {
        let p = expand(c, home);
        return p.is_file().then_some(p);
    }
    if let Some(p) = candidates(home).into_iter().find(|p| p.is_file()) {
        return Some(p);
    }
    on_path()
}

/// The configured path if it exists, else wherever Claude Code is installed.
/// Async so the login-shell lookup never blocks the window.
#[tauri::command]
pub async fn claude_detect(configured: Option<String>) -> Option<Detected> {
    let path = find(configured.as_deref(), home().as_deref())?;
    let version = crate::proc::command(&path)
        .arg("--version")
        .output()
        .ok()
        .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        .filter(|v| !v.is_empty());
    Some(Detected { path: path.to_string_lossy().into_owned(), version })
}

/// This tab's queue. Not created here: the first pick creates it, and the hook
/// removes it each time it delivers.
pub fn queue(id: u32) -> PathBuf {
    std::env::temp_dir()
        .join("bluprint")
        .join(format!("context-{}-{id}.md", std::process::id()))
}

/// Removes the tab's queue and everything kept beside it: every file named
/// `context-<pid>-<tab>.md` plus a suffix, so a marker added later (or a
/// `.part` a hook left half-written) goes with the rest.
pub fn forget(queue: &Path) {
    let (Some(dir), Some(name)) = (queue.parent(), queue.file_name().and_then(|n| n.to_str())) else { return };
    remove_named(dir, |f| f == name || f.strip_prefix(name).is_some_and(|rest| rest.starts_with('.')));
}

fn remove_named(dir: &Path, doomed: impl Fn(&str) -> bool) {
    let Ok(entries) = std::fs::read_dir(dir) else { return };
    for e in entries.flatten() {
        if e.file_name().to_str().is_some_and(&doomed) {
            let _ = std::fs::remove_file(e.path());
        }
    }
}

/// At startup: the tab files of a Bluprint that is gone. A crash or a kill skips
/// `forget`, and the files would wait for a reboot. Another Bluprint still
/// running (the dev build beside the installed one) keeps its own.
pub fn sweep_stale() {
    let Some(dir) = queue(0).parent().map(Path::to_path_buf) else { return };
    let me = std::process::id();
    remove_named(&dir, |f| {
        let Some(pid) = f.strip_prefix("context-").and_then(|r| r.split('-').next()).and_then(|p| p.parse::<u32>().ok()) else {
            return false;
        };
        pid != me && !alive(pid, &dir.join(f))
    });
}

/// How long a plan Claude Code wrote may sit untouched before it goes: the
/// same as Claude Code's own default for keeping sessions.
pub const PLAN_AGE: std::time::Duration = std::time::Duration::from_secs(30 * 24 * 3600);

/// Where Claude Code keeps the plans it writes in plan mode.
fn plans_dir() -> Option<PathBuf> {
    let config = std::env::var_os("CLAUDE_CONFIG_DIR").map(PathBuf::from).or_else(|| crate::proc::home().map(|h| h.join(".claude")))?;
    Some(config.join("plans"))
}

/// At startup: plans nothing has touched in `PLAN_AGE`. Nothing reads them
/// once their session is over (a plan's tab holds its own copy), and Claude
/// Code never removes them. A plan being shown right now was just rewritten
/// by HIDE, so it is never old.
pub fn prune_plans() {
    if let Some(dir) = plans_dir() {
        prune_older(&dir, PLAN_AGE);
    }
}

fn prune_older(dir: &Path, age: std::time::Duration) {
    let Ok(entries) = std::fs::read_dir(dir) else { return };
    for e in entries.flatten() {
        let path = e.path();
        let old = e
            .metadata()
            .ok()
            .filter(|m| m.is_file())
            .and_then(|m| m.modified().ok())
            .and_then(|t| t.elapsed().ok())
            .is_some_and(|a| a > age);
        if old && path.extension().is_some_and(|x| x == "md") {
            let _ = std::fs::remove_file(path);
        }
    }
}

#[cfg(unix)]
fn alive(pid: u32, _file: &Path) -> bool {
    crate::proc::command("kill").args(["-0", &pid.to_string()]).stderr(std::process::Stdio::null()).status().is_ok_and(|s| s.success())
}

/// No cheap liveness check without a dependency: a day untouched is gone.
#[cfg(not(unix))]
fn alive(_pid: u32, file: &Path) -> bool {
    let age = std::fs::metadata(file).and_then(|m| m.modified()).ok().and_then(|t| t.elapsed().ok());
    age.map_or(true, |a| a < std::time::Duration::from_secs(24 * 3600))
}

/// A plan Claude is waiting to have accepted: its Markdown, and the file
/// Claude Code keeps it in.
#[derive(serde::Serialize, Debug)]
pub struct Plan {
    text: String,
    file: Option<String>,
}

/// The plan Claude asked to start on since this was last asked. Taking it
/// clears it, so each plan opens its tab once.
pub fn take_plan(queue: &Path) -> Option<Plan> {
    let marker = queue.with_extension("md.plan");
    let hook = std::fs::read_to_string(&marker).ok()?;
    let _ = std::fs::remove_file(&marker);
    let input = serde_json::from_str::<serde_json::Value>(&hook).ok()?;
    let input = input.get("tool_input")?;
    Some(Plan {
        text: input.get("plan")?.as_str()?.to_string(),
        file: input.get("planFilePath").and_then(|f| f.as_str()).map(String::from),
    })
}

/// Whether the plan was accepted since this was last asked; reported once.
pub fn take_approved(queue: &Path) -> bool {
    std::fs::remove_file(queue.with_extension("md.approved")).is_ok()
}

/// A step of the accepted plan as Claude last marked it (STEP).
#[derive(serde::Serialize, Debug, PartialEq)]
pub struct Step {
    n: u32,
    /// `doing`, `done` or `skipped`.
    state: String,
    /// Why it was skipped.
    note: Option<String>,
}

/// The accepted plan's steps Claude has marked, each at its latest mark, in
/// order. Read on every poll rather than taken: the plan's tab keeps showing
/// them, and a new plan clears them (PLAN).
pub fn steps_of(queue: &Path) -> Vec<Step> {
    let Ok(text) = std::fs::read_to_string(queue.with_extension("md.steps")) else { return Vec::new() };
    let mut out: Vec<Step> = Vec::new();
    for l in text.lines() {
        let mut f = l.split('\t');
        let (Some(n), Some(state)) = (f.next().and_then(|n| n.trim().parse().ok()), f.next().map(str::trim)) else { continue };
        if !["doing", "done", "skipped"].contains(&state) {
            continue;
        }
        let note = f.next().map(str::trim).filter(|s| !s.is_empty()).map(String::from);
        out.retain(|s| s.n != n);
        out.push(Step { n, state: state.to_string(), note });
    }
    out.sort_by_key(|s| s.n);
    out
}

/// Something Claude asked the app to show. Serializes tagged on `verb`, for a
/// discriminated union on the page: `{"verb":"section","section":"Sign ups"}`,
/// or `{"verb":"diff","from":"HEAD~1","to":null}` — `from` empty meaning the
/// bluprint's own commit, `to` null meaning the working tree. Refs arrive as Claude
/// wrote them; resolving them is the page's job.
#[derive(serde::Serialize, Debug, PartialEq)]
#[serde(tag = "verb", rename_all = "lowercase")]
pub enum Act {
    Section { section: String },
    Diff { from: String, to: Option<String> },
    /// The history of the code, drawn over the bluprint's sections.
    Timeline,
}

/// What Claude has asked to show since this was last asked. Taking it clears
/// it, so each act happens once.
///
/// Deliberately not tied to the end of the turn, unlike `take_turn` and
/// `take_ended`: Claude shows a section as it starts explaining it, and the
/// point is that the user is looking at it while the answer streams. So this is
/// drained on every poll, with no Stop marker involved.
pub fn take_acts(queue: &Path) -> Vec<Act> {
    let marker = queue.with_extension("md.act");
    let Ok(text) = std::fs::read_to_string(&marker) else { return Vec::new() };
    let _ = std::fs::remove_file(&marker);
    text.lines()
        .filter_map(|l| {
            let mut f = l.split('\t');
            match (f.next()?, f.next()?.trim(), f.next().unwrap_or("").trim()) {
                ("section", s, _) if !s.is_empty() => Some(Act::Section { section: s.to_string() }),
                ("diff", from, to) => Some(Act::Diff {
                    from: from.to_string(),
                    to: (!to.is_empty()).then(|| to.to_string()),
                }),
                ("timeline", _, _) => Some(Act::Timeline),
                _ => None,
            }
        })
        .collect()
}

/// A finished turn the bluprint should follow: where its transcript is, and the
/// sections Claude found the bluprint wrong about.
#[derive(serde::Serialize, Debug)]
pub struct Turn {
    transcript: Option<String>,
    corrections: Vec<Correction>,
}

#[derive(serde::Serialize, Debug, PartialEq)]
pub struct Correction {
    section: String,
    note: String,
}

/// The transcript of the turn Claude just finished, whatever it did. Taking it
/// clears it, so each turn is offered once. Unlike `take_turn` this fires for a
/// turn that only answered a question, which is what the reader keeps.
pub fn take_ended(queue: &Path) -> Option<String> {
    let marker = queue.with_extension("md.ended");
    let stop = std::fs::read_to_string(&marker).ok()?;
    let _ = std::fs::remove_file(&marker);
    serde_json::from_str::<serde_json::Value>(&stop)
        .ok()
        .and_then(|v| v.get("transcript_path")?.as_str().map(String::from))
}

/// The turn Claude finished since this was last asked, if it edited code or
/// found the bluprint wrong. Taking it clears it, so each is reported once.
pub fn take_turn(queue: &Path) -> Option<Turn> {
    let marker = queue.with_extension("md.turn");
    let stop = std::fs::read_to_string(&marker).ok()?;
    let _ = std::fs::remove_file(&marker);
    let transcript = serde_json::from_str::<serde_json::Value>(&stop)
        .ok()
        .and_then(|v| v.get("transcript_path")?.as_str().map(String::from));
    let fix = queue.with_extension("md.fix");
    let corrections = std::fs::read_to_string(&fix)
        .unwrap_or_default()
        .lines()
        .filter_map(|l| l.split_once('\t'))
        .map(|(s, n)| Correction { section: s.trim().to_string(), note: n.trim().to_string() })
        .collect();
    let _ = std::fs::remove_file(&fix);
    Some(Turn { transcript, corrections })
}

/// Present while the launcher's Claude runs in the tab that owns `queue`.
fn live(queue: &Path) -> PathBuf {
    queue.with_extension("md.live")
}

pub fn running(queue: &Path) -> bool {
    live(queue).exists()
}

fn session(queue: &Path) -> PathBuf {
    queue.with_extension("md.session")
}

/// The conversation Claude has in the tab that owns `queue`, while it runs.
pub fn session_of(queue: &Path) -> Option<String> {
    std::fs::read_to_string(session(queue)).ok().map(|s| s.trim().to_string()).filter(|s| !s.is_empty())
}

/// A tab reopened into `id`: the launcher resumes it, in a file rather than the
/// tab's command line so the user's shell never has to split it. The tab counts
/// as that conversation's from the start, so a restart before Claude is up does
/// not lose it, and a resume that fails drops it when the launcher exits.
pub fn resuming(queue: &Path, id: &str) -> std::io::Result<()> {
    if let Some(dir) = queue.parent() {
        std::fs::create_dir_all(dir)?;
    }
    std::fs::write(queue.with_extension("md.resume"), id)?;
    std::fs::write(session(queue), format!("{id}\n"))
}

/// The last word a status hook wrote; none before Claude's first prompt.
pub fn status_of(queue: &Path) -> Option<String> {
    std::fs::read_to_string(queue.with_extension("md.status")).ok().map(|s| s.trim().to_string())
}

/// The launcher, and the scripts Claude talks back through beside it, written
/// where every tab's PATH can find them. Rewritten only when they differ, so
/// an upgrade of the app replaces old ones.
fn launcher() -> std::io::Result<PathBuf> {
    let dir = std::env::temp_dir().join("bluprint").join("bin");
    install(&dir.join("bluprint-fix"), FIX)?;
    install(&dir.join("bluprint-show"), SHOW)?;
    install(&dir.join("bluprint-list"), LIST)?;
    install(&dir.join("bluprint-plan-step"), STEP)?;
    install(&dir.join("bluprint-terminal"), TERMINAL)?;
    let path = dir.join("bluprint-claude");
    install(&path, LAUNCHER)?;
    #[cfg(unix)]
    {
        install(&dir.join("claude"), CLAUDE_SHIM)?;
        install(&zdotdir().join(".zshenv"), ZSHENV)?;
        install(&zdotdir().join(".zprofile"), ZPROFILE)?;
        install(&zdotdir().join(".zshrc"), ZSHRC)?;
    }
    #[cfg(windows)]
    let path = {
        let cmd = dir.join("bluprint-claude.cmd");
        install(&cmd, LAUNCHER_CMD)?;
        cmd
    };
    Ok(path)
}

#[cfg(unix)]
fn zdotdir() -> PathBuf {
    std::env::temp_dir().join("bluprint").join("zsh")
}

/// What cmd and PowerShell find as `bluprint-claude` on Windows: the launcher,
/// run by Git for Windows' bash (`git_bash`).
#[cfg(windows)]
const LAUNCHER_CMD: &str = "@echo off\r\n\
if not defined BLUPRINT_BASH (\r\n\
  echo Claude Code in Bluprint needs Git for Windows: https://git-scm.com/download/win 1>&2\r\n\
  exit /b 1\r\n\
)\r\n\
\"%BLUPRINT_BASH%\" \"%~dp0bluprint-claude\" %*\r\n";

fn install(path: &Path, script: &str) -> std::io::Result<()> {
    if std::fs::read_to_string(path).ok().as_deref() != Some(script) {
        std::fs::create_dir_all(path.parent().unwrap_or(Path::new(".")))?;
        std::fs::write(path, script)?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o755))?;
        }
    }
    Ok(())
}

/// What a tab's shell needs so that the launcher works in it: the user's
/// `claude`, the hook, the system prompt, the preview's tools (mcp.rs), and
/// the launcher on PATH. Returns the launcher's own path, for starting Claude
/// without relying on PATH.
pub fn prepare(cmd: &mut CommandBuilder, launch: &Launch, queue: &Path, outline: Option<&str>, tab: u32) -> std::io::Result<PathBuf> {
    let path = launcher()?;
    // The page has the bluprint; this only keeps it where bluprint-list can read it.
    // Written per tab and cleared with the tab, so it never outlives the bluprint it
    // was taken from.
    if let Some(text) = outline.map(str::trim).filter(|t| !t.is_empty()) {
        if let Some(dir) = queue.parent() {
            std::fs::create_dir_all(dir)?;
        }
        std::fs::write(queue.with_extension("md.bluprint"), format!("{text}\n"))?;
    }
    let hook = |c: &str| serde_json::json!({ "type": "command", "command": c });
    let mut settings = serde_json::json!({
        "hooks": {
            "SessionStart": [
                { "hooks": [hook(ON_PATH), hook(SESSION)] },
                { "matcher": "startup", "hooks": [hook(FRESH)] },
                { "matcher": "clear", "hooks": [hook(CLEARED)] },
                { "matcher": "compact", "hooks": [hook(REMIND)] }
            ],
            "UserPromptSubmit": [{ "hooks": [hook(HOOK), status("working")] }],
            "PreToolUse": [
                { "matcher": "AskUserQuestion|ExitPlanMode", "hooks": [status("waiting")] },
                { "matcher": "ExitPlanMode", "hooks": [hook(PLAN), hook(HIDE)] },
                // Not on ExitPlanMode itself, whose HIDE runs beside it.
                { "matcher": "^(?!ExitPlanMode$)", "hooks": [hook(RESTORE)] },
                { "matcher": "Bash", "hooks": [hook(NO_BROWSER)] },
                { "matcher": "^(mcp__bluprint-preview__.*|WebSearch|WebFetch|Skill)$", "hooks": [hook(PLAN_READS)] }
            ],
            "PostToolUse": [
                { "matcher": EDITING_TOOLS, "hooks": [hook(EDITED)] },
                { "matcher": "ExitPlanMode", "hooks": [hook(APPROVED), hook(TODOS)] },
                { "hooks": [hook(RESTORE), status("working")] }
            ],
            "Notification": [{ "matcher": "permission_prompt|elicitation_dialog", "hooks": [status("waiting")] }],
            "Stop": [{ "hooks": [hook(TURN), hook(RESTORE), hook(UNFINISHED)] }],
            "SessionEnd": [{ "hooks": [hook(RESTORE)] }]
        },
        "permissions": {
            "allow": ["Bash(bluprint-fix:*)", "Bash(bluprint-show:*)", "Bash(bluprint-list:*)", "Bash(bluprint-plan-step:*)", "Bash(bluprint-terminal:*)", "mcp__bluprint-preview"],
            // The preview is the browser here: Chrome would open beside the app, out of the user's sight.
            // So is gstack's headless Chromium: these skills do nothing but drive it, or hand it Chrome's sign-ins.
            "deny": [
                "mcp__claude-in-chrome",
                "Skill(browse)", "Skill(connect-chrome)", "Skill(open-gstack-browser)",
                "Skill(setup-browser-cookies)", "Skill(pair-agent)", "Skill(scrape)", "Skill(skillify)"
            ]
        }
    });
    // Only ever turned on here: with the setting off, the user's own `/voice` stands.
    if launch.voice {
        settings["voice"] = serde_json::json!({ "enabled": true });
    }
    // Lets plan mode research without a prompt per step; plan mode still blocks edits.
    if launch.research {
        if let Some(allow) = settings["permissions"]["allow"].as_array_mut() {
            allow.extend(["Skill", "WebSearch", "WebFetch"].map(serde_json::Value::from));
        }
    }
    cmd.env("BLUPRINT_CONTEXT", queue);
    cmd.env("BLUPRINT_LAUNCHER", &path);
    cmd.env("BLUPRINT_CLAUDE_BIN", &launch.path);
    cmd.env("BLUPRINT_CLAUDE_SETTINGS", settings.to_string());
    cmd.env("BLUPRINT_CLAUDE_SYSTEM", SYSTEM);
    if let Some(mcp) = crate::mcp::config(tab) {
        cmd.env("BLUPRINT_CLAUDE_MCP", mcp);
    }
    if let Some(url) = crate::mcp::url(tab) {
        cmd.env("BLUPRINT_MCP_URL", url);
    }
    if let Some(m) = launch.model.as_deref().map(str::trim).filter(|m| !m.is_empty()) {
        cmd.env("BLUPRINT_CLAUDE_MODEL", m);
    }
    #[cfg(windows)]
    if let Some(bash) = git_bash() {
        cmd.env("BLUPRINT_BASH", bash);
    }
    if let Some(dir) = path.parent() {
        cmd.env("BLUPRINT_BIN", dir);
        let rest = std::env::var_os("PATH").unwrap_or_default();
        let joined = std::env::join_paths(std::iter::once(dir.to_path_buf()).chain(std::env::split_paths(&rest)))
            .map_err(std::io::Error::other)?;
        cmd.env("PATH", joined);
    }
    // Other shells ignore it.
    #[cfg(unix)]
    {
        // A Bluprint started from one of Bluprint's own terminals inherits our
        // ZDOTDIR: taken as theirs, our .zshenv would source itself forever.
        if let Some(theirs) = std::env::var_os("ZDOTDIR").filter(|z| Path::new(z) != zdotdir()) {
            cmd.env("BLUPRINT_ZDOTDIR", theirs);
        }
        cmd.env("ZDOTDIR", zdotdir());
    }
    Ok(path)
}

/// Adds one block to the queue, after anything not yet delivered.
pub fn append(queue: &Path, text: &str) -> std::io::Result<()> {
    if let Some(dir) = queue.parent() {
        std::fs::create_dir_all(dir)?;
    }
    let mut f = std::fs::OpenOptions::new().create(true).append(true).open(queue)?;
    writeln!(f, "{}\n", text.trim_end())
}

/// Where the user is on the bluprint, rewritten whenever they move. Written whole
/// and renamed into place, so a prompt never reads half of it.
pub fn place(queue: &Path, text: &str) -> std::io::Result<()> {
    if let Some(dir) = queue.parent() {
        std::fs::create_dir_all(dir)?;
    }
    let to = queue.with_extension("md.where");
    let part = queue.with_extension("md.where.part");
    std::fs::write(&part, format!("{}\n", text.trim_end()))?;
    std::fs::rename(part, to)
}

/// Replaces what is still waiting. Empty clears it.
pub fn replace(queue: &Path, text: &str) -> std::io::Result<()> {
    if text.trim().is_empty() {
        // Only the queue: `forget` would also drop the tab's live, bluprint and fix state.
        let _ = std::fs::remove_file(queue);
        return Ok(());
    }
    if let Some(dir) = queue.parent() {
        std::fs::create_dir_all(dir)?;
    }
    std::fs::write(queue, format!("{}\n\n", text.trim_end()))
}

pub fn pending(queue: &Path) -> bool {
    std::fs::metadata(queue).is_ok_and(|m| m.len() > 0)
}

