    fn the_launcher_marks_the_tab_live_while_claude_runs() {
        let dir = tempfile::tempdir().unwrap();
        let q = dir.path().join("context-1.md");
        // A stand-in Claude that reports whether the marker is there.
        let probe = dir.path().join("probe");
        std::fs::write(&probe, format!("#!/bin/sh\n[ -e '{}' ] && exit 7\nexit 3\n", live(&q).display())).unwrap();
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&probe, std::fs::Permissions::from_mode(0o755)).unwrap();

        assert!(!running(&q));
        // Live while it ran (7), and Claude's own status comes back.
        assert_eq!(launch(&q, probe.to_str().unwrap()).code(), Some(7));
        assert!(!running(&q));
        // Gone after a failing exit too.
        assert!(!launch(&q, "/bin/false").success());
        assert!(!running(&q));
    }

    #[cfg(unix)]
    #[test]
    fn the_tab_keeps_its_conversation_while_claude_runs() {
        use std::io::Write as _;
        let dir = tempfile::tempdir().unwrap();
        let q = dir.path().join("context-1.md");
        let start = |input: &str| {
            let mut child = Command::new("sh")
                .args(["-c", SESSION])
                .env("BLUPRINT_CONTEXT", &q)
                .stdin(std::process::Stdio::piped())
                .spawn()
                .unwrap();
            child.stdin.take().unwrap().write_all(input.as_bytes()).unwrap();
            assert!(child.wait().unwrap().success());
        };
        start(r#"{"session_id": "abc-1", "source": "startup"}"#);
        assert_eq!(session_of(&q).as_deref(), Some("abc-1"));
        // A /clear is a new conversation; input without one changes nothing.
        start(r#"{"session_id":"abc-2","source":"clear"}"#);
        start("{}");
        assert_eq!(session_of(&q).as_deref(), Some("abc-2"));
        // A reopened tab has it from the start, and loses it when Claude exits.
        resuming(&q, "abc-3").unwrap();
        assert_eq!(session_of(&q).as_deref(), Some("abc-3"));
        assert!(!launch(&q, "/usr/bin/false").success());
        assert!(session_of(&q).is_none());
        // Claude is handed it as its own two arguments, once.
        let args = dir.path().join("args");
        let probe = dir.path().join("probe");
        std::fs::write(&probe, format!("#!/bin/sh
printf '[%s]' \"$@\" > '{}'\n", args.display())).unwrap();
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&probe, std::fs::Permissions::from_mode(0o755)).unwrap();
        // Only a conversation Claude Code kept: one never written to starts afresh.
        resuming(&q, "abc-5").unwrap();
        launch(&q, probe.to_str().unwrap());
        assert!(!std::fs::read_to_string(&args).unwrap().contains("--resume"));
        std::fs::create_dir_all(dir.path().join("projects/p")).unwrap();
        std::fs::write(dir.path().join("projects/p/abc-4.jsonl"), "").unwrap();
        resuming(&q, "abc-4").unwrap();
        launch(&q, probe.to_str().unwrap());
        assert!(std::fs::read_to_string(&args).unwrap().ends_with("[--resume][abc-4]"));
        launch(&q, probe.to_str().unwrap());
        assert!(!std::fs::read_to_string(&args).unwrap().contains("--resume"));
    }

    #[test]
    fn queue_appends_replaces_and_forgets() {
        let dir = tempfile::tempdir().unwrap();
        let q = dir.path().join("sub/context-1.md");
        assert!(!pending(&q));
        append(&q, "[Bluprint section: A]").unwrap();
        append(&q, "[Bluprint section: B]").unwrap();
        let text = std::fs::read_to_string(&q).unwrap();
        assert!(text.contains("A]") && text.contains("B]"));
        assert!(pending(&q));
        replace(&q, "[Bluprint section: B]").unwrap();
        assert!(!std::fs::read_to_string(&q).unwrap().contains("A]"));
        replace(&q, "").unwrap();
        assert!(!pending(&q) && !q.exists());
    }

    #[test]
    fn prune_takes_only_old_plans() {
        let dir = tempfile::tempdir().unwrap();
        let at = |name: &str, days: u64| {
            let p = dir.path().join(name);
            std::fs::write(&p, "# Plan\n").unwrap();
            let then = std::time::SystemTime::now() - std::time::Duration::from_secs(days * 24 * 3600);
            std::fs::File::options().write(true).open(&p).unwrap().set_modified(then).unwrap();
            p
        };
        let old = at("old.md", 40);
        let fresh = at("fresh.md", 2);
        let other = at("notes.txt", 40);
        std::fs::create_dir(dir.path().join("sub.md")).unwrap();
        prune_older(dir.path(), PLAN_AGE);
        assert!(!old.exists());
        assert!(fresh.exists() && other.exists() && dir.path().join("sub.md").is_dir());
        // A folder that is not there is nothing to do.
        prune_older(&dir.path().join("missing"), PLAN_AGE);
    }
}

app/src-tauri/src/devices.rs:
//! What a project runs as, and the phones it runs on.
//!
//! `project_detect` reads a checkout for how to start it: a web dev server
//! (components/agent/workspace.tsx starts it when the project opens, and the preview
//! follows it), an Android app, an iOS app. Nothing is installed for a phone
//! until a project has one and the user asks: then `device_setup` writes a
//! script that a terminal tab runs in front of them, so every download and
//! license is theirs to see and stop.
//!
//! Android needs no Android Studio: Google publishes the SDK's command-line
//! tools, emulator and system images on their own, and they go under the
//! app's data folder (or an SDK already on the machine is used). The iOS
//! Simulator only comes with Xcode, which only Apple distributes, so setting
//! it up means installing Xcode once; it is never opened. Either way the
//! phone runs with no window of its own and its screen is drawn in the app's
//! tab (components/preview/device.tsx), from screenshots, with taps sent back: `adb`
//! for Android, `simctl` and `idb` for iOS.

use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::{Mutex, OnceLock};
use std::time::{Duration, Instant};

/* ── what a project runs as ───────────────────────────────────── */

#[derive(Clone, Copy, PartialEq, Debug)]
enum Kind {
    Expo,
    ReactNative,
    Flutter,
    Native,
}

fn package(root: &Path) -> Option<serde_json::Value> {
    serde_json::from_str(&std::fs::read_to_string(root.join("package.json")).ok()?).ok()
}

fn depends_on(pkg: &serde_json::Value, name: &str) -> bool {
    ["dependencies", "devDependencies"].iter().any(|k| pkg.get(k).and_then(|d| d.get(name)).is_some())
}

fn kind(root: &Path) -> Kind {
    if root.join("pubspec.yaml").is_file() {
        return Kind::Flutter;
    }
    match package(root) {
        Some(p) if depends_on(&p, "expo") => Kind::Expo,
        Some(p) if depends_on(&p, "react-native") => Kind::ReactNative,
        _ => Kind::Native,
    }
}

/// The package manager the lockfile names, as `(install, run <script>)`.
fn manager(root: &Path) -> (&'static str, &'static str) {
    if root.join("pnpm-lock.yaml").is_file() {
        ("pnpm install", "pnpm run")
    } else if root.join("yarn.lock").is_file() {
        ("yarn install", "yarn run")
    } else if root.join("bun.lockb").is_file() || root.join("bun.lock").is_file() {
        ("bun install", "bun run")
    } else {
        ("npm install", "npm run")
    }
}

/// The command that serves a folder as a web app, if it is one: its `dev`
/// script; for a React Native app, its `web` script when it can run on the web
/// at all; else a `start` that is not a phone's bundler. Dependencies are
/// installed first when they never were. `BROWSER=none` keeps Vite, Create
/// React App and the like from opening a browser of their own.
///
/// A folder with no such script but an `index.html` is a plain site, served
/// as files on a free port by the Python every Mac and most machines have.
fn site(dir: &Path, root: &Path) -> Option<(u8, String)> {
    if let Some((script, start)) = served(dir, root) {
        return Some((if script == "start" { 1 } else { 0 }, start));
    }
    if !dir.join("index.html").is_file() {
        return None;
    }
    let python = if cfg!(windows) { "python" } else { "python3" };
    Some((2, format!("{python} -m http.server 0 --bind 127.0.0.1")))
}

/// A web app the project has, and how to start it.
#[derive(serde::Serialize)]
pub struct Site {
    /// The folder it is in, from the project's root; empty for the root itself.
    dir: String,
    run: String,
}

/// Every web app in the project, the one to open first leading. A project
/// that is one itself is only that. A repository with no package.json of its
/// own (an app beside its landing page, a monorepo) has each folder a level
/// or two down that is one: a `dev` script first, then a `start`, then plain
/// files, and among those the order of `NESTED`, then the alphabet's.
fn sites(root: &Path) -> Vec<Site> {
    if let Some((_, run)) = site(root, root) {
        return vec![Site { dir: String::new(), run }];
    }
    let inside = |d: &Path| -> Vec<PathBuf> {
        let mut all: Vec<PathBuf> = std::fs::read_dir(d)
            .into_iter()
            .flatten()
            .flatten()
            .map(|e| e.path())
            .filter(|p| p.is_dir() && p.file_name().and_then(|n| n.to_str()).is_some_and(|n| !n.starts_with('.') && !SKIP.contains(&n)))
            .collect();
        all.sort();
        all
    };
    let mut dirs = inside(root);
    for group in ["apps", "packages"] {
        dirs.extend(inside(&root.join(group)));
    }
    let mut found: Vec<(u8, usize, Site)> = dirs
        .into_iter()
        .filter_map(|d| {
            let (rank, start) = site(&d, root)?;
            let dir = d.strip_prefix(root).ok()?.to_string_lossy().replace('\\', "/");
            let named = NESTED.iter().position(|n| *n == dir).unwrap_or(NESTED.len());
            Some((rank, named, Site { run: format!("cd \"{dir}\" && {start}"), dir }))
        })
        .collect();
    found.sort_by_key(|(rank, named, _)| (*rank, *named));
    found.into_iter().map(|(_, _, s)| s).collect()
}

const NESTED: [&str; 5] = ["app", "web", "frontend", "client", "site"];

/// Folders that hold what a build made or what was installed, never an app of their own.
const SKIP: [&str; 7] = ["node_modules", "dist", "build", "out", "coverage", "target", "vendor"];

/// The script `dir` is served by and the command that runs it there; `root`
/// is the repository, whose lockfile and dependencies a workspace shares.
fn served(dir: &Path, root: &Path) -> Option<(&'static str, String)> {
    let pkg = package(dir)?;
    let scripts = pkg.get("scripts")?;
    let has = |s: &str| scripts.get(s).and_then(|v| v.as_str()).is_some();
    let phone = depends_on(&pkg, "expo") || depends_on(&pkg, "react-native");
    let script = if has("dev") {
        "dev"
    } else if phone {
        if has("web") && depends_on(&pkg, "react-native-web") { "web" } else { return None }
    } else if has("start") {
        "start"
    } else {
        return None;
    };
    let locked = |d: &Path| ["pnpm-lock.yaml", "yarn.lock", "bun.lockb", "bun.lock", "package-lock.json"].iter().any(|f| d.join(f).is_file());
    let (install, run) = manager(if locked(dir) { dir } else { root });
    let start = if cfg!(windows) { format!("{run} {script}") } else { format!("BROWSER=none {run} {script}") };
    let installed = dir.join("node_modules").is_dir() || root.join("node_modules").is_dir();
    Some((script, if installed { start } else { format!("{install} && {start}") }))
}

fn has_child(dir: &Path, ext: &str) -> bool {
    std::fs::read_dir(dir)
        .map(|d| d.flatten().any(|e| e.path().extension().is_some_and(|x| x == ext)))
        .unwrap_or(false)
}

fn android_dir(root: &Path) -> Option<PathBuf> {
    [root.join("android"), root.to_path_buf()].into_iter().find(|d| {
        ["settings.gradle", "settings.gradle.kts"].iter().any(|f| d.join(f).is_file())
            && (d.join("app/src/main/AndroidManifest.xml").is_file() || d.join("app/build.gradle").is_file() || d.join("app/build.gradle.kts").is_file())
    })
}

fn ios_dir(root: &Path) -> Option<PathBuf> {
    [root.join("ios"), root.to_path_buf()]
        .into_iter()
        .find(|d| has_child(d, "xcworkspace") || has_child(d, "xcodeproj"))
}

#[derive(serde::Serialize)]
pub struct Project {
    /// Its web apps, the one to open first leading.
    web: Vec<Site>,
    android: bool,
    ios: bool,
}

#[tauri::command]
pub fn project_detect(root: String) -> Project {
    let root = PathBuf::from(root);
    // An Expo app can make either native project when asked, so it has both.
    let expo = kind(&root) == Kind::Expo;
    Project {
        web: sites(&root),
        android: expo || android_dir(&root).is_some(),
        ios: expo || ios_dir(&root).is_some(),
    }
}

/* ── where things go ──────────────────────────────────────────── */

fn home() -> PathBuf {
    crate::proc::home().unwrap_or_default()
}

/// A folder Windows names in the environment, `APPDATA` or `LOCALAPPDATA`.
fn windows_dir(var: &str, under_home: &str) -> PathBuf {
    std::env::var_os(var).map(PathBuf::from).unwrap_or_else(|| home().join(under_home))
}

/// The app's data folder, where Tauri keeps it.
fn data() -> PathBuf {
    let id = "dev.bluprint.app";
    if cfg!(target_os = "macos") {
        home().join("Library/Application Support").join(id)
    } else if cfg!(windows) {
        windows_dir("APPDATA", r"AppData\Roaming").join(id)
    } else {
        std::env::var_os("XDG_DATA_HOME").map(PathBuf::from).unwrap_or_else(|| home().join(".local/share")).join(id)
    }
}

/// A path as one word of the tab's shell: cmd on Windows, where a path cannot
/// hold a double quote; sh elsewhere.
fn q(s: &Path) -> String {
    if cfg!(windows) {
        format!("\"{}\"", s.to_string_lossy())
    } else {
        format!("'{}'", s.to_string_lossy().replace('\'', r"'\''"))
    }
}

fn ok(cmd: &mut Command) -> Option<String> {
    let out = cmd.stdin(Stdio::null()).stderr(Stdio::null()).output().ok()?;
    out.status.success().then(|| String::from_utf8_lossy(&out.stdout).into_owned())
}

/* ── Android ──────────────────────────────────────────────────── */

/// An SDK already on the machine (Android Studio's, or one set in the
/// environment), else the app's own.
fn sdk() -> PathBuf {
    let env = ["ANDROID_HOME", "ANDROID_SDK_ROOT"].iter().filter_map(std::env::var_os).map(PathBuf::from);
    let studio = if cfg!(target_os = "macos") {
        home().join("Library/Android/sdk")
    } else if cfg!(windows) {
        windows_dir("LOCALAPPDATA", r"AppData\Local").join(r"Android\Sdk")
    } else {
        home().join("Android/Sdk")
    };
    env.chain([studio])
        .find(|p| p.join("platform-tools").is_dir() || p.join("cmdline-tools").is_dir())
        .unwrap_or_else(|| data().join("android/sdk"))
}

fn java_home() -> Option<PathBuf> {
    let has = |p: &Path| p.join("bin").join(exe("java")).is_file();
    let own = data().join("android/jdk");
    if has(&own) {
        return Some(own);
    }
    if let Some(p) = std::env::var_os("JAVA_HOME").map(PathBuf::from).filter(|p| has(p)) {
        return Some(p);
    }
    let studio = if cfg!(windows) {
        windows_dir("ProgramFiles", "").join(r"Android\Android Studio\jbr")
    } else {
        PathBuf::from("/Applications/Android Studio.app/Contents/jbr/Contents/Home")
    };
    if has(&studio) {
        return Some(studio);
    }
    // Android's Gradle plugin runs on 17 or 21, not on whatever is newest.
    #[cfg(target_os = "macos")]
    for v in ["17", "21"] {
        if let Some(p) = ok(crate::proc::command("/usr/libexec/java_home").args(["-v", v])).map(|s| PathBuf::from(s.trim())) {
            if has(&p) {
                return Some(p);
            }
        }
    }
    None
}

/// A program's file name: `adb.exe` on Windows.
fn exe(name: &str) -> String {
    format!("{name}{}", std::env::consts::EXE_SUFFIX)
}

fn adb(sdk: &Path) -> PathBuf {
    sdk.join("platform-tools").join(exe("adb"))
}

fn emulator(sdk: &Path) -> PathBuf {
    sdk.join("emulator").join(exe("emulator"))
}

fn avds(sdk: &Path) -> Vec<String> {
    let Some(out) = ok(crate::proc::command(emulator(sdk)).arg("-list-avds").env("ANDROID_HOME", sdk)) else { return Vec::new() };
    let mut all: Vec<String> = out
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with("INFO") && !l.contains(' '))
        .map(String::from)
        .collect();
    // The one the setup made comes first. It keeps the name it was given before
    // the rename to Bluprint: a new one would make every machine build a second phone.
    all.sort_by_key(|a| a != "slop_phone");
    all
}

/// An emulator adb can already talk to.
fn emulator_serial(sdk: &Path) -> Option<String> {
    ok(crate::proc::command(adb(sdk)).arg("devices"))?
        .lines()
        .filter_map(|l| l.split_once('\t'))
        .find(|(s, state)| s.starts_with("emulator-") && state.trim() == "device")
        .map(|(s, _)| s.to_string())
}

fn booted(sdk: &Path, serial: &str) -> bool {
    ok(crate::proc::command(adb(sdk)).args(["-s", serial, "shell", "getprop", "sys.boot_completed"])).is_some_and(|s| s.trim() == "1")
}

const ANDROID_SETUP: &str = r#"#!/bin/sh
# Sets up the Android emulator for Bluprint, without Android Studio
# (src-tauri/src/devices.rs). Safe to run again: it skips what is there.
set -e
SDK=__SDK__
JDK=__JDK__
IMAGE="system-images;android-35;google_apis;__ABI__"
export ANDROID_HOME="$SDK" ANDROID_SDK_ROOT="$SDK"
echo "Setting up the Android emulator in $SDK"
echo "Only what is missing is downloaded; building an app fetches Gradle's own on top."
echo "Ctrl+C stops at any point; running this again picks up where it left off."
echo
mkdir -p "$SDK"
if ! "$JDK/bin/java" -version >/dev/null 2>&1; then
  echo "→ Java 17, for the Android tools and Gradle"
  tmp=$(mktemp -d)
  curl -fL --progress-bar "https://api.adoptium.net/v3/binary/latest/17/ga/__OS__/__ARCH__/jdk/hotspot/normal/eclipse" -o "$tmp/jdk.tar.gz"
  mkdir "$tmp/jdk" && tar -xzf "$tmp/jdk.tar.gz" -C "$tmp/jdk"
  java=$(find "$tmp/jdk" -type f -path '*/bin/java' | head -n 1)
  rm -rf "$JDK" && mkdir -p "$(dirname "$JDK")" && mv "$(dirname "$(dirname "$java")")" "$JDK"
  rm -rf "$tmp"
fi
export JAVA_HOME="$JDK"
TOOLS="$SDK/cmdline-tools/latest/bin"
# Only what is missing: an SDK that already has a virtual phone keeps its own.
PKGS=""
[ -x "$SDK/platform-tools/adb" ] || PKGS="$PKGS platform-tools"
[ -x "$SDK/emulator/emulator" ] || PKGS="$PKGS emulator"
PHONES=$("$SDK/emulator/emulator" -list-avds 2>/dev/null | grep -v '^INFO' || true)
[ -n "$PHONES" ] || PKGS="$PKGS platforms;android-35 build-tools;35.0.0 $IMAGE"
if [ -n "$PKGS" ] && [ ! -x "$TOOLS/sdkmanager" ]; then
  echo "→ Android command-line tools"
  tmp=$(mktemp -d)
  curl -fL --progress-bar "https://dl.google.com/android/repository/commandlinetools-__CLT__-11076708_latest.zip" -o "$tmp/tools.zip"
  unzip -q "$tmp/tools.zip" -d "$tmp"
  mkdir -p "$SDK/cmdline-tools" && rm -rf "$SDK/cmdline-tools/latest" && mv "$tmp/cmdline-tools" "$SDK/cmdline-tools/latest"
  rm -rf "$tmp"
fi
if [ -n "$PKGS" ]; then
  echo
  echo "→ Google's licenses for the Android SDK: read each, and answer y to accept"
  "$TOOLS/sdkmanager" --sdk_root="$SDK" --licenses
  echo
  echo "→ Installing:$PKGS"
  "$TOOLS/sdkmanager" --sdk_root="$SDK" --install $PKGS
fi
if [ -z "$PHONES" ]; then
  echo "→ A virtual Pixel 7"
  echo no | "$TOOLS/avdmanager" create avd -n slop_phone -k "$IMAGE" -d pixel_7
fi
echo
echo "Done. Back in the Android tab, press Start."
"#;

/* ── iOS ──────────────────────────────────────────────────────── */

fn simctl_ok() -> bool {
    cfg!(target_os = "macos") && ok(crate::proc::command("xcrun").args(["simctl", "help"])).is_some()
}

fn idb() -> Option<PathBuf> {
    let candidates = [home().join(".local/bin/idb"), "/opt/homebrew/bin/idb".into(), "/usr/local/bin/idb".into()];
    candidates.into_iter().find(|p| p.is_file()).or_else(|| {
        let shell = std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".into());
        let p = PathBuf::from(ok(crate::proc::command(shell).args(["-lc", "command -v idb"]))?.trim());
        p.is_file().then_some(p)
    })
}

const IOS_SETUP: &str = r#"#!/bin/sh
# Sets up the iOS Simulator for Bluprint (src-tauri/src/devices.rs).
# The simulator comes only with Xcode; it is installed once and never opened.
XCODE=$(mdfind "kMDItemCFBundleIdentifier == 'com.apple.dt.Xcode'" 2>/dev/null | head -n 1)
[ -n "$XCODE" ] || XCODE=/Applications/Xcode.app
if [ ! -d "$XCODE" ]; then
  echo "The iOS Simulator only comes with Xcode, which only Apple distributes."
  echo "Opening Xcode in the App Store: a large download, 10 GB or more."
  echo "Once it is installed, press Set up in the iOS tab again to finish."
  open "macappstore://apps.apple.com/app/id497799835"
  exit 0
fi
set -e
echo "Using $XCODE"
if [ "$(xcode-select -p)" != "$XCODE/Contents/Developer" ]; then
  echo "→ Pointing the command-line tools at it (asks for your password)"
  sudo xcode-select -s "$XCODE/Contents/Developer"
fi
if ! xcodebuild -license check >/dev/null 2>&1; then
  echo "→ Apple's Xcode license: read it, and type agree to accept"
  sudo xcodebuild -license
fi
xcodebuild -runFirstLaunch
if ! xcrun simctl list runtimes | grep -q '^iOS'; then
  echo "→ The iOS Simulator runtime, several GB"
  xcodebuild -downloadPlatform iOS
fi
echo
if ! command -v idb >/dev/null 2>&1; then
  echo "To tap and type in the simulator from the app, install Meta's idb as well:"
  echo "  brew tap facebook/fb && brew install idb-companion && pipx install fb-idb"
  echo "Without it the iOS tab still shows the simulator's screen."
  echo
fi
echo "Done. Back in the iOS tab, press Start."
"#;

#[derive(serde::Deserialize)]
struct SimList {
    devices: std::collections::HashMap<String, Vec<Sim>>,
}

#[derive(serde::Deserialize, Clone)]
struct Sim {
    udid: String,
    name: String,
    state: String,
    #[serde(rename = "isAvailable", default)]
    available: bool,
}

/// A booted iPhone, else the newest runtime's first iPhone.
fn pick_sim() -> Result<Sim, String> {
    let out = ok(crate::proc::command("xcrun").args(["simctl", "list", "devices", "available", "-j"])).ok_or("simctl could not list simulators.")?;
    let list: SimList = serde_json::from_str(&out).map_err(|e| e.to_string())?;
    let mut runtimes: Vec<(&String, &Vec<Sim>)> = list.devices.iter().filter(|(r, _)| r.contains("iOS")).collect();
    // `…SimRuntime.iOS-18-2`: newest last, by version.
    let version = |r: &str| -> Vec<u32> { r.rsplit("iOS-").next().unwrap_or("").split('-').filter_map(|n| n.parse().ok()).collect() };
    runtimes.sort_by_key(|(r, _)| version(r));
    let phones = runtimes.iter().rev().flat_map(|(_, d)| d.iter()).filter(|d| d.available && d.name.starts_with("iPhone"));
    let all: Vec<&Sim> = phones.collect();
    all.iter()
        .find(|d| d.state == "Booted")
        .or_else(|| all.first())
        .map(|d| (*d).clone())
        .ok_or_else(|| "No iPhone simulator is installed: run Set up again to fetch the iOS runtime.".into())
}

/* ── the running phones ───────────────────────────────────────── */

struct Running {
    /// adb serial or simulator udid.
    id: String,
    name: String,
    /// Started here, so ended here when the app quits.
    child: Option<Child>,
    ours: bool,
    /// The screen in pixels, from the last screenshot.
    size: Option<(u32, u32)>,
    /// iOS: pixels per point, for idb, which taps in points.
    density: Option<f64>,
}

#[derive(Default)]
struct Phones {
    android: Option<Running>,
    ios: Option<Running>,
}

fn phones() -> &'static Mutex<Phones> {
    static P: OnceLock<Mutex<Phones>> = OnceLock::new();
    P.get_or_init(Default::default)
}

fn slot<'a>(p: &'a mut Phones, platform: &str) -> Result<&'a mut Option<Running>, String> {
    match platform {
        "android" => Ok(&mut p.android),
        "ios" => Ok(&mut p.ios),
        _ => Err(format!("No such platform: {platform}")),
    }
}

/// Ends the phones the app started, when it quits.
pub fn stop_all() {
    let mut p = phones().lock().unwrap();
    if let Some(mut a) = p.android.take() {
        let _ = crate::proc::command(adb(&sdk())).args(["-s", &a.id, "emu", "kill"]).status();
        if let Some(c) = a.child.as_mut() {
            let _ = c.kill();
        }
    }
    if let Some(i) = p.ios.take().filter(|i| i.ours) {
        let _ = crate::proc::command("xcrun").args(["simctl", "shutdown", &i.id]).status();
    }
}

#[derive(serde::Serialize)]
pub struct Status {
    /// Everything it needs is installed.
    ready: bool,
    /// What is missing, said plainly.
    missing: Vec<String>,
    /// The phone running now, by name.
    running: Option<String>,
    /// Where setup puts things, and roughly how much.
    location: String,
    size: String,
    /// Setup can be run on this machine.
    can_setup: bool,
    /// Something worth knowing that is not a blocker.
    note: Option<String>,
}

fn status(platform: &str) -> Status {
    let running = {
        let p = phones().lock().unwrap();
        if platform == "android" { p.android.as_ref() } else { p.ios.as_ref() }.map(|r| r.name.clone())
    };
    if platform == "android" {
        let sdk = sdk();
        let mut missing = Vec::new();
        if java_home().is_none() {
            missing.push("Java 17".into());
        }
        if !adb(&sdk).is_file() || !emulator(&sdk).is_file() {
            missing.push("the Android emulator and platform tools".into());
        }
        if emulator(&sdk).is_file() && avds(&sdk).is_empty() {
            missing.push("a virtual phone".into());
        }
        let size = if missing.len() == 1 && java_home().is_none() { "about 200 MB" } else { "about 4–6 GB" };
        Status {
            ready: missing.is_empty(),
            missing,
            running,
            location: sdk.to_string_lossy().into_owned(),
            size: size.into(),
            can_setup: cfg!(unix),
            note: None,
        }
    } else {
        let macos = cfg!(target_os = "macos");
        let ready = simctl_ok();
        Status {
            ready,
            missing: if ready { Vec::new() } else { vec!["Xcode".into()] },
            running,
            location: "/Applications/Xcode.app".into(),
            size: "10 GB or more, from the App Store".into(),
            can_setup: macos,
            note: if !macos {
                Some("The iOS Simulator only runs on a Mac.".into())
            } else if ready && idb().is_none() {
                Some("Tapping and typing need Meta's idb: brew tap facebook/fb && brew install idb-companion && pipx install fb-idb".into())
            } else {
                None
            },
        }
    }
}

#[tauri::command]
pub async fn device_status(platform: String) -> Status {
    tauri::async_runtime::spawn_blocking(move || status(&platform)).await.unwrap_or_else(|e| Status {
        ready: false,
        missing: vec![e.to_string()],
        running: None,
        location: String::new(),
        size: String::new(),
        can_setup: false,
        note: None,
    })
}

/// Writes the setup script and says how to run it, in a terminal tab.
#[tauri::command]
pub fn device_setup(platform: String) -> Result<String, String> {
    let script = if platform == "android" {
        let arm = cfg!(target_arch = "aarch64");
        ANDROID_SETUP
            .replace("__SDK__", &q(&sdk()))
            .replace("__JDK__", &q(&java_home().unwrap_or_else(|| data().join("android/jdk"))))
            .replace("__ABI__", if arm { "arm64-v8a" } else { "x86_64" })
            .replace("__OS__", if cfg!(target_os = "macos") { "mac" } else { "linux" })
            .replace("__ARCH__", if arm { "aarch64" } else { "x64" })
            .replace("__CLT__", if cfg!(target_os = "macos") { "mac" } else { "linux" })
    } else {
        IOS_SETUP.to_string()
    };
    let path = data().join(format!("setup-{platform}.sh"));
    std::fs::create_dir_all(data()).map_err(|e| e.to_string())?;
    std::fs::write(&path, script).map_err(|e| e.to_string())?;
    Ok(format!("sh {}", q(&path)))
}

#[derive(serde::Serialize)]
pub struct Device {
    id: String,
    name: String,
}

fn start(platform: &str) -> Result<Device, String> {
    if let Some(r) = slot(&mut phones().lock().unwrap(), platform)?.as_ref() {
        return Ok(Device { id: r.id.clone(), name: r.name.clone() });
    }
    let running = if platform == "android" { start_android()? } else { start_ios()? };
    let device = Device { id: running.id.clone(), name: running.name.clone() };
    *slot(&mut phones().lock().unwrap(), platform)? = Some(running);
    Ok(device)
}

fn start_android() -> Result<Running, String> {
    let sdk = sdk();
    if let Some(serial) = emulator_serial(&sdk) {
        return Ok(Running { name: "Android emulator".into(), id: serial, child: None, ours: false, size: None, density: None });
    }
    let avd = avds(&sdk).into_iter().next().ok_or("There is no virtual phone yet: run Set up.")?;
    let log = data().join("android/emulator.log");
    // The SDK may be Android Studio's, so the app's own folder may not exist yet.
    let _ = std::fs::create_dir_all(data().join("android"));
    // No window of its own: the tab draws its screen. Some emulator builds
    // cannot hide their window, so the second try has none at all.
    for flags in [&["-qt-hide-window"][..], &["-no-window", "-gpu", "swiftshader_indirect"][..]] {
        let out = std::fs::File::create(&log).map_err(|e| e.to_string())?;
        let mut child = crate::proc::command(emulator(&sdk))
            .args(["-avd", &avd, "-no-audio", "-no-boot-anim"])
            .args(flags)
            .env("ANDROID_HOME", &sdk)
            .env("ANDROID_SDK_ROOT", &sdk)
            .stdin(Stdio::null())
            .stdout(out.try_clone().map_err(|e| e.to_string())?)
            .stderr(out)
            .spawn()
            .map_err(|e| e.to_string())?;
        let begun = Instant::now();
        loop {
            if child.try_wait().ok().flatten().is_some() {
                break;
            }
            if let Some(serial) = emulator_serial(&sdk).filter(|s| booted(&sdk, s)) {
                return Ok(Running { name: avd.replace('_', " "), id: serial, child: Some(child), ours: true, size: None, density: None });
            }
            if begun.elapsed() > Duration::from_secs(300) {
                let _ = child.kill();
                return Err(format!("The emulator did not finish starting in five minutes. Its log: {}", log.display()));
            }
            std::thread::sleep(Duration::from_secs(2));
        }
    }
    let log = std::fs::read_to_string(&log).unwrap_or_default();
    let lines: Vec<&str> = log.lines().collect();
    let tail = lines[lines.len().saturating_sub(6)..].join("\n");
    Err(format!("The emulator stopped while starting:\n{tail}"))
}

fn start_ios() -> Result<Running, String> {
    if !simctl_ok() {
        return Err("The iOS Simulator needs Xcode: run Set up.".into());
    }
    let sim = pick_sim()?;
    let ours = sim.state != "Booted";
    if ours {
        // Booted with simctl alone, the simulator has no window; Simulator.app is never opened.
        ok(crate::proc::command("xcrun").args(["simctl", "boot", &sim.udid])).ok_or("simctl could not boot the simulator.")?;
    }
    ok(crate::proc::command("xcrun").args(["simctl", "bootstatus", &sim.udid, "-b"])).ok_or("The simulator did not finish booting.")?;
    Ok(Running { id: sim.udid, name: sim.name, child: None, ours, size: None, density: None })
}

#[tauri::command]
pub async fn device_start(platform: String) -> Result<Device, String> {
    tauri::async_runtime::spawn_blocking(move || start(&platform)).await.map_err(|e| e.to_string())?
}

fn running_id(platform: &str) -> Result<String, String> {
    slot(&mut phones().lock().unwrap(), platform)?
        .as_ref()
        .map(|r| r.id.clone())
        .ok_or_else(|| format!("No {} is running in the app: the user starts one from its tab.", if platform == "ios" { "iOS Simulator" } else { "Android emulator" }))
}

/// The screen now, as a PNG.
fn frame(platform: &str) -> Result<Vec<u8>, String> {
    let id = running_id(platform)?;
    let png = if platform == "android" {
        let out = crate::proc::command(adb(&sdk())).args(["-s", &id, "exec-out", "screencap", "-p"]).stderr(Stdio::null()).output().map_err(|e| e.to_string())?;
        if !out.status.success() || out.stdout.len() < 24 {
            return Err("The emulator did not send its screen.".into());
        }
        out.stdout
    } else {
        let file = std::env::temp_dir().join(format!("bluprint-sim-{}.png", std::process::id()));
        ok(crate::proc::command("xcrun").args(["simctl", "io", &id, "screenshot", "--type=png"]).arg(&file)).ok_or("The simulator did not send its screen.")?;
        std::fs::read(&file).map_err(|e| e.to_string())?
    };
    if let Some(r) = slot(&mut phones().lock().unwrap(), platform)?.as_mut() {
        r.size = crate::mcp::png_size(&png);
    }
    Ok(png)
}

#[tauri::command]
pub async fn device_frame(platform: String) -> Result<tauri::ipc::Response, String> {
    let png = tauri::async_runtime::spawn_blocking(move || frame(&platform)).await.map_err(|e| e.to_string())??;
    Ok(tauri::ipc::Response::new(png))
}

/// A touch or a key. Points are fractions of the screen, 0 to 1, so the tab
/// need not know its pixels.
#[derive(serde::Deserialize, Default)]
pub struct Input {
    kind: String,
    #[serde(default)]
    x: f64,
    #[serde(default)]
    y: f64,
    #[serde(default)]
    x2: f64,
    #[serde(default)]
    y2: f64,
    #[serde(default)]
    ms: u32,
    #[serde(default)]
    text: String,
}

/// What `adb shell input text` needs: its own space, and the device shell's specials escaped.
fn adb_text(t: &str) -> String {
    t.chars()
        .map(|c| match c {
            ' ' => "%s".to_string(),
            '\\' | '\'' | '"' | '(' | ')' | '<' | '>' | '|' | ';' | '&' | '*' | '~' | '$' | '`' | '#' | '?' | '[' | ']' | '{' | '}' | '%' | '!' => format!("\\{c}"),
            c => c.to_string(),
        })
        .collect()
}

fn input(platform: &str, i: &Input) -> Result<(), String> {
    let id = running_id(platform)?;
    let (size, density) = {
        let p = phones().lock().unwrap();
        let r = if platform == "android" { p.android.as_ref() } else { p.ios.as_ref() };
        (r.and_then(|r| r.size), r.and_then(|r| r.density))
    };
    let (w, h) = match size {
        Some(s) => s,
        None => {
            frame(platform)?;
            return input(platform, i);
        }
    };
    let run = |cmd: &mut Command| -> Result<(), String> {
        let out = cmd.stdin(Stdio::null()).output().map_err(|e| e.to_string())?;
        if out.status.success() {
            Ok(())
        } else {
            Err(String::from_utf8_lossy(&out.stderr).trim().to_string())
        }
    };
    if platform == "android" {
        let px = |f: f64, of: u32| ((f.clamp(0.0, 1.0) * of as f64) as u32).to_string();
        let adb = adb(&sdk());
        let shell = |args: &[&str]| run(crate::proc::command(&adb).args(["-s", &id, "shell", "input"]).args(args));
        return match i.kind.as_str() {
            "tap" => shell(&["tap", &px(i.x, w), &px(i.y, h)]),
            "swipe" => shell(&["swipe", &px(i.x, w), &px(i.y, h), &px(i.x2, w), &px(i.y2, h), &i.ms.max(100).to_string()]),
            "text" => {
                // adb types ASCII alone, and fails partway, in Java, on anything else.
                let other: String = i.text.chars().filter(|c| !c.is_ascii()).collect();
                if !other.is_empty() {
                    return Err(format!("The Android emulator can only be typed into in plain ASCII, and nothing was typed: not {other}."));
                }
                for (n, line) in i.text.split('\n').enumerate() {
                    if n > 0 {
                        shell(&["keyevent", "66"])?;
                    }
                    if !line.is_empty() {
                        shell(&["text", &adb_text(line)])?;
                    }
                }
                Ok(())
            }
            "key" => {
                let code = match i.text.to_ascii_lowercase().as_str() {
                    "home" => "3",
                    "back" | "escape" => "4",
                    "enter" => "66",
                    "delete" | "backspace" => "67",
                    "recents" | "app_switch" => "187",
                    k => return Err(format!("No key called {k} on Android: home, back, enter, delete, recents.")),
                };
                shell(&["keyevent", code])
            }
            k => Err(format!("No input called {k}.")),
        };
    }
    let idb = idb().ok_or("Tapping in the iOS Simulator needs Meta's idb: brew tap facebook/fb && brew install idb-companion && pipx install fb-idb")?;
    let density = density.unwrap_or_else(|| ios_density(&idb, &id));
    let pt = |f: f64, of: u32| ((f.clamp(0.0, 1.0) * of as f64 / density) as u32).to_string();
    let ui = |args: &[&str]| run(crate::proc::command(&idb).arg("ui").args(args).args(["--udid", &id]));
    match i.kind.as_str() {
        "tap" => ui(&["tap", &pt(i.x, w), &pt(i.y, h)]),
        "swipe" => ui(&["swipe", &pt(i.x, w), &pt(i.y, h), &pt(i.x2, w), &pt(i.y2, h), "--duration", &format!("{:.2}", i.ms.max(100) as f64 / 1000.0)]),
        "text" => ui(&["text", &i.text]),
        "key" => match i.text.to_ascii_lowercase().as_str() {
            "home" => ui(&["button", "HOME"]),
            "enter" => ui(&["key", "40"]),
            "delete" | "backspace" => ui(&["key", "42"]),
            "back" | "escape" => Err("An iPhone has no back button: swipe from the left edge instead.".into()),
            k => Err(format!("No key called {k} on iOS: home, enter, delete.")),
        },
        k => Err(format!("No input called {k}.")),
    }
}

/// iOS: pixels per point, asked of idb once and kept.
fn ios_density(idb: &Path, id: &str) -> f64 {
    let d = ok(crate::proc::command(idb).args(["describe", "--udid", id, "--json"]))
        .and_then(|s| serde_json::from_str::<serde_json::Value>(&s).ok())
        .and_then(|v| v.get("screen_dimensions")?.get("density")?.as_f64())
        .unwrap_or(3.0);
    if let Some(r) = phones().lock().unwrap().ios.as_mut() {
        r.density = Some(d);
    }
    d
}

/* ── the user pointing Claude at something ───────────────────── */

/// The element under a point of the phone's screen, for Claude: what the
/// platform's own accessibility tree says of it, and where it is, as
/// fractions of the screen so the tab can outline it.
#[derive(serde::Serialize)]
pub struct Picked {
    key: String,
    title: String,
    text: String,
    x: f64,
    y: f64,
    w: f64,
    h: f64,
}

/// An attribute of one `<node …>` of a uiautomator dump, unescaped.
fn attr(node: &str, name: &str) -> String {
    let Some(at) = node.find(&format!(" {name}=\"")) else { return String::new() };
    let rest = &node[at + name.len() + 3..];
    rest[..rest.find('"').unwrap_or(0)].replace("&quot;", "\"").replace("&lt;", "<").replace("&gt;", ">").replace("&apos;", "'").replace("&amp;", "&")
}

/// `[0,63][1080,210]` as left, top, right, bottom.
fn bounds(b: &str) -> Option<(f64, f64, f64, f64)> {
    let n: Vec<f64> = b.split(|c: char| !c.is_ascii_digit()).filter(|s| !s.is_empty()).filter_map(|s| s.parse().ok()).collect();
    (n.len() == 4).then(|| (n[0], n[1], n[2], n[3]))
}

fn describe_point(platform: &str, x: f64, y: f64) -> Result<Picked, String> {
    let id = running_id(platform)?;
    let (w, h) = match slot(&mut phones().lock().unwrap(), platform)?.as_ref().and_then(|r| r.size) {
        Some(s) => s,
        None => {
            frame(platform)?;
            return describe_point(platform, x, y);
        }
    };
    let (w, h) = (w as f64, h as f64);
    if platform == "android" {
        let out = crate::proc::command(adb(&sdk()))
            .args(["-s", &id, "exec-out", "uiautomator", "dump", "/dev/tty"])
            .stderr(Stdio::null())
            .output()
            .map_err(|e| e.to_string())?;
        let xml = String::from_utf8_lossy(&out.stdout);
        let (px, py) = (x * w, y * h);
        // The smallest thing there that takes a tap, else the smallest thing there.
        let mut best: Option<(bool, f64, &str, (f64, f64, f64, f64))> = None;
        for node in xml.split("<node ").skip(1) {
            let node = &node[..node.find('>').unwrap_or(node.len())];
            let Some(b) = bounds(&attr(node, "bounds")) else { continue };
            if px < b.0 || px > b.2 || py < b.1 || py > b.3 {
                continue;
            }
            let tap = attr(node, "clickable") == "true";
            let area = (b.2 - b.0) * (b.3 - b.1);
            if best.as_ref().is_none_or(|(t, a, ..)| (tap && !t) || (tap == *t && area < *a)) {
                best = Some((tap, area, node, b));
            }
        }
        let (_, _, node, b) = best.ok_or("The emulator did not say what is on its screen: it may be busy, try again.")?;
        let class = attr(node, "class");
        let short = class.rsplit('.').next().unwrap_or(&class).to_string();
        let (text, desc, rid) = (attr(node, "text"), attr(node, "content-desc"), attr(node, "resource-id"));
        let name = [&text, &desc, &rid].into_iter().find(|s| !s.is_empty()).cloned().unwrap_or_default();
        let title = if name.is_empty() { short } else { format!("{short} \"{}\"", name.chars().take(60).collect::<String>()) };
        let lines = [
            format!("[Android element: {title}, in the app on the Android emulator"),
            format!("Class: {class}"),
            if rid.is_empty() { String::new() } else { format!("Id: {rid} (a React Native testID or nativeID shows here)") },
            if text.is_empty() { String::new() } else { format!("Text: {text}") },
            if desc.is_empty() { String::new() } else { format!("Description: {desc}") },
            format!("Package: {}", attr(node, "package")),
            format!("Bounds: {} on a {w}×{h} screen]", attr(node, "bounds")),
        ];
        return Ok(Picked {
            key: format!("android:{class}@{}", attr(node, "bounds")),
            title,
            text: lines.into_iter().filter(|l| !l.is_empty()).collect::<Vec<_>>().join("\n"),
            x: b.0 / w,
            y: b.1 / h,
            w: (b.2 - b.0) / w,
            h: (b.3 - b.1) / h,
        });
    }
    let idb = idb().ok_or("Reading the iOS Simulator's screen needs Meta's idb: brew tap facebook/fb && brew install idb-companion && pipx install fb-idb")?;
    let density = phones().lock().unwrap().ios.as_ref().and_then(|r| r.density).unwrap_or_else(|| ios_density(&idb, &id));
    let (pw, ph) = (w / density, h / density);
    let out = ok(crate::proc::command(&idb).args(["ui", "describe-point", "--udid", &id, "--json"]).arg(((x * pw) as u32).to_string()).arg(((y * ph) as u32).to_string()))
        .ok_or("The simulator did not say what is on its screen: try again.")?;
    let v: serde_json::Value = serde_json::from_str(&out).map_err(|e| e.to_string())?;
    let s = |k: &str| v.get(k).and_then(|x| x.as_str()).unwrap_or("").to_string();
    let (kind, label, value, uid) = (s("type"), s("AXLabel"), s("AXValue"), s("AXUniqueId"));
    let f = |k: &str| v.get("frame").and_then(|fr| fr.get(k)).and_then(|n| n.as_f64()).unwrap_or(0.0);
    let (fx, fy, fw, fh) = (f("x"), f("y"), f("width"), f("height"));
    let name = [&label, &value, &uid].into_iter().find(|s| !s.is_empty()).cloned().unwrap_or_default();
    let kind = if kind.is_empty() { "element".to_string() } else { kind };
    let title = if name.is_empty() { kind.clone() } else { format!("{kind} \"{}\"", name.chars().take(60).collect::<String>()) };
    let lines = [
        format!("[iOS element: {title}, in the app on the iOS Simulator"),
        if uid.is_empty() { String::new() } else { format!("Id: {uid} (accessibilityIdentifier, or a React Native testID)") },
        if label.is_empty() { String::new() } else { format!("Label: {label}") },
        if value.is_empty() { String::new() } else { format!("Value: {value}") },
        format!("Frame: {fx},{fy} {fw}×{fh} points on a {pw}×{ph} screen]"),
    ];
    Ok(Picked {
        key: format!("ios:{kind}@{fx},{fy},{fw},{fh}"),
        title,
        text: lines.into_iter().filter(|l| !l.is_empty()).collect::<Vec<_>>().join("\n"),
        x: fx / pw,
        y: fy / ph,
        w: fw / pw,
        h: fh / ph,
    })
}

#[tauri::command]
