//! The preview: the project's running web app, in a workspace tab
//! (components/preview/preview.tsx). The page is not framed from its dev server
//! directly. It is framed through a small proxy on its own port here, which
//! passes every request on and adds one script to each HTML page: the agent
//! (agent.js), which lets the app, and Claude through it (mcp.rs), read the
//! page and click, type and scroll in it. A page from another origin cannot be
//! reached into from the window around it any other way.
//!
//! The proxy is plain HTTP/1.1 over std, one request per connection: every
//! response says `Connection: close`, so nothing here has to follow a
//! keep-alive stream, and anything it does not change is copied through byte
//! for byte. A WebSocket (the dev server's hot reload) is tunnelled as it is.
//! The frame is served from `localhost` like the app itself, so the two are
//! the same site and the page keeps its cookies.

use std::collections::HashMap;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{Shutdown, TcpListener, TcpStream};
use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};
use std::sync::{Arc, Mutex};

const AGENT: &str = include_str!("agent.js");

/// Where a preview's requests go: the dev server's host and port.
#[derive(Clone)]
struct Upstream {
    host: String,
    port: u16,
}

impl Upstream {
    /// `http://localhost:5173/x`, `localhost:5173`, `0.0.0.0:3000`. A server
    /// that says it listens everywhere is reached on the loopback.
    fn parse(target: &str) -> Option<Self> {
        let rest = target.trim().trim_start_matches("http://");
        let authority = rest.split(['/', '?', '#']).next()?;
        let (host, port) = match authority.strip_prefix('[') {
            Some(v6) => {
                let (h, p) = v6.split_once("]:")?;
                (h.to_string(), p)
            }
            None => {
                let (h, p) = authority.rsplit_once(':')?;
                (h.to_string(), p)
            }
        };
        let host = if host == "0.0.0.0" || host == "::" { "127.0.0.1".into() } else { host };
        Some(Self { host, port: port.parse().ok()? })
    }

    fn authority(&self) -> String {
        if self.host.contains(':') {
            format!("[{}]:{}", self.host, self.port)
        } else {
            format!("{}:{}", self.host, self.port)
        }
    }

    fn origin(&self) -> String {
        format!("http://{}", self.authority())
    }
}

struct Proxy {
    port: u16,
    upstream: Arc<Mutex<Upstream>>,
    closed: Arc<AtomicBool>,
}

#[derive(Default)]
pub struct Previews {
    next: AtomicU32,
    open: Mutex<HashMap<u32, Proxy>>,
}

impl Previews {
    pub fn close_all(&self) {
        for (_, p) in self.open.lock().unwrap().drain() {
            stop(&p);
        }
    }
}

fn stop(p: &Proxy) {
    p.closed.store(true, Ordering::Relaxed);
    // The accept loop is blocked; one connection wakes it to see the flag.
    let _ = TcpStream::connect(("127.0.0.1", p.port));
}

#[derive(serde::Serialize)]
pub struct Opened {
    id: u32,
    /// The proxy's port: the frame loads `http://localhost:{port}`.
    port: u16,
}

/// A proxy in front of `target`, on a port of its own.
#[tauri::command]
pub fn preview_open(target: String, previews: tauri::State<Previews>) -> Result<Opened, String> {
    let upstream = Upstream::parse(&target).ok_or_else(|| format!("Not an address the preview can open: {target}"))?;
    let listener = TcpListener::bind(("127.0.0.1", 0)).map_err(|e| e.to_string())?;
    let port = listener.local_addr().map_err(|e| e.to_string())?.port();
    // `localhost` may be looked up as ::1 first; the same port there too, if it is free.
    let v6 = TcpListener::bind(("::1", port)).ok();
    let upstream = Arc::new(Mutex::new(upstream));
    let closed = Arc::new(AtomicBool::new(false));
    for l in std::iter::once(listener).chain(v6) {
        let (upstream, closed) = (upstream.clone(), closed.clone());
        std::thread::spawn(move || {
            for conn in l.incoming() {
                if closed.load(Ordering::Relaxed) {
                    break;
                }
                let Ok(conn) = conn else { continue };
                let to = upstream.lock().unwrap().clone();
                std::thread::spawn(move || {
                    let _ = serve(conn, &to, port);
                });
            }
        });
    }
    let id = previews.next.fetch_add(1, Ordering::Relaxed) + 1;
    previews.open.lock().unwrap().insert(id, Proxy { port, upstream, closed });
    Ok(Opened { id, port })
}

/// Points a preview at another server, keeping its port: the frame's origin,
/// and so the page's storage, stay the same when a dev server restarts elsewhere.
#[tauri::command]
pub fn preview_target(id: u32, target: String, previews: tauri::State<Previews>) -> Result<(), String> {
    let upstream = Upstream::parse(&target).ok_or_else(|| format!("Not an address the preview can open: {target}"))?;
    let open = previews.open.lock().unwrap();
    let p = open.get(&id).ok_or("no such preview")?;
    *p.upstream.lock().unwrap() = upstream;
    Ok(())
}

#[tauri::command]
pub fn preview_close(id: u32, previews: tauri::State<Previews>) {
    if let Some(p) = previews.open.lock().unwrap().remove(&id) {
        stop(&p);
    }
}

/// The page in the user's own browser, from the preview's toolbar.
#[tauri::command]
pub fn preview_external(url: String) -> Result<(), String> {
    if !(url.starts_with("http://") || url.starts_with("https://")) {
        return Err("Only a web address opens in the browser.".into());
    }
    let mut opener = if cfg!(windows) {
        let mut c = crate::proc::command("rundll32");
        c.arg("url.dll,FileProtocolHandler");
        c
    } else {
        crate::proc::command(if cfg!(target_os = "macos") { "open" } else { "xdg-open" })
    };
    opener.arg(&url).spawn().map(|_| ()).map_err(|e| e.to_string())
}

/* ── HTTP, as little of it as a proxy needs ───────────────────── */

pub(crate) struct Head {
    /// The request or status line.
    pub line: String,
    pub headers: Vec<(String, String)>,
}

impl Head {
    pub fn get(&self, name: &str) -> Option<&str> {
        self.headers.iter().find(|(k, _)| k.eq_ignore_ascii_case(name)).map(|(_, v)| v.as_str())
    }

    fn has_token(&self, name: &str, token: &str) -> bool {
        self.get(name).is_some_and(|v| v.split(',').any(|t| t.trim().eq_ignore_ascii_case(token)))
    }
}

/// A message's head: its first line and headers, up to the blank line.
pub(crate) fn read_head(r: &mut impl BufRead) -> std::io::Result<Head> {
    let mut line = String::new();
    if r.read_line(&mut line)? == 0 {
        return Err(std::io::ErrorKind::UnexpectedEof.into());
    }
    let mut headers = Vec::new();
    let mut size = line.len();
    loop {
        let mut h = String::new();
        if r.read_line(&mut h)? == 0 {
            return Err(std::io::ErrorKind::UnexpectedEof.into());
        }
        size += h.len();
        if size > 64 * 1024 {
            return Err(std::io::Error::other("head too large"));
        }
        let h = h.trim_end_matches(['\r', '\n']);
        if h.is_empty() {
            break;
        }
        if let Some((k, v)) = h.split_once(':') {
            headers.push((k.trim().to_string(), v.trim().to_string()));
        }
    }
    Ok(Head { line: line.trim_end().to_string(), headers })
}

/// A body as its head frames it: chunked, a length, or (`to_eof`) the rest of
/// the stream, which is how a response with neither ends.
pub(crate) fn read_body(r: &mut impl BufRead, head: &Head, to_eof: bool) -> std::io::Result<Vec<u8>> {
    let mut body = Vec::new();
    if head.has_token("transfer-encoding", "chunked") {
        loop {
            let mut size = String::new();
            r.read_line(&mut size)?;
            let n = usize::from_str_radix(size.trim().split(';').next().unwrap_or(""), 16)
                .map_err(|_| std::io::Error::other("bad chunk"))?;
            if n == 0 {
                // Trailers, then the blank line.
                loop {
                    let mut t = String::new();
                    if r.read_line(&mut t)? == 0 || t.trim().is_empty() {
                        break;
                    }
                }
                return Ok(body);
            }
            let at = body.len();
            body.resize(at + n, 0);
            r.read_exact(&mut body[at..])?;
            let mut crlf = [0u8; 2];
            r.read_exact(&mut crlf)?;
        }
    }
    if let Some(n) = head.get("content-length").and_then(|v| v.parse::<usize>().ok()) {
        body.resize(n, 0);
        r.read_exact(&mut body)?;
    } else if to_eof {
        r.read_to_end(&mut body)?;
    }
    Ok(body)
}

pub(crate) fn respond(w: &mut impl Write, status: &str, kind: &str, body: &[u8], extra: &[(&str, &str)]) -> std::io::Result<()> {
    let mut head = format!("HTTP/1.1 {status}\r\nContent-Type: {kind}\r\nContent-Length: {}\r\nConnection: close\r\n", body.len());
    for (k, v) in extra {
        head.push_str(&format!("{k}: {v}\r\n"));
    }
    head.push_str("\r\n");
    w.write_all(head.as_bytes())?;
    w.write_all(body)?;
    w.flush()
}

/// Headers that belong to one hop, not to the message: each side of the proxy
/// sets its own.
fn hop(name: &str) -> bool {
    ["connection", "keep-alive", "proxy-connection", "te", "trailer", "upgrade", "transfer-encoding"]
        .iter()
        .any(|h| name.eq_ignore_ascii_case(h))
}

fn write_head(w: &mut impl Write, line: &str, headers: &[(String, String)]) -> std::io::Result<()> {
    let mut out = format!("{line}\r\n");
    for (k, v) in headers {
        out.push_str(&format!("{k}: {v}\r\n"));
    }
    out.push_str("\r\n");
    w.write_all(out.as_bytes())
}

/// One request from the frame, passed to the dev server and its answer back.
fn serve(client: TcpStream, to: &Upstream, port: u16) -> std::io::Result<()> {
    let mut from = BufReader::new(client.try_clone()?);
    let mut client = client;
    let req = read_head(&mut from)?;
    let here = format!("http://localhost:{port}");
    let there = to.origin();
    let swap = |v: &str| match v.strip_prefix(&here) {
        Some(rest) => format!("{there}{rest}"),
        None => v.to_string(),
    };

    let Ok(mut server) = TcpStream::connect((to.host.as_str(), to.port)) else {
        return respond(&mut client, "502 Bad Gateway", "text/html; charset=utf-8", waiting(&there).as_bytes(), &[]);
    };

    // The dev server sees itself asked for, by its own origin: Vite checks the
    // host, Next.js the origin of its own dev requests.
    let upgrade = req.has_token("connection", "upgrade") && req.get("upgrade").is_some();
    let mut headers: Vec<(String, String)> = req
        .headers
        .iter()
        // The body's length is said again below, once it is read: a server
        // turns away a request that says it twice.
        .filter(|(k, _)| {
            !k.eq_ignore_ascii_case("host") && !k.eq_ignore_ascii_case("accept-encoding") && (upgrade || (!hop(k) && !k.eq_ignore_ascii_case("content-length")))
        })
        .map(|(k, v)| match k.to_ascii_lowercase().as_str() {
            "origin" | "referer" => (k.clone(), swap(v)),
            _ => (k.clone(), v.clone()),
        })
        .collect();
    headers.insert(0, ("Host".into(), to.authority()));

    if upgrade {
        // Hot reload: the handshake goes through as asked, then the two
        // streams are joined until either side hangs up.
        write_head(&mut server, &req.line, &headers)?;
        server.write_all(from.buffer())?;
        let mut up = server.try_clone()?;
        let mut down = client.try_clone()?;
        let mut inner = from.into_inner();
        let a = std::thread::spawn(move || {
            let _ = std::io::copy(&mut inner, &mut up);
            let _ = up.shutdown(Shutdown::Write);
        });
        let _ = std::io::copy(&mut server, &mut down);
        let _ = down.shutdown(Shutdown::Both);
        let _ = a.join();
        return Ok(());
    }

    let body = read_body(&mut from, &req, false)?;
    headers.push(("Accept-Encoding".into(), "identity".into()));
    headers.push(("Connection".into(), "close".into()));
    if !body.is_empty() || req.get("content-length").is_some() || req.has_token("transfer-encoding", "chunked") {
        headers.push(("Content-Length".into(), body.len().to_string()));
    }
    write_head(&mut server, &req.line, &headers)?;
    server.write_all(&body)?;
    server.flush()?;

    let mut back = BufReader::new(server);
    let res = read_head(&mut back)?;
    let ok = res.line.split_whitespace().nth(1) == Some("200");
    let html = res.get("content-type").is_some_and(|t| t.to_ascii_lowercase().starts_with("text/html"));
    let encoded = res.get("content-encoding").is_some_and(|e| !e.eq_ignore_ascii_case("identity"));
    let inject = req.line.starts_with("GET ") && ok && html && !encoded;

    // Framing is this proxy's when the page is rewritten; otherwise the
    // server's own, copied as it is. The frame may always be framed.
    let headers: Vec<(String, String)> = res
        .headers
        .iter()
        .filter(|(k, _)| {
            let k = k.to_ascii_lowercase();
            k != "x-frame-options"
                && k != "content-security-policy"
                && k != "connection"
                && k != "keep-alive"
                && !(inject && (k == "content-length" || k == "transfer-encoding"))
        })
        .map(|(k, v)| match k.to_ascii_lowercase().as_str() {
            "location" => (k.clone(), v.strip_prefix(&there).map_or_else(|| v.clone(), |rest| format!("{here}{rest}"))),
            _ => (k.clone(), v.clone()),
        })
        .chain(std::iter::once(("Connection".to_string(), "close".to_string())))
        .collect();

    if inject {
        let page = with_agent(&read_body(&mut back, &res, true)?);
        let mut headers = headers;
        headers.push(("Content-Length".into(), page.len().to_string()));
        headers.push(("Cache-Control".into(), "no-store".into()));
        write_head(&mut client, &res.line, &headers)?;
        client.write_all(&page)?;
    } else {
        write_head(&mut client, &res.line, &headers)?;
        client.write_all(back.buffer())?;
        let mut rest = back.into_inner();
        // Copied as it arrives, so a stream of events is not held back.
        let mut buf = [0u8; 16 * 1024];
        loop {
            match rest.read(&mut buf) {
                Ok(0) | Err(_) => break,
                Ok(n) => {
                    client.write_all(&buf[..n])?;
                    client.flush()?;
                }
            }
        }
    }
    client.flush()?;
    let _ = client.shutdown(Shutdown::Both);
    Ok(())
}

/// The agent, first thing in the page's head, so it hears the page's own
/// console from the start. It takes itself out of the page as it runs: React
/// hydrates a server-rendered head in order, and would read a script left
/// there as the page's own first one, and call the page mismatched.
fn with_agent(page: &[u8]) -> Vec<u8> {
    let script = format!("<script data-bluprint-agent>document.currentScript.remove();\n{AGENT}</script>");
    let lower = String::from_utf8_lossy(page).to_ascii_lowercase();
    let after_tag = |tag: &str| lower.find(tag).and_then(|at| lower[at..].find('>').map(|end| at + end + 1));
    let at = after_tag("<head").or_else(|| after_tag("<html")).or_else(|| after_tag("<!doctype")).unwrap_or(0);
    // `lower` is the same length as `page` only when the page was valid UTF-8;
    // anything else gets the script up front, where it still runs.
    let at = if lower.len() == page.len() { at } else { 0 };
    let mut out = Vec::with_capacity(page.len() + script.len());
    out.extend_from_slice(&page[..at]);
    out.extend_from_slice(script.as_bytes());
    out.extend_from_slice(&page[at..]);
    out
}

/// What the frame shows while the dev server is not answering: it tries again
/// every second, so a server that restarts comes back by itself. It tells the
/// tab each time, which goes back to the dev server if it was pointed at
/// another that has stopped.
fn waiting(origin: &str) -> String {
    format!(
        // A server that stopped never answers, so the page says where to see why.
        r#"<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="1"><title>Waiting</title><script>parent.postMessage({{__bluprint:true,type:"down"}},"*")</script><body style="font:13px/1.6 -apple-system,system-ui,sans-serif;color:#85858e;display:grid;place-items:center;height:100vh;margin:0;text-align:center"><div>Waiting for {origin}…<br>If the dev server stopped, <b style="font-weight:500">Server</b> above shows its terminal.</div></body>"#
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reads_the_addresses_dev_servers_print() {
        let u = Upstream::parse("http://localhost:5173/").unwrap();
        assert_eq!((u.host.as_str(), u.port), ("localhost", 5173));
        assert_eq!(Upstream::parse("0.0.0.0:3000").unwrap().authority(), "127.0.0.1:3000");
        assert_eq!(Upstream::parse("http://[::1]:8080/x?y").unwrap().authority(), "[::1]:8080");
        assert!(Upstream::parse("http://localhost/").is_none());
    }

    #[test]
    fn the_agent_goes_first_in_the_head() {
        let page = with_agent(b"<!DOCTYPE html><html lang=en><HEAD><title>x</title></head></html>");
        let page = String::from_utf8(page).unwrap();
        assert!(page.starts_with("<!DOCTYPE html><html lang=en><HEAD><script data-bluprint-agent>"));
        assert!(page.ends_with("<title>x</title></head></html>"));
        // A fragment with no head still gets it.
        assert!(String::from_utf8(with_agent(b"<p>hi")).unwrap().starts_with("<script"));
    }

    /// A dev server that answers once, as told.
    fn server(reply: &'static [u8]) -> (u16, std::thread::JoinHandle<String>) {
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let port = l.local_addr().unwrap().port();
        let t = std::thread::spawn(move || {
            let (s, _) = l.accept().unwrap();
            let mut r = BufReader::new(s.try_clone().unwrap());
            let head = read_head(&mut r).unwrap();
            let mut s = s;
            s.write_all(reply).unwrap();
            format!("{}\n{}", head.line, head.headers.iter().map(|(k, v)| format!("{k}: {v}")).collect::<Vec<_>>().join("\n"))
        });
        (port, t)
    }

    fn through(port: u16, request: &str) -> String {
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let me = l.local_addr().unwrap().port();
        let mut c = TcpStream::connect(("127.0.0.1", me)).unwrap();
        let (conn, _) = l.accept().unwrap();
        let to = Upstream { host: "127.0.0.1".into(), port };
        let h = std::thread::spawn(move || serve(conn, &to, me).unwrap());
        c.write_all(request.replace("{me}", &me.to_string()).as_bytes()).unwrap();
        let mut out = String::new();
        c.read_to_string(&mut out).unwrap();
        h.join().unwrap();
        out
    }

    #[test]
    fn a_page_gets_the_agent_and_can_be_framed() {
        let (port, seen) = server(
            b"HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nX-Frame-Options: DENY\r\nTransfer-Encoding: chunked\r\n\r\n6\r\n<head>\r\n7\r\n</head>\r\n0\r\n\r\n",
        );
        let out = through(port, "GET / HTTP/1.1\r\nHost: localhost:{me}\r\nOrigin: http://localhost:{me}\r\nAccept-Encoding: gzip\r\n\r\n");
        assert!(out.contains("<head><script data-bluprint-agent>"));
        assert!(out.ends_with("</head>"));
        assert!(!out.to_ascii_lowercase().contains("x-frame-options"));
        assert!(!out.to_ascii_lowercase().contains("chunked"));
        // The server was asked as itself, for plain bytes.
        let seen = seen.join().unwrap();
        assert!(seen.contains(&format!("Host: 127.0.0.1:{port}")));
        assert!(seen.contains(&format!("Origin: http://127.0.0.1:{port}")));
        assert!(seen.contains("Accept-Encoding: identity") && !seen.contains("gzip"));
    }

    #[test]
    fn everything_else_is_copied_through() {
        let (port, _) = server(b"HTTP/1.1 302 Found\r\nLocation: http://127.0.0.1:PORT/next\r\nContent-Length: 2\r\n\r\nok");
        let out = through(port, "GET /a.js HTTP/1.1\r\nHost: x\r\n\r\n");
        assert!(out.starts_with("HTTP/1.1 302 Found"));
        assert!(out.ends_with("\r\n\r\nok"));
        assert!(!out.contains("bluprint-agent"));
    }

    #[test]
    fn a_body_is_sent_on_with_its_length_said_once() {
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let port = l.local_addr().unwrap().port();
        let seen = std::thread::spawn(move || {
            let (s, _) = l.accept().unwrap();
            let mut r = BufReader::new(s.try_clone().unwrap());
            let head = read_head(&mut r).unwrap();
            let body = read_body(&mut r, &head, false).unwrap();
            let mut s = s;
            s.write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\n").unwrap();
            (head.headers.iter().filter(|(k, _)| k.eq_ignore_ascii_case("content-length")).count(), body)
        });
        through(port, "POST /api HTTP/1.1\r\nHost: x\r\nContent-Length: 4\r\n\r\nping");
        assert_eq!(seen.join().unwrap(), (1, b"ping".to_vec()));
    }

    #[test]
    fn a_server_that_is_down_is_waited_for() {
        let l = TcpListener::bind(("127.0.0.1", 0)).unwrap();
        let port = l.local_addr().unwrap().port();
        drop(l);
        let out = through(port, "GET / HTTP/1.1\r\nHost: x\r\n\r\n");
        assert!(out.starts_with("HTTP/1.1 502"));
        assert!(out.contains("http-equiv=\"refresh\""));
    }
}

app/src-tauri/src/proc.rs:
//! Programs the app runs behind the scenes: git, `where`, `adb`, Claude's
//! `--version`. On Windows a console program started from a windowed app
//! opens a console window of its own, which flashes on screen for every call;
//! `command` starts it without one.

use std::ffi::OsStr;
use std::process::Command;

#[cfg(windows)]
const CREATE_NO_WINDOW: u32 = 0x0800_0000;

pub fn command(program: impl AsRef<OsStr>) -> Command {
    #[allow(unused_mut)]
    let mut cmd = Command::new(program);
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(CREATE_NO_WINDOW);
    }
    cmd
}

/// The user's home folder: `HOME` where there is one, else Windows' own.
pub fn home() -> Option<std::path::PathBuf> {
    std::env::var_os("HOME").or_else(|| std::env::var_os("USERPROFILE")).map(Into::into)
}

/// Which `program`s on PATH Windows would run, by `where`, in its order.
#[cfg(windows)]
pub fn where_is(program: &str) -> Vec<std::path::PathBuf> {
    command("where")
        .arg(program)
        .stdin(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .output()
        .ok()
        .filter(|o| o.status.success())
        .map(|o| String::from_utf8_lossy(&o.stdout).lines().map(|l| l.trim().into()).collect())
        .unwrap_or_default()
}

app/src-tauri/src/pty.rs:
//! The workspace's tabs. Each one is a real pty running the user's shell in the
//! open bluprint's checkout; its output streams to the webview over a `Channel` as
//! raw bytes (xterm decodes UTF-8 itself, so a character split across two
//! reads is fine), and one final JSON `{"exit": code}` says it ended.
//!
//! A tab can start Claude Code in the shell first (claude.rs), and Claude can
//! be started again in any tab. Every tab owns a context queue for it,
//! removed with the tab.

use portable_pty::{native_pty_system, Child, CommandBuilder, MasterPty, PtySize};
use std::collections::HashMap;
use std::io::{Read, Write};
use std::path::PathBuf;
use std::sync::atomic::{AtomicU32, Ordering};
use std::sync::{Arc, Mutex};
use tauri::ipc::{Channel, InvokeResponseBody};

use crate::claude;

struct Pty {
    master: Box<dyn MasterPty + Send>,
    writer: Box<dyn Write + Send>,
    child: Box<dyn Child + Send + Sync>,
    /// Where picks wait for the next prompt to Claude in this tab.
    context: PathBuf,
}

impl Pty {
    fn end(mut self) {
        let _ = self.child.kill();
        claude::forget(&self.context);
    }
}

#[derive(Default)]
pub struct Ptys {
    next: AtomicU32,
    open: Arc<Mutex<HashMap<u32, Pty>>>,
}

impl Ptys {
    /// Every shell still running, ended. Called when the app exits, so
    /// closing the window never leaves a shell behind.
    pub fn kill_all(&self) {
        for (_, p) in self.open.lock().unwrap().drain() {
            p.end();
        }
    }
}

fn size(cols: u16, rows: u16) -> PtySize {
    PtySize { rows: rows.max(1), cols: cols.max(1), pixel_width: 0, pixel_height: 0 }
}

fn shell() -> String {
    #[cfg(windows)]
    return std::env::var("COMSPEC").unwrap_or_else(|_| "powershell.exe".into());
    #[cfg(not(windows))]
    return std::env::var("SHELL").unwrap_or_else(|_| "/bin/bash".into());
}

/// What the tab is called: the shell's own name, `zsh` for `/usr/bin/zsh`.
#[derive(serde::Serialize)]
pub struct Spawned {
    id: u32,
    shell: String,
}

/// `outline` is the open bluprint's sections, so Claude in this tab can name one it
/// was not handed (claude.rs's LIST).
#[tauri::command]
pub fn pty_spawn(
    cols: u16,
    rows: u16,
    on_data: Channel<InvokeResponseBody>,
    launch: Option<claude::Launch>,
    start_claude: bool,
    resume: Option<String>,
    cwd: Option<String>,
    outline: Option<String>,
    ptys: tauri::State<Ptys>,
) -> Result<Spawned, String> {
    let pair = native_pty_system().openpty(size(cols, rows)).map_err(|e| e.to_string())?;
    let id = ptys.next.fetch_add(1, Ordering::Relaxed) + 1;
    let context = claude::queue(id);
    let program = shell();
    let name = std::path::Path::new(&program)
        .file_stem()
        .map_or_else(|| program.clone(), |s| s.to_string_lossy().into_owned());
    let mut cmd = CommandBuilder::new(&program);
    // A Mac app opened from Finder gets a bare PATH; Terminal.app's shells are
    // login shells, and only those read /etc/zprofile (path_helper, which adds
    // /usr/local/bin) and ~/.zprofile (Homebrew's shellenv).
    let login = cfg!(target_os = "macos");
    if login {
        cmd.arg("-l");
    }
    // With Claude found, the launcher works in this tab; asked to, Claude runs
    // first and the user's ordinary interactive shell takes over when it exits.
    if let Some(launch) = &launch {
        claude::prepare(&mut cmd, launch, &context, outline.as_deref(), id).map_err(|e| e.to_string())?;
        if start_claude {
            if cfg!(unix) {
                cmd.args(["-c", if login { r#""$BLUPRINT_LAUNCHER"; exec "$SHELL" -l"# } else { r#""$BLUPRINT_LAUNCHER"; exec "$SHELL""# }]);
                cmd.env("SHELL", &program);
                if let Some(id) = &resume {
                    claude::resuming(&context, id).map_err(|e| e.to_string())?;
                }
            } else if name.eq_ignore_ascii_case("cmd") {
                cmd.args(["/k", "bluprint-claude"]);
            } else {
                cmd.args(["-NoExit", "-Command", "bluprint-claude"]);
            }
        }
    }
    // The checkout the page named, if it is really there; home otherwise.
    let dir = cwd.map(PathBuf::from).filter(|d| d.is_dir());
    if let Some(dir) = dir.or_else(crate::proc::home) {
        cmd.cwd(dir);
    }
    // An app started from a Claude Code session would hand down its markers,
    // and a Claude in a tab would then take itself for a child of that one.
    cmd.env_remove("CLAUDECODE");
    cmd.env_remove("CLAUDE_CODE_CHILD_SESSION");
    cmd.env("TERM", "xterm-256color");
    cmd.env("COLORTERM", "truecolor");
    let child = pair.slave.spawn_command(cmd).map_err(|e| e.to_string())?;
    // The slave end belongs to the shell now; holding it here would keep the
    // reader below from ever seeing EOF.
    drop(pair.slave);

    let mut reader = pair.master.try_clone_reader().map_err(|e| e.to_string())?;
    let writer = pair.master.take_writer().map_err(|e| e.to_string())?;
    ptys.open.lock().unwrap().insert(id, Pty { master: pair.master, writer, child, context });

    let open = ptys.open.clone();
    // Reads go to a second thread that sends them on. Claude Code redraws in
    // many small writes; whatever piles up while one send is crossing to the
    // webview goes in the next as one message, rather than a message per read.
    let (tx, rx) = std::sync::mpsc::channel::<Vec<u8>>();
    std::thread::spawn(move || {
        let mut buf = [0u8; 16 * 1024];
        loop {
            match reader.read(&mut buf) {
                Ok(0) | Err(_) => break,
                Ok(n) => {
                    if tx.send(buf[..n].to_vec()).is_err() {
                        break;
                    }
                }
            }
        }
    });
    std::thread::spawn(move || {
        while let Ok(mut chunk) = rx.recv() {
            while let Ok(more) = rx.try_recv() {
                chunk.extend_from_slice(&more);
            }
            if on_data.send(InvokeResponseBody::Raw(chunk)).is_err() {
                break;
            }
        }
        // Gone from the bluprint already if it was killed from the UI.
        let code = open
            .lock()
            .unwrap()
            .remove(&id)
            .and_then(|mut p| {
                claude::forget(&p.context);
                p.child.wait().ok()
            })
            .map_or(0, |s| s.exit_code());
        let _ = on_data.send(InvokeResponseBody::Json(format!(r#"{{"exit":{code}}}"#)));
    });
    Ok(Spawned { id, shell: name })
}

fn with<T>(ptys: &Ptys, id: u32, f: impl FnOnce(&mut Pty) -> std::io::Result<T>) -> Result<T, String> {
    let mut open = ptys.open.lock().unwrap();
    let p = open.get_mut(&id).ok_or("no such terminal")?;
    f(p).map_err(|e| e.to_string())
}

#[tauri::command]
pub fn pty_write(id: u32, data: String, ptys: tauri::State<Ptys>) -> Result<(), String> {
    with(&ptys, id, |p| {
        p.writer.write_all(data.as_bytes())?;
        p.writer.flush()
    })
}

#[tauri::command]
pub fn pty_resize(id: u32, cols: u16, rows: u16, ptys: tauri::State<Ptys>) -> Result<(), String> {
    with(&ptys, id, |p| p.master.resize(size(cols, rows)).map_err(std::io::Error::other))
}

#[tauri::command]
pub fn pty_kill(id: u32, ptys: tauri::State<Ptys>) -> Result<(), String> {
    if let Some(p) = ptys.open.lock().unwrap().remove(&id) {
        p.end();
    }
    Ok(())
}

/// Which of `names` the user's shell can run, found the way their own
/// terminal finds them: an interactive shell, so PATH set in its rc counts.
/// Only plain names are asked about, never anything the shell would parse.
fn which(names: Vec<String>) -> Vec<String> {
    let names: Vec<String> = names
        .into_iter()
        .filter(|n| !n.is_empty() && n.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_'))
        .collect();
    if names.is_empty() {
        return Vec::new();
    }
    runnable(names)
}

/// Windows' own lookup: PATH and PATHEXT, as cmd and PowerShell use them.
#[cfg(windows)]
fn runnable(names: Vec<String>) -> Vec<String> {
    names.into_iter().filter(|n| !crate::proc::where_is(n).is_empty()).collect()
}

#[cfg(not(windows))]
fn runnable(names: Vec<String>) -> Vec<String> {
    let script = names
        .iter()
        .map(|n| format!("command -v {n} >/dev/null 2>&1 && echo {n}"))
        .collect::<Vec<_>>()
        .join("; ");
    let out = std::process::Command::new(shell())
        .args(["-ic", &script])
        .stdin(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .output();
    let text = out.map(|o| String::from_utf8_lossy(&o.stdout).into_owned()).unwrap_or_default();
    // An rc may print its own lines too; only exact names count.
    names.into_iter().filter(|n| text.lines().any(|l| l.trim() == n)).collect()
}

/// The coding agents a tab can start besides Claude. Async so the shell's
/// start-up never blocks the window.
#[tauri::command]
pub async fn pty_which(names: Vec<String>) -> Vec<String> {
    which(names)
}

/// A tab's queue.
fn queue_of(ptys: &Ptys, id: u32) -> Result<PathBuf, String> {
    Ok(ptys.open.lock().unwrap().get(&id).ok_or("no such terminal")?.context.clone())
}

/// What is in front in a tab: Claude through the launcher (able to take
/// context), or some other program the shell started, or the shell itself,
/// waiting at its prompt.
#[derive(serde::Serialize)]
pub struct State {
    claude: bool,
    busy: bool,
    /// What Claude is doing: `working`, `waiting` for the user, or `done`.
    status: Option<String>,
    /// Claude finished a turn the bluprint should follow; reported once.
    turn: Option<claude::Turn>,
    /// The transcript of the turn Claude just finished, whatever it did, so the
    /// app can offer to keep the answer on the bluprint; reported once.
    ended: Option<String>,
    /// What Claude asked the app to show — a section, a diff — taken mid-turn
    /// so the user is looking at it while the answer streams; reported once.
    acts: Vec<claude::Act>,
    /// A plan Claude is waiting to have accepted; reported once.
    plan: Option<claude::Plan>,
    /// The plan was accepted; reported once.
    approved: bool,
    /// The accepted plan's steps as Claude has marked them; every poll.
    steps: Vec<claude::Step>,
    /// The conversation Claude is having, to resume it after a restart.
    session: Option<String>,
}

#[tauri::command]
pub fn pty_state(id: u32, ptys: tauri::State<Ptys>) -> Result<State, String> {
    let open = ptys.open.lock().unwrap();
    let p = open.get(&id).ok_or("no such terminal")?;
    // An interactive shell gives each command its own process group, and
    // hands it the terminal: someone else leading the foreground group means
    // a program is running.
    #[cfg(unix)]
    let busy = match (p.master.process_group_leader(), p.child.process_id()) {
        (Some(front), Some(shell)) => front as u32 != shell,
        _ => false,
    };
    #[cfg(not(unix))]
    let busy = false;
    Ok(State {
        claude: claude::running(&p.context),
        busy,
        status: claude::status_of(&p.context),
        turn: claude::take_turn(&p.context),
        ended: claude::take_ended(&p.context),
        acts: claude::take_acts(&p.context),
        plan: claude::take_plan(&p.context),
        approved: claude::take_approved(&p.context),
        steps: claude::steps_of(&p.context),
        session: claude::session_of(&p.context),
    })
}

/// Queues a section for the next prompt to Claude in this tab.
#[tauri::command]
pub fn context_add(id: u32, text: String, ptys: tauri::State<Ptys>) -> Result<(), String> {
    claude::append(&queue_of(&ptys, id)?, &text).map_err(|e| e.to_string())
}

/// Rewrites what is still waiting, after a pick is taken back. Empty clears it.
#[tauri::command]
pub fn context_set(id: u32, text: String, ptys: tauri::State<Ptys>) -> Result<(), String> {
    claude::replace(&queue_of(&ptys, id)?, &text).map_err(|e| e.to_string())
}

/// Where the user is on the bluprint, for every prompt to say (claude::place).
#[tauri::command]
pub fn context_where(id: u32, text: String, ptys: tauri::State<Ptys>) -> Result<(), String> {
    claude::place(&queue_of(&ptys, id)?, &text).map_err(|e| e.to_string())
}

/// True while something queued has not gone out with a prompt yet.
#[tauri::command]
pub fn context_pending(id: u32, ptys: tauri::State<Ptys>) -> Result<bool, String> {
    Ok(claude::pending(&queue_of(&ptys, id)?))
}

#[cfg(test)]
mod tests {
    #[cfg(unix)]
    use super::*;

    #[cfg(unix)]
    #[test]
    fn which_finds_only_plain_names_the_shell_can_run() {
        let asked = ["sh", "surely-not-a-program-xyz", "sh; echo oops", ""].map(String::from).to_vec();
        assert_eq!(which(asked), vec!["sh".to_string()]);
    }
}

