import type { Metadata } from "next";
import { IBM_Plex_Mono, IBM_Plex_Sans, Zilla_Slab } from "next/font/google";
import { LandingAgent } from "@/components/landing-agent";
import { LandingCover } from "@/components/landing-cover";
